    }

    fn unhandled_input(&mut self, event: Gd<InputEvent>) {
        if event.is_action_pressed("ui_accept")
            && self
                .base()
                .get_node_as::<ColorRect>("UserInterface/Retry")
                .is_visible()
        {
            self.base().get_tree().reload_current_scene();
        }
    }
}

#[godot_api]
impl MainScene {
    #[func]
    fn on_mob_timer_timeout(&mut self) {
        // Create mob instance.
        let mut mob_spawn_location = self
            .base()
            .get_node_as::<PathFollow3D>("SpawnPath/SpawnLocation");

        // Choose a random location on the SpawnPath.
        // Set random progress using proper rng.
        mob_spawn_location.set_progress_ratio(rand::random_range(0.0..=1.0));

        // Communicate the spawn location and the player's location to the mob.
        let player_position = self
            .base()
            .get_node_as::<player::Player>("Player")
            .get_position();

        let mut mob = self.mob_scene.instantiate_as::<mob::Mob>();

        mob.bind_mut()
            .initialize(mob_spawn_location.get_position(), player_position);

        // Spawn the mob by adding it to the Main scene.
        self.base_mut().add_child(&mob);

        // We connect the mob to the score label to update the score upon squashing a mob.
        mob.signals()
            .squashed()
            .connect_other(&*self.user_interface, UserInterface::on_mob_squashed);
    }

    #[func]
    pub fn on_player_hit(&mut self) {
        self.mob_timer.stop();

        self.base()
            .get_node_as::<ColorRect>("UserInterface/Retry")
            .show();
    }
}

#[derive(GodotClass)]
#[class(init, base=CharacterBody3D)]
pub struct Mob {
    // Minimum speed of the mob in meters per second.
    #[export]
    min_speed: f32,
    // Maximum speed of the mob in meters per second.
    #[export]
    max_speed: f32,
    base: Base<CharacterBody3D>,
}

#[godot_api]
impl ICharacterBody3D for Mob {
    fn physics_process(&mut self, _delta: f64) {
        self.base_mut().move_and_slide();
    }
}

#[godot_api]
impl Mob {
    #[func]
    pub fn initialize(&mut self, start_position: Vector3, player_position: Vector3) {
        self.base_mut()
            .look_at_from_position(start_position, player_position);

        self.base_mut()
            .rotate_y(rand::random_range(-PI / 4.0..PI / 4.0));

        let random_speed = rand::random_range(self.min_speed..self.max_speed);

        // We calculate a forward velocity first, which represents the speed.
        self.base_mut()
            .set_velocity(Vector3::FORWARD * random_speed);

        let rotation = self.base().get_rotation();
        let velocity = self.base().get_velocity();

        // We then rotate the vector based on the mob's Y rotation to move in the direction it's looking.
        self.base_mut()
            .set_velocity(velocity.rotated(Vector3::UP, rotation.y));

        let animation_speed = rand::random_range(1.0..6.0);

        self.base()
            .get_node_as::<AnimationPlayer>("AnimationPlayer")
            .set_speed_scale(animation_speed as f32)
    }

    // Emitted when the player jumped on the mob.
    #[signal]
    pub fn squashed();

    #[func]
    pub fn squash(&mut self) {
        self.signals().squashed().emit();

        self.base_mut().queue_free();
    }

    #[func]
    fn on_visible_on_screen_notifier_3d_screen_exited(&mut self) {
        self.base_mut().queue_free();
    }
}

