#[itest]
fn dictionary_iter_simultaneous() {
    let dictionary = vdict! {
        "foo" => 10,
        "bar" => true,
        "baz" => "foobar",
        "nil" => &Variant::nil(),
    };

    let map: HashMap<String, (Variant, Variant)> = dictionary
        .iter_shared()
        .typed::<String, Variant>()
        .zip(dictionary.iter_shared().typed::<String, Variant>())
        .map(|((mut k1, v1), (k2, v2))| {
            k1.push_str(k2.as_str());
            (k1, (v1, v2))
        })
        .collect();

    assert_eq!(map.len(), 4);

    let mut tens = 0;
    let mut trues = 0;
    let mut foobars = 0;
    let mut nils = 0;

    for v in map.iter().flat_map(|(_, (v1, v2))| [v1, v2]) {
        match bool::try_from_variant(v) {
            Ok(b) => {
                assert!(b);
                trues += 1;
            }
            _ => match i64::try_from_variant(v) {
                Ok(i) => {
                    assert_eq!(i, 10);
                    tens += 1;
                }
                _ => match String::try_from_variant(v) {
                    Ok(s) => {
                        assert_eq!(s.as_str(), "foobar");
                        foobars += 1;
                    }
                    _ => {
                        assert!(v.is_nil());
                        nils += 1;
                    }
                },
            },
        }
    }

    assert_eq!(tens, 2);
    assert_eq!(trues, 2);
    assert_eq!(foobars, 2);
    assert_eq!(nils, 2);
}

