trait Generator: PackedElement + Default + PartialEq + fmt::Debug {
    /// Deterministically generate a value depending on the index.
    ///
    /// Values may repeat, but the period must be at least 5.
    fn r#gen(index: usize) -> Self;

    /// Generate a `Vec` of `gen(0)`, `gen(1)`, ..., `gen(n-1)`.
    fn vec_n(n: usize) -> Vec<Self>
    where
        Self: Sized,
    {
        (0..n).map(|i| Self::r#gen(i)).collect()
    }

    /// Generate a `PackedArray` of `gen(0)`, `gen(1)`, ..., `gen(n-1)`.
    fn packed_n(n: usize) -> PackedArray<Self>
    where
        Self: Sized,
    {
        let iter = (0..n).map(|i| Self::r#gen(i));
        PackedArray::from_iter(iter)
    }
}

impl Generator for u8 {
    fn r#gen(index: usize) -> Self {
        index as u8
    }
}

impl Generator for i32 {
    fn r#gen(index: usize) -> Self {
        index as i32
    }
}

impl Generator for GString {
    fn r#gen(index: usize) -> Self {
        godot_str!("test_{}", index)
    }
}

impl Generator for Color {
    fn r#gen(index: usize) -> Self {
        let colors = [
            Color::RED,
            Color::GREEN,
            Color::BLUE,
            Color::YELLOW,
            Color::CYAN,
            Color::MAGENTA,
        ];
        colors[index % colors.len()]
    }
}

#[itest]
fn rid_equiv() {
    let invalid: Rid = Rid::Invalid;
    let valid: Rid = Rid::new((10 << 32) | 20);
    assert!(!InnerRid::from_outer(&invalid).is_valid());
    assert!(InnerRid::from_outer(&valid).is_valid());

    assert_eq!(InnerRid::from_outer(&invalid).get_id(), 0);
    assert_eq!(InnerRid::from_outer(&valid).get_id(), (10 << 32) | 20);
}

