#[itest]
fn enums_as_signal_args() {
    #[derive(Debug, Clone)]
    enum EventType {
        Ready,
    }

    impl GodotConvert for EventType {
        type Via = u8;

        fn godot_shape() -> godot::meta::shape::GodotShape {
            <u8 as GodotConvert>::godot_shape()
        }
    }

    impl ToGodot for EventType {
        type Pass = godot::meta::conv::ByValue;

        fn to_godot(&self) -> Self::Via {
            match self {
                EventType::Ready => 0,
            }
        }
    }

    impl FromGodot for EventType {
        fn try_from_godot(via: Self::Via) -> Result<Self, ConvertError> {
            match via {
                0 => Ok(Self::Ready),
                _ => Err(ConvertError::new("value out of range")),
            }
        }
    }

    #[derive(GodotClass)]
    #[class(base = RefCounted, init)]
    struct SignalObject {
        base: Base<RefCounted>,
    }

    #[godot_api]
    impl SignalObject {
        #[signal]
        fn game_event(ty: EventType);
    }

    let object = SignalObject::new_gd();
    let event = EventType::Ready;

    object.signals().game_event().emit(event);
}

