#[itest]
fn error_has_value_and_no_cause() {
    let node = Node::new_alloc();
    let errors: Vec<(ConvertError, &'static str)> = vec![
        (
            Variant::nil().try_to::<i64>().unwrap_err(),
            "`nil` -> `i64`",
        ),
        (
            VarArray::new()
                .to_variant()
                .try_to::<GString>()
                .unwrap_err(),
            "`VarArray` -> `GString`",
        ),
        (
            VarArray::new()
                .to_variant()
                .try_to::<Array<i64>>()
                .unwrap_err(),
            "`VarArray` -> `Array<i64>`",
        ),
        (
            Array::<Gd<Node>>::new()
                .to_variant()
                .try_to::<Array<Gd<Resource>>>()
                .unwrap_err(),
            "`Array<Gd<Node>>` -> `Array<Gd<Resource>>`",
        ),
        (
            node.clone().to_variant().try_to::<f32>().unwrap_err(),
            "`Gd<Node>` -> `f32`",
        ),
        (
            node.clone()
                .to_variant()
                .try_to::<Gd<Resource>>()
                .unwrap_err(),
            "`Gd<Node>` -> `Gd<Resource>`",
        ),
    ];

    for (err, err_str) in errors.into_iter() {
        assert!(
            err.value().is_some(),
            "{err_str} conversion has no value: {err:?}"
