#[itest]
fn rect2_inner_equivalence() {
    let rects = [
        Rect2::from_components(0.2, 0.3, 1.5, 0.9),
        Rect2::from_components(0.2, 0.3, 1.5, 1.9),
        Rect2::from_components(0.2, 0.3, 1.0, 1.9),
        Rect2::from_components(4.2, 4.3, 1.5, 1.9),
        Rect2::from_components(8.2, 8.3, 2.5, 2.9),
        Rect2::from_components(8.2, 8.3, 2.5, 3.9),
    ];
    let vectors = [
        Vector2::ZERO,
        Vector2::new(0.0, 10.0),
        Vector2::new(10.0, 0.0),
        Vector2::new(10.0, 10.0),
    ];
    let reals = reals![0.0, 1.0, 32.0];
    let grow_values = reals![-1.0, 0.0, 7.0];
    let sides = [Side::LEFT, Side::TOP, Side::RIGHT, Side::BOTTOM];

    for rect in rects {
        let inner_rect = InnerRect2::from_outer(&rect);

        assert_eq_approx!(rect.abs(), inner_rect.abs());
        assert_eq_approx!(rect.area(), real::from_f64(inner_rect.get_area()));
        assert_eq_approx!(rect.center(), inner_rect.get_center());
        assert_eq!(rect.has_area(), inner_rect.has_area());

        for other in rects {
            assert_eq!(rect.encloses(other), inner_rect.encloses(other));
            assert_eq!(rect.intersects(other), inner_rect.intersects(other, true));
            // Check intersection without considering borders
            assert_eq!(
                rect.intersects_exclude_borders(other),
                inner_rect.intersects(other, false),
            );
            assert_eq!(
                rect.intersect(other).unwrap_or_default(),
                inner_rect.intersection(other),
            );
            assert_eq_approx!(rect.merge(other), inner_rect.merge(other));
        }

        for vec in vectors {
            assert_eq_approx!(rect.expand(vec), inner_rect.expand(vec));
            assert_eq!(rect.contains_point(vec), inner_rect.has_point(vec));
        }

        for grow in grow_values {
            assert_eq_approx!(rect.grow(grow), inner_rect.grow(grow.as_f64()));
        }

        for left in grow_values {
            for top in grow_values {
                for right in grow_values {
                    for bottom in grow_values {
                        assert_eq_approx!(
                            rect.grow_individual(left, top, right, bottom),
                            inner_rect.grow_individual(
                                left.as_f64(),
                                top.as_f64(),
                                right.as_f64(),
                                bottom.as_f64(),
                            ),
                        );
                    }
                }
            }
        }

        for side in sides {
            for amount in reals {
                assert_eq_approx!(
                    rect.grow_side(side, amount),
                    inner_rect.grow_side(side as i64, amount.as_f64()),
                );
            }
        }
    }
}

#[itest]
fn rect2i_equiv_unary() {
    let test_rects = [
        Rect2i::from_components(0, 0, 1, 0),
        Rect2i::from_components(0, 0, 1, 1),
        Rect2i::from_components(0, 0, 10, 10),
        Rect2i::from_components(4, 4, 1, 1),
        Rect2i::from_components(8, 8, 2, 2),
        Rect2i::from_components(8, 8, 2, 3),
    ];
    let test_vectors = [
        Vector2i::ZERO,
        Vector2i::new(0, 10),
        Vector2i::new(10, 0),
        Vector2i::new(10, 10),
    ];
    let test_ints = [0, 1, 10, 32];
    let test_sides = [Side::LEFT, Side::TOP, Side::RIGHT, Side::BOTTOM];

    fn evaluate_mappings<T>(key: &str, a: T, b: T)
    where
        T: Eq + Debug,
    {
        assert_eq!(a, b, "{key}: outer != inner ({a:?} != {b:?})");
    }

    for a in test_rects {
        let inner_a = InnerRect2i::from_outer(&a);

        evaluate_mappings("abs", a.abs(), inner_a.abs());
        evaluate_mappings("area", a.area(), inner_a.get_area() as i32);
        evaluate_mappings("center", a.center(), inner_a.get_center());
        evaluate_mappings("has_area", a.has_area(), inner_a.has_area());

        for b in test_rects {
            evaluate_mappings("encloses", a.encloses(b), inner_a.encloses(b));
            evaluate_mappings("intersects", a.intersects(b), inner_a.intersects(b));
            evaluate_mappings(
                "intersect",
                a.intersect(b).unwrap_or_default(),
                inner_a.intersection(b),
            );
            evaluate_mappings("merge", a.merge(b), inner_a.merge(b));
        }

        for b in test_vectors {
            evaluate_mappings("expand", a.expand(b), inner_a.expand(b));
            evaluate_mappings("contains_point", a.contains_point(b), inner_a.has_point(b));
        }

        for b in test_ints {
            evaluate_mappings("grow", a.grow(b), inner_a.grow(b as i64));

            for c in test_ints {
                for d in test_ints {
                    for e in test_ints {
                        evaluate_mappings(
                            "grow_individual",
                            a.grow_individual(b, c, d, e),
                            inner_a.grow_individual(b as i64, c as i64, d as i64, e as i64),
                        );
                    }
                }
            }
        }

        for b in test_sides {
            for c in test_ints {
                evaluate_mappings(
                    "grow_side",
                    a.grow_side(b, c),
                    inner_a.grow_side(b.ord() as i64, c as i64),
                );
            }
        }
    }
}

