impl Baseless {
    /// Steals the `Base<T>` from a newly constructed object and stores it in the output parameter.
    fn smuggle_out(other_base: &mut Option<Base<Node2D>>) -> Gd<Self> {
        Gd::from_init_fn(|base| {
            *other_base = Some(base);
            Self {}
