#[cfg(before_api = "4.7")]
impl RefcBased {
    /// Used in `base_init_test.rs` to test that a base pointer can be extracted during initialization.
    pub fn split_simple() -> (Gd<Self>, Gd<RefCounted>) {
        let mut moved_out = None;

        let self_gd = Gd::from_init_fn(|base| {
            moved_out = Some(base.to_init_gd()); // Moved out.
            Self { base }
        });

        (self_gd, moved_out.unwrap())
    }

    /// Used in `base_init_test.rs`, testing extraction + several drops happening at different times.
    pub fn split_intermixed() -> (Gd<Self>, Gd<RefCounted>) {
        let mut moved_out = None;

        let self_gd = Gd::from_init_fn(|base| {
            let gd = base.to_init_gd(); // Explicitly dropped below.

            drop(base.to_init_gd()); // Immediately dropped.

            let _local_copy = base.to_init_gd(); // Dropped at end of scope.
            moved_out = Some(base.to_init_gd()); // Moved out.

            drop(gd);

            Self { base }
        });

        (self_gd, moved_out.unwrap())
    }
}

#[itest]
fn bitfield_ops_with() {
    let no_flags = DuplicateFlags::from_ord(0);

    assert_eq!(no_flags.with(GROUPS).ord(), 2);
    assert_eq!(GROUPS.with(no_flags).ord(), 2);
    assert_eq!(GROUPS.with(GROUPS).ord(), 2);

    assert_eq!(GROUPS.with(SIGNALS).ord(), 1 | 2);
    assert_eq!(GROUPS.with(GROUPS.with(SIGNALS)).ord(), 1 | 2);
    assert_eq!(GROUPS.with(GROUPS).with(SIGNALS).ord(), 1 | 2);

    assert_eq!(GROUPS.with(SIGNALS).with(SCRIPTS).ord(), 1 | 2 | 4);
}

#[itest]
fn bitfield_ops_without() {
    let no_flags = DuplicateFlags::from_ord(0);

    assert_eq!(no_flags.without(no_flags).ord(), 0);
    assert_eq!(GROUPS.without(GROUPS).ord(), 0);

    assert_eq!(GROUPS.without(SIGNALS).ord(), 2);
    assert_eq!(SIGNALS.with(GROUPS).without(SIGNALS).ord(), 2);
    assert_eq!(SIGNALS.with(GROUPS).without(SIGNALS.with(SCRIPTS)).ord(), 2);

    let all = GROUPS.with(SIGNALS).with(SCRIPTS);
    assert_eq!(all.without(SIGNALS).ord(), 2 | 4);
    assert_eq!(all.without(SIGNALS).without(SCRIPTS).ord(), 2);
}

trait ForwardTrait {
    fn forward(&mut self);
}

#[derive(GodotClass)]
#[class(init,base=Node2D)]
struct DeferredTestNode {
    base: Base<Node2D>,
}

#[godot_api]
impl DeferredTestNode {
    #[signal]
    fn test_completed(name: StringName);

    #[func]
    fn accept(&mut self) {
        self.base_mut().set_name(ACCEPTED_NAME);
    }

    fn accept_gd(mut this: Gd<Self>) {
        this.set_name(ACCEPTED_NAME);
    }

    fn accept_dyn_gd(mut this: DynGd<Object, dyn ForwardTrait>) {
        this.dyn_bind_mut().forward();
    }

    fn create_assertion_task(&mut self) -> TaskHandle {
        assert_ne!(
            self.base().get_name().to_string(),
            ACCEPTED_NAME,
            "accept evaluated synchronously"
        );

        let run_test: SignalFuture<(StringName,)> = self.signals().test_completed().to_future();

        godot::task::spawn(async move {
            let (name,) = run_test.await;

            assert_eq!(name.to_string(), ACCEPTED_NAME);
        })
    }
}

#[godot_api]
impl INode2D for DeferredTestNode {
    fn process(&mut self, _delta: f64) {
        let name = self.base().get_name();
        self.signals().test_completed().emit(&name);
        self.base_mut().queue_free();
    }

    fn ready(&mut self) {
        self.base_mut().set_name("verify");
    }
}

#[godot_dyn]
impl ForwardTrait for DeferredTestNode {
    fn forward(&mut self) {
        self.accept();
    }
}

#[itest(async)]
