    expect_panic(
        "Cannot acquire dyn_bind() guard while dyn_bind_mut() is held",
        || {
            let _ = b.dyn_bind();
        },
    );
    expect_panic(
        "Cannot acquire 2nd dyn_bind_mut() guard while dyn_bind_mut() is held",
        || {
            let _ = b.dyn_bind_mut();
        },
    );
    expect_panic("Cannot free object while dyn_bind_mut() is held", || {
        b.free();
    });

    drop(guard);
    a.free(); // now allowed.
}

