trait Health: 'static {
    fn get_hitpoints(&self) -> u8;

    fn deal_damage(&mut self, damage: u8);

    fn kill(&mut self) {
        self.deal_damage(self.get_hitpoints());
    }
}

#[derive(GodotClass)]
#[class(init)]
struct RefcHealth {
    hp: u8,
}

#[godot_api]
impl IRefCounted for RefcHealth {
