#[derive(GodotClass)]
#[class(init, base=Node)]
struct Duplicator {
    // #[export] would also make tests pass, but #[export(storage)] additionally hides the properties from the editor.
    // See https://docs.godotengine.org/en/stable/tutorials/scripting/gdscript/gdscript_exports.html#export-storage.
    #[export(storage)]
    int_export: i32,

    // Low-level #[var] should also work.
    #[var(usage_flags = [STORAGE])]
    int_var: i32,

    // Not copied because not marked as serialize ("storage").
    #[var]
    int_ignored: i32,

    #[export(storage)]
    optional_node: Option<Gd<Node>>,

    #[export(storage)]
    oneditor_node: OnEditor<Gd<Node>>,
}

#[itest]
fn test_duplicate_retains_properties() {
    let optional_node = Node::new_alloc();
    let oneditor_node = Node::new_alloc();

    // Set up original node.
    let mut original = Duplicator::new_alloc();
    {
        let mut original = original.bind_mut();
        original.int_export = 5;
        original.int_var = 7;
        original.int_ignored = 9; // Will not be copied.
        original.optional_node = Some(optional_node.clone());
        original.oneditor_node.init(oneditor_node.clone());
    }

    // Create duplicate and verify all properties are copied correctly.
    let duplicated: Gd<Duplicator> = original.duplicate_node();
    {
        let duplicated = duplicated.bind();
        assert_eq!(duplicated.int_export, 5);
        assert_eq!(duplicated.int_var, 7);
        assert_eq!(duplicated.int_ignored, 0); // Not copied.
        assert_eq!(duplicated.optional_node.as_ref().unwrap(), &optional_node);
        assert_eq!(&*duplicated.oneditor_node, &oneditor_node);
    }

    optional_node.free();
    oneditor_node.free();
    duplicated.free();
    original.free();
}

#[godot_api]
impl ReentrantClass {
    #[signal(__no_builder)]
    fn some_signal();

    #[func]
    fn first_calls(&mut self) {
        self.first_called_pre = true;
        self.base_mut().call("second", &[]);
        self.first_called_post = true;
    }

    #[func]
    fn first_signal(&mut self) {
        self.first_called_pre = true;
        self.base_mut().emit_signal("some_signal", &[]);
        self.first_called_post = true;
    }

    #[func]
    fn first_unbind(&mut self) -> i32 {
        self.first_called_pre = true;
        let ret = self.unbind(|base| base.call("second", &[]).to::<i32>());
        self.first_called_post = true;
        ret
    }

    #[func]
    fn second(&mut self) -> i32 {
        self.second_called = true;
        SECOND_RESULT
    }
}

fn check_reentrant(method: &str, setup: impl FnOnce(&mut Gd<ReentrantClass>)) -> Variant {
    let mut class = ReentrantClass::new_alloc();
    setup(&mut class);

    assert!(!class.bind().first_called_pre);
    assert!(!class.bind().first_called_post);
    assert!(!class.bind().second_called);

    let ret = class.call(method, &[]);

    assert!(class.bind().first_called_pre);
    assert!(class.bind().first_called_post);
    assert!(class.bind().second_called);

    class.free();
    ret
}

#[itest]
fn reentrant_call_succeeds() {
    check_reentrant("first_calls", |_| {});
}

#[itest]
fn reentrant_emit_succeeds() {
    check_reentrant("first_signal", |class| {
        let callable = class.callable("second");
        class.connect("some_signal", &callable);
    });
}

#[itest]
fn reentrant_closure_call_succeeds() {
    // Also verifies that the closure's return value is propagated through unbind().
    let ret = check_reentrant("first_unbind", |_| {});

    assert_eq!(ret.to::<i32>(), SECOND_RESULT);
}

