use godot::classes::{CharacterBody2D, ICharacterBody2D, Input};
use godot::global::Key;
use godot::prelude::*;

/// A platformer hero: arrow keys to run, Space (or Up) to jump.
#[derive(GodotClass)]
#[class(base = CharacterBody2D)]
pub struct Player {
    #[export]
    speed: f32,
    #[export]
    jump_velocity: f32,
    #[export]
    gravity: f32,
    base: Base<CharacterBody2D>,
}

#[godot_api]
impl ICharacterBody2D for Player {
    fn init(base: Base<CharacterBody2D>) -> Self {
        Self { speed: 280.0, jump_velocity: -480.0, gravity: 1100.0, base }
    }

    fn physics_process(&mut self, delta: f64) {
        let input = Input::singleton();
        let mut velocity = self.base().get_velocity();
        let on_floor = self.base().is_on_floor();

        if !on_floor {
            velocity.y += self.gravity * delta as f32;
        }
        let wants_jump = input.is_key_pressed(Key::SPACE) || input.is_action_pressed("ui_up");
        if wants_jump && on_floor {
            velocity.y = self.jump_velocity;
        }
        velocity.x = input.get_axis("ui_left", "ui_right") * self.speed;

        self.base_mut().set_velocity(velocity);
        self.base_mut().move_and_slide();
    }
}

use godot::classes::{CharacterBody2D, ICharacterBody2D};
use godot::global::randf_range;
use godot::prelude::*;

use crate::player::Player;

/// Wanders around, and chases the player when it gets close.
#[derive(GodotClass)]
#[class(base = CharacterBody2D)]
pub struct Enemy {
    #[export]
    speed: f32,
    #[export]
    chase_distance: f32,
    wander: Vector2,
    base: Base<CharacterBody2D>,
}

#[godot_api]
impl ICharacterBody2D for Enemy {
    fn init(base: Base<CharacterBody2D>) -> Self {
        Self { speed: 140.0, chase_distance: 300.0, wander: Vector2::ZERO, base }
    }

    fn ready(&mut self) {
        let angle = randf_range(0.0, std::f64::consts::TAU) as f32;
        self.wander = Vector2::from_angle(angle);
    }

    fn physics_process(&mut self, _delta: f64) {
        let my_position = self.base().get_global_position();
        let mut direction = self.wander;
        if let Some(player) = self.base().try_get_node_as::<Player>("../Player") {
            let player_position = player.get_global_position();
            if my_position.distance_to(player_position) < self.chase_distance {
                direction = (player_position - my_position).normalized();
            }
        }
        let velocity = direction * self.speed;
        self.base_mut().set_velocity(velocity);
        self.base_mut().move_and_slide();
        if self.base().is_on_wall() {
            self.wander = -self.wander;
        }
    }
}

use godot::classes::{Area2D, IArea2D, Node2D};
use godot::prelude::*;

use crate::enemy::Enemy;

/// Flies in a straight line, removes any enemy it hits, and disappears after a while.
#[derive(GodotClass)]
#[class(base = Area2D)]
pub struct Bullet {
    #[export]
    speed: f32,
    direction: Vector2,
    life: f64,
    base: Base<Area2D>,
}

#[godot_api]
impl IArea2D for Bullet {
    fn init(base: Base<Area2D>) -> Self {
        Self { speed: 700.0, direction: Vector2::RIGHT, life: 1.5, base }
    }

    fn ready(&mut self) {
        self.signals().body_entered().connect_self(Self::on_body_entered);
    }

    fn process(&mut self, delta: f64) {
        let step = self.direction * self.speed * delta as f32;
        let position = self.base().get_position();
        self.base_mut().set_position(position + step);
        self.life -= delta;
        if self.life <= 0.0 {
            self.base_mut().queue_free();
        }
    }
}

#[godot_api]
impl Bullet {
    pub fn launch(&mut self, direction: Vector2) {
        self.direction = direction;
    }

    fn on_body_entered(&mut self, body: Gd<Node2D>) {
        if let Ok(mut enemy) = body.try_cast::<Enemy>() {
            enemy.queue_free();
            self.base_mut().queue_free();
        }
    }
}

use godot::classes::{CharacterBody2D, ICharacterBody2D, Input, PackedScene};
use godot::prelude::*;

use crate::bullet::Bullet;

/// Moves with the arrow keys and shoots with Space in the direction it last moved.
#[derive(GodotClass)]
#[class(base = CharacterBody2D)]
pub struct Player {
    #[export]
    speed: f32,
    /// The bullet scene to fire (bullet.tscn).
    #[export]
    bullet_scene: OnEditor<Gd<PackedScene>>,
    facing: Vector2,
    base: Base<CharacterBody2D>,
}

#[godot_api]
impl ICharacterBody2D for Player {
    fn init(base: Base<CharacterBody2D>) -> Self {
        Self { speed: 300.0, bullet_scene: OnEditor::default(), facing: Vector2::RIGHT, base }
    }

    fn physics_process(&mut self, _delta: f64) {
        let input = Input::singleton();
        let direction = input.get_vector("ui_left", "ui_right", "ui_up", "ui_down");
        if direction != Vector2::ZERO {
            self.facing = direction.normalized();
        }
        let velocity = direction * self.speed;
        self.base_mut().set_velocity(velocity);
        self.base_mut().move_and_slide();

        if input.is_action_just_pressed("ui_accept") {
            self.shoot();
        }
    }
}

impl Player {
    fn shoot(&mut self) {
        let mut bullet = self.bullet_scene.instantiate_as::<Bullet>();
        let start = self.base().get_global_position() + self.facing * 40.0;
        bullet.set_global_position(start);
        bullet.bind_mut().launch(self.facing);
        if let Some(mut parent) = self.base().get_parent() {
            parent.add_child(&bullet);
        }
    }
}

use godot::classes::{CharacterBody2D, ICharacterBody2D};
use godot::global::randf_range;
use godot::prelude::*;

use crate::player::Player;

/// Wanders around, and chases the player when it gets close.
#[derive(GodotClass)]
#[class(base = CharacterBody2D)]
pub struct Enemy {
    #[export]
    speed: f32,
    #[export]
    chase_distance: f32,
    wander: Vector2,
    /// Seconds until it can hurt the player again.
    cooldown: f64,
    base: Base<CharacterBody2D>,
}

#[godot_api]
impl ICharacterBody2D for Enemy {
    fn init(base: Base<CharacterBody2D>) -> Self {
        Self { speed: 140.0, chase_distance: 300.0, wander: Vector2::ZERO, cooldown: 0.0, base }
    }

    fn ready(&mut self) {
        let angle = randf_range(0.0, std::f64::consts::TAU) as f32;
        self.wander = Vector2::from_angle(angle);
    }

    fn physics_process(&mut self, delta: f64) {
        self.cooldown -= delta;
        let my_position = self.base().get_global_position();
        let mut direction = self.wander;
        if let Some(player) = self.base().try_get_node_as::<Player>("../Player") {
            let player_position = player.get_global_position();
            if my_position.distance_to(player_position) < self.chase_distance {
                direction = (player_position - my_position).normalized();
            }
            // Touching the player hurts it, at most once per second.
            if my_position.distance_to(player_position) < 56.0 && self.cooldown <= 0.0 {
                self.cooldown = 1.0;
                let mut player = player;
                player.bind_mut().take_damage(1);
            }
        }
        let velocity = direction * self.speed;
        self.base_mut().set_velocity(velocity);
        self.base_mut().move_and_slide();
        if self.base().is_on_wall() {
            self.wander = -self.wander;
        }
    }
}

