        .map(|path| format!("#[controller(architecture = {path})]
"))
        .unwrap_or_default();
    if godot {
        format!(
            "use godot::classes::{{INode, Node}};
use godot::prelude::*;
use qframework_godot::prelude::*;

#[derive(GodotClass, IController)]
#[class(base = Node)]
{attribute}pub struct {type_name} {{
    arch: ArchRef,
    base: Base<Node>,
}}

#[godot_api]
impl INode for {type_name} {{
    fn init(base: Base<Node>) -> Self {{
        Self {{ arch: ArchRef::new(), base }}
    }}

    fn ready(&mut self) {{
        // Subscribe to events and properties here.
    }}
}}
"
        )
    } else {
        format!(
            "use qframework_core::prelude::*;

#[derive(Default, IController)]
{attribute}pub struct {type_name} {{
    arch: ArchRef,
}}
"
        )
    }
}

fn cleanup_for(node: &mut Node) -> Gd<QSubscriptionCleanup> {
    for child in node
        .get_children_ex()
        .include_internal(true)
        .done()
        .iter_shared()
    {
        if let Ok(cleanup) = child.try_cast::<QSubscriptionCleanup>() {
            return cleanup;
        }
    }

    let cleanup = QSubscriptionCleanup::new_alloc();
    node.add_child_ex(&cleanup)
        .internal(InternalMode::BACK)
        .done();
    cleanup
}

