#[godot_api]
impl Node2dRust {
    #[func]
    fn broadcast(&mut self) {
        let result = self.udp.bind(0);
        if result != godot::global::Error::OK {
            godot_error!("Failed to bind UDP sender: {:?}", result);
            return;
        }
        self.udp.set_broadcast_enabled(true);
        godot_print!("UDP Broadcaster ready");
    }
    fn get_broadcast_address(&self) -> String {
        match local_ip() {
            Ok(ip) => {
                let mut octets = match ip {
                    std::net::IpAddr::V4(v4) => v4.octets(),
                    _ => return "255.255.255.255".to_string(),
                };
                octets[3] = 255;
                format!("{}.{}.{}.{}", octets[0], octets[1], octets[2], octets[3])
            }
            Err(_) => "255.255.255.255".to_string(),
        }
    }

    #[func]
    fn broadcaster_timeout(&mut self, packet: PackedByteArray) {
        let addr = GString::from(&self.get_broadcast_address().to_string());

        let result = self.udp.set_dest_address(&addr, BROADCAST_PORT);
        if result != godot::global::Error::OK {
            godot_error!("Failed to set dest address: {:?}", result);
            return;
        }

        let result = self.udp.put_packet(&packet);
        if result != godot::global::Error::OK {
            godot_error!("Failed to send packet: {:?}", result);
            return;
        }

        godot_print!("Broadcasted to {}:{}", addr, BROADCAST_PORT);
    }
}

#[godot_api]
impl Inventory {
    #[signal]
    fn update();

    #[func]
    pub fn insert(&mut self, item: Gd<Collectibles>, index1: i32, index2: i32) {
        if index1 < 0 {
            // Try to stack first
            // stacking loop
            for mut slot in self.slots.iter_shared() {
                let slot_ref = slot.bind_mut();
                let mut existing = slot_ref.get_item();
                let mut existing_ref = existing.bind_mut();

                if existing_ref.is_stackable() && existing_ref.get_name() == item.bind().get_name()
                {
                    let amount = existing_ref.get_amount();
                    existing_ref.set_amount(amount + 1);
                    drop(existing_ref);
                    drop(slot_ref);
                    self.signals().update().emit();
                    return;
                }
            }

            // empty slot loop
            for mut slot in self.slots.iter_shared() {
                let mut slot_ref = slot.bind_mut();
                if slot_ref.get_item().bind().get_name().is_empty() {
                    slot_ref.set_item(item.clone());
                    drop(slot_ref);
                    self.signals().update().emit();
                    return;
                }
            }
            godot_error!("Inventory is full!");
        } else {
            // Swap two slots
            let a = self.slots.get(index1 as usize).unwrap().clone();
            let b = self.slots.get(index2 as usize).unwrap().clone();
            self.slots.set(index1 as usize, &b);
            self.slots.set(index2 as usize, &a);
            self.signals().update().emit();
            godot_print!("Swapped slots {} and {}", index1, index2);
        }
    }
}

