pub fn append_history(&mut self, history: &ToolHistory) {
    if history.latest_seq() <= self.cursor {
        return;
    }
    let Some(mut tree) = self.history_tree.clone() else {
        return;
    };
    // Timezone bias in minutes, read once per batch.
    let bias_minutes = Time::singleton()
        .get_time_zone_from_system()
        .get("bias")
        .and_then(|value| value.try_to::<i64>().ok())
        .unwrap_or(0);

    let fresh = history.records_since(self.cursor).count();
    if self.rows + fresh > HISTORY_CAPACITY {
        tree.clear();
        tree.create_item();
        self.rows = 0;
        self.cursor = 0;
    }

    let mut last_item = None;
    for record in history.records_since(self.cursor) {
        // With a root present, parentless create_item appends under it.
        let Some(mut item) = tree.create_item() else {
            continue;
        };
        item.set_text(0, &format_row_time(record.started_unix_ms, bias_minutes));
        item.set_text(1, &record.tool);
        match &record.error_code {
            None => item.set_text(2, "ok"),
            Some(code) => {
                item.set_text(2, code);
                item.set_custom_color(2, COLOR_ERROR_TEXT);
                item.set_tooltip_text(2, code);
            }
        }
        item.set_text(3, &format!("{} ms", record.duration.as_millis()));
        self.cursor = record.seq;
        self.rows += 1;
        last_item = Some(item);
    }

    if let Some(item) = last_item {
        tree.scroll_to_item(&item);
    }
}

fn format_row_time(unix_ms: u64, bias_minutes: i64) -> GString {
    let local_seconds = unix_ms as i64 / 1000 + bias_minutes * 60;
    Time::singleton().get_time_string_from_unix_time(local_seconds)
}

pub fn call_on(object: &mut Gd<Object>, method: &str, args: &[Variant]) -> Result<Variant, BridgeError> {
    object.try_call(method, args).map_err(call_error)
}

pub fn call_static(class: &str, method: &str, args: &[Variant]) -> Result<Variant, BridgeError> {
    let mut db = ClassDb::singleton();
    if !db.class_exists(class) {
        return Err(BridgeError::InvalidArgs(format!(
            "class '{class}' does not exist in this engine build"
        )));
    }
    match static_method_exists(&db, class, method) {
        StaticLookup::Static => {}
        StaticLookup::Instance => {
            return Err(BridgeError::InvalidArgs(format!(
                "'{class}.{method}' is an instance method, not a static one; obtain an instance first (for example with a static factory such as open) and call it on the object handle that came back"
            )))
        }
        StaticLookup::Absent => {
            return Err(BridgeError::CallFailed(format!("class '{class}' has no method '{method}'")))
        }
    }
    db.try_class_call_static(class, method, args).map_err(call_error)
}

fn require_class(args: &Value) -> Result<String, BridgeError> {
    let class = require_str(args, "class")?;
    if !ClassDb::singleton().class_exists(class.as_str()) {
        return Err(BridgeError::InvalidArgs(format!("class '{class}' does not exist in this engine build")));
    }
    Ok(class)
}

fn list_classes(args: &Value) -> Result<Value, BridgeError> {
    let filter = optional_str(args, "filter").map(|f| f.to_lowercase());
    let limit = optional_u64(args, "limit").unwrap_or(DEFAULT_CLASS_LIMIT);
    let offset = optional_u64(args, "offset").unwrap_or(0);

    let mut names: Vec<String> = ClassDb::singleton()
        .get_class_list()
        .to_vec()
        .into_iter()
        .map(|s| s.to_string())
        .filter(|name| filter.as_deref().is_none_or(|f| name.to_lowercase().contains(f)))
        .collect();
    names.sort_unstable();
    Ok(paginate(names.into_iter().map(Value::String).collect(), limit, offset))
}

fn class_info(args: &Value) -> Result<Value, BridgeError> {
    let class = require_class(args)?;
    let no_inheritance = optional_bool(args, "no_inheritance").unwrap_or(false);
    let db = ClassDb::singleton();
    let parent = db.get_parent_class(class.as_str()).to_string();
    Ok(json!({
        "class": class,
        "parent": if parent.is_empty() { Value::Null } else { json!(parent) },
        "instantiable": db.can_instantiate(class.as_str()),
        "counts": {
            "properties": db.class_get_property_list_ex(class.as_str()).no_inheritance(no_inheritance).done().len(),
            "methods": db.class_get_method_list_ex(class.as_str()).no_inheritance(no_inheritance).done().len(),
            "signals": db.class_get_signal_list_ex(class.as_str()).no_inheritance(no_inheritance).done().len(),
            "constants": db.class_get_integer_constant_list_ex(class.as_str()).no_inheritance(no_inheritance).done().len(),
            "enums": db.class_get_enum_list_ex(class.as_str()).no_inheritance(no_inheritance).done().len(),
        },
    }))
}

fn list_properties(class: &str, no_inheritance: bool) -> Vec<Value> {
    ClassDb::singleton()
        .class_get_property_list_ex(class)
        .no_inheritance(no_inheritance)
        .done()
        .iter_shared()
        .filter(|dict| dict_i64(dict, "usage") & GROUP_MARKER_USAGE == 0)
        .map(|dict| {
            let mut entry = json!({ "name": dict_str(&dict, "name"), "type": type_label(&dict) });
            add_hint(&mut entry, &dict, "");
            entry
        })
        .collect()
}

fn list_methods(class: &str, no_inheritance: bool) -> Vec<Value> {
    ClassDb::singleton()
        .class_get_method_list_ex(class)
        .no_inheritance(no_inheritance)
        .done()
        .iter_shared()
        .map(|dict| {
            let ret = dict.get(&GString::from("return")).and_then(|v| v.try_to::<VarDictionary>().ok());
            let return_type = ret
                .as_ref()
                .map(|ret| {
                    if dict_i64(ret, "type") == 0 && dict_str(ret, "class_name").is_empty() {
                        "void".to_string()
                    } else {
                        type_label(ret)
                    }
                })
                .unwrap_or_else(|| "void".to_string());
            // `static` is what makes the `class:<Class>` target scheme
            // discoverable: it is the one bit that says whether a method can be
            // called without an instance.
            let mut entry = json!({
                "name": dict_str(&dict, "name"),
                "return_type": return_type,
                "args": args_json(&dict),
                "static": crate::handlers::call::method_dict_is_static(&dict),
            });
            // A return carries a hint the same way an argument does, which is
            // how `get_children` reports Node as its element class.
            if let Some(ret) = ret.as_ref() {
                add_hint(&mut entry, ret, "return_");
            }
            entry
        })
        .collect()
}

fn list_constants(class: &str, no_inheritance: bool) -> Vec<Value> {
    let db = ClassDb::singleton();
    db.class_get_integer_constant_list_ex(class)
        .no_inheritance(no_inheritance)
        .done()
        .to_vec()
        .into_iter()
        .map(|name| {
            let value = db.class_get_integer_constant(class, name.to_string().as_str());
            json!({ "name": name.to_string(), "value": value })
        })
        .collect()
}

fn list_enums(class: &str, no_inheritance: bool) -> Vec<Value> {
    let db = ClassDb::singleton();
    db.class_get_enum_list_ex(class)
        .no_inheritance(no_inheritance)
        .done()
        .to_vec()
        .into_iter()
        .map(|enum_name| {
            let enum_string = enum_name.to_string();
            let constants: Vec<Value> = db
                .class_get_enum_constants_ex(class, enum_string.as_str())
                .no_inheritance(no_inheritance)
                .done()
                .to_vec()
                .into_iter()
                .map(|constant| {
                    let value = db.class_get_integer_constant(class, constant.to_string().as_str());
                    json!({ "name": constant.to_string(), "value": value })
                })
                .collect();
            json!({ "name": enum_string, "constants": constants })
        })
        .collect()
}

fn parents(args: &Value) -> Result<Value, BridgeError> {
    let class = require_class(args)?;
    let db = ClassDb::singleton();
    let mut chain = Vec::new();
    let mut current = class.clone();
    loop {
        let parent = db.get_parent_class(current.as_str()).to_string();
        if parent.is_empty() {
            break;
        }
        chain.push(json!(parent));
        current = parent;
    }
    Ok(json!({ "class": class, "parents": chain }))
}

fn exists(args: &Value) -> Result<Value, BridgeError> {
    let class = require_str(args, "class")?;
    let db = ClassDb::singleton();
    let class_exists = db.class_exists(class.as_str());
    let mut result = json!({ "class": class, "class_exists": class_exists });
    if let Some(method) = optional_str(args, "method") {
        result["method_exists"] = json!(class_exists && db.class_has_method(class.as_str(), method.as_str()));
    }
    if let Some(signal) = optional_str(args, "signal") {
        result["signal_exists"] = json!(class_exists && db.class_has_signal(class.as_str(), signal.as_str()));
    }
    if let Some(property) = optional_str(args, "property") {
        let found = class_exists
            && db
                .class_get_property_list(class.as_str())
                .iter_shared()
                .any(|dict| dict_str(&dict, "name") == property);
        result["property_exists"] = json!(found);
    }
    Ok(result)
}

pub fn add(args: &Value, ctx: &FrameContext) -> HandlerOutcome {
    let prepared: Result<(String, Vec<u8>), BridgeError> = (|| {
        let path = require_str(args, "path")?;
        validate_project_path(&path)?;
        let data_base64 = require_str(args, "data_base64")?;
        let bytes = base64::decode(&data_base64)?;
        Ok((path, bytes))
    })();
    let (path, bytes) = match prepared {
        Ok(v) => v,
        Err(e) => return HandlerOutcome::Done(Err(e)),
    };

    let write_result: Result<(), BridgeError> = {
        let global_path = ProjectSettings::singleton().globalize_path(path.as_str()).to_string();
        std::fs::write(&global_path, &bytes)
            .map_err(|e| BridgeError::ResourceError(format!("failed to write '{path}': {e}")))
    };
    if let Err(e) = write_result {
        return HandlerOutcome::Done(Err(e));
    }

    let bytes_written = bytes.len();
    trigger_rescan(false, ctx, move || {
        let resource_type = ResourceLoader::singleton().load(path.as_str()).map(|r| r.get_class().to_string());
        let uid = resource_uid_text(&path);
        Ok(json!({ "path": path, "bytes_written": bytes_written, "type": resource_type, "uid": uid }))
    })
}

fn load_import_config(path: &str) -> Result<(Gd<ConfigFile>, String), BridgeError> {
    let import_path = import_path_of(path);
    let mut config = ConfigFile::new_gd();
    let err = config.load(import_path.as_str());
    if err != GdError::OK {
        if !FileAccess::file_exists(path) {
            return Err(BridgeError::ResourceError(format!("no file at '{path}'")));
        }
        return Err(BridgeError::ResourceError(format!(
            "could not read import settings at '{import_path}' ({err:?}); only assets the import pipeline brings in (textures, audio, fonts, models) have a sidecar, unlike scenes, scripts, and .tres resources"
        )));
    }
    Ok((config, import_path))
}

fn section_value(config: &Gd<ConfigFile>, section: &str, key: &str) -> Value {
    if config.has_section_key(section, key) {
        variant_to_json(&config.get_value(section, key))
    } else {
        Value::Null
    }
}

fn section_keys(config: &Gd<ConfigFile>, section: &str) -> Vec<String> {
    if !config.has_section(section) {
        return Vec::new();
    }
    config.get_section_keys(section).as_slice().iter().map(|key| key.to_string()).collect()
}

fn list() -> Result<Value, BridgeError> {
    let settings = ProjectSettings::singleton();
    let mut autoloads = Vec::new();
    for entry in settings.get_property_list().iter_shared() {
        let key = entry.get(&GString::from("name")).map(|v| v.to_string()).unwrap_or_default();
        let Some(name) = key.strip_prefix(PREFIX) else { continue };
        let stored = settings.get_setting(key.as_str()).to_string();
        let (enabled, path) = parse_value(&stored);
        autoloads.push(json!({ "name": name, "path": path, "enabled": enabled }));
    }
    Ok(json!({ "autoloads": autoloads }))
}

fn add(args: &Value) -> Result<Value, BridgeError> {
    let name = require_str(args, "name")?;
    let path = require_str(args, "path")?;
    let enabled = optional_bool(args, "enabled").unwrap_or(true);
    validate_name(&name)?;
    validate_project_path(&path)?;

    let key = format!("{PREFIX}{name}");
    let mut settings = ProjectSettings::singleton();
    if settings.has_setting(key.as_str()) {
        return Err(BridgeError::AlreadyExists(format!(
            "autoload '{name}' already exists; remove it first to replace it"
        )));
    }
    let stored = if enabled { format!("*{path}") } else { path.clone() };
    settings.set_setting(key.as_str(), &GString::from(stored.as_str()).to_variant());
    let save_err = settings.save();
    if save_err != GdError::OK {
        return Err(BridgeError::ResourceError(format!("failed to save project settings: {save_err:?}")));
    }
    Ok(json!({ "name": name, "path": path, "enabled": enabled }))
}

fn remove(args: &Value) -> Result<Value, BridgeError> {
    let name = require_str(args, "name")?;
    let key = format!("{PREFIX}{name}");
    let mut settings = ProjectSettings::singleton();
    if !settings.has_setting(key.as_str()) {
        return Err(BridgeError::InvalidArgs(format!("no autoload named '{name}'")));
    }
    // Setting NIL erases the entry from project.godot.
    settings.set_setting(key.as_str(), &Variant::nil());
    let save_err = settings.save();
    if save_err != GdError::OK {
        return Err(BridgeError::ResourceError(format!("failed to save project settings: {save_err:?}")));
    }
    Ok(json!({ "name": name, "removed": true }))
}

fn select_inner(args: &Value) -> Result<Value, BridgeError> {
    let op = require_str(args, "op")?;
    let editor = EditorInterface::singleton();
    let mut selection = editor
        .get_selection()
        .ok_or_else(|| BridgeError::Internal("no EditorSelection available".into()))?;

    match op.as_str() {
        "clear" => selection.clear(),
        "set" | "add" => {
            if op == "set" {
                selection.clear();
            }
            let paths = args.get("node_paths").and_then(Value::as_array).ok_or_else(|| {
                BridgeError::InvalidArgs("'node_paths' must be an array of node paths for op set/add".into())
            })?;
            for entry in paths {
                let path = entry
                    .as_str()
                    .ok_or_else(|| BridgeError::InvalidArgs("each node_paths entry must be a string".into()))?;
                let node = resolve_editor_node(path)?;
                selection.add_node(&node);
            }
        }
        other => {
            return Err(BridgeError::InvalidArgs(format!("unknown select op '{other}'; expected set, add, or clear")));
        }
    }

    let root = edited_scene_root()?;
    let selected: Vec<String> = selection
        .get_selected_nodes()
        .iter_shared()
        .map(|node| relative_path(&root, &node))
        .collect();
    Ok(json!({ "selection": selected }))
}

fn open_script_inner(args: &Value) -> Result<Value, BridgeError> {
    let path = require_str(args, "path")?;
    validate_project_path(&path)?;
    let resource = ResourceLoader::singleton()
        .load(&path)
        .ok_or_else(|| BridgeError::ResourceError(format!("could not load '{path}'")))?;
    let script: Gd<Script> = resource
        .try_cast()
        .map_err(|_| BridgeError::InvalidArgs(format!("'{path}' is not a script")))?;

    let line = optional_u64(args, "line").map(|line| line as i32).unwrap_or(-1);
    let column = optional_u64(args, "column").map(|column| column as i32).unwrap_or(0);

    let mut editor = EditorInterface::singleton();
    editor.set_main_screen_editor("Script");
    editor.edit_script_ex(&script).line(line).column(column).done();
    Ok(json!({ "opened": path, "line": line, "column": column }))
}

fn inspect_inner(args: &Value) -> Result<Value, BridgeError> {
    let node_path = optional_str(args, "node_path");
    let resource_path = optional_str(args, "resource_path");
    let mut editor = EditorInterface::singleton();
    match (node_path, resource_path) {
        (Some(node_path), None) => {
            let node = resolve_editor_node(&node_path)?;
            editor.edit_node(&node);
            editor.inspect_object(&node);
            Ok(json!({ "inspecting": "node", "node_path": node_path }))
        }
        (None, Some(resource_path)) => {
            validate_project_path(&resource_path)?;
            let resource = ResourceLoader::singleton()
                .load(&resource_path)
                .ok_or_else(|| BridgeError::ResourceError(format!("could not load '{resource_path}'")))?;
            editor.edit_resource(&resource);
            Ok(json!({ "inspecting": "resource", "resource_path": resource_path }))
        }
        _ => Err(BridgeError::InvalidArgs("provide exactly one of 'node_path' or 'resource_path'".into())),
    }
}

fn set_main_screen_inner(args: &Value) -> Result<Value, BridgeError> {
    let name = require_str(args, "name")?;
    if !MAIN_SCREENS.contains(&name.as_str()) {
        return Err(BridgeError::InvalidArgs(format!(
            "unknown main screen '{name}'; expected one of {MAIN_SCREENS:?}"
        )));
    }
    EditorInterface::singleton().set_main_screen_editor(&name);
    Ok(json!({ "main_screen": name }))
}

pub fn screenshot(args: &Value, ctx: &FrameContext) -> HandlerOutcome {
    if is_headless_display() {
        return HandlerOutcome::Done(Err(BridgeError::NotAvailableHeadless(
            "editor screenshots are unavailable under a headless display server".into(),
        )));
    }
    let max_dimension = optional_u64(args, "max_dimension").map(|value| value as i32);
    let format = ImageFormat::from_arg(optional_str(args, "format").as_deref().unwrap_or("png"));

    let sink = ConduitFrameSink::new_gd();
    let callable = Callable::from_object_method(&sink, "on_frame");
    RenderingServer::singleton().connect("frame_post_draw", &callable);

    HandlerOutcome::Pending(Box::new(EditorScreenshotPending {
        sink,
        callable,
        max_dimension,
        format,
        deadline_frame: ctx.frame_index.saturating_add(SCREENSHOT_DEADLINE_FRAMES),
    }))
}

impl EditorScreenshotPending {
    fn disconnect(&mut self) {
        let mut server = RenderingServer::singleton();
        if server.is_connected("frame_post_draw", &self.callable) {
            server.disconnect("frame_post_draw", &self.callable);
        }
    }

    fn capture(&self) -> Result<Value, BridgeError> {
        let base = EditorInterface::singleton()
            .get_base_control()
            .ok_or_else(|| BridgeError::Internal("editor has no base control".into()))?;
        let viewport = base
            .get_viewport()
            .ok_or_else(|| BridgeError::Internal("editor base control has no viewport".into()))?;
        encode_viewport(&viewport, self.max_dimension, self.format)
    }
}

pub fn get_state(_args: &Value, _ctx: &FrameContext) -> HandlerOutcome {
    HandlerOutcome::Done({
        let editor = EditorInterface::singleton();
        let open_paths = editor.get_open_scenes();
        let open_roots = editor.get_open_scene_roots();
        let edited_root = editor.get_edited_scene_root();

        let mut scenes = Vec::new();
        let mut current_scene = None;
        for (index, root) in open_roots.iter_shared().enumerate() {
            let path = open_paths.get(index).map(|p| p.to_string()).unwrap_or_default();
            let dirty = editor.is_object_edited(&root);
            if edited_root.as_ref() == Some(&root) {
                current_scene = Some(path.clone());
            }
            scenes.push(json!({ "path": path, "dirty": dirty }));
        }

        let selection: Vec<String> = editor
            .get_selection()
            .map(|selection| {
                selection
                    .get_selected_nodes()
                    .iter_shared()
                    .map(|node| node.get_name().to_string())
                    .collect()
            })
            .unwrap_or_default();

        Ok(json!({
            "open_scenes": scenes,
            "current_scene": current_scene,
            "selection": selection,
            "main_screen": current_main_screen(&editor),
            "playing": editor.is_playing_scene(),
            "breakpoints": crate::debugger::breakpoints_json(),
            "debug": { "sessions": crate::debugger::sessions_json() },
        }))
    })
}

fn current_main_screen(editor: &Gd<EditorInterface>) -> Value {
    let Some(container) = editor.get_editor_main_screen() else {
        return Value::Null;
    };
    for child in container.get_children().iter_shared() {
        let visible = child.clone().try_cast::<Control>().map(|c| c.is_visible()).unwrap_or(false);
        if visible {
            // Since 4.3 a main-screen editor may be nested in a WindowWrapper
            // (for the make-floating feature), so map from the first known editor
            // class in the visible subtree rather than the wrapper's own class.
            let class = main_screen_class(&child).unwrap_or_else(|| child.get_class().to_string());
            let name = match class.as_str() {
                "CanvasItemEditor" => "2D",
                "Node3DEditor" => "3D",
                "ScriptEditor" => "Script",
                "GameView" => "Game",
                "EditorAssetLibrary" => "AssetLib",
                other => other,
            };
            return Value::String(name.to_string());
        }
    }
    Value::Null
}

fn main_screen_class(node: &Gd<Node>) -> Option<String> {
    const KNOWN: [&str; 5] = ["CanvasItemEditor", "Node3DEditor", "ScriptEditor", "GameView", "EditorAssetLibrary"];
    let class = node.get_class().to_string();
    if KNOWN.contains(&class.as_str()) {
        return Some(class);
    }
    for child in node.get_children().iter_shared() {
        if let Some(found) = main_screen_class(&child) {
            return Some(found);
        }
    }
    None
}

fn globalize(path: &str) -> String {
    ProjectSettings::singleton().globalize_path(path).to_string()
}

pub fn export_presets(args: &Value, _ctx: &FrameContext) -> HandlerOutcome {
    HandlerOutcome::Done((|| {
        let limit = optional_u64(args, "limit").unwrap_or(50);
        let offset = optional_u64(args, "offset").unwrap_or(0);

        let mut config = ConfigFile::new_gd();
        if config.load("res://export_presets.cfg") != godot::global::Error::OK {
            // A project with no presets has no file; that is an empty list.
            return Ok(paginate(Vec::new(), limit, offset));
        }

        let sections: Vec<String> = config.get_sections().as_slice().iter().map(|s| s.to_string()).collect();
        let mut items = Vec::new();
        for section in preset_sections(&sections) {
            let read = |key: &str| -> Value {
                if config.has_section_key(section.as_str(), key) {
                    variant_to_json(&config.get_value(section.as_str(), key))
                } else {
                    Value::Null
                }
            };
            items.push(json!({
                "name": read("name"),
                "platform": read("platform"),
                "runnable": read("runnable"),
                "export_path": read("export_path"),
                "include_filter": read("include_filter"),
                "exclude_filter": read("exclude_filter"),
            }));
        }
        Ok(paginate(items, limit, offset))
    })())
}

pub fn export_project(args: &Value, _ctx: &FrameContext) -> HandlerOutcome {
    let prepared: Result<(String, String, String, &'static str), BridgeError> = (|| {
        let preset = require_str(args, "preset")?;
        let output_path = require_str(args, "output_path")?;
        validate_project_path(&output_path)?;
        let mode = require_str(args, "mode")?;
        let flag = export_flag(&mode)?;
        Ok((preset, output_path, mode, flag))
    })();

    let (preset, output_path, mode, flag) = match prepared {
        Ok(v) => v,
        Err(e) => return HandlerOutcome::Done(Err(e)),
    };

    let godot_bin = Os::singleton().get_executable_path().to_string();
    let project_settings = ProjectSettings::singleton();
    let project_path = project_settings.globalize_path("res://").to_string();
    let output_abs = project_settings.globalize_path(output_path.as_str()).to_string();

    // Godot does not create missing intermediate directories for the export
    // output path itself (confirmed empirically: it fails with "Can't open
    // file for writing"), so a first-use output path like `res://export/...`
    // would otherwise always fail.
    if let Err(e) = Path::new(&output_abs).parent().map_or(Ok(()), std::fs::create_dir_all) {
        return HandlerOutcome::Done(Err(BridgeError::Internal(format!(
            "failed to create output directory for '{output_abs}': {e}"
        ))));
    }

    let scratch_path = unique_export_log_path();
    let output_file = match std::fs::File::create(&scratch_path) {
        Ok(f) => f,
        Err(e) => {
            return HandlerOutcome::Done(Err(BridgeError::Internal(format!(
                "failed to create scratch file for export logging: {e}"
            ))))
        }
    };
    let stderr_file = match output_file.try_clone() {
        Ok(f) => f,
        Err(e) => {
            let _ = std::fs::remove_file(&scratch_path);
            return HandlerOutcome::Done(Err(BridgeError::Internal(format!(
                "failed to prepare scratch file for export logging: {e}"
            ))));
        }
    };

    // Export CLI invocations run with editor context: is_editor_hint() is
    // true even without --editor (confirmed empirically -- the bridge's own
    // "Conduit (editor): listening on ..." log line appears during a bare
    // --export-pack run), and the editor personality's should_bind() returns
    // true unconditionally, ignoring CONDUIT_ENABLE. Stripping CONDUIT_SOCK
    // and CONDUIT_ENABLE alone does NOT stop this subprocess from binding a
    // second editor listener; it only makes it fall back to the same
    // default socket path (derived from CONDUIT_RUNTIME_DIR plus the project
    // path) that a live editor launched without an explicit CONDUIT_SOCK
    // also uses -- confirmed to unlink and steal that live editor's socket
    // out from under it. The fix is not preventing the bind (it cannot be
    // prevented from here) but isolating it: give the subprocess its own
    // private, throwaway CONDUIT_RUNTIME_DIR so whatever it binds can never
    // collide with the parent's.
    let runtime_dir = unique_export_runtime_dir();
    if let Err(e) = std::fs::create_dir_all(&runtime_dir) {
        let _ = std::fs::remove_file(&scratch_path);
        return HandlerOutcome::Done(Err(BridgeError::Internal(format!(
            "failed to create isolated runtime directory for export subprocess: {e}"
        ))));
    }

    let mut command = Command::new(&godot_bin);
    command
        .args(["--headless", "--path", project_path.as_str(), flag, preset.as_str(), output_abs.as_str()])
        .env_remove("CONDUIT_ENABLE")
        .env_remove("CONDUIT_SOCK")
        .env("CONDUIT_RUNTIME_DIR", &runtime_dir)
        .stdin(Stdio::null())
        .stdout(Stdio::from(output_file))
        .stderr(Stdio::from(stderr_file));

    let child = match command.spawn() {
        Ok(c) => c,
        Err(e) => {
            let _ = std::fs::remove_file(&scratch_path

fn read_action(action: &str) -> Result<(f64, Array<Gd<InputEvent>>), BridgeError> {
    let settings = ProjectSettings::singleton();
    let key = format!("{PREFIX}{action}");
    if !settings.has_setting(key.as_str()) {
        return Err(BridgeError::InvalidArgs(format!("no input action named '{action}'")));
    }
    let stored = settings.get_setting(key.as_str());
    let dict = stored
        .try_to::<VarDictionary>()
        .map_err(|_| BridgeError::Internal(format!("setting '{key}' is not an action dictionary")))?;
    let deadzone = dict
        .get(&GString::from("deadzone"))
        .and_then(|v| v.try_to::<f64>().ok())
        .unwrap_or(DEFAULT_DEADZONE);
    let mut events = Array::<Gd<InputEvent>>::new();
    if let Some(raw) = dict.get(&GString::from("events")).and_then(|v| v.try_to::<VarArray>().ok()) {
        for item in raw.iter_shared() {
            if let Ok(event) = item.try_to::<Gd<InputEvent>>() {
                events.push(&event);
            }
        }
    }
    Ok((deadzone, events))
}

fn write_action(action: &str, deadzone: f64, events: &Array<Gd<InputEvent>>) -> Result<(), BridgeError> {
    let mut stored_events = VarArray::new();
    for event in events.iter_shared() {
        stored_events.push(&event.to_variant());
    }
    let mut dict = VarDictionary::new();
    dict.set(&GString::from("deadzone"), &deadzone.to_variant());
    dict.set(&GString::from("events"), &stored_events.to_variant());

    let mut settings = ProjectSettings::singleton();
    settings.set_setting(format!("{PREFIX}{action}").as_str(), &dict.to_variant());
    save(&mut settings)
}

fn save(settings: &mut Gd<ProjectSettings>) -> Result<(), BridgeError> {
    let save_err = settings.save();
    if save_err != GdError::OK {
        return Err(BridgeError::ResourceError(format!("failed to save project settings: {save_err:?}")));
    }
    Ok(())
}

fn encode_event(event: &Gd<InputEvent>) -> Value {
    if let Ok(key) = event.clone().try_cast::<InputEventKey>() {
        let mut entry = json!({ "type": "key", "text": event.as_text().to_string() });
        if key.get_keycode() != Key::NONE {
            entry["keycode"] = json!(key.get_keycode().ord());
        }
        if key.get_physical_keycode() != Key::NONE {
            entry["physical_keycode"] = json!(key.get_physical_keycode().ord());
        }
        for (name, active) in [
            ("shift", key.is_shift_pressed()),
            ("ctrl", key.is_ctrl_pressed()),
            ("alt", key.is_alt_pressed()),
            ("meta", key.is_meta_pressed()),
        ] {
            if active {
                entry[name] = json!(true);
            }
        }
        return entry;
    }
    if let Ok(button) = event.clone().try_cast::<InputEventJoypadButton>() {
        return json!({ "type": "joy_button", "button_index": button.get_button_index().ord(), "text": event.as_text().to_string() });
    }
    if let Ok(motion) = event.clone().try_cast::<InputEventJoypadMotion>() {
        return json!({ "type": "joy_motion", "axis": motion.get_axis().ord(), "axis_value": motion.get_axis_value(), "text": event.as_text().to_string() });
    }
    if let Ok(mouse) = event.clone().try_cast::<InputEventMouseButton>() {
        return json!({ "type": "mouse_button", "button_index": mouse.get_button_index().ord(), "text": event.as_text().to_string() });
    }
    json!({ "type": "other", "class": event.get_class().to_string(), "text": event.as_text().to_string() })
}

fn decode_event(value: &Value) -> Result<Gd<InputEvent>, BridgeError> {
    let kind = value
        .get("type")
        .and_then(Value::as_str)
        .ok_or_else(|| BridgeError::InvalidArgs("'event.type' is required".into()))?;
    match kind {
        "key" => {
            let key = decode_key(value)?;
            let physical = value.get("physical").and_then(Value::as_bool).unwrap_or(false);
            let mut event = InputEventKey::new_gd();
            if physical {
                event.set_physical_keycode(key);
            } else {
                event.set_keycode(key);
            }
            event.set_shift_pressed(value.get("shift").and_then(Value::as_bool).unwrap_or(false));
            event.set_ctrl_pressed(value.get("ctrl").and_then(Value::as_bool).unwrap_or(false));
            event.set_alt_pressed(value.get("alt").and_then(Value::as_bool).unwrap_or(false));
            event.set_meta_pressed(value.get("meta").and_then(Value::as_bool).unwrap_or(false));
            Ok(event.upcast())
        }
        "joy_button" => {
            let index = value
                .get("button_index")
                .and_then(Value::as_i64)
                .ok_or_else(|| BridgeError::InvalidArgs("'event.button_index' is required for joy_button".into()))?;
            let button = JoyButton::try_from_ord(index as i32)
                .ok_or_else(|| BridgeError::InvalidArgs(format!("unknown joypad button {index}")))?;
            let mut event = InputEventJoypadButton::new_gd();
            event.set_button_index(button);
            Ok(event.upcast())
        }
        "joy_motion" => {
            let axis_ord = value
                .get("axis")
                .and_then(Value::as_i64)
                .ok_or_else(|| BridgeError::InvalidArgs("'event.axis' is required for joy_motion".into()))?;
            let axis = JoyAxis::try_from_ord(axis_ord as i32)
                .ok_or_else(|| BridgeError::InvalidArgs(format!("unknown joypad axis {axis_ord}")))?;
            let axis_value = value.get("axis_value").and_then(Value::as_f64).unwrap_or(1.0);
            let mut event = InputEventJoypadMotion::new_gd();
            event.set_axis(axis);
            event.set_axis_value(axis_value as f32);
            Ok(event.upcast())
        }
        "mouse_button" => {
            let index = value
                .get("button_index")
                .and_then(Value::as_i64)
                .ok_or_else(|| BridgeError::InvalidArgs("'event.button_index' is required for mouse_button".into()))?;
            let button = MouseButton::try_from_ord(index as i32)
                .ok_or_else(|| BridgeError::InvalidArgs(format!("unknown mouse button {index}")))?;
            let mut event = InputEventMouseButton::new_gd();
            event.set_button_index(button);
            Ok(event.upcast())
        }
        other => Err(BridgeError::InvalidArgs(format!(
            "unknown event type '{other}'; expected key, joy_button, joy_motion, or mouse_button"
        ))),
    }
}

fn list() -> Result<Value, BridgeError> {
    let settings = ProjectSettings::singleton();
    let mut actions = Vec::new();
    for entry in settings.get_property_list().iter_shared() {
        let key = entry.get(&GString::from("name")).map(|v| v.to_string()).unwrap_or_default();
        let Some(action) = key.strip_prefix(PREFIX) else { continue };
        let Ok((deadzone, events)) = read_action(action) else { continue };
        let events_json: Vec<Value> = events
            .iter_shared()
            .enumerate()
            .map(|(index, event)| {
                let mut encoded = encode_event(&event);
                encoded["index"] = json!(index);
                encoded
            })
            .collect();
        actions.push(json!({ "action": action, "deadzone": deadzone, "events": events_json }));
    }
    Ok(json!({ "actions": actions }))
}

fn add_action(args: &Value) -> Result<Value, BridgeError> {
    let action = require_str(args, "action")?;
    validate_action(&action)?;
    let deadzone = optional_f64(args, "deadzone").unwrap_or(DEFAULT_DEADZONE);

    let settings = ProjectSettings::singleton();
    if settings.has_setting(format!("{PREFIX}{action}").as_str()) {
        return Err(BridgeError::AlreadyExists(format!("input action '{action}' already exists")));
    }
    write_action(&action, deadzone, &Array::new())?;
    Ok(json!({ "action": action, "deadzone": deadzone }))
}

fn remove_action(args: &Value) -> Result<Value, BridgeError> {
    let action = require_str(args, "action")?;
    validate_action(&action)?;
    read_action(&action)?;

    let mut settings = ProjectSettings::singleton();
    settings.set_setting(format!("{PREFIX}{action}").as_str(), &Variant::nil());
    save(&mut settings)?;
    Ok(json!({ "action": action, "removed": true }))
}

