fn list() -> Result<Value, BridgeError> {
    let editor = EditorInterface::singleton();
    let mut plugins = Vec::new();
    if DirAccess::dir_exists_absolute(ADDONS_DIR) {
        for entry in DirAccess::get_directories_at(ADDONS_DIR).as_slice() {
            let name = entry.to_string();
            let config_path = plugin_config_path(&name);
            let mut config = ConfigFile::new_gd();
            // A directory under addons/ without a plugin.cfg is not a plugin:
            // a GDExtension addon (Conduit's own, for one) lives there too.
            if config.load(config_path.as_str()) != GdError::OK {
                continue;
            }
            let read = |key: &str| -> Value {
                if config.has_section_key(PLUGIN_SECTION, key) {
                    variant_to_json(&config.get_value(PLUGIN_SECTION, key))
                } else {
                    Value::Null
                }
            };
            plugins.push(json!({
                "plugin": name,
                "config_path": config_path,
                "name": read("name"),
                "description": read("description"),
                "author": read("author"),
                "version": read("version"),
                "script": read("script"),
                "enabled": editor.is_plugin_enabled(name.as_str()),
            }));
        }
    }
    Ok(json!({ "plugins": plugins }))
}

fn set_enabled(args: &Value, enabled: bool) -> Result<Value, BridgeError> {
    let name = require_str(args, "plugin")?;
    validate_plugin_name(&name)?;

    let config_path = plugin_config_path(&name);
    if !FileAccess::file_exists(config_path.as_str()) {
        return Err(BridgeError::ResourceError(format!(
            "no plugin at '{config_path}'; the plugin argument is a directory name under res://addons, and gd_editor_plugin list reports the ones that exist"
        )));
    }

    let mut editor = EditorInterface::singleton();
    let previous = editor.is_plugin_enabled(name.as_str());
    editor.set_plugin_enabled(name.as_str(), enabled);

    // set_plugin_enabled reports nothing. A plugin whose script fails to load
    // leaves the enabled set unchanged, so reading it back is the only way to
    // tell a refusal from a success.
    let observed = editor.is_plugin_enabled(name.as_str());
    if observed != enabled {
        let verb = if enabled { "enable" } else { "disable" };
        return Err(BridgeError::ResourceError(format!(
            "the editor did not {verb} plugin '{name}'; its plugin script probably failed to load, which the editor log records"
        )));
    }

    // The engine updates editor_plugins/enabled in memory; the save is what
    // puts it in project.godot. Saving unconditionally is idempotent, so
    // whether the engine already saved does not have to be known.
    let mut settings = ProjectSettings::singleton();
    let save_err = settings.save();
    if save_err != GdError::OK {
        return Err(BridgeError::ResourceError(format!("failed to save project settings: {save_err:?}")));
    }

    Ok(json!({ "plugin": name, "enabled": enabled, "previous": previous }))
}

pub fn get_setting(args: &Value, _ctx: &FrameContext) -> HandlerOutcome {
    HandlerOutcome::Done((|| {
        let key = require_str(args, "key")?;
        let settings = ProjectSettings::singleton();
        if !settings.has_setting(key.as_str()) {
            return Err(BridgeError::InvalidProperty(format!("no project setting '{key}'")));
        }
        let value = settings.get_setting(key.as_str());
        Ok(json!({ "key": key, "value": variant_to_json(&value) }))
    })())
}

pub fn set_setting(args: &Value, _ctx: &FrameContext) -> HandlerOutcome {
    HandlerOutcome::Done((|| {
        let key = require_str(args, "key")?;
        let value = args.get("value").ok_or_else(|| BridgeError::InvalidArgs("'value' is required".into()))?;

        let mut settings = ProjectSettings::singleton();
        let previous = settings.get_setting(key.as_str());
        let expected = previous.get_type();
        let variant = if expected == VariantType::NIL {
            json_to_variant(value)?
        } else {
            json_to_variant_typed(value, expected)?
        };
        settings.set_setting(key.as_str(), &variant);

        let save_err = settings.save();
        if save_err != GdError::OK {
            return Err(BridgeError::ResourceError(format!("failed to save project settings: {save_err:?}")));
        }

        Ok(json!({ "key": key, "previous": variant_to_json(&previous) }))
    })())
}

fn resource_property_names(resource: &Gd<Resource>) -> Vec<String> {
    let mut names = Vec::new();
    for entry in resource.get_property_list().iter_shared() {
        let name = entry.get(&GString::from("name")).map(|value| value.to_string()).unwrap_or_default();
        if !name.is_empty() {
            names.push(name);
        }
    }
    names
}

fn resource_property_exists(resource: &Gd<Resource>, name: &str) -> bool {
    resource_property_names(resource).iter().any(|candidate| candidate == name)
}

pub(crate) fn resource_uid_text(path: &str) -> Option<String> {
    let uid = ResourceLoader::singleton().get_resource_uid(path);
    if uid == ResourceUid::INVALID_ID as i64 {
        None
    } else {
        Some(ResourceUid::singleton().id_to_text(uid).to_string())
    }
}

pub fn create(args: &Value, ctx: &FrameContext) -> HandlerOutcome {
    let prepared: Result<(String, String), BridgeError> = (|| {
        let class_name = require_str(args, "class_name")?;
        let path = require_str(args, "path")?;
        validate_project_path(&path)?;

        let class_db = ClassDb::singleton();
        if !class_db.class_exists(class_name.as_str()) || !class_db.can_instantiate(class_name.as_str()) {
            return Err(BridgeError::InvalidArgs(format!(
                "'{class_name}' does not exist or cannot be instantiated"
            )));
        }
        if !class_db.is_parent_class(class_name.as_str(), "Resource") {
            return Err(BridgeError::InvalidArgs(format!("'{class_name}' is not a Resource subclass")));
        }
        let resource = class_db
            .instantiate(class_name.as_str())
            .try_to::<Gd<Resource>>()
            .map_err(|e| BridgeError::ResourceError(format!("failed to instantiate '{class_name}': {e}")))?;

        let save_err = ResourceSaver::singleton().save_ex(&resource).path(path.as_str()).done();
        if save_err != GdError::OK {
            return Err(BridgeError::ResourceError(format!("failed to save resource to '{path}': {save_err:?}")));
        }
        Ok((path, class_name))
    })();

    let (path, class_name) = match prepared {
        Ok(v) => v,
        Err(e) => return HandlerOutcome::Done(Err(e)),
    };

    trigger_rescan(false, ctx, move || {
        let uid = resource_uid_text(&path);
        Ok(json!({ "path": path, "class_name": class_name, "uid": uid }))
    })
}

pub fn set_property(args: &Value, ctx: &FrameContext) -> HandlerOutcome {
    let path = match require_str(args, "path") {
        Ok(v) => v,
        Err(e) => return HandlerOutcome::Done(Err(e)),
    };
    if let Err(e) = validate_project_path(&path) {
        return HandlerOutcome::Done(Err(e));
    }
    let property = match require_str(args, "property") {
        Ok(v) => v,
        Err(e) => return HandlerOutcome::Done(Err(e)),
    };
    let value = match args.get("value") {
        Some(v) => v.clone(),
        None => return HandlerOutcome::Done(Err(BridgeError::InvalidArgs("'value' is required".into()))),
    };

    let previous_json = match (|| -> Result<Value, BridgeError> {
        let mut resource = ResourceLoader::singleton()
            .load(path.as_str())
            .ok_or_else(|| BridgeError::ResourceError(format!("could not load resource at '{path}'")))?;
        let previous = resource.get(property.as_str());
        if previous.is_nil() && !resource_property_exists(&resource, &property) {
            return Err(BridgeError::InvalidProperty(format!(
                "resource at '{path}' has no property '{property}'"
            )));
        }

        let expected = previous.get_type();
        let variant = if expected == VariantType::NIL {
            json_to_variant(&value)?
        } else {
            json_to_variant_typed(&value, expected)?
        };
        resource.set(property.as_str(), &variant);

        let save_err = ResourceSaver::singleton().save(&resource);
        if save_err != GdError::OK {
            return Err(BridgeError::ResourceError(format!("failed to save resource to '{path}': {save_err:?}")));
        }
        Ok(variant_to_json(&previous))
    })() {
        Ok(v) => v,
        Err(e) => return HandlerOutcome::Done(Err(e)),
    };

    trigger_rescan(false, ctx, move || Ok(json!({ "path": path, "property": property, "previous": previous_json })))
}

pub fn call_method(args: &Value, ctx: &FrameContext) -> HandlerOutcome {
    let prepared: Result<(String, String, Value, bool, Value), BridgeError> = (|| {
        let path = require_str(args, "path")?;
        validate_project_path(&path)?;
        let method = require_str(args, "method")?;
        let save = args.get("save").and_then(Value::as_bool).unwrap_or(true);

        let resource = load_resource(&path)?;
        if !resource.has_method(method.as_str()) {
            return Err(BridgeError::CallFailed(format!(
                "resource at '{path}' has no method '{method}'"
            )));
        }

        let call_args = crate::handlers::call::call_args(args)?;

        let mut object = resource.clone().upcast::<Object>();
        let result = crate::handlers::call::call_on(&mut object, &method, &call_args)?;
        if save {
            let save_err = ResourceSaver::singleton().save(&resource);
            if save_err != GdError::OK {
                return Err(BridgeError::ResourceError(format!(
                    "failed to save resource to '{path}': {save_err:?}"
                )));
            }
        }
        // Capture runs after the save so a failed write does not leave a minted
        // handle behind for a call that reports an error.
        let mut capture = json!({});
        crate::handles::apply_capture(args, &result, &mut capture)?;
        Ok((path, method, variant_to_json(&result), save, capture))
    })();

    let (path, method, result, save, capture) = match prepared {
        Ok(v) => v,
        Err(e) => return HandlerOutcome::Done(Err(e)),
    };

    let mut response = json!({ "path": path, "method": method, "result": result });
    if let (Some(target), Some(extra)) = (response.as_object_mut(), capture.as_object()) {
        target.extend(extra.iter().map(|(key, value)| (key.clone(), value.clone())));
    }

    // A pure query changed no file, so there is nothing for the editor to
    // rescan and no reason to make the caller wait for one.
    if !save {
        response["saved"] = json!(false);
        return HandlerOutcome::Done(Ok(response));
    }
    trigger_rescan(false, ctx, move || {
        let mut response = response;
        response["saved"] = json!(true);
        Ok(response)
    })
}

fn load_resource(path: &str) -> Result<Gd<Resource>, BridgeError> {
    ResourceLoader::singleton()
        .load(path)
        .ok_or_else(|| BridgeError::ResourceError(format!("could not load resource at '{path}'")))
}

fn instantiate_node(type_name: &str) -> Result<Gd<Node>, BridgeError> {
    let class_db = ClassDb::singleton();
    if !class_db.class_exists(type_name) || !class_db.can_instantiate(type_name) {
        return Err(BridgeError::InvalidArgs(format!(
            "'{type_name}' does not exist or cannot be instantiated"
        )));
    }
    if !class_db.is_parent_class(type_name, "Node") {
        return Err(BridgeError::InvalidArgs(format!("'{type_name}' is not a Node subclass")));
    }
    class_db
        .instantiate(type_name)
        .try_to::<Gd<Node>>()
        .map_err(|e| BridgeError::ResourceError(format!("failed to instantiate '{type_name}': {e}")))
}

pub fn open(args: &Value, ctx: &FrameContext) -> HandlerOutcome {
    let path = match require_str(args, "path") {
        Ok(v) => v,
        Err(e) => return HandlerOutcome::Done(Err(e)),
    };
    if let Err(e) = validate_project_path(&path) {
        return HandlerOutcome::Done(Err(e));
    }
    EditorInterface::singleton().open_scene_from_path(path.as_str());
    HandlerOutcome::Pending(Box::new(SceneOpenPending {
        path,
        deadline_frame: ctx.frame_index.saturating_add(SCENE_OPEN_DEADLINE_FRAMES),
    }))
}

pub fn create(args: &Value, ctx: &FrameContext) -> HandlerOutcome {
    let prepared: Result<(String, String, bool), BridgeError> = (|| {
        let root_type = require_str(args, "root_type")?;
        let path = require_str(args, "path")?;
        validate_project_path(&path)?;
        let root_name = optional_str(args, "root_name");
        let open = optional_bool(args, "open").unwrap_or(true);

        let mut root = instantiate_node(&root_type)?;
        root.set_name(root_name.as_deref().unwrap_or(root_type.as_str()));

        let mut packed = PackedScene::new_gd();
        let pack_err = packed.pack(&root);
        if pack_err != GdError::OK {
            return Err(BridgeError::ResourceError(format!("failed to pack scene: {pack_err:?}")));
        }
        let save_err = ResourceSaver::singleton().save_ex(&packed).path(path.as_str()).done();
        if save_err != GdError::OK {
            return Err(BridgeError::ResourceError(format!("failed to save scene to '{path}': {save_err:?}")));
        }
        Ok((path, root_type, open))
    })();

    let (path, root_type, open) = match prepared {
        Ok(v) => v,
        Err(e) => return HandlerOutcome::Done(Err(e)),
    };

    trigger_rescan(false, ctx, move || {
        if open {
            EditorInterface::singleton().open_scene_from_path(path.as_str());
        }
        Ok(json!({ "path": path, "root_type": root_type, "opened": open }))
    })
}

fn tree_node(scene_root: &Gd<Node>, node: &Gd<Node>, depth_remaining: u64) -> Value {
    let script_path = node.get_script().map(|script| script.get_path().to_string());
    let mut entry = json!({
        "name": node.get_name().to_string(),
        "class": node.get_class().to_string(),
        "path": relative_path(scene_root, node),
        "child_count": node.get_child_count(),
        "script": script_path,
    });
    if depth_remaining > 0 {
        let children: Vec<Value> = node
            .get_children()
            .iter_shared()
            .map(|child| tree_node(scene_root, &child, depth_remaining - 1))
            .collect();
        entry["children"] = Value::Array(children);
    } else if node.get_child_count() > 0 {
        entry["children_truncated"] = json!(true);
    }
    entry
}

pub fn save(args: &Value, _ctx: &FrameContext) -> HandlerOutcome {
    HandlerOutcome::Done((|| {
        let mut editor = EditorInterface::singleton();
        match optional_str(args, "path") {
