pub fn node_add(args: &Value, _ctx: &FrameContext) -> HandlerOutcome {
    HandlerOutcome::Done((|| {
        let parent_path = require_str(args, "parent_path")?;
        let type_name = require_str(args, "type")?;
        let name = optional_str(args, "name");
        let properties = match args.get("properties") {
            None | Some(Value::Null) => None,
            Some(Value::Object(map)) => Some(map),
            Some(_) => return Err(BridgeError::InvalidArgs("'properties' must be an object".into())),
        };

        let parent = resolve_editor_node(&parent_path)?;
        let mut new_node = instantiate_node(&type_name)?;
        if let Some(name) = &name {
            new_node.set_name(name.as_str());
        }

        // Initial values are applied before the undo-wrapped add commits, so a
        // single undo removes the whole node and no per-property undo entries
        // are needed. The instance is freed on failure because it is not yet in
        // the tree and would otherwise leak.
        if let Some(map) = properties {
            for (key, value) in map {
                if let Err(err) = apply_initial_property(&mut new_node, &type_name, key, value) {
                    new_node.free();
                    return Err(err);
                }
            }
        }

        let root = edited_scene_root()?;
        let mut ur = undo_redo()?;
        let action_name = format!("Conduit: Add {type_name}");
        ur.create_action(action_name.as_str());
        ur.try_add_do_method(&parent, "add_child", &[new_node.to_variant()])
            .map_err(|e| call_error("add_do_method(add_child)", e))?;
        ur.try_add_do_method(&new_node, "set_owner", &[root.to_variant()])
            .map_err(|e| call_error("add_do_method(set_owner)", e))?;
        crate::handlers::editor::support::queue_owner_recursive(&mut ur, &new_node, &root);
        ur.add_do_reference(&new_node);
        ur.try_add_undo_method(&parent, "remove_child", &[new_node.to_variant()])
            .map_err(|e| call_error("add_undo_method(remove_child)", e))?;
        ur.commit_action();

        Ok(json!({
            "node_path": relative_path(&root, &new_node),
            "name": new_node.get_name().to_string(),
            "class": type_name,
            "action_name": action_name,
        }))
    })())
}

pub fn scene_instantiate(args: &Value, _ctx: &FrameContext) -> HandlerOutcome {
    HandlerOutcome::Done((|| {
        let scene_path = require_str(args, "scene_path")?;
        let parent_path = require_str(args, "parent_path")?;
        let name = optional_str(args, "name");
        validate_project_path(&scene_path)?;

        let parent = resolve_editor_node(&parent_path)?;
        let root = edited_scene_root()?;
        if root.get_scene_file_path().to_string() == scene_path {
            return Err(BridgeError::InvalidArgs(format!("cannot instantiate '{scene_path}' inside itself")));
        }

        let packed = ResourceLoader::singleton()
            .load(scene_path.as_str())
            .and_then(|res| res.try_cast::<PackedScene>().ok())
            .ok_or_else(|| BridgeError::ResourceError(format!("'{scene_path}' is not a loadable PackedScene")))?;
        let mut instance = packed
            .instantiate_ex()
            .edit_state(GenEditState::INSTANCE)
            .done()
            .ok_or_else(|| BridgeError::ResourceError(format!("failed to instantiate '{scene_path}'")))?;
        if let Some(name) = &name {
            instance.set_name(name.as_str());
        }

        let mut ur = undo_redo()?;
        let action_name = format!("Conduit: Instantiate {scene_path}");
        ur.create_action(action_name.as_str());
        ur.try_add_do_method(&parent, "add_child", &[instance.to_variant()])
            .map_err(|e| call_error("add_do_method(add_child)", e))?;
        ur.try_add_do_method(&instance, "set_owner", &[root.to_variant()])
            .map_err(|e| call_error("add_do_method(set_owner)", e))?;
        ur.add_do_reference(&instance);
        ur.try_add_undo_method(&parent, "remove_child", &[instance.to_variant()])
            .map_err(|e| call_error("add_undo_method(remove_child)", e))?;
        ur.commit_action();

        Ok(json!({
            "node_path": relative_path(&root, &instance),
            "name": instance.get_name().to_string(),
            "scene_path": scene_path,
            "action_name": action_name,
        }))
    })())
}

fn apply_initial_property(
    node: &mut Gd<Node>,
    type_name: &str,
    key: &str,
    value: &Value,
) -> Result<(), BridgeError> {
    let previous = node.get(key);
    if previous.is_nil() && !crate::handlers::runtime::support::property_exists(node, key) {
        return Err(BridgeError::InvalidProperty(format!("'{type_name}' has no property '{key}'")));
    }
    let variant = if previous.get_type() == godot::builtin::VariantType::NIL {
        crate::variant_json::json_to_variant(value)?
    } else {
        crate::variant_json::json_to_variant_typed(value, previous.get_type())?
    };
    node.set(key, &variant);
    Ok(())
}

pub fn create(args: &Value, ctx: &FrameContext) -> HandlerOutcome {
    let prepared: Result<(String, String), BridgeError> = (|| {
        let path = require_str(args, "path")?;
        validate_project_path(&path)?;
        let extends = optional_str(args, "extends").unwrap_or_else(|| "Node".to_string());
        let template_source = optional_str(args, "template_source");
        // Never validated here: a broken template_source is exactly how
        // gd_script_validate's diagnostics path gets exercised, so this
        // handler's only job is writing bytes faithfully.
        let source = template_source.unwrap_or_else(|| format!("extends {extends}\n"));

        let mut script = GDScript::new_gd();
        script.set_source_code(source.as_str());
        let save_err = ResourceSaver::singleton().save_ex(&script).path(path.as_str()).done();
        if save_err != GdError::OK {
            return Err(BridgeError::ResourceError(format!("failed to save script to '{path}': {save_err:?}")));
        }
        Ok((path, extends))
    })();

    let (path, extends) = match prepared {
        Ok(v) => v,
        Err(e) => return HandlerOutcome::Done(Err(e)),
    };

    trigger_rescan(false, ctx, move || Ok(json!({ "path": path, "extends": extends })))
}

pub fn attach(args: &Value, _ctx: &FrameContext) -> HandlerOutcome {
    HandlerOutcome::Done((|| {
        let node_path = require_str(args, "node_path")?;
        let script_path = require_str(args, "script_path")?;
        validate_project_path(&script_path)?;

        let node = resolve_editor_node(&node_path)?;
        let resource = ResourceLoader::singleton()
            .load(script_path.as_str())
            .ok_or_else(|| BridgeError::ResourceError(format!("could not load resource at '{script_path}'")))?;
        let script = resource
            .try_cast::<Script>()
            .map_err(|_| BridgeError::InvalidArgs(format!("'{script_path}' is not a Script resource")))?;

        let old_script = node.get_script().map(|s| s.to_variant()).unwrap_or(Variant::nil());
        let mut ur = undo_redo()?;
        let action_name = format!("Conduit: Attach {script_path} to {}", node.get_name());
        ur.create_action(action_name.as_str());
        ur.add_do_property(&node, "script", &script.to_variant());
        ur.add_undo_property(&node, "script", &old_script);
        ur.commit_action();

        Ok(json!({ "node_path": node_path, "script_path": script_path, "action_name": action_name }))
    })())
}

pub fn validate(args: &Value, _ctx: &FrameContext) -> HandlerOutcome {
    let path = match require_str(args, "path") {
        Ok(v) => v,
        Err(e) => return HandlerOutcome::Done(Err(e)),
    };
    if let Err(e) = validate_project_path(&path) {
        return HandlerOutcome::Done(Err(e));
    }

    let godot_bin = Os::singleton().get_executable_path().to_string();
    let project_path = ProjectSettings::singleton().globalize_path("res://").to_string();
    let output_path = unique_check_output_path();

    let output_file = match std::fs::File::create(&output_path) {
        Ok(f) => f,
        Err(e) => {
            return HandlerOutcome::Done(Err(BridgeError::Internal(format!(
                "failed to create scratch file for script validation: {e}"
            ))))
        }
    };
    let stderr_file = match output_file.try_clone() {
        Ok(f) => f,
        Err(e) => {
            let _ = std::fs::remove_file(&output_path);
            return HandlerOutcome::Done(Err(BridgeError::Internal(format!(
                "failed to prepare scratch file for script validation: {e}"
            ))));
        }
    };

    let mut command = Command::new(&godot_bin);
    command
        .args(["--headless", "--path", project_path.as_str(), "--script", path.as_str(), "--check-only"])
        // Never let the checked-out subprocess's own GDExtension init try to
        // bind a bridge socket; it inherits these otherwise (whitepaper
        // section 6.3's opt-in gate covers the non-editor case, but clearing
        // them here means the gate is never even consulted).
        .env_remove("CONDUIT_ENABLE")
        .env_remove("CONDUIT_SOCK")
        .env_remove("CONDUIT_RUNTIME_DIR")
        .stdin(Stdio::null())
        .stdout(Stdio::from(output_file))
        .stderr(Stdio::from(stderr_file));

    let child = match command.spawn() {
        Ok(c) => c,
        Err(e) => {
            let _ = std::fs::remove_file(&output_path);
            return HandlerOutcome::Done(Err(BridgeError::Internal(format!(
                "failed to spawn godot for script validation: {e}"
            ))));
        }
    };

    HandlerOutcome::Pending(Box::new(ScriptCheckPending { path, child, output_path }))
}

pub fn poll_deferred_quit() {
    enum Action {
        None,
        Quit,
        Kill,
    }
    let action = PENDING_QUIT.with(|slot| {
        let mut borrow = slot.borrow_mut();
        let now = Instant::now();
        match borrow.as_mut() {
            Some(QuitPhase::Flush(schedule)) => {
                if schedule.tick(now) {
                    *borrow = Some(QuitPhase::Grace(QuitSchedule::new(now, GRACE_FRAMES, GRACE_DELAY)));
                    Action::Quit
                } else {
                    Action::None
                }
            }
            Some(QuitPhase::Grace(schedule)) => {
                if schedule.tick(now) {
                    *borrow = None;
                    Action::Kill
                } else {
                    Action::None
                }
            }
            None => Action::None,
        }
    });
    match action {
        Action::None => {}
        Action::Quit => {
            if let Ok(mut tree) = scene_tree() {
                tree.quit();
            }
        }
        Action::Kill => {
            eprintln!("conduit: editor still running after quit request; killing own process");
            let mut os = Os::singleton();
            let pid = os.get_process_id();
            let _ = os.kill(pid);
        }
    }
}

pub fn validate(args: &Value, _ctx: &FrameContext) -> HandlerOutcome {
    let path = match require_str(args, "path") {
        Ok(v) => v,
        Err(e) => return HandlerOutcome::Done(Err(e)),
    };
    if let Err(e) = validate_project_path(&path) {
        return HandlerOutcome::Done(Err(e));
    }
    if let Err(e) = validate_shader_extension(&path) {
        return HandlerOutcome::Done(Err(e));
    }

    let godot_bin = Os::singleton().get_executable_path().to_string();
    let project_path = ProjectSettings::singleton().globalize_path("res://").to_string();
    let (driver_path, output_path) = scratch_paths();

    if let Err(e) = std::fs::write(&driver_path, DRIVER_SOURCE) {
        return HandlerOutcome::Done(Err(BridgeError::Internal(format!(
            "failed to write the shader validation driver script: {e}"
        ))));
    }

    let output_file = match std::fs::File::create(&output_path) {
        Ok(f) => f,
        Err(e) => {
            let _ = std::fs::remove_file(&driver_path);
            return HandlerOutcome::Done(Err(BridgeError::Internal(format!(
                "failed to create scratch file for shader validation: {e}"
            ))));
        }
    };
    let stderr_file = match output_file.try_clone() {
        Ok(f) => f,
        Err(e) => {
            let _ = std::fs::remove_file(&driver_path);
            let _ = std::fs::remove_file(&output_path);
            return HandlerOutcome::Done(Err(BridgeError::Internal(format!(
                "failed to prepare scratch file for shader validation: {e}"
            ))));
        }
    };

    let mut command = Command::new(&godot_bin);
    command
        .args([
            "--headless",
            "--path",
            project_path.as_str(),
            "--script",
            driver_path.to_string_lossy().as_ref(),
            "--",
            path.as_str(),
        ])
        // Same reason as gd_script_validate: the child loads this project's
        // GDExtension too, and must never try to bind a bridge socket of its own.
        .env_remove("CONDUIT_ENABLE")
        .env_remove("CONDUIT_SOCK")
        .env_remove("CONDUIT_RUNTIME_DIR")
        .stdin(Stdio::null())
        .stdout(Stdio::from(output_file))
        .stderr(Stdio::from(stderr_file));

    let child = match command.spawn() {
        Ok(c) => c,
        Err(e) => {
            let _ = std::fs::remove_file(&driver_path);
            let _ = std::fs::remove_file(&output_path);
            return HandlerOutcome::Done(Err(BridgeError::Internal(format!(
                "failed to spawn godot for shader validation: {e}"
            ))));
        }
    };

    HandlerOutcome::Pending(Box::new(ShaderCheckPending { path, child, driver_path, output_path }))
}

pub(crate) fn edited_scene_root() -> Result<Gd<Node>, BridgeError> {
    EditorInterface::singleton()
        .get_edited_scene_root()
        .ok_or_else(|| BridgeError::NoEditedScene("no scene is open for editing; call gd_scene_open first".into()))
}

pub(crate) fn resolve_editor_node(path: &str) -> Result<Gd<Node>, BridgeError> {
    let root = edited_scene_root()?;
    match root.get_node_or_null(path) {
        Some(node) => Ok(node),
        None => Err(BridgeError::NodeNotFound(nearest_ancestor_message(&root, path))),
    }
}

pub(crate) fn resolve_editor_target(spec: &TargetSpec) -> Result<Gd<Object>, BridgeError> {
    match spec {
        TargetSpec::Node(path) => Ok(resolve_editor_node(path)?.upcast()),
        TargetSpec::Singleton(name) => resolve_singleton(name),
        TargetSpec::Object(id) => crate::handles::resolve(*id),
        // A class is not an object, so there is nothing to resolve. Every tool
        // that reaches an object through this function refuses a `class:`
        // target here rather than each one growing its own check; the two call
        // tools branch on the spec before they get this far.
        TargetSpec::Class(name) => Err(crate::handlers::target::class_target_is_not_an_object(name)),
    }
}

fn nearest_ancestor_message(root: &Gd<Node>, path: &str) -> String {
    if path == "." || path.is_empty() {
        return format!("No node at path '{path}' under the edited scene root.");
    }
    let segments: Vec<&str> = path.split('/').filter(|segment| !segment.is_empty()).collect();
    let mut nearest = ".".to_string();
    for end in (1..segments.len()).rev() {
        let prefix = segments[..end].join("/");
        if root.get_node_or_null(prefix.as_str()).is_some() {
            nearest = prefix;
            break;
        }
    }
    format!("No node at path '{path}' in the edited scene. Nearest existing ancestor: '{nearest}'.")
}

pub(crate) fn relative_path(root: &Gd<Node>, node: &Gd<Node>) -> String {
    if node == root {
        return ".".to_string();
    }
    let mut segments = Vec::new();
    let mut current = node.clone();
    loop {
        segments.push(current.get_name().to_string());
        match current.get_parent() {
            Some(parent) if &parent == root => break,
            Some(parent) => current = parent,
            None => break,
        }
    }
    segments.reverse();
    segments.join("/")
}

pub(crate) fn undo_redo() -> Result<Gd<EditorUndoRedoManager>, BridgeError> {
    EditorInterface::singleton()
        .get_editor_undo_redo()
        .ok_or_else(|| BridgeError::Internal("no EditorUndoRedoManager available".into()))
}

pub(crate) fn queue_owner_recursive(ur: &mut Gd<EditorUndoRedoManager>, node: &Gd<Node>, owner: &Gd<Node>) {
    for child in node.get_children().iter_shared() {
        ur.add_do_property(&child, "owner", &owner.to_variant());
        queue_owner_recursive(ur, &child, owner);
    }
}

impl<F: FnOnce() -> Result<Value, BridgeError>> PendingOp for RescanPending<F> {
    fn poll(&mut self, ctx: &FrameContext) -> Option<Result<Value, BridgeError>> {
        let still_scanning = EditorInterface::singleton()
            .get_resource_filesystem()
            .map(|fs| fs.is_scanning())
            .unwrap_or(false);
        if !still_scanning {
            let finish = self.finish.take().expect("RescanPending polled again after settling");
            return Some(finish());
        }
        if ctx.frame_index >= self.deadline_frame {
            return Some(Err(BridgeError::Internal("filesystem scan did not settle before the deadline".into())));
        }
        None
    }
}

pub(crate) fn trigger_rescan<F>(sources_only: bool, ctx: &FrameContext, finish: F) -> HandlerOutcome
where
    F: FnOnce() -> Result<Value, BridgeError> + 'static,
{
    let Some(mut fs) = EditorInterface::singleton().get_resource_filesystem() else {
        return HandlerOutcome::Done(Err(BridgeError::Internal("no EditorFileSystem available".into())));
    };
    if sources_only {
        fs.scan_sources();
    } else {
        fs.scan();
    }
    HandlerOutcome::Pending(Box::new(RescanPending {
        deadline_frame: ctx.frame_index.saturating_add(RESCAN_DEADLINE_FRAMES),
        finish: Some(finish),
    }))
}

fn layer_op(mut layer: Gd<TileMapLayer>, op: &str, args: &Value) -> Result<Value, BridgeError> {
    // Reads first: identical to the game bridge, and nothing to record.
    match op {
        "get_cell" => return Ok(cell_json(&read_cell(&layer, require_coords(args)?))),
        "used_cells" => {
            let region = parse_region_2d(args)?;
            let cells: Vec<Value> = layer
                .get_used_cells()
                .iter_shared()
                .map(|coords| (coords.x, coords.y))
                .filter(|coords| region.is_none_or(|r| cell_in_region(*coords, r)))
                .map(|coords| cell_json(&read_cell(&layer, coords)))
                .collect();
            let limit = crate::handlers::args::optional_u64(args, "limit")
                .map(|l| l.clamp(1, 1024))
                .unwrap_or(256);
            let offset = crate::handlers::args::optional_u64(args, "offset").unwrap_or(0);
            return Ok(crate::handlers::classdb::paginate(cells, limit, offset));
        }
        "used_rect" => {
            return Ok(json!({ "rect": variant_to_json(&layer.get_used_rect().to_variant()) }));
        }
        "pattern_get" => return tilemap::pattern_get(&layer, args),
        _ => {}
    }

    // Everything else mutates, so it goes through the undo-wrapped path.
    // set_cell and erase_cell become cell writes like any paint op; clear is
    // the one exception, for the reason given at its arm.
    let action = match op {
        "set_cell" => {
            PaintAction::Write(vec![Cell { coords: require_coords(args)?, tile: tilemap::parse_tile(args)? }])
        }
        "erase_cell" => {
            PaintAction::Write(vec![Cell { coords: require_coords(args)?, tile: TileSpec::EMPTY }])
        }
        // clear takes the property path rather than the cell path, because it
        // has an inverse the paint ops do not: a layer's whole cell map is one
        // `tile_map_data` byte array, and restoring it puts back every cell
        // exactly. Queuing one property pair instead of one method pair per
        // cell is what keeps clearing a real level possible at all -- the
        // 4096-cell paint cap would otherwise refuse any layer bigger than
        // 64x64, while the game half's `clear` accepted it.
        "clear" => return clear_layer(&mut layer),
        _ if is_paint_op(op) => tilemap::plan(&layer, op, args)?,
        other => return Err(unknown_op(other)),
    };
    if let PaintAction::Write(cells) = &action
        && cells.len() > tilemap::MAX_PAINT_CELLS
    {
        return Err(tilemap::over_cap(cells.len(), tilemap::MAX_PAINT_CELLS, op));
    }
    run_undoable(&mut layer, op, &action)
}

fn clear_layer(layer: &mut Gd<TileMapLayer>) -> Result<Value, BridgeError> {
    let before = layer.get_tile_map_data_as_array();
    let count = layer.get_used_cells().len();
    if count == 0 {
        return Ok(json!({ "op": "clear", "cleared": true, "changed_count": 0, "action_name": Value::Null, "undoable": false }));
    }
    layer.clear();
    let after = layer.get_tile_map_data_as_array();
    let name = tilemap::action_name("clear", layer);
    let target = layer.clone();
    let mut ur = undo_redo()?;
    ur.create_action(name.as_str());
    ur.add_do_property(&target, "tile_map_data", &after.to_variant());
    ur.add_undo_property(&target, "tile_map_data", &before.to_variant());
    ur.commit_action_ex().execute(false).done();
    Ok(json!({
        "op": "clear",
        "cleared": true,
        "changed_count": count,
        "action_name": name,
        "undoable": true,
    }))
}

fn run_undoable(
    layer: &mut Gd<TileMapLayer>,
    op: &str,
    action: &PaintAction,
) -> Result<Value, BridgeError> {
    let cells = tilemap::affected(layer, action);
    // Checked here rather than only in `plan`, because a terrain op expands to
    // its named cells plus one ring: 4000 named cells become five times that
    // many snapshotted and twice again as many queued undo methods, so the cap
    // has to bound the list that is actually recorded.
    if cells.len() > tilemap::MAX_PAINT_CELLS {
        return Err(tilemap::over_cap(cells.len(), tilemap::MAX_PAINT_CELLS, op));
    }
    let before = tilemap::snapshot(layer, &cells);
    tilemap::apply(layer, action);
    let after = tilemap::snapshot(layer, &cells);
    let changed = tilemap::changed(&before, &after);

    // Nothing moved: no action, and saying so is more useful than an empty
    // entry on the history that `gd_undo` would later consume for nothing.
    if changed.is_empty() {
        return Ok(tilemap::paint_response(op, &changed, None));
    }

    let name = tilemap::action_name(op, layer);
    let mut ur = undo_redo()?;
    ur.create_action(name.as_str());
    for (was, now) in before.iter().zip(after.iter()) {
        if was.tile == now.tile {
            continue;
        }
        queue_cell(&mut ur, layer, now, true)?;
        queue_cell(&mut ur, layer, was, false)?;
    }
    ur.commit_action_ex().execute(false).done();
    Ok(tilemap::paint_response(op, &changed, Some(&name)))
}

fn queue_cell(
    ur: &mut Gd<EditorUndoRedoManager>,
    layer: &Gd<TileMapLayer>,
    cell: &Cell,
    is_do: bool,
) -> Result<(), BridgeError> {
    let coords = Vector2i::new(cell.coords.0, cell.coords.1);
    let (method, call_args) = if cell.tile.is_empty() {
        ("erase_cell", vec![coords.to_variant()])
    } else {
        (
            "set_cell",
            vec![
                coords.to_variant(),
                cell.tile.source_id.to_variant(),
                Vector2i::new(cell.tile.atlas.0, cell.tile.atlas.1).to_variant(),
                cell.tile.alternative.to_variant(),
            ],
        )
    };
    let result = if is_do {
        ur.try_add_do_method(layer, method, &call_args)
    } else {
        ur.try_add_undo_method(layer, method, &call_args)
    };
    result.map_err(|error| {
        BridgeError::Internal(format!(
            "queueing {} {method} on the undo history failed: {error}",
            if is_do { "do" } else { "undo" }
        ))
    })
}

fn grid_op(mut grid: Gd<GridMap>, op: &str, args: &Value) -> Result<Value, BridgeError> {
    if is_paint_op(op) || op == "pattern_get" {
        return Err(BridgeError::InvalidArgs(format!(
            "op '{op}' is a TileMapLayer paint op; a GridMap has cells but no tile geometry, atlas, pattern, or terrain. Use set_cell for each cell"
        )));
    }
    let coords = |args: &Value| -> Result<Vector3i, BridgeError> {
        let value = args
            .get("coords")
            .ok_or_else(|| BridgeError::InvalidArgs("'coords' is required".into()))?;
        let obj = value.as_object();
        let list = value.as_array();
        let read = |index: usize, key: &str| -> Option<i64> {
            match (&list, &obj) {
                (Some(items), _) if items.len() == 3 => items[index].as_i64(),
                (_, Some(map)) => map.get(key).and_then(Value::as_i64),
                _ => None,
            }
        };
        match (read(0, "x"), read(1, "y"), read(2, "z")) {
            (Some(x), Some(y), Some(z)) => Ok(Vector3i::new(x as i32, y as i32, z as i32)),
            _ => Err(BridgeError::InvalidArgs(
                "'coords' must be [x, y, z] or {x, y, z} integers".into(),
            )),
        }
    };
    match op {
        "get_cell" => Ok(grid_cell(&grid, coords(args)?)),
        "used_cells" => Ok(json!({
            "items": grid.get_used_cells().iter_shared().map(|c| grid_cell(&grid, c)).collect::<Vec<Value>>(),
        })),
        "set_cell" | "erase_cell" | "clear" => {
            let (cells, item, orientation) = match op {
                "clear" => (grid.get_used_cells().iter_shared().collect::<Vec<Vector3i>>(), -1, 0),
                "erase_cell" => (vec![coords(args)?], -1, 0),
                _ => (
                    vec![coords(args)?],
                    args.get("item").and_then(Value::as_i64).ok_or_else(|| {
                        BridgeError::InvalidArgs("'item' is required for GridMap set_cell".into())
                    })? as i32,
                    args.get("orientation").and_then(Value::as_i64).unwrap_or(0) as i32,
                ),
            };
            let name = format!("Conduit: {op} on {}", grid.get_name());
            let mut ur = undo_redo()?;
            ur.create_action(name.as_str());
            for cell in &cells {
                let previous = grid.get_cell_item(*cell);
                let previous_orientation = grid.get_cell_item_orientation(*cell);
                grid.set_cell_item_ex(*cell, item).orientation(orientation).done();
                let queue = |ur: &mut Gd<EditorUndoRedoManager>, is_do: bool| {
                    let (value, turn) =
                        if is_do { (item, orientation) } else { (previous, previous_orientation) };
                    let call_args =
                        vec![cell.to_variant(), value.to_variant(), turn.max(0).to_variant()];
                    if is_do {
                        ur.try_add_do_method(&grid, "set_cell_item", &call_args)
                    } else {
                        ur.try_add_undo_method(&grid, "set_cell_item", &call_args)
                    }
                };
                queue(&mut ur, true).map_err(|e| {
                    BridgeError::Internal(format!("queueing do set_cell_item failed: {e}"))
                })?;
                queue(&mut ur, false).map_err(|e| {
                    BridgeError::Internal(format!("queueing undo set_cell_item failed: {e}"))
                })?;
            }
            ur.commit_action_ex().execute(false).done();
            Ok(json!({
                "op": op,
                "changed_count": cells.len(),
                "action_name": name,
                "undoable": true,
            }))
        }
        "used_rect" => Ok(json!({ "rect": Value::Null })),
        other => Err(unknown_op(other)),
    }
}

fn grid_cell(grid: &Gd<GridMap>, coords: Vector3i) -> Value {
    let item = grid.get_cell_item(coords);
    json!({
        "coords": { "x": coords.x, "y": coords.y, "z": coords.z },
        "item": item,
        "orientation": grid.get_cell_item_orientation(coords),
        "empty": item == -1,
    })
}

fn read_list(settings: &Gd<ProjectSettings>, key: &str) -> Vec<String> {
    if !settings.has_setting(key) {
        return Vec::new();
    }
    settings
        .get_setting(key)
        .try_to::<PackedStringArray>()
        .map(|packed| packed.to_vec().into_iter().map(|s| s.to_string()).collect())
        .unwrap_or_default()
}

fn write_list(settings: &mut Gd<ProjectSettings>, key: &str, values: &[String]) {
    if values.is_empty() {
        // Setting NIL erases the entry, so an emptied list leaves project.godot
        // as it was before anything was registered rather than holding a stub.
        settings.set_setting(key, &Variant::nil());
        return;
    }
    let mut packed = PackedStringArray::new();
    for value in values {
        packed.push(&GString::from(value.as_str()));
    }
    settings.set_setting(key, &packed.to_variant());
}

fn read_remaps(settings: &Gd<ProjectSettings>) -> VarDictionary {
    if !settings.has_setting(REMAPS) {
        return VarDictionary::new();
    }
    settings.get_setting(REMAPS).try_to::<VarDictionary>().unwrap_or_default()
}

fn read_all() -> Value {
    let settings = ProjectSettings::singleton();
    let remaps = read_remaps(&settings);
    let mut remap_json = Map::new();
    for (key, _) in remaps.iter_shared() {
        let resource = key.to_string();
        let entries: Vec<Value> = remap_entries(&remaps, &resource)
            .iter()
            .map(|entry| {
                let (variant, locale) = split_entry(entry);
                json!({ "variant": variant, "locale": locale })
            })
            .collect();
        remap_json.insert(resource, Value::Array(entries));
    }

    let locale = |key: &str| -> Value {
        if settings.has_setting(key) {
            json!(settings.get_setting(key).to_string())
        } else {
            Value::Null
        }
    };

    json!({
        "translations": read_list(&settings, TRANSLATIONS),
        "remaps": Value::Object(remap_json),
        "fallback": locale(FALLBACK),
        "test": locale(TEST),
    })
}

fn add(args: &Value) -> Result<Value, BridgeError> {
    let path = require_str(args, "path")?;
    validate_project_path(&path)?;

    let mut settings = ProjectSettings::singleton();
    let mut current = read_list(&settings, TRANSLATIONS);
    if current.iter().any(|entry| entry == &path) {
        return Err(BridgeError::AlreadyExists(format!("translation '{path}' is already registered")));
    }
    current.push(path.clone());
    write_list(&mut settings, TRANSLATIONS, &current);
    save(&mut settings)?;
    Ok(json!({ "path": path, "translations": current }))
}

fn remove(args: &Value) -> Result<Value, BridgeError> {
    let path = require_str(args, "path")?;

    let mut settings = ProjectSettings::singleton();
    let current = read_list(&settings, TRANSLATIONS);
    if !current.iter().any(|entry| entry == &path) {
        return Err(BridgeError::InvalidArgs(format!("no registered translation '{path}'")));
    }
    let remaining: Vec<String> = current.into_iter().filter(|entry| entry != &path).collect();
    write_list(&mut settings, TRANSLATIONS, &remaining);
    save(&mut settings)?;
    Ok(json!({ "path": path, "removed": true, "translations": remaining }))
}

fn remap_add(args: &Value) -> Result<Value, BridgeError> {
    let resource = require_str(args, "resource")?;
    let variant = require_str(args, "variant")?;
    let locale = require_locale(args, "locale")?;
    validate_project_path(&resource)?;
    validate_project_path(&variant)?;

    let mut settings = ProjectSettings::singleton();
    let mut remaps = read_remaps(&settings);
    let mut entries = remap_entries(&remaps, &resource);
    if entries.iter().any(|entry| locale_of(entry).as_deref() == Some(locale.as_str())) {
        return Err(BridgeError::AlreadyExists(format!(
            "'{resource}' already has a remap for locale '{locale}'; remove it first to replace it"
        )));
    }
    entries.push(format!("{variant}:{locale}"));

    let mut packed = PackedStringArray::new();
    for entry in &entries {
        packed.push(&GString::from(entry.as_str()));
    }
    remaps.set(&GString::from(resource.as_str()), &packed.to_variant());
    settings.set_setting(REMAPS, &remaps.to_variant());
    save(&mut settings)?;
    Ok(json!({ "resource": resource, "variant": variant, "locale": locale, "entries": entries }))
}

fn remap_remove(args: &Value) -> Result<Value, BridgeError> {
    let resource = require_str(args, "resource")?;
    let locale = require_locale(args, "locale")?;

    let mut settings = ProjectSettings::singleton();
    let mut remaps = read_remaps(&settings);
    let entries = remap_entries(&remaps, &resource);
    if entries.is_empty() {
        return Err(BridgeError::InvalidArgs(format!("no remaps registered for '{resource}'")));
    }
    let remaining: Vec<String> = entries
        .iter()
        .filter(|entry| locale_of(entry).as_deref() != Some(locale.as_str()))
        .cloned()
        .collect();
    if remaining.len() == entries.len() {
        return Err(BridgeError::InvalidArgs(format!("'{resource}' has no remap for locale '{locale}'")));
    }

    if remaining.is_empty() {
        // A resource whose last variant goes leaves the table, so an emptied
        // remap does not linger as an empty array in project.godot.
        remaps.remove(&GString::from(resource.as_str()));
    } else {
        let mut packed = PackedStringArray::new();
        for entry in &remaining {
            packed.push(&GString::from(entry.as_str()));
        }
        remaps.set(&GString::from(resource.as_str()), &packed.to_variant());
    }

    if remaps.is_empty() {
        settings.set_setting(REMAPS, &Variant::nil());
    } else {
        settings.set_setting(REMAPS, &remaps.to_variant());
    }
    save(&mut settings)?;
    Ok(json!({ "resource": resource, "locale": locale, "removed": true, "entries": remaining }))
}

fn set_locale(args: &Value) -> Result<Value, BridgeError> {
    let fallback = optional_str(args, "fallback");
    let test = optional_str(args, "test");
    if fallback.is_none() && test.is_none() {
        return Err(BridgeError::InvalidArgs("set_locale needs 'fallback', 'test', or both".into()));
    }
    if fallback.as_deref().is_some_and(|value| value.trim().is_empty()) {
        return Err(BridgeError::InvalidArgs("'fallback' must be a locale code such as 'en'".into()));
    }

    let mut settings = ProjectSettings::singleton();
    if let Some(value) = &fallback {
        settings.set_setting(FALLBACK, &GString::from(value.as_str()).to_variant());
    }
    // An empty test locale is the "no override" state the editor writes, so it
    // is a legal value here rather than an error.
    if let Some(value) = &test {
        settings.set_setting(TEST, &GString::from(value.as_str()).to_variant());
    }
    save(&mut settings)?;
    Ok(read_all())
}

fn root_window() -> Result<Gd<Window>, BridgeError> {
    let base = godot::classes::EditorInterface::singleton()
        .get_base_control()
        .ok_or_else(|| BridgeError::Internal("editor has no base control".into()))?;
    base.get_tree()
        .get_root()
        .ok_or_else(|| BridgeError::Internal("editor has no root window".into()))
}

fn list_dialogs_inner() -> Result<Value, BridgeError> {
    let root = root_window()?;
    let dialogs = root.find_children_ex("*").type_("AcceptDialog").recursive(true).owned(false).done();
    let mut visible = Vec::new();
    for (index, node) in dialogs.iter_shared().enumerate() {
        let dialog: Gd<AcceptDialog> = node.cast();
        if !dialog.is_visible() {
            continue;
        }
        visible.push(json!({
            "index": index,
            "class": dialog.get_class().to_string(),
            "title": dialog.get_title().to_string(),
            "text": dialog.get_text().to_string(),
            "buttons": dialog_buttons(&dialog),
        }));
    }
    Ok(json!({ "dialogs": visible }))
}

fn dialog_buttons(dialog: &Gd<AcceptDialog>) -> Vec<String> {
    let mut labels = Vec::new();
    if let Some(ok) = dialog.get_ok_button()
        && let Some(parent) = ok.get_parent()
    {
        for child in parent.get_children().iter_shared() {
            if let Ok(button) = child.try_cast::<Button>() {
                labels.push(button.get_text().to_string());
            }
        }
    }
    if labels.is_empty()
        && let Ok(confirm) = dialog.clone().try_cast::<ConfirmationDialog>()
        && let Some(cancel) = confirm.get_cancel_button()
    {
        labels.push(cancel.get_text().to_string());
    }
    labels
}

fn dialog_choose_inner(args: &Value) -> Result<Value, BridgeError> {
    let button_label = require_str(args, "button")?;
    let title = optional_str(args, "title");
    let index = optional_u64(args, "index").map(|value| value as usize);

    let root = root_window()?;
    let dialogs = root.find_children_ex("*").type_("AcceptDialog").recursive(true).owned(false).done();
    let visible: Vec<Gd<AcceptDialog>> = dialogs
        .iter_shared()
        .map(|node| node.cast::<AcceptDialog>())
        .filter(|dialog| dialog.is_visible())
        .collect();

    if visible.is_empty() {
        return Err(BridgeError::NodeNotFound("no dialog is currently visible".into()));
    }

    let dialog = if let Some(title) = &title {
        visible
            .iter()
            .find(|d| d.get_title().to_string().eq_ignore_ascii_case(title))
            .cloned()
            .ok_or_else(|| {
                let titles: Vec<String> = visible.iter().map(|d| d.get_title().to_string()).collect();
                BridgeError::NodeNotFound(format!("no visible dialog titled '{title}'; visible dialogs: {titles:?}"))
            })?
    } else if let Some(index) = index {
        visible
            .get(index)
            .cloned()
            .ok_or_else(|| BridgeError::NodeNotFound(format!("no visible dialog at index {index}")))?
    } else {
        visible[0].clone()
    };

    let button = find_dialog_button(&dialog, &button_label).ok_or_else(|| {
        BridgeError::NodeNotFound(format!(
            "dialog '{}' has no button labelled '{button_label}'; buttons: {:?}",
            dialog.get_title(),
            dialog_buttons(&dialog)
        ))
    })?;

    // Emitting the button's own pressed signal drives the dialog's accept, cancel,
    // or custom-action wiring exactly as a click would, without pixel input.
    button.clone().emit_signal("pressed", &[]);
    Ok(json!({ "pressed": button_label, "dialog": dialog.get_title().to_string() }))
}

fn find_dialog_button(dialog: &Gd<AcceptDialog>, label: &str) -> Option<Gd<Button>> {
    let ok = dialog.get_ok_button()?;
    let parent = ok.get_parent()?;
    for child in parent.get_children().iter_shared() {
        if let Ok(button) = child.try_cast::<Button>()
            && button.get_text().to_string().eq_ignore_ascii_case(label)
        {
            return Some(button);
        }
    }
    None
}

fn ui_root(args: &Value) -> Result<Gd<Node>, BridgeError> {
    match optional_str(args, "root") {
        Some(path) => resolve_control(&path),
        None => godot::classes::EditorInterface::singleton()
            .get_base_control()
            .map(|c| c.upcast())
            .ok_or_else(|| BridgeError::Internal("editor has no base control".into())),
    }
}

fn resolve_control(path: &str) -> Result<Gd<Node>, BridgeError> {
    let root = root_window()?;
    root.get_node_or_null(path)
        .ok_or_else(|| BridgeError::NodeNotFound(format!("no control at editor path '{path}'")))
}

fn control_path(node: &Gd<Node>) -> String {
    node.get_path().to_string()
}

fn collect_controls(node: &Gd<Node>, pattern: Option<&str>, class: Option<&str>, out: &mut Vec<Value>) {
    let name = node.get_name().to_string();
    let name_matches = pattern.is_none_or(|p| name.to_lowercase().contains(p));
    let class_matches = class.is_none_or(|c| node.is_class(c));
    if name_matches && class_matches {
        out.push(control_summary(node));
    }
    for child in node.get_children().iter_shared() {
        collect_controls(&child, pattern, class, out);
    }
}

fn control_summary(node: &Gd<Node>) -> Value {
    let mut entry = json!({
        "path": control_path(node),
        "name": node.get_name().to_string(),
        "class": node.get_class().to_string(),
    });
    if let Ok(control) = node.clone().try_cast::<Control>() {
        entry["visible"] = json!(control.is_visible());
        let rect = control.get_global_rect();
        entry["rect"] = json!({
            "x": rect.position.x,
            "y": rect.position.y,
            "width": rect.size.x,
            "height": rect.size.y,
        });
    }
    if let Some(text) = node_text(node) {
        entry["text"] = json!(text);
    }
    entry
}

fn node_text(node: &Gd<Node>) -> Option<String> {
    if let Ok(button) = node.clone().try_cast::<Button>() {
        return Some(button.get_text().to_string());
    }
    if let Ok(line) = node.clone().try_cast::<LineEdit>() {
        return Some(line.get_text().to_string());
    }
    if let Ok(label) = node.clone().try_cast::<godot::classes::Label>() {
        return Some(label.get_text().to_string());
    }
    None
}

fn popup_items(popup: &Gd<PopupMenu>) -> Value {
    let count = popup.get_item_count();
    let items: Vec<Value> = (0..count)
        .map(|index| {
            json!({
                "index": index,
                "id": popup.get_item_id(index),
                "text": popup.get_item_text(index).to_string(),
                "disabled": popup.is_item_disabled(index),
            })
        })
        .collect();
    Value::Array(items)
}

fn option_items(option: &Gd<OptionButton>) -> Value {
    let count = option.get_item_count();
    let items: Vec<Value> = (0..count)
        .map(|index| json!({ "index": index, "id": option.get_item_id(index), "text": option.get_item_text(index).to_string() }))
        .collect();
    Value::Array(items)
}

fn item_list_items(list: &Gd<ItemList>) -> Value {
    let count = list.get_item_count();
    let items: Vec<Value> =
        (0..count).map(|index| json!({ "index": index, "text": list.get_item_text(index).to_string() })).collect();
    Value::Array(items)
}

fn resolve_popup_id(popup: &Gd<PopupMenu>, index: Option<i32>, id: Option<i32>, text: Option<&str>) -> Result<i32, BridgeError> {
    if let Some(id) = id {
        return Ok(id);
    }
    let count = popup.get_item_count();
    if let Some(index) = index {
        if index < 0 || index >= count {
            return Err(BridgeError::InvalidArgs(format!("popup index {index} out of range 0..{count}")));
        }
        return Ok(popup.get_item_id(index));
    }
    if let Some(text) = text {
        for i in 0..count {
            if popup.get_item_text(i).to_string().eq_ignore_ascii_case(text) {
                return Ok(popup.get_item_id(i));
            }
        }
        return Err(BridgeError::InvalidArgs(format!("popup has no item matching '{text}'")));
    }
    Err(BridgeError::InvalidArgs("select_item on a PopupMenu needs one of id, index, or text".into()))
}

struct Connection {
    signal: String,
    target: Option<Gd<Node>>,
    method: String,
    flags: i64,
}

fn persisted_connections(node: &Gd<Node>, signal_filter: Option<&str>) -> Vec<Connection> {
    let mut connections = Vec::new();
    for entry in node.get_signal_list().iter_shared() {
        let name = entry.get(&GString::from("name")).map(|v| v.to_string()).unwrap_or_default();
        if name.is_empty() || signal_filter.is_some_and(|filter| filter != name) {
            continue;
        }
        for row in node.get_signal_connection_list(name.as_str()).iter_shared() {
            let flags = row.get(&GString::from("flags")).and_then(|v| v.try_to::<i64>().ok()).unwrap_or(0);
            if flags & CONNECT_PERSIST == 0 {
                continue;
            }
            let callable = row.get(&GString::from("callable")).and_then(|v| v.try_to::<Callable>().ok());
            let (target, method) = match &callable {
                Some(c) => (
                    c.object().and_then(|o| o.try_cast::<Node>().ok()),
                    c.method_name().map(|m| m.to_string()).unwrap_or_default(),
                ),
                None => (None, String::new()),
            };
            connections.push(Connection { signal: name.clone(), target, method, flags });
        }
    }
    connections
}

