impl NodeFilters {
    /// Parse the shared filter arguments, requiring at least one so a bare
    /// call cannot dump an entire tree unfiltered.
    pub fn from_args(args: &Value) -> Result<NodeFilters, BridgeError> {
        let filters = NodeFilters {
            class: optional_str(args, "class"),
            group: optional_str(args, "group"),
            name_pattern: optional_str(args, "name_pattern"),
        };
        if filters.class.is_none() && filters.group.is_none() && filters.name_pattern.is_none() {
            return Err(BridgeError::InvalidArgs(
                "provide at least one of 'class', 'group', or 'name_pattern'".into(),
            ));
        }
        Ok(filters)
    }

    fn matches(&self, node: &Gd<Node>) -> bool {
        if self.class.as_deref().is_some_and(|class| !node.is_class(class)) {
            return false;
        }
        if self.group.as_deref().is_some_and(|group| !node.is_in_group(group)) {
            return false;
        }
        if self
            .name_pattern
            .as_deref()
            .is_some_and(|pattern| !glob_match(&node.get_name().to_string(), pattern))
        {
            return false;
        }
        true
    }
}

pub fn find_matching(
    start: &Gd<Node>,
    filters: &NodeFilters,
    to_entry: &mut dyn FnMut(&Gd<Node>) -> Value,
) -> Vec<Value> {
    let mut results = Vec::new();
    walk(start, filters, to_entry, &mut results);
    results
}

fn walk(
    node: &Gd<Node>,
    filters: &NodeFilters,
    to_entry: &mut dyn FnMut(&Gd<Node>) -> Value,
    results: &mut Vec<Value>,
) {
    if filters.matches(node) {
        results.push(to_entry(node));
    }
    for child in node.get_children().iter_shared() {
        walk(&child, filters, to_entry, results);
    }
}

fn create(args: &Value) -> Result<Value, BridgeError> {
    let class = require_str(args, "class")?;
    let db = ClassDb::singleton();
    if !db.class_exists(class.as_str()) {
        return Err(BridgeError::InvalidArgs(format!(
            "class '{class}' does not exist in this engine build"
        )));
    }
    if db.is_parent_class(class.as_str(), "Node") {
        return Err(BridgeError::InvalidArgs(format!(
            "'{class}' is a Node; add it to a tree with gd_tree_mutate add_node in a running game, or gd_node_add in the editor, rather than holding it as a free-floating object"
        )));
    }
    if !db.is_parent_class(class.as_str(), "RefCounted") {
        return Err(BridgeError::InvalidArgs(format!(
            "'{class}' is not RefCounted, so a handle could not own the instance and releasing it could not free it. Objects of this kind are obtained from a call and taken with capture, not constructed"
        )));
    }
    if !db.can_instantiate(class.as_str()) {
        return Err(BridgeError::InvalidArgs(format!(
            "class '{class}' cannot be instantiated; it is abstract or engine-internal"
        )));
    }

    let mut object = db
        .instantiate(class.as_str())
        .try_to::<Gd<Object>>()
        .map_err(|_| BridgeError::CallFailed(format!("failed to instantiate '{class}'")))?;
    // Initial properties are applied before the handle exists, so a rejected
    // property name costs the caller a failed call rather than a live handle on
    // a half-configured object.
    let applied = match optional_properties(args)? {
        Some(properties) => apply_properties(&mut object, properties)?,
        None => Vec::new(),
    };

    let actual = object.get_class().to_string();
    let id = handles::mint(object)?;
    Ok(json!({
        "handle": handles::format_handle(id),
        "id": id,
        "class": actual,
        "refcounted": true,
        "properties_set": applied,
        "held": handles::count(),
        "max": handles::MAX_HANDLES,
    }))
}

fn animation_player(args: &Value) -> Result<Gd<AnimationPlayer>, BridgeError> {
    let node_path = require_str(args, "node_path")?;
    let node = resolve_node(&node_path)?;
    let class = node.get_class().to_string();
    node.try_cast::<AnimationPlayer>().map_err(|_| {
        BridgeError::InvalidArgs(format!("node at {node_path} is {class}, not an AnimationPlayer"))
    })
}

fn player_state(player: &Gd<AnimationPlayer>) -> Value {
    let current = player.get_current_animation().to_string();
    if current.is_empty() {
        // The position and length getters push engine errors with no current
        // animation, so report them as null instead of calling them.
        return json!({
            "playing": false,
            "current_animation": Value::Null,
            "position": Value::Null,
            "length": Value::Null,
            "speed_scale": player.get_speed_scale(),
        });
    }
    json!({
        "playing": player.is_playing(),
        "current_animation": current,
        "position": player.get_current_animation_position(),
        "length": player.get_current_animation_length(),
        "speed_scale": player.get_speed_scale(),
    })
}

fn create(args: &Value) -> Result<Value, BridgeError> {
    let mut player = animation_player(args)?;
    let name = require_str(args, "name")?;
    let length = require_f64(args, "length")?;
    if player.has_animation(name.as_str()) {
        return Err(BridgeError::AlreadyExists(format!("animation '{name}' already exists")));
    }
    let tracks = args
        .get("tracks")
        .and_then(Value::as_array)
        .ok_or_else(|| BridgeError::InvalidArgs("'tracks' must be an array".into()))?;

    let mut animation = Animation::new_gd();
    animation.set_length(length as f32);
    if optional_bool(args, "loop").unwrap_or(false) {
        animation.set_loop_mode(LoopMode::LINEAR);
    }
    for track in tracks {
        let path = track
            .get("path")
            .and_then(Value::as_str)
            .ok_or_else(|| BridgeError::InvalidArgs("each track needs a 'path'".into()))?;
        let keys = track
            .get("keys")
            .and_then(Value::as_array)
            .ok_or_else(|| BridgeError::InvalidArgs("each track needs a 'keys' array".into()))?;
        let index = animation.add_track(TrackType::VALUE);
        animation.track_set_path(index, &NodePath::from(path));
        for key in keys {
            let time = key
                .get("time")
                .and_then(Value::as_f64)
                .ok_or_else(|| BridgeError::InvalidArgs("each key needs a numeric 'time'".into()))?;
            let value = key
                .get("value")
                .ok_or_else(|| BridgeError::InvalidArgs("each key needs a 'value'".into()))?;
            animation.track_insert_key(index, time, &json_to_variant(value)?);
        }
    }

    let mut library = match player.get_animation_library("") {
        Some(library) => library,
        None => {
            let library = AnimationLibrary::new_gd();
            let error = player.add_animation_library("", &library);
            if error != godot::global::Error::OK {
                return Err(BridgeError::CallFailed(format!(
                    "add_animation_library failed: {error:?}"
                )));
            }
            library
        }
    };
    let error = library.add_animation(name.as_str(), &animation);
    if error != godot::global::Error::OK {
        return Err(BridgeError::CallFailed(format!("add_animation failed: {error:?}")));
    }
    Ok(json!({ "created": name, "tracks": tracks.len(), "length": length }))
}

fn tree(args: &Value) -> Result<Value, BridgeError> {
    let node_path = require_str(args, "node_path")?;
    let action = require_str(args, "action")?;
    let node = resolve_node(&node_path)?;

    let playback_variant = node.get("parameters/playback");
    if playback_variant.is_nil() {
        return Err(BridgeError::InvalidArgs(format!(
            "node at {node_path} has no 'parameters/playback'; expected an AnimationTree whose root is a state machine"
        )));
    }
    let mut playback = playback_variant.try_to::<Gd<Object>>().map_err(|_| {
        BridgeError::InvalidArgs(format!("'parameters/playback' on {node_path} is not an object"))
    })?;

    match action.as_str() {
        "travel" | "start" => {
            let to = require_str(args, "to")?;
            playback.call(action.as_str(), &[to.to_variant()]);
        }
        "stop" => {
            playback.call("stop", &[]);
        }
        "state" => {}
        other => {
            return Err(BridgeError::InvalidArgs(format!(
                "unknown action '{other}'; expected travel, start, stop, or state"
            )));
        }
    }
    Ok(json!({
        "action": action,
        "current_node": playback.call("get_current_node", &[]).to_string(),
        "playing": playback.call("is_playing", &[]).try_to::<bool>().unwrap_or(false),
        "active": node.get("active").try_to::<bool>().unwrap_or(false),
    }))
}

fn skeleton(args: &Value) -> Result<(Gd<Skeleton3D>, i32), BridgeError> {
    let node_path = require_str(args, "node_path")?;
    let node = resolve_node(&node_path)?;
    let class = node.get_class().to_string();
    let skeleton = node.try_cast::<Skeleton3D>().map_err(|_| {
        BridgeError::InvalidArgs(format!("node at {node_path} is {class}, not a Skeleton3D"))
    })?;
    let bone = match args.get("bone") {
        Some(Value::Number(n)) => {
            let index = n.as_i64().unwrap_or(-1) as i32;
            if index < 0 || index >= skeleton.get_bone_count() {
                return Err(BridgeError::InvalidArgs(format!(
                    "bone index {index} out of range; skeleton has {} bones",
                    skeleton.get_bone_count()
                )));
            }
            index
        }
        Some(Value::String(name)) => {
            let index = skeleton.find_bone(name.as_str());
            if index < 0 {
                return Err(BridgeError::InvalidArgs(format!("no bone named '{name}'")));
            }
            index
        }
        _ => return Err(BridgeError::InvalidArgs("'bone' must be a name or index".into())),
    };
    Ok((skeleton, bone))
}

fn bone_state(skeleton: &Gd<Skeleton3D>, bone: i32) -> Value {
    json!({
        "bone": bone,
        "name": skeleton.get_bone_name(bone).to_string(),
        "position": variant_to_json(&skeleton.get_bone_pose_position(bone).to_variant()),
        "rotation": variant_to_json(&skeleton.get_bone_pose_rotation(bone).to_variant()),
        "scale": variant_to_json(&skeleton.get_bone_pose_scale(bone).to_variant()),
    })
}

fn bus_entry(index: i32) -> Value {
    let server = AudioServer::singleton();
    let effects: Vec<Value> = (0..server.get_bus_effect_count(index))
        .map(|effect_index| {
            let class = server
                .get_bus_effect(index, effect_index)
                .map(|effect| effect.get_class().to_string())
                .unwrap_or_default();
            json!({
                "index": effect_index,
                "class": class,
                "enabled": server.is_bus_effect_enabled(index, effect_index),
            })
        })
        .collect();
    json!({
        "index": index,
        "name": server.get_bus_name(index).to_string(),
        "volume_db": server.get_bus_volume_db(index),
        "mute": server.is_bus_mute(index),
        "solo": server.is_bus_solo(index),
        "bypass_effects": server.is_bus_bypassing_effects(index),
        "send": server.get_bus_send(index).to_string(),
        "effects": effects,
    })
}

fn bus_list() -> Value {
    let count = AudioServer::singleton().get_bus_count();
    let buses: Vec<Value> = (0..count).map(bus_entry).collect();
    json!({ "count": count, "buses": buses })
}

fn resolve_bus(args: &Value) -> Result<i32, BridgeError> {
    let server = AudioServer::singleton();
    match args.get("bus") {
        Some(Value::Number(n)) => {
            let index = n.as_i64().unwrap_or(-1) as i32;
            if index < 0 || index >= server.get_bus_count() {
                return Err(BridgeError::InvalidArgs(format!(
                    "bus index {index} out of range; there are {} buses",
                    server.get_bus_count()
                )));
            }
            Ok(index)
        }
        Some(Value::String(name)) => {
            let index = server.get_bus_index(name.as_str());
            if index < 0 {
                let names: Vec<String> = (0..server.get_bus_count())
                    .map(|i| server.get_bus_name(i).to_string())
                    .collect();
                return Err(BridgeError::InvalidArgs(format!(
                    "no bus named '{name}'; existing buses: {}",
                    names.join(", ")
                )));
            }
            Ok(index)
        }
        _ => Err(BridgeError::InvalidArgs("'bus' must be a name or index".into())),
    }
}

fn bus_set(args: &Value) -> Result<Value, BridgeError> {
    let index = resolve_bus(args)?;
    let mut server = AudioServer::singleton();
    if let Some(volume_db) = optional_f64(args, "volume_db") {
        server.set_bus_volume_db(index, volume_db as f32);
    }
    if let Some(mute) = optional_bool(args, "mute") {
        server.set_bus_mute(index, mute);
    }
    if let Some(solo) = optional_bool(args, "solo") {
        server.set_bus_solo(index, solo);
    }
    if let Some(bypass) = optional_bool(args, "bypass") {
        server.set_bus_bypass_effects(index, bypass);
    }
    if let Some(send) = optional_str(args, "send") {
        if server.get_bus_index(send.as_str()) < 0 {
            return Err(BridgeError::InvalidArgs(format!("send target bus '{send}' does not exist")));
        }
        server.set_bus_send(index, send.as_str());
    }
    Ok(bus_entry(index))
}

fn bus_add(args: &Value) -> Result<Value, BridgeError> {
    let name = require_str(args, "name")?;
    let mut server = AudioServer::singleton();
    if server.get_bus_index(name.as_str()) >= 0 {
        return Err(BridgeError::AlreadyExists(format!("bus '{name}' already exists")));
    }
    server.add_bus();
    let index = server.get_bus_count() - 1;
    server.set_bus_name(index, name.as_str());
    Ok(bus_entry(index))
}

fn bus_remove(args: &Value) -> Result<Value, BridgeError> {
    let index = resolve_bus(args)?;
    if index == 0 {
        return Err(BridgeError::InvalidArgs("the Master bus cannot be removed".into()));
    }
    let name = AudioServer::singleton().get_bus_name(index).to_string();
    AudioServer::singleton().remove_bus(index);
    Ok(json!({ "removed": name, "count": AudioServer::singleton().get_bus_count() }))
}

fn bus_effect(args: &Value) -> Result<Value, BridgeError> {
    let action = require_str(args, "action")?;
    let index = resolve_bus(args)?;
    let mut server = AudioServer::singleton();
    match action.as_str() {
        "add" => {
            let class = require_str(args, "effect_class")?;
            let db = ClassDb::singleton();
            if !db.class_exists(class.as_str()) || !db.is_parent_class(class.as_str(), "AudioEffect")
            {
                return Err(BridgeError::ResourceError(format!(
                    "'{class}' is not an AudioEffect class"
                )));
            }
            let effect = db.instantiate(class.as_str()).try_to::<Gd<AudioEffect>>().map_err(
                |_| BridgeError::ResourceError(format!("failed to instantiate '{class}'")),
            )?;
            server.add_bus_effect(index, &effect);
            Ok(bus_entry(index))
        }
        "remove" => {
            let effect_index = effect_index(args, index)?;
            server.remove_bus_effect(index, effect_index);
            Ok(bus_entry(index))
        }
        "set_enabled" => {
            let effect_index = effect_index(args, index)?;
            let enabled = optional_bool(args, "enabled").unwrap_or(true);
            server.set_bus_effect_enabled(index, effect_index, enabled);
            Ok(bus_entry(index))
        }
        other => Err(BridgeError::InvalidArgs(format!(
            "unknown action '{other}'; expected add, remove, or set_enabled"
        ))),
    }
}

fn effect_index(args: &Value, bus: i32) -> Result<i32, BridgeError> {
    let index = optional_u64(args, "effect_index")
        .ok_or_else(|| BridgeError::InvalidArgs("'effect_index' is required".into()))?
        as i32;
    let count = AudioServer::singleton().get_bus_effect_count(bus);
    if index >= count {
        return Err(BridgeError::InvalidArgs(format!(
            "effect index {index} out of range; bus has {count} effects"
        )));
    }
    Ok(index)
}

struct Stored {
    command: Command,
    font: Option<Gd<Font>>,
    texture: Option<Gd<Texture2D>>,
}

fn load_resource(path: &str, what: &str) -> Result<Gd<Resource>, BridgeError> {
    ResourceLoader::singleton()
        .load(path)
        .ok_or_else(|| BridgeError::InvalidArgs(format!("no {what} at '{path}'")))
}

fn resolve(command: Command) -> Result<Stored, BridgeError> {
    let mut font = None;
    let mut texture = None;
    match &command {
        Command::Text { font: path, .. } => {
            font = match path {
                Some(path) => Some(load_resource(path, "font")?.try_cast::<Font>().map_err(|resource| {
                    BridgeError::InvalidArgs(format!(
                        "'{path}' is {}, not a Font",
                        resource.get_class()
                    ))
                })?),
                // The engine's own example for draw_string uses exactly this
                // pair, so text with no font asked for is the project default
                // rather than an error.
                None => ThemeDb::singleton().get_fallback_font(),
            };
            if font.is_none() {
                return Err(BridgeError::Internal("ThemeDb has no fallback font".into()));
            }
        }
        Command::TextureRect { texture: path, .. } => {
            texture = Some(load_resource(path, "texture")?.try_cast::<Texture2D>().map_err(|resource| {
                BridgeError::InvalidArgs(format!("'{path}' is {}, not a Texture2D", resource.get_class()))
            })?);
        }
        _ => {}
    }
    Ok(Stored { command, font, texture })
}

#[derive(GodotClass)]
#[class(base = Node2D, init)]
struct ConduitCanvasDraw {
    base: Base<Node2D>,
    commands: Vec<Stored>,
}

fn overlay_for(node_path: &str, create: bool) -> Result<Option<Gd<ConduitCanvasDraw>>, BridgeError> {
    let node = resolve_node(node_path)?;
    let mut canvas = node.clone().try_cast::<CanvasItem>().map_err(|node| {
        BridgeError::InvalidArgs(format!(
            "node at {node_path} is {}; drawing needs a CanvasItem (a Node2D or a Control)",
            node.get_class()
        ))
    })?;
    if let Some(existing) = canvas.get_node_or_null(OVERLAY_NAME) {
        return existing
            .try_cast::<ConduitCanvasDraw>()
            .map(Some)
            .map_err(|_| BridgeError::Internal(format!("{OVERLAY_NAME} under {node_path} has an unexpected type")));
    }
    if !create {
        return Ok(None);
    }
    // A Node2D child serves a Control target as well as a Node2D one: its
    // transform is relative to the parent CanvasItem, which for a Control is
    // the top-left of its rect, exactly the origin the Control's own _draw()
    // would use, and the parent's clip_contents clips it the same way.
    let mut overlay = ConduitCanvasDraw::new_alloc();
    overlay.set_name(OVERLAY_NAME);
    canvas.add_child(&overlay);
    Ok(Some(overlay))
}

fn append(overlay: &mut Gd<ConduitCanvasDraw>, commands: Vec<Command>, replace: bool) -> Result<usize, BridgeError> {
    let resolved = commands.into_iter().map(resolve).collect::<Result<Vec<_>, _>>()?;
    let mut bound = overlay.bind_mut();
    let held = if replace { 0 } else { bound.commands.len() };
    if held + resolved.len() > MAX_DRAW_COMMANDS {
        return Err(BridgeError::InvalidArgs(format!(
            "{} commands would exceed the {MAX_DRAW_COMMANDS} an overlay may hold ({held} already held); clear first or draw fewer",
            held + resolved.len()
        )));
    }
    if replace {
        bound.commands.clear();
    }
    bound.commands.extend(resolved);
    let total = bound.commands.len();
    drop(bound);
    overlay.queue_redraw();
    Ok(total)
}

#[godot_api]
impl ConduitEvalSink {
    #[func]
    fn on_done(&mut self, value: Variant) {
        self.value = Some(value);
        self.done = true;
    }
}

pub fn run_source(source: &str, ctx: &FrameContext) -> HandlerOutcome {
    if source.trim().is_empty() {
        return HandlerOutcome::Done(Err(BridgeError::InvalidArgs("'source' must not be empty".into())));
    }

    let mut script = GDScript::new_gd();
    script.set_source_code(&wrap_source(source));
    if script.reload() != godot::global::Error::OK {
        return HandlerOutcome::Done(Err(BridgeError::CallFailed(
            "evaluation source failed to compile; see gd_get_errors for the parser diagnostics".into(),
        )));
    }

    let root = match scene_root() {
        Ok(root) => root,
        Err(err) => return HandlerOutcome::Done(Err(err)),
    };

    let mut holder = Node::new_alloc();
    holder.set_script(&script);
    if !holder.has_method("_conduit_run") {
        holder.queue_free();
        return HandlerOutcome::Done(Err(BridgeError::CallFailed(
            "evaluation script did not attach; see gd_get_errors".into(),
        )));
    }

    let mut root = root;
    root.add_child(&holder);

    let sink = ConduitEvalSink::new_gd();
    holder.connect("_conduit_done", &Callable::from_object_method(&sink, "on_done"));
    holder.call("_conduit_run", &[]);

    HandlerOutcome::Pending(Box::new(EvalPending {
        holder,
        sink,
        deadline_frame: ctx.frame_index.saturating_add(EVAL_DEADLINE_FRAMES),
    }))
}

struct EvalPending {
    holder: Gd<Node>,
    sink: Gd<ConduitEvalSink>,
    deadline_frame: u64,
}

fn inject_key(args: &Value) -> Result<Value, BridgeError> {
    let key = resolve_key(args)?;
    let pressed = pressed_flag(args);
    let physical = args.get("physical").and_then(Value::as_bool).unwrap_or(false);

    let mut event = InputEventKey::new_gd();
    if physical {
        event.set_physical_keycode(key);
    } else {
        event.set_keycode(key);
    }
    event.set_pressed(pressed);
    Input::singleton().parse_input_event(&event);
    Ok(json!({ "injected": true, "device": "key", "pressed": pressed }))
}

fn inject_action(args: &Value) -> Result<Value, BridgeError> {
    let action = require_str(args, "action")?;
    let pressed = pressed_flag(args);
    let mut input = Input::singleton();
    if pressed {
        match args.get("strength").and_then(Value::as_f64) {
            Some(strength) => {
                input.action_press_ex(action.as_str()).strength(strength as f32).done();
            }
            None => input.action_press(action.as_str()),
        }
    } else {
        input.action_release(action.as_str());
    }
    Ok(json!({ "injected": true, "device": "action", "action": action, "pressed": pressed }))
}

