fn node_summary(node: &Gd<Node>) -> Value {
    json!({
        "name": node.get_name().to_string(),
        "class": node.get_class().to_string(),
        "path": node.get_path().to_string(),
    })
}

fn tree_node(node: &Gd<Node>, depth_remaining: u64) -> Value {
    let mut entry = json!({
        "name": node.get_name().to_string(),
        "class": node.get_class().to_string(),
        "path": node.get_path().to_string(),
        "child_count": node.get_child_count(),
    });
    if depth_remaining > 0 {
        let children: Vec<Value> = node
            .get_children()
            .iter_shared()
            .map(|child| tree_node(&child, depth_remaining - 1))
            .collect();
        entry["children"] = Value::Array(children);
    } else if node.get_child_count() > 0 {
        entry["children_truncated"] = json!(true);
    }
    entry
}

pub fn set_time_scale(args: &Value, _ctx: &FrameContext) -> HandlerOutcome {
    HandlerOutcome::Done((|| {
        let scale = args
            .get("scale")
            .and_then(Value::as_f64)
            .ok_or_else(|| BridgeError::InvalidArgs("'scale' is required and must be a number".into()))?;
        if scale < 0.0 {
            return Err(BridgeError::InvalidArgs("'scale' must not be negative".into()));
        }
        Engine::singleton().set_time_scale(scale);
        Ok(json!({ "time_scale": scale }))
    })())
}

pub fn tree_mutate(args: &Value, _ctx: &FrameContext) -> HandlerOutcome {
    HandlerOutcome::Done((|| {
        let op = require_str(args, "op")?;
        match op.as_str() {
            "instantiate" => instantiate(args),
            "add_node" => add_node(args),
            "free" => free(args),
            "reparent" => reparent(args),
            "change_scene" => change_scene(args),
            other => Err(BridgeError::InvalidArgs(format!(
                "unknown op '{other}'; expected instantiate, add_node, free, reparent, or change_scene"
            ))),
        }
    })())
}

fn instantiate(args: &Value) -> Result<Value, BridgeError> {
    let scene_path = require_str(args, "scene_path")?;
    let parent_path = require_str(args, "parent_path")?;
    validate_resource_path(&scene_path)?;

    let mut parent = resolve_node(&parent_path)?;
    let packed = ResourceLoader::singleton()
        .load(scene_path.as_str())
        .and_then(|res| res.try_cast::<PackedScene>().ok())
        .ok_or_else(|| {
            BridgeError::ResourceError(format!("'{scene_path}' is not a loadable PackedScene"))
        })?;
    let mut instance = packed.instantiate().ok_or_else(|| {
        BridgeError::ResourceError(format!("failed to instantiate '{scene_path}'"))
    })?;
    if let Some(name) = optional_str(args, "name") {
        instance.set_name(name.as_str());
    }
    if let Some(properties) = optional_properties(args)? {
        let mut object = instance.clone().upcast::<Object>();
        apply_properties(&mut object, properties)?;
    }
    parent.add_child(&instance);
    Ok(json!({
        "node_path": instance.get_path().to_string(),
        "name": instance.get_name().to_string(),
        "class": instance.get_class().to_string(),
        "scene_path": scene_path,
    }))
}

fn add_node(args: &Value) -> Result<Value, BridgeError> {
    let class = require_str(args, "class")?;
    let parent_path = require_str(args, "parent_path")?;

    let db = ClassDb::singleton();
    if !db.class_exists(class.as_str()) {
        return Err(BridgeError::InvalidArgs(format!(
            "class '{class}' does not exist in this engine build"
        )));
    }
    if !db.is_parent_class(class.as_str(), "Node") {
        return Err(BridgeError::InvalidArgs(format!("class '{class}' is not a Node type")));
    }
    if !db.can_instantiate(class.as_str()) {
        return Err(BridgeError::InvalidArgs(format!("class '{class}' cannot be instantiated")));
    }

    let mut parent = resolve_node(&parent_path)?;
    let mut node = db
        .instantiate(class.as_str())
        .try_to::<Gd<Node>>()
        .map_err(|_| BridgeError::CallFailed(format!("failed to instantiate '{class}'")))?;
    if let Some(name) = optional_str(args, "name") {
        node.set_name(name.as_str());
    }
    if let Some(properties) = optional_properties(args)? {
        let mut object = node.clone().upcast::<Object>();
        if let Err(error) = apply_properties(&mut object, properties) {
            node.queue_free();
            return Err(error);
        }
    }
    parent.add_child(&node);
    Ok(json!({
        "node_path": node.get_path().to_string(),
        "name": node.get_name().to_string(),
        "class": node.get_class().to_string(),
    }))
}

#[godot_api]
impl ConduitHttpSink {
    #[func]
    fn on_completed(&mut self, result: i64, response_code: i64, headers: PackedStringArray, body: PackedByteArray) {
        self.result = result;
        self.response_code = response_code;
        self.headers = headers;
        self.body = body;
        self.done = true;
    }
}

pub fn http_request(args: &Value, ctx: &FrameContext) -> HandlerOutcome {
    let prepared: Result<PreparedRequest, BridgeError> = (|| {
        let url = require_str(args, "url")?;
        if !url.starts_with("http://") && !url.starts_with("https://") {
            return Err(BridgeError::InvalidArgs("'url' must start with http:// or https://".into()));
        }
        let method = parse_http_method(optional_str(args, "method").as_deref().unwrap_or("GET"))?;
        let header_lines = parse_headers(args)?;
        let body = optional_str(args, "body").unwrap_or_default();
        let timeout_s = optional_f64(args, "timeout_s").unwrap_or(HTTP_DEFAULT_TIMEOUT_S).clamp(1.0, HTTP_MAX_TIMEOUT_S);
        let max_body = optional_u64(args, "max_body_bytes").unwrap_or(HTTP_DEFAULT_MAX_BODY as u64) as usize;
        Ok(PreparedRequest { url, method, header_lines, body, timeout_s, max_body })
    })();
    let request = match prepared {
        Ok(v) => v,
        Err(e) => return HandlerOutcome::Done(Err(e)),
    };

    let root = match scene_root() {
        Ok(root) => root,
        Err(err) => return HandlerOutcome::Done(Err(err)),
    };

    let mut headers = PackedStringArray::new();
    for line in &request.header_lines {
        headers.push(&GString::from(line.as_str()));
    }

    let mut node = HttpRequest::new_alloc();
    let mut root = root;
    root.add_child(&node);
    node.set_timeout(request.timeout_s);

    let sink = ConduitHttpSink::new_gd();
    node.connect("request_completed", &Callable::from_object_method(&sink, "on_completed"));

    let err = node
        .request_ex(request.url.as_str())
        .custom_headers(&headers)
        .method(request.method)
        .request_data(request.body.as_str())
        .done();
    if err != godot::global::Error::OK {
        node.queue_free();
        return HandlerOutcome::Done(Err(BridgeError::NetworkError(format!(
            "http request could not start: {err:?}"
        ))));
    }

    HandlerOutcome::Pending(Box::new(HttpPending {
        node,
        sink,
        url: request.url,
        max_body: request.max_body,
        deadline_frame: ctx.frame_index.saturating_add(HTTP_DEADLINE_FRAMES),
    }))
}

struct WsConn {
    peer: Gd<WebSocketPeer>,
    inbox: VecDeque<Value>,
    dropped: u64,
}

fn ws_connect(args: &Value) -> HandlerOutcome {
    let url = match require_str(args, "url") {
        Ok(url) => url,
        Err(err) => return HandlerOutcome::Done(Err(err)),
    };
    if !url.starts_with("ws://") && !url.starts_with("wss://") {
        return HandlerOutcome::Done(Err(BridgeError::InvalidArgs("'url' must start with ws:// or wss://".into())));
    }
    let at_capacity = WS_CONNS.with(|conns| conns.borrow().len() >= WS_MAX_CONNECTIONS);
    if at_capacity {
        return HandlerOutcome::Done(Err(BridgeError::NetworkError(format!(
            "too many open websocket connections (max {WS_MAX_CONNECTIONS}); close one first"
        ))));
    }

    let mut peer = WebSocketPeer::new_gd();
    let err = peer.connect_to_url(url.as_str());
    if err != godot::global::Error::OK {
        return HandlerOutcome::Done(Err(BridgeError::NetworkError(format!(
            "websocket connect to {url} could not start: {err:?}"
        ))));
    }

    let id = WS_NEXT_ID.with(|next| {
        let mut next = next.borrow_mut();
        let id = *next;
        *next += 1;
        id
    });
    WS_CONNS.with(|conns| {
        conns.borrow_mut().insert(id, WsConn { peer, inbox: VecDeque::new(), dropped: 0 });
    });

    HandlerOutcome::Pending(Box::new(WsConnectPending { id, url, deadline: Instant::now() + WS_CONNECT_TIMEOUT }))
}

