fn fetch_driver_handles(rd: &Gd<RenderingDevice>) -> RawDriverHandles {
    RawDriverHandles {
        instance: rd.get_driver_resource(DriverResource::VULKAN_INSTANCE, Rid::Invalid, 0) as u64,
        physical_device: rd.get_driver_resource(DriverResource::VULKAN_PHYSICAL_DEVICE, Rid::Invalid, 0) as u64,
        device: rd.get_driver_resource(DriverResource::VULKAN_DEVICE, Rid::Invalid, 0) as u64,
        queue_family: rd.get_driver_resource(DriverResource::VULKAN_QUEUE_FAMILY_INDEX, Rid::Invalid, 0) as u32,
        queue: rd.get_driver_resource(DriverResource::VULKAN_QUEUE, Rid::Invalid, 0) as u64,
    }
}

impl VulkanContext {

    pub fn new() -> Result<VulkanContext, VulkanError> {
        let rd = RenderingServer::singleton()
            .get_rendering_device()
            .ok_or(VulkanError::RenderingDeviceUnavailable)?;

        let entry = unsafe { ash::Entry::load() }
            .map_err(|_| VulkanError::EntryLoadFailed)?;

        let raw_handles = fetch_driver_handles(&rd);
        let adopted_handles = unsafe {adopt_driver_handles(&entry, &raw_handles)};

        let command_pool = create_command_pool(&adopted_handles.device, raw_handles.queue_family)
            .map_err(|_| VulkanError::CommandPoolCreationFailed)?;

        Ok(VulkanContext {
            instance: adopted_handles.instance,
            physical_device: adopted_handles.physical_device,
            device: adopted_handles.device,
            queue_family: raw_handles.queue_family,
            queue: std::sync::Mutex::new(adopted_handles.queue),
            command_pool: command_pool
        })
    }

    pub fn shutdown(&mut self) {
        godot_print!("Shuting down vulkan context...");

        unsafe {
            self.device.destroy_command_pool(self.command_pool, None);
        };
    }
}

#[godot_api]
impl DogSoapAgent {
	#[func]
	pub fn make_plan(&mut self) {
		if self.data.get_type() != VariantType::OBJECT {
			godot_error!("Agent data was not set to a DogSoapAgentData resource.");
			return;
		}
		let data = self.data.to::<Gd<Resource>>();
		self.brain.update_thoughts(None);
		let mut goal: Goal = Goal::new(data.get("goal_name").to::<GString>());
		for string in data
			.get("goal_conditions")
			.to::<Array<GString>>()
			.iter_shared()
		{
			match self.brain.thoughts.parse_condition(&string) {
				Ok(condition) => {
					goal.push_condition(condition);
				}

				Err(error) => {
					godot_error!("Failed to parse condition `{string}`: {error}");
				}
			}
		}
		match self.planner.plan(
			&self.brain.thought_state,
			&goal,
			usize::try_from(data.get("max_actions").to::<i64>().max(0)).unwrap_or(0),
		) {
			Ok(plan) => {
				let mut plan_result: Array<AnyArray> = Array::new();
				for index in 0..plan.len() {
					let Some(action) = self.planner.get_plan_action(&plan, index) else {
						godot_warn!(
							"Problem interpreting plan: No planned action for plan action index {index}."
						);
						continue;
					};
					let mut plan_action: Array<AnyArray> = Array::new();
					for executor in &action.executors {
						let mut plan_action_executor: Array<GString> = Array::new();
						plan_action_executor.push(&executor.0.to_godot_owned());
						plan_action_executor.push(&executor.1.to_godot_owned());
						plan_action.push(plan_action_executor.upcast_any_array());
					}
					plan_result.push(plan_action.upcast_any_array());
				}
				self.plan = plan_result.to_variant();
			}

			Err(error) => {
				godot_warn!("Failed to plan `{}`: {error}", goal.name);
			}
		}
	}
}

