#[derive(Subcommand)]
pub enum NodeAction {
    /// Spawns a specific 3D node at the given position and adds it to the main scene
    #[command(add = marker::Risky, add = marker::Experimental)]
    Spawn {
        /// If set, set the name of the instantiated node
        #[arg(short, long)]
        name: Option<String>,

        /// The 3D position to spawn the scene at
        #[arg(short, long, value_name = POSITION_ARG_HELP)]
        pos: Option<PositionArg>,

        /// The path of the scene, e.g. `res://main.tscn`
        #[arg(add = ArgValueCompleter::new(scene_file_completer))]
        #[arg(trailing_var_arg = true, allow_hyphen_values = true, num_args = 1.., required = true)]
        path: Vec<String>,
    },

    /// Find a node (or nodes) that matches the given pattern or type
    Find {
        /// The `NodePath` to search for. If empty, find all nodes.
        #[arg(add = ArgValueCompleter::new(nodepath_completer))]
        #[arg(trailing_var_arg = true, allow_hyphen_values = true, num_args = 0..)]
        nodepath_needle: Vec<String>, //                           ^^^^^^^^^^^^^^ <- optional

        /// If set, returns *all* nodes that match the given pattern, instead of just the first one
        #[arg(short, long)]
        all: bool,

        /// If set, returns the full `NodePath` of the node, instead of the node itself
        #[arg(short, long)]
        path: bool,

        /// If set, returns only nodes that inherit the given type
        #[arg(short, long = "type", value_name = "TYPE")]
        typ: Option<String>,
    },

    /// List all nodes
    List,

    /// Reload a node (or nodes) from disk (note - this only works for nodes that are the root node of a scene file stored on disk)
    Reload {
        /// The `NodePath` to search for.
        #[arg(add = ArgValueCompleter::new(nodepath_completer))]
        #[arg(trailing_var_arg = true, allow_hyphen_values = true, num_args = 1.., required = true)]
        nodepath_needle: Vec<String>,

        /// If set, reloads *all* nodes that match the given pattern, instead of just the first one
        #[arg(short, long)]
        all: bool,
    },

    /// Find a node by its instance ID
    FromId { instance_id: NonZeroU64 }, // <-- no need to use i64 here, since negative instance id means its RefCounted, and nodes can never be RefCounted

    /// Wait for any signal to come in on a node, and return the signal's data
    Signals {
        /// The `NodePath` to search for.
        #[arg(add = ArgValueCompleter::new(nodepath_completer))]
        #[arg(trailing_var_arg = true, allow_hyphen_values = true, num_args = 1.., required = true)]
        nodepath_needle: Vec<String>,
    },
}

#[tracing::instrument(skip_all)]
pub(super) async fn toggle_visibility_task(mut self: AsyncGd<Self>) {
    loop {
        tracing::debug!("waiting for tilde press...");

        let Ok(_) = self
            .gd_mut()
            .signals()
            .console_toggle_requested()
            .to_fallible_future()
            .await
        else {
            tracing::warn!("console was freed, stopping toggle_visibility_task...");
            return;
        };

        let was_visible = self.bind().nodes.canvas_layer.is_visible();
        self.bind_mut().nodes.canvas_layer.set_visible(!was_visible);

        tracing::debug!("console visibility toggled");

        if !was_visible {
            self.bind_mut().nodes.line_edit.grab_focus(); // so we can start typing immediately
        } else {
            // Note - we no longer use a SVC, so this may no longer be needed.
            // When you hide the CanvasLayer, the line_edit fires its `hidden` signal.
            // So, it seems to recognize whenever it gets hidden, so it should be smart enough to release focus on its own.
            self.bind_mut().nodes.line_edit.release_focus();
        }
    }
}

#[tracing::instrument(skip_all)]
pub(super) async fn toggle_autocomplete_visibility_task(self: AsyncGd<Self>) {
    let line_edit = self.gd().bind().nodes.line_edit.clone(); // fast clone
    let mut autocomplete = self.gd().bind().nodes.autocomplete_label.clone(); // fast clone

    // This loops between two states:
    // 1. Show the autocomplete label when the textbox gains focus
    // 2. Hide the autocomplete label when the textbox loses focus

    loop {
        let Ok(_) = line_edit
            .signals()
            .focus_entered()
            .to_fallible_future()
            .await
        else {
            return; // Line edit was freed
        };

        autocomplete.show();

        let Ok(_) = line_edit
            .signals()
            .focus_exited()
            .to_fallible_future()
            .await
        else {
            return; // Line edit was freed
        };

        autocomplete.hide();
    }
}

#[tracing::instrument(skip_all)]
pub(super) async fn autocomplete_task(mut self: AsyncGd<Self>) {
    let rx = self.bind().autocomplete_chan.1.clone();

    // How many autocompletion slots to display in the UI.
    // Note: 150 is pushing it in terms of performance, this causes a ~30ms lag spike every time you type.
    // To increase performance, you can make enable threaded mode on the RichTextLabel.
    // However, this will increase code complexity,
    // since draw_slots() will then need to become async to handle the delayed computation.
    let max_slots = 150;

    let mut prev_line = String::new();

    loop {
        let mut got_new_line = false;

        // For history search, we select on two futures here:
        // 1. wait_and_retain_latest_message_async
        // 2. wait_until(dirty_slots == true)
        // Then, dirty_slots is set to true once the user pressed Ctrl+R.
        // Otherwise, it will still show stale autocomplete slots, if the user switches to search mode.
        let line = tokio::select! {
            Some(line) = wait_and_retain_latest_message_async(&rx) => { got_new_line = true; line },
            () = wait_until(|| self.bind().suggestions.dirty) => prev_line, // use line from previous iteration of the loop
            else => {
                // Entering this branch means wait_and_retain_latest_message_async returned None.
                // That means the channel `rx` was closed.
                tracing::warn!("autocomplete_chan dropped, stopping autocomplete_task...");
                break;
            }
        };

        prev_line = line.clone();

        // Depending on the console mode, we gather specific kinds of autocomplete slots and store them here.
        if self.bind().get_search_mode_enabled() {
            let mut slots = self.handle_history_search(&line);

            truncate_slots(&mut slots, max_slots);

            let index = match &self.bind().suggestions.slots {
                SuggestionSlots::Search(_, i) if !got_new_line => *i, // same slot kind + line, so remember previous index
                _ => None, // different slot kind or line, so reset to None
            };
            self.bind_mut().suggestions.slots = SuggestionSlots::Search(slots, index);
        } else {
            let mut slots = if let Some(clap) = line.strip_prefix(CLAP_COMMAND_PREFIX) {
                // If line starts with :, evaluate the rest with clap autocomplete
                self.handle_autocomplete_clap(clap)
            } else {
                // Else, use GDScript autocomplete.
                self.handle_autocomplete_gdscript(&line)
            };

            truncate_slots(&mut slots, max_slots);

            let line_edit_text = self.bind().nodes.line_edit.get_text().to_string();

            let index = match &self.bind().suggestions.slots {
                SuggestionSlots::Autocomplete(_, i, _) if !got_new_line => *i, // same slot kind + line, so remember previous index
                _ => None, // different slot kind or line, so reset to None
            };
            self.bind_mut().suggestions.slots =
                SuggestionSlots::Autocomplete(slots, index, line_edit_text);
        }

        // Since autocomplete_slots has been changed, we need to re-draw the slots.
        self.bind_mut().draw_slots();

        // Finally, set dirty slots to false, so we don't re-update every frame.
        self.bind_mut().suggestions.dirty = false;
    }
}

#[tracing::instrument(skip_all)]
pub(super) async fn eval_job_without_channel(
    self: AsyncGd<Self>,
    expression: JobExpressionInner,
) -> Result<Variant, Arc<JobError>> {
    let job = JobInner {
        expression,
        reply_tx: flume::unbounded().0, // dummy channel
        use_timeout: USE_EVAL_TIMEOUT.try_get().unwrap_or_else(|_| {
            tracing::warn!("USE_EVAL_TIMEOUT wasn't set - defaulting to true");
            true
        }),
    };

    self.eval_job(job).await
}

#[tracing::instrument(skip_all)]
pub(super) fn eval_job(
    mut self: AsyncGd<Self>,
    job: JobInner,
) -> Pin<Box<dyn Future<Output = Result<Variant, Arc<JobError>>>>> {
    Box::pin(async move {
        let reply_tx = job.reply_tx.clone();

        // Evaluate the expression while measuring execution time.
        let timeout = if job.use_timeout {
            MaybeTimeout::from(self.bind().timeout)
        } else {
            MaybeTimeout::NoTimeout
        };

        // Uses Tokio timeout, since we want to timeout based on real time.
        let fut = timeout.run_with_timeout(
            USE_EVAL_TIMEOUT.scope(job.use_timeout, self.clone().eval(job.expression)), // fast clone
        );

        // Determine what kind of future we're dealing with.
        let (execution_time, async_wait_time, eval_result) = {
            let mut initial_busy_time = Duration::default();

            let future_kind = profile!("classify_future", classify_future(fut), |t| {
                initial_busy_time = t
            });
            match future_kind {
                FutureKind::Sync(result) => (initial_busy_time, None, result), // no idle time
                FutureKind::Async(fut) => {
                    // Indicate to user/watch we're waiting for an async call.
                    let _ = reply_tx.send(JobEvent::WaitingAsync);

                    future_timing::timed(fut) // measure idle + busy time of the future
                        .await
                        .into_parts()
                        .pipe(|(timing, result)| {
                            // Note - future_timing does NOT measure the busy time BEFORE the first poll.
                            // See documentation for timing.idle().
                            // So, we need to add it manually here...
                            (
                                timing.busy() + initial_busy_time,
                                Some(timing.idle()),
                                result,
                            )
                        })
                }
            }
        };

        // Replace the tokio Elapsed error type by TimeoutAsync.
        let mut eval_result = eval_result
            .map_err(|_| JobError::TimeoutAsync(timeout.unwrap_duration())) // safe unwrap
            .flatten();

        let mut signal_wait_time = None;

        // Check if it's a signal - in that case, await it (with timeout)
        let mut signal_timed_out = false;
        if let Ok(eval_result) = eval_result.as_mut()
            && let Ok(signal) = eval_result.try_to::<Signal>()
        {
            // Indicate to user/watch we're waiting for a signal.
            let _ = job.reply_tx.send(JobEvent::WaitingSignal);

            // Wait for the signal while measuring time spent waiting.
            let signal_result = profile!(
                "await_signal",
                timeout.run_with_timeout(await_untyped_signal(signal)).await,
                |time| { signal_wait_time = Some(time) }
            );

            match signal_result {
                Ok(signal_result) => {
                    // Overwrite the original signal with the result from the signal.
                    *eval_result = VarArray::from(&signal_result[..]).to_variant()
                }
                Err(_ /* timed out */) => {
                    signal_timed_out = true;
                }
            }
        };

        if signal_timed_out {
            eval_result = Err(JobError::TimeoutSignal(timeout.unwrap_duration())); // safe unwrap
        }

        // Need this, otherwise we can't clone the error, since we're now sending it to 2 places (channel + return type).
        let eval_result = eval_result.map_err(Arc::new);

        // Prepare result by stringifying the Variant. (We can't send the Variant itself, since it's not Send)
        let result = JobResult {
            result: JobResultData::prepare_job_result(
                &eval_result,
                &mut self.bind

#[tracing::instrument(skip_all)]
pub(super) fn handle_autocomplete_gdscript(
    self: &mut AsyncGd<Self>,
    line: &str,
) -> Vec<AutocompleteSlot> {
    if is_lockdown_enabled() {
        // In lockdown mode, do not show GDScript autocomplete at all
        return vec![];
    }
    let mut line = line.to_owned();

    let reduced = reduce_expression(&line);
    let (haystack, _call_depth) = self.bind().resolve_expression_autocomplete(&reduced);
    line = reduced.remaining;

    let slots = {
        let mut temp = haystack
            .iter()
            .filter_map(|slot @ AutocompleteSlot { name, .. }| {
                let name_lower = name.to_lowercase();
                let line_lower = line.to_lowercase();

                if name_lower.starts_with(&line_lower) {
                    Some((true, slot.clone())) // true = perfect match
                } else if name_lower.contains(&line_lower) {
                    Some((false, slot.clone()))
                } else {
                    None
                }
            })
            .collect::<Vec<_>>();

        // Deprioritize classes/built in types, since we have so many of them
        // Remember, lower number = higher priority
        temp.sort_by_cached_key(|(perfect_match, AutocompleteSlot { name, typ, .. })| {
            let rank = match typ {
                // Deprioritize methods starting with an underscore,
                // generally they're not useful and you don't want to call them directly.
                AutocompleteType::Method(_, _) if name.starts_with("_") => 25,
                AutocompleteType::Method(_, _) => 20,
                AutocompleteType::UtilityFunc(_, _) => 30, // show after "real" methods
                AutocompleteType::Property(_) => 10, // Highest priority, since they are less common
                AutocompleteType::Class {
                    is_global,
                    is_abstract,
                } => {
                    if *is_global {
                        40 // globals have higher priority
                    } else if *is_abstract {
                        100 // abstract classes have lower priority, since they're hardly useful
                    } else {
                        60
                    }
                }
                AutocompleteType::BuiltInType => 80,
                AutocompleteType::Signal(_, _) => 70,
                AutocompleteType::Clap => 0,
            };
            (
                if *perfect_match { 0 } else { 1 }, // Show perfect matches first
                rank,                               // Then order by rank
                name.to_lowercase(),                // If same rank, sort alphabetically
            )
        });

        temp
    };

    slots.into_iter().map(|(_, b)| b).collect()
}

fn get_classes_and_globals(&self, indentation: usize) -> Vec<AutocompleteSlot> {
    let (global_names, _) = &**self.singletons;
    let global_set = global_names.as_slice().iter().collect::<IndexSet<_>>();

    ClassDb::singleton()
        .get_class_list()
        .as_slice()
        .iter()
        .map(|name| {
            let is_abstract =
                !ClassDb::singleton().can_instantiate(&StringName::from(&name.to_string()));

            let is_global = global_set.contains(name);

            AutocompleteSlot {
                name: name.to_string(),
                indentation,
                help: None,
                typ: AutocompleteType::Class {
                    is_abstract,
                    is_global,
                },
            }
        })
        .collect::<Vec<_>>()
}

fn get_variables(&self, indentation: usize) -> Vec<AutocompleteSlot> {
    self.get_vars()
        .iter()
        .map(|(name, value)| AutocompleteSlot {
            name: name.to_string(),
            indentation,
            help: None,
            typ: AutocompleteType::Property(VariantTypePair {
                // Get the value's type
                typ: value.get_type(),
                class_name: StringName::from(
                    // Get the value's class name, if it is an Object
                    &value
                        .try_to::<Gd<Object>>()
                        .map(|obj| obj.get_class())
                        .unwrap_or_default(),
                ),
            }),
        })
        .collect::<Vec<_>>()
}

#[tracing::instrument(skip(self))]
pub(super) fn handle_history_search(self: &mut AsyncGd<Self>, line: &str) -> Vec<SearchSlot> {
    let history_unique = {
        let mut history = self.bind().history.clone();
        history.reverse(); // reverse it to retain only the LATEST duplicates, instead of the first
        let mut seen = HashSet::new();
        history.retain(|slot| seen.insert(slot.command.trim().to_owned())); // trailing whitespace should not be counted as unique
        history.reverse(); // reverse it again to retain only the LATEST duplicates, instead of the first
        history
    };

    // basic search alg
    let mut result: Vec<_> = history_unique
        .iter()
        .filter_map(|hist| {
            let cmd_lower = hist.command.to_lowercase();
            let line_lower = line.to_lowercase();
            if cmd_lower.starts_with(&line_lower) {
                Some((
                    SearchSlot {
                        name: hist.command.clone(),
                        timestamp: hist.timestamp,
                        success: hist.success,
                    },
                    true, // perfect match
                ))
            } else if cmd_lower.contains(&line_lower) {
                Some((
                    SearchSlot {
                        name: hist.command.clone(),
                        timestamp: hist.timestamp,
                        success: hist.success,
                    },
                    false,
                ))
            } else {
                None
            }
        })
        .collect();

    result.sort_by_key(|(slot, perfect_match)| {
        // First sort by perfect match, then by date, then by string length
        (
            if *perfect_match { 0 } else { 1 },
            Reverse(slot.timestamp),
            slot.name.len(),
        )
    });
    result.into_iter().map(|(slot, _)| slot).collect()
}

#[tracing::instrument(skip_all)]
pub(super) fn handle_autocomplete_clap(
    self: &mut AsyncGd<Self>,
    line: &str,
) -> Vec<AutocompleteSlot> {
    let mut args: Vec<OsString> = split_console_whitespace(line).map(OsString::from).collect();

    if line.is_empty() || line.ends_with(' ') {
        args.push("".into()); // why do we need this again?
    }

    let arg_index = args.len().saturating_sub(1); // completing last token
    let mut cmd = MainCommand::command();

    // Inject custom subcommands, so they appear in the completion list
    cmd = self.inject_subcommands(cmd);

    // We occasionally get a panic here in `clap`, so catch it.
    // Type this to trigger the panic: :watch signals --style  -u icon
    let completions = panic::catch_unwind(AssertUnwindSafe(|| {
        Ok(complete(
            &mut cmd,
            args,
            arg_index,
            env::current_dir().ok().as_deref(), // None = current dir, for file path completions
        )?)
    }))
    .map_err(panic_payload_to_eyre)
    .flatten();

    // The length of the input rounded down to the nearest space
    let rounded_input_length = second_to_last_word_end(line); // arcane black magic but okay

    completions
        .tap_err(|err| tracing::warn!(?err, "clap autocomplete failed - returning empty list"))
        .unwrap_or_default() // if completion fails, use empty vec
        .into_iter()
        .map(|completion| AutocompleteSlot {
            name: completion.get_value().to_string_lossy().to_string(),
            indentation: rounded_input_length,
            help: completion.get_help().map(|style| style.to_string()),
            typ: AutocompleteType::Clap,
        })
        .collect()
}

