    match self {
        AutocompleteTargetObj::Object(obj) => obj.get_signal_list(), // similar to obj.get_method_list()
        AutocompleteTargetObj::UninstantiableObject(class_name) => {
            ClassDb::singleton().class_get_signal_list(class_name)
        }
