pub(crate) fn inject_subcommands(self: &AsyncGd<Self>, mut cmd: Command) -> Command {
    for (name, CustomCommand { help, .. }) in &self.bind().commands {
        cmd = cmd.subcommand(
            Command::new(name.to_string())
                .about(help) // note - about() covers both short help (-h) and long help (--help)
                .trailing_var_arg(true)
                .arg(
                    Arg::new("args") // Add a single variadic argument that allows 0 or more entries
                        .num_args(0..)
                        .action(ArgAction::Append)
                        .allow_hyphen_values(true)
                        .value_name("ARGS"),
                ),
        )
    }
    cmd
}

#[tracing::instrument(skip_all)]
pub(super) async fn eval_clap(
    self: AsyncGd<Self>,
    clap: &str,
) -> Result<Variant, EvalClapError> {
    let split = split_console_whitespace(clap);

    // Clap has some commands specific to repls: see:
    // - https://docs.rs/clap/latest/clap/struct.Command.html#method.multicall
    // - https://docs.rs/clap/latest/clap/struct.Command.html#method.no_binary_name

    let mut cmd = MainCommand::command();
    cmd = self.inject_subcommands(cmd);

    // TODO cloning Command here may be slow - check profiler!
    // Needed due to new riskiness check
    let matches = cmd.clone().try_get_matches_from(split)?;

    if let Some((name, matches)) = matches.subcommand() {
        // clone here prevents long bind.
        // do NOT use if let x = y.bind().z.clone() or it will panic with double borrow
        let cmd_slot = self.bind().commands.get(name).cloned();

        if let Some(CustomCommand { expression, .. }) = cmd_slot {
            // Parse arguments
            let args: Vec<String> = matches
                .get_many::<String>("args")
                .unwrap_or_default()
                .cloned() // &String -> String
                .collect();

            return Ok(self.handle_custom_command(expression, args).await?);
        }
    }

    // If lockdown mode is enabled, reject risky commands
    if is_lockdown_enabled() {
        let (is_risky, risky_cmd) = check_marker::<marker::Risky>(&cmd, &matches);
        if is_risky {
            return Err(EvalClapError::Lockdown { risky_cmd });
        }
    }

    let args = MainCommand::from_arg_matches(&matches)?;

    Ok(self.handle_clap_command(args).await?)
}

pub(super) async fn handle_custom_command(
    self: &AsyncGd<Self>,
    custom_expression: CustomCommandExpression,
    args: Vec<String>,
) -> EyreResult<Variant> {
    let expression = match custom_expression {
        CustomCommandExpression::String(string) => JobExpressionInner::String(string),
        CustomCommandExpression::Callable(func) => {
            let args_len = args.len();

            let closure = move || -> JobExpressionCallableResult {
                let func = func.clone(); // needed otherwise it becomes FnOnce

                // Note; do not parse the strings into Variant::number etc, leave that up the user.
                let callable_args = args
                    .iter()
                    .map(|s| Variant::from(s.clone()))
                    .collect::<VarArray>();

                Box::pin(async move {
                    // NOTE: If called on an invalid Callable then no error is printed, and NIL is returned.
                    // i think the problem is the closure is destroyed when run_12345() exits, so the callable refers to a destroyed closure
                    // so closures may not work, since they get destroyed too early, but bind() does seem to work, so use that instead
                    if !func.is_valid() {
                        return Err(eyre!("Callable is not valid - did it get freed?"));
                    }

                    // Warning - If called with fewer arguments than expected, callv will crash Godot (without triggering UB).
                    // However, if you pass too many, the rest will be ignored.
                    // This is convenient, because variadic functions only return the amount of non-variadic arguments they take.
                    // So, check with < instead of !=, otherwise we can't call variadic functions properly.

                    // TODO - this does NOT work properly with arguments that can have default values, e.g.
                    //      > combine(name: String, greeting: String = "Hello", ...extras: Array)
                    // Because func.get_argument_count() will return 2, not 1, so you can never take advantage of the default argument.

                    // Note that get_argument_count returns 1 for print() (you would expect 0 because variadic but eh).
                    // Also, luckily get_argument_count does seem to work properly for bound functions.
                    // I haven't tested bind + variadic + optional args yet though.
                    let callable_arg_count = func.get_argument_count();
                    if args_len < callable_arg_count {
                        return Err(eyre!(
                            "Callable expected at least {} arguments, but got only {}",
                            callable_arg_count,
                            args_len
                        ));
                    }

                    // TODO we can do basic typechecking here maybe?
                    // if callable.object() is Some you can lookup callable.get_method() in object's ClassDB (or get_method_list()) to get type information
                    // note - the argument list may not line up 1-to-1 with get_method_list().
                    // e.g. if you have a method  Object.foo(a, b) and do Object.foo.bind("a") then you may need to skip the first arg in Object.get_method_list("foo")

                    Ok(func.callv(&callable_args))
                })
            };

            JobExpressionInner::Callable(OpaqueDebug(Rc::new(closure)))
        }
    };

    let result = self
        .clone()
        .eval_job_without_channel(expression)
        .with_tracy_non_continuous_frame("handle_custom_command")
        .await?;

    Ok(result)
}

pub(super) trait ClapSubAction {
    async fn handle(self, console: AsyncGd<CrabConsole>) -> Result<Variant, Report>;
}

#[tracing::instrument(skip_all)]
pub async fn eval(self: AsyncGd<Self>, code: JobExpressionInner) -> Result<Variant, JobError> {
    {
        match code {
            JobExpressionInner::String(code) => {
                // Filter all control chars here and newlines
                // Do this here since using eval_blocking you can send arbitrary bad things into this method.
                let code: String = code
                    .chars()
                    .map(|c| if c == '\t' { ' ' } else { c }) // tab becomes space
                    .filter(|c| !c.is_control())
                    .collect();
                //TODO doesn't work for ZWJ (zero width joiner)
                //TODO maybe trim the start of the string as well?
                //TODO use a newtype SanitizedString in all descendent methods to encode this information in the type system

                #[cfg(feature = "tracy")]
                get_tracy_client_or_panic().message(&format!("Evaluating: {code}"), 60); // tracing::info causes massive delay here

                // TODO this tracing call may be slow/cause crashes in mem_test?
                tracing::trace!(code, "Evaluating...");

                // If code starts with :, evaluate the rest with clap instead of Godot's Expression.
                if let Some(clap) = code.strip_prefix(CLAP_COMMAND_PREFIX) {
                    self.eval_clap(clap).await.map_err(JobError::EvalClap)
                } else {
                    // This is not async - if it returns a signal, it will be awaited later
                    self.eval_godot_advanced(&code).map_err(JobError::EvalGodot)
                }
            }
            JobExpressionInner::Callable(OpaqueDebug(callable)) => self
                .eval_callable(|| callable()) // <-- this turns the `Rc<dyn Fn() -> ...>` into `impl Fn() -> ...`
                .await
                .map_err(JobError::EvalGodot),
        }
    }
    .tap(|result| {
        #[cfg(feature = "tracy")]
        {
            use crabbyconsole_misc::reflection::SafeDebug as _;
            let result_str = result.safe_debug(); // <-- Safe now, even if result is a Callable or GDScriptNativeObject

            // Warning: limit to 65k chars max, otherwise Tracy hard-crashes your program!
            let too_large = result_str.len() >= (u16::MAX as usize);
            let msg = format!(
                "Evaluated to: {}",
                if too_large {
                    format!(
                        "<evaluation result too large
(was {} characters, but the limit is {})>",
                        result_str.len(),
                        u16::MAX
                    )
                } else {
                    result_str
                }
            );

            get_tracy_client_or_panic().message(&msg, 60);
        }

        // Use the variable when `tracy` is disabled, to avoid unused variable warning.
        #[cfg(not(feature = "tracy"))]
        let _ = result;
    })
}

#[tracing::instrument(skip_all)]
pub async fn eval_callable(
    self: AsyncGd<Self>,
    callable: impl Fn() -> JobExpressionCallableResult,
) -> Result<Variant, EvalGodotError> {
    let result = callable().await?;

    Ok(result)
}

pub(super) fn get_root(self: &AsyncGd<Self>) -> Gd<Window> {
    self.gd().get_tree().get_root().expect("no root node")
}

pub(super) fn find_nodes_variant(self: &AsyncGd<Self>, pattern: &str) -> Variant {
    Variant::from(
        self.find_nodes_by_pattern(pattern)
            .into_iter()
            .map(Variant::from)
            .collect::<Vec<_>>(),
    )
}

pub(super) fn find_node_by_pattern(
    self: &AsyncGd<Self>,
    pattern: &str,
) -> EyreResult<Gd<Node>> {
    // Let's just always use find_nodes, since it has more functionality anyway

    self.find_nodes_by_pattern(pattern)
        .into_iter()
        .next()
        .with_context(|| format!("no nodes found with given pattern `{pattern}`"))
}

pub(super) fn find_nodes_by_pattern(self: &AsyncGd<Self>, pattern: &str) -> Vec<Gd<Node>> {
    let root = self.get_root();

    root.find_children_ex(pattern)
        .owned(false) // Note - by default, find_children only returns nodes that have a valid `owner` set.
        .done()
        .iter_shared()
        .collect::<Vec<_>>()
}

pub(super) fn find_node_by_nodepath_needle(
    self: &AsyncGd<Self>,
    nodepath_needle: &str,
    typ: Option<&str>,
) -> EyreResult<Gd<Node>> {
    // Note - in the future, you may want to do more advanced sorting to ensure we return perfect matches first.
    // E.g. right now, if you search for `/root/`, you will NOT get the root node, which is problematic.

    self.find_nodes_by_nodepath_needle(nodepath_needle, typ)
        .into_iter()
        .next()
        .ok_or_else(|| {
            let type_hint = if let Some(typ) = typ {
                format!("(and type `{typ}`)")
            } else {
                String::new()
            };
            eyre!("no node found with given NodePath needle: `{nodepath_needle}` {type_hint}")
        })
}

pub(super) fn find_nodes_by_nodepath_needle(
    self: &AsyncGd<Self>,
    nodepath_needle: &str,
    typ: Option<&str>,
) -> Vec<Gd<Node>> {
    let root = self.get_root();

    // Only prepend the root node if its type matches.
    let prepend_root_node: bool = typ.is_none_or(|typ| root.is_class(typ));

    prepend_root_node
        .then_some(root.clone().upcast())
        .into_iter() // Empty iterator if None, else [Gd<Node>]
        .chain(
            root.find_children_ex("*")
                .owned(false)
                .type_(typ.unwrap_or("")) // empty type = all types allowed
                .done()
                .iter_shared(),
        )
        .filter(|n| n.get_path().to_string().contains(nodepath_needle))
        .collect()
}

pub fn resolve_position_2d(
    self: &AsyncGd<Self>,
    position: &PositionArg,
) -> EyreResult<Vector2> {
    match position {
        // TODO add PositionArg::Variable(string)?
        PositionArg::Coords2D(xy) => Ok(*xy),
        PositionArg::Coords3D(xyz) => {
            Err(eyre!("expected a 2D position, but got a 3D one ({xyz})"))
        }
        PositionArg::Cursor => Ok(get_viewport().get_mouse_position()), // See ScriptExecutionContext::cursor_2d
        PositionArg::Camera => Ok(get_camera_2d()
            .ok_or_eyre("no Camera2D in scene")?
            .get_global_position()),
        PositionArg::Node(pattern) => self
            .find_node_by_pattern(pattern)
            .and_then(|node| {
                node.try_cast::<Node2D>()
                    .map(Resolvable2D::from)
                    .or_else(|node| node.try_cast::<Control>().map(Resolvable2D::from))
                    .map_err(|node| {
                        eyre!("found node `{node}` but it wasn't a Control or Node2D")
                    })
            })
            .map(|node| node.get_global_position()),
    }
}

pub fn resolve_position_3d(
    self: &AsyncGd<Self>,
    position: &PositionArg,
) -> EyreResult<Vector3> {
    // Do this lazily
    let cam3d = || get_camera_3d().ok_or_eyre("no Camera3D in scene");

    match position {
        PositionArg::Coords2D(xy) => {
            Err(eyre!("expected a 3D position, but got a 2D one ({xy})"))
        }
        PositionArg::Coords3D(xyz) => Ok(*xyz),
        PositionArg::Cursor => Ok(get_cursor_world_position(3.0, cam3d()?)),
        PositionArg::Camera => Ok(cam3d()?.get_global_position()),
        PositionArg::Node(pattern) => self
            .find_node_by_pattern(pattern)
            .and_then(|node| {
                node.try_cast::<Node3D>()
                    .map_err(|node| eyre!("found node `{node}` but it wasn't a Node3D"))
            })
            .map(|node| node.get_global_position()),
    }
}

pub(super) fn find_by_pattern_infallible(
    self: &AsyncGd<Self>,
    pattern: &str,
    all: bool,
) -> Vec<Gd<Node>> {
    let mut targets = vec![];
    if all {
        targets.append(&mut self.find_nodes_by_pattern(pattern));
    } else if let Ok(x) = self.find_node_by_pattern(pattern) {
        targets.push(x);
    };
    targets
}

pub(super) fn find_by_nodepath_needle_infallible(
    self: &AsyncGd<Self>,
    pattern: &str,
    typ: Option<&str>,
    all: bool,
) -> Vec<Gd<Node>> {
    let mut targets = vec![];
    if all {
        targets.append(&mut self.find_nodes_by_nodepath_needle(pattern, typ));
    } else if let Ok(x) = self.find_node_by_nodepath_needle(pattern, typ) {
        targets.push(x);
    };
    targets
}

enum Resolvable2D {
    Node2D(Gd<Node2D>),
    Control(Gd<Control>),
}

impl From<Gd<Node2D>> for Resolvable2D {
    fn from(value: Gd<Node2D>) -> Self {
        Resolvable2D::Node2D(value)
    }
}

impl From<Gd<Control>> for Resolvable2D {
    fn from(value: Gd<Control>) -> Self {
        Resolvable2D::Control(value)
    }
}

async fn handle(self, console: AsyncGd<CrabConsole>) -> Result<Variant, Report> {
    let (w, h) = (340, 180); // if h > 200 it will be scaled down by JobResultData::add_to

    match self {
        ref pa @ PlotAction::Line {
            ref time,
            ref y_range,
            ref threshold,
            ref metrics,
            ref rate,
            ref expression,
        } => {
            // TODO maybe trim the start of the expression too? To increase cache hit rate
            let expression: Arc<str> = Arc::from(expression.join(" "));
            let pa = pa.clone();

            // Evaluate the expression
            let value = console
                .clone() // fast clone
                .eval_job_without_channel(JobExpressionInner::String(Arc::clone(&expression)))
                .with_tracy_non_continuous_frame("eval_job_plot")
                .await?;

            // Try to convert its result to f32
            let value_numeric = value.try_to_relaxed::<f32>().map_err(|e| e.into_erased())?;

            let data = LINE_PLOT_DATA.with_borrow_mut(|cache| {
                // TODO maybe pass Arc<str> here and store the Arc in the data cache as key
                gather_data(expression.to_string(), value_numeric, *time, cache)
            });

            let x_range = Some(-time..nn(0.0));

            let plot =
                get_or_create_rate_limited_plot(pa, w, h, *rate, console, |source_rgb| {
                    profile!(draw_line_plot(
                        source_rgb,
                        // TODO `source_rgb` can't reuse slot.borrow_mut().0.buffer_mut() here
                        // it assumes the thing is RGBA8, not RGB8.
                        // so we do need to reallocate this buffer every time, oh well
                        // maybe make a second buffer inside of it? `buffer_rgb8` or sth?
                        // and then add a method buffer_rgb8_mut()? and pass it to draw_line_plot?
                        data,
                        (w, h),
                        x_range,
                        y_range.clone(),
                        threshold.clone(),
                        *metrics,
                    ))
                })?;
            Ok(Variant::from(plot))
        }
        ref pa @ PlotAction::Histo {
            ref x_range,
            ref y_range,
            ref threshold,
            ref metrics,
            ref rate,
            ref expression,
        } => {
            let expression: Arc<str> = Arc::from(expression.join(" "));
            let pa = pa.clone();

            let time = NotNan::from(5_u16); // TODO pass `time` in via PlotAction::Histo?

            // Evaluate the expression
            let value = console
                .clone() // fast clone
                .eval_job_without_channel(JobExpressionInner::String(Arc::clone(&expression)))
                .with_tracy_non_continuous_frame("eval_job_plot")
                .await?;

            // Try to convert its result to f32
            let value_numeric = value.try_to_relaxed::<f32>().map_err(|e| e.into_erased())?;

            let data = HISTO_PLOT_DATA.with_borrow_mut(|cache| {
                // TODO maybe pass Arc<str> here and store the Arc in the data cache as key
                gather_data(expression.to_string(), value_numeric, time, cache)
            });

            let plot =
                get_or_create_rate_limited_plot(pa, w, h, *rate, console, |source_rgb| {
                    profile!(draw_histo_plot(
                        source_rgb,
                        data,
                        (w, h),
                        x_range.clone(), // These clones are kinda wasteful, since `pa` already contains them. Maybe pass them into the closure?
                        y_range.clone(), // So the arg list becomes |source_rgb, x_range, y_range, threshold|?
                        threshold.clone(),
                        *metrics,
                    ))
                })?;

fn get_or_create_rate_limited_plot(
    pa: PlotAction,
    w: u32,
    h: u32,
    rate: NotNan<f32>,
    console: AsyncGd<CrabConsole>,
    draw_plot: impl FnOnce(&mut [u8]) -> Result<(), Report>,
) -> Result<Gd<ImageTexture>, Report> {
    // At this point, we need to call get_or_create_texture BEFORE calling draw_line_plot.
    // That way, we can determine whether or not we're currently rate limited.
    // If not, we just do the current logic. If we are rate limited, however, we DO NOT CALL draw_line_plot AT ALL.
    // Instead, we just return whatever the cache returned (however, if the cache is empty, we need to call draw_line_plot anyway).
    // To make this less complex we return some kind of Guard struct in get_or_create_texture().
    // It returns whether or not we were rate limited, so you can do sth like this:
    // let guard = get_or_create_texture(). if guard.rate_limited() { return guard.texture } else {
    //      let plot = draw_line_plot(guard.buffer)
    //      guard.upload()
    // }
    // so guard.upload() actually takes the vec<u8> buffer and puts it in the Texture2D on the gpu.
    // Beware: I think guard needs to hold a &reference to the StreamingTexture, so we may get lifetime problems.
    // May need to sprinkle a Rc<> in there to fix that.
    //
    // essentially the idea is that get_or_create_texture is split up into two halves A (lookup) and B (upload).
    // then we need to call them in this order: A -> draw_line_plot -> B
    // because B can't happen before draw_line_plot, since we can't upload the texture if we don't have it yet.
    // but A can't happen after draw_line_plot either, because then the rate-limit-check happens after we've already generated the plot,
    // defeating the entire point of the rate limiter.
    // Returning a guard struct is prob the best way to fix this.

    let now = Instant::now();
    let slot = profile!(
        "get_or_create_texture",
        get_or_create_texture(w, h, pa, now, rate, console)
    );

    let rate_limited = now < slot.borrow().1 + Duration::from_secs_f32(1.0 / *slot.borrow().2); // `rate` should not be zero methinks so probably safe
    if rate_limited {
        // generating plots too fast, so re-use the cached one.
        // we do write down the data point though, so we don't lose it
        return Ok(Gd::clone(&slot.borrow().0.texture));
    } else {
        let mut source_rgb = profile!(vec![0u8; (w * h * 3) as usize]); // <- 0.02-0.04ms: TODO can we cache this? as part of the below scheme? i think we can!

        draw_plot(&mut source_rgb)?;

        // We now have the plot's texture data in `source_rgb`: upload it to the gpu
        {
            let mut slot = slot.borrow_mut();
            profile!(slot.0.update_and_upload_rgb8(&source_rgb)); // ~0.2-0.3ms
            slot.1 = Instant::now(); // write down last update time // -> do not use `now`, it will be slightly off here, since draw_line_plot takes some time to generate + upload
            slot.2 = rate; // update the target frequency
        }
    }

    Ok(Gd::clone(&slot.borrow().0.texture))
}

pub struct StreamingTexture {
    pub(super) image: Gd<Image>,
    pub(super) texture: Gd<ImageTexture>, // Maybe store InstanceId here? (that acts as a WeakRef, but godot-rust discourages using it), and get rid of the auto-expiry entirely?
    pub(super) buffer: PackedByteArray,   /* rgba8 */
    // Actually that may not work - maybe add :plot clear instead of auto-expiry?
    // Because auto-expiry is risky and can disconnect texture connections if you don't update the plot in a while
    pub(super) width: u32,
    pub(super) height: u32,
    // TODO add buffer_rgb8? so we can re-use the buffer? may not be worth it
}

fn get_or_create_texture(
    w: u32,
    h: u32,
    key: PlotAction,
    now: Instant,
    rate: NotNan<f32>,
    mut console: AsyncGd<CrabConsole>, // TODO maybe just pass the cache instead of the console, but that requires making it a Rc<RefCell<Cache>> probably because we need &mut
) -> PlotTextureCacheSlot {
    // Using the texture cache makes get_or_create_texture about 1.78x faster (n=~500)
    // So 0.39ms -> 0.21ms on average
    // On PC it was 2.4x faster (n=~2000)
    // So 0.27ms -> 0.11ms
    // Huge improvement!
    if !PLOT_USE_TEXTURE_CACHE_FLAG.get() {
        // not using the cache, so create a new texture every frame (slow).
        // (this will convert rgb8 -> rgba8 btw in Rust)
        return Rc::new(RefCell::new((StreamingTexture::new(w, h), now, nn(0.0))));
    }

    // try to get texture from cache
    {
        let mut console = console.bind_mut();
        let entry = console.plot_texture_cache.get(&key);
        if let Some(entry) = entry {
            // return it - update it later
            return Rc::clone(entry);
        }
    }

    // no value in the cache - create a new one
    let new_entry = Rc::new(RefCell::new((
        StreamingTexture::new(w, h),
        now, // TODO `now` will be slightly off here, since StreamingTexture::new takes some time to generate
        rate,
    )));
    let new_texture = Gd::clone(&new_entry.borrow().0.texture); // fast clone
    console
        .bind_mut()
        .plot_texture_cache
        .insert(key, Rc::clone(&new_entry));

    {
        let size = new_texture.get_size();
        let memory_usage_mb = if new_texture.get_format() == Format::RGBA8 {
            Some((size.x * size.y * 4.0).round() / 1024.0 / 1024.)
        } else {
            None // don't feel like implementing this logic for like 50 image formats
        };

        // keep this info statement here - it serves as a warning for when you accidentally create a lot of plots every frame
        tracing::info!(
            %new_texture,
            %size,
            vram_usage = %memory_usage_mb
                .map(|mb| format!("{:.2} MB", mb))
                .unwrap_or_else(|| "???".into()),
            "created fresh new plot texture",

        );
    }

    new_entry
}

impl ClapSubAction for SmoothArgs {
    async fn handle(self, console: AsyncGd<CrabConsole>) -> Result<Variant, Report> {
        let Self { speed, expression } = self;

        thread_local! {

            /// TODO you should move this cache into CrabConsole!
            /// Otherwise, if this holds a Object-type, it will panic when you shut down the game (due to running Gd's destructor after Godot has already exited).
            static SMOOTH_CACHE: BoxedCache<Arc<str>, Rc<Variant>> = RefCell::new(Box::new(
                Cache::builder()
                    .time_to_live(Duration::from_mins(10))
                    .build()
            ));
        }

        // TODO maybe trim the start of the expression too? To increase cache hit rate
        let expression: Arc<str> = Arc::from(expression.join(" "));

        let new = console
            .clone() // fast clone
            .eval_job_without_channel(JobExpressionInner::String(Arc::clone(&expression)))
            .with_tracy_non_continuous_frame("eval_job_smooth")
            .await?;

        // Check if expression was present in cache
        let old = SMOOTH_CACHE.with(|c| c.borrow_mut().get(&expression).cloned());

        let Some(old) = old else {
            // Insert in cache
            // Variant cloned here, not sure how slow that is:                  vvvvv
            SMOOTH_CACHE.with(|c| c.borrow_mut().insert(expression, Rc::new(new.clone())));

            tracing::info!("inserted in smooth cache");

            // Return unsmoothed if we don't have a cached entry
            return Ok(new);
        };

        // TODO this does not work properly in slow motion
        let delta = console.gd().get_process_delta_time();

        // for extra smoothness you can do :smooth :smooth randf() -> looks almost like perlin noise
        let smoothed =
            variant_smooth(&old, &new, speed, delta).ok_or_else(|| error_wrong_type(&new))?;

        // Insert in cache
        // Variant cloned here, not sure how slow that is:                       vvvvv
        SMOOTH_CACHE.with(|c| c.borrow_mut().insert(expression, Rc::new(smoothed.clone())));

        Ok(smoothed)
    }
}

#[derive(Debug, Clone)]
pub struct VrState {
    sprite: Gd<Sprite3D>,
    sprite_parent: Gd<Node>,
    // vr_camera: Gd<Camera3D>, // don't store this, panics if you switch scenes and then call any vr command, use get_camera_3d() instead
    // viewport: Gd<SubViewport>, // seems unneeded?
    follow_camera: bool,
}

pub fn enter_vr(mut console: AsyncGd<CrabConsole>) -> Result<Variant, Report> {
    // If we already are in VR mode, bail out
    ensure!(
        console.bind().vr_state.is_none(),
        "can't enable VR mode - already enabled"
    );

    let cam_xr = find_camera_xr(&console)
        .ok_or_eyre("no XRCamera3D nor Camera3D in the scene, can't enter VR mode")?;

    // Create 3D plane to put the console on
    let mut sprite = Sprite3D::new_alloc();
    let mut viewport = SubViewport::new_alloc();
    viewport.set_size(Vector2i::new(1280, 720)); // 540p may be too small, doesn't fit a lot of text
    viewport.set_transparent_background(true);

    // Add it to the root
    let mut sprite_parent = console.get_root();
    sprite_parent.add_child(&viewport);

    let vp_tex: Gd<ViewportTexture> = viewport.get_texture().expect("no viewport texture");

    // Scale multiplier (reflects `world_scale` in your XROrigin3D)
    let world_scale = XrServer::singleton().get_world_scale() as f32;
    tracing::info!(world_scale);

    // Align quad to camera (with scale set to ONE, regardless of `scale_mult`)
    //
    // Note - XROrigin3D and its child node XRCamera3D aren't intended to be scaled like a Node3D.
    // Instead, users are expected to change the `world_scale` prop instead.
    // However, in case the user doesn't know about this, we orthonormalize the camera transform anyway.
    // See https://github.com/godotengine/godot/issues/101241#issuecomment-3166116746
    sprite.set_global_transform(Transform3D::new(
        cam_xr.get_global_transform().basis.orthonormalized(),
        cam_xr.get_global_position(),
    ));
    // Put the console at 0.6 meters distance from the camera
    sprite.translate_object_local(Vector3::new(0., 0., -0.6) * world_scale);
    sprite.set_texture(&vp_tex);

    // Check Sprite3D docs to see the default values of all draw flags
    sprite.set_draw_flag(DrawFlags::DISABLE_DEPTH_TEST, true);
    sprite.set_draw_flag(DrawFlags::DOUBLE_SIDED, true); // may be default already but eh
    sprite.set_render_priority(127); // 127 = highest prio, to ensure it draws on top of all other transparent things

    // Calculate pixel size based on height, so it can become wider without the text becoming smaller
    // Note - do not touch `sprite.scale`, we want `:cons vr scale` to be unaffected by `scale_mult`
    let world_height = 0.3 * world_scale; // meters 
    let tex_height = vp_tex.get_height();
    sprite.set_pixel_size(world_height / tex_height as f32);

    console.get_root().add_child(&sprite);

    // Now reparent ourselves to be inside the viewport
    console.gd_mut().reparent(&viewport);

    // Focus the textbox here so we can type in VR
    console.bind_mut().nodes.line_edit.grab_focus();

    // TODO maybe do DisplayServer.virtual_keyboard_show() here to show the VR keyboard?

    // Start waiting for keyboard events
    console
        .bind_mut()
        .bound_task()
        .new({
            let mut viewport = viewport.clone(); // fast clone
            async move |_| {
                loop_over_unhandled_input_events(|e| {
                    if let Ok(key) = e.try_cast::<InputEventKey>() {
                        // forward to viewport
                        tracing::debug!(?key);
                        viewport.push_input(&key);
                    }

                    ControlFlow::Continue::<()>(())
                })
                .await;
            }
        })
        .spawn();

    // Store VrState to indicate VR mode has been activated
    console.bind_mut().vr_state = Some(VrState {
        sprite,
        sprite_parent: sprite_parent.upcast(),
        follow_camera: false,
    });

    // Last, but certainly not least, make the console actually visible:
    console.bind_mut().nodes.canvas_layer.show();

    Ok(Variant::from("VR mode enabled."))
}

#[tracing::instrument(skip_all)]
fn find_camera_xr(console: &AsyncGd<CrabConsole>) -> Option<Gd<Camera3D>> {
    let all_nodes = console.find_nodes_by_nodepath_needle("", None);

    let mut candidates = all_nodes
        .iter()
        .filter_map(|node| {
            // fast clone
            if let Ok(cam_xr) = node.clone().try_cast::<XrCamera3D>() {
                if cam_xr.is_current() {
                    Some((cam_xr.upcast(), 0)) // highest rank
                } else {
                    Some((cam_xr.upcast(), 1)) // high rank
                }
            } else if let Ok(cam_3d) = node.clone().try_cast::<Camera3D>() {
                if cam_3d.is_current() {
                    Some((cam_3d.upcast(), 2)) // low rank
                } else {
                    Some((cam_3d.upcast(), 3)) // lowest rank
                }
            } else {
                // node is not XrCamera3D nor Camera3D, so skip it
                None
            }
        })
        .collect::<Vec<(Gd<Camera3D>, i32)>>();
    candidates.sort_by_key(|(_, rank)| *rank);
    tracing::info!(?candidates);
    let mut candidates = candidates.into_iter().map(|(cam, _)| cam); // throw rank away, only used for sorting

    // If no candidates, next() will return None
    candidates.next()
}

async fn handle(self, mut console: AsyncGd<CrabConsole>) -> Result<Variant, Report> {
    match self {
        VrAction::Enter => enter_vr(console), // TODO this can be removed now? it does give better errors than CrabbyConsole.enter_vr() though

        VrAction::Scale { scale } => {
            // fast clone
            let Some(VrState {
                sprite: mut sprite3d,
                ..
            }) = console.bind().vr_state.clone()
            else {
                bail!("please enable VR mode first");
            };

            sprite3d.set_scale(Vector3::ONE * scale);
            Ok(Variant::from(sprite3d.get_scale()))
        }

        VrAction::Follow { follow } => {
            // TODO maybe prioritize OverrideCamera3D here? for debugging?
            let cam_xr = find_camera_xr(&console)
                .ok_or_eyre("no XRCamera3D nor Camera3D in the scene, can't enter VR mode")?;

            let Some(VrState {
                sprite,
                sprite_parent,

                follow_camera: old_value,
                ..
            }) = &mut console.bind_mut().vr_state
            else {
                bail!("please enable VR mode first");
            };

            let new_value = match follow {
                BoolArg::Set(value) => value,
                BoolArg::Toggle => !*old_value,
            };

            match (*old_value, new_value) {
                (true, false) => {
                    // unparent sprite from camera, and put it back to its original parent
                    sprite
                        .reparent_ex(&*sprite_parent)
                        .keep_global_transform(true)
                        .done();
                }
                (false, true) => {
                    // parent sprite to camera
                    sprite
                        .reparent_ex(&cam_xr)
                        .keep_global_transform(true)
                        .done();
                }
                _ => {
                    // nothing to do, value didn't change
                }
            }

            // Store the new value inside of vr_state
            *old_value = new_value;

            Ok(Variant::from(if new_value {
                "Following camera"
            } else {
                "Unfollowing camera"
            }))
        }
        VrAction::Expand => {
            // Move the vsplitter all the way down
            console.bind_mut().nodes.vsplitter.set_split_offset(999_999); // don't use i32::MAX here, or it overflows

            Ok(Variant::nil())
        }
    }
}

fn make_signal_callable(
    signal_name: String,
    obj: Gd<Object>,
    path: Option<WatchablePath>,
    use_instance_id: bool,
) -> Rc<dyn Fn() -> JobExpressionCallableResult> {
    // Looking nodes up by ID should be faster than by NodePath.
    // Drawback: does not work if you reload the scene...
    // Update: get_node doesn't work if you reload the scene either, since it doesn't recognize the node was swapped out...
    // So no more signals come in... solution: call `:watch refresh`
    // NOTE: that will be fixed once we make await_untyped_signal detect the node being freed while waiting for it!
    // because then all watches will fail at the same time, causing them to re-evaluate, so it will re-connect the signals to the fresh node

    Rc::new(move || {
        let result = try {
            // We can do the callable in two ways: either:
            // 1. Return a future that resolves when the signal is emitted
            // 2. Return a signal immediately, which will then be awaited later by the evaluator
            // I think 2 is better, but I'm not sure, we can try both
            // 2 is more consistent with how it used to work before JobExpression::Callable existed

            let target_obj = if let Some(WatchablePath::NodePath(path)) = &path
                && !path.is_empty()  // <-- Warning! `path` can be empty if the Node is not in the tree!
                && !use_instance_id
            {
                // We can only use `get_node()` if the watchable object is a Node! Else, fallback to `instance_from_id()`.

                get_root()
                    .try_get_node_as::<Node>(path)
                    .ok_or_else(|| {
                        eyre!("failed to watch signal `{signal_name}` - node not found at `{path}`")
                    })?
                    .upcast::<Object>()
            } else {
                // Important: Gd::clone will panic if the object was freed, so we need to check its validity BEFORE cloning it.
                if !obj.is_instance_valid() {
                    Err(eyre!(
                        "failed to watch signal `{signal_name}` - target object was freed"
                    ))?; // Using ? on Err means: always bail out 
                }
                // Now it should be safe to clone it.
                obj.clone()
            };

            Variant::from(Signal::from_object_signal(&target_obj, &signal_name))
        };
        Box::pin(async move { result })
    })
}

#[derive(Clone)] // cheap clone
pub(super) enum Watchable {
    Node(Gd<Node>),
    Resource(Gd<Resource>),
    Object(Gd<Object>),
}

impl Watchable {
    pub(super) fn get_name(&self) -> String {
        match self {
            Watchable::Node(node) => node.get_name().to_string(),
            Watchable::Resource(res) => {
                let name = res.get_name();
                if name.is_empty() {
                    self.get_inner().get_class().to_string() // fallback to class name, if no name 
                } else {
                    name.to_string()
                }
            }
            Watchable::Object(obj) => obj.get_class().to_string(), // <-- Object has no Name, so just use its type for now
        }
    }

    pub(super) fn get_path(&self) -> Option<WatchablePath> {
        match self {
            Watchable::Node(node) => Some(WatchablePath::NodePath(node.get_path())), // <-- warning - this can be empty if the node is not in the tree
            Watchable::Resource(res) => Some(WatchablePath::FilePath(res.get_path().to_string())),
            Watchable::Object(_) => None,
        }
    }

    pub(super) fn get_inner(&self) -> Gd<Object> {
        match self {
            Watchable::Node(node) => node.clone().upcast(),
            Watchable::Resource(res) => res.clone().upcast(),
            Watchable::Object(obj) => obj.clone(),
        }
    }

    pub(super) fn get_kind(&self) -> &str {
        match self {
            Watchable::Node(_) => "node",
            Watchable::Resource(_) => "resource",
            Watchable::Object(_) => "object",
        }
    }
}

#[tracing::instrument(skip_all)]
pub(super) async fn load_history_task(mut self: AsyncGd<Self>) {
    let history_file_path = Self::get_history_file_path();

    // Now using TOKIO_RUNTIME.spawn instead of TOKIO_RUNTIME.enter here to prevent panics
    let result: impl Future<Output = Result<eyre::Result<_>, JoinError>> =
        TOKIO_RUNTIME.spawn({
            let history_file_path = history_file_path.clone(); // <-- satisfy borrow checker
            async move {
                let history_file_path = history_file_path?; // Bail out if failed to create history file

                let file_tokio = tokio::fs::OpenOptions::new()
                    .read(true)
                    .open(&history_file_path)
                    .await?;
                let file_std = file_tokio.try_into_std().map_err(|_| {
                    std::io::Error::other("failed to convert tokio file handle to std")
                })?;

                let mut reader = csv::Reader::from_reader(file_std);

                // Note - you may be able to use tokio::task::block_in_place here instead
                let entries = tokio::task::spawn_blocking(move || -> eyre::Result<_> {
                    info_span!("load_history_task[spawn_blocking]").in_scope(|| {
                        profile!("load_history_task[spawn_blocking]", {
                            let mut entries = vec![];
                            for result in reader.deserialize() {
                                let entry: HistoryEntry = result?;
                                entries.push(entry);
                            }
                            Ok(entries)
                        })
                    })
                })
                .await
                .expect("tokio task panicked")?;

                Ok(entries)
            }
        });

    match profile!(result.await.expect("tokio task panicked")) {
        Ok(entries) => {
            tracing::info!(
                "read {} history entries from {history_file_path:?}",
                entries.len()
            );
            self.bind_mut().history = OpaqueDebug(entries);
        }
        Err(err) => {
            tracing::warn!(?err, "failed to read history - using default");

            // use default history entries
            let default_history = Self::get_default_history_entries();
            self.bind_mut().history = OpaqueDebug(default_history.clone());

            // now write them back to disk
            for entry in default_history {
                self.bind_mut().append_history_to_disk(entry);
            }
        }
    }
}

#[tracing::instrument(skip_all)]
pub(super) async fn save_history_task(self: AsyncGd<Self>) {
    let rx = self.bind().history_chan.1.clone();

    let history_file_path = Self::get_history_file_path();

    while let Ok(history) = rx.recv_async().await {
        // Now using TOKIO_RUNTIME.spawn instead of TOKIO_RUNTIME.enter here to prevent panics
        let result: impl Future<Output = Result<eyre::Result<_>, JoinError>> = TOKIO_RUNTIME
            .spawn({
                let history_file_path = history_file_path.clone(); // <-- satisfy borrow checker
                async move {
                    let history_file_path = history_file_path?; // Bail out if failed to create history file

                    // Only write csv headers if 1. the history file doesn't exist or 2. it exists, but is empty
                    // Note - this relies on OR short-circuiting, so don't introduce a metadata var:
                    let write_headers = !Path::new(&history_file_path).exists()
                        || tokio::fs::metadata(&history_file_path).await?.len() == 0;

                    let file_tokio = tokio::fs::OpenOptions::new()
                        .create(true)
                        .append(true)
                        .open(&history_file_path)
                        .await?;
                    let file_std = file_tokio.try_into_std().map_err(|_| {
                        std::io::Error::other("failed to convert tokio file handle to std")
                    })?;
                    let mut writer = csv::WriterBuilder::new()
                        .has_headers(write_headers)
                        .from_writer(file_std);

                    // These two calls are blocking so use spawn_blocking
                    // Note - you may be able to use tokio::task::block_in_place here instead
                    tokio::task::spawn_blocking(move || -> eyre::Result<()> {
                        info_span!("save_history_task[spawn_blocking]").in_scope(|| {
                            writer.serialize(history)?;
                            writer.flush()?;
                            Ok(())
                        })
                    })
                    .await
                    .expect("tokio task panicked")?;

                    Ok(())
                }
            });

        match profile!(result.await.expect("tokio task panicked")) {
            Ok(()) => tracing::debug!("appended an entry to {history_file_path:?}"),
            Err(err) => tracing::error!(?err, "failed to write history"),
        }
    }

    tracing::warn!("save_history_task ended");
}

impl CrabConsole {
    /// Adds the default CrabConsole input maps (skipping them if the user redefined them manually)
    #[tracing::instrument(skip_all)]
    pub(super) fn setup_input_maps() {
        let actions: &[InputActionDef] = &[
            InputActionDef {
                name: "crabbyconsole_toggle",
                physical_keys: &[Key::QUOTELEFT], // `
                control: false,
            },
            InputActionDef {
                name: "crabbyconsole_search_toggle",
                physical_keys: &[Key::R],
                control: true,
            },
            InputActionDef {
                name: "crabbyconsole_interrupt",
                physical_keys: &[Key::C],
                control: true,
            },
        ];

        let mut input_map = InputMap::singleton();

        for action in actions {
            let action_name = StringName::from(action.name);

            if input_map.has_action(&action_name) {
                tracing::info!(action = action.name, "input map already added, skipping");
                continue;
            }

            input_map.add_action(&action_name);

            for &key in action.physical_keys {
                let mut event = InputEventKey::new_gd();
                event.set_physical_keycode(key);
                event.set_command_or_control_autoremap(action.control);
                input_map.action_add_event(&action_name, &event);
            }

            tracing::info!(
                action = action.name,
                keys = ?action.physical_keys,
                control = action.control,
                "added input map"
            );
        }
    }
}

impl JobResultData {
    pub(super) fn prepare_job_result(
        eval_result: &Result<Variant, Arc<JobError>>,
        cache: &mut Cache<InstanceId, Gd<Texture2D>>,
    ) -> Result<(Self, JobResultType), Arc<JobError>> {
        eval_result
            .as_ref()
            .map(|var| {
                let class_name = {
                    if let Ok(obj) = var.try_to::<Gd<Object>>() {
                        Some(obj.get_class().to_string()) // Use Rust string here because it's thread safe
                    } else {
                        None
                    }
                };
                (
                    Self::new(var, cache),
                    JobResultType {
                        typ: var.get_type(),
                        class: class_name,
                    },
                )
            })
            .map_err(Arc::clone)
    }
}

impl JobResultData {
    pub(super) fn add_to(
        &self,
        mut rt: Gd<RichTextLabel>,
        cache: &mut Cache<InstanceId, Gd<Texture2D>>,
    ) {
        match self {
            JobResultData::String(string) => rt.add_text(string), // ignores bbcode
            JobResultData::Image(id) => {
                // This doesn't work, since instance get freed too early
                // let img = Gd::<Texture2D>::try_from_instance_id(*id);
                // Instead, use a cache:
                let img = cache.get(id).cloned();

                if let Some(img) = img {
                    let img_h = img.get_height();
                    let max_h = 200;
                    let img_str = &format!("{img:?}");

                    rt.add_image_ex(&img)
                        .height(img_h.min(max_h))
                        .tooltip(img_str) // tooltip only works in the console, not in the watch panel
                        .color(Color::from_rgba(1., 1., 1., 0.8)) // slightly transparent
                        .done(); // don't make the image taller than it needs to be
                } else {
                    // Cache miss
                    rt.add_text(&format!(
                        "<texture {id} was destroyed before we had the opportunity to draw it>"
                    ));
                }
            }
            JobResultData::Color(color) => {
                let color_stringified = color.to_string();
                rt.add_text(&color_stringified); // ignores bbcode
                rt.push_color(*color);
                rt.add_text(" █"); // visualize the color by drawing a little colored block next to it
                rt.pop();
            }
        }
    }
}

impl JobResultData {
    fn new(value: &Variant, cache: &mut Cache<InstanceId, Gd<Texture2D>>) -> Self {
        // Always try to cast to the most specific type first!
        if let Ok(tex) = value.try_to::<Gd<Texture2D>>() {
            let id = tex.instance_id();

            // Put the texture in the cache, so it doesn't immediately get destroyed
            cache.insert(id, tex);

            // Return its instance id
            JobResultData::Image(id)
        } else if let Ok(color) = value.try_to::<Color>() {
            JobResultData::Color(color)
        } else {
            JobResultData::String(value.stringify().to_string())
        }
    }
}

#[godot_api]
impl CrabConsoleLogHook {
    /// Check if log hook is enabled.
    #[func]
    pub(super) fn get_enabled(&self) -> bool {
        self.enabled.load(Ordering::Relaxed)
    }

    /// Enable or disable log hook. Returns the new value.
    #[func]
    pub(super) fn set_enabled(&mut self, enabled: bool) -> bool {
        self.enabled.store(enabled, Ordering::Relaxed);
        enabled
    }

    /// Toggle log hook. Returns the new value.
    #[func]
    pub(super) fn toggle_enabled(&mut self) -> bool {
        let old_val = self.enabled.fetch_xor(true, Ordering::Relaxed);
        !old_val
    }

    pub(super) fn new(enabled: bool, hook_tx: Sender<LogHookMsg>) -> Gd<Self> {
        Gd::from_init_fn(|base| Self {
            enabled: enabled.into(),
            hook_tx,
            base,
        })
    }
}

#[tracing::instrument(skip_all)]
pub(super) async fn log_hook_task(mut self: AsyncGd<Self>, hook_rx: Receiver<LogHookMsg>) {
    tracing::info!("log hook task starting...");

    let mut rich_text = self.bind_mut().nodes.console_history.clone();

    while let Ok(msg) = hook_rx.recv_async().await {
        // Warning - do not use tracing::___ here if LOG_TO_GODOT is true, or you get an infinite loop.

        self.bind_mut().maybe_add_timestamp();

        match msg {
            LogHookMsg::Message(inner) => {
                let LogHookMsgMessage { message, error } = inner.as_ref();
                // Do not use append_text, it parses bbcode in the message.

                if *error {
                    rich_text.push_color(Color::RED);
                } else {
                    rich_text.push_color(Color::DARK_GRAY);
                }

                // TODO make a method that takes a string with ANSI color codes and puts them in rich_text::push_color/pop?
                rich_text.add_text(message);

                rich_text.pop(); //pop color
            }
            LogHookMsg::Error(function, inner) => {
                let LogHookMsgKeyError {
                    file,
                    line,
                    reason,
                    rationale,
                    error_type,
                    ..
                } = inner.as_ref();
                // Do not use append_text, it parses bbcode in the message, may be risky.

                rich_text.push_color(Color::RED);
                rich_text.push_bold();
                rich_text.add_text(&format!("Error ({error_type:?}): "));
                rich_text.pop(); //pop bold
                rich_text.pop(); //pop color

                rich_text.push_color(Color::ORANGE);
                rich_text.add_text(&format!("{reason} ({rationale})\n"));
                rich_text.pop(); //pop color

                // TODO may need another call to this.bind_mut().maybe_add_timestamp() here

                rich_text.push_color(Color::RED);
                rich_text.push_bold();
                rich_text.add_text("Function: ");
                rich_text.pop(); //pop bold
                rich_text.pop(); //pop color

                rich_text.push_color(Color::ORANGE);
                rich_text.add_text(&format!("{function} ("));
                rich_text.push_color(Color::GRAY);
                rich_text.add_text(&format!("{file}:{line}"));
                rich_text.pop(); //pop color
                rich_text.add_text(")\n");
                rich_text.pop(); //pop color
            }
        }
    }
    tracing::warn!("log hook task shutdown");
}

struct EventChecker<'a> {
    event: &'a InputEvent,
    line_edit: Gd<LineEdit>,
}

async fn show_nodepath_popup_and_insert_text(mut self: AsyncGd<Self>, hovered: HoveredNode) {
    // This allow user to pick format A, B, C or D in a dropdown
    // A = get_node("/root/foo")
    // B = root/foo
    // C = from_instance_id([instance id])
    // D = :node from-id [instance id]
    // B is useful for e.g. :watch signals :node find B
    // C is useful if the node path is extremely long
    // D is useful to avoid using GDScript

    let mut menu = PopupMenu::new_alloc();
    self.gd_mut().add_child(&menu);

    // We allow the user to pick 4 different kind of formats:
    let text_a = format!(r#"get_node("{}")"#, hovered.get_path());
    let text_b = hovered.get_path().to_string();
    let text_c = format!(r#"instance_from_id({})"#, hovered.get_inner().instance_id());
    let text_d = format!(r#":node from-id {}"#, hovered.get_inner().instance_id());

    // Truncate the strings to avoid creating a massive menu for deep NodePaths
    menu.add_separator_ex().label("Which format to use?").done();
    menu.add_item_ex(&truncate_with_ellipsis(&text_a, 100))
        .id(0)
        .done();
    menu.add_item_ex(&truncate_with_ellipsis(&text_b, 100))
        .id(1)
        .done();
    menu.add_item_ex(&truncate_with_ellipsis(&text_c, 100))
        .id(2)
        .done();
    menu.add_item_ex(&truncate_with_ellipsis(&text_d, 100))
        .id(3)
        .done();
    // TODO use smaller monospace font maybe?

    // create the future before showing the menu, to ensure we connect in time to the signal
    let menu_selected_fut = menu.signals().id_pressed().to_fallible_future();
    let menu_hidden_fut = menu.signals().popup_hide().to_fallible_future(); //  `close_requested` does not fire at all
    let mouse_pos = get_viewport().get_mouse_position();
    menu.popup_ex() // using `rect` will automatically limit the menu to the screen bounds
        .rect(Rect2i::new(
            Vector2i::new(mouse_pos.x.round() as i32, mouse_pos.y.round() as i32),
            Vector2i::new(100, 100),
        ))
        .done();

    tracing::debug!("waiting for user to pick...");

    let selected = tokio::select! {
        biased; // <-- important: ensures `menu_selected` has priority over `menu_hidden`
        Ok((selected,)) = menu_selected_fut => selected,
        Ok(()) = menu_hidden_fut => {
            // menu was hidden while waiting for it, so cancel
            return;
        },
        else => {
            // menu was freed while waiting for it, so cancel
            return;
        },
    };

    tracing::debug!("user picked {selected}");

    let text_to_insert = match selected {
        0 => text_a,
        1 => text_b,
        2 => text_c,
        3 => text_d,
        _ => return, // invalid id, so cancel
    };

    menu.queue_free(); // important, or it will leak, since we create a new one every time

    let mut line_edit = self.bind().nodes.line_edit.clone(); //fast clone

    // TODO insert text at the caret, not just at the end
    let new_text = line_edit.get_text().to_string() + &text_to_insert;
    line_edit.set_text(&new_text);
}

struct LoopState {
    hovered: Option<HoveredNode>,
    hovered_ones: Vec<HoveredNode>, // so we can do HoveredNode.get_index() and HoveredNode.get_under_mouse and HoveredNode.get_global_bounding_rect
    selected_slot: usize,
    picker: Gd<Node2D>,
}

fn handle_mouse_pos(&mut self, mouse_pos: Vector2, pick_type: &PickType, skip: &[Gd<Node>]) {
    self.picker.set_global_position(mouse_pos); // or global_vp.get_mouse_position();

    // hovered = global_vp.gui_get_hovered_control(); // <- unusable: always returns the console subviewport, since it's above everything...
    self.hovered_ones =
        HoveredNode::get_under_mouse(pick_type, &get_root().upcast(), mouse_pos, skip);

    // Get the one by highest z-index
    // TODO: we need to take "is_above_parent" and "z_as_relative" into account.
    // Doing this accurately basically means re-implementing godot's entire ordering system, so extremely complex
    // ...let's just do the bare minimum

    // sort by z index
    self.hovered_ones
        .sort_by_key(|c| OrderedFloat(c.get_z_index()));

    self.selected_slot = self.hovered_ones.len().saturating_sub(1);
    self.hovered = self.hovered_ones.get(self.selected_slot).cloned(); // can be None if empty

    if let Some(hovered) = &self.hovered {
        let slot_text = format!(
            "[{}/{}]\n(scroll to change slot)",
            self.selected_slot + 1,
            self.hovered_ones.len()
        );
        // see console_picker.gd - wait why are we going through the script again?
        // this code seems fragile, maybe just access them directly via %?
        self.picker.set("text", &Variant::from(hovered.get_path()));
        self.picker.set("slot_text", &Variant::from(slot_text));
        self.picker.set("panel_visible", &Variant::from(true));

        self.picker.call(
            "set_panel_rect_global",
            &[Variant::from(hovered.get_global_bounding_rect())],
        );
    } else {
        self.picker.set(
            "text",
            &Variant::from(format!("<no {pick_type:?} under cursor>")),
        );
        self.picker.set("slot_text", &Variant::from(""));
        self.picker.set("panel_visible", &Variant::from(false));
    }
}

#[derive(Clone)]
enum HoveredNode {
    Control(Gd<Control>),
    Node2D(Gd<Node2D>),
    Node3D(Gd<Node3D>, Vector3), // raycast hit pos
}

fn get_under_mouse(
    pick_type: &PickType,
    root: &Gd<Node>,
    mouse_pos: Vector2,
    skip: &[Gd<Node>],
) -> Vec<Self> {
    // TODO if you have a lot of skips maybe use a HashSet instead for performance
    match pick_type {
        PickType::Control => get_controls_under_mouse(root, mouse_pos, skip)
            .into_iter()
            .map(HoveredNode::Control)
            .collect(),
        PickType::Node2D => get_node2ds_under_mouse(root, mouse_pos, skip)
            .into_iter()
            .map(HoveredNode::Node2D)
            .collect(),
        PickType::Node3D => get_node3ds_under_mouse(mouse_pos, skip)
            .into_iter()
            .map(|(n3d, hitpos)| HoveredNode::Node3D(n3d, hitpos))
            .collect(),
    }
}

fn get_inner(&self) -> Gd<Node> {
    match self {
        HoveredNode::Control(gd) => gd.clone().upcast(),
        HoveredNode::Node2D(gd) => gd.clone().upcast(),
        HoveredNode::Node3D(gd, _) => gd.clone().upcast(),
    }
}

fn get_controls_under_mouse(
    root: &Gd<Node>,
    mouse_pos: Vector2,
    skip: &[Gd<Node>],
) -> Vec<Gd<Control>> {
    fn collect_controls_under_mouse(
        root: &Gd<Node>,
        mouse_pos: Vector2,
        skip: &[Gd<Node>],
        out: &mut Vec<Gd<Control>>,
    ) {
        for child in root.get_children().iter_shared() {
            if let Ok(control) = child.clone().try_cast::<Control>()
                && !skip.iter().any(|skip| *skip == control.clone().upcast())
                && control.is_visible()
                && get_control_global_bounding_rect(&control).contains_point(mouse_pos)
            {
                out.push(control);
            }

            if child.get_child_count() > 0 {
                collect_controls_under_mouse(&child, mouse_pos, skip, out);
            }
        }
    }

    let mut results: Vec<Gd<Control>> = Vec::new();
    collect_controls_under_mouse(root, mouse_pos, skip, &mut results);
    results
}

pub fn get_control_global_bounding_rect(control: &Gd<Control>) -> Rect2 {
    // Control.get_global_rect takes the following into account:
    // - Control.scale
    // - Control.pivot_offset
    // It does NOT take into account:
    // - Control.rotation
    // - Camera2D position/rotation/zoom
    // So, let's make our own

    // This seems to take pivot_offset into account automagically
    let xform = control.get_global_transform_with_canvas(); // "_with_canvas" = take Cam2d into account
    let size = control.get_size();

    let corners = [
        xform * Vector2::new(0.0, 0.0),
        xform * Vector2::new(size.x, 0.0),
        xform * Vector2::new(0.0, size.y),
        xform * Vector2::new(size.x, size.y),
    ];

    // Create a Rect2 that encompasses all corner points, even if they're rotated.
    corners
        .iter()
        .map(|c| Rect2::new(*c, Vector2::ZERO))
        .reduce(|l, r| l.merge(r))
        .unwrap() // safe unwrap - corners cannot be empty
}

fn get_node2ds_under_mouse(
    root: &Gd<Node>,
    mouse_pos: Vector2,
    skip: &[Gd<Node>],
) -> Vec<Gd<Node2D>> {
    fn collect_node2ds_under_mouse(
        root: &Gd<Node>,
        mouse_pos: Vector2,
        skip: &[Gd<Node>],
        out: &mut Vec<Gd<Node2D>>,
    ) {
        for child in root.get_children().iter_shared() {
            if let Ok(node2d) = child.clone().try_cast::<Node2D>()
                && !skip.iter().any(|skip| *skip == node2d.clone().upcast())
                && node2d.is_visible()
                && get_node2d_global_bounding_rect(&node2d).contains_point(mouse_pos)
            {
                out.push(node2d);
            }

            if child.get_child_count() > 0 {
                collect_node2ds_under_mouse(&child, mouse_pos, skip, out);
            }
        }
    }

    let mut results: Vec<Gd<Node2D>> = Vec::new();
    collect_node2ds_under_mouse(root, mouse_pos, skip, &mut results);
    results
}

fn get_node2d_global_bounding_rect(node: &Gd<Node2D>) -> Rect2 {
    let mut rs = RenderingServer::singleton();

    let mut local_rect = if let Ok(spr) = node.clone().try_cast::<Sprite2D>() {
        // Note - this does NOT work for AnimatedSprite2D, since it inherits Node2D, NOT Sprite2D.
        // May wanna add custom logic for AnimatedSprite2D, Polygon2D
        // TODO - also add CollisionObject2D - will need to branch manually on all shape types though + deal with shape owner transform, kinda tedious
        spr.get_rect()
    } else if let Ok(mut body) = node.clone().try_cast::<CollisionObject2D>() {
        get_body_local_rect2(&mut body)
    } else {
        // Warning: This function is intended for debugging in the editor, and will return a zero Rect2 in exported projects.
        rs.debug_canvas_item_get_rect(node.get_canvas_item())
            .tap(|r| tracing::debug!(?r, ?node, "debug_canvas_item_get_rect"))
    };

    // If rect is zero-sized, grow it a little, else there's no way we can hover over it.
    let eps = 0.01;
    if local_rect.size.x.abs() < eps && local_rect.size.y.abs() < eps {
        local_rect = local_rect.grow(5.0);
    }

    node.get_global_transform_with_canvas() * local_rect
}

fn get_body_local_rect2(body: &mut Gd<CollisionObject2D>) -> Rect2 {
    let mut rects: Vec<Rect2> = Vec::new();

    for owner_id in body.get_shape_owners().as_slice().iter().copied() {
        let owner_id = owner_id as u32;
        let shape_count = body.shape_owner_get_shape_count(owner_id);

        for shape_id in 0..shape_count {
            let Some(shape) = body.shape_owner_get_shape(owner_id, shape_id) else {
                continue;
            };

            let xform = body.shape_owner_get_transform(owner_id);
            rects.push(xform * shape.get_rect());
        }
    }

    rects
        .into_iter()
        .reduce(|l, r| l.merge(r))
        .unwrap_or_default()
}

fn get_node3ds_under_mouse(mouse_pos: Vector2, skip: &[Gd<Node>]) -> Vec<(Gd<Node3D>, Vector3)> {
    // TODO this uses a potentially different viewport/camera3d compared to get_node3d_global_bounding_rect().
    // Watch out for discrepancies in split-screen games, or games that use multiple viewports in general!
    let viewport = get_viewport();
    let Some(camera) = viewport.get_camera_3d() else {
        tracing::warn!("no Camera3D in scene, so can't pick any 3D nodes");
        return Vec::new();
    };

    let ray_origin = camera.project_ray_origin(mouse_pos);
    let ray_end = ray_origin + camera.project_ray_normal(mouse_pos) * 1000.0;

    let world = viewport.get_world_3d();
    let Some(world) = world else {
        tracing::warn!("no World");
        return Vec::new();
    };

    let Some(mut space_state) = world.get_direct_space_state() else {
        tracing::warn!("no PhysicsDirectSpaceState3D");
        return Vec::new();
    };

    let mut exclude: Array<Rid> = Array::new();
    let mut nodes = Vec::new();

    loop {
        let mut query = PhysicsRayQueryParameters3D::create_ex(ray_origin, ray_end)
            .exclude(&exclude)
            .done()
            .expect("failed to create PhysicsRayQueryParameters3D"); // <-- not sure if this can ever fail?

        query.set_collide_with_areas(true);
        query.set_collide_with_bodies(true);

        let result = space_state.intersect_ray(&query);

        if result.is_empty() {
            break; // No hit
        }

        // At this point none of the unwraps should fail, unless Godot's API changes in the future:

        let hitpos = result
            .get("position")
            .expect("no position in raycast dict")
            .try_to::<Vector3>()
            .expect("position in raycast dict wasn't a Vector3");
        let collider = result.get("collider").expect("no collider in raycast dict");

        if let Ok(node3d) = collider.try_to::<Gd<Node3D>>()
            && !skip.iter().any(|skip| *skip == node3d.clone().upcast())
        {
            // add node only if it's a node3d and not in skip list
            nodes.push((node3d, hitpos));
        }

        let rid = result.get("rid").expect("no rid in raycast dict");
        if let Ok(rid) = rid.try_to::<Rid>() {
            exclude.push(rid);
        }
    }

    nodes
}

pub fn get_node3d_global_bounding_rect(n3d: &Gd<Node3D>) -> Rect2 {
    let aabb = get_node3d_global_aabb(n3d);
    let Some(cam) = get_camera_3d() else {
        // If the user tries to pick a 3D node when no Camera3D exists, we can't return anything meaningful here.
        // So just return a dummy rect.
        return Rect2::new(Vector2::ZERO, Vector2::new(10.0, 10.0));
    };
    project_aabb_to_2d(aabb, &cam)
}

#[tracing::instrument(skip_all)]
pub(super) async fn handle_console_client_events(
    mut self: AsyncGd<Self>,
    connection_rx: Receiver<(SocketAddr, ConsoleClientEvent)>,
) {
    while let Ok((addr, connected)) = connection_rx.recv_async().await {
        let key = addr.to_string();

        {
            let server = &mut self.bind_mut().server;
            if let Some(server) = server {
                let conns = &mut server.connections;
                match connected {
                    ConsoleClientEvent::Connected => {
                        let old = conns.insert(key.clone(), ConsoleClient::default());
                        if let Some(old) = old {
                            tracing::warn!(
                                "Client ({:?}, {:?}) was already \
                                    present in connection list - may indicate bug",
                                key,
                                old
                            );
                        }
                    }
                    ConsoleClientEvent::Disconnected => {
                        conns.shift_remove(&key);
                    }
                    ConsoleClientEvent::RanCommand => {
                        let client = conns.get_mut(&key);

                        match client {
                            Some(client) => {
                                client.commands_run += 1;
                            }
                            None => tracing::warn!("Missing client {}", key),
                        }
                    }
                }
            } else {
                // This happens since we get disconnection events when the server shuts down
                tracing::warn!(
                    "Received connection from ({:?}) while server was offline",
                    key
                );
            }
        } // drop bind
    }

    tracing::warn!("wait_for_connection_events stopped, since connection_tx was dropped");
}

pub(super) async fn handle_connection(
    peer_addr: SocketAddr,
    stream: TokioTcpStream,
    tx: Sender<Job>,
    connection_tx: Sender<(SocketAddr, ConsoleClientEvent)>,
) {
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    tracing::debug!("Client connected");
    writer
        .write_all(b"Remote console ready! Type :help to get started.\n")
        .await
        .ok(); // TODO error ignored

    while let Ok(Some(line)) = lines.next_line().await {
        let expression = line.trim().to_string();
        if expression.is_empty() {
            continue; // Skip empty expressions
        }

        let (reply_tx, reply_rx) = flume::unbounded();

        let _ = connection_tx
            .send_async((peer_addr, ConsoleClientEvent::RanCommand))
            .await;

        if tx
            .send_async(Job {
                expression: JobExpression::String(Arc::from(expression)),
                reply_tx,
                use_timeout: true,
            })
            .await
            .is_err()
        {
            writer
                .write_all(
                    b"Error: main thread unavailable - did you delete the CrabConsole node?\n",
                )
                .await
                .ok();
            break;
        }

        while let Some(response) = reply_rx.stream().next().await {
            let response = match response {
                JobEvent::Done(JobResult {
                    result: Ok(result), ..
                }) => format!("{result:?}\n"), // TODO print execution time
                JobEvent::Done(JobResult { result: Err(e), .. }) => format!("Error: {e}\n"),
                JobEvent::WaitingSignal => "Waiting for signal...".to_owned(),
                JobEvent::WaitingAsync => "Waiting for async...".to_owned(),
            };

            //NOTE - can't use godot_print! here because not on main thread. (update: might've been fixed in recent version of gdext)

            // Don't use tracing here! This must be always visible, regardless of RUST_LOG filters
            println!("REMOTE: {line} => {response}");

            writer.write_all(response.as_bytes()).await.ok(); // TODO error ignored here
        }
    }
}

#[tracing::instrument(skip_all)]
pub(super) fn update_remote_text(&mut self) {
    let ticks = Time::singleton().get_ticks_msec();
    let time_secs = ticks as f64 / 1000.0; // rounded to nearest ms
    let blink = (time_secs % 0.5) > 0.25;

    let mut remote_label = self.nodes.remote_label.clone(); // fast clone
    let server = &self.server;

    remote_label.clear();
    remote_label.add_text("Status: ");

    if let Some(server) = server {
        remote_label.push_color(if blink { Color::ORANGE } else { Color::WHITE });
        remote_label.add_text(&format!("online ({}:{})", server.ip, server.port));
        remote_label.pop();
    } else {
        remote_label.push_color(Color::GRAY);
        remote_label.add_text("offline");
        remote_label.pop();
    }

    remote_label.newline();

    if let Some(server) = server {
        let conns = &server.connections;
        remote_label.add_text(&format!("Connected clients ({}):\n", conns.len(),));

        for (ip, cl) in conns {
            remote_label.add_text("- ");

            remote_label.push_color(Color::YELLOW);
            remote_label.add_text(ip);
            remote_label.pop();

            remote_label.add_text(&format!(" (commands run: {})\n", cl.commands_run));
        }
    } else {
        remote_label.newline();
        remote_label.add_text("To start the remote console, run ");

        remote_label.push_color(Color::YELLOW);
        remote_label.add_text(":cons remote start");
        remote_label.pop();

        remote_label.add_text(".");
    }
}

fn scroll_line_into_view(label: Gd<RichTextLabel>, target_line: i32) {
    let Some(mut vscroll) = label.get_v_scroll_bar() else {
        tracing::warn!("RichTextLabel has no scrollbar (scroll_active may be false)");
        return;
    };

    let line_top = label.get_line_offset(target_line);
    let line_bottom = label.get_line_offset(target_line + 1);

    let visible_height = label.get_size().y;
    let current_scroll = vscroll.get_value() as f32;
    let max_value = vscroll.get_max() as f32;

    let viewport_top = current_scroll;
    let viewport_bottom = current_scroll + visible_height;

    let new_scroll = if line_top < viewport_top {
        // Line is above the visible area - scroll up so its top aligns with viewport top
        line_top
    } else if line_bottom > viewport_bottom {
        // Line is below the visible area - scroll down so its bottom aligns with viewport bottom
        line_bottom - visible_height
    } else {
        // Already fully visible - don't scroll at all
        return;
    };

    vscroll.set_value(new_scroll.clamp(0.0, max_value) as f64);
}

pub(super) fn reload_node(mut node: Gd<Node>) -> EyreResult<()> {
    let mut parent = node.get_parent().context("node has no parent")?;
    let index = node.get_index();
    let scene_file = node.get_scene_file_path();

    ensure!(
        !scene_file.is_empty(),
        "tried to reload a node that wasn't loaded from disk"
    );

    node.queue_free();

    // Need to spawn a background task, since our async executor may stop after calling node.queue_free(), since we may have freed `self`.
    godot::task::spawn(async move {
        // Now wait 1 frame to ensure the previous one is gone.
        // Otherwise, they will co-exist, which causes many problems, and messes up the name of the second one.
        wait_for_next_frame().await;

        let res: EyreResult<()> = async move {
            let packed_scene = try_load::<PackedScene>(&scene_file.to_string())
                .with_context(|| format!("failed to load scene file `{scene_file}`"))?;
            let new_instance = packed_scene
                .instantiate()
                .context("failed to instantiate scene")?;

            parent.add_child(&new_instance.clone());
            parent.move_child(&new_instance, index);

            Ok(())
        }
        .await;
        match res {
            Ok(()) => {}
            Err(err) => tracing::warn!(?err, "failed to reload node"),
        }
    });

    Ok(())
}

pub(super) fn get_cursor_world_position(depth: f32, camera: Gd<Camera3D>) -> Vector3 {
    let viewport = camera
        .get_viewport()
        .expect("camera 3d has no viewport, ensure it's in the scene tree"); // TODO handle more gracefully?

    let mouse_pos = viewport.get_mouse_position();
    let origin = camera.project_ray_origin(mouse_pos);
    let direction = camera.project_ray_normal(mouse_pos);

    origin + direction * depth
}

pub(super) async fn http_get(url: &str) -> eyre::Result<String> {
    use godot::{classes::http_request::Result as HttpResult, global::Error as GodotError};

    // Create the HttpRequest node and attach it to the tree.
    let mut http = HttpRequest::new_alloc();
    http.set_process_mode(ProcessMode::ALWAYS); // Prevent a paused game from pausing the http request.

    // http.set_use_threads(true) seems to cause some kind of deadlock so don't use threads
    // to diagnose run :debug http-get https://eu.httpbin.org/
    // (or any other slow server that runs into the console timeout before it finishes)

    get_current_scene()
        .expect("no current scene")
        .add_child(&http);

    // Ensure we always clean up the node, even on early return.
    let cleanup_target = http.clone();
    scopeguard::defer! {
        if cleanup_target.is_instance_valid() {
            cleanup_target.clone().queue_free();
        }
    }

    // Grab the future for the `request_completed` signal *before* firing the request,
    // so we can't possibly miss the emission.
    let fut = http.signals().request_completed().to_fallible_future();

    let err = http.request(url);
    ensure!(
        err == GodotError::OK,
        "failed to start HTTP request: {err:?}"
    );

    // This can fail if we switch scenes during the HTTP request,
    // causing the HTTPRequest node to be freed.
    let (result, response_code, _headers, body) = fut.await?;

    let result = HttpResult::from_ord(result as i32);
    if result != HttpResult::SUCCESS {
        return Err(eyre!("HTTP request did not succeed: {:?}", result));
    }

    //200-299 = success
    //300-399 = redirection
    //400-499 = client error
    //500-599 = server error

    // Do not use is_client_error/is_server_error, we can only use it if response_code is a valid response code.
    // In the future the HTTP standard may get new kinds of client/server errors which may not be caught otherwise.
    if (400..600).contains(&response_code) {
        return Err(eyre!(
            "HTTP request returned status {}",
            describe_status(response_code)
        ));
    }

    String::from_utf8(body.to_vec()).map_err(|_| eyre!("response body was not valid UTF-8"))
}

pub(super) async fn show_dialog(title: &str, text: &str) {
    let mut dialog = AcceptDialog::new_alloc();
    dialog.set_title(title);

    // Add custom label so we can make it wrap automatically
    let mut label = Label::new_alloc();
    label.set_text(text);
    label.set_autowrap_mode(AutowrapMode::WORD_SMART);
    label.set_custom_minimum_size(Vector2::new(400.0, 0.0));

    // Add scroll container to prevent long text from making the dialog impossible to close
    let mut scroll = ScrollContainer::new_alloc();
    scroll.set_custom_minimum_size(Vector2::new(400.0, 300.0));
    scroll.add_child(&label);
    dialog.add_child(&scroll);

    get_root().add_child(&dialog);
    dialog
        .popup_centered_clamped_ex()
        .minsize(Vector2i::new(500, 80))
        .fallback_ratio(0.8) // <-- does not seem to work, if you feed a very long string into it it will occupy more than full screen
        .done();

    let mut dialog2 = dialog.clone();
    defer! {
        // Do not forget this, or you get a memory leak if the future is cancelled
        dialog2.queue_free();  // This is idempotent, so calling is twice is harmless
    }

    let _ = dialog
        .signals()
        .visibility_changed()
        .to_fallible_future()
        .await
        .is_ok();
}

pub(super) async fn show_prompt(title: &str, prompt: &str) -> Option<String> {
    let mut dialog = AcceptDialog::new_alloc();
    dialog.set_title(title);

    let mut line_edit = LineEdit::new_alloc();
    line_edit.set_placeholder(prompt);
    dialog.add_child(&line_edit);

    get_root().add_child(&dialog);
    dialog
        .popup_centered_clamped_ex()
        .minsize(Vector2i::new(500, 80))
        .fallback_ratio(0.8)
        .done();
    line_edit.grab_focus();

    let mut dialog2 = dialog.clone();
    defer! {
        // Do not forget this, or you get a memory leak if the future is cancelled
        dialog2.queue_free(); // This is idempotent, so calling is twice is harmless
    }

    let confirmed = dialog.signals().confirmed().to_fallible_future();
    let visibility_changed = dialog.signals().visibility_changed().to_fallible_future();
    let line_accepted = line_edit.signals().text_submitted().to_fallible_future();

    tokio::select! {
        biased; // <-- important, to ensure `line_accepted` always triggers before `confirmed` which always triggers before `visibility_changed`
        Ok((text,)) = line_accepted => Some(text.to_string()),
        Ok(_) = confirmed => Some(line_edit.get_text().to_string()),
        Ok(_) = visibility_changed => None,
        else => None, // One of the futures returned Err, so it was already freed
    }
}

fn create_folder_if_not_exists(godot_path: &str) -> Result<PathBuf, Arc<io::Error>> {
    assert!(is_main_thread());

    let folder = PathBuf::from(
        ProjectSettings::singleton()
            .globalize_path(godot_path)
            .to_string(),
    );

    // This will succeed even if the folder already exists.
    // It will only fail if e.g. it does not have permission to create the folder (e.g. in wasm)
    std::fs::create_dir_all(&folder)?;

    tracing::info!(?folder, "created folder `{godot_path}`");

    Ok(folder)
}

pub fn get_sysinfo() -> Dictionary<Variant, Variant> {
    let os = Os::singleton();
    let rendering_server = RenderingServer::singleton();
    let display_server = DisplayServer::singleton();

    let memory_total_mb = os
        .get_memory_info()
        .get("physical")
        .map(|v| v.to::<i64>() as f64 / 1024.0 / 1024.0)
        .unwrap_or(0.0);

    let os_info = vdict! {
        "name" => &os.get_name(),
        "distribution" => &os.get_distribution_name(),
        "locale" => &os.get_locale(),
        "executable_path" =>& os.get_executable_path(),
    };

    let hardware_info = vdict! {
        "model_name" => &os.get_model_name(),
        "processor_name" => &os.get_processor_name(),
        "processor_count" => os.get_processor_count(),
        "memory_total_mb" => memory_total_mb,
    };

    let graphics_info = vdict! {
        "video_adapter" => &rendering_server.get_video_adapter_name(),
        "video_adapter_vendor" => &rendering_server.get_video_adapter_vendor(),
        "video_adapter_api_version" => &rendering_server.get_video_adapter_api_version(),
        "screen_count" => display_server.get_screen_count(),
        "screen_resolution" => display_server.screen_get_size(),
    };

    let engine_info = vdict! {
        "godot_runtime_version" => GdextBuild::godot_runtime_version_string(), // Godot version running the game
        "godot_static_version" => GdextBuild::godot_static_version_string(), // Godot-api level godot-rust compiles against
        "is_exported_build" => !os.has_feature("editor"),

    };

    let bi = BUILD_INFO
        .get()
        .expect("build info not set, ensure you called assign_build_info()");
    let cc_info = vdict! {
        "crate_version" => format!("{} v{}", env!("CARGO_PKG_NAME"), env!("CARGO_PKG_VERSION")),
        "build_id" => bi.build_id,
        "build_profile" =>  bi.actual_profile,
        "build_features" =>  bi.build_features,

    };

    let features = VarArray::from_iter(active_godot_features().into_iter().map(|s| s.to_variant()));

    vdict! {
        "os" => &os_info,
        "hardware" => &hardware_info,
        "graphics" => &graphics_info,
        "engine" => &engine_info,
        "crabbyconsole" => &cc_info,
        "active_godot_features" => &features,
    }

    // TODO maybe make this strictly typed instead of a dict?
}

pub fn get_node3d_global_aabb(n3d: &Gd<Node3D>) -> Aabb {
    if let Ok(c) = n3d.clone().try_cast::<CollisionObject3D>() {
        let mut aabbs = vec![]; // <-- in global space

        // note - shape owners are NOT guaranteed to be contiguous, so don't iterate using 0..shape_count
        for shape_owner in c.get_shape_owners().as_slice() {
            // on the other hand, shapes within a shape owner ARE contiguous, so we can use 0..n iteration
            for shape_id in 0..c.shape_owner_get_shape_count(*shape_owner as u32) {
                let shape = c
                    .shape_owner_get_shape(*shape_owner as u32, shape_id)
                    .unwrap_or_else(|| {
                        panic!("missing shape with id {shape_id} in shape_owner {shape_owner}")
                    });

                // Note - this works in an exported game as well
                let debug_mesh = shape.get_debug_mesh().expect("no debug mesh"); // <-- TODO may be very slow for concave meshes

                let global_aabb = n3d.get_global_transform()
                    * c.shape_owner_get_transform(*shape_owner as u32)
                    * debug_mesh.get_aabb();
                aabbs.push(global_aabb)
            }
        }

        // Now reduce them together into one big AABB.
        // (we don't start with a "identity" AABB here, or it may be incorrectly included, e.g. if the node3d's origin lies outside the shape's AABB)
        aabbs
            .into_iter()
            .reduce(|left, right| left.merge(right))
            .unwrap_or_else(|| {
                tracing::warn!("CollisionObject3D has no shapes - using dummy AABB");
                Aabb::new(n3d.get_global_position(), Vector3::ONE * 0.1)
            })
    } else if let Ok(vis) = n3d.clone().try_cast::<VisualInstance3D>() {
        // If it's a VisualInstance3D, we're in luck, we can easily get the AABB like this:
        vis.get_global_transform() * vis.get_aabb()
    } else {
        // Not sure if a raycast can ever return an object that isn't a CollisionObject3D, but okay
        tracing::warn!(
            "object wasn't a CollisionObject3D nor a VisualInstance3D - using dummy AABB"
        );
        Aabb::new(n3d.get_global_position(), Vector3::ONE * 0.5)
    }
}

pub async fn load_threaded(path: &str) -> Result<Gd<Resource>, Report> {
    let mut loader = ResourceLoader::singleton();

    if loader.load_threaded_request(path) != godot::global::Error::OK {
        return Err(eyre!("failed to start threaded load for `{path}`"));
    }

    loop {
        match loader.load_threaded_get_status(path) {
            ThreadLoadStatus::IN_PROGRESS => {
                // Spin loop: check every frame if the resource is ready
                wait_for_next_frame().await;
            }
            ThreadLoadStatus::LOADED => break,
            e @ (ThreadLoadStatus::FAILED | ThreadLoadStatus::INVALID_RESOURCE) => {
                return Err(eyre!("threaded load failed for `{path}` ({e:?})"));
            }
            _ => unreachable!(),
        }
    }

    let resource = loader
        .load_threaded_get(path)
        .ok_or_else(|| eyre!("failed to get loaded resource at `{path}`"))?;

    Ok(resource)
}

impl TweenConfig {
    /// Sets up the given Tween according to this `TweenConfig`.
    pub fn apply(&self, tween: &mut Gd<Tween>) {
        tween.set_trans(self.transition_type);
        tween.set_ease(self.ease_type);
        tween.set_pause_mode(self.pause_mode);
        tween.set_process_mode(self.process_mode);
    }

    pub fn linear() -> Self {
        Self::builder()
            .transition_type(TransitionType::LINEAR)
            .build()
    }

    pub fn smooth() -> Self {
        Self::builder() // Default ease is IN_OUT
            .transition_type(TransitionType::QUINT)
            .build()
    }

    pub fn elastic() -> Self {
        Self::builder()
            .transition_type(TransitionType::ELASTIC)
            .ease_type(EaseType::OUT)
            .build()
    }
}

