pub fn project_aabb_to_2d(aabb: Aabb, camera: &Gd<Camera3D>) -> Rect2 {
    let mut rect: Option<Rect2> = None;

    for i in 0..8 {
        let corner = aabb.get_corner(i);

        // Skip corners behind the camera
        if camera.is_position_behind(corner) {
            continue;
        }

        let screen_pos = camera.unproject_position(corner);

        rect = Some(match rect {
            None => Rect2::new(screen_pos, Vector2::ZERO),
            Some(r) => r.expand(screen_pos),
        });
    }

    rect.unwrap_or_default()
}

pub fn get_all_resources() -> Vec<String> {
    let path = "res://";

    fn scan_dir(path: &str, result: &mut Vec<String>) {
        let mut loader = ResourceLoader::singleton();

        // skip directories that contain .gdignore
        let ignore_marker = format!("{path}.gdignore");
        if FileAccess::file_exists(&ignore_marker) {
            return;
        }

        for entry in loader.list_directory(path).as_slice() {
            let entry = entry.to_string();
            if entry.starts_with('.') {
                continue;
            }
            if entry.ends_with('/') {
                scan_dir(&format!("{path}{entry}"), result);
            } else {
                result.push(format!("{path}{entry}"));
            }
        }
    }

    let mut result = Vec::new();
    scan_dir(path, &mut result);
    result.sort(); // Important, since list_directory returns in non-deterministic order
    result
}

pub fn build_key_name_map() -> IndexMap<String, Key> {
    let os = Os::singleton();

    let mut duplicate_checker = IndexSet::<String>::default();

    Key::all_constants()
        .iter()
        .filter_map(|constant| {
            let key = constant.value();

            // Note - os.get_keycode_string(Key::SPECIAL) will spam Godot errors about invalid UTF-8, so skip it early
            if key == Key::SPECIAL {
                return None;
            }

            // store in lowercase, so we can look them up in a case-insensitive way
            let name = os.get_keycode_string(key).to_string().to_lowercase();
            let valid = !name.is_empty() // the first one is always empty
                && name.chars().all(|c| c.is_ascii_alphanumeric()) // some names contain spaces (notably all keypad binds), so cannot be used in :key bind
                && key != Key::UNKNOWN;

            if valid {
                let inserted = duplicate_checker.insert(name.clone());
                if !inserted {
                    tracing::warn!("duplicate key {name} ({key:?})");
                }
            }

            valid.then_some((name, key))
        })
        .collect()
}

#[derive(GodotClass)]
#[class(base = RefCounted)]
pub struct CrabConsoleTestRunner {
    base: Base<RefCounted>,
}

#[godot_api]
impl CrabConsoleTestRunner {
    /// Call this static method from integration_test.gd.
    ///
    /// Returns exit code (0 = test success, 1 = test failure)
    #[func]
    fn run_from_args(args: PackedStringArray) -> i32 {
        // Find the --crabbyconsole-write-tests-to <FILE_NAME> cli arg
        let test_file_name = find_cli_arg("--crabbyconsole-write-tests-to", &args);

        if let Some(test_file_name) = test_file_name {
            // Write the names of all tests to `test_file_name`
            let result = write_lines(
                &test_file_name,
                test_registry::list_names()
                    .iter()
                    .map(|s| (*s).to_owned()) // &'static str -> String
                    .collect(),
            );

            match result {
                Ok(()) => {
                    println!(
                        "Wrote {} tests to `{test_file_name}`",
                        test_registry::list_names().len()
                    );
                    return 0;
                }
                Err(e) => {
                    godot_error!("Failed to write tests to `{test_file_name}`: {e}");
                    return 1;
                }
            }
        }

        // Find the --crabbyconsole-test <TEST_NAME> cli arg
        let test_name: Option<String> = find_cli_arg("--crabbyconsole-test", &args);

        let Some(test_name) = test_name else {
            godot_error!(
                "No --crabbyconsole-test name provided (usage: -- --crabbyconsole-test <name>)"
            );
            return 1;
        };

        // Now run the test
        let passed = test_registry::run_one(&test_name);
        if passed { 0 } else { 1 }
    }
}

pub fn run_one(name: &str) -> bool {
    match get_tests_from_inventory().iter().find(|t| t.name == name) {
        Some(test) => match catch_unwind(AssertUnwindSafe(test.func)) {
            Ok(_) => {
                godot_print!("[PASS] {name}");
                true
            }
            Err(_) => {
                // Note: the panic info seems to get printed automatically, so we don't need to print it here
                godot_print!("[FAIL] {name}");
                false
            }
        },
        None => {
            godot_error!("no test named {name}");
            false
        }
    }
}

