fn run_check() -> Result<String, String> {
    let (frames, realize) = fixture();
    let vpc = verts_per_chunk(RES);

    let mut rd = RenderingServer::singleton()
        .create_local_rendering_device()
        .ok_or("no local RenderingDevice")?;

    let mut gpu = ChunkGpuResources::new_compute_only(realize.len() as u32, RES, TILE_RES, RADIUS);
    if !gpu.ensure_ready(&mut rd) {
        return Err("ChunkGpuResources::ensure_ready failed (pipeline/pool build)".into());
    }

    // Also exercise the instance packer (no multimesh in compute-only mode, so
    // this is just a shape/size check that it produces the expected bytes).
    let slots: Vec<u32> = realize.iter().map(|(s, _)| *s).collect();
    let inst = pack_instances(&slots, &vec![1.0f32; slots.len()]);
    if inst.len() != realize.len() * 16 * 4 {
        return Err(format!("pack_instances size {} unexpected", inst.len()));
    }

    // ── Terrain OFF: positions must equal chunk_subvertex_base exactly. ──
    let terrain_off = TerrainGpu::zeroed(); // enabled == 0 → pure geometry
    let off = realize_positions(&mut gpu, &mut rd, &frames, &realize, &terrain_off);

    // Tolerance basis: 1e-4 * scale, scale ≥ radius.
    let tol = 1.0e-4 * frames[FACE as usize].edge_len().max(RADIUS);
    let mut max_err = 0.0f32;
    let mut worst = (0u32, 0u32, 0u32);
    for &(slot, i, j, pos) in &off {
        let chunk = realize.iter().find(|(s, _)| *s == slot).map(|(_, c)| c).unwrap();
        let frame = &frames[chunk.id.face as usize];
        let want = chunk_subvertex_base(frame, chunk, RES, i, j);
        let err = (pos - want).length();
        if !err.is_finite() {
            return Err(format!("slot {slot} (i={i},j={j}): non-finite position {pos}"));
        }
        if err > max_err {
            max_err = err;
            worst = (slot, i, j);
        }
    }
    let total = off.len();
    if max_err > tol {
        return Err(format!(
            "terrain-OFF max error {max_err:.6} > tol {tol:.6} at slot {} (i={},j={}); {total} verts",
            worst.0, worst.1, worst.2
        ));
    }

    // ── Terrain ON: every position within the [0.7r, 1.3r] envelope. ──
    let terrain_on = assemble(&HeightGpu::default(), &TextureGpu::default());
    let on = realize_positions(&mut gpu, &mut rd, &frames, &realize, &terrain_on);
    let (lo, hi) = (RADIUS * 0.7, RADIUS * 1.3);
    let mut env_bad = 0usize;
    let mut env_worst = 0.0f32;
    for &(_, _, _, pos) in &on {
        let l = pos.length();
        if !l.is_finite() || l < lo || l > hi {
            env_bad += 1;
            env_worst = env_worst.max((l - RADIUS).abs());
        }
    }


    if env_bad > 0 {
        return Err(format!(
            "terrain-ON envelope: {env_bad}/{} verts out of [{lo:.0},{hi:.0}] (worst |Δr|={env_worst:.1})",
            on.len()
        ));
    }

    Ok(format!(
        "terrain-OFF max error {max_err:.6} (tol {tol:.6}) over {total} verts \
         ({} chunks × {vpc} verts, res {RES}); terrain-ON {} verts within [{lo:.0},{hi:.0}]",
        realize.len(),
        on.len(),
    ))
}

pub fn reference_chunk_mesh(
    res: u32,
    material: &godot::obj::Gd<godot::classes::Material>,
) -> godot::obj::Gd<godot::classes::ArrayMesh> {
    use godot::classes::mesh::{ArrayType, PrimitiveType};
    use godot::classes::ArrayMesh;
    use godot::prelude::*;

    let (verts_bary, indices_raw) = chunk_grid(res);

    let packed_verts: PackedVector3Array = verts_bary
        .iter()
        .map(|&[wa, wb, wc]| Vector3::new(wa, wb, wc))
        .collect();

    let packed_normals: PackedVector3Array =
        std::iter::repeat(Vector3::new(0.0, 0.0, 1.0))
            .take(verts_bary.len())
            .collect();

    // Phase 4: store each vertex's chunk-local barycentric (wb, wc) in UV so the
    // fragment shader gets an interpolated per-pixel (u, v) to index the detail
    // atlas (tx = u*tile_res, ty = v*tile_res). u==wb axis, v==wc axis — matching
    // ChunkTileBake.slang's texel→bary reconstruction.
    let packed_uvs: PackedVector2Array = verts_bary
        .iter()
        .map(|&[_wa, wb, wc]| Vector2::new(wb, wc))
        .collect();

    let packed_indices: PackedInt32Array = indices_raw.iter().copied().collect();

    let mut arrays = VarArray::new();
    arrays.resize(ArrayType::MAX.ord() as usize, &Variant::nil());
    arrays.set(ArrayType::VERTEX.ord() as usize, &packed_verts.to_variant());
    arrays.set(ArrayType::NORMAL.ord() as usize, &packed_normals.to_variant());
    arrays.set(ArrayType::TEX_UV.ord() as usize, &packed_uvs.to_variant());
    arrays.set(ArrayType::INDEX.ord() as usize, &packed_indices.to_variant());

    let mut mesh = ArrayMesh::new_gd();
    mesh.add_surface_from_arrays(PrimitiveType::TRIANGLES, &arrays);
    mesh.surface_set_material(0, material);
    mesh
}

pub struct ChunkCtx<'a> {
    pub rd: Gd<RenderingDevice>,
    pub gpu: &'a mut ChunkGpuResources,
    pub stage: &'a mut Option<ChunkStage>,
    pub terrain: TerrainGpu,
    pub res: u32,
    /// Chunks to realize this execute; set by the upload node from the stage and
    /// read by the realize node to size its dispatch (`count * verts_per_chunk`).
    pub realize_count: u32,
    /// Visible instances this execute (CEL-73); set by the upload node, read by
    /// the scatter-compact node to size its dispatch (`vis * capacity`).
    pub vis_count: u32,
    list: Option<i64>,
    /// Timestamp labels captured this execute (for GPU timing parity with `Ctx`).
    pub captured: Vec<&'static str>,
}

impl<'a> ChunkCtx<'a> {
    pub fn new(
        rd: Gd<RenderingDevice>,
        gpu: &'a mut ChunkGpuResources,
        stage: &'a mut Option<ChunkStage>,
        terrain: TerrainGpu,
        res: u32,
    ) -> Self {
        Self {
            rd,
            gpu,
            stage,
            terrain,
            res,
            realize_count: 0,
            vis_count: 0,
            list: None,
            captured: Vec::new(),
        }
    }

    pub fn list(&mut self) -> i64 {
        *self.list.get_or_insert_with(|| self.rd.compute_list_begin())
    }

    /// Timestamps must sit between compute lists, so close any open list.
    pub fn close_list(&mut self) {
        if self.list.take().is_some() {
            self.rd.compute_list_end();
        }
    }

    /// Close the list and capture the end marker; returns the captured labels.
    pub fn finish(mut self) -> Vec<&'static str> {
        self.close_list();
        self.rd.capture_timestamp("celestial/chunk-end");
        self.captured.push("celestial/chunk-end");
        self.captured
    }
}

#[derive(GodotClass)]
#[class(base = RefCounted, no_init)]
pub struct CesChunkJob {
    base: Base<RefCounted>,
    pub gpu: ChunkGpuResources,
    graph: Graph<Box<dyn ChunkNode>>,
    upload_node: NodeId,
    /// Staged by the main thread; drained on the render thread.
    pub stage: Option<ChunkStage>,
    /// Current terrain params (uploaded with the batch).
    pub terrain: TerrainGpu,
    pub res: u32,
    /// Number of graph executes that actually ran (consumed a stage). Stays flat
    /// on a stationary camera — the no-readback / cache win the HUD verifies.
    pub executes: u64,
    /// Timestamp labels captured last execute (drained the next execute).
    pending_labels: Vec<&'static str>,
    /// Per-stage GPU milliseconds from the previous execute: `(node name, ms)`
    /// for each graph node that ran (`chunk-upload`, `chunk-realize`, and any
    /// future pass). Read by the node for the HUD breakdown.
    pub gpu_ms: Vec<(&'static str, f64)>,
}

impl CesChunkJob {
    /// Build a job targeting `mm_rid` (or `Rid::Invalid` to self-create the
    /// multimesh) with capacity `budget` chunks at resolution `res`.
    pub fn create(
        mm_rid: Rid,
        budget: u32,
        res: u32,
        tile_res: u32,
        radius: f32,
        bump_enable: f32,
        terrain: TerrainGpu,
        scatter: Vec<crate::gpu::chunk_gpu::ScatterConfig>,
    ) -> Gd<Self> {
        let mut graph: Graph<Box<dyn ChunkNode>> = Graph::new();
        let reg = build_chunk_pipeline(&mut graph);
        let mut gpu = ChunkGpuResources::new(mm_rid, budget, res, tile_res, radius);
        gpu.set_bump_enable(bump_enable);
        gpu.set_scatter_configs(scatter);
        Gd::from_init_fn(|base| Self {
            base,
            gpu,
            graph,
            upload_node: reg.upload,
            stage: None,
            terrain,
            res,
            executes: 0,
            pending_labels: Vec::new(),
            gpu_ms: Vec::new(),
        })
    }
}

fn ensure_scatter_ready(&mut self, rd: &mut Gd<RenderingDevice>) -> bool {
    let rs = RenderingServer::singleton();
    for cfg in &self.scatter_cfgs {
        // A config without a multimesh (compute-only verification) skips
        // the wait — its compact set simply stays Invalid.
        if cfg.mm_rid.is_valid()
            && (rs.multimesh_get_buffer_rd_rid(cfg.mm_rid).is_invalid()
                || rs.multimesh_get_command_buffer_rd_rid(cfg.mm_rid).is_invalid())
        {
            return false;
        }
    }

    let sink = self.sink();
    let Some((shader, pipeline)) =
        device::compute_pipeline(rd, &sink, SCATTER_PLACE_SPV, "ScatterPlace")
    else {
        self.init_failed = true;
        return false;
    };
    self.scatter_shader = shader;
    self.scatter_pipeline = pipeline;
    let Some((cshader, cpipeline)) =
        device::compute_pipeline(rd, &sink, SCATTER_COMPACT_SPV, "ScatterCompact")
    else {
        self.init_failed = true;
        return false;
    };
    self.compact_shader = cshader;
    self.compact_pipeline = cpipeline;

    self.scatter_aux_buf = device::storage_buffer_empty(rd, &sink, self.budget as u64 * 16);
    // 1 uint (slot) per visible chunk.
    self.scatter_vis_buf = device::storage_buffer_empty(rd, &sink, self.budget as u64 * 4);

    let cfgs = std::mem::take(&mut self.scatter_cfgs);
    for cfg in &cfgs {
        let pool_bytes = self.budget as u64 * cfg.capacity as u64 * 64;
        let pool_buf = device::storage_buffer_empty(rd, &sink, pool_bytes);
        let params_buf = device::storage_buffer(
            rd,
            &sink,
            &[0u8; std::mem::size_of::<crate::scatter_descriptors::ScatterParamsGpu>()],
        );
        let counter_buf = device::storage_buffer_empty(rd, &sink, 4);

        let mut layer = ScatterLayerGpu {
            cfg: *cfg,
            place_set: Owned::invalid(sink.clone()),
            compact_set: Owned::invalid(sink.clone()),
            pool_buf,
            params_buf,
            counter_buf,
        };
        self.build_scatter_sets(rd, &mut layer);
        self.scatter_layers.push(layer);
    }
    self.scatter_built = true;
    true
}

fn ensure_custom_ready(&mut self, rd: &mut Gd<RenderingDevice>) {
    let Some(src) = self.custom_source.clone() else { return };
    let sink = self.sink();
    let Some((shader, pipeline)) =
        device::compute_pipeline_from_glsl(rd, &sink, &src, "CustomSurface")
    else {
        self.custom_failed = true;
        return;
    };
    self.custom_shader = shader;
    self.custom_pipeline = pipeline;
    let params0 = crate::custom_surface::pack_params(
        0,
        self.tile_res,
        self.custom_water_height,
        self.custom_height_scale,
        &self.custom_user_params,
    );
    self.custom_params_buf = device::storage_buffer(rd, &sink, &params0);
    let uniforms: Array<Gd<RdUniform>> = [
        device::uniform(UniformType::STORAGE_BUFFER, 0, self.desc_buf.rid()),
        device::uniform(UniformType::STORAGE_BUFFER, 1, self.surface_color_buf.rid()),
        device::uniform(UniformType::STORAGE_BUFFER, 2, self.surface_height_buf.rid()),
        device::uniform(UniformType::STORAGE_BUFFER, 3, self.surface_normal_buf.rid()),
        device::uniform(UniformType::STORAGE_BUFFER, 4, self.custom_params_buf.rid()),
    ]
    .into_iter()
    .collect();
    self.custom_set =
        Owned::new(rd.uniform_set_create(&uniforms, self.custom_shader.rid(), 0), sink.clone());
    self.custom_built = true;
}

fn build_scatter_sets(&self, rd: &mut Gd<RenderingDevice>, layer: &mut ScatterLayerGpu) {
    let rs = RenderingServer::singleton();
    let sink = self.sink();
    let place_uniforms: Array<Gd<RdUniform>> = [
        device::uniform(UniformType::STORAGE_BUFFER, 0, self.desc_buf.rid()),
        device::uniform(UniformType::STORAGE_BUFFER, 1, self.scatter_aux_buf.rid()),
        device::uniform(UniformType::STORAGE_BUFFER, 2, layer.params_buf.rid()),
        device::uniform(UniformType::STORAGE_BUFFER, 3, layer.pool_buf.rid()),
        // CPU-surface elevation grid: place samples the SAME heightmap
        // realize displaces the terrain with (procedural route ignores it).
        device::uniform(UniformType::STORAGE_BUFFER, 4, self.surface_height_buf.rid()),
    ]
    .into_iter()
    .collect();
    layer.place_set = Owned::new(
        rd.uniform_set_create(&place_uniforms, self.scatter_shader.rid(), 0),
        sink.clone(),
    );

    if layer.cfg.mm_rid.is_invalid() {
        // Compute-only verification: place side only.
        layer.compact_set = Owned::invalid(sink);
        return;
    }
    let mm_buf = rs.multimesh_get_buffer_rd_rid(layer.cfg.mm_rid);
    let cmd_buf = rs.multimesh_get_command_buffer_rd_rid(layer.cfg.mm_rid);
    let compact_uniforms: Array<Gd<RdUniform>> = [
        device::uniform(UniformType::STORAGE_BUFFER, 0, layer.params_buf.rid()),
        device::uniform(UniformType::STORAGE_BUFFER, 1, layer.pool_buf.rid()),
        device::uniform(UniformType::STORAGE_BUFFER, 2, self.scatter_vis_buf.rid()),
        device::uniform(UniformType::STORAGE_BUFFER, 3, layer.counter_buf.rid()),
        device::uniform(UniformType::STORAGE_BUFFER, 4, mm_buf),
        device::uniform(UniformType::STORAGE_BUFFER, 5, cmd_buf),
    ]
    .into_iter()
    .collect();
    layer.compact_set = Owned::new(
        rd.uniform_set_create(&compact_uniforms, self.compact_shader.rid(), 0),
        sink,
    );
}

pub fn upload_scatter(
    &mut self,
    rd: &mut Gd<RenderingDevice>,
    aux_bytes: &[u8],
    vis_bytes: &[u8],
    layer_params: &[Vec<u8>],
) {
    if !self.scatter_built {
        return;
    }
    let mut layers = std::mem::take(&mut self.scatter_layers);
    for layer in &mut layers {
        if !rd.uniform_set_is_valid(layer.place_set.rid())
            || (layer.cfg.mm_rid.is_valid() && !rd.uniform_set_is_valid(layer.compact_set.rid()))
        {
            self.build_scatter_sets(rd, layer);
        }
    }
    self.scatter_layers = layers;
    if !aux_bytes.is_empty() {
        let n = aux_bytes.len().min(self.budget as usize * 16);
        rd.buffer_update(
            self.scatter_aux_buf.rid(),
            0,
            n as u32,
            &PackedByteArray::from(&aux_bytes[..n]),
        );
    }
    if !vis_bytes.is_empty() {
        let n = vis_bytes.len().min(self.budget as usize * 4);
        rd.buffer_update(
            self.scatter_vis_buf.rid(),
            0,
            n as u32,
            &PackedByteArray::from(&vis_bytes[..n]),
        );
    }
    let rs = RenderingServer::singleton();
    let zero = PackedByteArray::from(&0u32.to_le_bytes()[..]);
    for (layer, params) in self.scatter_layers.iter().zip(layer_params.iter()) {
        rd.buffer_update(
            layer.params_buf.rid(),
            0,
            params.len() as u32,
            &PackedByteArray::from(&params[..]),
        );
        rd.buffer_update(layer.counter_buf.rid(), 0, 4, &zero);
        if layer.cfg.mm_rid.is_valid() {
            let cmd = rs.multimesh_get_command_buffer_rd_rid(layer.cfg.mm_rid);
            if cmd.is_valid() {
                rd.buffer_update(cmd, 4, 4, &zero);
            }
        }
    }
}

pub fn record_scatter_place(
    &self,
    rd: &mut Gd<RenderingDevice>,
    list: i64,
    li: usize,
    chunk_count: u32,
) {
    let Some(layer) = self.scatter_layers.get(li) else { return };
    let max_threads = self.budget * layer.cfg.capacity;
    let threads = (chunk_count * layer.cfg.capacity).min(max_threads);
    let groups = threads.div_ceil(64);
    if groups == 0 {
        return;
    }
    rd.compute_list_bind_compute_pipeline(list, self.scatter_pipeline.rid());
    rd.compute_list_bind_uniform_set(list, layer.place_set.rid(), 0);
    rd.compute_list_dispatch(list, groups, 1, 1);
    rd.compute_list_add_barrier(list);
}

pub fn record_scatter_compact(
    &self,
    rd: &mut Gd<RenderingDevice>,
    list: i64,
    li: usize,
    vis_count: u32,
) {
    let Some(layer) = self.scatter_layers.get(li) else { return };
    if !layer.compact_set.is_valid() {
        return; // compute-only verification: no multimesh to compact into
    }
    let max_threads = self.budget * layer.cfg.capacity;
    let threads = (vis_count * layer.cfg.capacity).min(max_threads);
    let groups = threads.div_ceil(64);
    if groups == 0 {
        return;
    }
    rd.compute_list_bind_compute_pipeline(list, self.compact_pipeline.rid());
    rd.compute_list_bind_uniform_set(list, layer.compact_set.rid(), 0);
    rd.compute_list_dispatch(list, groups, 1, 1);
    rd.compute_list_add_barrier(list);
}

fn create_multimesh(&mut self) {
    let mut rs = RenderingServer::singleton();
    let material: Gd<Material> = StandardMaterial3D::new_gd().upcast();
    let template = reference_chunk_mesh(self.res, &material);
    let multimesh = MultiMesh::new_gd();
    let mm_rid = multimesh.get_rid();
    rs.multimesh_allocate_data_ex(mm_rid, self.budget as i32, MultimeshTransformFormat::TRANSFORM_3D)
        .custom_data_format(true)
        .use_indirect(true)
        .done();
    rs.multimesh_set_mesh(mm_rid, template.get_rid());
    self.mm_rid = mm_rid;
    self.multimesh = Some(multimesh);
    self._template = Some(template);
    self._material = Some(material);
}

pub fn upload_descs(&mut self, rd: &mut Gd<RenderingDevice>, bytes: &[u8], count: u32) {
    if bytes.is_empty() {
        return;
    }
    debug_assert!(
        count <= self.budget,
        "chunk realize count {count} exceeds budget {} — would overrun desc buffer",
        self.budget
    );
    let max = self.budget as usize * std::mem::size_of::<crate::chunk_descriptors::ChunkGpu>();
    let n = bytes.len().min(max);
    rd.buffer_update(self.desc_buf.rid(), 0, n as u32, &PackedByteArray::from(&bytes[..n]));
}

pub fn upload_params(
    &mut self,
    rd: &mut Gd<RenderingDevice>,
    chunk_count: u32,
    terrain: &TerrainGpu,
) {
    let bytes = pack_params(
        self.res,
        self.vpc,
        self.attr_w,
        chunk_count,
        self.tile_res,
        self.bump_enable,
        terrain,
        self.surface_enabled,
        self.surface_height_scale,
    );
    rd.buffer_update(
        self.params_buf.rid(),
        0,
        bytes.len() as u32,
        &PackedByteArray::from(&bytes[..]),
    );
}

pub fn upload_terrain(&mut self, rd: &mut Gd<RenderingDevice>, terrain: &TerrainGpu) {
    let bytes = bytemuck::bytes_of(terrain);
    rd.buffer_update(self.params_buf.rid(), 16, bytes.len() as u32, &PackedByteArray::from(bytes));
}

pub fn upload_surface(
    &mut self,
    rd: &mut Gd<RenderingDevice>,
    slot: u32,
    color_bytes: &[u8],
    height: &[f32],
    normal_bytes: &[u8],
) {
    if slot >= self.budget
        || !self.surface_color_buf.is_valid()
        || !self.surface_height_buf.is_valid()
        || !self.surface_normal_buf.is_valid()
    {
        return;
    }
    let off = slot as u64 * self.tile_texels() * 4;
    if !color_bytes.is_empty() {
        rd.buffer_update(
            self.surface_color_buf.rid(),
            off as u32,
            color_bytes.len() as u32,
            &PackedByteArray::from(color_bytes),
        );
    }
    if !height.is_empty() {
        let h: &[u8] = bytemuck::cast_slice(height);
        rd.buffer_update(
            self.surface_height_buf.rid(),
            off as u32,
            h.len() as u32,
            &PackedByteArray::from(h),
        );
    }
    if !normal_bytes.is_empty() {
        rd.buffer_update(
            self.surface_normal_buf.rid(),
            off as u32,
            normal_bytes.len() as u32,
            &PackedByteArray::from(normal_bytes),
        );
    }
}

pub fn upload_instances(&mut self, rd: &mut Gd<RenderingDevice>, bytes: &[u8], count: u32) {
    let rs = RenderingServer::singleton();
    let buffer = rs.multimesh_get_buffer_rd_rid(self.mm_rid);
    let command = rs.multimesh_get_command_buffer_rd_rid(self.mm_rid);
    if buffer.is_invalid() || command.is_invalid() {
        return;
    }
    if !bytes.is_empty() {
        rd.buffer_update(buffer, 0, bytes.len() as u32, &PackedByteArray::from(bytes));
    }
    let c = count.min(self.budget);
    rd.buffer_update(command, 4, 4, &PackedByteArray::from(&c.to_le_bytes()[..]));
}

pub fn record_realize(&self, rd: &mut Gd<RenderingDevice>, list: i64, vert_threads: u32) {
    // Guard the dispatch against an over-budget batch: clamp to the pool's
    // vertex capacity so the realize can never write past `verts`/`pos_tex`
    // (defensive against the stale-oversized-buffer device-loss shape).
    let max_threads = self.budget * self.vpc;
    debug_assert!(
        vert_threads <= max_threads,
        "chunk realize vert_threads {vert_threads} exceeds pool capacity {max_threads}"
    );
    let vert_threads = vert_threads.min(max_threads);
    let groups = vert_threads.div_ceil(64);
    if groups == 0 {
        return;
    }
    rd.compute_list_bind_compute_pipeline(list, self.pipeline.rid());
    rd.compute_list_bind_uniform_set(list, self.realize_set.rid(), 0);
    rd.compute_list_dispatch(list, groups, 1, 1);
    rd.compute_list_add_barrier(list);
}

pub fn record_bake(&self, rd: &mut Gd<RenderingDevice>, list: i64, texel_threads: u32) {
    let max_threads = (self.budget as u64 * self.tile_texels()).min(u32::MAX as u64) as u32;
    debug_assert!(
        texel_threads <= max_threads,
        "chunk bake texel_threads {texel_threads} exceeds atlas capacity {max_threads}"
    );
    let texel_threads = texel_threads.min(max_threads);
    let groups = texel_threads.div_ceil(64);
    if groups == 0 {
        return;
    }
    rd.compute_list_bind_compute_pipeline(list, self.bake_pipeline.rid());
    rd.compute_list_bind_uniform_set(list, self.bake_set.rid(), 0);
    rd.compute_list_dispatch(list, groups, 1, 1);
    rd.compute_list_add_barrier(list);
}

pub fn upload_custom_params(&self, rd: &mut Gd<RenderingDevice>, chunk_count: u32) {
    if !self.custom_ready() || !self.custom_params_buf.is_valid() {
        return;
    }
    let bytes = crate::custom_surface::pack_params(
        chunk_count.min(self.budget),
        self.tile_res,
        self.custom_water_height,
        self.custom_height_scale,
        &self.custom_user_params,
    );
    rd.buffer_update(
        self.custom_params_buf.rid(),
        0,
        bytes.len() as u32,
        &PackedByteArray::from(&bytes[..]),
    );
}

pub fn record_custom_surface(&self, rd: &mut Gd<RenderingDevice>, list: i64, chunk_count: u32) {
    if !self.custom_ready() {
        return;
    }
    let max_threads = (self.budget as u64 * self.tile_texels()).min(u32::MAX as u64) as u32;
    let threads = ((chunk_count as u64 * self.tile_texels()).min(max_threads as u64)) as u32;
    let groups = threads.div_ceil(64);
    if groups == 0 {
        return;
    }
    rd.compute_list_bind_compute_pipeline(list, self.custom_pipeline.rid());
    rd.compute_list_bind_uniform_set(list, self.custom_set.rid(), 0);
    rd.compute_list_dispatch(list, groups, 1, 1);
    rd.compute_list_add_barrier(list);
}

pub fn compute_pipeline(
    rd: &mut Gd<RenderingDevice>,
    sink: &Arc<dyn RidSink>,
    spirv: &[u8],
    name: &str,
) -> Option<(RdShader, RdPipeline)> {
    if spirv.is_empty() {
        godot_error!("[celestial] {name}: empty SPIR-V — was slangc installed at build time?");
        return None;
    }
    let mut sp = RdShaderSpirv::new_gd();
    sp.set_stage_bytecode(ShaderStage::COMPUTE, &PackedByteArray::from(spirv));
    let shader_rid = rd.shader_create_from_spirv(&sp);
    if !shader_rid.is_valid() {
        godot_error!("[celestial] {name}: shader_create_from_spirv failed");
        return None;
    }
    let shader: RdShader = Owned::new(shader_rid, sink.clone());
    let pipeline_rid = rd.compute_pipeline_create(shader.rid());
    if !pipeline_rid.is_valid() {
        godot_error!("[celestial] {name}: compute_pipeline_create failed");
        return None; // dropping `shader` frees it
    }
    Some((shader, Owned::new(pipeline_rid, sink.clone())))
}

pub fn compute_pipeline_from_glsl(
    rd: &mut Gd<RenderingDevice>,
    sink: &Arc<dyn RidSink>,
    glsl: &str,
    name: &str,
) -> Option<(RdShader, RdPipeline)> {
    let mut src = RdShaderSource::new_gd();
    src.set_language(ShaderLanguage::GLSL);
    src.set_stage_source(ShaderStage::COMPUTE, glsl);
    let Some(spirv) = rd.shader_compile_spirv_from_source_ex(&src).allow_cache(true).done() else {
        godot_error!("[celestial] {name}: shader_compile_spirv_from_source returned null");
        return None;
    };
    let err = spirv.get_stage_compile_error(ShaderStage::COMPUTE);
    if !err.is_empty() {
        godot_error!("[celestial] {name}: GLSL compile error:\n{err}");
        return None;
    }
    let shader_rid = rd.shader_create_from_spirv(&spirv);
    if !shader_rid.is_valid() {
        godot_error!("[celestial] {name}: shader_create_from_spirv failed");
        return None;
    }
    let shader: RdShader = Owned::new(shader_rid, sink.clone());
    let pipeline_rid = rd.compute_pipeline_create(shader.rid());
    if !pipeline_rid.is_valid() {
        godot_error!("[celestial] {name}: compute_pipeline_create failed");
        return None; // dropping `shader` frees it
    }
    Some((shader, Owned::new(pipeline_rid, sink.clone())))
}

pub fn storage_buffer_empty(
    rd: &mut Gd<RenderingDevice>,
    sink: &Arc<dyn RidSink>,
    size: u64,
) -> RdBuffer {
    Owned::new(rd.storage_buffer_create_ex(size as u32).done(), sink.clone())
}

pub fn storage_buffer(
    rd: &mut Gd<RenderingDevice>,
    sink: &Arc<dyn RidSink>,
    bytes: &[u8],
) -> RdBuffer {
    let rid = rd
        .storage_buffer_create_ex(bytes.len() as u32)
        .data(&PackedByteArray::from(bytes))
        .done();
    Owned::new(rid, sink.clone())
}

pub fn attribute_texture(
    rd: &mut Gd<RenderingDevice>,
    sink: &Arc<dyn RidSink>,
    width: u32,
    height: u32,
) -> RdTexture {
    let mut fmt = RdTextureFormat::new_gd();
    fmt.set_format(DataFormat::R16G16B16A16_SFLOAT);
    fmt.set_width(width);
    fmt.set_height(height);
    fmt.set_usage_bits(
        TextureUsageBits::STORAGE_BIT | TextureUsageBits::SAMPLING_BIT,
    );
    Owned::new(rd.texture_create(&fmt, &RdTextureView::new_gd()), sink.clone())
}

pub fn position_texture(
    rd: &mut Gd<RenderingDevice>,
    sink: &Arc<dyn RidSink>,
    width: u32,
    height: u32,
) -> RdTexture {
    let mut fmt = RdTextureFormat::new_gd();
    fmt.set_format(DataFormat::R32G32B32A32_SFLOAT);
    fmt.set_width(width);
    fmt.set_height(height);
    // CAN_COPY_FROM so debug tooling can read the drawn positions back.
    fmt.set_usage_bits(
        TextureUsageBits::STORAGE_BIT
            | TextureUsageBits::SAMPLING_BIT
            | TextureUsageBits::CAN_COPY_FROM_BIT,
    );
    Owned::new(rd.texture_create(&fmt, &RdTextureView::new_gd()), sink.clone())
}

pub fn atlas_texture(
    rd: &mut Gd<RenderingDevice>,
    sink: &Arc<dyn RidSink>,
    width: u32,
    height: u32,
) -> RdTexture {
    let mut fmt = RdTextureFormat::new_gd();
    fmt.set_format(DataFormat::R8G8B8A8_UNORM);
    fmt.set_width(width);
    fmt.set_height(height);
    // CAN_COPY_FROM so the detail tile can be read back / exported for inspection.
    fmt.set_usage_bits(
        TextureUsageBits::STORAGE_BIT
            | TextureUsageBits::SAMPLING_BIT
            | TextureUsageBits::CAN_COPY_FROM_BIT,
    );
    Owned::new(rd.texture_create(&fmt, &RdTextureView::new_gd()), sink.clone())
}

pub fn uniform(utype: UniformType, binding: i32, rid: Rid) -> Gd<RdUniform> {
    let mut u = RdUniform::new_gd();
    u.set_uniform_type(utype);
    u.set_binding(binding);
    u.add_id(rid);
    u
}

impl MainDeviceSink {
    /// Create a sink. `Arc` because every [`Owned`] handle shares it.
    pub fn new() -> Arc<Self> {
        Arc::new_cyclic(|me| Self {
            queue: Mutex::new(Vec::new()),
            scheduled: AtomicBool::new(false),
            me: me.clone(),
        })
    }

    /// Free every queued RID, FIFO. **Render thread only.**
    #[cfg(not(test))]
    fn drain(&self) {
        self.scheduled.store(false, Ordering::SeqCst);
        let rids: Vec<Rid> = std::mem::take(&mut *self.queue.lock().unwrap());
        if rids.is_empty() {
            return;
        }
        let Some(mut rd) = RenderingServer::singleton().get_rendering_device() else {
            return;
        };
        for rid in rids {
            rd.free_rid(rid);
        }
    }

    /// RIDs queued but not yet drained (tests only — there is no Godot server under
    /// `cargo test`, so nothing is ever scheduled).
    #[cfg(test)]
    pub fn pending(&self) -> Vec<Rid> {
        self.queue.lock().unwrap().clone()
    }
}

impl RidSink for MainDeviceSink {
    #[cfg(not(test))]
    fn free(&self, rid: Rid) {
        {
            let mut q = self.queue.lock().unwrap();
            q.push(rid);
        }
        // Schedule the drain exactly once per pending batch. The callable keeps the sink
        // alive until the render thread has run it.
        if !self.scheduled.swap(true, Ordering::SeqCst) {
            let Some(sink) = self.me.upgrade() else {
                self.scheduled.store(false, Ordering::SeqCst);
                return;
            };
            let callable = Callable::from_sync_fn("ces_gpu_free_drain", move |_args| {
                sink.drain();
                Variant::nil()
            });
            RenderingServer::singleton().call_on_render_thread(&callable);
        }
    }

    #[cfg(test)]
    fn free(&self, rid: Rid) {
        // No Godot server under `cargo test`: only enqueue.
        let _ = &self.scheduled;
        self.queue.lock().unwrap().push(rid);
    }
}

pub struct IndirectMultiMesh {
    mm: Gd<MultiMesh>,
    sink: Arc<dyn RidSink>,
}

impl IndirectMultiMesh {
    /// Take ownership of an already-`multimesh_allocate_data`'d indirect multimesh.
    pub fn new(mm: Gd<MultiMesh>, sink: Arc<dyn RidSink>) -> Self {
        Self { mm, sink }
    }
}

impl std::ops::Deref for IndirectMultiMesh {
    type Target = Gd<MultiMesh>;
    fn deref(&self) -> &Self::Target {
        &self.mm
    }
}

impl Drop for IndirectMultiMesh {
    fn drop(&mut self) {
        // Resolve the command buffer HERE rather than at construction: the renderer
        // creates it lazily and can recreate it, so the RID is only knowable now — while
        // the multimesh is still alive, which is precisely why this must happen on drop
        // and not after the `Gd` is released.
        let cmd = RenderingServer::singleton().multimesh_get_command_buffer_rd_rid(self.mm.get_rid());
        if cmd.is_valid() {
            self.sink.free(cmd);
        }
    }
}

#[godot_api]
impl INode3D for CelestialQuadtreeDebug {
    fn ready(&mut self) {
        let mut mi = MeshInstance3D::new_alloc();
        let mut mat = StandardMaterial3D::new_gd();
        mat.set_shading_mode(ShadingMode::UNSHADED);
        mat.set_flag(Flags::ALBEDO_FROM_VERTEX_COLOR, true);
        mat.set_cull_mode(CullMode::DISABLED);
        mi.set_material_override(&mat);
        self.mesh_instance = Some(mi.clone());
        self.base_mut().add_child(&mi);
    }

    fn process(&mut self, _delta: f64) {
        let Some(camera) = self
            .base()
            .get_viewport()
            .and_then(|vp| vp.get_camera_3d())
            .map(|c| c.get_global_position())
        else {
            return;
        };

        let frames = base_face_frames(self.radius);
        let t0 = Instant::now();
        let chunks =
            select_chunks(&frames, camera, self.screen_error, self.chunk_res as u32, self.max_depth as u8, None);
        self.last_select_ms = t0.elapsed().as_secs_f64() * 1000.0;
        self.chunk_count = chunks.len() as i64;

        let t1 = Instant::now();
        let data = build_debug_mesh(&chunks, self.radius, self.chunk_res as u32);
        self.last_realize_ms = t1.elapsed().as_secs_f64() * 1000.0;
        let positions: PackedVector3Array = data.positions.iter().copied().collect();
        let colors: PackedColorArray =
            data.colors.iter().map(|c| Color::from_rgba(c[0], c[1], c[2], 1.0)).collect();
        let indices: PackedInt32Array = data.indices.iter().copied().collect();

        let mut arrays = VarArray::new();
        arrays.resize(ArrayType::MAX.ord() as usize, &Variant::nil());
        arrays.set(ArrayType::VERTEX.ord() as usize, &positions.to_variant());
        arrays.set(ArrayType::COLOR.ord() as usize, &colors.to_variant());
        arrays.set(ArrayType::INDEX.ord() as usize, &indices.to_variant());

        let mut mesh = ArrayMesh::new_gd();
        if !indices.is_empty() {
            mesh.add_surface_from_arrays(PrimitiveType::TRIANGLES, &arrays);
        }
        if let Some(mi) = self.mesh_instance.as_mut() {
            mi.set_mesh(&mesh);
        }

        if let Some(mut vp) = self.base().get_viewport() {
            vp.set_debug_draw(if self.wireframe { DebugDraw::WIREFRAME } else { DebugDraw::DISABLED });
        }
    }
}

#[godot_api]
impl CelestialQuadtreeDebug {
    #[func]
    fn last_select_ms(&self) -> f64 {
        self.last_select_ms
    }

    #[func]
    fn last_realize_ms(&self) -> f64 {
        self.last_realize_ms
    }

    #[func]
    fn chunk_count(&self) -> i64 {
        self.chunk_count
    }
}

#[derive(GodotClass)]
#[class(base = Resource, tool, init)]
pub struct CesScatterLayer {
    base: Base<Resource>,

    /// Display name (e.g. "Grass", "Oak trees"). Mirrored into
    /// `resource_name`, so the inspector's layer array shows it per element —
    /// name your layers instead of hunting through "CesScatterLayer" entries.
    #[var(get = get_layer_name, set = set_layer_name)]
    #[export]
    pub layer_name: GString,
    /// LIVE on/off toggle: a disabled layer draws nothing but keeps its cached
    /// GPU placement, so re-enabling is instant (compact-only update).
    #[var(get = get_enabled, set = set_enabled)]
    #[export]
    #[init(val = true)]
    pub enabled: bool,
    /// Fraction of the lattice candidates actually drawn, 0..1 — the thinning knob
    /// (LIVE: only the gather pass re-runs, so it is free to drag). It never adds
    /// instances beyond what `lod_level`/`instances_per_cell` place; 1.0 draws them
    /// all. Default 0.5.
    #[var(get = get_density, set = set_density)]
    #[export(range = (0.0, 1.0, 0.005))]
    #[init(val = 0.5)]
    pub density: f32,
    /// The mesh every instance of this layer draws. **No mesh ⇒ the layer is
    /// INACTIVE**: it is skipped entirely (no GPU placement, nothing drawn), which is
    /// also how a layer you are not using costs nothing. For grass, assign
    /// `res://addons/celestialsim/grass_blade.tres` (regenerable via
    /// `CesScatterLayer.make_grass_blade_mesh()`).
    #[var(get = get_mesh, set = set_mesh)]
    #[export]
    pub mesh: Option<Gd<Mesh>>,
    /// Base scale applied to every instance (on top of a ±20% per-instance
    /// jitter), so you can size a mesh without re-authoring it. 1.0 = the
    /// mesh's native size.
    #[var(get = get_scale, set = set_scale)]
    #[export(range = (0.01, 100.0, 0.01))]
    #[init(val = 1.0)]
    pub scale: f32,
    /// LIVE lower bound on normalized terrain height (0..1) where this layer may
    /// appear. Default 0.45 = the default sea level, so nothing scatters
    /// underwater; drop to 0 to allow it. (Terrain height is normalized: ~0.45
    /// is the shoreline, 1.0 the highest peaks.)
    #[var(get = get_min_height, set = set_min_height)]
    #[export(range = (0.0, 1.0, 0.01))]
    #[init(val = 0.45)]
    pub min_height: f32,
    /// LIVE upper bound on normalized terrain height (0..1). Default 1.0 = no
    /// upper limit; lower it to keep this layer off the mountain tops.
    #[var(get = get_max_height, set = set_max_height)]
    #[export(range = (0.0, 1.0, 0.01))]
    #[init(val = 1.0)]
    pub max_height: f32,
    /// LOD level the candidates are keyed to — the fineness of the stable world
    /// lattice. Higher = denser and shorter-range; the layer only appears on
    /// terrain chunks at depth `>= lod_level - 3` (per-slot capacity bound), so
    /// this is the single knob for both density and reach. Instances never move
    /// when chunks split/merge. Rough starting points: ~12 for grass, ~6 for trees.
    /// Editing it re-places every resident chunk. Default 9 (range 0–20).
    #[var(get = get_lod_level, set = set_lod_level)]
    #[export(range = (0.0, 20.0, 1.0))]
    #[init(val = 9)]
    pub lod_level: i64,
    /// Candidates placed per lattice cell (K) — jitters several instances into one
    /// cell instead of one per cell, which breaks up the grid look. Costs GPU memory:
    /// the per-slot candidate pool is `K * 64` entries. Changing it rebuilds the GPU
    /// job. Default 4 (range 1–64).
    #[var(get = get_instances_per_cell, set = set_instances_per_cell)]
    #[export(range = (1.0, 64.0, 1.0))]
    #[init(val = 4)]
    pub instances_per_cell: i64,
    /// Hard cap on the instances this layer draws — the size of its `MultiMesh` pool.
    /// The gather pass stops appending once it is hit (so instances go missing rather
    /// than the frame blowing up), and the buffer is sized for it, so raising it costs
    /// VRAM. Changing it rebuilds the GPU job. Default 100000.

pub fn grass_blade_mesh() -> Gd<ArrayMesh> {
    let mut verts = PackedVector3Array::new();
    let mut normals = PackedVector3Array::new();
    let mut colors = PackedColorArray::new();

    let (sin_a, cos_a) = ROUND_ANGLE.sin_cos();
    let n_rows = ROWS.len();
    for (row, &(y, hw, bend)) in ROWS.iter().enumerate() {
        let t = row as f32 / (n_rows - 1) as f32;
        // Face normal tilts from +Z (base) toward +Y (tip) so tips face the sky.
        let forward = (Vector3::new(0.0, 0.0, 1.0).lerp(Vector3::new(0.0, 1.0, 0.0), t)).normalized();
        let tangent = Vector3::new(1.0, 0.0, 0.0);
        // Edge normals fan ±ROUND_ANGLE around the face normal (cylinder fake).
        let left_n = (forward * cos_a - tangent * sin_a).normalized();
        let right_n = (forward * cos_a + tangent * sin_a).normalized();
        if row + 1 < n_rows {
            verts.push(Vector3::new(-hw, y, bend));
            verts.push(Vector3::new(hw, y, bend));
            normals.push(left_n);
            normals.push(right_n);
            colors.push(COLORS[row]);
            colors.push(COLORS[row]);
        } else {
            verts.push(Vector3::new(0.0, y, bend)); // tip
            normals.push(forward);
            colors.push(COLORS[row]);
        }
    }

    // Two tris per quad band between consecutive rows; the top band fans to the
    // single tip vertex. Row r's pair = (2r, 2r+1); tip = 2*(n_rows-1).
    let mut indices: Vec<i32> = Vec::new();
    for row in 0..n_rows - 1 {
        let a = (2 * row) as i32; // left
        let b = a + 1; // right
        if row + 2 < n_rows {
            let c = (2 * (row + 1)) as i32; // next left
            let d = c + 1; // next right
            indices.extend_from_slice(&[a, c, b, b, c, d]);
        } else {
            let tip = (2 * (n_rows - 1)) as i32;
            indices.extend_from_slice(&[a, tip, b]);
        }
    }
    let indices: PackedInt32Array = indices.into_iter().collect();

    let mut arrays = VarArray::new();
    arrays.resize(ArrayType::MAX.ord() as usize, &Variant::nil());
    arrays.set(ArrayType::VERTEX.ord() as usize, &verts.to_variant());
    arrays.set(ArrayType::NORMAL.ord() as usize, &normals.to_variant());
    arrays.set(ArrayType::COLOR.ord() as usize, &colors.to_variant());
    arrays.set(ArrayType::INDEX.ord() as usize, &indices.to_variant());

    let mut material = StandardMaterial3D::new_gd();
    material.set_flag(Flags::ALBEDO_FROM_VERTEX_COLOR, true);
    material.set_cull_mode(CullMode::DISABLED);
    material.set_roughness(0.85);
    material.set_specular(0.3);

    let mut mesh = ArrayMesh::new_gd();
    mesh.add_surface_from_arrays(PrimitiveType::TRIANGLES, &arrays);
    mesh.surface_set_material(0, &material.upcast::<godot::classes::Material>());
    mesh
}

impl TileViewerGpu {
    /// Build the pipeline + output texture + params buffer + uniform set. Idempotent.
    fn ensure_ready(&mut self, rd: &mut Gd<RenderingDevice>, width: u32) -> bool {
        if self.init_failed {
            return false;
        }
        if self.built {
            return true;
        }
        let sink = self.sink.clone();
        let Some((shader, pipeline)) =
            device::compute_pipeline(rd, &sink, TILE_VIEWER_SPV, "TileViewer")
        else {
            self.init_failed = true;
            return false;
        };
        self.shader = shader;
        self.pipeline = pipeline;
        // rgba8 STORAGE|SAMPLING|CAN_COPY_FROM square textures (atlas_texture fits).
        self.tex = device::atlas_texture(rd, &sink, width, width);
        self.nrm = device::atlas_texture(rd, &sink, width, width);
        self.params_buf =
            device::storage_buffer(rd, &sink, &vec![0u8; std::mem::size_of::<TileViewerParams>()]);
        let uniforms: Array<Gd<RdUniform>> = [
            device::uniform(UniformType::STORAGE_BUFFER, 0, self.params_buf.rid()),
            device::uniform(UniformType::IMAGE, 1, self.tex.rid()),
            device::uniform(UniformType::IMAGE, 2, self.nrm.rid()),
        ]
        .into_iter()
        .collect();
        self.set = Owned::new(rd.uniform_set_create(&uniforms, self.shader.rid(), 0), sink);
        self.width = width;
        self.built = true;
        true
    }

    /// Upload params and record a `W*W`-thread bake into the output texture.
    fn dispatch(&mut self, rd: &mut Gd<RenderingDevice>, params: &TileViewerParams) {
        let bytes = bytemuck::bytes_of(params);
        rd.buffer_update(
            self.params_buf.rid(),
            0,
            bytes.len() as u32,
            &PackedByteArray::from(bytes),
        );
        let total = self.width.saturating_mul(self.width);
        let groups = total.div_ceil(64);
        if groups == 0 {
            return;
        }
        let list = rd.compute_list_begin();
        rd.compute_list_bind_compute_pipeline(list, self.pipeline.rid());
        rd.compute_list_bind_uniform_set(list, self.set.rid(), 0);
        rd.compute_list_dispatch(list, groups, 1, 1);
        rd.compute_list_end();
    }
}

#[derive(GodotClass)]
#[class(base = RefCounted, no_init)]
pub struct TileViewerJob {
    base: Base<RefCounted>,
    gpu: TileViewerGpu,
    /// The view to bake on the next render-thread run.
    params: TileViewerParams,
    /// Set by `set_view`, drained by `run`.
    pending: bool,
}

impl TileViewerJob {
    fn create() -> Gd<Self> {
        Gd::from_init_fn(|base| Self {
            base,
            gpu: TileViewerGpu::default(),
            params: TileViewerParams::zeroed(),
            pending: false,
        })
    }

    /// The colour output texture RID (`Invalid` until the first run builds it).
    fn tex_rid(&self) -> Rid {
        self.gpu.tex.rid()
    }

    /// The normal output texture RID (`Invalid` until the first run builds it).
    fn nrm_rid(&self) -> Rid {
        self.gpu.nrm.rid()
    }
}

#[godot_api]
impl TileViewerJob {
    /// Render-thread entry point: ensure resources, then bake the pending view.
    #[func]
    fn run(&mut self) {
        if !self.pending {
            return;
        }
        let rs = RenderingServer::singleton();
        let Some(mut rd) = rs.get_rendering_device() else { return };
        let w = self.params.width;
        if !self.gpu.ensure_ready(&mut rd, w) {
            return; // retry next request
        }
        let params = self.params;
        self.gpu.dispatch(&mut rd, &params);
        self.pending = false;
    }
}

