fn map_inner(s: &str) -> String {
    let s = s.trim();
    if let Some(inner) = s.strip_prefix("Option<").and_then(|x| x.strip_suffix('>')) {
        return map_inner(inner);
    }
    if let Some(inner) = s.strip_prefix("Gd<").and_then(|x| x.strip_suffix('>')) {
        return map_inner(inner);
    }
    match s {
        "()" => "void",
        "bool" => "bool",
        "i8" | "i16" | "i32" | "i64" | "u8" | "u16" | "u32" | "u64" | "usize" | "isize" => "int",
        "f32" | "f64" => "float",
        "GString" | "String" | "StringName" => "String",
        "VarDictionary" | "Dictionary" => "Dictionary",
        "VarArray" | "Array" => "Array",
        other => other,
    }
    .to_string()
}

pub fn alloc_texture_array(width: i32, height: i32, layers: i32, _srgb: bool) -> Option<u32> {
    let g = gl()?;
    unsafe {
        while (g.get_error)() != 0 {}
        let mut tex: u32 = 0;
        (g.gen_textures)(1, &mut tex);
        if tex == 0 || (g.get_error)() != 0 {
            return None;
        }
        (g.bind_texture)(GL_TEXTURE_2D_ARRAY, tex);
        (g.tex_parameteri)(GL_TEXTURE_2D_ARRAY, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
        (g.tex_parameteri)(GL_TEXTURE_2D_ARRAY, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
        (g.tex_parameteri)(GL_TEXTURE_2D_ARRAY, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
        (g.tex_parameteri)(GL_TEXTURE_2D_ARRAY, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);

        // Prefer immutable storage (matches Unity). A single mip level; pin BASE/MAX level so the
        // texture is mip-complete for whatever sampler state the compositor binds it with.
        let immutable = match g.tex_storage_3d {
            Some(tex_storage_3d) => {
                (g.tex_parameteri)(GL_TEXTURE_2D_ARRAY, GL_TEXTURE_BASE_LEVEL, 0);
                (g.tex_parameteri)(GL_TEXTURE_2D_ARRAY, GL_TEXTURE_MAX_LEVEL, 0);
                tex_storage_3d(
                    GL_TEXTURE_2D_ARRAY,
                    1,
                    GL_RGB10_A2 as u32,
                    width,
                    height,
                    layers,
                );
                if (g.get_error)() == 0 {
                    true
                } else {
                    // Immutable allocation failed (e.g. format/driver quirk): drain the error and
                    // retry mutable on the same, still-mutable texture object.
                    while (g.get_error)() != 0 {}
                    false
                }
            }
            None => false,
        };
        if !immutable {
            (g.tex_image_3d)(
                GL_TEXTURE_2D_ARRAY,
                0,
                GL_RGB10_A2,
                width,
                height,
                layers,
                0,
                GL_RGBA,
                GL_UNSIGNED_INT_2_10_10_10_REV,
                std::ptr::null(),
            );
        }
        (g.bind_texture)(GL_TEXTURE_2D_ARRAY, 0);
        let err = (g.get_error)();
        if err != 0 {
            godot::global::godot_warn!(
                "[xreal] alloc_texture_array {width}x{height}x{layers} immutable={immutable} gl_err={err}"
            );
            (g.delete_textures)(1, &tex);
            return None;
        }
        godot::global::godot_print!(
            "[xreal] alloc_texture_array {width}x{height}x{layers} immutable={immutable} tex={tex}"
        );
        Some(tex)
    }
}

unsafe fn probed_src_format(g: &Gl, src: u32) -> u32 {
    if PROBE_LOG
        .compare_exchange(0, 1, Ordering::Relaxed, Ordering::Relaxed)
        .is_ok()
    {
        if let Some(get_tex_level_parameteriv) = g.get_tex_level_parameteriv {
            let mut prev_tex2d: i32 = 0;
            (g.get_integerv)(GL_TEXTURE_BINDING_2D, &mut prev_tex2d);
            let mut src_fmt: i32 = 0;
            (g.bind_texture)(GL_TEXTURE_2D, src);
            get_tex_level_parameteriv(GL_TEXTURE_2D, 0, GL_TEXTURE_INTERNAL_FORMAT, &mut src_fmt);
            (g.bind_texture)(GL_TEXTURE_2D, prev_tex2d as u32);
            let err = (g.get_error)();
            if err == 0 {
                PROBED_SRC_FMT.store(src_fmt as u32, Ordering::Relaxed);
            }
            godot::global::godot_print!(
                "[xreal] eye-src probe: src={src} internal_format={src_fmt:#x} gl_err={err} \
                 (direct copy {})",
                if src_fmt == GL_RGB10_A2 && err == 0 {
                    "enabled: matches eye-texture format"
                } else {
                    "disabled: eye textures are RGB10_A2, will convert via blit"
                }
            );
        } else {
            godot::global::godot_print!(
                "[xreal] eye-src probe: glGetTexLevelParameteriv unavailable (blit path)"
            );
        }
    }
    PROBED_SRC_FMT.load(Ordering::Relaxed)
}

pub fn fill_texture(tex: u32, r: f32, g_: f32, b: f32) {
    let Some(g) = gl() else { return };
    if tex == 0 {
        return;
    }
    unsafe {
        while (g.get_error)() != 0 {}
        let mut prev_draw_fbo: i32 = 0;
        (g.get_integerv)(GL_DRAW_FRAMEBUFFER_BINDING, &mut prev_draw_fbo);
        let scissor_was_on = (g.is_enabled)(GL_SCISSOR_TEST) != 0;

        let fbo = scratch_fbo(g, 0);
        (g.bind_framebuffer)(GL_DRAW_FRAMEBUFFER, fbo);
        (g.framebuffer_texture_2d)(
            GL_DRAW_FRAMEBUFFER,
            GL_COLOR_ATTACHMENT0,
            GL_TEXTURE_2D,
            tex,
            0,
        );
        let status = (g.check_framebuffer_status)(GL_DRAW_FRAMEBUFFER);
        if status == GL_FRAMEBUFFER_COMPLETE {
            if scissor_was_on {
                (g.disable)(GL_SCISSOR_TEST);
            }
            (g.clear_color)(r, g_, b, 1.0);
            (g.clear)(GL_COLOR_BUFFER_BIT);
            if scissor_was_on {
                (g.enable)(GL_SCISSOR_TEST);
            }
        }
        let gl_err = (g.get_error)();
        // Detach and restore the previous draw FBO.
        (g.framebuffer_texture_2d)(
            GL_DRAW_FRAMEBUFFER,
            GL_COLOR_ATTACHMENT0,
            GL_TEXTURE_2D,
            0,
            0,
        );
        (g.bind_framebuffer)(GL_DRAW_FRAMEBUFFER, prev_draw_fbo as u32);

        if FILL_LOG_COUNT.fetch_add(1, Ordering::Relaxed) < 4 {
            godot::global::godot_print!(
                "[xreal] fill_texture tex={tex}: fbo_status={status:#x} complete={} \
                 prev_fbo={prev_draw_fbo} gl_err={gl_err}",
                status == GL_FRAMEBUFFER_COMPLETE
            );
        }
    }
}

pub fn blit_texture(src: u32, src_w: i32, src_h: i32, dst: u32, dst_w: i32, dst_h: i32) {
    let Some(g) = gl() else { return };
    if src == 0 || dst == 0 {
        return;
    }
    unsafe {
        // Preferred path: identical formats (probed) → ONE exact copy, no FBO/state churn.
        if let Some(copy_image_sub_data) = g.copy_image_sub_data {
            if src_w == dst_w
                && src_h == dst_h
                && probed_src_format(g, src) == GL_RGB10_A2 as u32
                && !DIRECT_COPY_2D_BROKEN.load(Ordering::Relaxed)
            {
                while (g.get_error)() != 0 {}
                copy_image_sub_data(
                    src,
                    GL_TEXTURE_2D,
                    0,
                    0,
                    0,
                    0,
                    dst,
                    GL_TEXTURE_2D,
                    0,
                    0,
                    0,
                    0,
                    dst_w,
                    dst_h,
                    1,
                );
                let err = (g.get_error)();
                if BLIT2D_LOG.fetch_add(1, Ordering::Relaxed) < 8 {
                    godot::global::godot_print!(
                        "[xreal] direct_copy_2d dst={dst} src={src} {dst_w}x{dst_h}: gl_err={err}"
                    );
                }
                if err == 0 {
                    return;
                }
                // Failed — remember and fall through to the blit below.
                DIRECT_COPY_2D_BROKEN.store(true, Ordering::Relaxed);
            }
        }

        let mut prev_draw: i32 = 0;
        let mut prev_read: i32 = 0;
        (g.get_integerv)(GL_DRAW_FRAMEBUFFER_BINDING, &mut prev_draw);
        (g.get_integerv)(GL_READ_FRAMEBUFFER_BINDING, &mut prev_read);

        let read_fbo = scratch_fbo(g, 1);
        let draw_fbo = scratch_fbo(g, 0);
        (g.bind_framebuffer)(GL_READ_FRAMEBUFFER, read_fbo);
        (g.framebuffer_texture_2d)(
            GL_READ_FRAMEBUFFER,
            GL_COLOR_ATTACHMENT0,
            GL_TEXTURE_2D,
            src,
            0,
        );
        (g.bind_framebuffer)(GL_DRAW_FRAMEBUFFER, draw_fbo);
        (g.framebuffer_texture_2d)(
            GL_DRAW_FRAMEBUFFER,
            GL_COLOR_ATTACHMENT0,
            GL_TEXTURE_2D,
            dst,
            0,
        );

        let read_ok = (g.check_framebuffer_status)(GL_READ_FRAMEBUFFER) == GL_FRAMEBUFFER_COMPLETE;
        let draw_ok = (g.check_framebuffer_status)(GL_DRAW_FRAMEBUFFER) == GL_FRAMEBUFFER_COMPLETE;
        if read_ok && draw_ok {
            // Straight copy (no Y-flip): the SubViewport render target and the eye texture share
            // GL bottom-left origin, matching blit_default_framebuffer (flipping showed upside-down).
            (g.blit_framebuffer)(
                0,
                0,
                src_w,
                src_h,
                0,
                0,
                dst_w,
                dst_h,
                GL_COLOR_BUFFER_BIT,
                GL_LINEAR as u32,
            );
        }

        (g.framebuffer_texture_2d)(
            GL_READ_FRAMEBUFFER,
            GL_COLOR_ATTACHMENT0,
            GL_TEXTURE_2D,
            0,
            0,
        );
        (g.framebuffer_texture_2d)(
            GL_DRAW_FRAMEBUFFER,
            GL_COLOR_ATTACHMENT0,
            GL_TEXTURE_2D,
            0,
            0,
        );
        (g.bind_framebuffer)(GL_READ_FRAMEBUFFER, prev_read as u32);
        (g.bind_framebuffer)(GL_DRAW_FRAMEBUFFER, prev_draw as u32);
    }
}

pub fn ensure_enabled() {
    if HAND_ENABLED.load(Ordering::Relaxed) {
        return;
    }
    let lib_base = crate::signal_guard::lib_base();
    if lib_base == 0 {
        return;
    }
    unsafe {
        let get_im: FnGetInputManager = std::mem::transmute(lib_base + OFF_GET_INPUT_MANAGER);
        let input_manager = get_im();
        if input_manager.is_null() {
            return;
        }
        let perception = (input_manager.add(IM_PERCEPTION_PTR) as *const *mut u8).read();
        if perception.is_null() {
            return;
        }
        let started = perception.add(NP_STARTED).read();
        let session = (perception.add(NP_SESSION) as *const u64).read();
        let config = (perception.add(NP_CONFIG) as *const u64).read();
        if started == 0 || session == 0 || config == 0 {
            return; // perception not fully brought up yet — retry next frame
        }
        let set_enabled: FnSetHandTrackingEnabled =
            std::mem::transmute(lib_base + OFF_SET_HAND_TRACKING_ENABLED);
        set_enabled(perception, true);
        HAND_ENABLED.store(true, Ordering::Relaxed);
        godot::global::godot_print!(
            "[xreal] hand tracking enabled (NativePerception::SetHandTrackingEnabled, session={session:#x} config={config:#x})"
        );
    }
}

fn make_tracker(name: &str, hand: TrackerHand) -> Gd<XrHandTracker> {
    let mut tracker = XrHandTracker::new_gd();
    tracker.set_tracker_name(name);
    tracker.set_tracker_hand(hand);
    tracker
}

fn feed_tracker(tracker: &mut Gd<XrHandTracker>, snapshot: Option<HandSnapshot>) {
    let flags = hand_joint_flags_all();
    match snapshot {
        Some(s) if s.tracked => {
            tracker.set_has_tracking_data(true);
            for (i, joint) in GODOT_JOINTS.iter().enumerate() {
                tracker.set_hand_joint_transform(*joint, s.joints[i]);
                tracker.set_hand_joint_flags(*joint, flags);
            }
        }
        _ => tracker.set_has_tracking_data(false),
    }
}

fn create_rgba_textures(&self, count: u32, width: i32, height: i32) -> Result<Vec<u32>, u32> {
    let mut textures = vec![0; count as usize];
    unsafe {
        while (self.get_error)() != 0 {}
        (self.gen_textures)(count as i32, textures.as_mut_ptr());
        if let Some(error) = self.take_gl_error("glGenTextures") {
            return Err(error);
        }
        godot::global::godot_print!(
            "[xreal] GL texture probe: generated count={}, first_id={}",
            textures.len(),
            textures.first().copied().unwrap_or_default()
        );
        for (index, texture) in textures.iter().enumerate() {
            (self.bind_texture)(GL_TEXTURE_2D, *texture);
            if let Some(error) = self.take_gl_error("glBindTexture") {
                (self.delete_textures)(textures.len() as i32, textures.as_ptr());
                return Err(error);
            }
            (self.tex_parameteri)(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
            if let Some(error) = self.take_gl_error("glTexParameteri MIN_FILTER") {
                (self.delete_textures)(textures.len() as i32, textures.as_ptr());
                return Err(error);
            }
            (self.tex_parameteri)(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
            if let Some(error) = self.take_gl_error("glTexParameteri MAG_FILTER") {
                (self.delete_textures)(textures.len() as i32, textures.as_ptr());
                return Err(error);
            }
            (self.tex_parameteri)(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
            if let Some(error) = self.take_gl_error("glTexParameteri WRAP_S") {
                (self.delete_textures)(textures.len() as i32, textures.as_ptr());
                return Err(error);
            }
            (self.tex_parameteri)(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
            if let Some(error) = self.take_gl_error("glTexParameteri WRAP_T") {
                (self.delete_textures)(textures.len() as i32, textures.as_ptr());
                return Err(error);
            }
            (self.tex_image_2d)(
                GL_TEXTURE_2D,
                0,
                GL_RGBA as i32,
                width,
                height,
                0,
                GL_RGBA,
                GL_UNSIGNED_BYTE,
                std::ptr::null(),
            );
            if let Some(error) = self.take_gl_error("glTexImage2D") {
                godot::global::godot_print!(
                    "[xreal] GL texture probe failed at texture_index={index}, \
                     texture_id={texture}, size={}x{}",
                    width,
                    height
                );
                (self.delete_textures)(textures.len() as i32, textures.as_ptr());
                return Err(error);
            }
        }
        (self.bind_texture)(GL_TEXTURE_2D, 0);
        if let Some(error) = self.take_gl_error("glBindTexture reset") {
            if !textures.is_empty() {
                (self.delete_textures)(textures.len() as i32, textures.as_ptr());
            }
            return Err(error);
        }
    }
    Ok(textures)
}

unsafe fn take_gl_error(&self, label: &str) -> Option<u32> {
    let error = (self.get_error)();
    if error == 0 {
        return None;
    }
    godot::global::godot_print!("[xreal] GL texture probe: {label} -> error {error}");
    Some(error)
}

fn create_swapchain_probe(&self, rendering: NrHandle) -> Result<NrSwapchainProbe, i32> {
    let mut buffer_spec: NrHandle = 0;
    let create_spec_status = unsafe { (self.buffer_spec_create)(rendering, &mut buffer_spec) };
    if create_spec_status != 0 {
        return Err(create_spec_status);
    }
    if buffer_spec == 0 {
        return Err(-20);
    }

    // RE / unverified: Unity logs CreateBufferSpec: 1968 1134 on XREAL One Pro.
    let set_size_status =
        unsafe { (self.buffer_spec_set_size)(rendering, buffer_spec, 1968, 1134) };
    if set_size_status != 0 {
        let _ = unsafe { (self.buffer_spec_destroy)(rendering, buffer_spec) };
        return Err(set_size_status);
    }

    // RE / unverified: Unity creates non-MSAA textures in the inspected GLES path.
    let set_samples_status =
        unsafe { (self.buffer_spec_set_samples)(rendering, buffer_spec, 1) };
    if set_samples_status != 0 {
        godot::global::godot_print!(
            "[xreal] NRBufferSpecSetSamples(1) returned {set_samples_status}"
        );
    }

    // Try create flags = 1 to enable Android Surface mode for NRSwapchainCreateAndroidSurface.
    // Without this flag, calling NRSwapchainCreateAndroidSurface aborts with an assertion.
    let set_flags_status =
        unsafe { (self.buffer_spec_set_create_flags)(rendering, buffer_spec, 1) };
    godot::global::godot_print!("[xreal] NRBufferSpecSetCreateFlags(1) -> {set_flags_status}");

    let mut swapchain: NrHandle = 0;
    let create_swapchain_status =
        unsafe { (self.swapchain_create_ex)(rendering, buffer_spec, &mut swapchain) };
    if create_swapchain_status != 0 {
        let _ = unsafe { (self.buffer_spec_destroy)(rendering, buffer_spec) };
        return Err(create_swapchain_status);
    }
    if swapchain == 0 {
        let _ = unsafe { (self.buffer_spec_destroy)(rendering, buffer_spec) };
        return Err(-21);
    }

    let mut recommend_count = 0;
    let recommend_status = unsafe {
        (self.swapchain_get_recommend_buffer_count)(rendering, swapchain, &mut recommend_count)
    };

    if recommend_status != 0 {
        let _ = unsafe { (self.swapchain_destroy)(rendering, swapchain) };
        let _ = unsafe { (self.buffer_spec_destroy)(rendering, buffer_spec) };
        return Err(recommend_status);
    }
    Ok(NrSwapchainProbe {
        buffer_spec,
        swapchain,
        recommend_count,
    })
}

fn create_viewport_probe(
    &self,
    rendering: NrHandle,
    swapchain: NrHandle,
    target_component: i32,
) -> Result<NrHandle, i32> {
    let mut viewport: NrHandle = 0;
    let create_status = unsafe { (self.viewport_create)(rendering, &mut viewport) };
    if create_status != 0 {
        return Err(create_status);
    }
    if viewport == 0 {
        return Err(-30);
    }

    let set_swapchain_status =
        unsafe { (self.viewport_set_swapchain)(rendering, viewport, swapchain) };
    if set_swapchain_status != 0 {
        let _ = unsafe { (self.viewport_destroy)(rendering, viewport) };
        return Err(set_swapchain_status);
    }

    let source_uv = NrRectf {
        x: 0.0,
        y: 0.0,
        width: 1.0,
        height: 1.0,
    };
    // RE / unverified: approximate one-eye FOV angles in radians from One Pro
    // calibration logs (1920x1080, fx/fy around 2190/2215). The exact order/units
    // still need confirmation.
    let source_fov = NrFov4f {
        left: -0.414,
        right: 0.414,
        up: 0.239,
        down: -0.239,
    };
    let transform = NrTransform {
        qx: 0.0,
        qy: 0.0,
        qz: 0.0,
        qw: 1.0,
        px: 0.0,
        py: 0.0,
        pz: 0.0,
    };
    let set_type_status = unsafe { (self.viewport_set_type)(rendering, viewport, 0) };
    let set_target_status =
        unsafe { (self.viewport_set_target_component)(rendering, viewport, target_component) };
    let set_transform_status = unsafe {
        (self.viewport_set_transform)(
            rendering,
            viewport,
            &transform as *const _ as *const c_void,
        )
    };
    let set_uv_status = unsafe {
        (self.viewport_set_source_uv)(
            rendering,
            viewport,
            &source_uv as *const _ as *const c_void,
        )
    };
    let set_fov_status = unsafe {
        (self.viewport_set_source_fov)(
            rendering,
            viewport,
            &source_fov as *const _ as *const c_void,
        )
    };
    let set_near_far_status =
        unsafe { (self.viewport_set_scene_near_far)(rendering, viewport, 0.1, 1000.0) };
    let set_flags_status = unsafe { (self.viewport_set_flags)(rendering, viewport, 0) };
    godot::global::godot_print!(
        "[xreal] NR viewport config: type={set_type_status}, target={set_target_status}, \
         transform={set_transform_status}, uv={set_uv_status}, fov={set_fov_status}, \
         near_far={set_near_far_status}, flags={set_flags_status}, \
         target_component={target_component}"
    );
    Ok(viewport)
}

fn probe_frame_compose(
    &self,
    rendering: NrHandle,
    viewports: &[NrHandle],
    gl_texture_ids: &[u32],
) -> Result<(), i32> {
    use std::os::raw::c_void;

    let mut frame: NrHandle = 0;
    let create_status = unsafe { (self.frame_create)(rendering, &mut frame) };
    godot::global::godot_print!(
        "[xreal] NR frame probe: Create -> status={create_status}, frame={frame}"
    );
    if frame == 0 {
        return Err(-4000 - create_status);
    }

    if !gl_texture_ids.is_empty() {
        let ptrs: Vec<*const c_void> = gl_texture_ids
            .iter()
            .map(|id| (*id as usize) as *const c_void)
            .collect();
        let set_status = unsafe {
            (self.frame_set_color_textures)(rendering, frame, ptrs.as_ptr(), ptrs.len() as u32)
        };
        godot::global::godot_print!(
            "[xreal] NR frame probe: SetColorTextures(count={}) -> {set_status}",
            ptrs.len()
        );
        if set_status != 0 {
            let _ = unsafe { (self.frame_destroy)(rendering, frame) };
            return Err(-4100 - set_status);
        }
    }

    // viewport indices are 1-based (target_component: 1=left, 2=right)
    for (index, viewport) in viewports.iter().enumerate() {
        let vp_idx = (index + 1) as u32;
        let set_viewport_status =
            unsafe { (self.frame_set_buffer_viewport)(rendering, frame, vp_idx, *viewport) };
        if set_viewport_status != 0 {
            let _ = unsafe { (self.frame_destroy)(rendering, frame) };
            return Err(-4200 - set_viewport_status);
        }
    }

    let compose_status = unsafe { (self.frame_compose)(rendering, frame) };
    let destroy_status = unsafe { (self.frame_destroy)(rendering, frame) };
    if compose_status != 0 {
        return Err(-4300 - compose_status);
    }
    if destroy_status != 0 {
        return Err(-4400 - destroy_status);
    }
    Ok(())
}

pub fn display_manager_submit_frame_probe(&mut self) -> String {
    let desc = match self.display_manager_desc_ptr {
        Some(d) => d,
        None => return "no desc_ptr (plugin lib not loaded)".into(),
    };

    // Read the gate byte BEFORE populate to see its initial value.
    let gate_byte_before = unsafe { *(desc as *const u8).add(0x10) };

    // Call PopulateNextFrameDesc with the global UnityXRNextFrameDesc static.
    // This writes a non-zero render-pass indicator to desc+0x10 (gate byte = 0xa6
    // on XREAL One Pro) and populates render-pass / texture fields at various offsets.
    let populate_status =
        crate::unity_plugin::populate_registered_display_frame_desc_with_ptr(desc);

    let gate_byte = unsafe { *(desc as *const u8).add(0x10) };
    let read_u64_at = |off: usize| -> u64 { unsafe { *(desc as *const u64).byte_add(off) } };
    godot::global::godot_print!(
        "[xreal] DisplayManager desc gate_byte(+0x10): before={gate_byte_before:#04x} \
         after={gate_byte:#04x} (populate_status={populate_status})"
    );
    // Log key offsets from the desc that look like texture/swapchain handles or frame counts.
    godot::global::godot_print!(
        "[xreal] desc fields: +0x08={:#018x} +0x18={:#018x} +0x24={:#018x} +0x28={:#018x} \
         +0x30={:#018x} +0x38={:#018x} +0x3f0={:#018x} +0x410={:#018x} +0x450={:#018x} \
         +0x580={:#018x}",
        read_u64_at(0x08),
        read_u64_at(0x18),
        read_u64_at(0x24),
        read_u64_at(0x28),
        read_u64_at(0x30),
        read_u64_at(0x38),
        read_u64_at(0x3f0),
        read_u64_at(0x410),
        read_u64_at(0x450),
        read_u64_at(0x580)
    );

    // DO NOT call CreateFrame() or SubmitCurrentFrame() here:
    // DisplayManager+0x120 is managed by the XREAL SDK's own rendering thread (GLThread).
    // Calling CreateFrame tries to destroy the SDK's live frame via NativeRendering::DestroyFrame,
    // which fails (frame is locked by the render thread) and crashes in LogHelper::Error
    // (fault addr 0xb9a40998bac55c8a — a valid SDK frame handle passed to fprintf-style log).
    // Device-confirmed: both CreateFrame and SubmitCurrentFrame crash with SIGSEGV at
    // the DestroyFrame path when the SDK's rendering thread owns DisplayManager+0x120.
    //
    // Next step: hook into the SDK's rendering loop properly by providing Godot textures
    // to the SetBufferViewport path BEFORE the SDK calls SubmitCurrentFrame on its own thread.

    format!(
        "gate_before={gate_byte_before:#x} populate={populate_status} gate_after={gate_byte:#x}"
    )
}

#[allow(dead_code)]
pub fn unity_display_manager_probe(&mut self) -> Result<bool, &'static str> {
    let initialize = self
        .initialize_rendering
        .ok_or("InitializeRendering missing")?;
    let create_frame = self.create_frame.ok_or("CreateFrame missing")?;

    unsafe { initialize() };
    self.display_manager_rendering_initialized = true;
    let created_frame = unsafe { create_frame() };
    godot::global::godot_print!(
        "[xreal] Unity DisplayManager probe: InitializeRendering -> CreateFrame = \
         {created_frame}"
    );
    Ok(created_frame)
}

pub fn unity_display_frame_probe(&mut self) -> Result<(bool, usize), &'static str> {
    let create_frame = self.create_frame.ok_or("CreateFrame missing")?;
    let get_frame_metadata = self.get_frame_metadata.ok_or("GetFrameMetaData missing")?;

    let created_frame = unsafe { create_frame() };
    let metadata = unsafe { get_frame_metadata() };
    let metadata_size = if metadata.ptr.is_null() {
        0
    } else {
        metadata.size
    };
    godot::global::godot_print!(
        "[xreal] Unity DisplayManager frame probe: CreateFrame={created_frame}, \
         metadata_ptr={:?}, metadata_size={metadata_size}",
        metadata.ptr
    );
    Ok((created_frame, metadata_size))
}

pub fn nr_frame_submit(&self) -> Result<u32, i32> {
    let api = self.nr_rendering.as_ref().ok_or(-1)?;
    let rendering = self.nr_rendering_handle.ok_or(-2)?;

    let mut frame: NrHandle = 0;
    let acquire_s = unsafe { (api.rendering_acquire_frame)(rendering, &mut frame) };
    if acquire_s != 0 || frame == 0 {
        return Err(-3000 - acquire_s);
    }

    // AcquiredFrames have no viewports by default; associate our left+right viewports.
    let mut vp_statuses = [99i32; 4];
    for (i, &vp) in self.nr_viewport_handles.iter().enumerate().take(2) {
        // 1-based index (Unity uses vp_idx=1 for left, vp_idx=2 for right)
        vp_statuses[i] =
            unsafe { (api.frame_set_buffer_viewport)(rendering, frame, (i + 1) as u32, vp) };
    }

    static FRAME_CTR: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);
    let n = FRAME_CTR.fetch_add(1, std::sync::atomic::Ordering::Relaxed);

    let mut vp_count: u32 = 0;
    let vp_count_s = unsafe { (api.frame_get_viewport_count)(rendering, frame, &mut vp_count) };

    let compose_s = unsafe { (api.frame_compose)(rendering, frame) };
    let submit_s = unsafe { (api.frame_submit)(rendering, frame) };
    let _ = unsafe { (api.frame_destroy)(rendering, frame) };

    if n.is_multiple_of(60) {
        godot::global::godot_print!(
            "[xreal] frame #{n}: Acquire={acquire_s} SetVP={:?} VpCount(s={vp_count_s})={vp_count} \
             Compose={compose_s} Submit={submit_s}",
            &vp_statuses[..self.nr_viewport_handles.len().min(2)]
        );
    }

    if compose_s != 0 {
        return Err(-4300 - compose_s);
    }
    if submit_s != 0 {
        return Err(-4400 - submit_s);
    }
    Ok(0)
}

struct StereoRig {
    viewports: [Gd<SubViewport>; 2],
    cameras: [Gd<Camera3D>; 2],
}

#[derive(GodotClass)]
#[class(base = Node3D)]
pub struct XrealHeadTracker {
    base: Base<Node3D>,
    /// Whether a head pose was applied on the most recent frame.
    tracking: bool,
    /// Frame counter, used to throttle the "no pose" diagnostic log.
    frames: u64,
    /// Last raw/converted pose sample for on-device visual debugging.
    debug_pose: GString,
    /// Lazily-created per-eye offscreen render rig (stereo).
    stereo: Option<StereoRig>,
    /// Whether the `display_started` signal has been emitted (once, on first tracking).
    display_signaled: bool,
    /// Last-seen glasses hot-plug event counts (from the JNI DisplayManager callbacks); a change
    /// re-emits `glasses_connected` / `glasses_disconnected` on the Godot main thread.
    last_connect_count: u32,
    last_disconnect_count: u32,
    /// App-side recenter reference. The SDK's `RecenterGlasses` (libXREALXRPlugin.so, display
    /// subsystem) does NOT reset the pose we read via `XREALGetHeadPoseAtTime` (session-manager
    /// subsystem) — device-confirmed: the pose quaternion is unchanged after calling it. So
    /// recentering is done here: `recenter()` captures the current raw rotation and `process()`
    /// applies `reference.inverse() * raw`, making "wherever you look at recenter" the forward.
    recenter_reference: Quaternion,
    /// The raw (uncorrected) rotation from the last pose sample; captured by `recenter()`.
    last_raw_rotation: Quaternion,
    /// Keep the glasses display awake when not worn (bypass the proximity sensor's auto-off). Read
    /// once in `ready()` from the ProjectSetting `xreal/display_bypass_psensor` (default `true`).
    bypass_psensor: bool,
}

fn poll_glasses_events(&mut self) {
    let connect = crate::jni_bridge::glasses_connect_count();
    if connect != self.last_connect_count {
        self.last_connect_count = connect;
        self.signals().glasses_connected().emit();
    }
    let disconnect = crate::jni_bridge::glasses_disconnect_count();
    if disconnect != self.last_disconnect_count {
        self.last_disconnect_count = disconnect;
        self.signals().glasses_disconnected().emit();
    }
}

fn poll_hardware_events(&mut self) {
    use crate::ffi as f;
    for ev in crate::glasses_events::drain() {
        // Raw event log — this is the Phase A device-verification instrument (one line
        // per physical key press / wear change / brightness step; low volume).
        godot_print!(
            "[xreal] glasses event: type={} para={} para2={} para3={}",
            ev.action_type,
            ev.para,
            ev.para2,
            ev.para3
        );
        match ev.action_type {
            f::ACTION_TYPE_CLICK | f::ACTION_TYPE_DOUBLE_CLICK | f::ACTION_TYPE_LONG_PRESS => {
                // para = XREALKeyType, action_type = XREALClickType (same numbering as
                // the ACTION_CLICK/DOUBLE_CLICK/LONG_PRESS constants).
                self.signals()
                    .key_event()
                    .emit(ev.para as i64, ev.action_type as i64);
            }
            f::ACTION_TYPE_KEY_STATE => {
                self.signals()
                    .key_state_changed()
                    .emit(ev.para as i64, ev.para2 as i64);
            }
            f::ACTION_TYPE_PROXIMITY_WEARING_STATE => {
                // Mirror the Unity handler: only PUT_ON / TAKE_OFF are forwarded.
                if ev.para == f::WEARING_STATUS_PUT_ON || ev.para == f::WEARING_STATUS_TAKE_OFF
                {
                    self.signals()
                        .wearing_changed()
                        .emit(ev.para == f::WEARING_STATUS_PUT_ON);
                }
            }
            f::ACTION_TYPE_INCREASE_BRIGHTNESS | f::ACTION_TYPE_DECREASE_BRIGHTNESS => {
                self.signals().brightness_changed().emit(ev.para as i64);
            }
            f::ACTION_TYPE_INCREASE_VOLUME | f::ACTION_TYPE_DECREASE_VOLUME => {
                self.signals().volume_changed().emit(ev.para as i64);
            }
            f::ACTION_TYPE_NEXT_EC_LEVEL => {
                self.signals().ec_level_changed().emit(ev.para as i64);
            }
            _ => {}
        }
        self.signals().glasses_event().emit(
            ev.action_type as i64,
            ev.para as i64,
            ev.para2 as i64,
            ev.para3 as f64,
        );
    }
}

fn ensure_stereo(&mut self) {
    if self.stereo.is_some() {
        return;
    }
    let Some(world) = self.base().get_world_3d() else {
        return;
    };
    let make_eye = || {
        let mut sv = SubViewport::new_alloc();
        sv.set_size(Vector2i::new(EYE_W, EYE_H));
        sv.set_update_mode(UpdateMode::ALWAYS);
        sv.set_world_3d(&world);
        let mut cam = Camera3D::new_alloc();
        cam.set_fov(EYE_FOV);
        cam.set_near(0.05);
        cam.set_far(1000.0);
        cam.set_current(true);
        sv.add_child(&cam);
        (sv, cam)
    };
    let (svl, caml) = make_eye();
    let (svr, camr) = make_eye();
    self.base_mut().add_child(&svl);
    self.base_mut().add_child(&svr);
    self.stereo = Some(StereoRig {
        viewports: [svl, svr],
        cameras: [caml, camr],
    });
    godot_print!("[xreal] stereo rig created ({EYE_W}x{EYE_H} per eye)");
}

fn update_stereo(&mut self) {
    let head = self.base().get_global_transform();
    let Some(rig) = self.stereo.as_mut() else {
        // Mono fallback: publish the window size so the frame tick blits the default framebuffer.
        if let Some(viewport) = self.base().get_viewport() {
            let size = viewport.get_visible_rect().size;
            crate::unity_plugin::set_godot_source_size(size.x as i32, size.y as i32);
        }
        return;
    };
    // Apply the SDK's exact per-eye projection + eye offset when available (pixel-accurate AR),
    // else fall back to the symmetric IPD + hardcoded FOV.
    let proj = crate::unity_plugin::stereo_projection();
    const NEAR: f32 = 0.05;
    const FAR: f32 = 1000.0;
    for (i, cam) in rig.cameras.iter_mut().enumerate() {
        let p = proj[i];
        let eye_x = if p.valid && p.px != 0.0 {
            p.px
        } else if i == 0 {
            -HALF_IPD
        } else {
            HALF_IPD
        };
        cam.set_global_transform(
            head * Transform3D::new(Basis::IDENTITY, Vector3::new(eye_x, 0.0, 0.0)),
        );

        if p.valid && (p.r - p.l) > 1e-4 && (p.t - p.b) > 1e-4 {
            // Half-angle tangents → asymmetric frustum. Godot's Camera3D.set_frustum(size,
            // offset, near, far) maps to near-plane extents ±size/2 (vert) / ±size*aspect/2
            // (horiz) shifted by offset; near-plane coord = tangent*near.
            let (size, offset) = frustum_size_offset(p.l, p.r, p.t, p.b, NEAR);
            cam.set_frustum(size, offset, NEAR, FAR);
        } else {
            cam.set_fov(EYE_FOV);
            cam.set_near(NEAR);
            cam.set_far(FAR);
        }
    }
    let rs = RenderingServer::singleton();
    // Use the actual render-target texture RID (viewport_get_texture on the viewport RID), not
    // the ViewportTexture *resource* RID, whose native handle is 0.
    let handle = |sv: &Gd<SubViewport>| -> u32 {
        let tex_rid = rs.viewport_get_texture(sv.get_viewport_rid());
        rs.texture_get_native_handle(tex_rid) as u32
    };
    let left = handle(&rig.viewports[0]);
    let right = handle(&rig.viewports[1]);
    crate::unity_plugin::set_godot_eye_sources(left, right, EYE_W, EYE_H);
}

#[cfg(target_os = "android")]
pub fn patch_handle_action_callback(lib_base: usize) {
    let patch_addr = lib_base + 0x849bc; // ldr x0,[x0,#0x60] = load NativeGlasses*

    let wrapper_addr = null_safe_handle_action as *const () as usize;
    let byte_offset = wrapper_addr as i64 - patch_addr as i64;
    let word_offset = byte_offset >> 2;
    let page_size: usize = 4096;

    let bl_target: usize = if word_offset.abs() <= (1i64 << 25) {
        wrapper_addr
    } else {
        // Out of ±128 MiB of the wrapper: place a trampoline page WITHIN BL range of patch_addr and
        // long-jump from there. The old code passed a single fixed hint to mmap without MAP_FIXED, so
        // when that address was occupied the kernel relocated the page anywhere — often back out of
        // range, and the patch was silently skipped ("bl_target still out of range → giving up"),
        // leaving this run without the teardown null-guard. Instead, scan /proc/self/maps for a free
        // gap in [patch_addr ± 112 MiB] and claim it with MAP_FIXED_NOREPLACE, checking the returned
        // address so a race just moves us to the next gap.
        let Some(page) = alloc_trampoline_near(patch_addr, page_size) else {
            godot::global::godot_warn!(
                "[xreal] code_patch: no trampoline slot within BL range of {patch_addr:#018x} — \
                 HandleActionCallback null-guard NOT installed (teardown crash unguarded this run)"
            );
            return;
        };
        unsafe {
            // LDR X17, +8  (0x58000051) then BR X17 (0xD61F0220), then 8-byte literal
            let tram = page as *mut u32;
            *tram = 0x5800_0051u32; // LDR x17, #8
            *tram.add(1) = 0xD61F_0220u32; // BR  x17
            *(tram.add(2) as *mut u64) = wrapper_addr as u64;
            let a = page;
            core::arch::asm!("dc cvau,{a}","dsb ish","ic ivau,{a}","dsb ish","isb",a=in(reg)a);
            libc::mprotect(
                page as *mut libc::c_void,
                page_size,
                libc::PROT_READ | libc::PROT_EXEC,
            );
        }
        godot::global::godot_print!(
            "[xreal] code_patch: trampoline at {page:#018x} → {wrapper_addr:#018x}"
        );
        page
    };

    let bl_boff = bl_target as i64 - patch_addr as i64;
    let bl_woff = bl_boff >> 2;
    if bl_woff.abs() > (1i64 << 25) {
        godot::global::godot_warn!(
            "[xreal] code_patch: bl_target still out of range ({bl_boff:#x}), giving up — \
             HandleActionCallback null-guard NOT installed (teardown crash unguarded this run)"
        );
        return;
    }
    let bl_insn: u32 = 0x9400_0000 | (bl_woff as u32 & 0x03FF_FFFF);
    let page_addr = (patch_addr & !(page_size - 1)) as *mut libc::c_void;

    unsafe {
        if libc::mprotect(
            page_addr,
            page_size,
            libc::PROT_READ | libc::PROT_WRITE | libc::PROT_EXEC,
        ) != 0
        {
            godot::global::godot_print!("[xreal] code_patch: mprotect(RWX) failed");
            return;
        }
        *(patch_addr as *mut u32) = bl_insn;
        core::arch::asm!(
            "dc cvau,{a}","dsb ish","ic ivau,{a}","dsb ish","isb",
            a = in(reg) patch_addr,
        );
        libc::mprotect(page_addr, page_size, libc::PROT_READ | libc::PROT_EXEC);
    }
    godot::global::godot_print!(
        "[xreal] code_patch: patched HandleActionCallback+20 at {patch_addr:#018x} \
         bl→{bl_target:#018x} encoding={bl_insn:#010x}"
    );
}

#[cfg(target_os = "android")]
pub fn patch_create_display_layer(lib_base: usize) {
    // Patch 1: cbz w8, 0x6dd18 → b 0x6dd18 — force the real `DisplayOverlay` (vs DummyDisplayOverlay),
    // so Multiview registers the swapchain texture.
    let patch_addr = lib_base + 0x6dc98;
    let branch_real: u32 = 0x1400_0020; // b 0x6dd18 (delta 0x80, imm26 0x20)
                                        // Patch 2 (Multiview two-viewport): `lsl w21, w8, #1` → `mov w21, #2` at CreateDisplayLayer+0x48.
                                        // This is inside the `stereo_rendering_mode == 2` block, so Multipass is untouched. It forces the
                                        // DisplayOverlay ctor's `overlay+0x14 = 2` — the value `DisplayOverlay::CreateViewport @0xa6a68`
                                        // tests to build TWO viewports (viewport[0] layer 0 = left, viewport[1] layer 1 = right) for the
                                        // one array swapchain. Without it our path built only ONE viewport (component 6), so the compositor
                                        // never presented array layer 1 and the right eye was black. See docs/archive/codex-righteye-analysis.md.
    let viewport_addr = lib_base + 0x6dc60;
    let mov_w21_2: u32 = 0x5280_0055; // mov w21, #2

    let page_size: usize = 4096;
    // Both targets sit in the same page (…6d000).
    let page_addr = (patch_addr & !(page_size - 1)) as *mut libc::c_void;

    unsafe {
        if libc::mprotect(
            page_addr,
            page_size,
            libc::PROT_READ | libc::PROT_WRITE | libc::PROT_EXEC,
        ) != 0
        {
            godot::global::godot_print!("[xreal] patch_display_layer: mprotect(RWX) failed");
            return;
        }
        *(patch_addr as *mut u32) = branch_real;
        *(viewport_addr as *mut u32) = mov_w21_2;
        core::arch::asm!(
            "dc cvau,{a}", "dc cvau,{b}", "dsb ish",
            "ic ivau,{a}", "ic ivau,{b}", "dsb ish", "isb",
            a = in(reg) patch_addr,
            b = in(reg) viewport_addr,
        );
        libc::mprotect(page_addr, page_size, libc::PROT_READ | libc::PROT_EXEC);
    }
    godot::global::godot_print!(
        "[xreal] patch_display_layer: patched CreateDisplayLayer at {patch_addr:#018x} cbz→b 0x6dd18 \
         (real DisplayOverlay) + {viewport_addr:#018x} lsl→mov w21,#2 (Multiview two-viewport / layer 1)"
    );
}

#[cfg(target_os = "android")]
pub fn patch_update_metrics(lib_base: usize) {
    let patch_addr = lib_base + 0x68974; // DisplayManager::UpdateMetrics first instruction
    let ret: u32 = 0xD65F_03C0; // ret
    let page_size: usize = 4096;
    let page_addr = (patch_addr & !(page_size - 1)) as *mut libc::c_void;

    unsafe {
        if libc::mprotect(
            page_addr,
            page_size,
            libc::PROT_READ | libc::PROT_WRITE | libc::PROT_EXEC,
        ) != 0
        {
            godot::global::godot_print!("[xreal] patch_update_metrics: mprotect(RWX) failed");
            return;
        }
        *(patch_addr as *mut u32) = ret;
        core::arch::asm!(
            "dc cvau,{a}", "dsb ish", "ic ivau,{a}", "dsb ish", "isb",
            a = in(reg) patch_addr,
        );
        libc::mprotect(page_addr, page_size, libc::PROT_READ | libc::PROT_EXEC);
    }
    godot::global::godot_print!(
        "[xreal] patch_update_metrics: patched UpdateMetrics at {patch_addr:#018x} → ret \
         (skip null metrics callback so SubmitCurrentFrame can present)"
    );
}

#[cfg(target_os = "android")]
pub fn reassert_update_metrics_on_render_thread() {
    static DONE: AtomicBool = AtomicBool::new(false);
    if DONE.swap(true, Ordering::SeqCst) {
        return;
    }
    let lib_base = LIB_BASE.load(Ordering::SeqCst);
    if lib_base == 0 {
        return;
    }
    patch_update_metrics(lib_base);
    godot::global::godot_print!(
        "[xreal] reassert_update_metrics_on_render_thread: re-applied ret on the render thread"
    );
}

pub fn install(lib_base: usize) {
    LIB_BASE.store(lib_base, Ordering::SeqCst);

    #[cfg(target_os = "android")]
    {
        use libc::{SA_NODEFER, SA_RESTART, SA_SIGINFO};
        unsafe {
            let mut sa: libc::sigaction = std::mem::zeroed();
            sa.sa_sigaction = sigsegv_handler as *const () as usize;
            sa.sa_flags = SA_SIGINFO | SA_RESTART | SA_NODEFER;
            libc::sigemptyset(&mut sa.sa_mask);
            let ret = libc::sigaction(libc::SIGSEGV, &sa, std::ptr::null_mut());
            godot::global::godot_print!(
                "[xreal] signal_guard: sigaction={ret}, lib_base={lib_base:#018x}, \
                 crash_addr={:#018x}, epilogue_addr={:#018x}",
                lib_base + OFFSET_CRASH,
                lib_base + OFFSET_EPILOGUE
            );
        }
    }
    #[cfg(not(target_os = "android"))]
    godot::global::godot_print!(
        "[xreal] signal_guard: no-op on non-Android (lib_base={lib_base:#018x})"
    );
}

