#[godot_api]
impl AseTilesetSync {
    /// Syncs sources from `path` into `tile_set` in place. Returns the number
    /// of sources synced (0 on failure, with details logged).
    #[func]
    fn sync(tile_set: Option<Gd<godot::classes::TileSet>>, path: GString) -> i64 {
        let Some(mut tile_set) = tile_set else {
            godot_error!("AseTilesetSync.sync: tile_set is null");
            return 0;
        };
        match convert::load_ase(&path)
            .and_then(|f| convert::sync_tileset_into(&f, &mut tile_set, None))
        {
            Ok(n) => n as i64,
            Err(e) => {
                godot_error!("AseTilesetSync.sync: {path}: {e}");
                0
            }
        }
    }

    /// Like `sync`, but saves the atlas sheet as its own lossless texture
    /// file at `sheet_path` (created there or updated in place) and
    /// references it from the TileSet instead of embedding a copy. Point
    /// `sheet_path` at an extraction's `sheet.res` and the TileSet shares
    /// one texture with the extracted AtlasTextures. The sheet file is owned
    /// by the sync; single embedded tileset only.
    #[func]
    fn sync_with_sheet(
        tile_set: Option<Gd<godot::classes::TileSet>>,
        path: GString,
        sheet_path: GString,
    ) -> i64 {
        let Some(mut tile_set) = tile_set else {
            godot_error!("AseTilesetSync.sync_with_sheet: tile_set is null");
            return 0;
        };
        let sheet_path = sheet_path.to_string();
        let sheet_path = sheet_path.trim();
        if sheet_path.is_empty() {
            godot_error!("AseTilesetSync.sync_with_sheet: sheet_path is empty");
            return 0;
        }
        match convert::load_ase(&path)
            .and_then(|f| convert::sync_tileset_into(&f, &mut tile_set, Some(sheet_path)))
        {
            Ok(n) => n as i64,
            Err(e) => {
                godot_error!("AseTilesetSync.sync_with_sheet: {path}: {e}");
                0
            }
        }
    }
}

pub(crate) fn new(
    address: String,
    display_address: String,
    name: String,
    client: CoreClient,
) -> Gd<Self> {
    Gd::from_init_fn(|base| Self {
        base,
        client: Some(client),
        address,
        display_address: GString::from(display_address.as_str()),
        name: GString::from(name.as_str()),
        cache: DeviceCache::default(),
        next_local_operation_id: 1,
    })
}

pub(crate) fn apply_core_event(&mut self, event: &BleEvent) {
    if event.context.device_address != self.address {
        return;
    }

    if let EventData::Device { info, .. } = &event.data {
        self.display_address = GString::from(info.address.as_str());
        if let Some(name) = &info.name {
            self.name = GString::from(name.as_str());
        }
    }

    self.cache.apply(event);

    self.base_mut().emit_signal(
        "ble_event",
        &[godot_event::to_dictionary(event).to_variant()],
    );

    match (event.operation, event.phase) {
        (Operation::Connect, Phase::Succeeded) => {
            self.base_mut().emit_signal("connected", &[]);
        }
        (Operation::Connect, Phase::Failed | Phase::Cancelled) => {
            let error = legacy_error(event);
            self.base_mut()
                .emit_signal("connection_failed", &[error.to_variant()]);
        }
        (Operation::Disconnect, Phase::Succeeded | Phase::Received) => {
            self.base_mut().emit_signal("disconnected", &[]);
        }
        (Operation::Disconnect, Phase::Failed | Phase::Cancelled) => {
            self.emit_operation_failed(event);
        }
        (Operation::DiscoverServices, Phase::Succeeded) => {
            if let EventData::Services(services) = &event.data {
                let dictionaries: Array<VarDictionary> = services
                    .iter()
                    .map(crate::ble_service::BleServiceInfo::to_dictionary)
                    .collect();
                self.base_mut()
                    .emit_signal("services_discovered", &[dictionaries.to_variant()]);
            }
        }
        (Operation::Read, Phase::Succeeded) => {
            if let EventData::Bytes(data) = &event.data {
                let data = PackedByteArray::from(data.as_slice());
                self.base_mut().emit_signal(
                    "characteristic_read",
                    &[
                        GString::from(event.context.characteristic_uuid.as_str()).to_variant(),
                        data.to_variant(),
                    ],
                );
            }
        }
        (Operation::Write, Phase::Succeeded) => {
            self.base_mut().emit_signal(
                "characteristic_written",
                &[GString::from(event.context.characteristic_uuid.as_str()).to_variant()],
            );
        }
        (Operation::Notification, Phase::Received) => {
            if let EventData::Bytes(data) = &event.data {
                let data = PackedByteArray::from(data.as_slice());
                self.base_mut().emit_signal(
                    "characteristic_notified",
                    &[
                        GString::from(event.context.characteristic_uuid.as_str()).to_variant(),
                        data.to_variant(),
                    ],
                );
            }
        }
        (
            Operation::DiscoverServices
            | Operation::Read
            | Operation::Write
            | Operation::Subscribe
            | Operation::Unsubscribe
            | Operation::Notification,
            Phase::Failed | Phase::Cancelled,
        ) => self.emit_operation_failed(event),
        _ => {}
    }
}

fn emit_operation_failed(&mut self, event: &BleEvent) {
    let operation = match event.operation {
        Operation::DiscoverServices => "discover_services",
        Operation::Read => "read_characteristic",
        Operation::Write => "write_characteristic",
        Operation::Subscribe => "subscribe_characteristic",
        Operation::Unsubscribe => "unsubscribe_characteristic",
        Operation::Disconnect => "disconnect",
        _ => event.operation.as_str(),
    };
    self.base_mut().emit_signal(
        "operation_failed",
        &[
            GString::from(operation).to_variant(),
            legacy_error(event).to_variant(),
        ],
    );
}

#[godot_api]
impl INode for BluetoothManager {
    fn init(base: Base<Node>) -> Self {
        let core = CoreRuntime::spawn_production();
        let client = core.client();
        Self {
            base,
            core: Some(core),
            client,
            initialized: false,
            adapter_info: None,
            scan: ScanCache::default(),
            discovered_devices: HashMap::new(),
            devices: HashMap::new(),
        }
    }

    fn ready(&mut self) {
        self.base_mut().set_process(true);
    }

    fn process(&mut self, _delta: f64) {
        for _ in 0..EVENTS_PER_FRAME {
            let Some(event) = self.core.as_mut().and_then(CoreRuntime::try_recv) else {
                break;
            };
            self.apply_core_event(event);
        }
    }

    fn on_notification(&mut self, what: NodeNotification) {
        if what == NodeNotification::PREDELETE {
            if let Some(mut core) = self.core.take() {
                core.shutdown();
            }
            for device in self.devices.values_mut() {
                device.bind_mut().detach();
            }
            self.devices.clear();
            self.initialized = false;
        }
    }
}

fn apply_core_event(&mut self, event: BleEvent) {
    self.update_caches(&event);
    let scan_signals = self.scan.apply(&event);

    if !event.context.device_address.is_empty() {
        if let Some(mut device) = self.devices.get(&event.context.device_address).cloned() {
            // Keep the guard alive across *all* device callbacks. They may
            // synchronously read or call this Manager again through Godot.
            let _reentrant = self.base_mut();
            device.bind_mut().apply_core_event(&event);
        }
    }

    self.base_mut().emit_signal(
        "ble_event",
        &[godot_event::to_dictionary(&event).to_variant()],
    );
    self.emit_legacy_manager_signals(&event, scan_signals);
}

fn emit_legacy_manager_signals(&mut self, event: &BleEvent, scan_signals: ScanSignals) {
    match (event.operation, event.phase) {
        (Operation::Initialize, Phase::Succeeded) => {
            self.base_mut().emit_signal(
                "adapter_initialized",
                &[true.to_variant(), GString::new().to_variant()],
            );
        }
        (Operation::Initialize, Phase::Failed | Phase::Cancelled) => {
            let error = legacy_error(event);
            self.base_mut().emit_signal(
                "adapter_initialized",
                &[false.to_variant(), error.to_variant()],
            );
            self.base_mut()
                .emit_signal("error_occurred", &[error.to_variant()]);
        }
        (Operation::Scan, Phase::Started) => {
            if scan_signals.started {
                self.base_mut().emit_signal("scan_started", &[]);
            }
        }
        (Operation::Scan, Phase::Progress) => {
            if let EventData::Device { kind, info } = &event.data {
                let signal = match kind {
                    DeviceProgressKind::Discovered => "device_discovered",
                    DeviceProgressKind::Updated => "device_updated",
                };
                self.base_mut()
                    .emit_signal(signal, &[info.to_dictionary().to_variant()]);
            }
        }
        (Operation::Scan, Phase::Succeeded | Phase::Failed | Phase::Cancelled) => {
            if matches!(event.phase, Phase::Failed | Phase::Cancelled) {
                let error = legacy_error(event);
                self.base_mut()
                    .emit_signal("error_occurred", &[error.to_variant()]);
            }
            if scan_signals.stopped {
                self.base_mut().emit_signal("scan_stopped", &[]);
            }
        }
        (Operation::Connect, Phase::Started) => {
            self.base_mut().emit_signal(
                "device_connecting",
                &[GString::from(event.context.device_address.as_str()).to_variant()],
            );
        }
        (Operation::Connect, Phase::Succeeded) => {
            self.base_mut().emit_signal(
                "device_connected",
                &[GString::from(event.context.device_address.as_str()).to_variant()],
            );
        }
        (Operation::Disconnect, Phase::Succeeded | Phase::Received) => {
            self.base_mut().emit_signal(
                "device_disconnected",
                &[GString::from(event.context.device_address.as_str()).to_variant()],
            );
        }
        (Operation::ResolveDevice, Phase::Failed | Phase::Cancelled) => {
            let error = legacy_error(event);
            self.base_mut()
                .emit_signal("error_occurred", &[error.to_variant()]);
        }
        _ => {}
    }
}

fn get_current_cam(&self) -> Gd<Camera3D> {
    self.cameras.get(self.cam_idx).unwrap()
}

fn position_control_based_on_unprojected_offset(
    &self,
    mut control: Gd<Control>,
    local_pos: Vector3,
    rotation: f32,
) {
    control.set_rotation(rotation);
    let cam = self.get_current_cam();
    let size = control.get_size();
    control.set_pivot_offset(size / 2.0);

    let cam_pos = cam.get_global_position();

    let world_pos = cam_pos + local_pos;
    let screen_pos = cam.unproject_position(world_pos);

    let viewport_center = self
        .artificial_horizon
        .get_viewport()
        .map(|v| v.get_visible_rect().size / 2.0)
        .unwrap_or(Vector2::ZERO);

    let half_size = size / 2.0;
    let left = screen_pos.x - viewport_center.x - half_size.x;
    let top = screen_pos.y - viewport_center.y - half_size.y;
    control.set_offset(Side::LEFT, left);
    control.set_offset(Side::TOP, top);
    control.set_offset(Side::RIGHT, left + size.x);
    control.set_offset(Side::BOTTOM, top + size.y);
}

fn handle_cam_movement(&mut self, delta_time: f32) {
    let mut cam = self.get_current_cam();
    let cam_yaw = Input::singleton().get_action_strength("cam_yaw_right")
        - Input::singleton().get_action_strength("cam_yaw_left");
    let cam_pitch = Input::singleton().get_action_strength("cam_pitch_up")
        - Input::singleton().get_action_strength("cam_pitch_down");

    let mut rot = cam.get_rotation_degrees() - self.cam_rotation_offset
        + Vector3::new(
            cam_pitch * self.cam_sensitivity.x,
            cam_yaw * self.cam_sensitivity.y,
            0.,
        ) * delta_time;
    rot = rot.clamp(
        Vector3::new(
            -self.cam_max_yaw_pitch_deg.x,
            -self.cam_max_yaw_pitch_deg.y,
            0.,
        ),
        Vector3::new(
            self.cam_max_yaw_pitch_deg.x,
            self.cam_max_yaw_pitch_deg.y,
            0.,
        ),
    );
    cam.set_rotation_degrees(rot + self.cam_rotation_offset);
}

