#[derive(GodotClass)]
#[class(no_init)]
struct PanicHook {}

#[godot_api]
impl PanicHook {
    #[func]
    fn open() {
        godot_print!("Set panic hook");

        let hook = std::panic::take_hook();
        std::panic::set_hook(Box::new(move |info| {
            let location_msg;
            if let Some(location) = info.location() {
                location_msg = format!("file {} at line {}", location.file(), location.line());
            } else {
                location_msg = "unknown location".into();
            }

            let payload_msg;
            if let Some(s) = info.payload().downcast_ref::<&str>() {
                payload_msg = s.to_string();
            } else if let Some(s) = info.payload().downcast_ref::<String>() {
                payload_msg = s.clone();
            } else {
                payload_msg = "unknown panic".into();
            }

            godot_error!("[RUST] {}: {}", location_msg, payload_msg);
            hook(info);
        }));
    }

    #[func]
    fn close() {
        godot_print!("Unset panic hook");

        let _ = std::panic::take_hook();
    }
}

#[derive(GodotClass)]
#[class(base=Node)]
struct YawcTransport {
    base: Base<Node>,
    worker: Worker,
}

#[godot_api]
impl YawcTransport {
    #[signal]
    fn opened();

    #[signal]
    fn closed();

    #[signal]
    fn error(message: GString);

    #[signal]
    fn text_message(message: GString);

    #[signal]
    fn binary_message(message: PackedByteArray);

    #[func]
    fn connect_to_url(&self, url: GString) -> bool {
        self.worker.send(Command::Connect(url.to_string()))
    }

    #[func]
    fn send_text(&self, message: GString) -> bool {
        self.worker.send(Command::SendText(message.to_string()))
    }

    #[func]
    fn send_binary(&self, message: PackedByteArray) -> bool {
        self.worker.send(Command::SendBinary(message.to_vec()))
    }

    #[func]
    fn close(&self) -> bool {
        self.worker.send(Command::Close)
    }
}

#[godot_api]
impl INode for YawcTransport {
    fn init(base: Base<Node>) -> Self {
        Self {
            base,
            worker: Worker::start(),
        }
    }

    fn enter_tree(&mut self) {
        self.worker.restart();
    }

    fn process(&mut self, _delta: f64) {
        for _ in 0..64 {
            let event = match self.worker.try_recv() {
                Ok(event) => event,
                Err(mpsc::error::TryRecvError::Empty | mpsc::error::TryRecvError::Disconnected) => {
                    break;
                }
            };

            match event {
                Event::Opened => self.signals().opened().emit(),
                Event::Closed => self.signals().closed().emit(),
                Event::Error(message) => self.signals().error().emit(message.as_str()),
                Event::TextMessage(message) => self.signals().text_message().emit(message.as_str()),
                Event::BinaryMessage(message) => self
                    .signals()
                    .binary_message()
                    .emit(&PackedByteArray::from(message)),
            }
        }
    }

    fn exit_tree(&mut self) {
        self.worker.shutdown();
    }
}

pub fn enable_space_override(
    area_id: &RapierId,
    physics_spaces: &mut PhysicsSpaces,
    physics_collision_objects: &mut PhysicsCollisionObjects,
    physics_ids: &PhysicsIds,
) {
    let area_rid = get_id_rid(*area_id, physics_ids);
    let mut detected_bodies = HashMap::default();
    let mut space_rid = Rid::Invalid;
    if let Some(area_rid) = physics_collision_objects.get(&area_rid)
        && let Some(area) = area_rid.get_area()
    {
        detected_bodies = area.state.monitored_objects.clone();
        space_rid = area.get_base().get_space(physics_ids);
    }
    if let Some(space) = physics_spaces.get_mut(&space_rid) {
        for (_, monitor_info) in detected_bodies.iter() {
            if let [Some(body), Some(area)] = physics_collision_objects.get_disjoint_mut([
                &get_id_rid(monitor_info.other_collider_id, physics_ids),
                &area_rid,
            ]) && let Some(body) = body.get_mut_body()
                && let Some(area) = area.get_mut_area()
            {
                body.add_area(area, space);
            }
        }
        // No need to update anymore if it was scheduled before
        space
            .get_mut_state()
            .area_remove_from_area_update_list(*area_id);
    }
}

pub fn disable_space_override(
    area_id: &RapierId,
    physics_spaces: &mut PhysicsSpaces,
    physics_collision_objects: &mut PhysicsCollisionObjects,
    physics_ids: &PhysicsIds,
) {
    let area_rid = get_id_rid(*area_id, physics_ids);
    let mut detected_bodies = HashMap::default();
    let mut space_rid = Rid::Invalid;
    if let Some(area_rid) = physics_collision_objects.get(&area_rid)
        && let Some(area) = area_rid.get_area()
    {
        detected_bodies = area.state.monitored_objects.clone();
        space_rid = area.get_base().get_space(physics_ids);
    }
    if let Some(space) = physics_spaces.get_mut(&space_rid) {
        for (_, monitor_info) in detected_bodies.iter() {
            if let Some(body) = physics_collision_objects
                .get_mut(&get_id_rid(monitor_info.other_collider_id, physics_ids))
                && let Some(body) = body.get_mut_body()
            {
                body.remove_area(*area_id, space);
            }
        }
        // No need to update anymore if it was scheduled before
        space
            .get_mut_state()
            .area_remove_from_area_update_list(*area_id);
    }
}

pub fn reset_space_override(
    area_id: &RapierId,
    physics_spaces: &mut PhysicsSpaces,
    physics_collision_objects: &mut PhysicsCollisionObjects,
    physics_ids: &PhysicsIds,
) {
    let area_rid = get_id_rid(*area_id, physics_ids);
    let mut detected_bodies = HashMap::default();
    let mut space_rid: Rid = Rid::Invalid;
    if let Some(area_rid) = physics_collision_objects.get(&area_rid)
        && let Some(area) = area_rid.get_area()
    {
        detected_bodies = area.state.monitored_objects.clone();
        space_rid = area.get_base().get_space(physics_ids);
    }
    if let Some(space) = physics_spaces.get_mut(&space_rid) {
        for (_, monitor_info) in detected_bodies {
            if let [Some(body), Some(area)] = physics_collision_objects.get_disjoint_mut([
                &get_id_rid(monitor_info.other_collider_id, physics_ids),
                &area_rid,
            ]) && let Some(body) = body.get_mut_body()
                && let Some(area) = area.get_mut_area()
            {
                body.remove_area(*area_id, space);
                body.add_area(area, space);
            }
        }
        space
            .get_mut_state()
            .area_remove_from_area_update_list(*area_id);
    }
}

pub fn update_area_override(
    physics_collision_objects: &mut PhysicsCollisionObjects,
    physics_spaces: &mut PhysicsSpaces,
    physics_engine: &mut PhysicsEngine,
    area_id: &RapierId,
    physics_ids: &PhysicsIds,
) {
    let mut monitored_bodies = HashMap::default();
    let mut space_rid = Rid::Invalid;
    let area_rid = get_id_rid(*area_id, physics_ids);
    if let Some(area_rid) = physics_collision_objects.get(&area_rid)
        && let Some(area) = area_rid.get_area()
    {
        monitored_bodies = area.state.monitored_objects.clone();
        space_rid = area.get_base().get_space(physics_ids);
    }
    if let Some(space) = physics_spaces.get_mut(&space_rid) {
        space
            .get_mut_state()
            .area_remove_from_area_update_list(*area_id);
    }
    for (_, monitor_info) in &monitored_bodies {
        RapierBody::apply_area_override_to_body(
            &monitor_info.other_collider_id,
            physics_engine,
            physics_spaces,
            physics_collision_objects,
            physics_ids,
        )
    }
}

pub fn call_queries(
    unhandled_events: &HashMap<MonitorKey, EventReport>,
    monitor_callback: Option<Callable>,
    area_monitor_callback: Option<Callable>,
    physics_ids: &PhysicsIds,
) {
    let physics_data = physics_data();
    for monitor_report in unhandled_events.values() {
        if monitor_report.state == 0 {
            godot_error!("Invalid monitor state");
            continue;
        }
        let rid = get_id_rid(monitor_report.id, physics_ids);
        // Resolve the RapierId stored in instance_id to the real Godot instance_id
        let godot_instance_id: i64 = if let Some(obj_rid) =
            physics_data.ids.get(&monitor_report.instance_id)
            && let Some(obj) = physics_data.collision_objects.get(obj_rid)
        {
            obj.get_base().get_instance_id() as i64
        } else {
            0
        };
        let arg_array = if monitor_report.state > 0 {
            vec![
                AreaBodyStatus::ADDED.to_variant(),
                rid.to_variant(),
                godot_instance_id.to_variant(),
                monitor_report.object_shape_index.to_variant(),
                monitor_report.this_area_shape_index.to_variant(),
            ]
        } else {
            vec![
                AreaBodyStatus::REMOVED.to_variant(),
                rid.to_variant(),
                godot_instance_id.to_variant(),
                monitor_report.object_shape_index.to_variant(),
                monitor_report.this_area_shape_index.to_variant(),
            ]
        };
        if monitor_report.collision_object_type == CollisionObjectType::Body {
            if let Some(ref monitor_callback) = monitor_callback {
                monitor_callback.call(arg_array.as_slice());
            }
        } else if let Some(ref area_monitor_callback) = area_monitor_callback {
            area_monitor_callback.call(arg_array.as_slice());
        }
    }
}

pub fn compute_gravity(&self, position: Vector) -> Vector {
    if self.gravity_is_point {
        let gr_unit_dist = self.get_gravity_point_unit_distance();
        let v = self.get_base().get_transform() * self.gravity_vector - position;
        if gr_unit_dist > 0.0 {
            let v_length_sq = v.length_squared();
            if v_length_sq > 0.0 {
                let gravity_strength = self.gravity * gr_unit_dist * gr_unit_dist / v_length_sq;
                vector_normalized(v) * gravity_strength
            } else {
                Vector::default()
            }
        } else {
            vector_normalized(v) * self.gravity
        }
    } else {
        self.gravity_vector * self.gravity
    }
}

fn init_collider(
    &self,
    collider_handle: ColliderHandle,
    space_handle: WorldHandle,
    physics_engine: &mut PhysicsEngine,
) {
    // Send contact infos for dynamic bodies, or for static bodies with static linear velocity
    let is_with_static_linear_velocity = self.get_static_linear_velocity() != Vector::default();
    if self.base.mode.ord() >= BodyMode::KINEMATIC.ord() || is_with_static_linear_velocity {
        let mut send_contacts = self.can_report_contacts();
        if self.base.is_debugging_contacts && godot::classes::Os::singleton().is_debug_build() {
            send_contacts = true;
        }
        if is_with_static_linear_velocity {
            send_contacts = true;
        }
        physics_engine.collider_set_contact_force_events_enabled(
            space_handle,
            collider_handle,
            send_contacts,
        );
    }
    self.update_collider_filters(collider_handle, space_handle, physics_engine, false);
}

fn update_colliders_contact_events(&self, physics_engine: &mut PhysicsEngine) {
    let is_with_static_linear_velocity = self.get_static_linear_velocity() != Vector::default();
    if self.base.mode.ord() < BodyMode::KINEMATIC.ord() && !is_with_static_linear_velocity {
        return;
    }
    let colliders = physics_engine
        .body_get_colliders(self.base.get_space_id(), self.base.get_body_handle())
        .to_vec();
    let mut send_contacts = self.can_report_contacts();
    if self.base.is_debugging_contacts && godot::classes::Os::singleton().is_debug_build() {
        send_contacts = true;
    }
    if is_with_static_linear_velocity {
        send_contacts = true;
    }
    for collider in colliders {
        physics_engine.collider_set_contact_force_events_enabled(
            self.base.get_space_id(),
            collider,
            send_contacts,
        );
    }
}

pub fn create_direct_state(&mut self) {
    if self.direct_state.is_none() {
        self.direct_state_array.clear();
        let mut direct_space_state = RapierDirectBodyState::new_alloc();
        {
            let mut direct_state = direct_space_state.bind_mut();
            direct_state.set_body(self.base.get_rid());
        }
        self.direct_state_array
            .push(&direct_space_state.clone().to_variant());
        self.direct_state = Some(direct_space_state.upcast());
    }
}

pub fn get_direct_state(&self) -> Option<&Gd<PhysicsDirectBodyState>> {
    self.direct_state.as_ref()
}

pub fn add_area(&mut self, p_area: &RapierArea, space: &mut RapierSpace) {
    if p_area.has_any_space_override() {
        let area_id = p_area.get_base().get_id();
        let priority = p_area.get_priority();
        self.state
            .areas
            .push(IdWithPriority::new(area_id, priority));
        self.state.areas.sort_by(|a, b| a.priority.cmp(&b.priority));
        self.on_area_updated(space);
    }
}

pub fn get_aabb(&self, physics_shapes: &PhysicsShapes, physics_ids: &PhysicsIds) -> Rect {
    let mut shapes_found = false;
    let mut body_aabb = Rect::default();
    let shape_count = self.base.get_shape_count() as usize;
    for i in 0..shape_count {
        if self.base.is_shape_disabled(i) {
            continue;
        }
        if let Some(shape) = physics_shapes.get(&self.base.get_shape(physics_ids, i)) {
            let mut shape_transform = self.base.get_shape_transform(i);
            if !shapes_found {
                body_aabb = shape.get_base().get_aabb(shape_transform.origin);
                shape_transform.origin = Vector::default();
                body_aabb.size = transform_scale(&shape_transform) * body_aabb.size;
                shapes_found = true;
            } else {
                let mut shape_aabb = shape.get_base().get_aabb(shape_transform.origin);
                shape_transform.origin = Vector::default();
                shape_aabb.size = transform_scale(&shape_transform) * shape_aabb.size;
                body_aabb = body_aabb.merge(shape_aabb);
            }
        }
    }
    // HACK Rotation fix hack, do different
    body_aabb.size.x = body_aabb.size.x.max(body_aabb.size.y);
    body_aabb.size.y = body_aabb.size.x;
    #[cfg(feature = "dim3")]
    if crate::rapier::prelude::DIM == 3 {
        body_aabb.size.z = body_aabb.size.x;
    }
    body_aabb
}

pub fn new(id: RapierId, rid: Rid, collision_object_type: CollisionObjectType) -> Self {
    let mut mode = BodyMode::RIGID;
    if collision_object_type == CollisionObjectType::Area {
        mode = BodyMode::STATIC;
    }
    let project_settings = ProjectSettings::singleton();
    let activation_angular_threshold = project_settings
        .get_setting_with_override(SLEEP_THRESHOLD_ANGULAR)
        .try_to()
        .unwrap_or_default();
    let length_unit = RapierProjectSettings::get_length_unit();
    let mut activation_linear_threshold = project_settings
        .get_setting_with_override(SLEEP_THRESHOLD_LINEAR)
        .try_to()
        .unwrap_or_default();
    activation_linear_threshold /= length_unit;
    let activation_time_until_sleep = project_settings
        .get_setting_with_override(TIME_BEFORE_SLEEP)
        .try_to()
        .unwrap_or_default();
    Self {
        #[cfg(feature = "dim3")]
        user_flags: 0,
        collision_object_type,
        rid,
        state: RapierCollisionObjectBaseState {
            id,
            body_handle: RigidBodyHandle::invalid(),
            space_id: RapierId::default(),
            shapes: Vec::new(),
            transform: Transform::IDENTITY,
            inv_transform: Transform::IDENTITY,
        },
        instance_id: 0,
        canvas_instance_id: 0,
        pickable: true,
        collision_mask: 1,
        collision_layer: 1,
        dominance: 0,
        is_debugging_contacts: false,
        mode,
        massless: false,
        activation_angular_threshold,
        activation_linear_threshold,
        activation_time_until_sleep,
    }
}

pub(super) fn recreate_shapes(
    collision_object: &mut dyn IRapierCollisionObject,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_ids: &PhysicsIds,
) {
    for i in 0..collision_object.get_base().get_shape_count() as usize {
        if collision_object.get_base().state.shapes[i].disabled {
            continue;
        }
        if collision_object.get_base().state.shapes[i].collider_handle
            != ColliderHandle::invalid()
        {
            collision_object.get_mut_base().state.shapes[i].collider_handle =
                collision_object.get_base().destroy_shape(
                    collision_object.get_base().state.shapes[i],
                    i,
                    physics_spaces,
                    physics_engine,
                    physics_ids,
                );
        }
        collision_object.get_mut_base().state.shapes[i].collider_handle = collision_object
            .create_shape(
                collision_object.get_base().state.shapes[i],
                i,
                physics_engine,
            );
        collision_object.get_base().update_shape_transform(
            &collision_object.get_base().state.shapes[i],
            physics_engine,
        );
    }
}

#[allow(clippy::too_many_arguments)]
pub(super) fn add_shape(
    collision_object: &mut dyn IRapierCollisionObject,
    p_shape_id: RapierId,
    p_transform: Transform,
    p_disabled: bool,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_shapes: &mut PhysicsShapes,
    physics_ids: &PhysicsIds,
) {
    let mut shape = CollisionObjectShape {
        xform: p_transform,
        id: p_shape_id,
        disabled: p_disabled,
        one_way_collision: false,
        one_way_collision_margin: 0.0,
        #[cfg(feature = "dim2")]
        one_way_collision_direction: Vector::new(0.0, 1.0),
        collider_handle: ColliderHandle::invalid(),
    };
    if !shape.disabled {
        shape.collider_handle = collision_object.create_shape(
            shape,
            collision_object.get_base().state.shapes.len(),
            physics_engine,
        );
        collision_object
            .get_base()
            .update_shape_transform(&shape, physics_engine);
    }
    collision_object.get_mut_base().state.shapes.push(shape);
    if let Some(shape) = physics_shapes.get_mut(&get_id_rid(p_shape_id, physics_ids)) {
        shape
            .get_mut_base()
            .add_owner(collision_object.get_base().get_id());
    }
    if collision_object.get_base().is_space_valid() {
        collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
    }
}

pub(super) fn shape_changed(
    collision_object: &mut dyn IRapierCollisionObject,
    shape_id: RapierId,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_ids: &PhysicsIds,
) {
    for i in 0..collision_object.get_base().state.shapes.len() {
        let shape = collision_object.get_base().state.shapes[i];
        if shape.id != shape_id || shape.disabled {
            continue;
        }
        if collision_object.get_base().state.shapes[i].collider_handle
            != ColliderHandle::invalid()
        {
            collision_object.get_mut_base().state.shapes[i].collider_handle = collision_object
                .get_base()
                .destroy_shape(shape, i, physics_spaces, physics_engine, physics_ids);
        }
        collision_object.get_mut_base().state.shapes[i].collider_handle = collision_object
            .create_shape(
                collision_object.get_base().state.shapes[i],
                i,
                physics_engine,
            );
        collision_object.get_base().update_shape_transform(
            &collision_object.get_base().state.shapes[i],
            physics_engine,
        );
    }
    collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
}

pub(super) fn remove_shape_idx(
    collision_object: &mut dyn IRapierCollisionObject,
    p_index: usize,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_shapes: &mut PhysicsShapes,
    physics_ids: &PhysicsIds,
) {
    if p_index >= collision_object.get_base().state.shapes.len() {
        return;
    }
    let shape = &collision_object.get_base().state.shapes[p_index];
    if !shape.disabled {
        collision_object.get_base().destroy_shape(
            *shape,
            p_index,
            physics_spaces,
            physics_engine,
            physics_ids,
        );
    }
    let shape = collision_object.get_mut_base().state.shapes[p_index];
    collision_object.get_mut_base().state.shapes[p_index].collider_handle =
        ColliderHandle::invalid();
    if let Some(shape) = physics_shapes.get_mut(&get_id_rid(shape.id, physics_ids)) {
        shape
            .get_mut_base()
            .remove_owner(collision_object.get_base().get_id());
    }
    collision_object.get_mut_base().state.shapes.remove(p_index);
    if collision_object.get_base().is_space_valid() {
        collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
    }
    collision_object
        .get_mut_base()
        .update_shapes_indexes(physics_engine);
}

pub(super) fn set_shape(
    collision_object: &mut dyn IRapierCollisionObject,
    p_index: usize,
    p_shape: RapierId,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_shapes: &mut PhysicsShapes,
    physics_ids: &PhysicsIds,
) {
    if p_index >= collision_object.get_base().state.shapes.len() {
        return;
    }
    collision_object.get_mut_base().state.shapes[p_index].collider_handle =
        collision_object.get_base().destroy_shape(
            collision_object.get_base().state.shapes[p_index],
            p_index,
            physics_spaces,
            physics_engine,
            physics_ids,
        );
    let shape = collision_object.get_base().state.shapes[p_index];
    if let Some(shape) = physics_shapes.get_mut(&get_id_rid(shape.id, physics_ids)) {
        shape
            .get_mut_base()
            .remove_owner(collision_object.get_base().get_id());
    }
    collision_object.get_mut_base().state.shapes[p_index].id = p_shape;
    if let Some(shape) = physics_shapes.get_mut(&get_id_rid(shape.id, physics_ids)) {
        shape
            .get_mut_base()
            .add_owner(collision_object.get_base().get_id());
    }
    if !shape.disabled {
        collision_object.get_mut_base().state.shapes[p_index].collider_handle =
            collision_object.create_shape(shape, p_index, physics_engine);
        collision_object.get_base().update_shape_transform(
            &collision_object.get_base().state.shapes[p_index],
            physics_engine,
        );
    }
    if collision_object.get_base().is_space_valid() {
        collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
    }
}

pub(super) fn set_shape_transform(
    collision_object: &mut dyn IRapierCollisionObject,
    p_index: usize,
    p_transform: Transform,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_ids: &PhysicsIds,
) {
    if p_index >= collision_object.get_base().state.shapes.len() {
        return;
    }
    collision_object.get_mut_base().state.shapes[p_index].xform = p_transform;
    let shape = &collision_object.get_base().state.shapes[p_index];
    collision_object
        .get_base()
        .update_shape_transform(shape, physics_engine);
    if collision_object.get_base().is_space_valid() {
        collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
    }
}

pub(super) fn set_shape_disabled(
    collision_object: &mut dyn IRapierCollisionObject,
    p_index: usize,
    p_disabled: bool,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_ids: &PhysicsIds,
) {
    if p_index >= collision_object.get_base().state.shapes.len() {
        return;
    }
    let shape = collision_object.get_base().state.shapes[p_index];
    if shape.disabled == p_disabled {
        return;
    }
    collision_object.get_mut_base().state.shapes[p_index].disabled = p_disabled;
    let shape = collision_object.get_base().state.shapes[p_index];
    if shape.disabled {
        collision_object.get_mut_base().state.shapes[p_index].collider_handle =
            collision_object.get_base().destroy_shape(
                shape,
                p_index,
                physics_spaces,
                physics_engine,
                physics_ids,
            );
    }
    if !shape.disabled {
        collision_object.get_mut_base().state.shapes[p_index].collider_handle =
            collision_object.create_shape(shape, p_index, physics_engine);
        collision_object.get_base().update_shape_transform(
            &collision_object.get_base().state.shapes[p_index],
            physics_engine,
        );
    }
    if collision_object.get_base().is_space_valid() {
        collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
    }
}

