pub(super) fn get_total_gravity(&self) -> Vector {
    let mut space_rid = Rid::Invalid;
    let mut gravity_scale = 1.0;
    let physics_data = physics_data();
    if let Some(body) = physics_data.collision_objects.get(&self.body) {
        space_rid = body.get_base().get_space(&physics_data.ids);
        if let Some(body) = body.get_body() {
            if body.using_area_gravity() {
                return body.total_gravity();
            } else {
                gravity_scale = body.gravity_scale();
            }
        }
    }
    if let Some(space) = physics_data.spaces.get(&space_rid) {
        let default_gravity =
            variant_to_float(&space.get_default_area_param(AreaParameter::GRAVITY));
        let default_gravity_vector: Vector = space
            .get_default_area_param(AreaParameter::GRAVITY_VECTOR)
            .try_to()
            .unwrap_or_default();
        return default_gravity_vector * gravity_scale * default_gravity;
    }
    Vector::ZERO
}

pub(super) fn get_transform(&self) -> Transform {
    let physics_data = physics_data();
    if let Some(body) = physics_data.collision_objects.get(&self.body)
        && let Some(body) = body.get_body()
    {
        return body.get_base().get_transform();
    }
    Transform::IDENTITY
}

pub(super) fn set_sleep_state(&mut self, enabled: bool) {
    let physics_data = physics_data();
    if let Some(body) = physics_data.collision_objects.get_mut(&self.body)
        && let Some(body) = body.get_mut_body()
        && let Some(space) = physics_data
            .spaces
            .get_mut(&body.get_base().get_space(&physics_data.ids))
    {
        body.set_active(!enabled, space);
    }
}

pub(super) fn get_contact_collider_id(&self, contact_idx: i32) -> u64 {
    let physics_data = physics_data();
    if let Some(body) = physics_data.collision_objects.get(&self.body)
        && let Some(body) = body.get_body()
        && let Some(contact) = body.contacts().get(contact_idx as usize)
    {
        let rapier_id = contact.collider_instance_id;
        if let Some(rid) = physics_data.ids.get(&rapier_id)
            && let Some(collider_obj) = physics_data.collision_objects.get(rid)
        {
            return collider_obj.get_base().get_instance_id();
        }
    }
    0
}

pub(super) fn get_contact_collider_object(&self, contact_idx: i32) -> Option<Gd<Object>> {
    let physics_data = physics_data();
    if let Some(body) = physics_data.collision_objects.get(&self.body)
        && let Some(body) = body.get_body()
        && let Some(contact) = body.contacts().get(contact_idx as usize)
    {
        let rapier_id = contact.collider_instance_id;
        if let Some(rid) = physics_data.ids.get(&rapier_id)
            && let Some(collider_obj) = physics_data.collision_objects.get(rid)
        {
            let instance_id = collider_obj.get_base().get_instance_id();
            match Gd::try_from_instance_id(InstanceId::from_i64(instance_id as i64)) {
                Ok(object) => return Some(object),
                Err(_) => return None,
            }
        }
    }
    None
}

pub(super) fn integrate_forces(&mut self) {
    let step = RapierSpace::get_last_step();
    let mut linear_velocity = self.get_linear_velocity();
    linear_velocity += self.get_total_gravity() * step;
    linear_velocity *= (1.0 - step * self.get_total_linear_damp()).max(0.0);
    let mut angular_velocity = self.get_angular_velocity();
    angular_velocity *= (1.0 - step * self.get_total_angular_damp()).max(0.0);
    self.set_linear_velocity(linear_velocity);
    self.set_angular_velocity(angular_velocity);
    let physics_data = physics_data();
    if let Some(body) = physics_data.collision_objects.get_mut(&self.body)
        && let Some(body) = body.get_mut_body()
        && let Some(space) = physics_data
            .spaces
            .get_mut(&body.get_base().get_space(&physics_data.ids))
    {
        body.on_marked_active(space);
    }
}

