    if let Some(joint) = physics_data.joints.get(&joint) {
        match param {
            JointParam::MAX_FORCE => joint.get_base().get_max_force(),
            JointParam::BIAS => {
                if let RapierJoint::RapierRevoluteJoint(rev_joint) = joint {
                    rev_joint.get_bias_param()
