                .destroy_joint(&mut physics_data.physics_engine);
        }
    } else {
        let id = self.next_id();
        joint = RapierJoint::RapierEmptyJoint(RapierEmptyJoint::new(id));
        physics_data.joints.insert(rid, joint);
    }
}

pub(super) fn joint_change_type(&mut self, joint: Rid, joint_type: RapierJointType) {
    let physics_data = physics_data();
    if let Some(joint_obj) = physics_data.joints.get_mut(&joint) {
        let space_handle = joint_obj.get_base().get_space_id();
        let joint_handle = joint_obj.get_base().get_handle();
        // Call the physics engine to recreate the joint
        let new_handle =
            physics_data
                .physics_engine
                .recreate_joint(space_handle, joint_handle, joint_type);
        if new_handle != JointHandle::default() {
            // Update the joint object's handle and type
            joint_obj.get_mut_base().set_handle(new_handle);
        }
        joint_obj.get_mut_base().set_joint_type(joint_type);
    }
}

pub(super) fn free_rid(&mut self, rid: Rid) {
    let physics_data = physics_data();
    let mut space_to_reset = Rid::Invalid;
    if let Some(mut shape) = physics_data.shapes.remove(&rid) {
        for owner in shape.get_base().get_owners().keys() {
            if let Some(body) = physics_data
                .collision_objects
                .get_mut(&get_id_rid(*owner, &physics_data.ids))
            {
                space_to_reset = body.get_base().get_space(&physics_data.ids);
                body.remove_shape_rid(
                    shape.get_base().get_rid(),
                    &mut physics_data.physics_engine,
                    &mut physics_data.spaces,
                    &mut physics_data.shapes,
                    &physics_data.ids,
                );
            }
        }
        shape
            .get_mut_base()
            .destroy_shape(&mut physics_data.physics_engine);
        remove_id_rid(shape.get_base().get_id(), &mut physics_data.ids);
    } else if let Some(mut body) = physics_data.collision_objects.remove(&rid) {
        space_to_reset = body.get_base().get_space(&physics_data.ids);
        body.set_space(
            Rid::Invalid,
            &mut physics_data.physics_engine,
            &mut physics_data.spaces,
            &mut physics_data.ids,
        );
        remove_id_rid(body.get_base().get_id(), &mut physics_data.ids);
    } else if let Some(mut space) = physics_data.spaces.remove(&rid) {
        let space_handle = space.get_state().get_id();
        remove_id_rid(space.get_state().get_id(), &mut physics_data.ids);
        space
            .get_mut_state()
            .destroy(&mut physics_data.physics_engine);
        physics_data.active_spaces.remove(&space_handle);
    } else if let Some(mut joint) = physics_data.joints.remove(&rid) {
        space_to_reset = joint.get_base().get_space(&physics_data.ids);
        joint
            .get_mut_base()
            .destroy_joint(&mut physics_data.physics_engine);
        remove_id_rid(joint.get_base().get_id(), &mut physics_data.ids);
    } else if let Some(mut fluid) = physics_data.fluids.remove(&rid) {
        fluid.destroy_fluid(&mut physics_data.physics_engine);
        remove_id_rid(fluid.get_id(), &mut physics_data.ids);
    }
    if let Some(space) = physics_data.spaces.get_mut(&space_to_reset) {
        space.get_mut_state().reset_space_if_empty(
            &mut physics_data.physics_engine,
            &RapierSpace::get_world_settings(),
        );
    }
    // If there are no more objects, reset the ids. Ensures there will be determinism.
    if physics_data.collision_objects.is_empty()
        && physics_data.spaces.is_empty()
        && physics_data.joints.is_empty()
        && physics_data.fluids.is_empty()
        && physics_data.shapes.is_empty()
        && physics_data.ids.is_empty()
    {
        self.id = RapierId::default();
    }
}

pub(super) fn get_id(&self, rid: Rid) -> u64 {
    let physics_data = physics_data();
    if let Some(shape) = physics_data.shapes.get(&rid) {
        return shape.get_base().get_id();
    } else if let Some(body) = physics_data.collision_objects.get(&rid) {
        return body.get_base().get_id();
    } else if let Some(space) = physics_data.spaces.get(&rid) {
        return space.get_state().get_id();
    } else if let Some(joint) = physics_data.joints.get(&rid) {
        return joint.get_base().get_id();
    } else if let Some(fluid) = physics_data.fluids.get(&rid) {
        return fluid.get_id();
    }
    0
}

pub fn register_setting(
    p_name: &str,
    p_value: Variant,
    p_needs_restart: bool,
    p_hint: PropertyHint,
    p_hint_string: &str,
) {
    let mut project_settings = ProjectSettings::singleton();
    if !project_settings.has_setting(p_name) {
        project_settings.set(p_name, &p_value.clone());
    }
    let mut property_info = VarDictionary::new();
    let _ = property_info.insert("name", p_name);
    let _ = property_info.insert("type", p_value.get_type());
    let _ = property_info.insert("hint", p_hint);
    let _ = property_info.insert("hint_string", p_hint_string);
    project_settings.add_property_info(&property_info);
    project_settings.set_initial_value(p_name, &p_value);
    project_settings.set_restart_if_changed(p_name, p_needs_restart);
    static mut ORDER: i32 = 1000000;
    unsafe {
        project_settings.set_order(p_name, ORDER);
        ORDER += 1;
    }
}

fn get_setting_int(p_setting: &str) -> i64 {
    let project_settings = ProjectSettings::singleton();
    let setting_value = project_settings.get_setting_with_override(p_setting);
    setting_value.to::<i64>()
}

fn get_setting_double(p_setting: &str) -> f64 {
    let project_settings = ProjectSettings::singleton();
    let setting_value = project_settings.get_setting_with_override(p_setting);
    setting_value.to::<f64>()
}

pub fn apply_preset() {
    let preset = RapierProjectSettings::get_solver_preset();
    if matches!(preset, RapierSolverPreset::Custom) {
        return; // Don't apply when Custom
    }
    // Set flag to prevent detection during application
    APPLYING_PRESET.store(true, Ordering::Release);
    let mut project_settings = ProjectSettings::singleton();
    match preset {
        RapierSolverPreset::Stability => {
            // Stability preset
            project_settings.set(
                SOLVER_NUM_INTERNAL_PGS_ITERATIONS,
                &Variant::from(STABILITY_PGS_ITERATIONS as i32),
            );
            project_settings.set(
                SOLVER_NUM_INTERNAL_STABILIZATION_ITERATIONS,
                &Variant::from(STABILITY_STABILIZATION_ITERATIONS as i32),
            );
            project_settings.set(
                CONTACT_DAMPING_RATIO,
                &Variant::from(STABILITY_DAMPING_RATIO),
            );
            project_settings.set(
                CONTACT_NATURAL_FREQUENCY,
                &Variant::from(STABILITY_NATURAL_FREQUENCY),
            );
        }
        RapierSolverPreset::Performance => {
            // Performance preset (default Rapier values)
            let integration_parameters = IntegrationParameters::default();
            project_settings.set(
                SOLVER_NUM_INTERNAL_PGS_ITERATIONS,
                &Variant::from(integration_parameters.num_internal_pgs_iterations as i32),
            );
            project_settings.set(
                SOLVER_NUM_INTERNAL_STABILIZATION_ITERATIONS,
                &Variant::from(
                    integration_parameters.num_internal_stabilization_iterations as i32,
                ),
            );
            project_settings.set(
                CONTACT_DAMPING_RATIO,
                &Variant::from(integration_parameters.contact_softness.damping_ratio),
            );
            project_settings.set(
                CONTACT_NATURAL_FREQUENCY,
                &Variant::from(integration_parameters.contact_softness.natural_frequency),
            );
        }
        RapierSolverPreset::Custom => {} // Do nothing for Custom
    }
    APPLYING_PRESET.store(false, Ordering::Release);
}

