        collide_with_areas,
        &query_excluded_info,
        &physics_data.collision_objects,
        &physics_data.ids,
        space,
        false,
    );
    if results.is_empty() {
        return false;
    }
    let mut found_collision: bool = false;
    let shape_position = shape_info.transform.translation;
    let mut deepest_collision_index: Option<usize> = None;
    let mut deepest_collision_distance: Option<f32> = None;
    for (i, result) in results.iter().enumerate() {
        if !result.collided {
            continue;
        }
        found_collision = true;
        let collision_distance: f32 = (result.pixel_witness2 - shape_position).length();
        if let Some(current) = deepest_collision_distance {
            if collision_distance < current {
                deepest_collision_distance = Some(collision_distance);
                deepest_collision_index = Some(i);
            }
        } else {
            deepest_collision_distance = Some(collision_distance);
            deepest_collision_index = Some(i);
        }
    }
    if !found_collision {
        return false;
    }
    if let Some(i) = deepest_collision_index {
        let deepest_collision: &ShapeCastResult = &results[i];
        if !deepest_collision.user_data.is_valid() {
            return false;
        }
        let (rid, shape_index) = RapierCollisionObjectBase::get_collider_user_data(
            &deepest_collision.user_data,
            &physics_data.ids,
        );
        let r_info = unsafe { &mut *rest_info.ptr() };
        let Some(collision_object_2d) = physics_data.collision_objects.get(&rid) else {
            return false;
        };
        let instance_id = collision_object_2d.get_base().get_instance_id();
        r_info.collider_id = ObjectId { id: instance_id };
        let collision_point = vector_to_godot(deepest_collision.pixel_witness2);
        if let Some(body) = collision_object_2d.get_body() {
            let rel_vec = collision_point
                - (body.get_base().get_transform().origin + body.get_center_of_mass());
            r_info.linear_velocity = body.get_linear_velocity(&physics_data.physics_engine)
                + cross_product(
                    body.get_angular_velocity(&physics_data.physics_engine),
                    rel_vec,
                );
        } else {
            r_info.linear_velocity = Vector::default();
        }
        r_info.normal = vector_to_godot(deepest_collision.normal2);
        r_info.rid = rid;
        r_info.shape = shape_index as i32;
        r_info.point = collision_point;
        return true;
    }
    false
}

pub fn create(
    id: RapierId,
    rid: Rid,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
) {
    let mut direct_access = RapierDirectSpaceState::new_alloc();
    direct_access.bind_mut().set_space(rid);
    let project_settings = ProjectSettings::singleton();
    let default_gravity_dir: Vector = project_settings
        .get_setting_with_override(DEFAULT_GRAVITY_VECTOR)
        .try_to()
        .unwrap_or_default();
    let default_gravity_value =
        variant_to_float(&project_settings.get_setting_with_override(DEFAULT_GRAVITY));
    let space = Self {
        direct_access: Some(direct_access.upcast()),
        contact_max_allowed_penetration: 0.0,
        default_gravity_dir,
        default_gravity_value,
        default_linear_damping: 0.0,
        default_angular_damping: 0.0,
        contact_debug: PackedVectorArray::new(),
        contact_debug_count: 0,
        ghost_collision_distance: RapierProjectSettings::get_ghost_collision_distance(),
        #[cfg(feature = "dim2")]
        constraint_default_bias: 0.2,
        state: RapierSpaceState::new(id, physics_engine, &Self::get_world_settings()),
    };
    physics_spaces.insert(rid, space);
}

pub fn get_last_step() -> real {
    let project_settings = ProjectSettings::singleton();
    let physics_fps =
        project_settings.get_setting_with_override("physics/common/physics_ticks_per_second");
    let mut last_step = 1e-3;
    if !physics_fps.is_nil() {
        last_step = 1.0 / (physics_fps.to::<i32>() as f32);
    }
    last_step
}

pub fn get_direct_state(&self) -> &Option<Gd<PhysicsDirectSpaceState>> {
    &self.direct_access
}

#[cfg(feature = "dim2")]
fn shape_contact_aabb(shape: &RapierShape, transform: Transform) -> Rect {
    let mut aabb = shape.get_base().get_aabb(transform.origin);
    let mut local_transform = transform;
    local_transform.origin = Vector::default();
    aabb.size = transform_scale(&local_transform) * aabb.size;
    aabb
}

#[cfg(feature = "dim3")]
fn shape_contact_aabb(shape: &RapierShape, transform: Transform) -> Rect {
    let local_aabb = shape.get_base().get_aabb(Vector::default());
    let local_end = local_aabb.end();
    let mut min = Vector::new(Real::INFINITY, Real::INFINITY, Real::INFINITY);
    let mut max = Vector::new(Real::NEG_INFINITY, Real::NEG_INFINITY, Real::NEG_INFINITY);
    for x in [local_aabb.position.x, local_end.x] {
        for y in [local_aabb.position.y, local_end.y] {
            for z in [local_aabb.position.z, local_end.z] {
                let point = transform * Vector::new(x, y, z);
                min = min.coord_min(point);
                max = max.coord_max(point);
            }
        }
    }
    Rect::from_position_end(min, max)
}

impl PhysicsEngine {
    #[allow(clippy::too_many_arguments)]
    fn should_skip_collision_one_dir(
        &self,
        contact: &ContactResult,
        body_shape: &RapierShape,
        collision_body: &RapierCollisionObject,
        shape_index: usize,
        col_shape_transform: &Transform,
        moving_shape_origin: Vector,
        p_margin: f32,
        last_step: f32,
        _p_motion: Vector,
    ) -> bool {
        if body_shape.allows_one_way_collision()
            && collision_body
                .get_base()
                .is_shape_set_as_one_way_collision(shape_index)
        {
            let valid_dir = get_one_way_valid_direction(
                col_shape_transform,
                collision_body
                    .get_base()
                    .get_shape_one_way_collision_direction(shape_index),
            );
            let owc_margin = collision_body
                .get_base()
                .get_shape_one_way_collision_margin(shape_index);
            let mut platform_linear_velocity = Vector::default();
            if let Some(b) = collision_body.get_body()
                && b.get_base().mode.ord() >= BodyMode::KINEMATIC.ord()
            {
                platform_linear_velocity = b.get_linear_velocity(self);
            }
            let valid_depth = one_way_valid_depth(
                owc_margin,
                p_margin,
                platform_linear_velocity,
                last_step,
                valid_dir,
            );
            if is_one_way_contact_invalid(
                contact,
                moving_shape_origin,
                col_shape_transform.origin,
                valid_dir,
                valid_depth,
            ) {
                return true;
            }
        }
        false
    }
}

pub fn collision_filter_body_callback(
    filter_info: &CollisionFilterInfo,
    physics_collision_objects: &PhysicsCollisionObjects,
    physics_ids: &PhysicsIds,
) -> bool {
    let mut colliders_info = CollidersInfo::default();
    (colliders_info.object1, colliders_info.shape1) =
        RapierCollisionObjectBase::get_collider_user_data(&filter_info.user_data1, physics_ids);
    (colliders_info.object2, colliders_info.shape2) =
        RapierCollisionObjectBase::get_collider_user_data(&filter_info.user_data2, physics_ids);
    if let Some(obj1) = physics_collision_objects.get(&colliders_info.object1)
        && let Some(body1) = obj1.get_body()
        && let Some(obj2) = physics_collision_objects.get(&colliders_info.object2)
        && body1.has_exception(obj2.get_base().get_rid())
    {
        return false;
    }
    if let Some(obj2) = physics_collision_objects.get(&colliders_info.object2)
        && let Some(body2) = obj2.get_body()
        && let Some(obj1) = physics_collision_objects.get(&colliders_info.object1)
        && body2.has_exception(obj1.get_base().get_rid())
    {
        return false;
    }
    true
}

