            "Hello world"
        },
    );

    let ret = coroutine_with_return.bind_mut().force_run_to_completion();
    log(format!("Returned value: `{ret}`"));

    node.coroutine(
        #[coroutine]
        || {
            yield frames(5);
            5_i32
        },
    )
    .on_finish(|x| log(format!("Returned value: {x}")))
    .spawn();

    node.start_async_task(async {
        log("Async coroutine started");

        smol::Timer::after(Duration::from_secs(10)).await;

        log("Async coroutine finished");
    });

    node.coroutine(
        #[coroutine]
        || {
            yield frames(2);
            5.0
        },
    )
    .on_finish_callable(Callable::from_fn("anon", {
        let node = node.clone();
        move |args| {
            match args.first() {
                Some(var) => log(format!("Args: {var:?}")),
                None => log_err("Args array is empty"),
            }

            log("Test 5 finished");
            test_6(node.clone());
        }
    }))
    .spawn()
    .bind_mut()
    .finish_with(5_i32.to_variant());
}

fn test_6(node: Gd<Node>) {
    log("Starting test 6");

    node.coroutine({
        let node = node.clone();
        #[coroutine]
        move || {
            log("Coroutine waiting for child_entered_tree signal...");

            let engine = godot::classes::Engine::singleton();

            { 
                // Test wait_for_signal_untyped with a built-in signal.
                // We'll wait for `child_entered_tree` by adding a child after a delay.
                let start_frame = engine.get_process_frames() as i64;

                let signal = Signal::from_object_signal(&node, "child_entered_tree");
                yield wait_for_signal_untyped(signal);

                let end_frame = engine.get_process_frames() as i64;
                let diff = end_frame - start_frame;

                log(format!("Signal received after {diff} frames"));

                if diff < 5 {
                    log_err(format!("Expected at least 5 frames before signal, got: {diff}"));
                }
            }

            {
                // Typed version
                let start_frame = engine.get_process_frames() as i64;

                let typed_sig = node.signals().child_entered_tree();
                yield wait_for_signal(&typed_sig);

                let end_frame = engine.get_process_frames() as i64;
                let diff = end_frame - start_frame;

                log(format!("Typed signal received after {diff} frames"));

                if diff < 5 {
                    log_err(format!("Expected at least 5 frames before typed signal, got: {diff}"));
                }
            }

            log("Test 6 finished");
        }
    })
    .auto_start(true)
    .spawn();

    // Emit the signal by adding a child node after 5 frames.
    node.start_coroutine({
        let node = node.clone();
        #[coroutine]
        move || {
            yield frames(5);

            log("Adding child node to trigger child_entered_tree");
            let child = Node::new_alloc();
            node.clone().add_child(&child);

            yield frames(5);

            let child = Node::new_alloc();
            node.clone().add_child(&child);
            log("Added another child node to trigger child_entered_tree again");
        }
    });
}

#[must_use]
pub struct CoroutineBuilder<R: 'static + ToGodot = ()> {
    #[doc(hidden)]
	pub f: Box<dyn Unpin + Coroutine<(), Yield = SpireYield, Return = Variant>>,
    #[doc(hidden)]
	pub owner: Gd<Node>,
	/// Determines if the coroutine should be polled in [_process](INode::process)
	/// or [_physics_process](INode::physics_process)
    #[doc(hidden)]
	pub poll_mode: PollMode,
	/// Godot [ProcessMode] which the coroutine should run in.
    #[doc(hidden)]
	pub process_mode: ProcessMode,
	/// Whether the coroutine should be started automatically.
    #[doc(hidden)]
	pub auto_start: bool,
	/// A list of callables to invoke when the coroutine finishes.
	///
	/// The callables will be invoked with the coroutine's return value as a Variant.
    #[doc(hidden)]
	pub calls_on_finish: Vec<OnFinishCall>,
	/// Type hint for the coroutine's return value.
    #[doc(hidden)]
	pub type_hint: std::marker::PhantomData<R>,
}

#[doc(hidden)]
pub fn new_coroutine(
	owner: Gd<Node>,
	f: impl 'static + Unpin + Coroutine<(), Yield = SpireYield, Return = R>,
) -> CoroutineBuilder<R> {
	let wrapper =
		#[coroutine] move || {
			let mut f = f;

			loop {
				let pin = Pin::new(&mut f);
				match pin.resume(()) {
					CoroutineState::Yielded(_yield) => {
						yield _yield;
					}
					CoroutineState::Complete(result) => {
						return result.to_variant();
					}
				}
			}
		};

	Self {
		f: Box::new(wrapper),
		owner,
		poll_mode: PollMode::Process,
		process_mode: ProcessMode::INHERIT,
		auto_start: true,
		calls_on_finish: Vec::new(),
		type_hint: std::marker::PhantomData,
	}
}

	#[doc(hidden)]
	pub fn new_async_task(
		owner: Gd<Node>,
		f: impl std::future::Future<Output = R> + 'static,
	) -> CoroutineBuilder<R>
	{
        let result_handle = Arc::new(Mutex::new(Variant::nil()));

        let task: TaskHandle = godot::task::spawn({
            let result_handle = Arc::clone(&result_handle);
            async move {
                let result = f.await;
                let mut lock = result_handle.lock();
                *lock = result.to_variant();
            }
        });

		let routine =
			#[coroutine] move || {
				while task.is_pending() {
					yield frames(1);
				}

                return result_handle.lock().clone();
			};

		CoroutineBuilder {
			f: Box::new(routine),
			owner,
			poll_mode: PollMode::Process,
			process_mode: ProcessMode::INHERIT,
			auto_start: true,
			calls_on_finish: Vec::new(),
			type_hint: std::marker::PhantomData,
		}
	}

pub fn spawn(self) -> Gd<SpireCoroutine> {
	let mut coroutine =
		Gd::from_init_fn(|base| {
			SpireCoroutine {
				base,
				coroutine: self.f,
				poll_mode: self.poll_mode,
				last_yield: None,
				paused: !self.auto_start,
				calls_on_finish: self.calls_on_finish,
			}
		});

	coroutine.set_process_priority(256);
	coroutine.set_physics_process_priority(256);

	coroutine.set_process_mode(self.process_mode);

	let mut owner = self.owner;
	// In case this is being called outside the main thread
	owner.call_deferred("add_child", &[coroutine.to_variant()]);

	coroutine
}

impl IsRunning for Gd<SpireCoroutine> {
	fn is_running(&self) -> bool {
		self.is_instance_valid() && self.bind().is_running()
	}
}

impl IsFinished for Gd<SpireCoroutine> {
	fn is_finished(&self) -> bool {
		!self.is_instance_valid() || self.bind().is_finished()
	}
}

impl IsPaused for Gd<SpireCoroutine> {
	fn is_paused(&self) -> bool {
		self.is_instance_valid() && self.bind().is_paused()
	}
}

pub trait StartAsyncTask {
	/// Starts a new async_task with default settings.
	///
	/// # Example
	///
	/// ```no_run
	/// #![feature(coroutines)]
	/// use godot::prelude::*;
	/// use gdext_coroutines::prelude::*;
	/// 
	/// fn showcase_start_async_task(node: Gd<Node3D>) {
    ///     let sig_future = node.signals().tree_entered().to_future(); 
	///     node.start_async_task({
    ///         async {
    ///             sig_future.await;
    ///             godot_print!("Entered tree!");
    ///         }
    ///     });
	/// }
	/// ```
	fn start_async_task<R>(
		&self,
		f: impl Future<Output = R> + 'static,
	) -> Gd<SpireCoroutine>
		where
			R: 'static + ToGodot,
	{
		self.async_task(f).spawn()
	}

	/// Creates a new coroutine builder with default settings.
	///
	/// The coroutine does not actually `spawn` until you call [CoroutineBuilder::spawn].
	///
	/// # Example
	///
	/// ```no_run
    /// #![feature(coroutines)]
    /// use godot::prelude::*;
    /// use gdext_coroutines::prelude::*;
	///
    /// fn showcase_start_async_task(node: Gd<Node3D>) {
    ///     let sig_future = node.signals().tree_entered().to_future(); 
    ///     node.start_async_task({
    ///         async {
    ///             sig_future.await;
    ///             godot_print!("Entered tree!");
    ///         }
    ///     });
    /// }
	/// ```
	fn async_task<R>(
		&self,
		f: impl Future<Output = R> + 'static,
	) -> CoroutineBuilder<R>
		where
			R: 'static + ToGodot;
}

impl<TSelf> StartAsyncTask for Gd<TSelf>
	where
		TSelf: GodotClass + Inherits<Node>,
{
	fn async_task<R>(
		&self,
		f: impl Future<Output = R> + 'static,
	) -> CoroutineBuilder<R>
		where
			R: 'static + ToGodot,
	{
		CoroutineBuilder::new_async_task(self.clone().upcast(), f)
	}
}

pub trait StartCoroutine {
	/// Spawns and starts a new coroutine with default settings.
	///
	/// # Example
	///
	/// ```no_run
	/// #![feature(coroutines)]
	/// use godot::prelude::*;
	/// use gdext_coroutines::prelude::*;
	///
	/// fn showcase_start_coroutine(node: Gd<Node2D>) {
	///     node.start_coroutine(
	///         #[coroutine] || {
	///             yield frames(5);
	///             godot_print!("5 frames passed!");
	///         });
	/// }
	/// ```
	/// 
	/// # On Panics
	/// If `f` panics, the SpireCoroutine will automatically self-destruct and the closure will be leaked
	fn start_coroutine<R>(
		&self,
		f: impl 'static + Unpin + Coroutine<(), Yield = SpireYield, Return = R>,
	) -> Gd<SpireCoroutine>
		where
			R: 'static + ToGodot,
	{
		self.coroutine(f).spawn()
	}

	/// Creates a new coroutine builder with default settings.
	///
	/// The coroutine does not actually `spawn` until you call [CoroutineBuilder::spawn].
	///
	/// # Example
	///
	/// ```no_run
	/// #![feature(coroutines)]
	/// use godot::classes::node::ProcessMode;
	/// use godot::prelude::*;
	/// use gdext_coroutines::prelude::*;
	///
	/// fn showcase_coroutine(node: Gd<Node2D>) {
	///     node.coroutine(
	///         #[coroutine] || {
	///             godot_print!("This is a customized coroutine!");
	///             yield seconds(2.0);
	///             godot_print!("2 seconds passed!");
	///         })
	///         .auto_start(false)
	///         .process_mode(ProcessMode::WHEN_PAUSED)
	///         .spawn();
	/// }
	/// ```
	/// 
	/// # On Panics
	/// If `f` panics, the SpireCoroutine will automatically self-destruct and the closure will be leaked
	fn coroutine<R>(
		&self,
		f: impl 'static + Unpin + Coroutine<(), Yield = SpireYield, Return = R>,
	) -> CoroutineBuilder<R>
		where
			R: 'static + ToGodot;
}

impl<TSelf> StartCoroutine for Gd<TSelf>
	where
		TSelf: GodotClass + Inherits<Node>,
{
	fn coroutine<R>(
		&self,
		f: impl 'static + Unpin + Coroutine<(), Yield = SpireYield, Return = R>,
	) -> CoroutineBuilder<R>
		where
			R: 'static + ToGodot,
	{
		CoroutineBuilder::new_coroutine(self.clone().upcast(), f)
	}
}

pub enum SpireYield {
    Frames(i64),
    Seconds(f64),
    Coroutine(Gd<SpireCoroutine>),
