fn tokenize_ty_data_enum(gd_ty: GdScriptType, classes: &[ClassData]) -> TokenStream {
    let enum_data = gd_ty.property_data_ident();

    let mut enum_variants_ident = Vec::new();
    let mut enum_variants_data_ty = Vec::new();

    for class in classes {
        let TweensMap { methods, .. } = &class.tweens_map[gd_ty];
        if methods.is_empty() {
            continue;
        }

        enum_variants_ident.push(class.ident.clone());
        let variant_ident = class_property_data_ident(&class.name, &gd_ty);
        let variant_ty: Type = parse_quote! { #variant_ident };
        enum_variants_data_ty.push(variant_ty);
    }

    {
        enum_variants_ident.push(format_ident!("ViaCallable"));
        enum_variants_data_ty.push(gd_ty.property_via_callable_ty());
    }

    match gd_ty {
        GdScriptType::Vector2 => {
            enum_variants_ident.push(format_ident!("Follow2D"));
            enum_variants_data_ty.push(parse_quote! { PropertyVec2Node2DFollowData });
        }
        GdScriptType::Vector3 => {
            enum_variants_ident.push(format_ident!("Follow3D"));
            enum_variants_data_ty.push(parse_quote! { PropertyVec3Node3DFollowData });
        }
        _ => {}
    }

    quote! {
        #[derive(Debug, Clone)]
        #[allow(unused)]
        #[delegated_enum(impl_conversions)]
        pub enum #enum_data {
            #(#enum_variants_ident(#enum_variants_data_ty),)*
            Custom(PropertyDataCustom),
        }

        impl IGeneralPropertyData for #enum_data {
