fn observe(label: &str, node: &Gd<Node2D>, tween: &SpireTween<LerpMethodData<f64>>) {
    godot_print!("STATE {label} pos={} loop_time={:.12} state={:?} loops={}",
        node.get_position(), tween.get_animation_position(), tween.get_state(), tween.get_loops_finished());
}

#[derive(GodotClass)]
#[class(init, base=Node)]
struct ShakeLoopModeProbe { base: Base<Node> }

fn run<T: GodotClass<Declarer=DeclEngine> + Inherits<Node>>(
    kind: &str, case: &str, mode: LoopMode, loops: i64,
    steps: &[f64], force: bool,
    node: Gd<T>, get_pos: fn(&T)->Vector2, make_shake: fn(&Gd<T>)->Shake,
) {
    let mut tween=make_shake(&node).with_loops(loops,mode);
    let calls=Rc::new(RefCell::new(Vec::<f64>::new()));
    let recorded=Rc::clone(&calls);
    let original=tween.get_callable().clone();
    tween.t.callable=Callable::from_fn("trace_shake",move |args| {
        recorded.borrow_mut().push(args[0].to::<f64>());
        original.call(&[args[0].clone()])
    });
    let mut last=Vector2::ZERO;
    let mut forward_offset=Vector2::ZERO;
    let mut second_loop_changes=0;
    let mut second_loop_calls=Vec::new();
    godot_print!("START kind={kind} case={case} mode={mode:?} loops={loops} force={force}");
    for (i,delta) in steps.iter().enumerate() {
        let loop_before=tween.get_loops_finished();
        let _=tween.process(*delta,false);
        let pos=get_pos(&node);
        if i==0 { forward_offset=pos; }
        if loop_before==1 {
            second_loop_calls.push(*calls.borrow().last().unwrap());
            if pos.distance_to(last)>0.001 { second_loop_changes+=1; }
        }
        godot_print!("STEP index={i} callback={:.12} native_time={:.12} completed_loops={} state={:?} pos={pos}",
            calls.borrow().last().unwrap(),tween.get_animation_position(),tween.get_loops_finished(),tween.get_state());
        last=pos;
    }
    if force {
        tween.force_complete();
        godot_print!("FORCE callback={:.12} completed_loops={} state={:?} pos={}",
            calls.borrow().last().unwrap(),tween.get_loops_finished(),tween.get_state(),get_pos(&node));
    }
    assert!(tween.is_stopped(),"probe must reach a completed state");
    let final_pos=get_pos(&node);
    let final_len=final_pos.length();
    godot_print!("RESULT kind={kind} case={case} mode={mode:?} final_length={final_len:.6} restored={} second_loop_changes={second_loop_changes} second_loop_callbacks={second_loop_calls:?} initial_offset={forward_offset}", final_len<0.001);
    // Observations are printed for baseline/candidate comparison; cancellation,
    // object ownership and timestep math use the real Godot implementation.
    drop(tween);
    node.upcast::<Node>().free();
}

#[godot_api]
impl INode for ShakeLoopModeProbe {
    fn ready(&mut self) {
        let cases: &[(&str,i64,&[f64],bool)]=&[
            ("one_loop_control",1,&[0.5,0.5],false),
            ("two_loops_half_ticks",2,&[0.5,0.5,0.5,0.5],false),
            ("two_loops_reverse_activity",2,&[0.5,0.5,0.25,0.25,0.25,0.25],false),
            ("two_loops_three_ticks",2,&[0.5,0.5,0.25,0.25,0.5],false),
            ("near_first_endpoint",2,&[0.5,0.499999999,0.01,0.25,0.25,0.5],false),
            ("three_loops",3,&[0.5,0.5,0.25,0.25,0.5,0.5,0.5],false),
            ("force_during_second",2,&[0.5,0.5,0.25],true),
        ];
        let mut count=0;
        for mode in [LoopMode::Yoyo,LoopMode::Incremental] {
            for &(case,loops,steps,force) in cases {
                run("Node2D",case,mode,loops,steps,force,Node2D::new_alloc(),Node2D::get_position,
                    |node|node.do_shake(20.0,20.0,1.0,30.0,1.0));
                run("Control",case,mode,loops,steps,force,Control::new_alloc(),Control::get_position,
                    |node|node.do_shake(20.0,20.0,1.0,30.0,1.0));
                count+=2;
            }
        }
        godot_print!("SHAKE_LOOP_MODES_COMPLETE observations={count}");
        self.base().get_tree().quit();
    }
}

pub fn print_results() {
    let mut builder = String::new();

    RESULTS.iter_sync(|name, times| {
        let total: Duration = times.iter().sum();
        let count = times.len() as u32;
        let avg = total / count;

        builder.push_str(&format!("{name}: ran {count} times, avg: {avg:?}, total: {total:?}\n"));

        true
    });

    godot_print!("{builder}");
}

impl FromGodot for EaseKind {
    fn try_from_godot(via: Self::Via) -> Result<Self, ConvertError> {
        if let Ok(curve) = via.clone().try_to::<Gd<Curve>>() {
            Ok(EaseKind::GodotCurve(curve))
        } else if let Ok(callable) = via.clone().try_to::<Callable>() {
            Ok(EaseKind::Callable(callable))
        } else if let Ok(basic) = via.try_to_relaxed::<Ease>() {
            Ok(EaseKind::Basic(basic))
        } else {
            Err(ConvertError::with_error_value("Could not convert Variant to `EaseKind`", via))
        }
    }
}

#[godot_api(secondary)]
impl Spire {
    /// [b]Behavior:[/b] Once every update, invokes [param call], passing a single argument
    /// being the value computed by invoking [param lerp_func] with the arguments
    /// ([param from], [param to], and `weight`), where `weight` is a float
    /// that represents the progress of the tween towards completion (usually computed as: `elapsed_time/duration`).
    ///
    /// [b]Usage:[/b] This is an untyped way of creating a method tweener, if the type being tweened is one of
    /// [int, float, Vector2, Vector2i, Vector3, Vector3i, Color, String], then consider using the typed
    /// variants instead ([method do_call_int], [method do_call_float], etc.), they are more efficient and
    /// don't require specifying a `lerp` function.
    ///
    /// [b]Returns:[/b] A handle that can be used to further customize the tween.
    ///
    /// [b]Parameter [param lerp_func]:[/b] A Callable that takes three arguments: (`from`, `to`, `weight`),
    /// and returns the result of interpolating between `from` and `to` by `weight`. The return value will be
    /// used when invoking [param call].
    ///
    /// [b]Note:[/b] [param call] must accept a single argument. If it requires more arguments,
    /// then either they should have default values, or you can use [method Callable.bind] to bind fixed
    /// arguments to the Callable.
    ///
    /// [b]Note:[/b] Usually, the weight argument passed to [param lerp_func] will be in the range
    /// `0.0 ~ 1.0`, but that is not guaranteed, the Callable must be able to handle arguments outside that range.
    #[func]
    pub fn do_call_custom(
        callable: Callable,
        from: Variant,
        to: Variant,
        duration: f64,
        lerp_func: Callable,
    ) -> Gd<<Variant as TyToMethodTween>::GdTween> {
        <<Variant as TyToMethodTween>::GdTween>::build_custom(callable, from, to, duration, lerp_func)
    }
}

#[godot_api(secondary)]
impl Spire {
    /// [b]Behavior:[/b] Invokes [param call] after [param delay] seconds have passed.
    ///
    /// [b]Usage:[/b] This is similar to using a timer:
    /// ```gdscript
    /// get_tree().create_timer(delay).timeout.connect(call)
    /// ```
    /// except that this can be called from anywhere since it doesn't require accessing the [SceneTree].
    ///
    /// [b]Returns:[/b] A handle that can be used to further customize the tween.
    ///
    /// [b]Note:[/b] No arguments will be passed when invoking [param call]. If it
    /// requires arguments, then either they should have default values, or you can
    /// use [method Callable.bind] to bind fixed arguments to the Callable.
    ///
    /// [b]Note:[/b] If [param call] becomes invalid, including when its target
    /// object is freed, the tween stops and unregisters on its next processing
    /// step or when forced to complete. Cancellation does not emit completion signals.
    #[func]
    pub fn do_delayed_call(callable: Callable, delay: f64) -> Gd<SpireDelayedCall> {
        SpireDelayedCall::build(callable, delay)
    }
}

