#[delegated_enum]
#[derive(Debug, Clone)]
pub enum ObjectOrNode {
    Object(Gd<Object>),
    Node(Gd<Node>),
}

impl ObjectOrNode {
    pub fn from_unchecked_object(obj: Gd<Object>) -> Self {
        match obj.try_cast::<Node>() {
            Ok(node) => Self::Node(node),
            Err(obj) => Self::Object(obj.upcast()),
        }
    }

    /// Panics if the underlying instance has been freed.
    pub fn to_object(&self) -> Gd<Object> {
        match self {
            ObjectOrNode::Object(obj) => {
                debug_assert!(is_instance_id_valid(obj.instance_id_unchecked().to_i64()));
                obj.clone()
            }
            ObjectOrNode::Node(node) => {
                debug_assert!(is_instance_id_valid(node.instance_id_unchecked().to_i64()));
                node.clone().upcast()
            }
        }
    }

    pub fn into_object(self) -> Gd<Object> {
        match self {
            ObjectOrNode::Object(obj) => obj,
            ObjectOrNode::Node(node) => node.upcast(),
        }
    }
}

impl From<Gd<Node>> for ObjectOrNode {
    fn from(node: Gd<Node>) -> Self { Self::Node(node) }
}

pub fn tween_from_gd_handle(handle: Gd<RefCounted>) -> Result<AnyTween, Gd<RefCounted>> {
    macro_rules! match_tys {
        ($Handle: expr, $($Ty: ty => $EnumVar: ident,)*) => {
            match_class! { $Handle,
                $(
                    tween @ $Ty => {
                        let inner = tween.bind().to_ref().clone();
                        Ok(AnyTween::$EnumVar(inner.into()))
                    },
                )*
                other => Err(other),
            }
        };
    }

    match_tys! { handle,
        SpireSequence => Sequence,
        SpireDelayedCall => DelayedCall,
        SpirePropertyInt => Property,
        SpirePropertyFloat => Property,
        SpirePropertyString => Property,
        SpirePropertyColor => Property,
        SpirePropertyVec2 => Property,
        SpirePropertyVec2i => Property,
        SpirePropertyVec3 => Property,
        SpirePropertyVec3i => Property,
        SpireProperty => Property,
        SpireMethodInt => Method,
        SpireMethodFloat => Method,
        SpireMethodString => Method,
        SpireMethodColor => Method,
        SpireMethodVec2 => Method,
        SpireMethodVec2i => Method,
        SpireMethodVec3 => Method,
        SpireMethodVec3i => Method,
        SpireMethod => Method,
    }
}

pub fn bound_to<N: Inherits<Node>>(mut self, node: Gd<N>) -> Self {
    // Binding process is finished in TweensMap::register
    self.bound_nodes.insert(node.upcast());
    self
}

pub fn maybe_bound(mut self, obj: Gd<Object>) -> Self {
    if let Ok(node) = obj.try_cast::<Node>() {
        self.bound_nodes.insert(node);
    }

    self
}

impl<T: ITweenable> TweenPtr<T> {
    /// Binds this tween to the given node.
    /// Unlike the built-in [Tween], Spire tweens can be bound to any number of nodes.
    ///
    /// This influences the tween in several ways:
    /// - It will automatically be deleted when any of the bound nodes is freed.
    /// - If [enum Spire.PauseMode] is set to [constant Spire.PAUSE_MODE_BOUND],
    ///   the tween will only process when all bound nodes are also processing
    ///   (this is checked by calling [method Node.can_process] on each).
    ///
    /// Repeatedly binding the same node is harmless. Explicit bindings persist
    /// across unregister/register and sequence insertion.
    ///
    /// [b]Note:[/b] Property/Method tweeners also track their animated node's
    /// lifetime automatically; explicit binding does not change that behavior.
    pub fn bind_node(&mut self, obj: Gd<Node>)
    where WeakAnyTween: From<WeakTweenPtr<T>> {
        self.bound_nodes_mut().insert(obj.clone());
        TM.node_bind(obj, self.downgrade());
    }

    /// Unbinds this tween from the given node.
    /// See [method bind_node] for details on what binding to a node does.
    ///
    /// Calling this method with a node that isn't bound to this tween is harmless.
    pub fn unbind_node(&mut self, obj: Gd<Node>) {
        self.bound_nodes_mut().remove(&obj);
        TM.node_unbind(obj, self);
    }

    pub fn unregister(&mut self) { TM.tween_unregister(self); }

    pub fn re_register(&mut self)
    where AnyTween: From<Self> {
        let ptr = TweenPtr::clone(self);
        TM.tween_register(ptr);
    }

    pub fn is_registered(&self) -> bool { TM.tween_is_registered(self) }
}

fn check_bound_nodes_validity(&self, is_tree_paused: bool) -> NodesValidityResult {
    enum BoundNodesState {
        AllAliveOrInsideTree,
        SomeOutsideTree,
        SomeDead,
    }

    match (self.get_pause_mode(), eval_bound_nodes_status(self.get_bound_nodes())) {
        (PauseMode::Bound, BoundNodesState::AllAliveOrInsideTree) => {
            if self.get_bound_nodes().iter().any(|node| !node.can_process()) {
                return NodesValidityResult::DontProcess;
            }
        }
        (PauseMode::Bound, BoundNodesState::SomeOutsideTree) => {
            return NodesValidityResult::DontProcess;
        }
        (PauseMode::Process, BoundNodesState::AllAliveOrInsideTree | BoundNodesState::SomeOutsideTree) => {}
        (_, BoundNodesState::SomeDead) => {
            return NodesValidityResult::SomeNodesDead;
        }
        (PauseMode::Stop, _) => {
            if is_tree_paused {
                return NodesValidityResult::DontProcess;
            }
        }
    }

    return NodesValidityResult::CanProcess;

    fn eval_bound_nodes_status(bound_nodes: &SmallSet<[Gd<Node>; 1]>) -> BoundNodesState {
        let mut any_outside = false;

        for node in bound_nodes {
            // Official gdext panics on clone of freed instances, check ID first.
            if !is_instance_id_valid(node.instance_id_unchecked().to_i64()) {
                return BoundNodesState::SomeDead;
            }

            match TM.node_get_status_fresh(node.clone()) {
                NodeStatus::InsideTree => {}
                NodeStatus::OutsideTree => {
                    any_outside = true;
                }
                NodeStatus::Dead { .. } => return BoundNodesState::SomeDead,
            }
        }

        if any_outside { BoundNodesState::SomeOutsideTree } else { BoundNodesState::AllAliveOrInsideTree }
    }
}

