pub fn run(city: &mut City) -> MilestoneResult {
    if !city.misc.present || city.misc.data.len() as i64 != misc_layout::SIZE {
        return MilestoneResult::failed("MISC is missing or has the wrong size");
    }

    let mut misc = city.misc.data.clone();
    let mut progression = read_u32_be(&misc, misc_layout::PROGRESSION) & 0xffff;
    let population = read_u32_be(&misc, misc_layout::NORMAL_POPULATION);
    let mut result = MilestoneResult {
        old_progression: progression,
        progression,
        population,
        ..Default::default()
    };
    result.base_mut().ok = true;

    if progression >= PROGRESSION_REQUIREMENTS.len() as i64 {
        return result;
    }

    let requirement = PROGRESSION_REQUIREMENTS[progression as usize];
    result.requirement = requirement;

    if population <= requirement {
        return result;
    }

    let old_progression = progression;
    progression += 1;
    write_u32_be(&mut misc, misc_layout::PROGRESSION, progression);
    let mut reward_id = -1;
    let mut military_proposal_pending = false;

    if progression < 4 {
        reward_id = progression - 1;
    } else if progression == 4 {
        military_proposal_pending = true;
    } else if progression == 5 {
        reward_id = 3;
    }

    if reward_id >= 0 {
        let rewards = read_u32_be(&misc, misc_layout::GRANTED_REWARDS);
        write_u32_be(&mut misc, misc_layout::GRANTED_REWARDS, rewards | (1 << reward_id));
    }

    rebuild_reward_mask(&mut misc);
    city.misc.replace(misc);
    result.advanced = true;
    result.progression = progression;
    result.reward_id = reward_id;
    result.military_proposal_pending = military_proposal_pending;
    result.base.news_items = vec![NewsEvent::new(NEWS_GROWTH, old_progression)];
    result.base.complete = !military_proposal_pending;
    result
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::sim::testing::{empty_city, sequence_random};

    fn nation_fixture(federal_rate: i64, national_value: i64) -> City {
        let mut city = empty_city(16);
        city.set_misc_u32(misc_layout::NATIONAL_POPULATION, 1_000_000);
        city.set_misc_u32(misc_layout::NATIONAL_VALUE, national_value);
        city.set_misc_u32(misc_layout::NATIONAL_FEDERAL_RATE, federal_rate);
        city.set_misc_u32(misc_layout::NATIONAL_ECONOMY_TREND, 0);
        city
    }

    #[test]
    fn zero_federal_rate_continues_without_a_rate_change() {
        let mut city = nation_fixture(0, 800_000);
        let result = run(&mut city, &mut sequence_random(&[1, 0, 0]));

        assert!(result.base().ok);
        assert_eq!(result.federal_rate, 0);
        assert_eq!(read_u32_be(&city.misc.data, misc_layout::NATIONAL_FEDERAL_RATE), 0);
    }

    #[test]
    fn zero_federal_rate_starts_at_the_lowest_rate_for_a_rate_change() {
        // a national score of 80 raises the rate
        let mut city = nation_fixture(0, 800_000);
        let result = run(&mut city, &mut sequence_random(&[0, 0, 0, 99, 1, 1]));

        assert!(result.base().ok);
        assert_eq!(result.federal_rate, 2);
        assert_eq!(read_u32_be(&city.misc.data, misc_layout::NATIONAL_FEDERAL_RATE), 2);
    }

    #[test]
    fn decrease_keeps_the_lowest_federal_rate() {
        // a national score of 10 lowers the rate
        let mut city = nation_fixture(0, 100_000);
        let result = run(&mut city, &mut sequence_random(&[0, 0, 20, 20, 1, 1]));

        assert!(result.base().ok);
        assert_eq!(result.federal_rate, MIN_FEDERAL_RATE);
        assert!(result.base().news_items.is_empty());
    }
}

pub fn run(city: &mut City, scenario: Option<&mut Scenario>) -> ScenarioResult {
    let mut result = ScenarioResult::default();

    let Some(scenario) = scenario else {
        result.base_mut().ok = true;
        return result;
    };

    let unmet = scenario.unmet_goals(city);

    if unmet.is_empty() {
        result.base.ok = true;
        result.active = true;
        result.outcome = "victory".to_string();
        result.remaining_months = scenario.time_limit_months;
        result.base.game_over_events = vec![GameOverEvent::new("scenario_victory", 0)];

        return result;
    }

    let remaining = (scenario.time_limit_months - 1) & 0xffff;

    if !scenario.set_time_limit_months(city, remaining) {
        return ScenarioResult::failed("cannot store the scenario time limit");
    }

    let failure = remaining == 0;
    result.base.ok = true;
    result.active = true;
    result.outcome = if failure { "failure".to_string() } else { String::new() };
    result.remaining_months = remaining;
    result.unmet = Strings(unmet);

    if failure {
        result.base.game_over_events.push(GameOverEvent::new("scenario_failure", 0));
    }

    result
}

pub fn run_pollution_and_coverage(city: &mut City) -> CoverageResult {
    let mut span = TimingSpan::new();
    span.mark("pollution sources");
    let edge = city.map_size as usize;
    let count = edge * edge;

    if let Some(message) = invalid_chunk(city, count) {
        return CoverageResult::failed(message);
    }

    let old_pollution = &city.xplt.data;
    let old_traffic = &city.xtrf.data;
    let buildings = &city.xbld.data;
    let mut sources = vec![0i32; count];
    let mut center_x_sum = 0i64;
    let mut center_y_sum = 0i64;
    let mut center_count = 0i64;

    for x in 0..edge {
        crate::sim::budget::checkpoint();
        let row = x * edge;

        for y in 0..edge {
            let index = row + y;
            let building = buildings[index] as i64;
            sources[index] = (old_pollution[index] as i64 + old_traffic[index] as i64 / 5 + pollution_weight(building)) as i32;

            if building >= tiles::DEVELOPED_FIRST {
                center_x_sum += x as i64;
                center_y_sum += y as i64;
                center_count += 1;
            }
        }
    }

    let half = city.map_size / 2;
    let center = if center_count == 0 {
        Vec2i::new(half, half)
    } else {
        Vec2i::new(center_x_sum / center_count, center_y_sum / center_count)
    };
    let ordinances = city.misc_u32(misc_layout::ORDINANCES);
    let divisor = super::pollution_divisor(city);
    span.mark("pollution smoothing");
    let (pollution, pollution_sum) = grid_math::smooth_bytes(&sources, edge, 4, divisor.max(1) * 2, 1, 2);
    span.mark("ordinance coverage");
    let mut police = vec![0u8; count];
    let mut fire = vec![0u8; count];

    if ordinances & (POLICE_COVERAGE_ORDINANCE | FIRE_COVERAGE_ORDINANCE) != 0 {
        let occupied: Vec<i32> = buildings
            .iter()
            .map(|&building| ((building as i64) >= tiles::DEVELOPED_FIRST && (building as i64) < tiles::HYDRO_POWER_1) as i32)
            .collect();
        let coverage = grid_math::neighborhood_bytes(&occupied, edge, 2, 32);

        if ordinances & POLICE_COVERAGE_ORDINANCE != 0 {
            police = coverage.clone();
        }

        if ordinances & FIRE_COVERAGE_ORDINANCE != 0 {
            fire = coverage;
        }
    }

    span.mark("station coverage");
    add_stations(city, &mut police, &mut fire);
    span.mark("store maps and totals");
    city.xplt.replace(pollution);
    city.xplc.replace(police);
    city.xfir.replace(fire);
    // MISC totals keep the original half-resolution area unit for economic consumers.
    let pollution_total = pollution_sum / 4;
    city.set_misc_u32(misc_layout::CITY_POLLUTION, pollution_total);
    city.set_misc_u32(misc_layout::CITY_CENTER_X, center.x);
    city.set_misc_u32(misc_layout::CITY_CENTER_Y, center.y);

    let mut result = CoverageResult {
        pollution_total,
        city_center: center,
        ..Default::default()
    };
    result.base_mut().ok = true;
    result.base_mut().timing = span.finish();
    result
}

pub fn set_funding(city: &mut City, values: &[i32], auto_budget: bool) -> BudgetResult {
    if values.len() as i64 != budget::COUNT {
        return BudgetResult::failed("sixteen budget funding values are required");
    }

    if !misc_valid(city) {
        return BudgetResult::failed("MISC is missing or has the wrong size");
    }

    let mut misc = city.misc.data.clone();

    for (budget_id, value) in values.iter().enumerate() {
        write_u32_be(&mut misc, budget_offset(budget_id as i64) + budget::FUNDING, *value as i64);
    }

    write_u32_be(&mut misc, misc_layout::AUTO_BUDGET, auto_budget as i64);
    city.misc.replace(misc);
    let mut result = BudgetResult::default();
    result.base_mut().ok = true;
    result
}

pub fn calculate(city: &City) -> CityValueResult {
    if !city.misc.present || city.misc.data.len() as i64 != misc_layout::SIZE {
        return CityValueResult::failed("MISC is missing or has the wrong size");
    }

    let misc = &city.misc.data;
    let edge = city.map_size;
    let count = |tile: i64| read_count(misc, misc_layout::TILE_COUNTS + tile * 4, edge);
    let mut value = to_i32(read_count(misc, misc_layout::SUBWAY_COUNT, edge) * SUBWAY_TILE_VALUE);

    for tile in tiles::POWER_LINE_FIRST..tiles::DEVELOPED_FIRST {
        let cost = if tile < tiles::ROAD_STRAIGHT_1 {
            2
        } else if tile < tiles::RAIL_STRAIGHT_1 {
            10
        } else if tile < tiles::TUNNEL_ENTRANCE_1 {
            25
        } else if tile < tiles::SUSPENSION_BRIDGE_1 {
            15
        } else {
            // Bridges, highways, and rail-subway entrances.
            if tile < tiles::RAIL_SUBWAY_ENTRANCE_1 { 100 } else { 250 }
        };
        value = to_i32(value + to_i32(count(tile) * cost));
    }

    for (tile, divisor, cost) in BUILDING_RULES {
        value = to_i32(value + to_i32((count(tile) / divisor) * cost));
    }

    let mut result = CityValueResult {
        city_value: value,
        ..Default::default()
    };
    result.base_mut().ok = true;
    result
}

pub fn bankruptcy(city: &City) -> BankruptcyResult {
    let funds = city.funds();
    let bankrupt = funds < BANKRUPTCY_LIMIT;
    let mut result = BankruptcyResult {
        bankrupt,
        funds,
        ..Default::default()
    };
    result.base_mut().ok = true;

    if bankrupt {
        result.base_mut().game_over_events.push(GameOverEvent::new("bankruptcy", funds));
    }

    result
}

impl Context<'_> {
    /// SimulationPhaseContext.record: persist the stories, then keep the result.
    /// An existing name keeps its position, as a Dictionary assignment.
    fn record<T: PhaseResultLike>(&mut self, name: &str, result: &mut T) -> Result<(), String> {
        news::persist(self.city, result.base_mut())?;
        let value = result.to_value();

        match self.phase_results.iter_mut().find(|(existing, _)| existing == name) {
            Some(slot) => slot.1 = value,
            None => self.phase_results.push((name.to_string(), value)),
        }

        Ok(())
    }

    /// Record `result` and report it, or report the phase failure.
    fn finish<T: PhaseResultLike>(&mut self, name: &str, mut result: T) -> PhaseOutcome {
        if !result.base().ok {
            return PhaseOutcome::of(result.base());
        }

        match self.record(name, &mut result) {
            Ok(()) => PhaseOutcome::of(result.base()),
            Err(message) => PhaseOutcome::failed(message),
        }
    }
}

pub fn month_start(city: &mut City) -> MonthStartResult {
    if !city.misc.present || city.misc.data.len() as i64 != misc_layout::SIZE {
        return MonthStartResult::failed("MISC is missing or has the wrong size");
    }

    let misc = city.misc.mutate();

    for index in 0..ZONE_POPULATION_COUNT {
        write_u32_be(misc, misc_layout::ZONE_POPULATIONS + index * 4, 0);
    }

    let month = (city.age_in_days() / DAYS_PER_MONTH) % MONTHS_PER_YEAR;
    let mut result = MonthStartResult {
        cleared_population_fields: ZONE_POPULATION_COUNT,
        ..Default::default()
    };
    result.base_mut().ok = true;
    result.base_mut().newspaper_requested = city.misc_u32(misc_layout::NEWSPAPER_SUBSCRIPTION) != 0 && SUBSCRIPTION_MONTHS.contains(&month);
    result
}

pub fn run(city: &mut City, random: &mut SimRandom, season: i64) -> AftermathResult {
    let cells = city.tile_count() as usize;

    if !(0..=3).contains(&season) {
        return AftermathResult::failed("weather season is out of range");
    }

    if !city.misc.present || city.misc.data.len() as i64 != misc_layout::SIZE {
        return AftermathResult::failed("MISC is missing or has the wrong size");
    }

    for (chunk, id) in [(&city.xbld, "XBLD"), (&city.xzon, "XZON"), (&city.xbit, "XBIT")] {
        if !chunk.present || chunk.data.len() != cells {
            return AftermathResult::failed(format!("{id} is missing or has the wrong size"));
        }
    }

    if !city.xgrp.present || city.xgrp.data.len() != 16 * 52 * 4 {
        return AftermathResult::failed("XGRP is missing or has the wrong size");
    }

    let mut span = TimingSpan::new();
    span.mark("prepare data");
    let mut misc = city.misc.data.clone();
    let mut buildings = city.xbld.data.clone();
    let mut map_changes = Vec::new();
    span.mark("random tree");
    update_random_tree(
        city.map_size,
        random,
        &mut buildings,
        &city.xzon.data,
        &city.xbit.data,
        &mut misc,
        &mut map_changes,
    );
    span.mark("news decay and selection");

    if let Err(message) = news::decay_and_sort(&mut misc) {
        return AftermathResult::failed(message);
    }

    let mut news_items = vec![NewsEvent::new(NEWS_JUNK, 0)];
    append_general_news(random, &misc, &city.xgrp.data, &mut news_items, city.map_size);
    span.mark("inventions");
    let invention_index = release_invention(city.age_in_days(), random, &mut misc, &mut news_items);

    if invention_index >= 0 {
        crate::sim::civic::milestones::rebuild_reward_mask(&mut misc);
    }

    span.mark("weather");
    let old_trend = read_u32_be(&misc, misc_layout::WEATHER_TREND) & 0xff;

    if old_trend >= WEATHER_NAMES.len() as i64 {
        return AftermathResult::failed("weather trend is out of range");
    }

    let weather_roll = random.next_u15() & 7;
    let new_trend = weather_transition(old_trend, season, weather_roll);
    let trend = new_trend as usize;
    let heat = ((read_u32_be(&misc, misc_layout::WEATHER_HEAT) & 0xff) + WEATHER_HEAT_TARGETS[trend]) / 2;
    let wind = ((read_u32_be(&misc, misc_layout::WEATHER_WIND) & 0xff) + WEATHER_WIND_TARGETS[trend]) / 2;
    let rain = ((read_u32_be(&misc, misc_layout::WEATHER_RAIN) & 0xff) + WEATHER_RAIN_TARGETS[trend]) / 2;
    write_u32_be(&mut misc, misc_layout::WEATHER_HEAT, heat);
    write_u32_be(&mut misc, misc_layout::WEATHER_WIND, wind);
    write_u32_be(&mut misc, misc_layout::WEATHER_RAIN, rain);
    write_u32_be(&mut misc, misc_layout::WEATHER_TREND, new_trend);
    span.mark("news insertion");

    if let Err(message) = news::insert_items(&mut misc, &news_items) {
        return AftermathResult::failed(message);
    }

    span.mark("store monthly changes");

    // A month without tree growth must not bump the XBLD revision. The render
    // change signature reads that revision instead of hashing the whole map.
    if buildings != city.xbld.data {
        city.xbld.replace(buildings);
    }

    city.misc.replace(misc);
    let mut result = AftermathResult {
        season,
        old_weather_trend: old_trend,
        weather_trend: new_trend,
        weather_name: WEATHER_NAMES[trend].to_string(),
        weather_roll,
        heat,
        wind,
        rain,
        map_changed: !map_changes.is_empty(),
        map_changes,
        invention_index,
        ..Default::default()
    };
    result.base_mut().ok = true;
    result.base_mut().news_items = news_items;
    result.base_mut().news_queue_updated = true;
    result.base_mut().timing = span.finish();
    result
}

pub fn run(city: &mut City, random: &mut SimRandom) -> PowerResult {
    let mut span = TimingSpan::new();
    span.mark("clear power and scan marks");
    let mut flags = flags_without(&city.xbit.data, FLAG_MARK | FLAG_POWERED);
    let mut total_generation = 0;
    let mut supplied_consumers = 0;
    let mut total_consumers = 0;
    // SC2X cities trace without the original queue limit.
    let bounded_queue = !city.is_extended();
    let mut queue = if bounded_queue { Vec::new() } else { vec![0i64; flags.len()] };
    span.mark("find power sources");
    let plant_ids: Vec<i64> = (tiles::HYDRO_POWER_1..=tiles::COAL_POWER).collect();
    let plants = building_indices(&city.xbld.data, &plant_ids);

    for index in plants {
        if flags[index as usize] as i64 & FLAG_POWERED != 0 {
            continue;
        }

        span.mark("network traversal and generation");
        let component = if bounded_queue {
            trace_bounded_component(city, &mut flags, index, random)
        } else {
            trace_component(city, &mut flags, &mut queue, index, random)
        };

        span.mark("capacity and ordinance totals");
        let mut capacity = component.capacity;
        let consumers = component.consumers;
        total_generation += capacity;
        total_consumers += consumers;

        if city.misc_u32(misc_layout::ORDINANCES) & ordinance_ids::ENERGY_CONSERVATION_MASK != 0 {
            capacity += capacity / 12;
        }

        supplied_consumers += capacity.min(consumers);
        span.mark("distribute power");

        if bounded_queue {
            distribute_bounded(city, &mut flags, index, capacity);
            span.mark("find power sources");
            continue;
        }

        // Power goes to the tiles in trace order until the capacity is used.
        for &tile in &queue[..component.size] {
            let tile = tile as usize;

            if capacity != 0 {
                if city.xbld.data[tile] as i64 >= tiles::DEVELOPED_FIRST {
                    capacity -= 1;
                }

                flags[tile] = (flags[tile] as i64 | FLAG_POWERED) as u8;
            }

            flags[tile] = (flags[tile] as i64 & !FLAG_MARK & 0xff) as u8;
        }

        span.mark("find power sources");
    }

    span.mark("store powered tiles");
    city.xbit.replace(flags);
    span.mark("utilization");
    let usage_percent = if total_generation != 0 {
        ((supplied_consumers * 100) / total_generation).min(100)
    } else {
        100
    };
    let mut result = PowerResult {
        generation: total_generation,
        consumers: total_consumers,
        supplied_consumers,
        usage_percent,
        ..Default::default()
    };
    result.base_mut().ok = true;
    result.base_mut().timing = span.finish();
    result
}

pub fn run(city: &mut City) -> TrafficResult {
    if !city.xtrf.present || city.xtrf.data.len() as i64 != city.decoded_size("XTRF") {
        return TrafficResult::failed("XTRF is missing or has the wrong size");
    }

    let mut span = TimingSpan::new();
    span.mark("copy traffic map");
    let mut traffic = city.xtrf.data.clone();
    let mut total = 0i64;
    span.mark("decay and sum traffic");

    for (index, value) in traffic.iter_mut().enumerate() {
        if index & 1023 == 0 {
            crate::sim::budget::checkpoint();
        }

        let decayed = *value - (*value >> 2);
        *value = decayed;
        total += decayed as i64;
    }

    span.mark("normalize total");

    if city.full_resolution_maps() {
        total /= 4;
    }

    span.mark("store traffic map and total");

    // Decay leaves an empty map unchanged. A redundant write would repaint the
    // city, because the render change signature reads the XTRF revision.
    if traffic != city.xtrf.data {
        city.xtrf.replace(traffic);
    }

    city.set_misc_u32(misc_layout::CITY_TRAFFIC, total);
    let mut result = TrafficResult {
        traffic_count: total,
        ..Default::default()
    };
    result.base_mut().ok = true;
    result.base_mut().timing = span.finish();
    result
}

pub fn run(city: &mut City) -> WaterResult {
    let map_edge = city.map_size;
    let mut span = TimingSpan::new();
    span.mark("clear water and scan marks");
    let mut flags = flags_without(&city.xbit.data, FLAG_MARK | FLAG_WATERED);

    // A water tower keeps its stored water.
    for index in building_indices(&city.xbld.data, &[tiles::WATER_TOWER]) {
        let i = index as usize;
        flags[i] = (flags[i] as i64 | (city.xbit.data[i] as i64 & FLAG_WATERED)) as u8;
    }

    let mut total_supply = 0;
    let mut total_consumers = 0;
    let mut watered_consumers = 0;
    let pump_base_supply = (city.misc_u32(misc_layout::WEATHER_RAIN) & 0xff) / 2 + city.misc_u32(misc_layout::WATER_LEVEL) * 5;
    // SC2X cities trace without the original queue limit.
    let bounded_queue = !city.is_extended();
    let mut queue = if bounded_queue { Vec::new() } else { vec![0i64; flags.len()] };
    span.mark("find water sources");
    let sources = sources_in_scan_order(city, city.compass_rotation());

    for index in sources {
        let i = index as usize;

        if flags[i] as i64 & FLAG_WATERED != 0 || flags[i] as i64 & FLAG_POWERED == 0 {
            continue;
        }

        span.mark("network traversal and supply");
        let component = if bounded_queue {
            trace_bounded_component(city, &mut flags, index, pump_base_supply)
        } else {
            trace_component(&city.xbld.data, &mut flags, &mut queue, index, pump_base_supply, map_edge)
        };

        span.mark("capacity and tower allocation");
        let served = component.supply.min(component.consumers);
        let stored_units = (component.supply - served).min(component.tower_capacity);
        let mut distribution = Distribution {
            served,
            towers_to_fill: (stored_units + 50) / 100,
        };
        total_supply += component.supply;
        total_consumers += component.consumers;
        watered_consumers += served;
        span.mark("distribute water and fill towers");

        if bounded_queue {
            distribute_bounded(city, &mut flags, index, &mut distribution);
            span.mark("find water sources");
            continue;
        }

        for &tile in &queue[..component.size] {
            water_tile(&city.xbld.data, &mut flags, tile, &mut distribution);
            flags[tile as usize] = (flags[tile as usize] as i64 & !FLAG_MARK & 0xff) as u8;
        }

        span.mark("find water sources");
    }

    span.mark("store watered tiles");
    city.xbit.replace(flags);
    span.mark("utilization and treatment capacity");
    let usage_percent = if total_supply != 0 {
        (watered_consumers * 100) / total_supply
    } else {
        100
    };
    let mut treatment_tiles = city.misc_u32(misc_layout::TILE_COUNTS + tiles::WATER_TREATMENT * 4);

    if !city.is_extended() {
        treatment_tiles &= 0xffff;

        if treatment_tiles >= 0x8000 {
            treatment_tiles -= 0x10000;
        }
    }

    let treatment_capacity = (treatment_tiles / 4) * 2000;
    let treatment_sufficient = watered_consumers <= treatment_capacity;
    city.set_misc_u32(misc_layout::TREATMENT_SUFFICIENT, treatment_sufficient as i64);

    let mut result = WaterResult {
        supply: total_supply,
        consumers: total_consumers,
        watered_consumers,
        usage_percent,
        treatment_capacity,
        treatment_sufficient,
        ..Default::default()
    };
    result.base_mut().ok = true;
    result.base_mut().timing = span.finish();
    result
}

pub fn run(city: &mut City, developed_tiles: i64, power_usage_percent: i64, water_usage_percent: i64) -> GraphResult {
    let mut span = TimingSpan::new();
    span.mark("calculate graph values");
    let (values, unemployment) = match calculate_current_values(city, developed_tiles, power_usage_percent, water_usage_percent) {
        Ok(calculated) => calculated,
        Err(message) => return GraphResult::failed(message),
    };

    if !city.xgrp.present || city.xgrp.data.len() as i64 != layout::SIZE {
        return GraphResult::failed("XGRP is missing or has the wrong size");
    }

    span.mark("store unemployment");
    city.set_misc_u32(misc_layout::UNEMPLOYMENT, unemployment);
    span.mark("shift graph histories");
    let (month, elapsed_years) = match advance(city, &values) {
        Ok(shifted) => shifted,
        Err(message) => return GraphResult::failed(message),
    };
    let mut result = GraphResult {
        month,
        elapsed_years,
        values: Ints64(values),
        unemployment,
        ..Default::default()
    };
    result.base_mut().ok = true;
    result.base_mut().timing = span.finish();
    result
}

