#[derive(GodotClass)]
#[class(base=Object, no_init)]
pub struct NativeImportSource {}

#[godot_api]
impl NativeImportSource {
    /// `{platform, warnings, notes, error, root, names, kinds, ids, sources,
    /// payloads}` of an asset file or game folder at an absolute, simplified path.
    #[func]
    fn scan(path: GString) -> VarDictionary {
        let scanned = Source::scan(&path.to_string());
        let records = &scanned.records;
        let mut payloads = VarArray::new();

        for record in records {
            payloads.push(&PackedByteArray::from(record.bytes.as_slice()).to_variant());
        }

        let mut result = VarDictionary::new();
        result.set("platform", scanned.platform.as_str());
        result.set("warnings", &texts(&scanned.warnings));
        result.set("notes", &texts(&scanned.notes));
        result.set("error", scanned.error.as_str());
        result.set("root", scanned.root.as_str());
        result.set(
            "names",
            &records
                .iter()
                .map(|record| GString::from(record.name.as_str()))
                .collect::<PackedStringArray>(),
        );
        result.set(
            "kinds",
            &records
                .iter()
                .map(|record| GString::from(record.kind.as_str()))
                .collect::<PackedStringArray>(),
        );
        result.set("ids", &records.iter().map(|record| record.id).collect::<PackedInt64Array>());
        result.set(
            "sources",
            &records
                .iter()
                .map(|record| GString::from(record.source.as_str()))
                .collect::<PackedStringArray>(),
        );
        result.set("payloads", &payloads);
        result
    }

    /// The file name without an ISO 9660 version suffix or a final dot.
    #[func]
    fn original_name(name: GString) -> GString {
        GString::from(source::original_name(&name.to_string()).as_str())
    }
}

#[derive(GodotClass)]
#[class(base=Object, no_init)]
pub struct NativeJohab {}

#[godot_api]
impl NativeJohab {
    /// The Unicode code point of the pair at `at`, or 0 for an invalid pair.
    #[func]
    fn code_point(bytes: PackedByteArray, at: i64) -> i64 {
        usize::try_from(at).map_or(0, |at| i64::from(johab::code_point(bytes.as_slice(), at)))
    }

    /// True when the whole resource file is Johab text. A pair cannot cross
    /// one of `record_boundaries`.
    #[func]
    fn is_text(bytes: PackedByteArray, record_boundaries: PackedInt32Array) -> bool {
        let boundaries: Option<Vec<usize>> = record_boundaries.as_slice().iter().map(|&end| usize::try_from(end).ok()).collect();

        boundaries.is_some_and(|boundaries| johab::is_text(bytes.as_slice(), &boundaries))
    }

    #[func]
    fn decode_text(bytes: PackedByteArray) -> GString {
        GString::from(johab::decode_text(bytes.as_slice()).as_str())
    }

    /// True when newspaper grammar is Johab text.
    #[func]
    fn is_grammar(grammar: PackedByteArray, offsets: PackedByteArray) -> bool {
        johab::is_grammar(grammar.as_slice(), offsets.as_slice())
    }
}

