#[derive(GodotClass)]
#[class(base=RefCounted, init)]
pub struct NativeTileSnapshot {
    snapshot: Snapshot,
}

#[godot_api]
impl NativeTileSnapshot {
    /// Copy the arrays of `tiles`: `edge`, `buildings`, `zones`, `terrain`,
    /// `altitude`, `underground`, `overlays` and `flags`. Overlays keep their
    /// first byte plane.
    #[func]
    fn capture(&mut self, tiles: VarDictionary) {
        self.snapshot = Snapshot::copy(&GodotTiles::from(&tiles).tiles());
    }

    #[func]
    fn is_empty(&self) -> bool {
        !self.snapshot.tiles().is_complete()
    }

    #[func]
    fn edge(&self) -> i64 {
        self.snapshot.edge as i64
    }

    /// The changed tiles from this copy to `tiles`: `{values, counts, tiles}`.
    /// `counts` holds the changed tiles of each plane, in bit order.
    #[func]
    fn difference(&self, tiles: VarDictionary, ignored_flags: i64) -> VarDictionary {
        let after = GodotTiles::from(&tiles);
        let found = self.snapshot.tiles().difference(&after.tiles(), ignored_flags as u8);
        let counts: PackedInt32Array = found.counts.iter().map(|&count| count as i32).collect();
        let mut result = VarDictionary::new();

        result.set("values", &PackedByteArray::from(found.values.as_slice()));
        result.set("counts", &counts);
        result.set("tiles", found.tiles as i64);
        result
    }

    /// Make this copy hold the arrays of `other`.
    #[func]
    fn copy_from(&mut self, other: Gd<NativeTileSnapshot>) {
        self.snapshot = other.bind().snapshot.clone();
    }

    #[constant]
    const CHANGED_BUILDING: i32 = snapshot::CHANGED_BUILDING as i32;
    #[constant]
    const CHANGED_ZONE: i32 = snapshot::CHANGED_ZONE as i32;
    #[constant]
    const CHANGED_TERRAIN: i32 = snapshot::CHANGED_TERRAIN as i32;
    #[constant]
    const CHANGED_ALTITUDE: i32 = snapshot::CHANGED_ALTITUDE as i32;
    #[constant]
    const CHANGED_UNDERGROUND: i32 = snapshot::CHANGED_UNDERGROUND as i32;
    #[constant]
    const CHANGED_OVERLAY: i32 = snapshot::CHANGED_OVERLAY as i32;
    #[constant]
    const CHANGED_FLAGS: i32 = snapshot::CHANGED_FLAGS as i32;
}

#[derive(GodotClass)]
#[class(base=Object, no_init)]
pub struct NativeCityMinimap {}

#[godot_api]
impl NativeCityMinimap {
    /// The chunk that `mode` reads, or an empty string.
    #[func]
    fn data_chunk(mode: GString) -> GString {
        GString::from(minimap::Mode::from_name(&mode.to_string()).chunk().unwrap_or(""))
    }

    /// The image edge of a map with `edge` tiles.
    #[func]
    fn image_edge(edge: i64) -> i64 {
        minimap::image_edge(edge.max(0) as usize) as i64
    }
    /// An RGBA8 image of the map. `request` has `edge`, `buildings`, `zones`,
    /// `flags`, `underground`, `altitude` (ALTM words), `mode` and `data`, the
    /// mode's data map. `palette` holds 256 RGBA colors. Returns null for invalid arrays.
    #[func]
    fn create_image(request: VarDictionary, palette: PackedByteArray) -> Option<Gd<Image>> {
        let (edge, rgba) = Self::with_city(&request, |city, mode| {
            let indices = minimap::indices(city, mode);
            (minimap::image_edge(city.edge), minimap::colorize(&indices, palette.as_slice()))
        })?;
        Image::create_from_data(
            edge as i32,
            edge as i32,
            false,
            Format::RGBA8,
            &PackedByteArray::from(rgba.as_slice()),
        )
    }

    /// The palette index of one tile, or -1 for invalid arrays.
    #[func]
    fn color_index(request: VarDictionary, x: i64, y: i64) -> i64 {
        Self::with_city(&request, |city, mode| {
            if x < 0 || y < 0 {
                0
            } else {
                i64::from(city.color_index(x as usize, y as usize, mode))
            }
        })
        .unwrap_or(-1)
    }
}

fn sprite_from_image(image: &Gd<Image>) -> Result<Sprite, String> {
    let (w, h) = (image.get_width(), image.get_height());

    if w <= 0 || h <= 0 || w > 8190 || h > 8190 {
        return Err("invalid sprite dimensions".into());
    }

    let mut rgba = Image::create_from_data(w, h, false, image.get_format(), &image.get_data()).ok_or("invalid sprite pixels")?;
    rgba.convert(Format::RGBA8);
    let data = rgba.get_data().to_vec();
    let mut la = Image::create_from_data(w, h, false, Format::RGBA8, &rgba.get_data()).ok_or("invalid sprite pixels")?;
    la.convert(Format::LA8);
    Ok(Sprite {
        w,
        h,
        rgba: data,
        la: la.get_data().to_vec(),
    })
}

fn artwork_image(value: &Variant) -> Result<Sprite, String> {
    let image = value.try_to::<Gd<Image>>().map_err(|_| "invalid HD sprite image")?;
    let (w, h) = (image.get_width(), image.get_height());

    if w <= 0 || h <= 0 || w + 2 > sprites::ATLAS_LIMIT || h + 2 > sprites::ATLAS_LIMIT {
        return Err("invalid HD sprite dimensions".into());
    }

    let mut rgba = Image::create_from_data(w, h, false, image.get_format(), &image.get_data()).ok_or("invalid HD sprite pixels")?;
    rgba.convert(Format::RGBA8);

    Ok(Sprite {
        w,
        h,
        rgba: rgba.get_data().to_vec(),
        la: Vec::new(),
    })
}

impl NativeCityRegionBuilder {
    // Draw records and the images that they index. Each image is made once.
    fn records(cache: &mut HashMap<u64, Gd<Image>>, sprites: &sprites::Sprites, draws: &[Draw]) -> (PackedInt64Array, VarArray) {
        let mut records = Vec::with_capacity(draws.len() * RECORD_SIZE);
        let mut images = VarArray::new();
        let mut slots: HashMap<u64, i64> = HashMap::new();

        for d in draws {
            let slot = *slots.entry(d.image).or_insert_with(|| {
                let image = cache.entry(d.image).or_insert_with(|| {
                    let s = &sprites.images[&d.image];
                    Image::create_from_data(s.w, s.h, false, Format::RGBA8, &PackedByteArray::from(s.rgba.as_slice()))
                        .expect("validated sprite dimensions")
                });

                images.push(&image.to_variant());
                images.len() as i64 - 1
            });

            records.extend([
                d.rect.x as i64,
                d.rect.y as i64,
                d.rect.w as i64,
                d.rect.h as i64,
                slot,
                d.sprite as i64,
                i64::from(d.flip),
                d.depth,
                d.order,
                i64::from(d.ignore),
                d.reference as i64,
                d.thickness as i64,
                d.deck as i64,
                i64::from(d.requires_depth),
            ]);
        }

        (PackedInt64Array::from(records.as_slice()), images)
    }
}

