fn render_diagnostics(view: &mut Gd<RichTextLabel>, diagnostics: &[DiagnosticLine]) {
    view.clear();
    for line in diagnostics {
        if line.meta_path.is_empty() {
            view.add_text(&line.text);
        } else {
            view.push_meta(&line.meta_path.to_variant());
            view.add_text(&line.text);
            view.pop();
        }
        view.add_text("\n");
    }
}

