pub(crate) fn build_profile(profile: &Profile, save_output: bool) -> OperationOutcome {
    let operation = if save_output {
        Operation::Materialize
    } else {
        Operation::Validate
    };
    let source = profile.source.as_str();
    let output = profile.output.as_str();
    if let Err(error) = profiles::validate_source_path(source) {
        return invalid(
            operation,
            &profile.name,
            source,
            output,
            format!("source {error}"),
            vec![source.to_owned()],
        );
    }
    if let Err(error) = profiles::validate_output_path(output) {
        return invalid(
            operation,
            &profile.name,
            source,
            output,
            format!("output {error}"),
            vec![source.to_owned()],
        );
    }
    let started = Time::singleton().get_ticks_msec();
    let attempt = generate_from_project_path(source);
    let elapsed = elapsed_since(started);
    let dependencies = attempt.dependency_list();
    let theme = match attempt.result {
        Ok(theme) => theme,
        Err(failure) => {
            return failed(
                operation,
                &profile.name,
                source,
                output,
                failure.message,
                failure.diagnostics,
                dependencies,
                elapsed,
            );
        }
    };
    if !save_output {
        return succeeded(
            operation,
            &profile.name,
            source,
            output,
            OutcomeStatus::Validated,
            dependencies,
            elapsed,
        );
    }
    match save_theme(&theme, output) {
        Ok(()) => succeeded(
            operation,
            &profile.name,
            source,
            output,
            OutcomeStatus::Success,
            dependencies,
            elapsed_since(started),
        ),
        Err(diagnostic) => failed(
            operation,
            &profile.name,
            source,
            output,
            diagnostic.render(),
            vec![*diagnostic],
            dependencies,
            elapsed,
        ),
    }
}

fn elapsed_since(started: u64) -> i64 {
    Time::singleton().get_ticks_msec().saturating_sub(started) as i64
}

#[derive(Debug)]
pub(crate) struct GenerationAttempt {
    /// Every source and `res://` resource the compilation read.
    pub(crate) dependencies: BTreeSet<String>,
    /// The compiled theme, or the structured failure that replaced it.
    pub(crate) result: Result<Gd<Theme>, GenerationFailure>,
}

pub(crate) fn save_imported(
    theme: &mut Gd<Theme>,
    dependencies: &[String],
    source_file: &str,
    save_path: &str,
) -> Result<(), SaveFailure> {
    let dependency_paths = if dependencies.is_empty() {
        vec![source_file.to_owned()]
    } else {
        dependencies.to_vec()
    };
    theme.set_name(file_stem(source_file));
    theme.set_meta(
        DEPENDENCIES_META,
        &packed_strings(&dependency_paths).to_variant(),
    );
    theme.set_meta(
        DEPENDENCY_FINGERPRINT_META,
        &dependency_fingerprint(&dependency_paths).to_variant(),
    );
    let target = format!("{save_path}.tres");
    let error = ResourceSaver::singleton()
        .save_ex(&*theme)
        .path(target.as_str())
        .done();
    if error != Error::OK {
        let message = format!(
            "cannot save imported theme '{target}' ({})",
            error_string(error.ord() as i64)
        );
        return Err(SaveFailure {
            error,
            diagnostics: vec![
                RunnerDiagnostic::new("save_failed", message.as_str()).at_source(source_file),
            ],
            message,
        });
    }
    Ok(())
}

pub(crate) fn load_imported_theme(source: &str) -> Option<Gd<Theme>> {
    load_theme(source)
}

pub(crate) fn resolved_uid_path(reference: &str) -> Option<String> {
    let uid = ResourceUid::singleton();
    let id = uid.text_to_id(reference);
    if id < 0 || !uid.has_id(id) {
        return None;
    }
    let path = uid.get_id_path(id).to_string();
    if path.is_empty() { None } else { Some(path) }
}

pub(crate) fn load_theme(path: &str) -> Option<Gd<Theme>> {
    let mut loader = ResourceLoader::singleton();
    if !loader.exists_ex(path).type_hint("Theme").done() {
        return None;
    }
    loader
        .load_ex(path)
        .type_hint("Theme")
        .cache_mode(resource_loader::CacheMode::IGNORE_DEEP)
        .done()
        .and_then(|resource| resource.try_cast::<Theme>().ok())
}

pub(crate) fn save_theme(theme: &Gd<Theme>, output: &str) -> Result<(), Box<RunnerDiagnostic>> {
    write_output(output, "tres", |temporary| {
        let error = ResourceSaver::singleton()
            .save_ex(theme)
            .path(temporary)
            .done();
        if error != GodotError::OK {
            return Err(failure(
                "save_failed",
                format!("could not serialize theme '{output}': {error:?}"),
            ));
        }
        Ok(())
    })
}

fn write_output(
    output: &str,
    extension: &str,
    write: impl FnOnce(&str) -> Result<(), Box<RunnerDiagnostic>>,
) -> Result<(), Box<RunnerDiagnostic>> {
    let settings = ProjectSettings::singleton();
    let project = PathBuf::from(settings.globalize_path("res://").to_string());
    let absolute = confined_output(&project, output, extension)
        .map_err(|error| Box::new(RunnerDiagnostic::new("invalid_output", error)))?;
    let directory = absolute
        .parent()
        .expect("output has a containing directory");
    fs::create_dir_all(directory).map_err(|error| failure("output_directory", error))?;
    // Closing the handle before ResourceSaver opens it also supports Windows.
    let temporary = tempfile::Builder::new()
        .prefix(".themosis-")
        .suffix(&format!(".{extension}"))
        .tempfile_in(directory)
        .map_err(|error| failure("save_failed", error))?
        .into_temp_path();
    let temporary_text = temporary
        .to_str()
        .ok_or_else(|| failure("invalid_output", "output path is not UTF-8"))?;
    write(temporary_text)?;
    temporary
        .persist(&absolute)
        .map_err(|error| failure("replace_failed", error.error))?;
    Ok(())
}

pub(crate) fn ensure_project_setting() {
    let mut settings = ProjectSettings::singleton();
    let default = profiles::DEFAULT_CONFIG_PATH.to_variant();
    if !settings.has_setting(profiles::CONFIG_SETTING) {
        settings.set_setting(profiles::CONFIG_SETTING, &default);
    }
    settings.set_initial_value(profiles::CONFIG_SETTING, &default);
    let mut info = VarDictionary::new();
    info.set("name", profiles::CONFIG_SETTING);
    info.set("type", VariantType::STRING.ord() as i64);
    info.set("hint", &PropertyHint::FILE.to_variant());
    info.set("hint_string", "*.json");
    settings.add_property_info(&info);
}

fn configured_path() -> String {
    let path = ProjectSettings::singleton()
        .get_setting(profiles::CONFIG_SETTING)
        .try_to::<GString>()
        .map(|path| path.to_string())
        .unwrap_or_default();
    if path.is_empty() {
        profiles::DEFAULT_CONFIG_PATH.to_owned()
    } else {
        path
    }
}

fn legacy_flag(setting: &str) -> bool {
    ProjectSettings::singleton()
        .get_setting(setting)
        .try_to::<bool>()
        .unwrap_or(true)
}

fn confine_physical(resource_path: &str) -> Result<(), SourceReadError> {
    let settings = ProjectSettings::singleton();
    let project = settings.globalize_path("res://").to_string();
    let physical = settings.globalize_path(resource_path).to_string();
    validate_physical(Path::new(&project), Path::new(&physical))
}

