impl IPopupPanel for ProgressDialog {
    fn ready(&mut self) {
        let main = self.main.clone();
        let mut base = self.base_mut();

        base.add_child(&main);
        base.set_exclusive(true);
        base.set_flag(window::Flags::POPUP, false);
    }
