#[godot_script_impl]
impl WaterDecal {
    const LIFETIME: f64 = 6.0;

    pub fn _ready(&mut self) {
        if !self.is_active {
            return;
        }

        util::timer(&mut self.base.get_tree(), Self::LIFETIME)
            .connect("timeout", &script_callable!(self, Self::on_timeout));
    }

    pub fn on_timeout(&mut self, mut ctx: Context<Self>) {
        let Some(mut tween) = self.base.create_tween() else {
            logger::error!("Failed to create tween!");
            return;
        };

        ctx.reentrant_scope(self, |base: Gd<Decal>| {
            tween.tween_property(
                &base,
                &NodePath::from("modulate"),
                &Color::TRANSPARENT_WHITE.to_variant(),
                1.0,
            );

            let mut script: Rs<Self> = base.clone().into_script();

            tween.tween_callback(&Callable::from_fn("water_decal_tween_out", move |_| {
                script.clean_up();
            }));
        });
    }

    pub fn clean_up(&mut self) {
        self.decal_tracker.bind_mut().free(&self.base);
        self.base.queue_free();
    }
}

impl FireFeature {
    const FIRE_SPAWNER_SCENE: &'static str = "res://resources/Objects/Spawner/fire_spawner.tscn";
    const RECOVERY_RATE: f32 = 0.01;
    const WATER_IMPACT_RATE: f32 = 0.2;

    pub fn new(
        tile_coords: TileCoords,
        mesh: &Gd<MeshInstance3D>,
        config: &super::FireEventConfig,
    ) -> Self {
        let packed = load(Self::FIRE_SPAWNER_SCENE);

        Self {
            packed_fire_scene: packed,
            fire_scene: None,
            fire_strength: 1.0,
            last_fire_strength: 1.0,
            last_fire: 0,
            building_mesh: mesh.to_owned(),
            emission_points: config.emission_points.clone(),
            emission_point_normals: config.emission_point_normals.clone(),
            emission_point_count: config.emission_point_count,
            tile_coords,
        }
    }

    pub fn is_dead(&self) -> bool {
        self.fire_strength.approx_eq(&0.0)
    }

    pub fn is_recovering(&self) -> bool {
        !self.is_dead() && self.fire_strength - self.last_fire_strength >= 0.0
    }

    pub fn update_fire_strength(&mut self, fire: &mut Rs<FireSpawner>) {
        if self.fire_strength.approx_eq(&self.last_fire_strength) {
            return;
        }

        fire.set_fire_strength(self.fire_strength);
        self.last_fire_strength = self.fire_strength;
    }

    pub fn recover_fire_strength(&mut self, delta: f64) {
        if !self.is_recovering() {
            return;
        }

        self.fire_strength = (self.fire_strength
            + Self::RECOVERY_RATE * delta.to_f32().expect("delta can be truncated"))
        .min(1.0);
    }
}

fn process(&mut self, _delta: f64, node: &mut Gd<N>) {
    let current_ticks = Time::singleton().get_ticks_msec();

    if let Some(mut scene) = self.fire_scene.clone() {
        self.update_fire_strength(&mut scene);

        if !self.is_dead() {
            self.last_fire = current_ticks;
            return;
        }

        if current_ticks - self.last_fire < 60_000 {
            return;
        }

        scene.queue_free();
        self.fire_scene = None;
        self.last_fire = current_ticks;
        self.fire_strength = 1.0;
        self.last_fire_strength = 1.0;
        return;
    }

    let tick_delta = current_ticks - self.last_fire;
    let tick_damp = (tick_delta
        .to_f64()
        .expect("tick delta is expected to fit in f64")
        / 10_000.0)
        .min(1.0);
    let rng = rand::rng().sample::<f64, _>(rand::distr::OpenClosed01);

    let chance = rng * tick_damp;

    if chance < 0.9 {
        return;
    }

    logger::debug!("Building will burn! (tick_delta: {tick_delta}, tick_boost: {tick_damp}, rng: {rng}, chance: {chance})");

    let Some(scene_instance) = self.packed_fire_scene.try_instantiate_as::<Node3D>() else {
        logger::error!("Failed to instantiate fire_spawner scene as decendant of Node3D");
        return;
    };

    let aabb = self.building_mesh.get_aabb();
    let aabb_size = (Transform3D::new(self.building_mesh.get_basis(), Vector3::default())
        * aabb.size)
        .abs();

    let mut script: Rs<FireSpawner> = scene_instance.to_script();

    script.set_emission_points(Some(self.emission_points.clone()));
    script.set_emission_point_normals(Some(self.emission_point_normals.clone()));
    script.set_emission_point_count(self.emission_point_count);
    script.resize(aabb_size);

    node.upcast_mut()
        .add_child_ex(&scene_instance)
        .force_readable_name(true)
        .done();

    self.fire_scene = Some(scene_instance.to_script());

    logger::info!("Building started burning: {:?}", self.tile_coords);
}

fn physics_process(&mut self, delta: f64, _node: &mut Gd<N>) {
    self.recover_fire_strength(delta);
}

trait BuildingFeature<N: Inherits<Node>>: Debug {
    fn process(&mut self, _delta: f64, _node: &mut Gd<N>) {}
    fn physics_process(&mut self, _delta: f64, _node: &mut Gd<N>) {}
    fn dispatch_notification(&mut self, _notification: BuildingNotification) {}
}

impl<N: Inherits<Node>> BuildingFeature<N> for Features<dyn BuildingFeature<N>> {
    fn process(&mut self, delta: f64, node: &mut Gd<N>) {
        for item in &mut self.0 {
            item.process(delta, node);
        }
    }

    fn physics_process(&mut self, delta: f64, node: &mut Gd<N>) {
        for item in &mut self.0 {
            item.physics_process(delta, node);
        }
    }

    fn dispatch_notification(&mut self, notification: BuildingNotification) {
        for item in &mut self.0 {
            item.dispatch_notification(notification);
        }
    }
}

