impl Building {
    pub fn _ready(&mut self) {
        self.tile_coords = (
            self.tile_coords_array.get(0).unwrap_or(0),
            self.tile_coords_array.get(1).unwrap_or(0),
        );

        if let Some(config) = &self.events.fire {
