pub(super) fn load_all_libraries(&mut self) {
    let library_db_path = self.get_library_db_path();

    if !std::path::Path::new(&library_db_path).exists() {
        godot_print!(
            "No library database found at {}, skipping load",
            library_db_path
        );
        return;
    }

    self.library_tree
        .as_mut()
        .expect("No library_tree found!")
        .clear();

    let libraries = library_store::get_all_libraries(self.db())
        .expect("Failed to get libraries from database");

    // hide welcome message and show tree
    if !libraries.is_empty() {
        let mut add_library_label = self.base().get_node_as::<Label>("%AddLibraryLabel");
        add_library_label.set_visible(false);

        self.library_tree
            .as_mut()
            .expect("No library_tree found!")
            .set_visible(true);
    }

    for library in libraries {
        let files = library_store::get_all_files_for_library(self.db(), library.id).expect(
            &format!("Failed to load files for library id {}", library.id),
        );

        self.library_roots
            .insert(library.id, library.root_dir.clone());
        self.build_library_tree(&library.root_dir, &library.id, library.name, &files);
        self.add_files_to_state(files);
    }

    self.filtered_indices = (0..self.files.len()).collect();

    self.file_scroll_list
        .as_mut()
        .expect("No file scroll list found in load_all_libraries")
        .set_item_count_deferred(self.filtered_indices.len());

    self.update_all_tags_list();
}

fn create_library_tree_root(
    &mut self,
    root_dir: &str,
    library_name: Option<String>,
    library_id: i32,
    icon: &Gd<Texture2D>,
) -> Gd<TreeItem> {
    let tree = self
        .library_tree
        .as_mut()
        .expect("No library_tree found!")
        .node_mut();

    let mut tree_root = if let Some(tree_root) = tree.get_root() {
        tree_root
    } else {
        tree.create_item().expect("Failed to create root tree item")
    };

    let display_name = library_name
        .unwrap_or_else(|| root_dir.split('/').last().unwrap_or("Library").to_string());

    let mut root = tree_root
        .create_child()
        .expect("Failed to create root tree item");
    root.set_text(0, &GString::from(&display_name));
    root.set_tooltip_text(0, &GString::from(root_dir));
    root.set_meta("full_path", &GString::from(root_dir).to_variant());
    root.set_meta("library_id", &library_id.to_variant());
    root.set_meta("library_name", &GString::from(&display_name).to_variant());
    root.set_icon(0, icon);

    root
}

fn create_library_tree_item(&self, parent: &Gd<TreeItem>, path: &PathBuf) -> Gd<TreeItem> {
    let mut item = parent
        .clone()
        .create_child()
        .expect("Failed to create tree item");

    let name = path
        .file_name()
        .map(|n| n.to_string_lossy().to_string())
        .unwrap_or_else(|| "".to_string());
    let full_path = path.display().to_string();

    item.set_text(0, &GString::from(&name));
    item.set_tooltip_text(0, &GString::from(&full_path));
    item.set_meta("full_path", &GString::from(&full_path).to_variant());

    item
}

fn build_library_tree(
    &mut self,
    root_dir: &str,
    library_id: &i32,
    library_name: Option<String>,
    files: &[AudioFile],
) {
    let folder_icon = load::<Texture2D>("res://addons/audiot/icons/Folder.svg");
    let library_icon = load::<Texture2D>("res://addons/audiot/icons/Library.svg");

    let mut root = self.create_library_tree_root(
        root_dir,
        library_name.clone(),
        *library_id,
        &library_icon,
    );

    let mut dir_items: HashMap<PathBuf, Gd<TreeItem>> = HashMap::new();
    dir_items.insert(PathBuf::from(root_dir), root.clone());

    // collect unique directory paths from the files
    let mut dir_paths: Vec<PathBuf> = files
        .iter()
        .map(|f| PathBuf::from(&f.dir_path))
        .collect::<HashSet<_>>()
        .into_iter()
        .collect();
    dir_paths.sort();

    for dir_path in dir_paths {
        // ensure all ancestor directories have tree items
        let mut ancestors: Vec<PathBuf> = Vec::new();
        let mut current = dir_path.clone();
        while current != PathBuf::from(root_dir) && !dir_items.contains_key(&current) {
            ancestors.push(current.clone());
            current = current.parent().unwrap_or(&current).to_path_buf();

            if current == dir_path {
                // just in case...
                break;
            }
        }

        // we need to add ancestors from the top down, so reverse the list
        ancestors.reverse();

        for ancestor in ancestors {
            let parent_path = ancestor.parent().unwrap_or(&ancestor).to_path_buf();
            if let Some(parent_item) = dir_items.get(&parent_path) {
                // parent has at least one subfolder, so it's not a leaf and we can give it the folder icon
                // we skip this if it has `library_id` since that's a library which has its own icon
                if !parent_item.has_meta("library_id") {
                    parent_item.clone().set_icon(0, &folder_icon);
                }

                let item = self.create_library_tree_item(&parent_item, &ancestor);
                dir_items.insert(ancestor, item);
            }
        }
    }

    root.set_collapsed_recursive(true);
    root.set_collapsed(false);
}

pub(super) fn walk_and_add_library(
    &mut self,
    directory: &str,
    library_name: Option<String>,
    library_id: i32,
    existing_files: &HashMap<(String, String), i32>,
) {
    let folder_icon = load::<Texture2D>("res://addons/audiot/icons/Folder.svg");
    let library_icon = load::<Texture2D>("res://addons/audiot/icons/Library.svg");

    self.library_roots.insert(library_id, directory.to_string());

    let mut root = self.create_library_tree_root(
        directory,
        library_name.clone(),
        library_id,
        &library_icon,
    );

    // tracks which directory path maps to which TreeItem
    let mut dir_items: HashMap<PathBuf, Gd<TreeItem>> = HashMap::new();
    dir_items.insert(PathBuf::from(directory), root.clone());

    let walker = WalkDir::new(directory).into_iter().filter_entry(|e| {
        e.file_name()
            .to_str()
            .map(|s| !s.starts_with('.')) // skip hidden files/directories
            .unwrap_or(false)
    });

    let mut conn = self.db.take().expect("Database connection not initialized");
    let tx = conn
        .transaction()
        .expect("Failed to create transaction in walk_and_add_library");

    // we track seen files to remove deleted ones from the database
    let mut seen_file_ids: HashSet<i32> = HashSet::new();

    // this is walking all of the folders,
    // silently ignoring ones we don't have access to
    for entry in walker.filter_map(|e| e.ok()) {
        if entry.file_type().is_dir() {
            self.handle_dir_entry(entry, directory, &folder_icon, &mut dir_items);
        } else if entry.file_type().is_file() {
            let file_id = self.handle_file_entry(entry, library_id, existing_files, &tx);

            if let Some(id) = file_id {
                seen_file_ids.insert(id);
            }
        }
    }

    // delete files that no longer exist on disk
    if !existing_files.is_empty() {
        let deleted_ids: Vec<i32> = existing_files
            .values()
            .filter(|id| !seen_file_ids.contains(id))
            .copied()
            .collect();

        if !deleted_ids.is_empty() {
            library_store::delete_files(&tx, &deleted_ids)
                .expect("Failed to delete removed files from database");
        }
    }

    let result = tx.commit();
    self.db = Some(conn);
    result.expect("Failed to commit transaction in walk_and_add_library");

    // reset the path filter and show all files after loading
    self.selected_library_path = None;
    self.filtered_indices = (0..self.files.len()).collect();

    // defer set_item_count so it runs after this &mut self borrow is released,
    // avoiding re-entrant bind when `_layout` calls `update_file_list_item`.
    self.file_scroll_list
        .as_mut()
        .expect("No file scroll list found in walk_and_add_library")
        .set_item_count_deferred(self.filtered_indices.len());

    // basically, collapse everything and then show the root folders
    root.set_collapsed_recursive(true);
    root.set_collapsed(false);
}

fn handle_dir_entry(
    &mut self,
    entry: walkdir::DirEntry,
    directory: &str,
    folder_icon: &Gd<Texture2D>,
    dir_items: &mut HashMap<PathBuf, Gd<TreeItem>>,
) {
    // for each dir, we add it to the directory tree so the user can navigate it
    let path = entry.path().to_path_buf();
    let parent_path = path.parent().unwrap_or(&path).to_path_buf();

    // skip the root directory itself since we already have it
    if path == PathBuf::from(directory) {
        return;
    }

    // find parent TreeItem and create a child under it
    if let Some(parent_item) = dir_items.get(&parent_path) {
        // parent has at least one subfolder, so it's not a leaf and we can give it the folder icon
        // we skip this if it has `library_id` since that's a library which has its own icon
        if !parent_item.has_meta("library_id") {
            parent_item.clone().set_icon(0, folder_icon);
        }

        let item = self.create_library_tree_item(&parent_item, &path);
        dir_items.insert(path, item);
    } else {
        godot_print!("WARNING: No parent found for {}", path.display());
    }
}

