fn get_library_db_path(&self) -> String {
    if Engine::singleton().is_editor_hint() {
        // If we're in the editor, we want to use the editor data path
        // https://docs.godotengine.org/en/latest/tutorials/io/data_paths.html#editor-data-paths
        // this is so that adding the addon to multiple projects, you get the same database
        //
        // Here's a cool thing about godot-rust, too! You can actually reference `EditorInterface` here
        // even when running in the stanadlone app.
        //
        // If this were GDScript, even mentioning this clas will cause it to explode
        // when not running in the editor
        let dir_path = EditorInterface::singleton()
            .get_editor_paths()
            .map(|p| p.get_data_dir())
            .unwrap_or_else(|| Os::singleton().get_user_data_dir())
            // add `/audiot` here so it's in its own folder
            .path_join("audiot");

        let dir_path_str = dir_path.to_string();
        if let Err(e) = std::fs::create_dir_all(&dir_path_str) {
            godot_warn!(
                "Failed to create audiot data directory '{}': {}",
                dir_path_str,
                e
            );
        }

        dir_path.path_join("library.db").to_string()
    } else {
        // In the standalone app, we use the user data dir which already has an `audiot` folder
        // https://docs.godotengine.org/en/latest/tutorials/io/data_paths.html#accessing-persistent-user-data-user
        Os::singleton()
            .get_user_data_dir()
            .path_join("library.db")
            .to_string()
    }
}

pub fn update(audiot: &Audiot, mut node: Gd<Control>, file: &AudioFile, is_selected: bool) {
    if !node.is_connected(
        "selected_changed",
        &audiot.base().callable("on_selected_changed"),
    ) {
        node.connect(
            "selected_changed",
            &audiot.base().callable("on_selected_changed"),
        );
    }

    if !node.is_connected(
        "favorite_changed",
        &audiot.base().callable("on_favorite_changed"),
    ) {
        node.connect(
            "favorite_changed",
            &audiot.base().callable("on_favorite_changed"),
        );
    }

    if !node.is_connected(
        "select_directory",
        &audiot.base().callable("on_select_directory"),
    ) {
        node.connect(
            "select_directory",
            &audiot.base().callable("on_select_directory"),
        );
    }

    if !node.is_connected(
        "tag_search",
        &audiot.base().callable("on_file_item_tag_selected"),
    ) {
        node.connect(
            "tag_search",
            &audiot.base().callable("on_file_item_tag_selected"),
        );
    }

    node.set(
        "file_view",
        &audiot.file_view.as_ref().unwrap().node().to_variant(),
    );

    node.set("file_id", &file.id.to_variant());
    node.set("library_id", &file.library_id.to_variant());
    node.set("dir_path", &file.dir_path.to_variant());
    node.set("file_name", &file.file_name.to_variant());

    // these are also used outside of this impl, so we keep them as separate functions
    let arr: Array<GString> = file
        .tags
        .iter()
        .map(|tag| GString::from(&tag.name))
        .collect();
    node.set("tags", &arr.to_variant());

    node.set("is_favorite", &file.is_favorite.to_variant());
    node.set("is_selected", &is_selected.to_variant());
}

