pub(super) struct BattleChrome {
    tiles: BTreeMap<&'static str, Gd<ImageTexture>>,
    /// The window-art words per CRAM line: `[line][(pattern, flip_h, flip_v)]`.
    window_words: [BTreeMap<(u16, bool, bool), Gd<ImageTexture>>; 4],
    damage_words: BTreeMap<(u16, bool, bool), Gd<ImageTexture>>,
    /// The menu font per CRAM line. Every glyph pixel is CRAM index 14 (the
    /// window fill, `$0600` on every line) or 15 (the ink), so a line only
    /// changes the ink (`ps4.asm:11056`, `Battle_DrawCommandIcons`, picks
    /// the line from the status byte).
    fonts: [Gd<ImageTexture>; 4],
    glyph_at: BTreeMap<char, Vector2>,
    glyph: Vector2,
    pub(super) cell: f32,
}

pub(super) fn build(
    pack_dir: &str,
    set: &DialogueSet,
    line_ink: [Color; 4],
) -> Option<BattleChrome> {
    let mut strip = load_image(pack_dir, &set.window.png)?;
    // The window tile art is shared with dialogue, but retail's battle
    // palette line sets colour index 14 (the window fill) to CRAM $0600
    // — pure blue, no green — where the field dialogue line uses $0620.
    // Receipt: oracle/states/battle_command_idle_vdp_25000.json, slot 14
    // of every line. The pack bakes the dialogue palette into the PNG,
    // so the battle chrome remaps that one colour at load.
    remap_color(
        &mut strip,
        Color::from_rgba8(0, 32, 98, 255),
        Color::from_rgba8(0, 0, 98, 255),
    );
    let mut tiles = BTreeMap::new();
    for role in Role::ALL {
        let tile = set.window.role(role)?;
        let region = Rect2i::new(
            Vector2i::new(tile.x, tile.y),
            Vector2i::new(tile.width as i32, tile.height as i32),
        );
        let mut cell = strip.get_region(region)?;
        if tile.flip_h {
            cell.flip_x();
        }
        if tile.flip_v {
            cell.flip_y();
        }
        tiles.insert(role.as_str(), ImageTexture::create_from_image(&cell)?);
    }

    // Battle/menu text is the retail 8x8 ArtNem_Font, not the 8x16
    // dialogue font. The pack asset is preferred; the generated copy is
    // a development fallback until older packs are regenerated.
    let menu_path = format!("{pack_dir}/dialogue/menu_font.png");
    let mut menu_image =
        Image::load_from_file(&GString::from(menu_path.as_str())).or_else(|| {
            let path = Path::new(pack_dir)
                .parent()?
                .join("generated/gfx/ArtNem_Font.png");
            Image::load_from_file(&GString::from(path.to_string_lossy().as_ref()))
        })?;
    // Same $0620 → $0600 battle-palette remap as the window strip: the
    // font sheet bakes the dialogue fill behind its glyphs.
    remap_color(
        &mut menu_image,
        Color::from_rgba8(0, 32, 98, 255),
        Color::from_rgba8(0, 0, 98, 255),
    );
    let mut fonts = Vec::new();
    let mut window_words = Vec::new();
    for ink in line_ink {
        // `Gd::clone` shares the image; a line needs its own pixels.
        let mut font = copy_image(&menu_image)?;
        let mut line_strip = copy_image(&strip)?;
        if ink != Color::from_rgba8(238, 238, 238, 255) {
            remap_color(&mut font, Color::from_rgba8(238, 238, 238, 255), ink);
            remap_color(&mut line_strip, Color::from_rgba8(238, 238, 238, 255), ink);
        }
        fonts.push(ImageTexture::create_from_image(&font)?);
        window_words.push(retail_window_words(&line_strip)?);
    }
    let fonts: [Gd<ImageTexture>; 4] = fonts.try_into().ok()?;
    let window_words: [BTreeMap<_, _>; 4] = window_words.try_into().ok()?;
    let damage_words = match DamageDigitArt::load(Path::new(pack_dir)) {
        Ok(art) => retail_damage_words(&art)?,
        Err(error) => {
            godot_error!("battle: damage-number art failed to load: {error}");
            return None;
        }
    };
    let glyph_at = crate::menu_font::retail_glyphs();
    Some(BattleChrome {
        tiles,
        window_words,
        damage_words,
        fonts,
        glyph_at,
        glyph: Vector2::new(8.0, 8.0),
        cell: set.window.geometry.cell_pixels as f32,
    })
}

fn tile(&self, name: &'static str) -> Option<Gd<ImageTexture>> {
    self.tiles.get(name).cloned()
}

fn retail_window_words(strip: &Gd<Image>) -> Option<BTreeMap<(u16, bool, bool), Gd<ImageTexture>>> {
    // These are the non-role window patterns observed in the decoded battle
    // planes: the 0x680 space/fill, selected/disabled cursor, separator
    // top/middle/bottom, and the HP/TP label glyphs. The source PNG is the
    // `0x680` window-tile load.
    const PATTERNS: [u16; 10] = [
        0x680, 0x6e6, 0x6e7, 0x6e8, 0x6f4, 0x6f5, 0x6f8, 0x6f9, 0x6fa, 0x6ff,
    ];
    let mut words = BTreeMap::new();
    for pattern in PATTERNS {
        let index = i32::from(pattern - WINDOW_BASE_TILE);
        for flip_h in [false, true] {
            for flip_v in [false, true] {
                let region = Rect2i::new(Vector2i::new(index * 8, 0), Vector2i::new(8, 8));
                let mut cell = strip.get_region(region)?;
                if flip_h {
                    cell.flip_x();
                }
                if flip_v {
                    cell.flip_y();
                }
                words.insert(
                    (pattern, flip_h, flip_v),
                    ImageTexture::create_from_image(&cell)?,
                );
            }
        }
    }
    Some(words)
}

fn retail_damage_words(
    art: &DamageDigitArt,
) -> Option<BTreeMap<(u16, bool, bool), Gd<ImageTexture>>> {
    let patterns = [
        0x5e4, 0x5e5, 0x5e6, 0x5e7, 0x5e8, 0x5e9, 0x5ea, 0x5ee, 0x5ef,
    ];
    let mut words = BTreeMap::new();
    for pattern in patterns {
        let rows = art.tile(pattern)?;
        for flip_h in [false, true] {
            for flip_v in [false, true] {
                let mut bytes = Vec::with_capacity(8 * 8 * 4);
                for y in 0..8 {
                    for x in 0..8 {
                        let row = rows[if flip_v { 7 - y } else { y }];
                        let index = row[if flip_h { 7 - x } else { x }];
                        bytes.extend_from_slice(match index {
                            14 => &[0, 0, 98, 255],
                            2 => &[172, 170, 172, 255],
                            15 => &[238, 238, 238, 255],
                            _ => return None,
                        });
                    }
                }
                let image = Image::create_from_data(
                    8,
                    8,
                    false,
                    Format::RGBA8,
                    &PackedByteArray::from(bytes),
                )?;
                words.insert(
                    (pattern, flip_h, flip_v),
                    ImageTexture::create_from_image(&image)?,
                );
            }
        }
    }
    Some(words)
}

fn load_image(pack_dir: &str, name: &str) -> Option<Gd<Image>> {
    let path = format!("{pack_dir}/{name}");
    Image::load_from_file(&GString::from(path.as_str()))
}

fn copy_image(image: &Gd<Image>) -> Option<Gd<Image>> {
    image.get_region(Rect2i::new(
        Vector2i::ZERO,
        Vector2i::new(image.get_width(), image.get_height()),
    ))
}

fn remap_color(image: &mut Gd<Image>, from: Color, to: Color) {
    let (width, height) = (image.get_width(), image.get_height());
    for y in 0..height {
        for x in 0..width {
            if image.get_pixel(x, y) == from {
                image.set_pixel(x, y, to);
            }
        }
    }
}

pub(super) struct AnimationPiece {
    pub(super) initial: Gd<Image>,
    pub(super) frames: Vec<Gd<Image>>,
    pub(super) durations: Vec<u8>,
    pub(super) placements: Vec<EnemyOverlayPlacementFile>,
}

pub(super) fn new(
    base: Gd<Image>,
    pieces: Vec<AnimationPiece>,
    attack: Option<AttackAnimation>,
    initial_phase_ticks: usize,
) -> Option<Self> {
    if pieces.is_empty() && attack.is_none() {
        return None;
    }
    let runtime = pieces
        .into_iter()
        .map(|piece| {
            let (frame, timer) =
                clock_at_phase(piece.frames.len(), &piece.durations, initial_phase_ticks);
            RuntimePiece {
                initial: piece.initial,
                frames: piece.frames,
                durations: piece.durations,
                placements: piece.placements,
                frame,
                timer,
            }
        })
        .collect();
    let mut animation = Self {
        output: base.clone(),
        texture: ImageTexture::create_from_image(&base)?,
        base,
        pieces: runtime,
        attack,
    };
    animation.rebuild()?;
    Some(animation)
}

pub(super) fn texture(&self) -> Gd<ImageTexture> {
    self.texture.clone()
}

pub(super) fn advance(&mut self) -> Option<Gd<ImageTexture>> {
    let mut changed = false;
    for piece in &mut self.pieces {
        changed |= advance_clock(&mut piece.frame, &mut piece.timer, &piece.durations);
    }
    if !changed {
        return None;
    }
    self.rebuild().map(|_| self.texture())
}

pub(crate) fn configure_battles(&mut self, session: &mut Session) {
    // `Field::ready` calls this before the title is shown. An older pack
    // can contain battle records but no command art; letting the node
    // default to empty tiles would make its menus silently incomplete.
    let command_art = match CommandUiArt::load(std::path::Path::new(&self.pack_dir)) {
        Ok(art) => art,
        Err(error) => {
            godot_error!(
                "runtime pack at {} has missing or invalid battle command art: {error}. Rebuild this local pack with `python3 -m psiv_tools pack <rom> <pack-dir>`.",
                self.pack_dir
            );
            let mut tree = self
                .base()
                .get_tree_or_null()
                .expect("Field::ready runs in the scene tree");
            tree.quit_ex().exit_code(1).done();
            return;
        }
    };
    match BattleFiles::load(std::path::Path::new(&self.pack_dir)) {
        Ok(files) => match session.enable_battles(&files) {
            Ok(()) => self.battle_files = Some(files),
            Err(error) => {
                godot_error!("battle pack failed to enable: {error}");
            }
        },
        Err(error) => {
            godot_error!("battle pack failed to load from {}: {error}", self.pack_dir);
        }
    }

    let mut screen = BattleScreen::new_alloc();
    screen.set_z_index(100);
    screen.bind_mut().configure(&self.pack_dir, command_art);
    self.base_mut().add_child(&screen);
    self.battle_screen = Some(screen);
}

pub(crate) fn present_battle_frame(&mut self, battle: psiv_runtime::BattleFrame) {
    if let Some(fault) = &battle.fault {
        godot_error!("{fault}");
    }
    if let Some(view) = battle.view.as_ref() {
        for id in &view.sounds {
            godot_print!("battle SFX dispatch: {id:#04x}");
            self.play_sound(*id);
        }
    }
    if let Some(start) = battle.started
        && !self.present_battle_start(start)
    {
        // The shell cannot draw this battle at all, so it must not leave
        // the fight running unseen: the session ends it the way the
        // shell's own error paths did, and the field keeps the frame.
        if let Some(session) = self.session.as_mut() {
            session.abort_battle();
        }
    }
    if let Some(view) = battle.view {
        self.set_battle_view(view);
    }
}

fn begin_battle_presentation(&mut self, setup: BattleSetup, label: &str) {
    let Some(screen) = self.battle_screen.as_mut() else {
        godot_error!("battle started without a BattleScreen node");
        return;
    };
    screen.bind_mut().begin(setup);
    self.hide_field_for_battle();
    // HOTFIX (live QA: the framed takeover blacked out all battle art
    // while screen-space windows survived): camera repositioning and the
    // cinema letterbox are DISABLED for battles until the framing is
    // rebuilt with live visual verification. The camera stays where the
    // field left it; battle art parents to the BattleScreen at the
    // field camera's current view. Ugly float, but visible - the
    // authentic 320x224 framing returns as its own verified task.
    if let Some(camera) = self.camera.as_mut() {
        camera.set_position(Vector2::new(
            BATTLE_FRAME_WIDTH / 2.0,
            BATTLE_FRAME_HEIGHT / 2.0,
        ));
    }
    godot_print!("battle started: {label}");
}

fn end_battle_presentation(&mut self, events: Vec<RuntimeEvent>) {
    // A defeat's fade owns the picture from here: the session entered its
    // game-over mode on the frame the stage closed, and this stage keeps
    // its last page on screen until the frame the title comes back
    // (`present_game_over` takes it down there).
    if self.runtime().is_some_and(|rt| rt.game_over()) {
        return;
    }
    if let Some(screen) = self.battle_screen.as_mut() {
        screen.set_visible(false);
        screen.bind_mut().release_stage();
    }
    if let Some(visibility) = self.battle_field_visibility.take() {
        if let Some(node) = self.map_sprite.as_mut() {
            node.set_visible(visibility.map);
        }
        if let Some(node) = self.overlay_sprite.as_mut() {
            node.set_visible(visibility.overlay);
        }
        if let Some(node) = self.party.as_mut() {
            node.set_visible(visibility.party);
        }
        if let Some(node) = self.vehicle.as_mut() {
            node.set_visible(visibility.vehicle);
        }
        if let Some(node) = self.dialogue.as_mut() {
            node.set_visible(visibility.dialogue);
        }
        for (node, was_visible) in self.npc_nodes.iter_mut().zip(visibility.npcs) {
            node.node.set_visible(was_visible);
        }
        for ((node, _, _), was_visible) in
            self.follower_nodes.iter_mut().zip(visibility.followers)
        {
            node.set_visible(was_visible);
        }
    }
    self.set_letterbox(false);
    self.process_events(events);
    self.sync_visuals(false);
    godot_print!("battle presentation ended");
}

#[derive(Default)]
pub(super) struct CommandTiles {
    art: Option<CommandUiArt>,
    cache: BTreeMap<(u16, bool, bool), Gd<ImageTexture>>,
}

fn texture(&mut self, tile: u16, flip_h: bool, flip_v: bool) -> Option<Gd<ImageTexture>> {
    if let Some(texture) = self.cache.get(&(tile, flip_h, flip_v)) {
        return Some(texture.clone());
    }
    let art = self.art.as_ref()?;
    let rows = art.tile(tile)?;
    let mut bytes = Vec::with_capacity(8 * 8 * 4);
    for y in 0..8 {
        let row = rows[if flip_v { 7 - y } else { y }];
        for x in 0..8 {
            let index = usize::from(row[if flip_h { 7 - x } else { x }]);
            if index == 0 {
                bytes.extend_from_slice(&[0, 0, 0, 0]);
                continue;
            }
            let color = cram_color(*art.palette_line_3.get(index - 1)?);
            bytes.extend_from_slice(&[color.r8(), color.g8(), color.b8(), 255]);
        }
    }
    let image =
        Image::create_from_data(8, 8, false, Format::RGBA8, &PackedByteArray::from(bytes))?;
    let texture = ImageTexture::create_from_image(&image)?;
    self.cache.insert((tile, flip_h, flip_v), texture.clone());
    Some(texture)
}

