#[godot_api]
impl INode2D for BattleScreen {
    fn init(base: Base<Node2D>) -> Self {
        BattleScreen {
            base,
            pack_dir: String::new(),
            art: None,
            chrome: None,
            tiles: super::tiles::CommandTiles::default(),
            background: None,
            enemy_nodes: Vec::new(),
            party_nodes: Vec::new(),
            enemy_textures: BTreeMap::new(),
            enemy_positions: BTreeMap::new(),
            fusion_frames: Vec::new(),
            fusion_nodes: Vec::new(),
            vehicle_index: None,
            view: None,
        }
    }

    fn ready(&mut self) {
        self.base_mut().set_z_index(100);
        self.base_mut().set_visible(false);
        // The black stage backing must sit BELOW the art children: a
        // CanvasItem's own draw() paints at its z, and the art nodes use
        // negative relative z — a draw_rect here covered the entire stage
        // (found via the self-screenshot loop). A ColorRect child at z -30
        // backs everything instead.
        let mut backing = godot::classes::ColorRect::new_alloc();
        backing.set_position(Vector2::ZERO);
        backing.set_size(Vector2::new(BATTLE_FRAME_WIDTH, BATTLE_FRAME_HEIGHT));
        backing.set_color(Color::BLACK);
        backing.set_z_index(-30);
        self.base_mut().add_child(&backing);
    }

    fn draw(&mut self) {
        draw::compose(self);
    }
}

pub(crate) fn begin(&mut self, setup: BattleSetup) {
    self.clear_sprites();
    self.enemy_positions.clear();
    self.vehicle_index = setup.vehicle_index;
    self.view = None;
    self.build_background(&setup);
    self.build_enemies(&setup.enemies, setup.enemy_animation_phase_ticks);
    self.build_party(&setup);
    self.base_mut().set_visible(true);
    self.base_mut().queue_redraw();
}

pub(crate) fn set_view(&mut self, view: BattleView) {
    for status in &view.enemies {
        if let Some(position) = status.position
            && self.enemy_nodes.iter().any(|enemy| {
                enemy.fighter.get() == status.fighter && enemy.enemy_id != status.enemy_id
            })
        {
            self.reseat_enemy(status.fighter, status.enemy_id, position);
        }
        if let Some(enemy) = self
            .enemy_nodes
            .iter_mut()
            .find(|enemy| enemy.fighter.get() == status.fighter)
        {
            enemy.node.set_visible(status.visible);
        }
    }
    // The party's own sprites are never hidden by a battle, so a revive
    // needs nothing here: the node was never taken away.
    // The runtime says which party bodies the plane holds: the cartridge
    // clears the party rows as a per-character window opens
    // (`Battle_OpenCharComd`, `ps4.asm:2099-2101`: `loc_E4C` clears,
    // `loc_E64` restores the saved enemy rows, `loc_EB6` draws one body)
    // and a body returns as its owner acts.
    for party in &mut self.party_nodes {
        party.node.set_visible(
            view.shown
                .as_ref()
                .is_none_or(|shown| shown.contains(&party.fighter.get())),
        );
    }
    self.restore_party_pose();
    for actor in &view.poses {
        self.set_party_pose(*actor, true);
    }
    for animation in &view.animations {
        self.start_enemy_animation(animation);
    }
    self.draw_fusion(&view.fusion);
    self.view = Some(view);
    self.base_mut().queue_redraw();
}

pub(super) fn texture(
    pack_dir: &str,
    path: &str,
    width: u32,
    height: u32,
) -> Option<Gd<ImageTexture>> {
    let full = format!("{pack_dir}/{path}");
    let image = Image::load_from_file(&GString::from(full.as_str()))?;
    let frame = image.get_region(Rect2i::new(
        Vector2i::ZERO,
        Vector2i::new(width as i32, height as i32),
    ))?;
    ImageTexture::create_from_image(&frame)
}

pub(crate) struct Quad {
    pub(crate) texture: Gd<ImageTexture>,
    pub(crate) dest: Rect2,
    pub(crate) src: Rect2,
}

pub(crate) struct CampChrome {
    tiles: BTreeMap<&'static str, Gd<ImageTexture>>,
    window_words: BTreeMap<(u16, bool, bool), Gd<ImageTexture>>,
    font: Gd<ImageTexture>,
    glyph_at: BTreeMap<char, Vector2>,
}

pub(super) fn frame(&self, rect: CellRect) -> Vec<Quad> {
    let mut quads = Vec::new();
    let push = |quads: &mut Vec<Quad>,
                tiles: &BTreeMap<&'static str, Gd<ImageTexture>>,
                name: &'static str,
                x: i32,
                y: i32| {
        if let Some(texture) = tiles.get(name) {
            quads.push(Quad {
                texture: texture.clone(),
                dest: Rect2::new(
                    Vector2::new((rect.x + x) as f32 * CELL, (rect.y + y) as f32 * CELL),
                    Vector2::new(CELL, CELL),
                ),
                src: Rect2::new(Vector2::ZERO, Vector2::new(CELL, CELL)),
            });
        }
    };
    for y in 1..rect.h - 1 {
        for x in 1..rect.w - 1 {
            push(&mut quads, &self.tiles, "fill", x, y);
        }
    }
    for x in 1..rect.w - 1 {
        push(&mut quads, &self.tiles, "edge_top", x, 0);
        push(&mut quads, &self.tiles, "edge_bottom", x, rect.h - 1);
    }
    for y in 1..rect.h - 1 {
        push(&mut quads, &self.tiles, "edge_left", 0, y);
        push(&mut quads, &self.tiles, "edge_right", rect.w - 1, y);
    }
    push(&mut quads, &self.tiles, "corner_top_left", 0, 0);
    push(&mut quads, &self.tiles, "corner_top_right", rect.w - 1, 0);
    push(&mut quads, &self.tiles, "corner_bottom_left", 0, rect.h - 1);
    push(
        &mut quads,
        &self.tiles,
        "corner_bottom_right",
        rect.w - 1,
        rect.h - 1,
    );
    quads
}

pub(crate) fn recoloured_font(
    &self,
    from: &[[u8; 3]],
    to: &[[u8; 3]],
) -> Option<Gd<ImageTexture>> {
    let mut image = self.font.get_image()?;
    for y in 0..image.get_height() {
        for x in 0..image.get_width() {
            let colour = image.get_pixel(x, y);
            let rgb = [colour.r8(), colour.g8(), colour.b8()];
            // Font art uses indices 1, 2, 14 and 15.
            if let Some(index) = [15, 14, 2, 1].into_iter().find(|&i| from[i] == rgb) {
                let [r, g, b] = to[index];
                image.set_pixel(x, y, Color::from_rgba8(r, g, b, colour.a8()));
            }
        }
    }
    ImageTexture::create_from_image(&image)
}

pub(crate) fn text_in(
    &self,
    font: &Gd<ImageTexture>,
    text: &str,
    cell: (i32, i32),
) -> Vec<Quad> {
    let mut quads = Vec::new();
    for (column, character) in text.chars().enumerate() {
        let dest_cell = (cell.0 + column as i32, cell.1);
        if character == '/' {
            if let Some(quad) = self.window_word(STATUS_SLASH_PATTERN, dest_cell) {
                quads.push(quad);
            }
            continue;
        }
        let dest = Rect2::new(
            Vector2::new(dest_cell.0 as f32 * CELL, dest_cell.1 as f32 * CELL),
            Vector2::new(CELL, CELL),
        );
        if character == ' ' {
            if let Some(quad) = self.window_word(0x680, dest_cell) {
                quads.push(quad);
            }
            continue;
        }
        let Some(source) = self
            .glyph_at
            .get(&character)
            .or_else(|| self.glyph_at.get(&'?'))
        else {
            continue;
        };
        quads.push(Quad {
            texture: font.clone(),
            dest,
            src: Rect2::new(*source, Vector2::new(CELL, CELL)),
        });
    }
    quads
}

fn retail_window_words(strip: &Gd<Image>) -> Option<BTreeMap<(u16, bool, bool), Gd<ImageTexture>>> {
    const PATTERNS: [u16; 10] = [
        0x680,
        0x6E6,
        0x6E7,
        0x6E8,
        0x6E9,
        STATUS_SLASH_PATTERN,
        0x6F8,
        0x6F9,
        0x6FA,
        0x6B4,
    ];
    let mut words = BTreeMap::new();
    for pattern in PATTERNS {
        let index = i32::from(pattern - WINDOW_BASE_TILE);
        for flip_h in [false, true] {
            for flip_v in [false, true] {
                let region = Rect2i::new(Vector2i::new(index * 8, 0), Vector2i::new(8, 8));
                let mut cell = strip.get_region(region)?;
                if flip_h {
                    cell.flip_x();
                }
                if flip_v {
                    cell.flip_y();
                }
                words.insert(
                    (pattern, flip_h, flip_v),
                    ImageTexture::create_from_image(&cell)?,
                );
            }
        }
    }
    Some(words)
}

struct DrawList {
    quads: Vec<Quad>,
    portrait: Option<(Gd<ImageTexture>, Rect2)>,
    /// Each window the page drew, in drawing order: its rectangle and its
