impl CutsceneLayer {
    /// Loads the pack's scene art into the tables this layer draws from.
    pub(crate) fn configure(&mut self, pack_dir: &str, set: &DialogueSet) {
        let assets = SceneAssets::load(pack_dir, set);
        if let Some(screen_y) = assets.opening_screen_y {
            self.opening_screen_y = screen_y;
        }
        self.palettes.extend(assets.palettes);
        self.textures.extend(assets.textures);
        self.temporary_assets.extend(assets.temporary_assets);
        self.opening_background = assets.opening_background;
        if assets.generic_portrait_named {
            self.generic_portrait = assets.generic_portrait;
        }
        if let Some(rect) = assets.generic_window_rect {
            self.generic_window_rect = rect;
        }
        self.window_tiles.extend(assets.window_tiles);

        let mut text = OpeningTextLayer::new_alloc();
        text.bind_mut().configure(pack_dir, set.clone());
        self.base_mut().add_child(&text);
        self.text_layer = Some(text);
    }

    pub(crate) fn place(&mut self) {
        let viewport = self.base().get_viewport_rect();
        let canvas = self.base().get_canvas_transform().affine_inverse();
        let top_left = canvas * viewport.position;
        let bottom_right = canvas * (viewport.position + viewport.size);
        let visible = bottom_right - top_left;
        let position = Vector2::new(
            (top_left.x + (visible.x - SCREEN.x) / 2.0).floor(),
            (top_left.y + (visible.y - SCREEN.y) / 2.0).floor(),
        );
        self.base_mut().set_position(position);
        if let Some(text) = self.text_layer.as_mut() {
            text.bind_mut().place();
        }
    }

    pub(crate) fn tick(&mut self) {
        self.red_flash_frames = self.red_flash_frames.saturating_sub(1);
        self.tick_opening_text();
        if self.red_flash_frames > 0 {
            self.base_mut().queue_redraw();
        }
    }

    pub(crate) fn temporary_asset(
        &self,
        object_id: u16,
        art_tile: u16,
    ) -> Option<TemporarySpriteAsset> {
        self.temporary_assets.get(&(object_id, art_tile)).cloned()
    }
}

pub(super) fn return_to_title_probe(&mut self) -> bool {
    if std::env::var("PSIV_NATIVE_TAPE").as_deref() != Ok("1") {
        return false;
    }
    let Some(session) = self.session.as_mut() else {
        return false;
    };
    if session.title().is_some() {
        return false;
    }
    session.start_title();
    self.take_down_stage_for_title();
    godot_print!("native tape: title restored for a memory probe");
    true
}

fn capture_debug_state(&self) {
    let Ok(path) = std::env::var("PSIV_DEBUG_STATE") else {
        return;
    };
    let at = std::env::var("PSIV_DEBUG_SHOT_FRAME")
        .ok()
        .and_then(|value| value.parse::<u64>().ok())
        .unwrap_or(180);
    if self.anim_tick != at {
        return;
    }
    let Some(runtime) = self.runtime() else {
        return;
    };
    let state = runtime.game().snapshot();
    let report = serde_json::json!({
        "tick": self.anim_tick,
        "map": runtime.map_id().0,
        "cell": [runtime.state().cell().x, runtime.state().cell().y],
        "scene_active": runtime.scene_active(),
        "leader_sheet": self.leader_char,
        "visible_followers": self.follower_nodes.iter().filter(|(node, _, _)| node.is_visible()).count(),
        "characters": state.characters.iter().enumerate().filter_map(|(id, stats)| stats.as_ref().map(|stats| serde_json::json!({
            "id": id, "hp": stats.curr_hp, "tp": stats.curr_tp, "status": stats.status,
            "skill_uses": stats.curr_skill_uses,
        }))).collect::<Vec<_>>(),
        "battle": runtime.battle_roster().map(|roster| roster.iter().map(|fighter| serde_json::json!({
            "id": fighter.id.get(), "name": fighter.name,
            "active": fighter.active,
            "hp": fighter.stats.curr_hp, "tp": fighter.stats.curr_tp,
            "status": fighter.stats.status,
            "attack": fighter.stats.attack.battle, "agility": fighter.stats.agility.battle,
            "dexterity": fighter.stats.dexterity.battle,
            "skills": fighter.stats.skills, "skill_uses": fighter.stats.curr_skill_uses,
            "max_skill_uses": fighter.stats.max_skill_uses,
        })).collect::<Vec<_>>()),
        "money": state.money,
        "inventory": runtime.game().inventory().slots().to_vec(),
        "party": state.party,
        "event_flags": state.event_flags.as_slice(),
        "town_flags": state.town_flags,
    });
    match std::fs::write(&path, format!("{report:#}\n")) {
        Ok(()) => godot_print!("debug: runtime state -> {path}"),
        Err(error) => {
            godot_error!("debug: runtime state failed: {error}");
        }
    }
}

pub(super) fn capture_debug_shot(&mut self) {
