        && let Some(texture) = viewport.get_texture()
        && let Some(image) = texture.get_image()
    {
        let err = image.save_png(&GString::from(path.as_str()));
        godot_print!("debug: screenshot -> {path} ({err:?})");
    }
}

fn debug_open_telepipe_towns(&mut self) {
    use psiv_runtime::{Button, CampPage, Pad};
    let Some(session) = self.session.as_mut() else {
        return;
    };
    for _ in 0..6 {
        if session
            .camp_view()
            .is_some_and(|view| view.page == CampPage::TravelTowns)
        {
            godot_print!("debug: TELEPIPE town list open");
            if crate::boot::debug_camp_telepipe_message() {
                // Tape 36: Down to MILE, Speak.
                for button in [Button::Down, Button::Speak] {
                    session.frame(Pad::new(button));
                    session.frame(Pad::NEUTRAL);
                }
                godot_print!("debug: teleport message open");
                if crate::boot::debug_camp_telepipe_close() {
                    // Tape 36's acknowledgement; the shell's own frame
                    // after this hook is the teardown's first step.
                    session.frame(Pad::new(Button::Speak));
                    godot_print!("debug: teleport message acknowledged");
                }
            }
            return;
        }
        session.frame(Pad::new(Button::Speak));
        session.frame(Pad::NEUTRAL);
    }
    godot_error!("debug: the TELEPIPE town list never opened");
}

