        let mut shader = Shader::new_gd();
        shader.set_code(MAP_PALETTE_SHADER);
        let mut material = ShaderMaterial::new_gd();
        material.set_shader(&shader);
        sprite.set_material(&material);
    } else {
        sprite.set_material(Gd::<Material>::null_arg());
    }
}

