impl Field {
    pub(super) fn poison_flash_visible(&self) -> bool {
        self.status_presentation
            .flash
            .as_ref()
            .is_some_and(|node| node.is_visible())
    }

    pub(super) fn clear_poison_flash(&mut self) {
        if let Some(flash) = self.status_presentation.flash.as_mut() {
            flash.hide();
        }
    }

    pub(super) fn flash_field_poison(&mut self) {
        let mut flash = self.status_presentation.flash.take().unwrap_or_else(|| {
            let mut rect = godot::classes::ColorRect::new_alloc();
            rect.set_color(Color::from_rgb(1.0, 0.0, 0.0));
            rect.set_z_index(1000);
            self.base_mut().add_child(&rect);
            rect
        });
        let viewport = self.base().get_viewport_rect();
        let inverse = self.base().get_canvas_transform().affine_inverse();
        let start = inverse * viewport.position;
        let end = inverse * (viewport.position + viewport.size);
        flash.set_position(start - Vector2::new(4.0, 4.0));
        flash.set_size(end - start + Vector2::new(8.0, 8.0));
        flash.show();
        self.status_presentation.flash = Some(flash);
    }
}

fn ensure_transition_nodes(&mut self) {
    if !self.transition_nodes.is_empty() {
        return;
    }
    for _ in 0..TRANSITION_RECTS {
        let mut node = ColorRect::new_alloc();
        node.set_visible(false);
        node.set_z_index(600);
        self.base_mut().add_child(&node);
        self.transition_nodes.push(node);
    }
}

fn transition_view(&self) -> Option<(Vector2, Vector2)> {
    let camera = self.camera.as_ref()?;
    let viewport = self.base().get_viewport_rect().size;
    let zoom = camera.get_zoom().x.max(0.01);
    let view = viewport / zoom;
    Some((camera.get_position() - view / 2.0, view))
}

pub(crate) fn read_pad(synthetic_speak: bool) -> Pad {
    let input = Input::singleton();
    let mut pad = Pad::NEUTRAL;
    for (action, button) in [
        ("ui_up", Button::Up),
        ("ui_down", Button::Down),
        ("ui_left", Button::Left),
        ("ui_right", Button::Right),
        ("ui_cancel", Button::Cancel),
        ("ui_accept", Button::Speak),
        ("psiv_camp", Button::Camp),
        ("psiv_start", Button::Start),
    ] {
        if input.is_action_pressed(action) {
            pad = pad.with(button);
        }
    }
    if synthetic_speak {
        pad = pad.with(Button::Speak);
    }
    pad
}

pub(crate) fn debug_trace(resolved: psiv_core::Input) {
    use std::sync::Mutex;
    static LAST: Mutex<Option<psiv_core::Input>> = Mutex::new(None);
    if !std::env::var("PSIV_DEBUG_INPUT").is_ok_and(|value| value == "1") {
        return;
    }
    let mut last = LAST.lock().expect("input trace lock");
    if *last != Some(resolved) {
        godot_print!("input: {resolved:?}");
        *last = Some(resolved);
    }
}

impl Field {
    /// The pad the session's frame is driven with: this frame's buttons, plus
    /// the retail-pace debug harness's synthetic Speak press.
    ///
    /// Retail pacing holds a completed page for the oracle tapes' four frames
    /// and then dismisses it; that press is an ordinary Speak press in the pad,
    /// so the runtime's own edge and swallow rules decide it. The dialogue view
    /// is read here either way — for the pace's dismiss hold, and for the
    /// `PSIV_DEBUG_INPUT` page trace, which must see the page *before* the
    /// frame spends the press that dismisses it.
    pub(crate) fn frame_pad(&mut self) -> Pad {
        let dismissable = self.session.as_ref().is_some_and(|session| {
            session
                .runtime()
                .dialogue_view()
                .is_some_and(|view| view.dismissable)
        });
        let synthetic_speak = retail_pace_enabled()
            && dismissable
            && self.retail_dialogue_wait >= RETAIL_DISMISS_HOLD_FRAMES;
        if retail_pace_enabled() && dismissable {
            self.retail_dialogue_wait = self.retail_dialogue_wait.saturating_add(1);
        } else if !dismissable {
            self.retail_dialogue_wait = 0;
        }
        let pad = read_pad(synthetic_speak);
        if std::env::var("PSIV_DEBUG_INPUT").is_ok_and(|value| value == "1")
            && pad
                .pressed(self.dialogue_pad)
                .held(psiv_runtime::Button::Speak)
            && let Some(view) = self
                .session
                .as_ref()
                .and_then(|session| session.runtime().dialogue_view())
            && view.page_end.is_some()
        {
            godot_print!("dialogue page {:?}: {:?}", view.page_end, view.lines);
        }
        self.dialogue_pad = pad;
        if synthetic_speak {
            self.retail_dialogue_wait = 0;
        }
        pad
    }
}

impl Install {
    /// This run's kind, from Godot.
    pub(crate) fn current() -> Self {
        let os = Os::singleton();
        if os.has_feature("template") {
            Install::Installed {
                user_data: PathBuf::from(os.get_user_data_dir().to_string()),
                executable: PathBuf::from(os.get_executable_path().to_string()),
            }
        } else {
            let root = ProjectSettings::singleton()
                .globalize_path("res://..")
                .to_string();
            Install::Checkout {
                root: PathBuf::from(root),
            }
        }
    }

    /// The user data folder of an installed game; `None` for a checkout.
    pub(crate) fn user_data(&self) -> Option<&Path> {
        match self {
            Install::Installed { user_data, .. } => Some(user_data),
            Install::Checkout { .. } => None,
        }
    }

    /// The pack this run reads, before `PSIV_RUNTIME_PACK` is applied.
    fn default_pack(&self) -> PathBuf {
        match self {
            Install::Installed { user_data, .. } => user_data.join(PACK_NAME),
            Install::Checkout { root } => root.join(PACK_NAME),
        }
    }
}

