fn present_title(&mut self, frame: TitleFrame) {
    if self.title.is_none() {
        let pack_dir = self.pack_dir.clone();
        self.title = title::TitleScreen::build(&pack_dir, self.base_mut());
    }
    if let Some(view) = frame.view {
        let camera = self.camera.as_ref().map(|node| node.get_position());
        if let Some(screen) = self.title.as_mut() {
            if let Some(center) = camera {
                screen.reposition(center);
            }
            screen.present(&view);
        }
        let ticks = view.ticks;
        let anim_tick = self.anim_tick;
        title::title_debug_shot(self, anim_tick, ticks);
    }
    if let Some(erased) = frame.erased {
        match erased {
            psiv_runtime::TitleErase::Erased { slot, path } => {
                godot_print!("title: erased save slot {} ({path})", slot + 1);
            }
            psiv_runtime::TitleErase::Failed { slot, error } => {
                godot_error!("title: ERASE DATA slot {} failed: {error}", slot + 1);
            }
        }
    }
    if let Some(failure) = frame.failure {
        match failure {
            psiv_runtime::TitleFailure::NewGame(error) => {
                godot_error!("title: new game failed to build: {error}");
            }
            psiv_runtime::TitleFailure::Continue { slot, error } => {
                godot_error!(
                    "title: CONTINUE slot {} failed validation: {error}",
                    slot + 1
                );
            }
        }
    }
    if let Some(entry) = frame.entered {
        self.finish_title_entry(entry);
    }
}

fn finish_title_entry(&mut self, entry: TitleEntry) {
    // The START/CONTINUE frame belongs to the front door. The next actual
    // Session::frame call is gameplay byte 1, not a shell callback guess.
    self.tape_frames = 0;
    self.tape_last_pad = None;
    self.tape_save_writes = [0; 3];
    match entry {
        TitleEntry::Started { event_started } => {
            godot_print!("title: START — new game, firing Event_GameStart");
            self.load_map_visuals();
            self.sync_visuals(false);
            if event_started {
                self.presentation.reset_scene();
                self.set_letterbox(true);
            } else {
                godot_error!("title: Event_GameStart did not start");
            }
        }
        TitleEntry::Continued { slot } => {
            godot_print!("title: CONTINUE loaded slot {}", slot + 1);
            self.load_map_visuals();
            self.play_map_music();
            self.sync_visuals(false);
        }
    }
    self.start_transition(TransitionKind::GameStart);
    // A later game over builds a new title. Release the old nodes instead
    // of accumulating hidden copies.
    if let Some(screen) = self.title.take() {
        screen.dispose();
    }
}

fn present_game_over(&mut self, game_over: Option<GameOverFrame>) {
    let Some(fade) = game_over else {
        return;
    };
    if fade.frames == 0 {
        self.start_transition(TransitionKind::SceneFadeOut);
        return;
    }
    if !fade.title_restored {
        return;
    }
    self.take_down_stage_for_title();
    self.play_sound(0xFB);
    godot_print!("game over: title restored; saved slots unchanged");
}

fn drive_game_frame(&mut self) {
    let window_open = self
        .session
        .as_ref()
        .is_some_and(|session| session.runtime().dialogue_open());
    let pad = self.frame_pad();
    if !window_open {
        self.retail_dialogue_wait = 0;
    }
    let Some(frame) = self.session_frame(pad, true) else {
        return;
    };
    // A field-status window the session opened this frame: its own retail
    // lines, logged where the shell's notice service logged them.
    if let Some(notice) = &frame.notice {
        godot_print!("field status: {}", notice.lines.join(" "));
    }
    match frame.mode {
        // A battle-mode frame here is the field frame a battle began on;
        // the battle loop's own frames go through `drive_battle_if_active`.
        FrameMode::Field | FrameMode::Battle => self.present_frame(frame),
        FrameMode::Shop | FrameMode::Camp | FrameMode::Destination => {
            self.present_menu_frame(frame);
        }
        // The defeat fade, and the frame its last count hands the title
        // back on: the picture comes down and the front door's nodes go up
        // in the same frame the shell's own game-over driver did it.
        FrameMode::GameOver => {
            self.present_game_over(frame.game_over);
            if let Some(title) = frame.title {
                self.present_title(title);
            }
        }
        // Unreachable while the title owns its frames — the dispatcher
        // drives those above — but the frame still carries the view.
        FrameMode::Title => {
            if let Some(title) = frame.title {
                self.present_title(title);
            }
        }
    }
}

fn set_letterbox(&mut self, on: bool) {
    if on && self.letterbox.is_empty() {
        for _ in 0..LETTERBOX_BARS {
            let mut bar = godot::classes::ColorRect::new_alloc();
            bar.set_color(Color::from_rgb(0.0, 0.0, 0.0));
            bar.set_z_index(500);
            self.base_mut().add_child(&bar);
            self.letterbox.push(bar);
        }
    }
    for bar in &mut self.letterbox {
        bar.set_visible(on);
    }
}

fn place_letterbox(&mut self) {
    if self.letterbox.is_empty() || !self.letterbox[0].is_visible() {
        return;
    }
    let Some(camera) = self.camera.as_ref() else {
        return;
    };
    let viewport = self.base().get_viewport_rect().size;
    let zoom = camera.get_zoom().x.max(0.01);
    let view = viewport / zoom;
    let center = camera.get_position();
    let top_left = center - view / 2.0;
    let frame_top_left =
        center - Vector2::new(BATTLE_FRAME_WIDTH / 2.0, BATTLE_FRAME_HEIGHT / 2.0);
    let frame_bottom_right =
        center + Vector2::new(BATTLE_FRAME_WIDTH / 2.0, BATTLE_FRAME_HEIGHT / 2.0);
    // The camera centre is fractional, so a bar that starts exactly at
    // the view edge can rasterize a sub-pixel short and leak a one-pixel
    // strip of world along the screen border. Overdraw every outward
    // edge by a couple of world pixels; the frame-facing edges stay
    // exact.
    const BLEED: f32 = 2.0;
    let sizes = [
        (
            top_left - Vector2::new(BLEED, BLEED),
            Vector2::new(
                view.x + 2.0 * BLEED,
                (frame_top_left.y - top_left.y).max(0.0) + BLEED,
            ),
        ),
        (
            Vector2::new(top_left.x - BLEED, frame_bottom_right.y),
            Vector2::new(
                view.x + 2.0 * BLEED,
                (top_left.y + view.y - frame_bottom_right.y).max(0.0) + BLEED,
            ),
        ),
        (
            Vector2::new(top_left.x - BLEED, frame_top_left.y),
            Vector2::new(
                (frame_top_left.x - top_left.x).max(0.0) + BLEED,
                BATTLE_FRAME_HEIGHT,
            ),
        ),
        (
            Vector2::new(frame_bottom_right.x, frame_top_left.y),
            Vector2::new(
                (top_left.x + view.x - frame_bottom_right.x).max(0.0) + BLEED,
                BATTLE_FRAME_HEIGHT,
            ),
        ),
    ];
    for (bar, (pos, size)) in self.letterbox.iter_mut().zip(sizes) {
        bar.set_position(pos);
        bar.set_size(size);
    }
}

fn refresh_party_sheets(&mut self) {
    let leader = self
        .runtime()
        .and_then(|runtime| runtime.game().party_slot(0))
        .map(|c| c.0)
        .unwrap_or(0);
    if leader != self.leader_char || self.party_view.is_none() {
        self.leader_char = leader;
        let view = self
            .runtime()
            .and_then(|runtime| runtime.data().party_sheet(leader as usize))
            .and_then(|sheet| SheetView::build(&self.pack_dir, sheet));
        self.party_view = view;
        if self.party_view.is_some() {
            godot_print!("party leader is now sheet {leader}");
        } else {
            godot_error!("party sheet {leader} failed to load");
        }
    }
}

impl CacheReport {
    /// A texture cache's report: one texture per entry.
    pub(crate) fn textures<'a>(
        name: &'static str,
        textures: impl Iterator<Item = &'a Gd<ImageTexture>>,
        ceiling: usize,
    ) -> CacheReport {
        let mut entries = 0;
        let mut bytes = 0u64;
        for texture in textures {
            entries += 1;
            bytes += u64::try_from(texture.get_width()).unwrap_or(0)
                * u64::try_from(texture.get_height()).unwrap_or(0)
                * 4;
        }
        CacheReport {
            name,
            entries,
            textures: entries,
            nodes: 0,
            other_objects: 0,
            bytes,
            ceiling,
        }
    }

    /// A node pool's report: one node per entry, and `other_objects` the
    /// pool also keeps (a material and its shader).
    pub(crate) fn pool(
        name: &'static str,
        entries: usize,
        other_objects: usize,
        ceiling: usize,
    ) -> CacheReport {
        CacheReport {
            name,
            entries,
            textures: 0,
            nodes: entries,
            other_objects,
            bytes: 0,
            ceiling,
        }
    }

    pub(crate) fn to_json(&self) -> serde_json::Value {
        serde_json::json!({
            "entries": self.entries, "textures": self.textures, "nodes": self.nodes,
            "other_objects": self.other_objects, "bytes": self.bytes, "ceiling": self.ceiling,
        })
    }
}

fn label(text: &str, size: i32) -> Gd<Label> {
    let mut label = Label::new_alloc();
    label.set_text(text);
    label.set_autowrap_mode(AutowrapMode::WORD_SMART);
    label.set_horizontal_alignment(HorizontalAlignment::CENTER);
    label.add_theme_font_size_override("font_size", size);
    label
}

fn start(&mut self, rom: PathBuf) {
    let Install::Installed { executable, .. } = &self.install else {
        return;
    };
    if self.build.is_some() {
        return;
    }
    let command = builder_command(executable, Platform::current(), &rom, &self.pack);
    godot_print!(
        "pack setup: building {} from {} with {}",
        self.pack.display(),
        rom.display(),
        command.program.display()
    );
    match Build::start(&command, rom) {
        Ok(build) => {
            self.build = Some(build);
            if let Some(choose) = self.choose.as_mut() {
                choose.set_disabled(true);
            }
        }
        Err(error) => self.show(&format!(
            "The pack builder could not start ({}: {error}).",
            command.program.display()
        )),
    }
}

fn add_picker(&mut self, column: &mut Gd<VBoxContainer>) {
    let mut choose = Button::new_alloc();
    choose.set_text("Choose your ROM file");
    choose.add_theme_font_size_override("font_size", 22);
    choose.set_h_size_flags(godot::classes::control::SizeFlags::SHRINK_CENTER);
    choose
        .signals()
        .pressed()
        .connect_other(&self.to_gd(), Self::on_choose);
    column.add_child(&choose);

    let status = Self::label("", 20);
    column.add_child(&status);

    let mut dialog = FileDialog::new_alloc();
    dialog.set_title("Choose your Phantasy Star IV ROM");
    dialog.set_file_mode(FileMode::OPEN_FILE);
    dialog.set_access(Access::FILESYSTEM);
    dialog.set_use_native_dialog(true);
    dialog
        .add_filter_ex("*.md, *.bin, *.gen, *.smd")
        .description("Genesis ROM image")
        .done();
    dialog
        .signals()
        .file_selected()
        .connect_other(&self.to_gd(), Self::on_file_selected);
    self.base_mut().add_child(&dialog);

    if let Some(window) = self.base().get_window() {
        self.dropped = Some(
            window
                .signals()
                .files_dropped()
                .connect_other(&self.to_gd(), Self::on_files_dropped),
        );
    }
    self.choose = Some(choose);
    self.status = Some(status);
    self.dialog = Some(dialog);
}

fn poll(&mut self) {
    let Some(build) = self.build.as_mut() else {
        return;
    };
    match build.child.try_wait() {
        Ok(None) => {
            let seconds = build.started.elapsed().as_secs();
            let lines = build.lines();
            let text = match progress(&lines) {
                Some((done, total, part)) => {
                    format!("Building {part} ({done} of {total})... {seconds} s")
                }
                None => format!("Building from {}... {seconds} s", build.rom.display()),
            };
            self.show(&text);
        }
        Ok(Some(_)) | Err(_) => {
            let Some(build) = self.build.take() else {
                return;
            };
            let (succeeded, lines) = build.finish();
            for line in &lines {
                godot_print!("pack builder: {line}");
            }
            if succeeded {
                self.show("Built. Starting the game...");
                // The reload removes this screen at once, which calls its
                // `exit_tree` while `poll` still holds `&mut self`; the
                // `base_mut` guard is what lets gdext take that call.
                let base = self.base_mut();
                base.get_tree().reload_current_scene();
            } else {
                self.show(&format!("The build failed:\n{}", failure(&lines)));
                if let Some(choose) = self.choose.as_mut() {
                    choose.set_disabled(false);
                    choose.grab_focus();
                }
            }
        }
    }
}

pub(super) fn start_red_palette(&mut self, delay: u8, restoring: bool) {
    if self.red_palette.node.is_none() {
        let mut shader = Shader::new_gd();
        shader.set_code(SHADER);
        let mut material = ShaderMaterial::new_gd();
        material.set_shader(&shader);
        let mut node = ColorRect::new_alloc();
        node.set_z_index(1100);
        node.set_material(&material);
        self.base_mut().add_child(&node);
        self.red_palette.node = Some(node);
        self.red_palette.material = Some(material);
    }
    self.red_palette.elapsed = 0;
    self.red_palette.stage_frames = u16::from(delay) + 1;
    self.red_palette.restoring = restoring;
    self.sync_red_palette();
}

fn sync_red_palette(&mut self) {
    let viewport = self.base().get_viewport_rect();
    let inverse = self.base().get_canvas_transform().affine_inverse();
    let start = inverse * viewport.position;
    let end = inverse * (viewport.position + viewport.size);
    if let Some(node) = self.red_palette.node.as_mut() {
        node.set_position(start - Vector2::new(4.0, 4.0));
        node.set_size(end - start + Vector2::new(8.0, 8.0));
        node.show();
    }
    if let Some(material) = self.red_palette.material.as_mut() {
        let stage = (1 + self.red_palette.elapsed / self.red_palette.stage_frames).min(8);
        material.set_shader_parameter("stage", &i32::from(stage).to_variant());
        material.set_shader_parameter("restoring", &self.red_palette.restoring.to_variant());
    }
}

pub(super) fn present_dialogue_signals(&mut self, signals: Vec<DialogueSignal>) {
    for signal in signals {
        match signal {
            DialogueSignal::Closed { .. } => {
                if self.runtime().is_some_and(|rt| rt.scene_active()) {
                    godot_print!("scene dialogue closed (t{})", self.anim_tick);
                }
                if matches!(
                    self.runtime().and_then(|rt| rt.scene_dialogue_window()),
                    Some(
                        psiv_core::DialogueWindow::Standard
                            | psiv_core::DialogueWindow::Cutscene
                            | psiv_core::DialogueWindow::Cutscene5
                    )
                ) && let Some(layer) = self.cutscene_layer.as_mut()
                {
                    layer.bind_mut().panel_destroy_all();
                }
            }
            DialogueSignal::ChoiceAnswered(yes) => {
                godot_print!("dialogue choice: {}", if yes { "YES" } else { "NO" });
            }
            DialogueSignal::Action(action) => self.dispatch_dialogue_action(action),
            DialogueSignal::Log(line) => godot_print!("dialogue: {line}"),
            DialogueSignal::Fault(line) => {
                godot_error!("dialogue: {line}");
            }
        }
    }
}

fn dispatch_dialogue_action(&mut self, action: DialogueAction) {
    match action {
        DialogueAction::LoadPanel(id) => {
            if let Some(layer) = self.cutscene_layer.as_mut() {
                layer.bind_mut().panel_create(id);
                layer.bind_mut().dma_planes();
            }
            godot_print!("dialogue action: LoadPanel({id:#05x})");
        }
        DialogueAction::DestroyLastPanel => {
            if let Some(layer) = self.cutscene_layer.as_mut() {
                layer.bind_mut().panel_destroy_last();
                layer.bind_mut().dma_planes();
            }
            godot_print!("dialogue action: DestroyLastPanel");
        }
        DialogueAction::DestroyAllPanels => {
            if let Some(layer) = self.cutscene_layer.as_mut() {
                layer.bind_mut().panel_destroy_all();
                layer.bind_mut().dma_planes();
            }
            godot_print!("dialogue action: DestroyAllPanels");
        }
        DialogueAction::LoadSound(id) => {
            if id != 0 {
                self.play_sound(id);
            }
            godot_print!("dialogue action: LoadSound({id:#04x})");
        }
        DialogueAction::LoadSound2(id) => {
            self.play_sound(id);
            godot_print!("dialogue action: LoadSound2({id:#04x})");
        }
        DialogueAction::UpdatePalette => {
            if let Some(layer) = self.cutscene_layer.as_mut() {
                layer.bind_mut().refresh_palette();
            }
        }
        DialogueAction::ZioEyesRed => {
            self.play_sound(0xCB);
            if let Some(layer) = self.cutscene_layer.as_mut() {
                layer.bind_mut().red_flash(6);
            }
            godot_print!("dialogue action: ZioEyesRed");
        }
        DialogueAction::PauseMusic => {
            if let Some(audio) = self.audio.as_mut() {
                audio.pause_music();
            }
            godot_print!("dialogue action: PauseMusic");
        }
        DialogueAction::ResumeMusic => {
            if let Some(audio) = self.audio.as_mut() {
                audio.resume_music();
            }
            godot_print!("dialogue action: ResumeMusic");
        }
        DialogueAction::SabotageAlarmRedPalette => {
            self.play_sound(0xDB);
            if let Some(layer) = self.cutscene_layer.as_mut() {
                layer.bind_mut().red_flash(18);
            }
            godot_print!("dialogue action: SabotageAlarmRedPalette");
        }
        DialogueAction::SetEventFlag(flag) => {
            // The runtime already wrote the live flag bank when it
            // released the action, so this is the log line only.
            godot_print!("dialogue action: SetEventFlag({flag:#04x})");
        }
        DialogueAction::ElsydeonBroken => {
            if let Some(layer) = self.cutscene_layer.as_mut() {
                layer.bind_mut().red_flash(12);
            }
            godot_print!("dialogue action: ElsydeonBroken");
        }
    }
}

pub(super) fn present_routed(&mut self, routed: &[Routed]) {
    for item in routed {
        match *item {
            Routed::Talk {
                npc_index,
                cell,
                outcome,
            } => match outcome {
                NpcDialogueOpen::Opened => {
                    let toward = self.runtime().map(|rt| rt.state().facing().opposite());
                    if let Some(toward) = toward {
                        let name = sequence_name("idle", toward);
                        for entry in &mut self.npc_nodes {
                            if entry.index == npc_index {
                                entry.idle = name.clone();
                            }
                        }
                    }
                }
                NpcDialogueOpen::NoBinding => {
                    godot_print!("talk: npc {npc_index} at {cell:?} has no dialogue binding");
                }
                NpcDialogueOpen::Nothing => {}
            },
            Routed::CounterWithoutShop { cell } => {
                godot_print!("counter reach at {cell:?} has no shop row; dialogue");
            }
            Routed::ShopOpened { .. } | Routed::NothingHere => {}
            Routed::DestinationMenu => godot_print!("scene opened the destination menu"),
            Routed::SceneChoice => godot_print!("scene awaits a dialogue choice"),
            Routed::SceneDialogue { entry, outcome } => {
                godot_print!("scene dialogue open: entry {entry:#04x}");
                if retail_pace_enabled() {
                    if !self.retail_pace_logged {
                        godot_print!(
                            "debug: retail-paced scene dialogue enabled (3f/char, dismiss hold {RETAIL_DISMISS_HOLD_FRAMES}f)"
                        );
                        self.retail_pace_logged = true;
                    }
                    self.retail_dialogue_wait = 0;
                }
                if outcome == SceneDialogueOpen::UnknownTree {
                    godot_error!("scene dialogue tree is absent from the loaded pack");
                }
            }
            Routed::SceneDialogueSkipped { entry } => {
                godot_print!("scene dialogue open: entry {entry:#04x}");
                godot_print!("debug: auto-closing scene dialogue entry {entry}");
            }
            Routed::SceneDialogueResume { .. } => {
                godot_print!("scene dialogue resume (t{})", self.anim_tick);
                self.retail_dialogue_wait = 0;
            }
            Routed::SceneSystemLine { line, opened } => {
                godot_print!("scene system line {line:?}: opened {opened}");
            }
            Routed::SceneDialogueResumeSkipped => {
                godot_print!("scene dialogue resume (t{})", self.anim_tick);
            }
        }
    }
}

pub(super) fn present_frame(&mut self, frame: Frame) {
    // `PSIV_DEBUG_INPUT=1` keeps its hook: the input the session gave the
    // field this frame. A window's frame has none — the field was starved.
    if let Some(input) = frame.field_input {
        debug_trace(input);
    }
    self.present_dialogue_signals(frame.signals);

    // A `$F6` the dialogue fired becomes a running scene. The high-bit
    // events are panel cutscenes and get a scene transition.
    if let Some(start) = frame.scene_started {
        if start.started {
            godot_print!("dialogue event {:#x} starts its scene", start.event);
            self.set_letterbox(true);
            if start.event & 0x8000 != 0 {
                self.start_transition(TransitionKind::SceneStart);
            }
        } else {
            godot_error!(
                "dialogue fired event {:#x} with no transcribed scene",
                start.event
            );
        }
    }

    self.present_routed(&frame.routed);
    let stepped = self.process_events(frame.events);
    self.present_shop();
    self.present_destination();
    self.present_job_board();

    // A battle this frame's events started: the runtime has already begun
    // it, so the shell builds the art, shows the stage and — for an
    // encounter — runs the battle transition its entry always ran.
    if let Some(battle) = frame.battle {
        let encounter = matches!(
            battle.started,
            Some(psiv_runtime::BattleStart::Encounter(_))
        );
        self.present_battle_frame(battle);
        if encounter {
            self.start_transition(TransitionKind::BattleEntry);
        }
    }

    // The window's own half of the frame ran last in the session, after the
    // events that open the window: the box took its first open-animation
    // step on the frame it opened.
    self.present_dialogue_signals(frame.window_signals);
    self.sync_dialogue_view();

    // A landing tick with the key still held is mid-stride, not rest:
    // without this, the idle frame flashes for one tick every step (the
    // cartridge's animation free-runs and never sees such a gap). A frame
    // the window owned has no field input, and drew no walk.
    let walking = match frame.field_input {
        None => false,
        Some(input) => {
            self.runtime().is_some_and(|rt| rt.state().is_stepping())
                || (stepped && input.direction().is_some())
        }
    };
    if !self.battle_presentation_active() {
        self.sync_visuals(walking);
    }
}

