pub(crate) fn apply(&self, sprite: &mut Gd<Sprite2D>, frame: i32) {
    sprite.set_texture(&self.texture);
    // Drawn above the node origin so the origin is the feet line and
    // y-sort orders characters the way the hardware did.
    sprite.set_offset(Vector2::new(0.0, -(self.frame_height as f32)));
    sprite.set_region_enabled(true);
    sprite.set_region_rect(Rect2::new(
        Vector2::new((frame * self.frame_width) as f32, 0.0),
        Vector2::new(self.frame_width as f32, self.frame_height as f32),
    ));
}

#[godot_api]
impl ISprite2D for Player {
    fn init(base: Base<Sprite2D>) -> Self {
        godot_print!("Hello, world!"); // Prints to the Godot console

        Self {
            speed: 400.0,
            angular_speed: std::f64::consts::PI,
            base,
        }
    }

    fn physics_process(&mut self, delta: f64) {
        // GDScript code:
        //
        // rotation += angular_speed * delta
        // var velocity = Vector2.UP.rotated(rotation) * speed
        // position += velocity * delta

        let radians = (self.angular_speed * delta) as f32;
        self.base_mut().rotate(radians);

        let rotation = self.base().get_rotation();
        let velocity = Vector2::UP.rotated(rotation) * self.speed as f32;
        self.base_mut().translate(velocity * delta as f32);

        // or verbose:
        // let this = self.base_mut();
        // this.set_position(
        //     this.position() + velocity * delta as f32
        // );
    }
}

#[derive(GodotClass)]
#[class(base=RefCounted)]
pub struct GdPAIBlackboard {
    /// All named properties, including the raw `GDPAI_OBJECTS` array if one was set.
    pub properties: HashMap<String, Variant>,
    /// Planning snapshots of the world objects, keyed by uid (instance id as a string).
    /// Rebuilt whenever `GDPAI_OBJECTS` is set; copied on `clone_for_simulation`.
    pub objects: HashMap<String, Gd<SimObjectProxy>>,
    /// Live nodes behind `objects`. Empty on simulation blackboards, so planning code cannot
    /// reach live nodes.
    pub source_objects: HashMap<String, Gd<Node>>,
    /// Property keys mutated since the board was built. Populated only through the marking
    /// mutators below, so [`crate::snapshot::BlackboardSnapshot::patch_from`] can re-encode
    /// just these keys. Never read from GDScript.
    pub(crate) dirty_props: HashSet<String>,
    /// Object uids whose proxy — or whose presence in [`Self::objects`] — changed since the
    /// board was built. Same consumer as [`Self::dirty_props`]. Never read from GDScript.
    pub(crate) dirty_objects: HashSet<String>,
    base: Base<RefCounted>,
}

#[cfg(not(test))]
pub fn process_logs() {
    if let Some((_, rx)) = LOG_CHANNEL.get() {
        loop {
            let log_msg = {
                let Ok(receiver) = rx.lock() else {
                    // Mutex poisoned, stop processing
                    break;
                };
                receiver.try_recv()
            };
            match log_msg {
                Ok(log_msg) => {
                    let timestamp = log_msg.timestamp as f64 / 1000.0;
                    match log_msg.level {
                        LogLevel::Error => {
                            godot::prelude::godot_error!(
                                "[GdPAI {:.3}s] {}",
                                timestamp,
                                log_msg.message
                            );
                        }
                        LogLevel::Warn => {
                            godot::prelude::godot_warn!(
                                "[GdPAI {:.3}s] {}",
                                timestamp,
                                log_msg.message
                            );
                        }
                        LogLevel::Info => {
                            godot::prelude::godot_print!(
                                "[GdPAI {:.3}s] {}",
                                timestamp,
                                log_msg.message
                            );
                        }
                        LogLevel::Debug => {
                            godot::prelude::godot_print!(
                                "[GdPAI {:.3}s | debug] {}",
                                timestamp,
                                log_msg.message
                            );
                        }
                    }
                }
                Err(TryRecvError::Empty) => break,
                Err(TryRecvError::Disconnected) => break,
            }
        }
    }
}

pub fn evaluate(
    &self,
    agent_state: &Gd<GdPAIBlackboard>,
    world_state: &Gd<GdPAIBlackboard>,
) -> bool {
    if self.operation == PreconditionOp::CustomCallback {
        if let Some(callable) = &self.eval_callable {
            let result = callable.call(&[agent_state.to_variant(), world_state.to_variant()]);
            return result.try_to::<bool>().unwrap_or(false);
        }
        log_warn!(
            "CustomCallback precondition on '{}' has no callable; evaluating as false",
            self.property_name
        );
        return false;
    }

    match self.target {
        PreconditionTarget::Agent => {
            let source = agent_state;
            Self::evaluate_on_blackboard(
                source,
                &self.operation,
                &self.property_name,
                &self.value,
            )
        }
        PreconditionTarget::WorldState => {
            let source = world_state;
            Self::evaluate_on_blackboard(
                source,
                &self.operation,
                &self.property_name,
                &self.value,
            )
        }
        PreconditionTarget::WorldObjectProxy {
            ref group,
            ref property,
        } => {
            // Iterate all objects in the world state that belong to the specified group
            let world_bind = world_state.bind();
            let objects = world_bind.get_proxies_in_group(GString::from(group.as_str()));
            for obj in objects.iter_shared() {
                let prop = obj.bind().get_property(GString::from(property.as_str()));
                if !prop.is_nil() {
                    let val = match &self.value {
                        Some(v) => v.to_variant(),
                        None => Variant::nil(),
                    };
                    // Compare prop with val based on operation
                    if Self::compare_variants(&prop, &val, &self.operation) {
                        return true;
                    }
                }
            }
            false
        }
    }
}

fn evaluate_on_blackboard(
    source: &Gd<GdPAIBlackboard>,
    op: &PreconditionOp,
    property_name: &str,
    value: &Option<Variant>,
) -> bool {
    let bind = source.bind();
    let prop = bind.get_property(GString::from(property_name));
    if prop.is_nil() {
        return false;
    }

    let compare_val = match value {
        Some(v) => v,
        None => return false,
    };

    match op {
        PreconditionOp::HasProperty => !prop.is_nil(),
        PreconditionOp::Equal => {
            if prop == *compare_val {
                return true;
            }
            // Numeric comparison with epsilon
            if let (Ok(p), Ok(v)) = (prop.try_to::<f64>(), compare_val.try_to::<f64>()) {
                return (p - v).abs() < f64::EPSILON;
            }
            false
        }
        PreconditionOp::NotEqual => !Self::compare_variants_equal(&prop, compare_val),
        PreconditionOp::GreaterThan => {
            if let (Ok(p), Ok(v)) = (prop.try_to::<f64>(), compare_val.try_to::<f64>()) {
                return p > v;
            }
            false
        }
        PreconditionOp::GreaterThanOrEqual => {
            if let (Ok(p), Ok(v)) = (prop.try_to::<f64>(), compare_val.try_to::<f64>()) {
                return p >= v;
            }
            false
        }
        PreconditionOp::LessThan => {
            if let (Ok(p), Ok(v)) = (prop.try_to::<f64>(), compare_val.try_to::<f64>()) {
                return p < v;
            }
            false
        }
        PreconditionOp::LessThanOrEqual => {
            if let (Ok(p), Ok(v)) = (prop.try_to::<f64>(), compare_val.try_to::<f64>()) {
                return p <= v;
            }
            false
        }
        PreconditionOp::CustomCallback => false,
    }
}

struct ActiveJobHandle {
    /// The agent object that receives `_on_plan_ready`. Held as a `Gd` and checked with
    /// `is_instance_valid` before use, since the agent may be freed mid-plan.
    agent: Gd<Object>,
    /// Instance id of `agent`, used to find and cancel an agent's earlier jobs.
    agent_instance_id: i64,
    /// Every `Callable` of this job; the planner refers to them by index. Only touched on the
    /// main thread because `Callable` is not `Send`.
    callable_registry: Vec<Callable>,
    /// Requests from the planner thread for GDScript callables to be run.
    request_rx: Receiver<CallbackRequest>,
    /// Engines coming back from worker threads, with the result of the step they just ran.
    result_rx: Receiver<(PlannerRunResult, PlannerEngine)>,
    /// Cloned into each worker step so it can hand the engine back.
    result_tx: Sender<(PlannerRunResult, PlannerEngine)>,
    /// The engine while it is parked between steps; `None` while a worker owns it.
    engine: Option<PlannerEngine>,
    /// Goals still to be searched (satisfied ones removed, sorted by reward, highest first).
    goals: Vec<GoalSpec>,
    /// If all goals were already satisfied by the initial state, this is the
    /// original index of the highest-reward satisfied goal; otherwise -1.
    satisfied_goal_index: i64,
    /// Shared with the engine; set to abort the job.
    cancel_flag: Arc<AtomicBool>,
    /// What the last finished step is waiting for: a request id, or 0 when it only yielded its
    /// budget and can be resumed immediately.
    pending_request_id: usize,
    /// The job will not run again (result delivered, failed, or cancelled).
    done: bool,
    /// The job was already `done` a frame ago and may now be dropped. The extra frame gives
    /// GDScript a chance to read the engine's debug tree right after the result arrives.
    pending_reap: bool,
    /// Requests answered since the last resume, so an answer arriving after the engine drained
    /// its channel still triggers a resume.
    completed_request_ids: HashSet<usize>,
    /// Limits the "not resuming" debug notice to once per stalled request.
    stall_notice: StallNoticeThrottle,
}

#[derive(GodotClass)]
#[class(base=Node)]
pub struct GdPAIPlanScheduler {
    /// Maximum Rayon worker threads. 0 = number of logical CPUs. Read once when the node
