    if let Some(space) = physics_spaces.get_mut(&space_rid) {
        for monitor_info in detected_bodies.values() {
            if let Some(body) = physics_collision_objects
                .get_mut(&get_id_rid(monitor_info.other_collider_id, physics_ids))
                && let Some(body) = body.get_mut_body()
            {
                body.remove_area(*area_id, space);
            }
        }
        // No need to update anymore if it was scheduled before
        space
            .get_mut_state()
            .area_remove_from_area_update_list(*area_id);
    }
}

pub fn reset_space_override(
    area_id: &RapierId,
    physics_spaces: &mut PhysicsSpaces,
    physics_collision_objects: &mut PhysicsCollisionObjects,
    physics_ids: &PhysicsIds,
) {
    let area_rid = get_id_rid(*area_id, physics_ids);
    let mut detected_bodies = BTreeMap::default();
    let mut space_rid: Rid = Rid::Invalid;
    if let Some(area_rid) = physics_collision_objects.get(&area_rid)
        && let Some(area) = area_rid.get_area()
    {
        detected_bodies = area.state.monitored_objects.clone();
        space_rid = area.get_base().get_space(physics_ids);
    }
    if let Some(space) = physics_spaces.get_mut(&space_rid) {
        for (_, monitor_info) in detected_bodies {
            if let [Some(body), Some(area)] = physics_collision_objects.get_disjoint_mut([
                &get_id_rid(monitor_info.other_collider_id, physics_ids),
                &area_rid,
            ]) && let Some(body) = body.get_mut_body()
                && let Some(area) = area.get_mut_area()
            {
                body.remove_area(*area_id, space);
                body.add_area(area, space);
            }
        }
        space
            .get_mut_state()
            .area_remove_from_area_update_list(*area_id);
    }
}

#[allow(clippy::too_many_arguments)]
pub fn receive_event(
    &mut self,
    event_state: i32,
    event_removed: bool,
    other_collider_type: CollisionObjectType,
    other_collider_handle: ColliderHandle,
    other_collider: &mut Option<&mut RapierCollisionObject>,
    other_collider_shape: usize,
    other_collider_id: RapierId,
    other_collider_instance_id: u64,
    this_collider_handle: ColliderHandle,
    this_shape: usize,
    space: &mut RapierSpace,
) {
    // The filters below decide whether a *new* overlap may be reported. One that is already
    // monitored still has to receive its exit event after the filters stop matching, or its
    // monitor would never be cleared.
    let monitor_key = OrderedMonitorKey::new(RapierAreaState::monitor_key(
        this_collider_handle,
        other_collider_handle,
    ));
    if !self.state.monitored_objects.contains_key(&monitor_key)
        && let Some(other_collider) = other_collider
    {
        // Godot only lets an area detect what its own mask covers, whereas the colliders'
        // interaction groups are matched with `Or` so that a pair reaches both sides. The
        // direction each area cares about is therefore resolved here rather than in rapier.
        if self.base.get_collision_mask() & other_collider.get_base().get_collision_layer() == 0
        {
            return;
        }
        // If the other object is an area:
        if let Some(other_area) = other_collider.get_area()
            && (self.area_monitor_callback.is_none() || !other_area.is_monitorable())
        {
            return;
        }
    }
    let event_report = EventReport {
        id: other_collider_id,
        collision_object_type: other_collider_type,
        state: event_state,
        instance_id: other_collider_instance_id,
        object_shape_index: other_collider_shape as u32,
        this_area_shape_index: this_shape as u32,
    };
    // Process the event, creating or destroying a monitor as necessary.
    if let Some(processed_event) = self.process_new_event(
        space,
        this_collider_handle,
        other_collider_handle,
        &event_report,
        event_removed,
    ) {
        // If the other object is a body, we may have to register or unregister this area from the body:
        if let Some(other_collider) = other_collider
            && let Some(other_body) = other_collider.get_mut_body()
        {
            if processed_event.num_contacts == 1 && event_state == 1 {
                // If we're adding this contact anew, register the area in the body:
                other_body.add_area(self, space);
            } else if processed_event.num_contacts == 0 {
                // Else, if our monitor has no more contacts:
                other_body.remove_area(self.base.get_id(), space);
            }
        }
        if processed_event.should_report {
            let monitor_key =
                RapierAreaState::monitor_key(this_collider_handle, other_collider_handle);
            self.enqueue_unhandled_event(space, monitor_key, event_report);
        }
    }
}

pub fn update_area_override(
    physics_collision_objects: &mut PhysicsCollisionObjects,
    physics_spaces: &mut PhysicsSpaces,
    physics_engine: &mut PhysicsEngine,
    area_id: &RapierId,
    physics_ids: &PhysicsIds,
) {
    let mut monitored_bodies = BTreeMap::default();
    let mut space_rid = Rid::Invalid;
    let area_rid = get_id_rid(*area_id, physics_ids);
    if let Some(area_rid) = physics_collision_objects.get(&area_rid)
        && let Some(area) = area_rid.get_area()
    {
        monitored_bodies = area.state.monitored_objects.clone();
        space_rid = area.get_base().get_space(physics_ids);
    }
    if let Some(space) = physics_spaces.get_mut(&space_rid) {
        space
            .get_mut_state()
            .area_remove_from_area_update_list(*area_id);
    }
    for monitor_info in monitored_bodies.values() {
        RapierBody::apply_area_override_to_body(
            &monitor_info.other_collider_id,
            physics_engine,
            physics_spaces,
            physics_collision_objects,
            physics_ids,
        )
    }
}

pub fn call_queries(
    unhandled_events: &BTreeMap<OrderedMonitorKey, EventReport>,
    monitor_callback: Option<Callable>,
    area_monitor_callback: Option<Callable>,
    physics_ids: &PhysicsIds,
) {
    let physics_data = physics_data();
    for monitor_report in unhandled_events.values() {
        if monitor_report.state == 0 {
            godot_error!("Invalid monitor state");
            continue;
        }
        let rid = get_id_rid(monitor_report.id, physics_ids);
        // Resolve the RapierId stored in instance_id to the real Godot instance_id
        let godot_instance_id: i64 = if let Some(obj_rid) =
            physics_data.ids.get(&monitor_report.instance_id)
            && let Some(obj) = physics_data.collision_objects.get(obj_rid)
        {
            obj.get_base().get_instance_id() as i64
        } else {
            0
        };
        let arg_array = if monitor_report.state > 0 {
            vec![
                AreaBodyStatus::ADDED.to_variant(),
                rid.to_variant(),
                godot_instance_id.to_variant(),
                monitor_report.object_shape_index.to_variant(),
                monitor_report.this_area_shape_index.to_variant(),
            ]
        } else {
            vec![
                AreaBodyStatus::REMOVED.to_variant(),
                rid.to_variant(),
                godot_instance_id.to_variant(),
                monitor_report.object_shape_index.to_variant(),
                monitor_report.this_area_shape_index.to_variant(),
            ]
        };
        if monitor_report.collision_object_type == CollisionObjectType::Body {
            if let Some(ref monitor_callback) = monitor_callback {
                monitor_callback.call(arg_array.as_slice());
            }
        } else if let Some(ref area_monitor_callback) = area_monitor_callback {
            area_monitor_callback.call(arg_array.as_slice());
        }
    }
}

fn init_collider(
    &self,
    collider_handle: ColliderHandle,
    space_handle: WorldHandle,
    physics_engine: &mut PhysicsEngine,
) {
    // Send contact infos for dynamic bodies, or for static bodies with static linear velocity
    let is_with_static_linear_velocity = self.get_static_linear_velocity() != Vector::default();
    if self.base.mode.ord() >= BodyMode::KINEMATIC.ord() || is_with_static_linear_velocity {
        let mut send_contacts = self.can_report_contacts();
        if self.base.is_debugging_contacts && godot::classes::Os::singleton().is_debug_build() {
            send_contacts = true;
        }
        if is_with_static_linear_velocity {
            send_contacts = true;
        }
        physics_engine.collider_set_contact_force_events(
            space_handle,
            collider_handle,
            send_contacts,
            self.contact_force_threshold,
        );
    }
    self.update_collider_filters(collider_handle, space_handle, physics_engine);
}

fn update_colliders_contact_events(&self, physics_engine: &mut PhysicsEngine) {
    let is_with_static_linear_velocity = self.get_static_linear_velocity() != Vector::default();
    if self.base.mode.ord() < BodyMode::KINEMATIC.ord() && !is_with_static_linear_velocity {
        return;
    }
    let colliders = physics_engine
        .body_get_colliders(self.base.get_space_id(), self.base.get_body_handle())
        .to_vec();
    let mut send_contacts = self.can_report_contacts();
    if self.base.is_debugging_contacts && godot::classes::Os::singleton().is_debug_build() {
        send_contacts = true;
    }
    if is_with_static_linear_velocity {
        send_contacts = true;
    }
    for collider in colliders {
        physics_engine.collider_set_contact_force_events(
            self.base.get_space_id(),
            collider,
            send_contacts,
            self.contact_force_threshold,
        );
    }
}

pub fn create_direct_state(&mut self) {
    if self.direct_state.is_some() {
        return;
    }
    self.direct_state = None;
    self.direct_state_array.clear();
    self.direct_state_variant = Variant::nil();
    let mut direct_space_state = RapierDirectBodyState::new_alloc();
    {
        let mut direct_state = direct_space_state.bind_mut();
        direct_state.set_body(self.base.get_rid());
    }
    if direct_space_state.is_instance_valid() {
        let direct_state = direct_space_state.to_variant();
        self.direct_state_array.push(&direct_state);
        self.direct_state_variant = direct_state.clone();
        self.direct_state = Some(direct_space_state.upcast());
    }
}

pub fn add_area(&mut self, p_area: &RapierArea, space: &mut RapierSpace) {
    if p_area.has_any_space_override() {
        self.state
            .add_area_ref(p_area.get_base().get_id(), p_area.get_priority());
        self.on_area_updated(space);
    }
}

pub fn get_aabb(&self, physics_shapes: &PhysicsShapes, physics_ids: &PhysicsIds) -> Rect {
    let mut body_aabb: Option<Rect> = None;
    for i in 0..self.base.get_shape_count() as usize {
        if self.base.is_shape_disabled(i) {
            continue;
        }
        if let Some(shape) = physics_shapes.get(&self.base.get_shape(physics_ids, i)) {
            let shape_aabb =
                self.base.get_shape_transform(i) * shape.get_base().get_aabb(Vector::default());
            body_aabb = Some(body_aabb.map_or(shape_aabb, |aabb| aabb.merge(shape_aabb)));
        }
    }
    body_aabb.unwrap_or_default()
}

pub fn new(id: RapierId, rid: Rid, collision_object_type: CollisionObjectType) -> Self {
    let mut mode = BodyMode::RIGID;
    if collision_object_type == CollisionObjectType::Area {
        mode = BodyMode::STATIC;
    }
    let project_settings = ProjectSettings::singleton();
    let activation_angular_threshold = project_settings
        .get_setting_with_override(SLEEP_THRESHOLD_ANGULAR)
        .try_to()
        .unwrap_or_default();
    let length_unit = RapierProjectSettings::get_length_unit();
    let mut activation_linear_threshold = project_settings
        .get_setting_with_override(SLEEP_THRESHOLD_LINEAR)
        .try_to()
        .unwrap_or_default();
    activation_linear_threshold /= length_unit;
    let activation_time_until_sleep = project_settings
        .get_setting_with_override(TIME_BEFORE_SLEEP)
        .try_to()
        .unwrap_or_default();
    Self {
        #[cfg(feature = "dim3")]
        user_flags: 0,
        collision_object_type,
        rid,
        state: RapierCollisionObjectBaseState {
            id,
            body_handle: RigidBodyHandle::invalid(),
            space_id: RapierId::default(),
            shapes: Vec::new(),
            transform: Transform::IDENTITY,
            inv_transform: Transform::IDENTITY,
        },
        instance_id: 0,
        canvas_instance_id: 0,
        pickable: true,
        collision_mask: 1,
        collision_layer: 1,
        dominance: 0,
        is_debugging_contacts: false,
        mode,
        massless: false,
        activation_angular_threshold,
        activation_linear_threshold,
        activation_time_until_sleep,
        compound_anchor: None,
        compound_members: Vec::new(),
        compound_part_shapes: Vec::new(),
    }
}

pub(super) fn recreate_shapes(
    collision_object: &mut dyn IRapierCollisionObject,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_ids: &PhysicsIds,
) {
    {
        if collision_object.get_base().is_compound() {
            // Holding the same shapes after the edit: swap the shape in place so the collider,
            // and every contact pair referencing it, survives.
            if collision_object
                .get_base()
                .compound_is_current(physics_engine)
            {
                collision_object
                    .get_mut_base()
                    .update_compound_collider(physics_engine);
                return;
            }
            // Falling back to one collider per shape: tear the compound down completely
            // first, a compound and per-shape colliders must never coexist on one object.
            collision_object.get_mut_base().destroy_shapes(
                physics_engine,
                physics_spaces,
                physics_ids,
            );
            collision_object.get_mut_base().clear_compound();
        }
        if collision_object
            .get_base()
            .wants_compound_collider(physics_engine)
        {
            let built = Self::recreate_as_compound(
                collision_object,
                physics_engine,
                physics_spaces,
                physics_ids,
            );
            if built {
                return;
            }
            // Refused once the shapes were already torn down. Fall through and give each its
            // own collider, rather than leave the object with none.
        }
    }
    for i in 0..collision_object.get_base().get_shape_count() as usize {
        if collision_object.get_base().state.shapes[i].disabled {
            continue;
        }
        if collision_object.get_base().state.shapes[i].collider_handle
            != ColliderHandle::invalid()
        {
            collision_object.get_mut_base().state.shapes[i].collider_handle =
                collision_object.get_base().destroy_shape(
                    collision_object.get_base().state.shapes[i],
                    i,
                    physics_spaces,
                    physics_engine,
                    physics_ids,
                );
        }
        collision_object.get_mut_base().state.shapes[i].collider_handle = collision_object
            .create_shape(
                collision_object.get_base().state.shapes[i],
                i,
                physics_engine,
            );
        let shape = collision_object.get_base().state.shapes[i];
        collision_object
            .get_mut_base()
            .update_shape_transform(i, shape, physics_engine);
    }
}

fn recreate_as_compound(
    collision_object: &mut dyn IRapierCollisionObject,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_ids: &PhysicsIds,
) -> bool {
    for i in 0..collision_object.get_base().get_shape_count() as usize {
        let shape = collision_object.get_base().state.shapes[i];
        if shape.collider_handle != ColliderHandle::invalid() {
            collision_object.get_mut_base().state.shapes[i].collider_handle = collision_object
                .get_base()
                .destroy_shape(shape, i, physics_spaces, physics_engine, physics_ids);
        }
    }

    let material = collision_object.init_material();
    let handle = collision_object
        .get_mut_base()
        .create_compound_collider(material, physics_engine);
    if handle == ColliderHandle::invalid() {
        collision_object.get_mut_base().clear_compound();
        return false;
    }

    let anchor = collision_object.get_base().compound_anchor_index();
    if let Some(anchor) = anchor {
        collision_object.get_mut_base().state.shapes[anchor].collider_handle = handle;
    }

    // Everything the compound did not take keeps a collider of its own, so one shape that
    // cannot be a part no longer costs the rest their place in the compound.
    for i in 0..collision_object.get_base().get_shape_count() as usize {
        let shape = collision_object.get_base().state.shapes[i];
        if shape.disabled || collision_object.get_base().is_compound_member(i) {
            continue;
        }
        let own = collision_object.create_shape(shape, i, physics_engine);
        collision_object.get_mut_base().state.shapes[i].collider_handle = own;
        collision_object
            .get_mut_base()
            .update_shape_transform(i, shape, physics_engine);
    }
    true
}

#[allow(clippy::too_many_arguments)]
#[allow(clippy::too_many_arguments)]
pub(super) fn add_shape(
    collision_object: &mut dyn IRapierCollisionObject,
    p_shape_id: RapierId,
    p_transform: Transform,
    p_disabled: bool,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_shapes: &mut PhysicsShapes,
    physics_ids: &PhysicsIds,
) {
    let shape = CollisionObjectShape {
        xform: p_transform,
        id: p_shape_id,
        disabled: p_disabled,
        one_way_collision: false,
        one_way_collision_margin: 0.0,
        #[cfg(feature = "dim2")]
        one_way_collision_direction: Vector::new(0.0, 1.0),
        collider_handle: ColliderHandle::invalid(),
    };
    collision_object.get_mut_base().state.shapes.push(shape);
    if let Some(shape) = physics_shapes.get_mut(&get_id_rid(p_shape_id, physics_ids)) {
        shape
            .get_mut_base()
            .add_owner(collision_object.get_base().get_id());
    }
    // The shape that tips the object past one is what turns it into a compound, and from then
    // on every further shape the compound can speak for joins it rather than getting a collider
    // of its own -- both of which mean rebuilding it around the new membership.
    if !collision_object
        .get_base()
        .compound_is_current(physics_engine)
    {
        Self::recreate_shapes(
            collision_object,
            physics_engine,
            physics_spaces,
            physics_ids,
        );
    } else if !p_disabled {
        let index = collision_object.get_base().state.shapes.len() - 1;
        let handle = collision_object.create_shape(shape, index, physics_engine);
        collision_object.get_mut_base().state.shapes[index].collider_handle = handle;
        let shape = collision_object.get_base().state.shapes[index];
        collision_object
            .get_mut_base()
            .update_shape_transform(index, shape, physics_engine);
    }
    if collision_object.get_base().is_space_valid() {
        collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
    }
}

pub(super) fn shape_changed(
    collision_object: &mut dyn IRapierCollisionObject,
    shape_id: RapierId,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_ids: &PhysicsIds,
) {
    if collision_object.get_base().is_compound() {
        // The compound baked this shape's geometry, so any of its parts changing means a
        // rebuild.
        Self::recreate_shapes(
            collision_object,
            physics_engine,
            physics_spaces,
            physics_ids,
        );
        collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
        return;
    }
    for i in 0..collision_object.get_base().state.shapes.len() {
        let shape = collision_object.get_base().state.shapes[i];
        if shape.id != shape_id || shape.disabled {
            continue;
        }
        if collision_object.get_base().state.shapes[i].collider_handle
            != ColliderHandle::invalid()
        {
            collision_object.get_mut_base().state.shapes[i].collider_handle = collision_object
                .get_base()
                .destroy_shape(shape, i, physics_spaces, physics_engine, physics_ids);
        }
        collision_object.get_mut_base().state.shapes[i].collider_handle = collision_object
            .create_shape(
                collision_object.get_base().state.shapes[i],
                i,
                physics_engine,
            );
        let shape = collision_object.get_base().state.shapes[i];
        collision_object
            .get_mut_base()
            .update_shape_transform(i, shape, physics_engine);
    }
    collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
}

pub(super) fn remove_shape_idx(
    collision_object: &mut dyn IRapierCollisionObject,
    p_index: usize,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_shapes: &mut PhysicsShapes,
    physics_ids: &PhysicsIds,
) {
    if p_index >= collision_object.get_base().state.shapes.len() {
        return;
    }
    if collision_object.get_base().is_compound() {
        let shape = collision_object.get_base().state.shapes[p_index];
        if let Some(shape) = physics_shapes.get_mut(&get_id_rid(shape.id, physics_ids)) {
            shape
                .get_mut_base()
                .remove_owner(collision_object.get_base().get_id());
        }
        collision_object.get_mut_base().state.shapes.remove(p_index);
        Self::recreate_shapes(
            collision_object,
            physics_engine,
            physics_spaces,
            physics_ids,
        );
        if collision_object.get_base().is_space_valid() {
            collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
        }
        return;
    }
    let shape = collision_object.get_base().state.shapes[p_index];
    if !shape.disabled {
        collision_object.get_base().destroy_shape(
            shape,
            p_index,
            physics_spaces,
            physics_engine,
            physics_ids,
        );
    }
    let shape = collision_object.get_mut_base().state.shapes[p_index];
    collision_object.get_mut_base().state.shapes[p_index].collider_handle =
        ColliderHandle::invalid();
    if let Some(shape) = physics_shapes.get_mut(&get_id_rid(shape.id, physics_ids)) {
        shape
            .get_mut_base()
            .remove_owner(collision_object.get_base().get_id());
    }
    collision_object.get_mut_base().state.shapes.remove(p_index);
    if collision_object.get_base().is_space_valid() {
        collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
    }
    collision_object
        .get_mut_base()
        .update_shapes_indexes(physics_engine);
}

pub(super) fn set_shape(
    collision_object: &mut dyn IRapierCollisionObject,
    p_index: usize,
    p_shape: RapierId,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_shapes: &mut PhysicsShapes,
    physics_ids: &PhysicsIds,
) {
    if p_index >= collision_object.get_base().state.shapes.len() {
        return;
    }
    if collision_object.get_base().is_compound() {
        let old_shape = collision_object.get_base().state.shapes[p_index];
        if let Some(shape) = physics_shapes.get_mut(&get_id_rid(old_shape.id, physics_ids)) {
            shape
                .get_mut_base()
                .remove_owner(collision_object.get_base().get_id());
        }
        collision_object.get_mut_base().state.shapes[p_index].id = p_shape;
        if let Some(shape) = physics_shapes.get_mut(&get_id_rid(p_shape, physics_ids)) {
            shape
                .get_mut_base()
                .add_owner(collision_object.get_base().get_id());
        }
        Self::recreate_shapes(
            collision_object,
            physics_engine,
            physics_spaces,
            physics_ids,
        );
        if collision_object.get_base().is_space_valid() {
            collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
        }
        return;
    }
    collision_object.get_mut_base().state.shapes[p_index].collider_handle =
        collision_object.get_base().destroy_shape(
            collision_object.get_base().state.shapes[p_index],
            p_index,
            physics_spaces,
            physics_engine,
            physics_ids,
        );
    let shape = collision_object.get_base().state.shapes[p_index];
    if let Some(shape) = physics_shapes.get_mut(&get_id_rid(shape.id, physics_ids)) {
        shape
            .get_mut_base()
            .remove_owner(collision_object.get_base().get_id());
    }
    collision_object.get_mut_base().state.shapes[p_index].id = p_shape;
    if let Some(shape) = physics_shapes.get_mut(&get_id_rid(shape.id, physics_ids)) {
        shape
            .get_mut_base()
            .add_owner(collision_object.get_base().get_id());
    }
    if !shape.disabled {
        collision_object.get_mut_base().state.shapes[p_index].collider_handle =
            collision_object.create_shape(shape, p_index, physics_engine);
        let shape = collision_object.get_base().state.shapes[p_index];
        collision_object
            .get_mut_base()
            .update_shape_transform(p_index, shape, physics_engine);
    }
    if collision_object.get_base().is_space_valid() {
        collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
    }
}

pub(super) fn set_shape_transform(
    collision_object: &mut dyn IRapierCollisionObject,
    p_index: usize,
    p_transform: Transform,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_ids: &PhysicsIds,
) {
    if p_index >= collision_object.get_base().state.shapes.len() {
        return;
    }
    collision_object.get_mut_base().state.shapes[p_index].xform = p_transform;
    let shape = collision_object.get_base().state.shapes[p_index];
    collision_object
        .get_mut_base()
        .update_shape_transform(p_index, shape, physics_engine);
    if collision_object.get_base().is_space_valid() {
        collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
    }
}

pub(super) fn set_shape_disabled(
    collision_object: &mut dyn IRapierCollisionObject,
    p_index: usize,
    p_disabled: bool,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
    physics_ids: &PhysicsIds,
) {
    if p_index >= collision_object.get_base().state.shapes.len() {
        return;
    }
    let shape = collision_object.get_base().state.shapes[p_index];
    if shape.disabled == p_disabled {
        return;
    }
    collision_object.get_mut_base().state.shapes[p_index].disabled = p_disabled;
    // Toggling a shape the compound speaks for changes what it holds, and can flip the whole
    // object into or out of compound form. A shape that keeps a collider of its own is left to
    // the per-shape path below, which is the only one that can destroy or rebuild that collider.
    if !collision_object
        .get_base()
        .compound_is_current(physics_engine)
    {
        Self::recreate_shapes(
            collision_object,
            physics_engine,
            physics_spaces,
            physics_ids,
        );
        return;
    }
    let shape = collision_object.get_base().state.shapes[p_index];
    if shape.disabled {
        collision_object.get_mut_base().state.shapes[p_index].collider_handle =
            collision_object.get_base().destroy_shape(
                shape,
                p_index,
                physics_spaces,
                physics_engine,
                physics_ids,
            );
    }
    if !shape.disabled {
        collision_object.get_mut_base().state.shapes[p_index].collider_handle =
            collision_object.create_shape(shape, p_index, physics_engine);
        let shape = collision_object.get_base().state.shapes[p_index];
        collision_object
            .get_mut_base()
            .update_shape_transform(p_index, shape, physics_engine);
    }
    if collision_object.get_base().is_space_valid() {
        collision_object.shapes_changed(physics_engine, physics_spaces, physics_ids);
    }
}

impl RapierDirectBodyState2D {
    pub fn set_body(&mut self, body: Rid) {
        self.implementation.set_body(body);
    }

    fn get_space_state_impl(&mut self) -> Gd<PhysicsDirectSpaceState2D> {
        let physics_data = physics_data();
        if let Some(body) = physics_data
            .collision_objects
            .get(self.implementation.get_body())
            && let Some(space) = physics_data
                .spaces
                .get(&body.get_base().get_space(&physics_data.ids))
            && let Some(state) = space.get_direct_state().clone()
        {
            return state;
        }
        // Error case, should never happen
        godot_error!(
            "RapierDirectBodyState2D: could not get space state for body {:?}",
            self.implementation.get_body()
        );
        RapierDirectSpaceState::new_alloc().upcast()
    }
}

