#[cfg(feature = "dim3")]
pub(super) fn get_inverse_inertia_tensor(&self) -> Basis {
    let physics_data = physics_data();
    if let Some(body) = physics_data.collision_objects.get(&self.body) {
        let basis = body.get_base().get_transform().basis;
        if let Some(body) = body.get_body() {
            // Godot reports the tensor in global orientation, while it's stored in the
            // body local frame.
            return basis * body.get_inv_inertia_tensor() * basis.transposed();
        }
    }
    Basis::IDENTITY
}

#[cfg(feature = "dim3")]
pub(super) fn get_principal_inertia_axes(&self) -> Basis {
    let physics_data = physics_data();
    if let Some(body) = physics_data.collision_objects.get(&self.body) {
        let basis = body.get_base().get_transform().basis;
        if let Some(body) = body.get_body() {
            return basis * body.get_principal_inertia_axes();
        }
    }
    Basis::IDENTITY
}

pub(super) fn get_contact_collider_object(&self, contact_idx: i32) -> Option<Gd<Object>> {
    let physics_data = physics_data();
    if let Some(body) = physics_data.collision_objects.get(&self.body)
        && let Some(body) = body.get_body()
        && let Some(contact) = body.contacts().get(contact_idx as usize)
    {
        let rapier_id = contact.collider_instance_id;
        if let Some(rid) = physics_data.ids.get(&rapier_id)
            && let Some(collider_obj) = physics_data.collision_objects.get(rid)
        {
            let instance_id =
                InstanceId::try_from_i64(collider_obj.get_base().get_instance_id() as i64)?;
            return Gd::try_from_instance_id(instance_id).ok();
        }
    }
    None
}

pub fn get_remaining_times(fluid: &Fluid) -> PackedFloat32Array {
    let ticks = Time::singleton().get_ticks_msec() as f32;
    fluid
        .create_times
        .as_slice()
        .iter()
        .map(|&create_time| (ticks - create_time) * (1.0 / 1000.0))
        .collect()
}

#[allow(clippy::too_many_arguments)]
pub fn new(
    id: RapierId,
    rid: Rid,
    p_anchor_a: Vector,
    p_anchor_b: Vector,
    body_a: &RapierCollisionObject,
    body_b: &RapierCollisionObject,
    physics_engine: &mut PhysicsEngine,
    joint_type: RapierJointType,
) -> Self {
    let invalid_joint = Self {
        rest_length: 0.0,
        stiffness: 20.0,
        damping: 1.0,
        base: RapierJointBase::default(),
    };
    let body_a_rid = body_a.get_base().get_rid();
    let body_b_rid = body_b.get_base().get_rid();
    if body_a_rid == body_b_rid {
        return invalid_joint;
    }
    if !body_a.get_base().is_valid()
        || !body_b.get_base().is_valid()
        || body_a.get_base().get_space_id() != body_b.get_base().get_space_id()
    {
        return invalid_joint;
    }
    // Convert world positions to local positions without scale for proper joint anchor placement
    let rapier_anchor_a =
        world_to_local_no_scale(&body_a.get_base().get_transform(), p_anchor_a);
    let rapier_anchor_b =
        world_to_local_no_scale(&body_b.get_base().get_transform(), p_anchor_b);
    let rest_length = vector_length(p_anchor_a - p_anchor_b);
    let space_handle = body_a.get_base().get_space_id();
    let space_id = body_a.get_base().get_space_id();
    let handle = physics_engine.joint_create_spring(
        space_handle,
        body_a.get_base().get_body_handle(),
        body_b.get_base().get_body_handle(),
        vector_to_rapier(rapier_anchor_a),
        vector_to_rapier(rapier_anchor_b),
        20.0,
        1.0,
        rest_length,
        joint_type,
        true,
    );
    Self {
        rest_length,
        stiffness: 20.0,
        damping: 1.0,
        base: RapierJointBase::new(id, rid, space_id, space_handle, handle, joint_type),
    }
}

