impl RapierGrooveJoint2D {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        id: RapierId,
        rid: Rid,
        p_a_groove1: Vector,
        p_a_groove2: Vector,
        p_b_anchor: Vector,
        body_a: &RapierCollisionObject,
        body_b: &RapierCollisionObject,
        physics_engine: &mut PhysicsEngine,
        joint_type: RapierJointType,
    ) -> Self {
        let invalid_joint = Self {
            base: RapierJointBase::default(),
        };
        let body_a_rid = body_a.get_base().get_rid();
        let body_b_rid = body_b.get_base().get_rid();
        if body_a_rid == body_b_rid {
            return invalid_joint;
        }
        if !body_a.get_base().is_valid()
            || !body_b.get_base().is_valid()
            || body_a.get_base().get_space_id() != body_b.get_base().get_space_id()
        {
            return invalid_joint;
        }
        let base_a = body_a.get_base();
        // Convert world positions to local positions without scale for proper joint anchor placement
        let point_a_1 = world_to_local_no_scale(&base_a.get_transform(), p_a_groove1);
        let point_a_2 = world_to_local_no_scale(&base_a.get_transform(), p_a_groove2);
        let axis = vector_normalized(point_a_2 - point_a_1);
        let length = vector_length(point_a_2 - point_a_1);
        let rapier_axis = vector_to_rapier(axis);
        let rapier_limits = vector_to_rapier(Vector2::new(0.0, length));
        let rapier_anchor_a = vector_to_rapier(point_a_1);
        let base_b = body_b.get_base();
        // Convert world position to local position without scale for proper joint anchor placement
        let anchor_b = world_to_local_no_scale(&base_b.get_transform(), p_b_anchor);
        let rapier_anchor_b = vector_to_rapier(anchor_b);
        let space_handle = body_a.get_base().get_space_id();
        let space_id = body_a.get_base().get_space_id();
        let handle = physics_engine.joint_create_pin_slot(
            space_handle,
            body_a.get_base().get_body_handle(),
            body_b.get_base().get_body_handle(),
            rapier_axis,
            rapier_anchor_a,
            rapier_anchor_b,
            rapier_limits,
            joint_type,
            true,
        );
        Self {
            base: RapierJointBase::new(id, rid, space_id, space_handle, handle, joint_type),
        }
    }
}

pub trait IRapierJoint {
    fn get_base(&self) -> &RapierJointBase;
    fn get_mut_base(&mut self) -> &mut RapierJointBase;
    fn get_type(&self) -> JointType;

    /// Named apart from each joint type's own `set_param`, which takes that type's specific
    /// param enum. Joint types that map a generic param onto a rapier joint override this so
    /// they can rebuild the rapier joint when it changes.
    #[cfg(feature = "dim2")]
    fn set_joint_param(
        &mut self,
        param: JointParam,
        value: f32,
        _physics_engine: &mut PhysicsEngine,
    ) {
        if param == JointParam::MAX_FORCE {
            self.get_mut_base().set_max_force(value);
        }
    }

    #[cfg(feature = "dim2")]
    fn get_joint_param(&self, param: JointParam) -> f32 {
        if param == JointParam::MAX_FORCE {
            self.get_base().get_max_force()
        } else {
            0.0
        }
    }
}

