#[cfg(feature = "dim2")]
#[allow(clippy::too_many_arguments)]
pub(super) unsafe fn shape_collide(
    &mut self,
    shape_a: Rid,
    xform_a: Transform,
    motion_a: Vector,
    shape_b: Rid,
    xform_b: Transform,
    motion_b: Vector,
    results: RawPtr<*mut c_void>,
    result_max: i32,
    result_count: RawPtr<*mut i32>,
) -> bool {
    let physics_data = physics_data();
    if !result_count.ptr().is_null() {
        unsafe { *result_count.ptr() = 0 };
    }
    let Some(shape_a_handle) = physics_data
        .shapes
        .get(&shape_a)
        .map(|shape| shape.get_base().get_id())
    else {
        return false;
    };
    let Some(shape_b_handle) = physics_data
        .shapes
        .get(&shape_b)
        .map(|shape| shape.get_base().get_id())
    else {
        return false;
    };
    let shape_a_info = shape_info_from_body_shape(shape_a_handle, xform_a);
    let shape_b_info = shape_info_from_body_shape(shape_b_handle, xform_b);
    let rapier_a_motion = vector_to_rapier(motion_a);
    let rapier_b_motion = vector_to_rapier(motion_b);
    let results_out: *mut Vector = results.ptr() as *mut Vector;
    let result = physics_data.physics_engine.shape_collide(
        rapier_a_motion,
        shape_a_info,
        rapier_b_motion,
        shape_b_info,
    );
    if !result.collided {
        return false;
    }
    if result_max >= 1 {
        if !result_count.ptr().is_null() {
            unsafe { *result_count.ptr() = 1 };
        }
        let vector2_slice: &mut [Vector] =
            unsafe { std::slice::from_raw_parts_mut(results_out, result_max as usize * 2) };
        vector2_slice[0] = vector_to_godot(result.pixel_witness1);
        vector2_slice[1] = vector_to_godot(result.pixel_witness2);
    }
    true
}

pub(super) fn space_get_direct_state(
    &mut self,
    space: Rid,
) -> Option<Gd<PhysicsDirectSpaceState>> {
    if !self.state_is_accessible() {
        godot_error!(
            "Space state is inaccessible right now, wait for iteration or physics process notification."
        );
        return None;
    }
    let physics_data = physics_data();
    if let Some(space) = physics_data.spaces.get(&space) {
        return space.get_direct_state().clone();
    }
    None
}

pub(super) fn area_set_space(&mut self, area: Rid, space: Rid) {
    let physics_data = physics_data();
    if let Some(area_object) = physics_data.collision_objects.get(&area)
        && let Some(rapier_area) = area_object.get_area()
        && rapier_area.has_any_space_override()
        && area_object.get_base().get_space(&physics_data.ids) != space
    {
        let area_id = area_object.get_base().get_id();
        RapierArea::disable_space_override(
            &area_id,
            &mut physics_data.spaces,
            &mut physics_data.collision_objects,
            &physics_data.ids,
        );
    }
    if let Some(area) = physics_data.collision_objects.get_mut(&area) {
        if let Some(area) = area.get_mut_area() {
            area.clear_monitored_objects();
        }
        area.set_space(
            space,
            &mut physics_data.physics_engine,
            &mut physics_data.spaces,
            &mut physics_data.ids,
        );
    }
}

#[cfg(feature = "dim2")]
pub(super) fn body_set_shape_as_one_way_collision(
    &mut self,
    body: Rid,
    shape_idx: i32,
    enable: bool,
    margin: f32,
    direction: Vector2,
) {
    let physics_data = physics_data();
    if let Some(body) = physics_data.collision_objects.get_mut(&body) {
        body.get_mut_base().set_shape_as_one_way_collision(
            shape_idx as usize,
            enable,
            margin,
            direction,
        );
        // One-way filtering is per shape, which a compound collider cannot express, so gaining
        // or losing it moves the shape into or out of the compound.
        if !body
            .get_base()
            .compound_is_current(&physics_data.physics_engine)
        {
            body.recreate_shapes(
                &mut physics_data.physics_engine,
                &mut physics_data.spaces,
                &physics_data.ids,
            );
        }
    }
}

pub(super) fn body_get_direct_state(
    &mut self,
    body: Rid,
) -> Option<Gd<PhysicsDirectBodyState>> {
    if !self.state_is_accessible() {
        godot_error!(
            "Body state is inaccessible right now, wait for iteration or physics process notification."
        );
        return None;
    }
    let physics_data = physics_data();
    if let Some(body) = physics_data.collision_objects.get_mut(&body)
        && let Some(body) = body.get_mut_body()
    {
        body.create_direct_state();
        return body.get_direct_state().cloned();
    }
    None
}

#[allow(clippy::too_many_arguments)]
/// # Safety
///
/// `result` must point to a valid writable Godot motion result for the duration of this call.
pub unsafe fn body_test_motion(
    &self,
    body: Rid,
    from: Transform,
    motion: Vector,
    margin: f32,
    _max_collisions: i32,
    collide_separation_ray: bool,
    recovery_as_collision: bool,
    result: RawPtr<*mut PhysicsServerExtensionMotionResult>,
) -> bool {
    let physics_data = physics_data();
    if let Some(body) = physics_data.collision_objects.get(&body)
        && let Some(body) = body.get_body()
        && let Some(space) = physics_data
            .spaces
            .get(&body.get_base().get_space(&physics_data.ids))
    {
        let result: &mut PhysicsServerExtensionMotionResult = unsafe { &mut *result.ptr() };
        return space.test_body_motion(
            body,
            from,
            motion,
            margin,
            collide_separation_ray,
            recovery_as_collision,
            result,
            &physics_data.physics_engine,
            &physics_data.shapes,
            &physics_data.ids,
            &physics_data.collision_objects,
        );
    }
    false
}

#[cfg(feature = "dim3")]
#[allow(clippy::too_many_arguments)]
pub(super) fn joint_make_hinge_simple(
    &mut self,
    rid: Rid,
    body_a: Rid,
    pivot_a: Vector3,
    axis_a: Vector3,
    body_b: Rid,
    pivot_b: Vector3,
    axis_b: Vector3,
) {
    let physics_data = physics_data();
    let joint: RapierJoint;
    let joint_type = if let Some(prev_joint) = physics_data.joints.get(&rid) {
        prev_joint.get_base().get_joint_type()
    } else {
        RapierJointType::Impulse
    };
    if let Some(body_a) = physics_data.collision_objects.get(&body_a)
        && let Some(body_b) = physics_data.collision_objects.get(&body_b)
    {
        // Create basis from axis vectors
        // The hinge axis should be the X-axis in the local frame
        // Construct a basis where X-axis is aligned with the given axis
        let basis_a = if axis_a.length_squared() > 0.0 {
            let x_axis = vector_normalized(axis_a);
            // Choose an arbitrary perpendicular vector for Y
            let y_axis = if x_axis.abs().dot(Vector3::UP) < 0.99 {
                vector_normalized(x_axis.cross(Vector3::UP))
            } else {
                vector_normalized(x_axis.cross(Vector3::RIGHT))
            };
            let z_axis = vector_normalized(x_axis.cross(y_axis));
            godot::prelude::Basis::from_cols(x_axis, y_axis, z_axis)
        } else {
            godot::prelude::Basis::IDENTITY
        };
        let basis_b = if axis_b.length_squared() > 0.0 {
            let x_axis = vector_normalized(axis_b);
            let y_axis = if x_axis.abs().dot(Vector3::UP) < 0.99 {
                vector_normalized(x_axis.cross(Vector3::UP))
            } else {
                vector_normalized(x_axis.cross(Vector3::RIGHT))
            };
            let z_axis = vector_normalized(x_axis.cross(y_axis));
            godot::prelude::Basis::from_cols(x_axis, y_axis, z_axis)
        } else {
            godot::prelude::Basis::IDENTITY
        };
        let id = self.next_id();
        joint = RapierJoint::RapierRevoluteJoint(RapierRevoluteJoint::new(
            id,
            rid,
            pivot_a,
            pivot_b,
            basis_a,
            basis_b,
            body_a,
            body_b,
            &mut physics_data.physics_engine,
            joint_type,
        ));
        let prev_joint = physics_data.joints.remove(&rid);
        physics_data.joints.insert(rid, joint);
        if let Some(mut prev_joint) = prev_joint {
            if let Some(joint) = physics_data.joints.get_mut(&rid) {
                joint.get_mut_base().copy_settings_from(
                    prev_joint.get_base(),
                    &mut physics_data.physics_engine,
                );
            }
            prev_joint
                .get_mut_base()
                .destroy_joint(&mut physics_data.physics_engine);
        }
    } else {
        let id = self.next_id();
        joint = RapierJoint::RapierEmptyJoint(RapierEmptyJoint::new(id));
        physics_data.joints.insert(rid, joint);
    }
}

fn free_rid_now(&mut self, rid: Rid) {
    let physics_data = physics_data();
    let mut space_to_reset = Rid::Invalid;
    if let Some(mut shape) = physics_data.shapes.remove(&rid) {
        for owner in shape.get_base().get_owners().keys() {
            if let Some(body) = physics_data
                .collision_objects
                .get_mut(&get_id_rid(*owner, &physics_data.ids))
            {
                space_to_reset = body.get_base().get_space(&physics_data.ids);
                body.remove_shape_rid(
                    shape.get_base().get_rid(),
                    &mut physics_data.physics_engine,
                    &mut physics_data.spaces,
                    &mut physics_data.shapes,
                    &physics_data.ids,
                );
            }
        }
        shape
            .get_mut_base()
            .destroy_shape(&mut physics_data.physics_engine);
        remove_id_rid(shape.get_base().get_id(), &mut physics_data.ids);
    } else if let Some(mut body) = physics_data.collision_objects.remove(&rid) {
        space_to_reset = body.get_base().get_space(&physics_data.ids);
        body.set_space(
            Rid::Invalid,
            &mut physics_data.physics_engine,
            &mut physics_data.spaces,
            &mut physics_data.ids,
        );
        remove_id_rid(body.get_base().get_id(), &mut physics_data.ids);
    } else if let Some(mut space) = physics_data.spaces.remove(&rid) {
        let space_handle = space.get_state().get_id();
        remove_id_rid(space.get_state().get_id(), &mut physics_data.ids);
        space
            .get_mut_state()
            .destroy(&mut physics_data.physics_engine);
        physics_data.active_spaces.remove(&space_handle);
    } else if let Some(mut joint) = physics_data.joints.remove(&rid) {
        space_to_reset = joint.get_base().get_space(&physics_data.ids);
        joint
            .get_mut_base()
            .destroy_joint(&mut physics_data.physics_engine);
        remove_id_rid(joint.get_base().get_id(), &mut physics_data.ids);
    } else if let Some(mut fluid) = physics_data.fluids.remove(&rid) {
        fluid.destroy_fluid(&mut physics_data.physics_engine);
        remove_id_rid(fluid.get_id(), &mut physics_data.ids);
    }
    if let Some(space) = physics_data.spaces.get_mut(&space_to_reset) {
        space.get_mut_state().reset_space_if_empty(
            &mut physics_data.physics_engine,
            &RapierSpace::get_world_settings(),
        );
    }
    // If there are no more objects, reset the ids. Ensures there will be determinism.
    if physics_data.collision_objects.is_empty()
        && physics_data.spaces.is_empty()
        && physics_data.joints.is_empty()
        && physics_data.fluids.is_empty()
        && physics_data.shapes.is_empty()
        && physics_data.ids.is_empty()
    {
        self.id = RapierId::default();
    }
}

pub fn motion_settings() -> &'static MotionSettings {
    MOTION_SETTINGS.get_or_init(|| {
        if !bindings_ready() {
            return MotionSettings::default();
        }
        MotionSettings {
            recover_attempts: RapierProjectSettings::get_setting_int(MOTION_RECOVER_ATTEMPTS).max(1)
                as i32,
            recover_ratio: (RapierProjectSettings::get_setting_double(MOTION_RECOVER_RATIO)
                as Real)
                .clamp(0.05, 1.0),
            cast_iterations: RapierProjectSettings::get_setting_int(MOTION_CAST_ITERATIONS).max(1)
                as i32,
            stuck_penetration: RapierProjectSettings::get_setting_double(MOTION_STUCK_PENETRATION)
                as Real,
            max_shape_cast_results: RapierProjectSettings::get_setting_int(
                QUERY_MAX_SHAPE_CAST_RESULTS,
            )
            .max(1) as usize,
            point_query_honors_pickable: ProjectSettings::singleton()
                .get_setting_with_override(QUERY_POINT_HONORS_PICKABLE)
                .try_to()
                .unwrap_or(true),
            shape_scale_subdivisions: RapierProjectSettings::get_setting_int(
                SHAPE_SCALE_SUBDIVISIONS,
            )
            .max(4) as u32,
        }
    })
}

fn get_setting_double(p_setting: &str) -> f64 {
    let project_settings = ProjectSettings::singleton();
    let setting_value = project_settings.get_setting_with_override(p_setting);
    // A value written as an integer -- from override.cfg, or `set_setting(name, 0)` --
    // arrives as an Int variant that a strict float conversion does not survive. Callers
    // use these as thresholds, where a garbage read silently disables the behaviour the
    // setting gates, so fall back through int and never hand back a non-finite number.
    let value = setting_value
        .try_to::<f64>()
        .or_else(|_| setting_value.try_to::<i64>().map(|i| i as f64))
        .unwrap_or(0.0);
    if value.is_finite() { value } else { 0.0 }
}

