fn heights_from_image(image: &Gd<Image>) -> Option<PackedFloatArray> {
    let format = image.get_format();
    if format != godot::classes::image::Format::RF {
        godot_error!("Heightmap image must use Image.FORMAT_RF. Got {:?}", format);
        return None;
    }
    let data = image.get_data();
    let bytes = data.as_slice();
    let heights: Vec<real> = bytes
        .as_chunks::<{ size_of::<f32>() }>()
        .0
        .iter()
        .map(|sample| f32::from_le_bytes(*sample) as real)
        .collect();
    Some(PackedFloatArray::from(heights.as_slice()))
}

fn set_data(&mut self, data: Variant, physics_engine: &mut PhysicsEngine) {
    let width;
    let depth;
    let heights;
    if let Ok(dictionary) = data.try_to::<VarDictionary>() {
        let in_width = dictionary.get_or_nil("width");
        let in_depth = dictionary.get_or_nil("depth");
        let new_heights = dictionary.get_or_nil("heights");
        let in_heights = match new_heights.try_to::<PackedFloatArray>() {
            Ok(in_heights) => Some(in_heights),
            Err(_) => match new_heights.try_to::<Gd<Image>>() {
                Ok(image) => heights_from_image(&image),
                Err(_) => {
                    godot_error!(
                        "Invalid heightmap heights. Expected a float array or a float Image. Got {}",
                        new_heights
                    );
                    return;
                }
            },
        };
        if let Ok(in_width) = in_width.try_to::<i32>()
            && let Ok(in_depth) = in_depth.try_to::<i32>()
            && let Some(in_heights) = in_heights
        {
            width = in_width;
            depth = in_depth;
            heights = in_heights;
            // Compute min and max heights or use precomputed values.
            let mut min_height: real = 0.0;
            let mut max_height: real = 0.0;
            if let Some(new_min_height) = dictionary.get("min_height")
                && let Some(new_max_height) = dictionary.get("max_height")
            {
                let new_min_height = variant_to_float(&new_min_height);
                let new_max_height = variant_to_float(&new_max_height);
                min_height = new_min_height;
                max_height = new_max_height;
            } else {
                let heights_size = heights.len();
                for i in 0..heights_size {
                    let h = heights[i];
                    if h < min_height {
                        min_height = h;
                    } else if h > max_height {
                        max_height = h;
                    }
                }
            }
            if min_height > max_height {
                godot_error!("Invalid heightmap shape data");
                return;
            }
        } else {
            godot_error!("Invalid heightmap dictionary data. Got {}", data);
            return;
        }
    } else {
        godot_error!("Invalid heightmap shape data type. Got {}", data);
        return;
    }
    if width <= 1 || depth <= 1 {
        godot_error!("Heightmap must have width and depth at least 2");
        return;
    }
    let Some(height_count) = width.checked_mul(depth) else {
        godot_error!("Invalid heightmap shape data");
        return;
    };
    if heights.len() != height_count as usize {
        godot_error!("Invalid heightmap shape data");
        return;
    }
    physics_engine.shape_create_heightmap(heights.as_slice(), width, depth, self.base.get_id());
    self.base.reset_aabb(physics_engine);
}

fn try_node_from_instance_id(instance_id: u64) -> Option<Gd<Node>> {
