pub fn create(
    id: RapierId,
    rid: Rid,
    physics_engine: &mut PhysicsEngine,
    physics_spaces: &mut PhysicsSpaces,
) {
    let mut direct_access = RapierDirectSpaceState::new_alloc();
    direct_access.bind_mut().set_space(rid);
    let project_settings = ProjectSettings::singleton();
    let default_gravity_dir: Vector = project_settings
        .get_setting_with_override(DEFAULT_GRAVITY_VECTOR)
        .try_to()
        .unwrap_or_default();
    let default_gravity_value =
        variant_to_float(&project_settings.get_setting_with_override(DEFAULT_GRAVITY));
    let space = Self {
        direct_access: Some(direct_access.upcast()),
        contact_max_allowed_penetration: 0.0,
        default_gravity_dir,
        default_gravity_value,
        default_linear_damping: 0.0,
        default_angular_damping: 0.0,
        contact_debug: PackedVectorArray::new(),
        contact_debug_count: 0,
        #[cfg(feature = "dim2")]
        constraint_default_bias: 0.2,
        query_callbacks: Vec::new(),
        state: RapierSpaceState::new(id, physics_engine, &Self::get_world_settings()),
    };
    physics_spaces.insert(rid, space);
}

pub fn after_step(
    &mut self,
    physics_engine: &mut PhysicsEngine,
    physics_collision_objects: &mut PhysicsCollisionObjects,
    physics_ids: &PhysicsIds,
) {
    // Needed only for one physics step to retrieve lost info
    self.state.reset_removed_colliders();
    self.state.set_active_objects(
        physics_engine.world_get_active_objects_count(self.state.get_id()) as i32,
    );
    let active_bodies: Vec<_> = self.state.get_active_list().iter().copied().collect();
    for body in active_bodies {
        if let Some(body) = physics_collision_objects.get_mut(&get_id_rid(body, physics_ids))
            && let Some(body) = body.get_mut_body()
        {
            if body.get_state_sync_callback().is_some() {
                self.get_mut_state()
                    .body_add_to_state_query_list(body.get_base().get_id());
            }
            if body.is_sleeping(physics_engine) {
                body.set_active(false, self);
                continue;
            }
            body.on_update_active(self, physics_engine);
        }
    }
}

impl PhysicsEngine {
    #[allow(clippy::too_many_arguments)]
    fn should_skip_collision_one_dir(
        &self,
        contact: &ContactResult,
        body_shape: &RapierShape,
        collision_body: &RapierCollisionObject,
        shape_index: usize,
        col_shape_transform: &Transform,
        p_margin: f32,
        last_step: f32,
        limit_depth: bool,
    ) -> bool {
        if body_shape.allows_one_way_collision()
            && collision_body
                .get_base()
                .is_shape_set_as_one_way_collision(shape_index)
        {
            let valid_dir = get_one_way_valid_direction(
                col_shape_transform,
                collision_body
                    .get_base()
                    .get_shape_one_way_collision_direction(shape_index),
            );
            let valid_depth = if limit_depth {
                let owc_margin = collision_body
                    .get_base()
                    .get_shape_one_way_collision_margin(shape_index);
                let mut platform_linear_velocity = Vector::default();
                if let Some(b) = collision_body.get_body()
                    && b.get_base().mode.ord() >= BodyMode::KINEMATIC.ord()
                {
                    platform_linear_velocity = b.get_linear_velocity(self);
                }
                OneWayDepthLimit::UpTo(one_way_valid_depth(
                    owc_margin,
                    p_margin,
                    platform_linear_velocity,
                    last_step,
                    valid_dir,
                ))
            } else {
                OneWayDepthLimit::Unlimited
            };
            if is_one_way_contact_invalid(contact, valid_dir, valid_depth) {
                return true;
            }
        }
        false
    }
}

pub fn contact_point_callback(
    &mut self,
    contact_info: &ContactPointInfo,
    event_info: &ContactForceEventInfo,
    physics_collision_objects: &mut PhysicsCollisionObjects,
    physics_ids: &PhysicsIds,
) {
    let pos1 = contact_info.pixel_local_pos_1;
    let pos2 = contact_info.pixel_local_pos_2;
    if self.is_debugging_contacts() {
        self.add_debug_contact(vector_to_godot(pos1));
        self.add_debug_contact(vector_to_godot(pos2));
    }
    let (p_object1, shape1) =
        RapierCollisionObjectBase::get_collider_user_data(&event_info.user_data1, physics_ids);
    let (p_object2, shape2) =
        RapierCollisionObjectBase::get_collider_user_data(&event_info.user_data2, physics_ids);
    let [p_object1, p_object2] =
        physics_collision_objects.get_disjoint_mut([&p_object1, &p_object2]);
    if let (Some(p_object1), Some(p_object2)) = (p_object1, p_object2) {
        let depth = real::max(0.0, -contact_info.pixel_distance); // negative distance means penetration
        let normal = contact_info.normal;
        // send just impulse directly along normal
        let impulse = contact_info.pixel_impulse * vector_to_godot(normal);
        let tangent_impulse = tangent_impulse_magnitude(contact_info.pixel_tangent_impulse);
        let vel_pos1 = contact_info.pixel_velocity_pos_1;
        let vel_pos2 = contact_info.pixel_velocity_pos_2;
        if let Some(body1) = p_object1.get_mut_body()
            && let Some(body2) = p_object2.get_mut_body()
        {
            let static_linvelocity_1 = body1.get_static_linear_velocity();
            let static_linvelocity_2 = body2.get_static_linear_velocity();
            let static_angvelocity_1 = body1.get_static_angular_velocity();
            let static_angvelocity_2 = body2.get_static_angular_velocity();
            if static_linvelocity_1 != Vector::ZERO {
                body2.to_add_static_constant_linear_velocity(static_linvelocity_1);
            }
            if static_linvelocity_2 != Vector::ZERO {
                body1.to_add_static_constant_linear_velocity(static_linvelocity_2);
            }
            if static_angvelocity_1 != ANGLE_ZERO {
                body2.to_add_static_constant_angular_velocity(static_angvelocity_1);
            }
            if static_angvelocity_2 != ANGLE_ZERO {
                body1.to_add_static_constant_angular_velocity(static_angvelocity_2);
            }
            if body1.can_report_contacts() {
                body1.add_contact(
                    vector_to_godot(pos1),
                    vector_to_godot(-normal),
                    depth,
                    shape1 as i32,
                    vector_to_godot(vel_pos1),
                    vector_to_godot(pos2),
                    shape2 as i32,
                    body2.get_base().get_id(),
                    body2.get_base().get_id(),
                    vector_to_godot(vel_pos2),
                    impulse,
                    tangent_impulse,
                );
            }
            if body2.can_report_contacts() {
                body2.add_contact(
                    vector_to_godot(pos2),
                    vector_to_godot(normal),
                    depth,
                    shape2 as i32,
                    vector_to_godot(vel_pos2),
                    vector_to_godot(pos1),
                    shape1 as i32,
                    body1.get_base().get_id(),
                    body1.get_base().get_id(),
                    vector_to_godot(vel_pos1),
                    -impulse,
                    tangent_impulse,
                );
            }
        }
    }
}

