    #[export(range = (0.0,10.0,0.001,or_greater))]
    #[init(val = 1.0)]
    spring_constant_multiplier: f32,

    /// What tick to update the [SimulatedRope]'s bound position on.
    #[var(set = set_update_tick)]
    #[export(enum = (Disabled = 0, Process = 1, PhysicsProcess = 2))]
    #[init(val = 2)]
    update_tick: i32,

    /// Whether this rope can snap or not.
    #[export]
    #[init(val = false)]
    snap_enabled: bool,

    /// If [snap_enabled] is true, when this amount of tension is applied to this binding,
    /// the rope binding will "snap," releasing the rope.
    #[export(range = (0.0, 15000.0, 0.001, or_greater, suffix="N"))]
    #[init(val = 5000.0)]
    snap_tension_threshold: f32,

    #[init(val = None)]
    event_rope_tree_exiting: Option<ConnectHandle>,

    base: Base<Node3D>,
}

pub fn editor_lock(mut node: Gd<Node>, lock: bool) {
    node.set_meta("_edit_lock_", &Variant::from(lock));
}

pub fn serialize_from(&mut self, node: &Gd<Node3D>) {
    self.serialize_walk(
        node,
        node,
        &node.clone().upcast::<Node>(),
        Transform3D::IDENTITY,
    );
}

fn serialize_walk(
    &mut self,
    _top_level_parent: &Gd<Node3D>,
    _parent: &Gd<Node3D>,
    node: &Gd<Node>,
    mut transform: Transform3D,
) {
    for child in node.get_children().iter_shared() {
        match_class! { child.clone(),
            child3d @ Node3D => {
                // Continue to build transform stack
                let stack = transform * child3d.get_transform();

                // Only continue walk if node is visible
                if child3d.is_visible() {
                    self.serialize_walk(_top_level_parent, _parent, &child, stack);
                }
            },
            _ => self.serialize_walk(_top_level_parent, _parent, &child, transform),
        }
    }

    let op: ShapeOperation; // CSG operation of node

    // First, do generic cast to get basic Node3D properties
    if let Ok(shape) = node.clone().try_cast::<CsgShape3D>() {
        // If the shape is hidden, don't serialize it!
        if !shape.is_visible() {
            return;
        }

        // Get node's CSG operation
        op = csg_operation(shape.get_operation());
    } else {
        // This isn't a valid node!
        return;
    }

    // Then, cast to each type of CSG class
    match_class! {node.clone(),
        csg @ CsgBox3D => {
            // Since we have a box, we can pull out the scale
            let mut scale = transform.basis.get_scale();
            // ...and unscale the transform!
            transform = transform.scaled_local(Vec3Godot::ONE / scale);
            // Also, don't forget to factor in the original CSG box scale on top
            scale *= csg.get_size();

            // Finally, store shape
            self.shapes.push(sdf::Shape::rounded_box(
                transform.to_transform3d(),
                scale.to_vector3(),
                0.0,
                op,
            ));
        },
        csg @ CsgSphere3D => {
            self.shapes.push(sdf::Shape::sphere(
                transform.to_transform3d(),
                csg.get_radius(),
                op,
            ));
        },
        csg @ CsgCylinder3D => {
            let mut scale = transform.basis.get_scale();
            transform = transform.scaled_local(Vec3Godot::ONE / Vec3Godot::new(1.0, scale.y, 1.0));
            scale.y *= csg.get_height();

            self.shapes.push(sdf::Shape::rounded_cylinder(
                transform.to_transform3d(),
                scale.y,
                csg.get_radius(),
                0.0,
                op,
            ));
        },
        csg @ CsgTorus3D => {
            let thickness = (csg.get_outer_radius() - csg.get_inner_radius()).abs() * 0.5;
            self.shapes.push(sdf::Shape::torus(
                transform.to_transform3d(),
                thickness,
                (csg.get_outer_radius() - thickness).abs(),
                op,
            ));
        },
        _ => {}
    }
}

#[proc_macro_attribute]
pub fn camera_process_toggles(_attr: TokenStream, item: TokenStream) -> TokenStream {
    let input = parse_macro_input!(item as syn::DeriveInput);
    let struct_identifier = &input.ident.to_token_stream();

    match &input.data {
        syn::Data::Struct(syn::DataStruct { fields, .. }) => {
            let mut attributes = quote! {};
            for attribute in &input.attrs {
                attributes.extend(quote! { #attribute });
            }

            let mut field_tokens = quote! {};
            for field in fields {
                let f = field.to_token_stream();
                field_tokens.extend(quote! { #f, });
            }

            quote! {
                #[automatically_derived]
                #attributes
                pub struct #struct_identifier {
                    #[export_group(name = "Process")]
                    /// Whether to continue tracking targets or not.
                    #[export]
                    #[var(set = set_enabled)]
                    #[init(val = true)]
                    enabled: bool,

                    /// Whether to perform tracking in-editor.
                    #[export]
                    #[var(set = set_editor_preview)]
                    #[init(val = true)]
                    editor_preview: bool,

                    #field_tokens
                }

                #[automatically_derived]
                // #[godot_api(secondary)]
                impl #struct_identifier {
                    /// Decides whether processing is enabled or not.
                    fn update_tracking(&mut self) {
                        let mut enabled = self.enabled;
                        if Engine::singleton().is_editor_hint() {
                            enabled = enabled && self.editor_preview;
                        }
                        self.base_mut().set_process(enabled);
                    }
                }
            }
        }
        _ => unimplemented!(),
    }
    .into()
}

impl PeerwireDoc {
    /// Doc `id` of the multiplayer peer `peer`.
    pub(crate) fn make(peer: InstanceId, id: DocId) -> Gd<PeerwireDoc> {
        Gd::from_init_fn(|base| PeerwireDoc { base, peer, id })
    }

    /// Runs `f` on the doc, if its peer still has it open.
    fn with<R>(&self, f: impl FnOnce(DocMut<'_>) -> R) -> Option<R> {
        let mut peer = Gd::<PeerwireMultiplayerPeer>::try_from_instance_id(self.peer).ok()?;
        let mut p = peer.bind_mut();
        let s: &mut Session = p.session_mut()?;
        Some(f(s.doc(self.id)?))
    }

    fn entries(&self, kind: Kind, coll: GString) -> VarArray {
        let items = self.with(|d| d.entries(kind, &coll.to_string())).unwrap_or_default();
        items.iter().map(|it| item_dict(kind, it).to_variant()).collect()
    }

    fn get(&self, kind: Kind, coll: GString, key: GString) -> Variant {
        self.with(|d| d.get(kind, &coll.to_string(), &key.to_string()).map(value)).flatten().unwrap_or_default()
    }
}

fn open_doc_with(&mut self, name: GString, copy: Option<Vec<u8>>) -> Option<Gd<PeerwireDoc>> {
    let Some(s) = self.session.as_mut() else {
        godot_error!("PeerwireMultiplayerPeer.open_doc: host or join first");
        return None;
    };
    let id = match s.open_doc(&name.to_string(), copy.as_deref()) {
        Ok(id) => id,
        Err(e) => {
            godot_error!("PeerwireMultiplayerPeer.open_doc: {e}");
            return None;
        }
    };
    if let Some(d) = self.docs.get(&id.0) {
        return Some(d.clone());
    }
    let peer = self.base().instance_id();
    let doc = PeerwireDoc::make(peer, id);
    self.docs.insert(id.0, doc.clone());
    Some(doc)
}

pub fn stream(samples: &[f32], sample_rate: u32) -> Gd<AudioStreamWav> {
    let wav = core::encode_wav(samples, sample_rate);
    let mut stream = AudioStreamWav::new_gd();
    stream.set_format(Format::FORMAT_16_BITS);
    stream.set_mix_rate(sample_rate as i32);
    stream.set_stereo(false);
    stream.set_data(&PackedByteArray::from(&wav[44..]));
    stream
}

