#[godot_api]
impl Mumble {
    /// `{ samples: PackedFloat32Array, duration: float, events: Array }`, or `{ error: String }`.
    /// Each event: `char_index`, `char_count`, `start`, `duration`, `style` (MumbleVoice.BEEP…),
    /// `variant` (which sound of the style: grunt 0–3, letter 0–25, 26 neutral).
    #[func]
    fn render(text: GString, voice: Option<Gd<MumbleVoice>>, sample_rate: i64) -> VarDictionary {
        let text = text.to_string();
        let sample_rate = u32::try_from(sample_rate).unwrap_or(0);
        match core::render(&text, &core_voice(&voice), sample_rate) {
            Ok(r) => {
                let mut events = VarArray::new();
                for e in &r.timeline.events {
                    let start = char_index(&text, e.utf8_start);
                    let end = char_index(&text, e.utf8_start + e.utf8_len);
                    let event = vdict! {
                        "char_index" => start,
                        "char_count" => end - start,
                        "start" => e.start,
                        "duration" => e.duration,
                        "style" => e.sound.style as i64,
                        "variant" => i64::from(e.sound.variant),
                    };
                    events.push(&event.to_variant());
                }
                let samples = PackedFloat32Array::from(r.samples.as_slice());
                vdict! {
                    "samples" => &samples,
                    "duration" => r.timeline.duration,
                    "events" => &events,
                }
            }
            Err(e) => vdict! { "error" => error_name(e) },
        }
    }

    /// A 16-bit PCM mono WAV file.
    #[func]
    fn encode_wav(samples: PackedFloat32Array, sample_rate: i64) -> PackedByteArray {
        PackedByteArray::from(core::encode_wav(samples.as_slice(), sample_rate.max(0) as u32).as_slice())
    }
}

#[godot_api]
impl INode for MumbleSpeaker {
    fn init(base: Base<Node>) -> Self {
        Self {
            voice: None,
            bus: "Master".into(),
            volume_db: 0.0,
            player: None,
            typewriter: None,
            events: Vec::new(),
            next_event: 0,
            duration: 0.0,
            speaking: false,
            wall_clock: false,
            started_usec: 0,
            base,
        }
    }

    /// Stops the voice when leaving the tree, so the AudioServer drops the playback right away.
    fn exit_tree(&mut self) {
        self.stop();
    }

    fn process(&mut self, _delta: f64) {
        if !self.speaking {
            return;
        }
        let position = self.position();
        while let Some(&(start, index)) = self.events.get(self.next_event) {
            if start > position {
                break;
            }
            self.next_event += 1;
            self.signals().character_spoken().emit(index);
        }
        if position >= self.duration {
            self.speaking = false;
            self.signals().finished().emit();
        }
    }
}

fn play(&mut self, stream: Gd<AudioStreamWav>) {
    let bus = self.bus.clone();
    let volume = self.volume_db as f32;
    let mut player = match self.player.clone() {
        Some(p) => p,
        None => {
            let p = AudioStreamPlayer::new_alloc();
            self.base_mut().add_child(&p);
            self.player = Some(p.clone());
            p
        }
    };
    player.set_bus(&bus);
    player.set_volume_db(volume);
    player.set_stream(&stream);
    player.play();
}

fn uses_wall_clock(&self) -> bool {
    let is_web = Os::singleton().has_feature(&GString::from("web"));
    let Some(player) = self.player.as_ref() else {
        return false;
    };
    let player_type = i64::from(player.get_playback_type().ord());
    // The project setting: 0 Stream, 1 Sample. `get_setting_with_override`, as the
    // AudioServer reads it: plain `get_setting` ignores the `.web` override, which is
    // what makes Sample the web default. A value that is not an integer reads as -1,
    // which `wall_clock_for` treats as the audio clock.
    let default_type = ProjectSettings::singleton()
        .get_setting_with_override(&StringName::from("audio/general/default_playback_type"))
        .try_to::<i64>()
        .unwrap_or(-1);
    wall_clock_for(is_web, player_type, default_type)
}

fn position(&self) -> f64 {
    if self.wall_clock {
        let now = Time::singleton().get_ticks_usec();
        return now.saturating_sub(self.started_usec) as f64 / 1_000_000.0;
    }
    let Some(player) = self.player.as_ref() else {
        return 0.0;
    };
    if self.speaking && !player.is_playing() {
        // The stream has played to its end and the player stopped, which resets its playback
        // position: the line was heard to the end. The latency-compensated clock may never
        // reach the duration (large output latency on the web, LD30), so `process` still
        // gets every remaining character and `finished`. `is_playing` is true from the
        // `play` in `say` on, and `stop` clears `speaking` first.
        return f64::INFINITY;
    }
    let server = AudioServer::singleton();
    player.get_playback_position() as f64 + server.get_time_since_last_mix() - server.get_output_latency()
}

#[godot_api]
impl MumbleTypewriter {
    /// Emitted when the whole line is visible.
    #[signal]
    pub fn finished();

    /// Sets the label's text and starts revealing it.
    #[func]
    pub fn type_text(&mut self, text: GString) {
        let text_string = text.to_string();
        let mut visible = 0;
        self.graphemes = text_string
            .graphemes(true)
            .map(|g| {
                visible += g.chars().count() as i64;
                (visible, g.to_string())
            })
            .collect();
        if let Some(mut label) = self.label_node() {
            label.set("text", &text.to_variant());
        }
        self.set_visible(0);
        if let Some(mut speaker) = self.speaker_node() {
            speaker.bind_mut().reset();
        }
        self.next = 0;
        self.wait = 0.0;
        self.typing = true;
    }

    /// Shows the whole line at once and stops the voice.
    #[func]
    pub fn skip(&mut self) {
        if !self.typing {
            return;
        }
        if let Some(mut speaker) = self.speaker_node() {
            speaker.bind_mut().stop();
        }
        self.finish();
    }

    #[func]
    pub fn is_typing(&self) -> bool {
        self.typing
    }
}

impl MumbleTypewriter {
    fn finish(&mut self) {
        self.typing = false;
        self.set_visible(-1);
        self.signals().finished().emit();
    }

    fn set_visible(&mut self, count: i64) {
        if let Some(mut label) = self.label_node() {
            label.set("visible_characters", &count.to_variant());
        }
    }

    fn label_node(&self) -> Option<Gd<Node>> {
        self.base().get_node_or_null(&self.label)
    }

    fn speaker_node(&self) -> Option<Gd<MumbleSpeaker>> {
        self.base().get_node_or_null(&self.speaker).and_then(|n| n.try_cast::<MumbleSpeaker>().ok())
    }
}

