impl<'w> GodotAccess<'w> {
    pub fn try_get<T: Inherits<Node>>(&mut self, handle: GodotNodeHandle) -> Option<Gd<T>> {
        Gd::try_from_instance_id(handle.instance_id()).ok()
    }

    #[track_caller]
    pub fn get<T: Inherits<Node>>(&mut self, handle: GodotNodeHandle) -> Gd<T> {
        self.get_instance_id(handle.instance_id())
    }

    pub fn try_get_instance_id<T: Inherits<Node>>(
        &mut self,
        instance_id: InstanceId,
    ) -> Option<Gd<T>> {
        Gd::try_from_instance_id(instance_id).ok()
    }

    #[track_caller]
    pub fn get_instance_id<T: Inherits<Node>>(&mut self, instance_id: InstanceId) -> Gd<T> {
        let Some(node) = self.try_get_instance_id(instance_id) else {
            panic!(
                "failed to get godot node handle as {}",
                std::any::type_name::<T>()
            );
        };
        node
    }

    /// Access a Godot singleton. Requires main-thread access.
    pub fn singleton<T: Singleton>(&mut self) -> Gd<T> {
        T::singleton()
    }

    /// Create a scoped node accessor tied to this main-thread guard.
    pub fn node<'a>(&'a mut self, handle: GodotNodeHandle) -> GodotNode<'a, 'w> {
        GodotNode {
            godot: self,
            handle,
        }
    }
}

impl<'a, 'w> GodotNode<'a, 'w> {
    pub fn handle(&self) -> GodotNodeHandle {
        self.handle
    }

    pub fn instance_id(&self) -> InstanceId {
        self.handle.instance_id()
    }

    pub fn try_get<T: Inherits<Node>>(&mut self) -> Option<Gd<T>> {
        self.godot.try_get(self.handle)
    }

    #[track_caller]
    pub fn get<T: Inherits<Node>>(&mut self) -> Gd<T> {
        self.godot.get(self.handle)
    }
}

impl GodotNodeHandle {
    pub fn instance_id(self) -> InstanceId {
        self.instance_id
    }

    /// Create a handle from a live Godot node.
    pub fn new<T: Inherits<Node>>(reference: Gd<T>) -> Self {
        Self {
            instance_id: reference.instance_id(),
        }
    }

    pub fn from_instance_id(instance_id: InstanceId) -> Self {
        Self { instance_id }
    }
}

impl<T: Inherits<Node>> From<Gd<T>> for GodotNodeHandle {
    fn from(node: Gd<T>) -> Self {
        Self::new(node)
    }
}

impl GodotResourceHandle {
    #[track_caller]
    pub fn get(&self) -> Gd<Resource> {
        self.try_get()
            .expect("Godot resource was freed unexpectedly")
    }

    pub fn try_get(&self) -> Option<Gd<Resource>> {
        Gd::try_from_instance_id(self.resource_id).ok()
    }

    pub fn new(reference: Gd<Resource>) -> Self {
        let resource_id = reference.instance_id();
        let mut owner = Object::new_alloc();
        owner.set_meta("_resource", &reference.to_variant());

        Self {
            resource_id,
            owner_id: owner.instance_id(),
        }
    }
}

