pub fn find_node_by_pattern(
    base_node: &godot::obj::Gd<godot::classes::Node>,
    pattern: &str,
) -> Option<godot::obj::Gd<godot::classes::Node>> {
    let (search_root, pattern_parts) = if let Some(stripped) = pattern.strip_prefix('/') {
        let scene_tree = base_node.get_tree();
        let root = scene_tree.get_root()?;
        let root_as_node = root.upcast::<godot::classes::Node>();
        let mut parts: Vec<&str> = stripped.split('/').filter(|s| !s.is_empty()).collect();

        if !parts.is_empty() && parts[0] == "root" {
            parts.remove(0);
        }

        (root_as_node, parts)
    } else {
        let parts: Vec<&str> = pattern.split('/').filter(|s| !s.is_empty()).collect();
        (base_node.clone(), parts)
    };

    find_node_recursive(&search_root, &pattern_parts, 0)
}

fn find_node_recursive(
    current_node: &godot::obj::Gd<godot::classes::Node>,
    pattern_parts: &[&str],
    depth: usize,
) -> Option<godot::obj::Gd<godot::classes::Node>> {
    if depth >= pattern_parts.len() {
        return Some(current_node.clone());
    }

    let pattern_part = pattern_parts[depth];

    if pattern_part == "*" {
        for i in 0..current_node.get_child_count() {
            if let Some(child) = current_node.get_child(i)
                && let Some(result) = find_node_recursive(&child, pattern_parts, depth + 1)
            {
                return Some(result);
            }
        }
    } else if pattern_part.contains('*') {
        for i in 0..current_node.get_child_count() {
            if let Some(child) = current_node.get_child(i) {
                let child_name = child.get_name().to_string();
                if matches_wildcard_pattern(&child_name, pattern_part)
                    && let Some(result) = find_node_recursive(&child, pattern_parts, depth + 1)
                {
                    return Some(result);
                }
            }
        }
    } else {
        if current_node.has_node(pattern_part) {
            let child = current_node.get_node_as::<godot::classes::Node>(pattern_part);
            if let Some(result) = find_node_recursive(&child, pattern_parts, depth + 1) {
                return Some(result);
            }
        }
    }

    None
}

impl GodotResource {
    /// Get the raw Godot resource - you'll need to cast it to the specific type you need
    #[track_caller]
    pub fn get(&self) -> Gd<GodotBaseResource> {
        self.handle.get()
    }

    /// Get the resource handle
    pub fn handle(&self) -> &GodotResourceHandle {
        &self.handle
    }

    /// Try to cast to a specific Godot resource type
    #[track_caller]
    pub fn try_cast<T>(&self) -> Option<Gd<T>>
    where
        T: godot::obj::GodotClass + godot::obj::Inherits<GodotBaseResource>,
    {
        self.get().try_cast().ok()
    }
}

#[cfg(feature = "experimental-threads")]
async fn load(
    &self,
    _reader: &mut dyn Reader,
    _settings: &(),
    load_context: &mut LoadContext<'_>,
) -> Result<Self::Asset, Self::Error> {
    let godot_path = load_context.path().to_string();

    {
        let mut resource_loader = ResourceLoader::singleton();
        let path_gstring = godot::builtin::GString::from(&godot_path);
        resource_loader.load_threaded_request(&path_gstring);
    }

    loop {
        let status = {
            let mut resource_loader = ResourceLoader::singleton();
            let path_gstring = godot::builtin::GString::from(&godot_path);
            resource_loader.load_threaded_get_status(&path_gstring)
        };

        match status {
            ThreadLoadStatus::LOADED => {
                let resource = {
                    let mut resource_loader = ResourceLoader::singleton();
                    let path_gstring = godot::builtin::GString::from(&godot_path);
                    resource_loader.load_threaded_get(&path_gstring)
                };

                match resource {
                    Some(resource) => {
                        let handle = GodotResourceHandle::new(resource);
                        return Ok(GodotResource { handle });
                    }
                    None => {
                        return Err(GodotAssetLoaderError::ResourceLoadFailed(format!(
                            "Failed to get loaded Godot resource: {godot_path}"
                        )));
                    }
                }
            }
            ThreadLoadStatus::FAILED => {
                return Err(GodotAssetLoaderError::ResourceLoadFailed(format!(
                    "Godot ResourceLoader failed to load: {godot_path}"
                )));
            }
            ThreadLoadStatus::INVALID_RESOURCE => {
                return Err(GodotAssetLoaderError::ResourceLoadFailed(format!(
                    "Invalid resource path or corrupted resource: {godot_path}"
                )));
            }
            _ => {
                futures_lite::future::yield_now().await;
            }
        }
    }
}

#[cfg(not(feature = "experimental-threads"))]
async fn load(
    &self,
    _reader: &mut dyn Reader,
    _settings: &(),
    load_context: &mut LoadContext<'_>,
) -> Result<Self::Asset, Self::Error> {
    let godot_path = load_context.path().to_string();
    let path_gstring = godot::builtin::GString::from(&godot_path);

    let mut resource_loader = ResourceLoader::singleton();
    let resource = resource_loader.load(&path_gstring);

    match resource {
        Some(resource) => {
            let handle = GodotResourceHandle::new(resource);
            Ok(GodotResource { handle })
        }
        None => Err(GodotAssetLoaderError::ResourceLoadFailed(format!(
            "Failed to load Godot resource: {godot_path}"
        ))),
    }
}

