fn configure_looping(
    audio_stream: godot::obj::Gd<AudioStream>,
    looping: bool,
) -> godot::obj::Gd<AudioStream> {
    if !looping {
        return audio_stream;
    }

    let audio_stream = audio_stream.duplicate_resource();

    if let Ok(mut ogg_stream) = audio_stream
        .clone()
        .try_cast::<godot::classes::AudioStreamOggVorbis>()
    {
        ogg_stream.set_loop(true);
        ogg_stream.upcast()
    } else if let Ok(mut wav_stream) = audio_stream
        .clone()
        .try_cast::<godot::classes::AudioStreamWav>()
    {
        wav_stream.set_loop_mode(godot::classes::audio_stream_wav::LoopMode::FORWARD);
        wav_stream.upcast()
    } else {
        warn!("Audio stream type doesn't support runtime loop configuration");
        audio_stream
    }
}

fn apply_godot_time_scale(_godot: GodotAccess, mut virt: ResMut<Time<Virtual>>) {
    // set_relative_speed_f64 panics on non-finite/negative input, which tears the app down.
    let raw = godot::classes::Engine::singleton().get_time_scale();
    if raw.is_finite() {
        virt.set_relative_speed_f64(raw.max(0.0));
    }
}

impl Default for DebuggerTransport {
    fn default() -> Self {
        Self::new(|frame| {
            let mut debugger = EngineDebugger::singleton();
            if debugger.is_active() {
                let mut data = VarArray::new();
                data.push(&frame.to_variant());
                debugger.send_message("bevy:rpc", &data);
            }
        })
    }
}

impl Drop for Runtime {
    fn drop(&mut self) {
        if self.capture_registered {
            EngineDebugger::singleton().unregister_message_capture("bevy");
        }
    }
}

fn build(&self, app: &mut App) {
    app.init_resource::<DebuggerConfig>()
        .init_resource::<DebuggerTransport>();
    let (sender, receiver) = channel();
    let endpoint = DebuggerEndpoint(Rc::new(sender));
    let mut debugger = EngineDebugger::singleton();
    let mut capture_registered = false;
    if !debugger.has_capture("bevy") {
        let endpoint = endpoint.clone();
        let capture = Callable::from_fn("bevy_rpc", move |args: &[&Variant]| {
            let Some(message) = args.first().and_then(|arg| arg.try_to::<GString>().ok())
            else {
                return false;
            };
            if message != "rpc" {
                return false;
            }
            let Some(data) = args.get(1).and_then(|arg| arg.try_to::<VarArray>().ok()) else {
                return false;
            };
            if data.len() != 1 {
                return false;
            }
            let Some(frame) = data
                .get(0)
                .and_then(|frame| frame.try_to::<Dictionary>().ok())
            else {
                return false;
            };
            endpoint.submit(frame)
        });
        debugger.register_message_capture("bevy", &capture);
        capture_registered = debugger.has_capture("bevy");
        if capture_registered {
            app.world()
                .resource::<DebuggerTransport>()
                .send(Wire::object([
                    ("jsonrpc", Wire::String("2.0".into())),
                    ("method", Wire::String("godot.ready".into())),
                    ("params", service::debugger_config(app.world())),
                ]));
        }
    } else {
        godot_warn!(
            "godot-bevy: the bevy debugger capture is already registered; this app's endpoint will not receive editor requests"
        );
    }
    app.init_resource::<SummaryChanges>()
        .insert_non_send(endpoint)
        .insert_non_send(Runtime {
            receiver,
            subscription: None,
            capture_registered,
        })
        .add_systems(
            First,
            (service::track_summary_changes, drain)
                .chain()
                .after(SceneTreeSet::Apply)
                .after(TimeSystems)
                .in_set(DebuggerSet::Drain),
        );
}

fn pending_deletion(node: Gd<Node>) -> bool {
    let mut node = Some(node);
    while let Some(current) = node {
        if current.is_queued_for_deletion() || !current.is_inside_tree() {
            return true;
        }
        node = current.get_parent();
    }
    false
}

fn resolve(world: &World, params: &Wire) -> Result<Wire, RpcError> {
    let scene_path = string(params, "scene_path")?;
    let node_path = string(params, "node_path")?;
    if scene_path.is_empty()
        || node_path.is_empty()
        || node_path.starts_with('/')
        || node_path.contains(':')
        || node_path.split('/').any(|segment| segment == "..")
    {
        return Err(RpcError::params(
            "expected an authored scene and relative node path",
        ));
    }
    let tree = Engine::singleton()
        .get_main_loop()
        .and_then(|node| node.try_cast::<SceneTree>().ok())
        .ok_or(InspectionError("scene tree unavailable"))?;
    let root = tree
        .get_root()
        .ok_or(InspectionError("scene tree unavailable"))?;
    let index = world
        .get_resource::<NodeEntityIndex>()
        .ok_or(InspectionError("node index unavailable"))?;
    let mut stack = vec![root.upcast::<Node>()];
    let mut candidates = Vec::new();
    while let Some(node) = stack.pop() {
        if node.get_scene_file_path() == scene_path
            && let Some(target) = node.try_get_node_as::<Node>(node_path)
            && !pending_deletion(target.clone())
            && let Some(entity) = index.get(target.instance_id())
            && world
                .get::<GodotNodeHandle>(entity)
                .is_some_and(|handle| handle.instance_id() == target.instance_id())
        {
            candidates.push(entity);
        }
        stack.extend(node.get_children().iter_shared());
    }
    candidates.sort();
    candidates.dedup();
    Ok(Wire::object([
        (
            "candidates",
            Wire::Array(candidates.into_iter().map(reference).collect()),
        ),
        ("reason", Wire::Null),
    ]))
}

