pub(crate) fn is_excluded_from_mirror(node: &Gd<Node>) -> bool {
    let mut current = Some(node.clone());
    while let Some(n) = current {
        if n.has_meta("_bevy_exclude") {
            return true;
        }
        current = n.get_parent();
    }
    false
}

fn emit_node_class(plan: &ClassPlan, input: &DeriveInput) -> TokenStream2 {
    let class = &plan.godot_class;
    let base = &plan.base;

    let mut exports: Vec<TokenStream2> = Vec::new();
    for m in &plan.primary.fields {
        let ty = m.as_type.clone().or_else(|| primary_field_type(input, m));
        exports.push(export_field(m, ty));
    }
    for c in &plan.companions {
        if !c.generated_exports {
            continue;
        }
        match &c.init {
            ComponentInit::Marker => {}
            ComponentInit::Newtype(m) => exports.push(export_field(m, m.as_type.clone())),
            ComponentInit::Fields(ms) => {
                for m in ms {
                    exports.push(export_field(m, m.as_type.clone()));
                }
            }
        }
    }

    quote! {
        #[derive(godot::prelude::GodotClass)]
        #[class(base = #base, init)]
        pub struct #class {
            base: godot::prelude::Base<godot::classes::#base>,
            #(#exports,)*
        }
    }
}

fn create_direct_path_expr(
    node_path: &syn::LitStr,
    is_optional: bool,
    span: proc_macro2::Span,
) -> syn::Result<TokenStream2> {
    let expr = if is_optional {
        quote_spanned! { span =>
            {
                let base_node = &node;
                base_node.has_node(#node_path)
                    .then(|| {
                        let node_ref = base_node.try_get_node_as::<godot::classes::Node>(#node_path)
                            .ok_or_else(|| godot_bevy::node_tree_view::NodeTreeViewError::NodeNotFound(
                                #node_path.to_string()
                            ))?;
                        godot_bevy::interop::GodotNodeHandle::from_instance_id(node_ref.instance_id())
                    })
            }
        }
    } else {
        quote_spanned! { span =>
            {
                let base_node = &node;
                let node_ref = base_node.try_get_node_as::<godot::classes::Node>(#node_path)
                    .ok_or_else(|| godot_bevy::node_tree_view::NodeTreeViewError::NodeNotFound(
                        #node_path.to_string()
                    ))?;
                godot_bevy::interop::GodotNodeHandle::from_instance_id(node_ref.instance_id())
            }
        }
    };
    Ok(expr)
}

