#[godot_api]
impl CaptureHook {
    #[func]
    fn after_draw(&mut self) {
        if !std::mem::take(&mut self.pending_draw) {
            return;
        }
        let Some(mut state) = self.state.take() else {
            return;
        };
        let callback = self.to_gd().callable("after_draw");
        let mut server = RenderingServer::singleton();
        server.disconnect("frame_post_draw", &callback);
        match state.finish_frame() {
            Ok(false) => {
                self.state = Some(state);
                server.connect("frame_post_draw", &callback);
            }
            Ok(true) => {}
            Err(error) => fail(error),
        }
    }

    #[func]
    fn before_physics(&mut self) {
        self.before_callback(true);
    }

    #[func]
    fn before_process(&mut self) {
        self.before_callback(false);
    }
}

fn scene_conditions(manifest: &CaptureManifest) -> bool {
    let Some(scene) = tree().get_current_scene() else {
        return false;
    };
    scene.is_node_ready()
        && manifest.settle.nodes.iter().all(|path| {
            scene
                .get_node_or_null(path.as_str())
                .is_some_and(|node| node.is_node_ready())
        })
        && manifest
            .settle
            .classes
            .iter()
            .all(|class| ClassDb::singleton().class_exists(class.as_str()))
}

fn capture(
    &self,
    checkpoint: &Checkpoint,
    scene: &Gd<Node>,
    elapsed: u64,
    fixed_elapsed: u64,
) -> Result<Value, String> {
    let drawn = Rc::new(Cell::new(false));
    let observed = drawn.clone();
    let callback = Callable::from_fn("capture_post_draw", move |_| observed.set(true));
    let mut server = RenderingServer::singleton();
    let connected = server.connect("frame_post_draw", &callback);
    if connected != godot::global::Error::OK {
        return Err(format!("cannot observe frame_post_draw: {connected:?}"));
    }
    // The idle editor does not redraw without input.
    server.force_draw();
    server.disconnect("frame_post_draw", &callback);
    if !drawn.get() {
        return Err("force_draw did not complete frame_post_draw".into());
    }
    let root = tree().get_root().ok_or("missing root viewport")?;
    let image = root
        .get_texture()
        .and_then(|texture| texture.get_image())
        .ok_or("missing viewport image")?;
    if [image.get_width() as u32, image.get_height() as u32] != self.manifest.viewport {
        return Err("viewport image has the wrong dimensions".into());
    }
    let path = self.frame_file(checkpoint.frame, "png");
    let temporary = path.with_extension("png.tmp");
    let error = image.save_png(temporary.to_str().ok_or("non-UTF-8 PNG path")?);
    if error != godot::global::Error::OK {
        return Err(format!("PNG capture: {error:?}"));
    }
    std::fs::rename(temporary, path).map_err(|error| error.to_string())?;
    let nodes: Vec<Value> = checkpoint
        .nodes
        .iter()
        .map(|expected| {
            let node = scene.get_node_or_null(expected.path.as_str());
            let position = node.as_ref().and_then(|node| {
                if let Ok(node) = node.clone().try_cast::<Node2D>() {
                    let position = node.get_position();
                    Some([position.x, position.y])
                } else if let Ok(node) = node.clone().try_cast::<Control>() {
                    let position = node.get_position();
                    Some([position.x, position.y])
                } else {
                    None
                }
            });
            let visible = node
                .and_then(|node| node.try_cast::<godot::classes::CanvasItem>().ok())
                .map(|node| node.is_visible_in_tree());
            json!({"path": expected.path, "position": position, "visible": visible})
        })
        .collect();
    let mut regions = Vec::new();
    for region in &checkpoint.regions {
        let [x, y, width, height] = region.rect;
        if width == 0
            || height == 0
            || u64::from(x) + u64::from(width) > u64::from(self.manifest.viewport[0])
            || u64::from(y) + u64::from(height) > u64::from(self.manifest.viewport[1])
        {
            return Err(format!("region {} is outside the viewport", region.name));
        }
        let pixels = (y..y + height).flat_map(|row| {
            let image = &image;
            (x..x + width).map(move |column| {
                let colour = image.get_pixel(column as i32, row as i32);
                [colour.r, colour.g, colour.b]
                    .map(|value| (value.clamp(0.0, 1.0) * 255.0).round() as u8)
            })
        });
        let (fraction, dominant) = pixels::summarize(
            pixels,
            region.non_blank.background,
            region.non_blank.tolerance,
        );
        regions.push(json!({
            "name": region.name, "rect": region.rect,
            "non_blank_fraction": fraction, "dominant_colour": dominant,
        }));
    }
    Ok(json!({
        "version": godot_bevy_capture_version(), "scenario": self.manifest.scenario, "scene": self.scene_path,
        "frame": checkpoint.frame, "viewport": self.manifest.viewport,
        "physics_ticks": self.physics_ticks, "virtual_elapsed_ns": elapsed,
        "fixed_elapsed_ns": fixed_elapsed, "fixed_step_ns": fixed_step().as_nanos() as u64,

#[derive(Clone)]
pub struct TestContext {
    pub scene_tree: godot::obj::Gd<godot::classes::Node>,
}

pub fn run_all_tests(&mut self, scene_tree: Gd<Node>) {
    println!("\n{FMT_CYAN_BOLD}Run{FMT_END} godot-bevy integration tests...");
    install_panic_capture_hook();

    let ctx = TestContext { scene_tree };
    let report_path = match report_path_from_env() {
        Ok(path) => path,
        Err(error) => {
            eprintln!("{FMT_RED}Configuration error: {error}{FMT_END}");
            terminate(&ctx, 2);
            return;
        }
    };

    let all_tests = self.collect_registered_tests();
    let config = match TestConfig::from_env() {
        Ok(config) => config,
        Err(error) => {
            let fallback = TestConfig::fallback();
            let selection = Selection {
                registered: all_tests.len(),
                selected: 0,
                focus_run: all_tests.iter().any(|test| test.focused),
                filter: std::env::var("ITEST_FILTER").ok(),
                patterns: Vec::new(),
            };
            finish_configuration_error(&ctx, &fallback, selection, report_path, error);
            return;
        }
    };

    let collected = select_registered_tests(all_tests, config.filter.as_ref());
    print_test_configuration(&config, &collected);

    let selection = Selection {
        registered: collected.registered,
        selected: collected.tests.len(),
        focus_run: collected.focus_run,
        filter: config
            .filter
            .as_ref()
            .map(|filter| filter.normalized.clone()),
        patterns: config
            .filter
            .as_ref()
            .map(|filter| filter.patterns.clone())
            .unwrap_or_default(),
    };
    let mut report = TestReport::new(&config, selection, godot_version());
    let writer = ReportWriter::new(config.json_path.clone());

    if let Err(error) = writer.write(&report) {
        eprintln!("{FMT_RED}Failed to initialize integration test report: {error}{FMT_END}");
        terminate(&ctx, 2);
        return;
    }

    if collected.focus_run && config.deny_focus {
        report.finish_error(
            "configuration",
            "focused integration tests are forbidden by ITEST_DENY_FOCUS".to_string(),
        );
        finish_early_report(&ctx, &writer, &report);
        return;
    }

    if collected.tests.is_empty() {
        report.finish_error(
            "configuration",
            "integration test selection matched zero tests".to_string(),
        );
        finish_early_report(&ctx, &writer, &report);
        return;
    }

    let state = Rc::new(RefCell::new(TestRunState {
        tests: collected.tests,
        ctx,
        config,
        report,
        writer,
        started: Instant::now(),
        test_index: 0,
        current_attempts: Vec::new(),
    }));
    run_next_attempt(state);
}

fn godot_version() -> String {
    let version = Engine::singleton().get_version_info();
    let major: i64 = version.at("major").to();
    let minor: i64 = version.at("minor").to();
    let patch: i64 = version.at("patch").to();
    let status: godot::builtin::GString = version.at("status").to();
    format!("{major}.{minor}.{patch}.{status}")
}

fn output_json_results(
    results: Vec<(&str, Duration, Duration)>,
    selection: &BenchmarkSelection,
    profile_run_id: Option<&str>,
) -> Result<(), String> {
    use std::collections::HashMap;

    let mut benchmarks = HashMap::new();

    for (name, min, median) in results {
        let mut entry = HashMap::new();
        entry.insert("min_ns", min.as_nanos().to_string());
        entry.insert("median_ns", median.as_nanos().to_string());
        entry.insert("min_display", format!("{min:.2?}"));
        entry.insert("median_display", format!("{median:.2?}"));

        benchmarks.insert(name.to_string(), entry);
    }

    let mut output = serde_json::json!({
        "benchmarks": benchmarks,
        "timestamp": chrono::Utc::now().to_rfc3339(),
        "environment": {
            "rust_debug": cfg!(debug_assertions),
            "godot_debug": Os::singleton().is_debug_build(),
        }
    });

    if let Some(run_id) = profile_run_id {
        let (mode, requested, patterns) = match &selection.selector {
            BenchmarkSelector::Exact(exact) => ("exact", exact.clone(), Vec::new()),
            BenchmarkSelector::Filter(filter) => {
                ("filter", filter.normalized.clone(), filter.patterns.clone())
            }
            BenchmarkSelector::All => {
                return Err("profile benchmark selection is missing".to_string());
            }
        };
        let selected: Vec<&str> = selection
            .benchmarks
            .iter()
            .map(|benchmark| benchmark.name)
            .collect();
        let repetitions: serde_json::Map<String, serde_json::Value> = selection
            .benchmarks
            .iter()
            .map(|benchmark| {
                (
                    benchmark.name.to_string(),
                    serde_json::Value::from(benchmark.repetitions),
                )
            })
            .collect();

        output["evidence_kind"] = serde_json::json!("profiled-benchmark-workload");
        output["benchmark_compatible"] = serde_json::json!(false);
        output["disclosure"] = serde_json::json!("INSTRUMENTED PROFILE — NOT BENCHMARK RESULTS");
        output["profile_run_id"] = serde_json::json!(run_id);
        output["selection"] = serde_json::json!({
            "mode": mode,
            "requested": requested,
            "patterns": patterns,
            "registered": selection.registered,
            "selected": selected.len(),
            "benchmarks": selected,
        });
        output["profiling"] = serde_json::json!({
            "warmup_iterations": bencher::WARMUP_RUNS,
            "sample_iterations": bencher::TEST_RUNS,
            "inner_repetitions": repetitions,
        });
    }

    if let Ok(path) = std::env::var("BENCHMARK_JSON_PATH") {
        match std::fs::File::create(&path) {
            Ok(file) => {
                if let Err(error) = serde_json::to_writer_pretty(file, &output)
                    && profile_run_id.is_some()
                {
                    return Err(format!("failed to write {path}: {error}"));
                }
            }
            Err(error) if profile_run_id.is_some() => {
                return Err(format!("failed to create {path}: {error}"));
            }
            Err(_) => {}
        }
    }

    println!("===BENCHMARK_JSON_START===");
    println!(
        "{}",
        serde_json::to_string_pretty(&output).unwrap_or_default()
    );
    println!("===BENCHMARK_JSON_END===");
    Ok(())
}

