        for protected in [false, true] {
            let mut app = TestApp::new(&ctx_clone, |_app| {}).await;
            let (mut parent, _) = app.add_node::<Node>("ReentryParent").await;
            let node = Node::new_alloc();
            let node_id = node.instance_id();
