            let old_entity = app.entity_for_node(node_id).expect("initial entity");
            app.with_world_mut(|world| {
                world.entity_mut(old_entity).insert(SceneTreePayload(42));
                if protected {
                    world.entity_mut(old_entity).insert(ProtectedNodeEntity);
                }
            });

