            .await;
            let (mut parent, parent_entity) = app.add_node::<Node>("NoCascadeParent").await;
            let parent_id = parent.instance_id();
            let child = Node::new_alloc();
            let child_id = child.instance_id();
            parent.add_child(&child);
            settle_scene_tree(&app).await;
            let child_entity = app.entity_for_node(child_id).expect("child entity");
            app.with_world_mut(|world| {
                world.entity_mut(child_entity).insert(SceneTreePayload(42));
                if protected_child {
                    world.entity_mut(child_entity).insert(ProtectedNodeEntity);
                }
                world.entity_mut(parent_entity).despawn();
                assert!(
                    world.get_entity(child_entity).is_ok(),
                    "ECS cascade must be disabled"
                );
            });
            assert!(parent.is_queued_for_deletion());
            settle_scene_tree(&app).await;

            assert!(!parent_id.lookup_validity());
            assert!(!child_id.lookup_validity());
            assert_unmirrored(&app, parent_id, parent_entity, false);
            assert_unmirrored(&app, child_id, child_entity, protected_child);
            app.cleanup().await;
        }
    })
}

fn find_bevy_app_node(
    scene_tree_node: &Gd<godot::classes::Node>,
) -> Option<Gd<godot::classes::Node>> {
    let tree = scene_tree_node.get_tree();
    let root = tree.get_root()?;
    root.try_get_node_as::<godot::classes::Node>("BevyAppSingleton")
}

fn count_children_with_prefix(parent: &Gd<godot::classes::Node>, prefix: &str) -> usize {
    let mut count = 0;
    for i in 0..parent.get_child_count() {
        if let Some(child) = parent.get_child(i)
            && child.get_name().to_string().starts_with(prefix)
        {
            count += 1;
        }
    }
    count
}

struct LocalApp {
    node: Gd<BevyApp>,
    counts: Arc<Counts>,
}

impl LocalApp {
    fn new(parent: &mut Gd<Node>, setup: impl Fn(&mut App) + Send + Sync + 'static) -> Self {
        let mut node = BevyApp::new_alloc();
        node.set_meta("_bevy_exclude", &true.to_variant());
        let counts = Arc::new(Counts::default());
        let observed = counts.clone();
        node.bind_mut().set_instance_init_func(Box::new(move |app| {
            count_app(app, &observed);
            setup(app);
        }));
        parent.add_child(&node);
        assert_eq!(counts.inits.load(Ordering::SeqCst), 1);
        Self { node, counts }
    }

    fn assert_counts(&self, inits: usize, startups: usize, terminal: usize, drops: usize) {
        assert_eq!(
            self.counts.inits.load(Ordering::SeqCst),
            inits,
            "initializations"
        );
        assert_eq!(
            self.counts.startups.load(Ordering::SeqCst),
            startups,
            "Startup runs"
        );
        assert_eq!(
            self.counts.terminal.load(Ordering::SeqCst),
            terminal,
            "terminal passes"
        );
        assert_eq!(
            self.counts.drops.load(Ordering::SeqCst),
            drops,
            "resource drops"
        );
    }
}

async fn preserve_world(ctx: TestContext, reparent: bool, request_ready: bool) {
    let mut clock = TestApp::new(&ctx, |_| {}).await;
    let mut probe = LocalApp::new(&mut ctx.scene_tree.clone(), |_| {});
    clock.updates(3).await;
    let entity = probe
        .node
        .bind_mut()
        .get_app_mut()
        .unwrap()
        .world_mut()
        .spawn(Unrelated(42))
        .id();
    if request_ready {
        probe.node.request_ready();
    }
    let mut other = Node::new_alloc();
    ctx.scene_tree.clone().add_child(&other);
    if reparent {
        probe.node.reparent(&other);
    } else {
        ctx.scene_tree.clone().remove_child(&probe.node);
        clock.updates(3).await;
        probe.assert_counts(1, 1, 0, 0);
        other.add_child(&probe.node);
    }
    clock.updates(3).await;
    probe.assert_counts(1, 1, 0, 0);
    {
        let binding = probe.node.bind();
        let world = binding.get_app().expect("world survives move").world();
        assert!(Arc::ptr_eq(
            &world.resource::<DropSentinel>().0,
            &probe.counts
        ));
        assert_eq!(world.get::<Unrelated>(entity).unwrap().0, 42);
    }
    other.free();
    probe.assert_counts(1, 1, 1, 1);
    clock.cleanup().await;
}

async fn system_shutdown(ctx: TestContext, fixed: bool) {
    let mut clock = TestApp::new(&ctx, |_| {}).await;
    for ancestor in [false, true] {
        let mut parent = Node::new_alloc();
        ctx.scene_tree.clone().add_child(&parent);
        let mut probe = LocalApp::new(&mut parent, |_| {});
        clock.updates(3).await;
        let id = probe.node.instance_id();
        let actions = Arc::new(AtomicUsize::new(0));
        let observed = actions.clone();
        let counts = probe.counts.clone();
        let system = move |_: GodotAccess, mut done: Local<bool>| {
            if *done {
                return;
            }
            *done = true;
            let mut node = Gd::<Node>::from_instance_id(id);
            let mut parent = node.get_parent().unwrap();
            let panics = Arc::new(AtomicUsize::new(0));
            let captured = panics.clone();
            let hook = std::panic::take_hook();
            std::panic::set_hook(Box::new(move |_| {
                captured.fetch_add(1, Ordering::SeqCst);
            }));
            parent.remove_child(&node);
            parent.add_child(&node);
            std::panic::set_hook(hook);
            assert_eq!(
                panics.load(Ordering::SeqCst),
                0,
                "tree callbacks must not reborrow the host"
            );
            assert_eq!(
                counts.terminal.load(Ordering::SeqCst),
                0,
                "removal must not end the world"
            );
            observed.fetch_add(1, Ordering::SeqCst);
            if ancestor {
                parent.queue_free();
            } else {
                node.queue_free();
            }
        };
        {
            let mut binding = probe.node.bind_mut();
            let app = binding.get_app_mut().unwrap();
            if fixed {
                app.add_systems(FixedUpdate, system);
            } else {
                app.add_systems(Update, system);
            }
        }
        clock.updates(4).await;
        assert!(godot_bevy::app::drain_test_frame_panics().is_empty());
        assert_eq!(actions.load(Ordering::SeqCst), 1);
        assert!(!probe.node.is_instance_valid());
        probe.assert_counts(1, 1, 1, 1);
        if parent.is_instance_valid() {
            parent.free();
        }
    }
    clock.cleanup().await;
}

#[itest(async)]
fn test_connect_object_signal(ctx: &TestContext) -> godot::task::TaskHandle {
    let ctx_clone = ctx.clone();

    godot::task::spawn(async move {
        #[derive(Resource, Default)]
        struct SignalReceived(bool);

        let mut app = TestApp::new(&ctx_clone, |app| {
            app.add_plugins(GodotSignalsPlugin::<NodeAdded>::default());
            app.init_resource::<SignalReceived>();
            app.add_observer(
                |_trigger: On<NodeAdded>, mut received: ResMut<SignalReceived>| {
