#[derive(GodotClass)]
#[class(base = RefCounted, init)]
pub struct FileDragMonitor {
    base: Base<RefCounted>,
    hook: Option<platform::Hook>,
}

#[godot_api]
impl FileDragMonitor {
    /// Files were dragged into the window
    #[signal]
    fn drag_entered();

    /// The files were dragged out of the window again, the drag was canceled, or they
    /// were dropped (just before the window's `files_dropped`)
    #[signal]
    fn drag_exited();

    /// Starts watching drags over [param window], until the monitor is freed. False when
    /// this platform or display server can't tell, and drops work as before.
    #[func]
    fn attach(&mut self, window: Gd<Window>) -> bool {
        self.hook = platform::Hook::new(self.to_gd().instance_id(), window);
        if self.hook.is_some() && platform::Hook::POLLS {
            let tree = Engine::singleton()
                .get_main_loop()
                .map(|main| main.cast::<SceneTree>());
            if let Some(mut tree) = tree {
                tree.connect("process_frame", &self.to_gd().callable("poll"));
            }
        }
        self.hook.is_some()
    }

    /// Reads what the platform said, each frame where it has to be asked (X11)
    #[func]
    fn poll(&mut self) {
        if let Some(hook) = &mut self.hook {
            hook.poll();
        }
    }
}

impl Hook {
    /// Drags are told as they happen, without polling
    pub const POLLS: bool = false;

    pub fn poll(&mut self) {}

    /// Watches the content view of `window`. None when it has none, like when running
    /// headless.
    pub fn new(monitor: InstanceId, window: Gd<Window>) -> Option<Hook> {
        let view = DisplayServer::singleton()
            .window_get_native_handle_ex(HandleType::WINDOW_VIEW)
            .window_id(window.get_window_id())
            .done() as usize;
        if view == 0 {
            return None;
        }
        let class = unsafe { (*(view as *const AnyObject)).class() };
        ORIGINALS.get_or_init(|| unsafe { install(class) });
        MONITORS.with_borrow_mut(|monitors| monitors.insert(view, monitor));
        Some(Hook { view })
    }
}

impl Hook {
    /// Drags are told as they happen, without polling
    pub const POLLS: bool = false;

    pub fn poll(&mut self) {}

    pub fn new(_monitor: InstanceId, _window: Gd<Window>) -> Option<Hook> {
        None
    }
}

impl Hook {
    /// Drags are told as they happen, without polling
    pub const POLLS: bool = false;

    pub fn poll(&mut self) {}

    /// Replaces the drop target of `window`. None when it has no native window, like when
    /// running headless.
    pub fn new(monitor: InstanceId, window: Gd<Window>) -> Option<Hook> {
        let handle = DisplayServer::singleton()
            .window_get_native_handle_ex(HandleType::WINDOW_HANDLE)
            .window_id(window.get_window_id())
            .done();
        if handle == 0 {
            return None;
        }
        let hwnd = HWND(handle as *mut c_void);
        let target: IDropTarget = DropTarget::new(monitor, window.instance_id()).into();
        unsafe {
            // Godot's isn't there when its window has no drop callback yet
            let _ = RevokeDragDrop(hwnd);
            if let Err(error) = RegisterDragDrop(hwnd, &target) {
                godot_error!("Could not watch file drags: {error}");
                return None;
            }
        }
        Some(Hook {
            hwnd,
            _target: target,
        })
    }
}

pub fn new(monitor: InstanceId, window: Gd<Window>) -> Option<Hook> {
    let server = DisplayServer::singleton();
    if server.get_name() != "X11" {
        return None;
    }
    let target = server
        .window_get_native_handle_ex(HandleType::WINDOW_HANDLE)
        .window_id(window.get_window_id())
        .done() as xproto::Window;
    if target == 0 {
        return None;
    }
    match Hook::connect(monitor, target) {
        Ok(hook) => Some(hook),
        Err(error) => {
            godot_error!("Could not watch file drags: {error}");
            None
        }
    }
}

