pub struct WaveProp {
    /// Full box extent in meters — a magnitude: a negative reading folds to
    /// its absolute value at the knob ([`SignFold`]).
    #[export(range = (0.05, 20.0, 0.05, or_greater, suffix = " m"))]
    #[var(get = get_size, set = set_size)]
