#[godot_api]
impl WaveProp {
    /// The size knob reshapes the prop live, mesh and collider together —
    /// on the knob's magnitude, so a minus sign cannot leave the mesh
    /// reshaped and the collider refusing to follow.
    #[func]
    fn set_size(&mut self, size: Vector3) {
        self.size = self.fold.vector("size", size);
        let size = self.size;
        if let Some(mesh) = self.mesh.as_mut() {
            render::paint::resize_box_surface(mesh, size, BOX_ORDINALS);
        }
        if let Some(shape) = self.shape.as_mut() {
            shape.set_size(size);
        }
        let named = self.base().is_inside_tree().then(|| self.base().get_name());
        self.fold.say(named);
    }

    #[func]
    fn get_size(&self) -> Vector3 {
        self.size
    }

    /// The id this prop carries — the engine-facing read-back of its own
    /// [`Skin`], off the mesh's own `CUSTOM0`.
    #[func]
    fn oid(&self) -> f64 {
        self.skin.oid()
    }

    /// The engine-facing read-back of
    /// [`IStaticBody3D::get_configuration_warnings`] — the GDVIRTUAL a
    /// script cannot reach directly; see [`Self::oid`] for the same
    /// disambiguation this forwarder needs.
    #[func]
    fn get_configuration_warnings(&self) -> PackedStringArray {
        IStaticBody3D::get_configuration_warnings(self)
    }

    /// See the field: recomputed, never stored, so it cannot go stale.
    #[func]
    fn get_stops_sound(&self) -> bool {
        matches!(
            solid::barrier_of(&WaveSolid::world_shape(self)),
            level_plan::Barrier::StopsSound
        )
    }

    /// See the field.
    #[func]
    fn get_sound_verdict(&self) -> GString {
        GString::from(
            level_plan::barrier_sentence(solid::barrier_of(&WaveSolid::world_shape(self))).as_str(),
        )
    }
}

