#[godot_api]
impl INode3D for WaveRun {
    fn ready(&mut self) {
        self.absorb_planar_transform();
        self.rebuild();
        self.base_mut().set_notify_local_transform(true);
    }

    fn on_notification(&mut self, what: Node3DNotification) {
        if matches!(what, Node3DNotification::LOCAL_TRANSFORM_CHANGED)
            && self.base().get_transform() != Transform3D::IDENTITY
        {
            if !self.authored_geometry_edit_is_live() {
                self.base_mut().set_transform(Transform3D::IDENTITY);
                return;
            }
            self.absorb_planar_transform();
            self.rebuild();
        }
    }

    fn get_configuration_warnings(&self) -> PackedStringArray {
        let mut warnings = self.own_warnings.clone();
        let level_warnings = warnings_from_level(&self.base().clone().upcast::<Node>());
        for warning in level_warnings.as_slice() {
            warnings.push(warning);
        }
        warnings
    }
}

#[derive(GodotClass)]
#[class(init, base=Control)]
pub struct SettingsFrame {
    /// The box to draw around — the rows' container, in this Control's
    /// own coordinates.
    #[var]
    content: Option<Gd<Control>>,
    /// How far the rule stands off the rows, in pixels.
    #[var]
    #[init(val = 24.0)]
    padding: f32,
    base: Base<Control>,
}

#[godot_api]
impl IControl for SettingsFrame {
    fn draw(&mut self) {
        let Some(content) = self.content.clone() else {
            return; // nothing to frame: draw nothing rather than a stray box
        };
        let rect = content.get_rect();
        if rect.size.x <= 0.0 || rect.size.y <= 0.0 {
            // the container has not been laid out yet; drawing now would
            // put a box at the origin around nothing. `item_rect_changed`
            // brings us back the moment it has a real rect.
            return;
        }
        let box_rect = rect.grow(self.padding);
        self.base_mut()
            .draw_rect_ex(box_rect, Color::WHITE)
            .filled(false)
            .width(RULE)
            .done();
    }
}

