pub(crate) fn clear_limbs<C>(node: &mut C, names: &[&str])
where
    C: WithBaseField,
    C::Base: Inherits<Node>,
{
    let base = node.base_mut();
    let mut owner: Gd<Node> = Gd::clone(&base).upcast();
    let stale: Vec<Gd<Node>> = owner
        .get_children()
        .iter_shared()
        .filter(|child| names.iter().any(|name| child.get_name() == *name))
        .collect();
    for limb in stale {
        owner.remove_child(&limb);
        limb.free();
    }
    drop(base);
}

pub trait WaveSolid {
    /// Take the world skin — the data-writing material the level deals to
    /// everything that renders at real depth.
    fn set_material(&mut self, mat: &Gd<Material>);

    /// This solid's geometry in WORLD space — the one shape the derive-time
    /// paint pass builds faces from and the occlusion-admission walk
    /// measures. Any node transform is already folded in, so `render::faces`
    /// never fights a basis stack.
    ///
    /// On the TRAIT rather than on each class because the level's two walks
    /// over `census.solids` are class-agnostic by construction, and a
    /// hand-written `try_cast` list is a second roster to keep in step. Both
    /// walks used to carry one, each falling through to a silent `None`, so
    /// a fifth solid class would have drawn, collided and reflected echoes
    /// while never taking a superface label and never entering the occluder
    /// table — with no fault, no warning and no failing test.
    fn world_shape(&self) -> render::Shape;

    /// Bake the paint pass's chosen per-face labels into this solid's own
    /// mesh `CUSTOM0`, positionally by face ordinal. Same reason as
    /// [`Self::world_shape`]: the level colours whatever the census found.
    fn paint(&mut self, labels_by_ordinal: &[f32]);
}

pub(crate) fn warnings_from_level(node: &Gd<Node>) -> PackedStringArray {
    let mut cursor = node.get_parent();
    while let Some(parent) = cursor {
        if let Ok(level) = parent.clone().try_cast::<WaveLevel>() {
            return level.bind().faults_for(node);
        }
        cursor = parent.get_parent();
    }
    PackedStringArray::new()
}

#[derive(Default)]
pub(crate) struct Skin {
    limb: Option<Gd<MeshInstance3D>>,
    mat: Option<Gd<Material>>,
}

impl Skin {
    /// Remember the limb a class just built, and dress it if a material
    /// has already arrived.
    pub(crate) fn adopt(&mut self, limb: Gd<MeshInstance3D>) {
        self.limb = Some(limb);
        if let Some(mat) = self.mat.clone() {
            self.wear(&mat);
        }
    }

    /// The limb this solid draws itself with, for a class that must move it
    /// (a column and a wedge ride half their height above their node).
    pub(crate) fn limb(&mut self) -> Option<&mut Gd<MeshInstance3D>> {
        self.limb.as_mut()
    }

    /// The material this solid was handed, if any — what a class passes
    /// into its builder so a limb is born already dressed.
    pub(crate) fn material(&self) -> Option<&Gd<Material>> {
        self.mat.as_ref()
    }

    /// Take a material, dressing the limb if it is already built. Injection
    /// may land on either side of `_ready`, and both orders must work: the
    /// level injects before the tree, but a test may build first.
    pub(crate) fn set_material(&mut self, mat: &Gd<Material>) {
        self.mat = Some(mat.clone());
        self.wear(mat);
    }

    /// The id the limb carries right now — the one source of truth, read
    /// straight off the limb's own mesh (`mesh_first_label`) rather than
    /// mirrored or pushed through any per-instance uniform: `CUSTOM0` is
    /// what the shader itself reads for G, so this is exactly that value.
    pub(crate) fn oid(&self) -> f64 {
        self.limb
            .as_ref()
            .and_then(mesh_first_label)
            .unwrap_or(oid_palette::NO_OID)
    }

    fn wear(&mut self, mat: &Gd<Material>) {
        if let Some(limb) = self.limb.as_mut() {
            limb.set_material_override(mat);
        }
    }
}

pub(crate) fn mesh_first_label(limb: &Gd<MeshInstance3D>) -> Option<f64> {
    let mesh = limb.get_mesh()?;
    if mesh.get_surface_count() == 0 {
        return None;
    }
    let arrays = mesh.surface_get_arrays(0);
    let custom = arrays.get(ArrayType::CUSTOM0.ord() as usize)?;
    let custom = custom.try_to::<PackedFloat32Array>().ok()?;
    custom.get(0).map(f64::from)
}

pub(crate) struct BuiltBody {
    /// The outline mesh limb.
    pub(crate) skin: Gd<MeshInstance3D>,
    /// The collider limb.
    pub(crate) collider: Gd<CollisionShape3D>,
}

pub(crate) fn build_body(
    mesh: &Gd<Mesh>,
    shape: &Gd<Shape3D>,
    lift: Vector3,
    mat: Option<&Gd<Material>>,
) -> BuiltBody {
    let mut skin = MeshInstance3D::new_alloc();
    skin.set_name(SKIN_NAME);
    skin.set_mesh(mesh);
    skin.set_position(lift);
    if let Some(mat) = mat {
        skin.set_material_override(mat);
    }
    let mut collider = CollisionShape3D::new_alloc();
    collider.set_name(COLLIDER_NAME);
    collider.set_shape(shape);
    collider.set_position(lift);
    BuiltBody { skin, collider }
}

pub(crate) struct BuiltBox {
    /// The outline mesh limb.
    pub(crate) skin: Gd<MeshInstance3D>,
    /// The skin's box mesh, kept for live reshaping.
    pub(crate) mesh: Gd<ArrayMesh>,
    /// The collider limb.
    pub(crate) collider: Gd<CollisionShape3D>,
    /// The collider's box shape, kept for live reshaping.
    pub(crate) shape: Gd<BoxShape3D>,
}

pub(crate) fn paint_solid(
    mesh: Option<&mut Gd<ArrayMesh>>,
    kind: render::paint::ShapeKind,
    labels_by_ordinal: &[f32],
) {
    if let Some(mesh) = mesh {
        render::paint::relabel(mesh, kind, labels_by_ordinal);
    }
}

pub(crate) fn build_box(size: Vector3, lift: Vector3, mat: Option<&Gd<Material>>) -> BuiltBox {
    let mesh = render::paint::labelled_box(size, Vector3::ZERO, BOX_ORDINALS);
    let mut shape = BoxShape3D::new_gd();
    shape.set_size(size);
    let built = build_body(
        &mesh.clone().upcast::<Mesh>(),
        &shape.clone().upcast::<Shape3D>(),
        lift,
        mat,
    );
    BuiltBox {
        skin: built.skin,
        mesh,
        collider: built.collider,
        shape,
    }
}

pub trait SoundSource {
    /// Where this source's waves are born, in world space, right now — the
    /// fan's spinning hub as the head sweeps, the radio's speaker cone. The
    /// level also measures the walls between the eye and THIS point to
    /// decide how muffled the source's image is.
    fn hub(&self) -> Vector3;

    /// This source's acoustic identity: volume, cadence, speed, spread.
    /// Read from the node's designer knobs, so a fan turned down in the
    /// Inspector answers differently.
    fn voice(&self) -> Voice;

    /// How many semantic limb roles this source paints. A fan has shell and
    /// moving roles; a radio has case and fascia roles. They enter the level's
    /// colourable separation graph as distinct classes so two touching
    /// same-class sources cannot melt merely because their role names match.
    fn role_count(&self) -> u8;

    /// Bake the level's chosen label for each semantic role back onto every
    /// limb in that role. Missing or non-finite labels retain that role's
    /// prior assignment (or its preview default before any assignment); extra
    /// labels are retained for a later generation but paint no absent limb.
    fn set_role_labels(&mut self, labels: &[f64]);

    /// Read one role's current label from an actual limb mesh. `None` when
    /// the role has no built limb or the mesh has no readable CUSTOM0 data.
    fn role_label(&self, role: usize) -> Option<f64>;

    /// The single injection point: the wave pool every sound enters and the
    /// acoustic-image skin every limb renders through. Called by the level
    /// BEFORE the source enters the tree, because a source that cannot
    /// sound or be seen must refuse to build rather than fail later.
    fn inject(&mut self, pulses: Gd<RefCounted>, skin: Gd<Material>);

    /// Advance this source's clockwork to `t` and emit whatever waves fall
    /// due. Driven by the level with the SIMULATED clock, like every
    /// animated thing, so movie-maker runs and time scaling stay correct.
    fn advance(&mut self, t: f64);

    /// How far this source's MOVING parts swing beyond the pose the level
    /// samples when it colours the world, in metres on the horizontal axes.
    ///
    /// The level connects every source-role class to the world and source
    /// roles touching this swept box. For a source that swings, one sampled
    /// pose is too small: a prop just outside it could meet the source for
    /// part of every cycle while a single-pose seam check reported green.
    /// Zero for a source that does not move.
    fn sweep_margin(&self) -> f64 {
        0.0
    }

    /// When this source's next wave is due, on the same simulated clock
    /// [`Self::advance`] is driven with — `None` when no appointment is
    /// being kept (a source that never built, or one whose cadence knob
    /// cannot fire). Read-only; nothing in the game asks, and the debug
    /// observer would otherwise have to guess a source's clockwork from its
    /// interval and the wall clock.
    ///
    /// The default answers `None` rather than inventing a date, so a source
    /// class that keeps its clock somewhere other than a [`SourceRig`] is
    /// honest about it until it says otherwise.
    fn next_emit(&self) -> Option<f64> {
        None
    }

    /// Set how strongly this source's standing image is felt: its own
    /// volume and the muffle of the walls between it and the eye, computed
    /// once per frame by the level and delivered SEPARATELY, as
    /// [`VOLUME_PARAM`] and [`MUFFLE_PARAM`].
    ///
    /// Separately because their product is not what the skin needs. A
    /// single pre-multiplied number can only enter the fragment as a floor
    /// under the source's own wave reveal, and that floor always loses: a
    /// source's hub is unwalled from its own body by construction, so the
    /// wave washing it is near full strength however many walls stand
    /// between it and the player. Kept apart, t

#[derive(Default)]
pub(crate) struct SourceRig {
    limbs: Vec<(Gd<MeshInstance3D>, usize)>,
    assigned_labels: Vec<Option<f64>>,
    cadence: Cadence,
}

pub(crate) fn limb(
    &mut self,
    parent: &mut Gd<Node3D>,
    mesh: &Gd<godot::classes::Mesh>,
    role: usize,
    at: Vector3,
    rotation: Vector3,
    skin: Option<&Gd<Material>>,
) -> Gd<MeshInstance3D> {
    let mut mi = MeshInstance3D::new_alloc();
    mi.set_mesh(mesh);
    if let Some(label) = self.assigned_labels.get(role).and_then(|label| *label)
        && let Some(current) = mi.get_mesh()
        && let Ok(mut current) = current.try_cast::<godot::classes::ArrayMesh>()
    {
        render::paint::relabel_constant(&mut current, label as f32);
        mi.set_mesh(&current);
    }
    if let Some(skin) = skin {
        mi.set_material_override(skin);
    }
    mi.set_position(at);
    mi.set_rotation(rotation);
    parent.add_child(&mi);
    self.limbs.push((mi.clone(), role));
    mi
}

pub(crate) fn sound(pulses: &mut Gd<RefCounted>, voice: &Voice, at: Vector3, aim: Vector3, t: f64) {
    if !voice.volume.audible() {
        return;
    }
    let wave = voice.wave(aim);
    pulses.call(
        "emit",
        &[
            i64::from(SOURCE_KIND).to_variant(),
            at.to_variant(),
            wave.range.to_variant(),
            wave.speed.to_variant(),
            wave.gain.to_variant(),
            t.to_variant(),
            wave.beam.to_variant(),
            wave.cos_half.to_variant(),
        ],
    );
}

