#[godot_dyn]
impl WaveSolid for WaveWall {
    fn set_material(&mut self, mat: &Gd<Material>) {
        self.skin.set_material(mat);
    }

    /// This wall's box as `render::Shape`, in world space — the geometry
    /// the derive-time paint pass folds into the superface graph. Mirrors
    /// exactly what `ready()` builds: [`level_plan::wall_box`], centered at
    /// the same lift the mesh is drawn at (`(0, WALL_H/2, 0)` local),
    /// carried into world space by the same stored canonical transform as
    /// the generated mesh and physics body. The authored container may retain
    /// a few low bits of parent round-trip dust; it is deliberately not a
    /// second geometry source.
    fn world_shape(&self) -> render::Shape {
        let frame = self.geometry_frame();
        let size = level_plan::wall_box(self.length);
        render::Shape::Box3d {
            center: solid::to_f64_3(frame.origin),
            size: solid::to_f64_3(size),
            basis: solid::basis_columns_f64(frame.basis),
        }
    }

    /// Bake the derive-time paint pass's labels onto this wall — see
    /// [`solid::paint_solid`].
    fn paint(&mut self, labels_by_ordinal: &[f32]) {
        solid::paint_solid(
            self.mesh.as_mut(),
            render::paint::ShapeKind::Box,
            labels_by_ordinal,
        );
    }
}

pub fn labelled_box(size: Vector3, lift: Vector3, face_labels: [f32; 6]) -> Gd<ArrayMesh> {
    let arrays = labelled_box_arrays(size, lift, face_labels);
    let mut mesh = ArrayMesh::new_gd();
    mesh.add_surface_from_arrays_ex(PrimitiveType::TRIANGLES, &arrays)
        .flags(custom0_format())
        .done();
    mesh
}

pub fn resize_box_surface(mesh: &mut Gd<ArrayMesh>, size: Vector3, face_labels: [f32; 6]) {
    let mut arrays = labelled_box_arrays(size, Vector3::ZERO, face_labels);
    carry_labels_over(mesh, &mut arrays);
    mesh.clear_surfaces();
    mesh.add_surface_from_arrays_ex(PrimitiveType::TRIANGLES, &arrays)
        .flags(custom0_format())
        .done();
}

fn carry_labels_over(mesh: &Gd<ArrayMesh>, arrays: &mut Array<Variant>) {
    if mesh.get_surface_count() == 0 {
        return;
    }
    let slot = ArrayType::CUSTOM0.ord() as usize;
    let Some(Ok(kept)) = mesh
        .surface_get_arrays(0)
        .get(slot)
        .map(|v| v.try_to::<PackedFloat32Array>())
    else {
        return;
    };
    let Some(Ok(fresh)) = arrays.get(slot).map(|v| v.try_to::<PackedFloat32Array>()) else {
        return;
    };
    if kept.len() == fresh.len() {
        arrays.set(slot, &kept.to_variant());
    }
}

pub fn resize_triangle_surface(mesh: &mut Gd<ArrayMesh>, triangles: &[(Vector3, Vector3, f32)]) {
    submit_triangle_arrays(mesh, triangle_arrays(triangles, false));
}

pub fn resize_outward_triangle_surface(
    mesh: &mut Gd<ArrayMesh>,
    triangles: &[(Vector3, Vector3, f32)],
) {
    submit_triangle_arrays(mesh, triangle_arrays(triangles, true));
}

pub fn resize_outward_triangle_surface_preserving_labels(
    mesh: &mut Gd<ArrayMesh>,
    triangles: &[(Vector3, Vector3, f32)],
) {
    let mut arrays = triangle_arrays(triangles, true);
    carry_labels_over(mesh, &mut arrays);
    submit_triangle_arrays(mesh, arrays);
}

fn submit_triangle_arrays(mesh: &mut Gd<ArrayMesh>, arrays: Array<Variant>) {
    mesh.clear_surfaces();
    mesh.add_surface_from_arrays_ex(PrimitiveType::TRIANGLES, &arrays)
        .flags(custom0_format())
        .done();
}

pub fn relabel(mesh: &mut Gd<ArrayMesh>, kind: ShapeKind, labels_by_ordinal: &[f32]) {
    if mesh.get_surface_count() == 0 {
        return;
    }
    let arrays = mesh.surface_get_arrays(0);
    let Some(custom_variant) = arrays.get(ArrayType::CUSTOM0.ord() as usize) else {
        return;
    };
    let Ok(mut custom) = custom_variant.try_to::<PackedFloat32Array>() else {
        return;
    };
    for (vertex, label) in custom.as_mut_slice().iter_mut().enumerate() {
        if let Some(real) =
            vertex_ordinal(kind, vertex).and_then(|ordinal| labels_by_ordinal.get(ordinal))
        {
            *label = *real;
        }
    }
    let mut new_arrays = arrays.clone();
    new_arrays.set(ArrayType::CUSTOM0.ord() as usize, &custom.to_variant());
    mesh.surface_remove(0);
    mesh.add_surface_from_arrays_ex(PrimitiveType::TRIANGLES, &new_arrays)
        .flags(custom0_format())
        .done();
}

pub fn relabel_constant(mesh: &mut Gd<ArrayMesh>, label: f32) {
    if !label.is_finite() || mesh.get_surface_count() == 0 {
        return;
    }
    let arrays = mesh.surface_get_arrays(0);
    let Some(custom_variant) = arrays.get(ArrayType::CUSTOM0.ord() as usize) else {
        return;
    };
    let Ok(mut custom) = custom_variant.try_to::<PackedFloat32Array>() else {
        return;
    };
    custom.as_mut_slice().fill(label);
    let mut new_arrays = arrays.clone();
    new_arrays.set(ArrayType::CUSTOM0.ord() as usize, &custom.to_variant());
    mesh.surface_remove(0);
    mesh.add_surface_from_arrays_ex(PrimitiveType::TRIANGLES, &new_arrays)
        .flags(custom0_format())
        .done();
}

fn diff_wave(a: &QueuedWave, b: &QueuedWave) -> Option<String> {
    let QueuedWave {
        kind,
        at,
        max_r,
        speed,
        gain,
        echoes,
        normal,
    } = a;
    // Named "kind" here, this struct's own field — but a reader chasing this
    // divergence path into a blob file wants the WIRE key, which is "type"
    // (`nodes::observer::queued_wave_capture_dict`). Two vocabularies for
    // one field, deliberately: this path names the struct, the wire names
    // the shipped `queued_waves` #[func]. Neither renames for the other.
    if *kind != b.kind {
        return Some("kind".to_string());
    }
    if let Some(c) = diff_v3(*at, b.at) {
        return Some(format!("at.{c}"));
    }
    if let Some(field) = first_mismatch(&[
        ("max_r", same_f64(*max_r, b.max_r)),
        ("speed", same_f64(*speed, b.speed)),
        ("gain", same_f64(*gain, b.gain)),
        ("echoes", *echoes == b.echoes),
    ]) {
        return Some(field.to_string());
    }
    diff_v3(*normal, b.normal).map(|c| format!("normal.{c}"))
}

impl Dropdown {
    pub fn parse(raw_args: &str, context: &ParseContext) -> Result<Self, String> {
        Ok(Self {
            options: OptionsExpression::parse(raw_args, context)?,
            variant_type: context.variant_type,
        })
    }

    pub fn evaluate_options(&self, object: &Gd<Object>) -> Result<Vec<DropdownOption>, String> {
        let options = self.options.evaluate(object)?;
        for option in &options {
            if !is_assignable(&option.value, self.variant_type) {
                return Err(format!(
                    "option '{}' is {}, not {}",
                    option.label,
                    type_string(option.value.get_type().ord() as i64),
                    type_string(self.variant_type.ord() as i64)
                ));
            }
        }

        Ok(options)
    }
}

impl MinMaxSlider {
    pub fn parse(raw_args: &str, context: &ParseContext) -> Result<Self, String> {
        if !SUPPORTED_TYPES.contains(&context.variant_type) {
            return Err("can be used only on Vector2 and Vector2i properties".to_string());
        }

        let args = split_args(raw_args);
        let [min_value, max_value] = args.as_slice() else {
            return Err("expected a minimum and a maximum".to_string());
        };

        Ok(Self {
            min_value: NumberExpression::parse(min_value, context)?,
            max_value: NumberExpression::parse(max_value, context)?,
        })
    }

    pub fn evaluate_bounds(&self, object: &Gd<Object>) -> Result<(f64, f64), String> {
        let min = self.min_value.evaluate(object)?;
        let max = self.max_value.evaluate(object)?;
        if min > max {
            return Err(format!(
                "the minimum {min} is greater than the maximum {max}"
            ));
        }

        Ok((min, max))
    }
}

