    fn from_object(object: &Gd<Object>) -> Self {
        Self {
            property_list: get_script_property_list(object),
            constants: get_script_constants(object),
            default_values: get_script_default_values(object),
        }
    }
}

pub fn from_object(object: &Gd<Object>) -> ScriptDescriptor {
    let snapshot = ScriptSnapshot::from_object(object);
    let path = get_script_path(object);
    let name = get_script_name(object);
    let mut properties = Vec::new();

    for info in &snapshot.property_list {
        let usage: PropertyUsageFlags = info.at("usage").to();
        if !is_editor_property(usage) {
            continue;
        }

        let property_info = PropertyInfo {
            name: info.at("name").to::<GString>().to_string(),
            variant_type: info.at("type").to(),
            hint: info.at("hint").to(),
            hint_text: info.at("hint_string").to::<GString>().to_string(),
            usage,
        };

        if property_info.hint != PropertyHint::NONE || property_info.hint_text.is_empty() {
            properties.push(PropertyDescriptor::plain(&property_info));
            continue;
        }

        let annotation =
            PropertyAnnotation::parse(&property_info.hint_text, NaughtyAttribute::is_known_key);

        for key in &annotation.unknown_keys {
            na_error!("{path}.{} - {key}: unknown attribute", property_info.name);
        }

        for key in &annotation.ignored_builtin_keys {
            na_error!(
                "{path}.{} - {key}: a property can have only one built-in hint, keeping the last one",
                property_info.name
            );
        }

        if !annotation.is_claimed() {
            properties.push(PropertyDescriptor::unclaimed(&property_info));
            continue;
        }

        let context = ParseContext {
            variant_type: property_info.variant_type,
            constants: &snapshot.constants,
        };

        let mut property = PropertyDescriptor::claimed(&property_info, &annotation);
        for entry in &annotation.attributes {
            match NaughtyAttribute::parse(&entry.key, &entry.raw_args, &context) {
                Ok(NaughtyAttribute::Decorator(decorator)) => {
                    property.decorators.push(decorator)
                }
                Ok(NaughtyAttribute::Drawer(drawer)) => {
                    if property.drawer.is_some() {
                        na_error!(
                            "{path}.{} - {}: a property can have only one drawer, keeping the last one",
                            property_info.name,
                            entry.key
                        );
                    }

                    property.drawer = Some(drawer);
                }
                Ok(NaughtyAttribute::Meta(meta)) => property.metas.push(meta),
                Ok(NaughtyAttribute::Validator(validator)) => {
                    property.validators.push(validator)
                }
                Err(error) => {
                    na_error!("{path}.{} - {}: {error}", property_info.name, entry.key);
                }
            }
        }

        properties.push(property);
    }

    ScriptDescriptor {
        snapshot,
        path,
        name,
        properties,
    }
}

pub fn is_stale(&self, object: &Gd<Object>) -> bool {
    ScriptSnapshot::from_object(object) != self.snapshot
}

fn get_script(object: &Gd<Object>) -> Option<Gd<Script>> {
    object.get("script").try_to::<Gd<Script>>().ok()
}

fn get_script_chain(object: &Gd<Object>) -> Vec<Gd<Script>> {
    let mut chain = Vec::new();
    let mut current = get_script(object);

    while let Some(script) = current {
        current = script.get_base_script();
        chain.push(script);
    }

    chain.reverse();
    chain
}

pub fn get_script_path(object: &Gd<Object>) -> String {
    get_script(object)
        .map(|script| script.get_path().to_string())
        .unwrap_or_default()
}

fn get_script_property_list(object: &Gd<Object>) -> Vec<VarDictionary> {
    get_script(object)
        .map(|script| script.get_script_property_list().iter_shared().collect())
        .unwrap_or_default()
}

fn get_script_constants(object: &Gd<Object>) -> VarDictionary {
    let mut constants = VarDictionary::new();

    for script in get_script_chain(object) {
        for (key, value) in script.get_script_constant_map().iter_shared() {
            constants.set(&key, &value);
        }
    }

    constants
}

fn get_script_default_values(object: &Gd<Object>) -> VarDictionary {
    let mut default_values = VarDictionary::new();
    let Some(script) = get_script(object) else {
        return default_values;
    };

    for info in script.get_script_property_list().iter_shared() {
        let name = info.at("name");
        let text = name.to::<GString>().to_string();
        let default_value = script.get_property_default_value(text.as_str());
        default_values.set(&name, &default_value);
    }

    default_values
}

impl BoolExpression {
    pub fn parse(raw_args: &str, context: &ParseContext) -> Result<Self, String> {
        let source = raw_args.trim();
        if source.is_empty() {
            return Err("expected a boolean expression".to_string());
        }

        let expression = Expression::compile(source, context.constants);
        if !expression.is_valid() {
            return Err(expression.get_error().to_string());
        }

        Ok(Self { expression })
    }

    pub fn evaluate(&self, object: &Gd<Object>) -> Result<bool, String> {
        self.expression.evaluate_bool(object)
    }

    pub fn get_text(&self) -> &str {
        self.expression.get_text()
    }
}

pub fn compile(expression_text: &str, constants: &VarDictionary) -> Self {
    let mut input_names = PackedStringArray::new();
    let mut inputs = VarArray::new();

    for (key, value) in constants.iter_shared() {
        input_names.push(&key.stringify());
        inputs.push(&value);
    }

    let normalized_text = normalize_operators(expression_text);
    let mut expression = GodotExpression::new_gd();
    let error = expression
        .parse_ex(&GString::from(&normalized_text))
        .input_names(&input_names)
        .done();

    let valid = error == godot::global::Error::OK;
    let message = if valid {
        String::new()
    } else {
        expression.get_error_text().to_string()
    };

    Self {
        text: expression_text.to_string(),
        expression,
        inputs,
        valid,
        error: message,
    }
}

pub fn evaluate(&self, object: &Gd<Object>) -> Result<Variant, String> {
    if !self.valid {
        return Err(self.error.clone());
    }

    let mut expression = Gd::clone(&self.expression);
    let result = expression
        .execute_ex()
        .inputs(&self.inputs)
        .base_instance(object)
        .show_error(false)
        .done();

    if expression.has_execute_failed() {
        let hint = if self.text.contains('(') {
            get_method_call_hint(object)
        } else {
            ""
        };

        return Err(format!(
            "'{}' failed: {}{hint}",
            self.text,
            expression.get_error_text()
        ));
    }

    Ok(result)
}

pub fn evaluate_bool(&self, object: &Gd<Object>) -> Result<bool, String> {
    self.evaluate(object).map(|value| value.booleanize())
}

pub fn evaluate_number(&self, object: &Gd<Object>) -> Result<f64, String> {
    let value = self.evaluate(object)?;

    match value.get_type() {
        VariantType::INT => Ok(value.to::<i64>() as f64),
        VariantType::FLOAT => Ok(value.to::<f64>()),
        other => Err(format!(
            "'{}' is {}, not a number",
            self.text,
            type_string(other.ord() as i64)
        )),
    }
}

pub fn get_method_call_hint(object: &Gd<Object>) -> &'static str {
    let is_tool = object
        .get("script")
        .try_to::<Gd<Script>>()
        .map(|script| script.is_tool())
        .unwrap_or(true);

    if is_tool {
        " (check that the method exists on the script and that its arguments match)"
    } else {
        " (calling a method needs @tool on the script)"
    }
}

impl NumberExpression {
    pub fn parse(raw_args: &str, context: &ParseContext) -> Result<Self, String> {
        if !NUMBER_TYPES.contains(&context.variant_type) {
            return Err(
                "can be used only on int, float, Vector2/3/4 and Vector2i/3i/4i properties"
                    .to_string(),
            );
        }

        let source = raw_args.trim();
        if source.is_empty() {
            return Err("expected a numeric expression".to_string());
        }

        let expression = Expression::compile(source, context.constants);
        if !expression.is_valid() {
            return Err(expression.get_error().to_string());
        }

        Ok(Self { expression })
    }

    pub fn evaluate(&self, object: &Gd<Object>) -> Result<f64, String> {
        self.expression.evaluate_number(object)
    }
}

impl OptionsExpression {
    pub fn parse(raw_args: &str, context: &ParseContext) -> Result<Self, String> {
        let source = raw_args.trim();
        if source.is_empty() {
            return Err("expected an Array or a Dictionary expression".to_string());
        }

        let expression = Expression::compile(source, context.constants);
        if !expression.is_valid() {
            return Err(expression.get_error().to_string());
        }

        Ok(Self { expression })
    }

    pub fn evaluate(&self, object: &Gd<Object>) -> Result<Vec<DropdownOption>, String> {
        let value = self.expression.evaluate(object)?;
        let options: Vec<DropdownOption> = match value.get_type() {
            VariantType::ARRAY => value
                .to::<AnyArray>()
                .iter_shared()
                .map(|element| DropdownOption {
                    label: element.stringify().to_string(),
                    value: element,
                })
                .collect(),
            VariantType::DICTIONARY => value
                .to::<AnyDictionary>()
                .iter_shared()
                .map(|(key, value)| DropdownOption {
                    label: key.stringify().to_string(),
                    value,
                })
                .collect(),
            other => {
                return Err(format!(
                    "'{}' is {}, not an Array or a Dictionary",
                    self.expression.get_text(),
                    type_string(other.ord() as i64)
                ));
            }
        };

        if options.is_empty() {
            return Err(format!("'{}' is empty", self.expression.get_text()));
        }

        Ok(options)
    }
}

