struct ObjectState {
    object: Gd<Object>,
    script: Rc<ScriptDescriptor>,
    property_blocks: HashMap<StringName, PropertyBlock>,
    edit_action: Option<PropertyEditAction>,
}

fn create_naughty_script(&self, object: &Gd<Object>) -> Option<Rc<ScriptDescriptor>> {
    let script = Rc::new(ScriptDescriptor::from_object(object));
    script.is_naughty().then_some(script)
}

fn create_property_block(
    &mut self,
    edit_action: &mut PropertyEditAction,
    object: &Gd<Object>,
    property: &PropertyDescriptor,
    wide: bool,
) -> Option<PropertyBlock> {
    let _scope = InstantiationScope::enter(&self.instantiating);
    let _base = self.base_mut();
    property_blocks::create_property_block(edit_action, object, property, wide)
}

fn refresh_property_blocks(&self) {
    let objects: Vec<(InstanceId, Gd<Object>, Rc<ScriptDescriptor>)> = self
        .state
        .borrow()
        .object_states
        .iter()
        .filter(|(_, object_state)| object_state.object.is_instance_valid())
        .map(|(instance_id, object_state)| {
            (
                *instance_id,
                Gd::clone(&object_state.object),
                Rc::clone(&object_state.script),
            )
        })
        .collect();

    for (instance_id, object, script) in &objects {
        for property in &script.properties {
            let Some(mut property_block) =
                self.find_property_block(*instance_id, &property.name)
            else {
                continue;
            };

            let visible = property_utils::is_visible(object, property);
            property_block.set_visible(visible);

            let enabled = property_utils::is_enabled(object, property);
            property_block.set_enabled(enabled);

            let message = visible
                .then(|| property_utils::get_validation_message(object, property))
                .flatten();

            property_block.set_message(message.as_deref());
        }
    }
}

fn defer_value_changed_callbacks(
    &self,
    mut object: Gd<Object>,
    script: Rc<ScriptDescriptor>,
    changes: Vec<PropertyChange>,
) {
    if changes.is_empty() {
        return;
    }

    Callable::from_fn("call_value_changed_callbacks", move |_args| {
        if object.is_instance_valid() {
            for change in &changes {
                if let Some(property) = script.find_property(&change.name) {
                    property_utils::call_value_changed_callbacks(
                        &mut object,
                        property,
                        &change.old_value,
                        &change.new_value,
                    );
                }
            }
        }

        Variant::nil()
    })
    .call_deferred(&[]);
}

#[godot_api]
impl IEditorPlugin for NaughtyEditorPlugin {
    fn enter_tree(&mut self) {
        let plugin = NaughtyEditorInspectorPlugin::new_gd();
        self.base_mut().add_inspector_plugin(&plugin);
        self.inspector_plugin = Some(plugin);

        self.add_inspector_edit_hook();
        self.connect_signals();

        na_print!("v{} ready", env!("CARGO_PKG_VERSION"));
    }

    fn exit_tree(&mut self) {
        self.disconnect_signals();
        self.remove_inspector_edit_hook();

        if let Some(plugin) = self.inspector_plugin.take() {
            self.base_mut().remove_inspector_plugin(&plugin);
        }
    }

    fn on_notification(&mut self, what: NodeNotification) {
        if what == NodeNotification::EXTENSION_RELOADED {
            self.disconnect_signals();
            self.remove_inspector_edit_hook();
            self.add_inspector_edit_hook();
            self.connect_signals();
        } else if what == NodeNotification::APPLICATION_FOCUS_IN {
            self.request_rebuild_if_stale();
        }
    }
}

fn add_inspector_edit_hook(&mut self) {
    if self.inspector_edit_hook.is_some() {
        return;
    }

    let Some(plugin) = self.inspector_plugin.as_ref() else {
        return;
    };

    let hook = Callable::from_object_method(plugin, "on_inspector_edit");
    self.base_mut().add_undo_redo_inspector_hook_callback(&hook);
    self.inspector_edit_hook = Some(hook);
}

fn remove_inspector_edit_hook(&mut self) {
    if let Some(hook) = self.inspector_edit_hook.take() {
        self.base_mut()
            .remove_undo_redo_inspector_hook_callback(&hook);
    }
}

fn connect_version_changed(&mut self) {
    if self.version_changed_handle.is_some() {
        return;
    }

    let Some(undo_redo) = EditorInterface::singleton().get_editor_undo_redo() else {
        return;
    };

    let handle = undo_redo
        .signals()
        .version_changed()
        .connect_other(&*self, Self::on_version_changed);

    self.version_changed_handle = Some(handle);
}

fn connect_resource_saved(&mut self) {
    if self.resource_saved_handle.is_some() {
        return;
    }

    let handle = self
        .base()
        .signals()
        .resource_saved()
        .connect_other(&*self, Self::on_resource_saved);

    self.resource_saved_handle = Some(handle);
}

fn on_resource_saved(&mut self, resource: Gd<Resource>) {
    if resource.try_cast::<Script>().is_ok() {
        self.request_rebuild_if_stale();
    }
}

fn connect_filesystem_changed(&mut self) {
    if self.filesystem_changed_handle.is_some() {
        return;
    }

    let Some(filesystem) = EditorInterface::singleton().get_resource_filesystem() else {
        return;
    };

    let handle = filesystem
        .signals()
        .filesystem_changed()
        .connect_other(&*self, Self::on_filesystem_changed);

    self.filesystem_changed_handle = Some(handle);
}

