fn set_control_visible<T: Inherits<Control>>(control: &mut Gd<T>, visible: bool) {
    if !control.is_instance_valid() {
        return;
    }

    let control = control.upcast_mut::<Control>();
    if control.is_visible() != visible {
        control.set_visible(visible);
    }
}

pub fn create_property_block(
    edit_action: &mut PropertyEditAction,
    object: &Gd<Object>,
    property: &PropertyDescriptor,
    wide: bool,
) -> Option<PropertyBlock> {
    let visible = property_utils::is_visible(object, property);
    if visible {
        property_utils::validate_property(edit_action, object, property);
    }

    let editor = property_utils::create_drawer_editor(object, property)
        .or_else(|| create_default_editor(object, property, wide));

    let Some(editor) = editor else {
        na_error!(
            "{}.{}: no property editor",
            descriptor::get_script_path(object),
            property.name
        );
        return None;
    };

    let mut property_block = PropertyBlock {
        editor,
        decorations_container: create_decorations_container(object, property),
        message_bubble: create_message_bubble(property),
    };

    property_block.set_visible(visible);
    Some(property_block)
}

fn create_decorations_container(
    object: &Gd<Object>,
    property: &PropertyDescriptor,
) -> Option<Gd<VBoxContainer>> {
    if property.decorators.is_empty() {
        return None;
    }

    let mut container = VBoxContainer::new_alloc();
    for attribute in &property.decorators {
        let decorator = attribute_registry::get_decorator(attribute);
        decorator.decorate(&mut container, object);
    }

    Some(container)
}

fn create_default_editor(
    object: &Gd<Object>,
    property: &PropertyDescriptor,
    wide: bool,
) -> Option<Gd<EditorProperty>> {
    EditorInspector::instantiate_property_editor_ex(
        object,
        property.variant_type,
        &GString::from(&property.name),
        property.hint,
        &property.hint_text,
        property.usage.ord() as u32,
    )
    .wide(wide)
    .done()
}

pub struct PropertyEditAction {
    object: Gd<Object>,
    changes: Vec<PropertyChange>,
}

pub fn new(object: &Gd<Object>) -> Self {
    Self {
        object: Gd::clone(object),
        changes: Vec::new(),
    }
}

pub fn commit(mut self, action_name: &str) {
    self.changes
        .retain(|change| change.old_value != change.new_value);
    if self.changes.is_empty() {
        return;
    }

    let Some(mut undo_redo) = EditorInterface::singleton().get_editor_undo_redo() else {
        return;
    };

    undo_redo
        .create_action_ex(action_name)
        .merge_mode(MergeMode::ALL)
        .backward_undo_ops(true)
        .done();

    for change in &self.changes {
        undo_redo.add_do_property(&self.object, &change.name, &change.new_value);
        undo_redo.add_undo_property(&self.object, &change.name, &change.old_value);
    }
    undo_redo.commit_action_ex().execute(false).done();
}

pub fn add_to(
    &mut self,
    undo_redo: &mut Gd<EditorUndoRedoManager>,
    session: &EditSession,
    requested_value: &Variant,
) {
    let mut history = get_history(undo_redo, &self.object);
    self.revert();

    for change in &self.changes {
        if change.name == session.name {
            let is_corrected = change.new_value != *requested_value;
            if is_corrected {
                undo_redo.add_do_property(&self.object, &change.name, &change.new_value);
            }

            continue;
        }

        if change.old_value == change.new_value {
            continue;
        }

        undo_redo.add_do_property(&self.object, &change.name, &change.new_value);

        let origin = session
            .origins
            .get(&change.name)
            .unwrap_or(&change.old_value);
        if let Some(history) = history.as_mut() {
            history.start_force_keep_in_merge_ends();
        }

        undo_redo.add_undo_property(&self.object, &change.name, origin);
        if let Some(history) = history.as_mut() {
            history.end_force_keep_in_merge_ends();
        }
    }
}

impl EditSession {
    pub fn resume<'a>(
        slot: &'a mut Option<Self>,
        undo_redo: &Gd<EditorUndoRedoManager>,
        object: &Gd<Object>,
        script: &ScriptDescriptor,
        name: &StringName,
    ) -> &'a Self {
        let version = get_history(undo_redo, object)
            .map(|history| history.get_version())
            .unwrap_or_default();

        if let Some(session) = slot.as_mut()
            && session.continues(object, name, version)
        {
            session.advance(version);
        } else {
            *slot = None;
        }

        slot.get_or_insert_with(|| Self::begin(object, script, name, version))
    }

    fn begin(
        object: &Gd<Object>,
        script: &ScriptDescriptor,
        name: &StringName,
        version: u64,
    ) -> Self {
        let origins = script
            .properties
            .iter()
            .filter(|property| property.claimed)
            .map(|property| (property.name.clone(), object.get(&property.name)))
            .collect();

        Self {
            object: object.instance_id(),
            name: name.clone(),
            origins,
            last_edit_time: Instant::now(),
            next_version: version + 1,
        }
    }

    fn continues(&self, object: &Gd<Object>, name: &StringName, version: u64) -> bool {
        self.object == object.instance_id()
            && &self.name == name
            && self.last_edit_time.elapsed() < GODOT_MERGE_WINDOW
            && self.next_version == version
    }

    fn advance(&mut self, version: u64) {
        self.last_edit_time = Instant::now();
        self.next_version = version;
    }
}

fn get_history(undo_redo: &Gd<EditorUndoRedoManager>, object: &Gd<Object>) -> Option<Gd<UndoRedo>> {
    let history_id = undo_redo.get_object_history_id(object);
    undo_redo.get_history_undo_redo(history_id)
}

pub fn create_drawer_editor(
    object: &Gd<Object>,
    property: &PropertyDescriptor,
) -> Option<Gd<EditorProperty>> {
    let attribute = property.drawer.as_ref()?;
    let drawer = attribute_registry::get_drawer(attribute);
    match drawer.create_editor(object, property) {
        Ok(editor) => Some(editor),
        Err(error) => {
            na_error!(
                "{}.{} - {}: {error}",
                descriptor::get_script_path(object),
                property.name,
                attribute.get_key()
            );
            None
        }
    }
}

pub fn is_visible(object: &Gd<Object>, property: &PropertyDescriptor) -> bool {
    is_meta_query_satisfied(object, property, |meta, obj| match meta {
        ShowIf(attribute) => attribute.is_visible(obj),
        HideIf(attribute) => attribute.is_visible(obj),
        EnableIf(_) | DisableIf(_) | ReadOnly | Label(_) | OnValueChanged(_) => Ok(true),
    })
}

pub fn is_enabled(object: &Gd<Object>, property: &PropertyDescriptor) -> bool {
    is_meta_query_satisfied(object, property, |meta, obj| match meta {
        EnableIf(attribute) => attribute.is_enabled(obj),
        DisableIf(attribute) => attribute.is_enabled(obj),
        ReadOnly => Ok(false),
        ShowIf(_) | HideIf(_) | Label(_) | OnValueChanged(_) => Ok(true),
    })
}

fn is_meta_query_satisfied(
    object: &Gd<Object>,
    property: &PropertyDescriptor,
    query: impl Fn(&MetaAttribute, &Gd<Object>) -> Result<bool, String>,
) -> bool {
    let mut satisfied = true;

    for meta in &property.metas {
        satisfied &= query(meta, object).unwrap_or_else(|error| {
            na_error!(
                "{}.{} - {}: {error}",
                descriptor::get_script_path(object),
                property.name,
                meta.get_key()
            );
            true
        });
    }

    satisfied
}

pub fn clamp_property(
    object: &Gd<Object>,
    property: &PropertyDescriptor,
    min: f64,
    max: f64,
) -> Result<Validation, String> {
    let value = object.get(&property.name);
    let clamped_value = variant_utils::clamp(&value, min, max)?;
    if clamped_value == value {
        return Ok(Validation::Valid);
    }

    Ok(Validation::Corrected(clamped_value))
}

pub fn validate_property(
    edit_action: &mut PropertyEditAction,
    object: &Gd<Object>,
    property: &PropertyDescriptor,
) {
    for attribute in &property.validators {
        let validator = attribute_registry::get_validator(attribute);
        match validator.validate(object, property) {
            Ok(Validation::Corrected(value)) => {
                edit_action.set_property_value(&property.name, &value)
            }
            Ok(Validation::Valid | Validation::Rejected(_)) => {}
            Err(error) => {
                na_error!(
                    "{}.{} - {}: {error}",
                    descriptor::get_script_path(object),
                    property.name,
                    attribute.get_key()
                );
            }
        }
    }
}

pub fn validate_properties(
    edit_action: &mut PropertyEditAction,
    object: &Gd<Object>,
    properties: &[PropertyDescriptor],
) {
    for property in properties {
        if is_visible(object, property) {
            validate_property(edit_action, object, property);
        }
    }
}

pub fn get_validation_message(
    object: &Gd<Object>,
    property: &PropertyDescriptor,
) -> Option<String> {
    let messages: Vec<String> = property
        .validators
        .iter()
        .filter_map(|attribute| {
            let validator = attribute_registry::get_validator(attribute);
            match validator.validate(object, property) {
                Ok(Validation::Rejected(message)) => Some(message),
                Ok(Validation::Valid | Validation::Corrected(_)) | Err(_) => None,
            }
        })
        .collect();

    (!messages.is_empty()).then(|| messages.join("\n"))
}

pub fn call_value_changed_callbacks(
    object: &mut Gd<Object>,
    property: &PropertyDescriptor,
    old_value: &Variant,
    new_value: &Variant,
) {
    for meta in &property.metas {
        let result = match meta {
            OnValueChanged(attribute) => attribute.call(object, old_value, new_value),
            ShowIf(_) | HideIf(_) | EnableIf(_) | DisableIf(_) | ReadOnly | Label(_) => Ok(()),
        };

        if let Err(error) = result {
            na_error!(
                "{}.{} - {}: {error}",
                descriptor::get_script_path(object),
                property.name,
                meta.get_key()
            );
        }
    }
}

impl IValidator for MaxValue {
    fn validate(
        &self,
        object: &Gd<Object>,
        property: &PropertyDescriptor,
    ) -> Result<Validation, String> {
        let (min, max) = self.get_bounds(object)?;
        property_utils::clamp_property(object, property, min, max)
    }
}

impl IValidator for MinValue {
    fn validate(
        &self,
        object: &Gd<Object>,
        property: &PropertyDescriptor,
    ) -> Result<Validation, String> {
        let (min, max) = self.get_bounds(object)?;
        property_utils::clamp_property(object, property, min, max)
    }
}

impl IValidator for Require {
    fn validate(
        &self,
        object: &Gd<Object>,
        property: &PropertyDescriptor,
    ) -> Result<Validation, String> {
        if self.is_satisfied(object)? {
            return Ok(Validation::Valid);
        }

        Ok(Validation::Rejected(
            self.get_message(&property.name.to_string()),
        ))
    }
}

pub trait IValidator {
    fn validate(
        &self,
        object: &Gd<Object>,
        property: &PropertyDescriptor,
    ) -> Result<Validation, String>;
}

impl GodotTextureImporter {
    pub fn new() -> Result<Self, String> {
        let render_backend = RenderBackend::detect();

        match render_backend {
            RenderBackend::Vulkan => {
                let vulkan_importer = vulkan::VulkanTextureImporter::new()?;
                godot_print!("[AcceleratedOSR/Linux] Using Vulkan backend with DMA-BUF");
                Ok(Self { vulkan_importer })
            }
            _ => Err(format!(
                "Unsupported Linux accelerated rendering backend: {render_backend:?}"
            )),
        }
    }

    pub fn capture(
        &mut self,
        info: &AcceleratedPaintInfo,
        target: NativeCaptureTarget,
    ) -> Result<(), String> {
        self.vulkan_importer.capture(info, target)
    }

    pub fn prepare_publication(&self) -> Result<(), String> {
        self.vulkan_importer.prepare_publication()
    }
}

pub fn new() -> Result<Self, String> {
    let rd = RenderingServer::singleton()
        .get_rendering_device()
        .ok_or("RenderingDevice unavailable for Vulkan capture")?;
    let device = vk::Device::from_raw(rd.get_driver_resource(
        DriverResource::LOGICAL_DEVICE,
        Rid::Invalid,
        0,
    ));
    let physical_device = vk::PhysicalDevice::from_raw(rd.get_driver_resource(
        DriverResource::PHYSICAL_DEVICE,
        Rid::Invalid,
        0,
    ));
    let queue = vk::Queue::from_raw(rd.get_driver_resource(
        DriverResource::COMMAND_QUEUE,
        Rid::Invalid,
        0,
    ));
    let queue_family_index =
        u32::try_from(rd.get_driver_resource(DriverResource::QUEUE_FAMILY, Rid::Invalid, 0))
            .map_err(|_| "Invalid Godot Vulkan queue family")?;
    if device == vk::Device::null()
        || physical_device == vk::PhysicalDevice::null()
        || queue == vk::Queue::null()
    {
        return Err("Godot returned a null Vulkan device or graphics queue".into());
    }
    crate::vulkan_hook::queue_sync::ensure_queue_synchronization(device, queue)?;
    let library = unsafe { libloading::Library::new("libvulkan.so.1") }
        .map_err(|error| format!("Failed to load Vulkan: {error}"))?;
    let fns = Self::load_vulkan_functions(&library, device)?;
    let get_physical_device_image_format_properties2 = unsafe {
        *library
            .get::<PfnVkGetPhysicalDeviceImageFormatProperties2>(
                b"vkGetPhysicalDeviceImageFormatProperties2\0",
            )
            .map_err(|error| format!("Missing Vulkan image format query: {error}"))?
    };
    // CEF's DMA-BUF may originate from a foreign API/driver. EXTERNAL is not
    // an interchangeable fallback for FOREIGN_EXT ownership.
    if !Self::device_supports_extension(
        &library,
        physical_device,
        c"VK_EXT_queue_family_foreign",
    ) {
        return Err("DMA-BUF capture requires VK_EXT_queue_family_foreign".into());
    }
    if !Self::device_supports_extension(
        &library,
        physical_device,
        c"VK_KHR_external_semaphore_fd",
    ) {
        return Err("DMA-BUF capture requires VK_KHR_external_semaphore_fd".into());
    }
    let pool_info = vk::CommandPoolCreateInfo::default()
        .queue_family_index(queue_family_index)
        .flags(vk::CommandPoolCreateFlags::RESET_COMMAND_BUFFER);
    let mut command_pool = vk::CommandPool::null();
    check(
        unsafe {
            (fns.create_command_pool)(device, &pool_info, std::ptr::null(), &mut command_pool)
        },
        "vkCreateCommandPool",
    )?;
    let allocate = vk::CommandBufferAllocateInfo::default()
        .command_pool(command_pool)
        .level(vk::CommandBufferLevel::PRIMARY)
        .command_buffer_count(1);
    let mut command_buffer = vk::CommandBuffer::null();
    if let Err(error) = check(
        unsafe { (fns.allocate_command_buffers)(device, &allocate, &mut command_buffer) },
        "vkAllocateCommandBuffers",
    ) {
        unsafe { (fns.destroy_command_pool)(device, command_pool, std::ptr::null()) };
        return Err(error);
    }
    let mut fence = vk::Fence::null();
    if let Err(error) = check(
        unsafe {
            (fns.create_fence)(
                device,
                &vk::FenceCreateInfo::default(),
                std::ptr::null(),
                &mut fence,
            )
        },
        "vkCreateFence",
    ) {
        unsafe { (fns.destroy_command_pool)(device, command_pool, std::ptr::null()) };
        return Err(error);
    }
    Ok(Self {
        device,
        physical_device,
        command_pool,
        command_buffer,
        fence,
        queue,
        queue_family_index,
        get_memory_fd_properties: fns.get_memory_fd_properties,
        get_physical_device_image_format_properties2: Some(
            get_physical_device_image_format_properties2,
        ),
        fns,
        device_lost: false,
        _library: library,
    })
}

fn probe_external_image_support(
    &self,
    params: &DmaBufImportParams,
    tiling: vk::ImageTiling,
) -> Result<(), String> {
    let Some(get_image_format_properties2) = self.get_physical_device_image_format_properties2
    else {
        return Ok(());
    };
    if self.physical_device == vk::PhysicalDevice::null() {
        return Ok(());
    }

    let mut external_info = vk::PhysicalDeviceExternalImageFormatInfo::default()
        .handle_type(vk::ExternalMemoryHandleTypeFlags::DMA_BUF_EXT);

    let mut modifier_info = vk::PhysicalDeviceImageDrmFormatModifierInfoEXT::default()
        .drm_format_modifier(params.modifier)
        .sharing_mode(vk::SharingMode::EXCLUSIVE);

    let mut format_info = vk::PhysicalDeviceImageFormatInfo2::default()
        .format(params.format)
        .ty(vk::ImageType::TYPE_2D)
        .tiling(tiling)
        .usage(vk::ImageUsageFlags::TRANSFER_SRC)
        .flags(vk::ImageCreateFlags::empty())
        .push_next(&mut external_info);

    if tiling == vk::ImageTiling::DRM_FORMAT_MODIFIER_EXT {
        format_info = format_info.push_next(&mut modifier_info);
    }

    let mut external_props = vk::ExternalImageFormatProperties::default();
    let mut format_props = vk::ImageFormatProperties2 {
        p_next: &mut external_props as *mut _ as *mut _,
        ..Default::default()
    };

    let result = unsafe {
        get_image_format_properties2(self.physical_device, &format_info, &mut format_props)
    };
    if result != vk::Result::SUCCESS {
        return Err(format!(
            "DMA-BUF image format is unsupported before import: {:?} \
             (format={:?}, tiling={:?}, modifier=0x{:x}, usage={:?})",
            result,
            params.format,
            tiling,
            params.modifier,
            vk::ImageUsageFlags::TRANSFER_SRC
        ));
    }

    let external_memory = external_props.external_memory_properties;
    if !external_memory
        .external_memory_features
        .contains(vk::ExternalMemoryFeatureFlags::IMPORTABLE)
    {
        return Err(format!(
            "DMA-BUF image format is not importable \
             (format={:?}, tiling={:?}, modifier=0x{:x}, features={:?}, compatible={:?})",
            params.format,
            tiling,
            params.modifier,
            external_memory.external_memory_features,
            external_memory.compatible_handle_types
        ));
    }

    if !external_memory
        .compatible_handle_types
        .contains(vk::ExternalMemoryHandleTypeFlags::DMA_BUF_EXT)
    {
        return Err(format!(
            "DMA-BUF handle type is not compatible with image format \
             (format={:?}, tiling={:?}, modifier=0x{:x}, compatible={:?})",
            params.format, tiling, params.modifier, external_memory.compatible_handle_types
        ));
    }

    godot_print!(
        "[AcceleratedOSR/Vulkan] DMA-BUF image format probe OK: format={:?}, \
         tiling={:?}, modifier=0x{:x}, max_extent={}x{}, features={:?}, compatible={:?}",
        params.format,
        tiling,
        params.modifier,
        format_props.image_format_properties.max_extent.width,
        format_props.image_format_properties.max_extent.height,
        external_memory.external_memory_features,
        external_memory.compatible_handle_types
    );

    Ok(())
}

fn import_memory_for_dmabuf(
    &mut self,
    params: &mut DmaBufImportParams,
    image: vk::Image,
) -> Result<vk::DeviceMemory, String> {
    let fns = self.fns;

    // Use the first plane's fd for memory import
    let fd = params.fds[0];

    let mut fd_props = vk::MemoryFdPropertiesKHR::default();
    let result = unsafe {
        (self.get_memory_fd_properties)(
            self.device,
            vk::ExternalMemoryHandleTypeFlags::DMA_BUF_EXT,
            fd,
            &mut fd_props,
        )
    };
    if result != vk::Result::SUCCESS {
        return Err(format!("Failed to get memory fd properties: {:?}", result));
    }

    let mut memory_requirements = vk::MemoryRequirements::default();
    unsafe {
        (fns.get_image_memory_requirements)(self.device, image, &mut memory_requirements)
    };

    let memory_type_bits = fd_props.memory_type_bits & memory_requirements.memory_type_bits;
    let memory_type_index = find_memory_type_index(memory_type_bits).ok_or_else(|| {
        format!(
            "Failed to find suitable DMA-BUF memory type \
             (fd_memory_type_bits=0x{:x}, image_memory_type_bits=0x{:x})",
            fd_props.memory_type_bits, memory_requirements.memory_type_bits
        )
    })?;

    #[cfg(debug_assertions)]
    {
        godot_print!(
            "[AcceleratedOSR/Vulkan] DMA-BUF memory import: \
             fd_memory_type_bits=0x{:x}, image_memory_type_bits=0x{:x}, \
             selected_memory_type={}, allocation_size={}, alignment={}",
            fd_props.memory_type_bits,
            memory_requirements.memory_type_bits,
            memory_type_index,
            memory_requirements.size,
            memory_requirements.alignment
        );
    }

    // Import the memory with the DMA-BUF fd
    // Note: The fd ownership is transferred to Vulkan upon successful import
    let mut import_info = vk::ImportMemoryFdInfoKHR::default()
        .handle_type(vk::ExternalMemoryHandleTypeFlags::DMA_BUF_EXT)
        .fd(fd);

    let mut dedicated_info = vk::MemoryDedicatedAllocateInfo::default().image(image);

    let alloc_info = vk::MemoryAllocateInfo::default()
        .push_next(&mut import_info)
        .push_next(&mut dedicated_info)
        .allocation_size(memory_requirements.size)
        .memory_type_index(memory_type_index);

    let mut memory = vk::DeviceMemory::null();
    let result = unsafe {
        (fns.allocate_memory)(self.device, &alloc_info, std::ptr::null(), &mut memory)
    };
    if result != vk::Result::SUCCESS {
        return Err(format!(
            "Failed to allocate/import DMA-BUF memory: {:?} \
             (fd_memory_type_bits=0x{:x}, image_memory_type_bits=0x{:x}, \
             memory_type_index={}, allocation_size={}, alignment={})",
            result,
            fd_props.memory_type_bits,
            memory_requirements.memory_type_bits,
            memory_type_index,
            memory_requirements.size,
            memory_requirements.alignment
        ));
    }

    params.fds[0] = -1;

    // Bind image to memory
    let result = unsafe { (fns.bind_image_memory)(self.device, image, memory, 0) };
    if result != vk::Result::SUCCESS {
        unsafe {
            (fns.free_memory)(self.device, memory, std::ptr::null());
        }
        return Err(format!("Failed to bind image memory: {:?}", result));
    }

    Ok(memory)
}

pub fn new() -> Result<Self, String> {
    let rd = RenderingServer::singleton()
        .get_rendering_device()
        .ok_or("Metal RenderingDevice unavailable")?;
    let device_ptr = rd.get_driver_resource(DriverResource::LOGICAL_DEVICE, Rid::Invalid, 0);
    let queue_ptr = rd.get_driver_resource(DriverResource::COMMAND_QUEUE, Rid::Invalid, 0);
    let device = unsafe { Retained::retain(device_ptr as *mut AnyObject) }
        .ok_or("Godot did not expose its Metal device")?;
    let command_queue = unsafe { Retained::retain(queue_ptr as *mut AnyObject) }
        .ok_or("Godot did not expose its Metal command queue")?;
    Ok(Self {
        device,
        command_queue,
    })
}

pub fn get_godot_gpu_device_ids() -> Option<(u32, u32)> {
    let rd = RenderingServer::singleton().get_rendering_device()?;
    let mtl_device_ptr = rd.get_driver_resource(DriverResource::LOGICAL_DEVICE, Rid::Invalid, 0);

    if mtl_device_ptr == 0 {
        godot_error!("[AcceleratedOSR/Metal] Failed to get Metal device for GPU ID query");
        return None;
    }

    let device: &AnyObject = unsafe { &*(mtl_device_ptr as *const AnyObject) };

    // Get registryID from MTLDevice
    let registry_id: u64 = unsafe { msg_send![device, registryID] };

    if registry_id == 0 {
        godot_error!("[AcceleratedOSR/Metal] Metal device has no registry ID");
        return None;
    }

    // Use IOKit to find the IOService entry and read vendor/device IDs
    unsafe {
        let matching = IORegistryEntryIDMatching(registry_id);
        if matching.is_null() {
            godot_error!("[AcceleratedOSR/Metal] Failed to create IORegistry matching dictionary");
            return None;
        }

        // kIOMasterPortDefault is 0
        let service = IOServiceGetMatchingService(0, matching);
        // matching is consumed by IOServiceGetMatchingService

        if service == 0 {
            godot_error!(
                "[AcceleratedOSR/Metal] No IOService found for registry ID {}",
                registry_id
            );
            return None;
        }

        let vendor_id = io_registry_search_property_u32(service, "vendor-id");
        let device_id = io_registry_search_property_u32(service, "device-id");

        IOObjectRelease(service);

        let name: Option<Retained<AnyObject>> = msg_send![device as &AnyObject, name];
        let name_str = name
            .map(|n| {
                let s: *const std::ffi::c_char = msg_send![&*n, UTF8String];
                if s.is_null() {
                    "Unknown".to_string()
                } else {
                    std::ffi::CStr::from_ptr(s).to_string_lossy().into_owned()
                }
            })
            .unwrap_or_else(|| "Unknown".to_string());

        match (vendor_id, device_id) {
            (Some(vendor), Some(device_id_val)) => {
                godot_print!(
                    "[AcceleratedOSR/Metal] Godot GPU: vendor=0x{:04x}, device=0x{:04x}, name={}",
                    vendor,
                    device_id_val,
                    name_str
                );
                Some((vendor, device_id_val))
            }
            _ => {
                // On Apple Silicon, there are no PCI vendor-id/device-id properties because
                // the GPU is integrated into the SoC, not a discrete PCI device.
                // This is fine - Apple Silicon Macs have only one GPU, so GPU pinning
                // is unnecessary (CEF will always use the same GPU as Godot).
                godot_print!(
                    "[AcceleratedOSR/Metal] GPU '{}' has no PCI vendor/device IDs (expected on Apple Silicon). \
                         GPU pinning not needed on single-GPU systems.",
                    name_str
                );
                None
            }
        }
    }
}

pub fn detect() -> Self {
    let rs = RenderingServer::singleton();
    let driver_name = rs.get_current_rendering_driver_name().to_string();
    let driver_lower = driver_name.to_lowercase();

    let backend = if driver_lower.contains("metal") {
        RenderBackend::Metal
    } else if driver_lower.contains("vulkan") {
        RenderBackend::Vulkan
    } else if driver_lower.contains("d3d12") {
        RenderBackend::D3D12
    } else if driver_lower.contains("opengl") || driver_lower.contains("gl_") {
        RenderBackend::OpenGL
    } else {
        RenderBackend::Unknown
    };

    godot_print!(
        "[AcceleratedOSR] Detected render backend: {:?} (driver: {})",
        backend,
        driver_name
    );

    backend
}

fn rendering_device() -> Result<Gd<RenderingDevice>, String> {
    RenderingServer::singleton()
        .get_rendering_device()
        .ok_or_else(|| "RenderingDevice unavailable for snapshot publication".to_string())
}

fn create_texture(
    rd: &mut RenderingDevice,
    width: u32,
    height: u32,
    snapshot_format: SnapshotFormat,
) -> Result<Rid, String> {
    let mut format = RdTextureFormat::new_gd();
    format.set_format(snapshot_format.rd_format());
    format.set_width(width);
    format.set_height(height);
    format.set_depth(1);
    format.set_array_layers(1);
    format.set_mipmaps(1);
    format.set_texture_type(TextureType::TYPE_2D);
    format.set_samples(TextureSamples::SAMPLES_1);
    // Bootstrap uses an initial zero upload, avoiding sRGB RTV/UAV clears.
    format.set_usage_bits(
        TextureUsageBits::CAN_COPY_FROM_BIT
            | TextureUsageBits::CAN_COPY_TO_BIT
            | TextureUsageBits::CAN_UPDATE_BIT,
    );
    let rid = rd.texture_create(&format, &RdTextureView::new_gd());
    if rid.is_valid() {
        Ok(rid)
    } else {
        Err(format!(
            "Failed to create snapshot texture {width}x{height}"
        ))
    }
}

fn read_completion(
    rd: &mut RenderingDevice,
    shared: &SharedPublication,
    token: SnapshotToken,
    sentinel: Rid,
    bootstrap: bool,
) -> Result<(), String> {
    let shared = Arc::clone(shared);
    let mut pending = Some(PendingReadback::new());
    let callback = Callable::from_sync_fn("cef_snapshot_complete", move |args: &[&Variant]| {
        let valid = args
            .first()
            .and_then(|arg| arg.try_to::<PackedByteArray>().ok())
            .is_some_and(|bytes| bytes.len() == 4);
        // Godot currently invokes this after its frame fence on the rendering
        // thread. Route through its public thread API so cleanup retains that
        // contract even if callback dispatch changes in a later engine version.
        let completion = Arc::clone(&shared);
        let mut pending_completion = pending.take();
        RenderingServer::singleton().call_on_render_thread(&Callable::from_sync_fn(
            "cef_snapshot_reclaim",
            move |_: &[&Variant]| {
                if let Ok(mut publication) = completion.lock() {
                    if valid {
                        if bootstrap {
                            publication.pool.bootstrap_complete(token);
                        } else {
                            publication.pool.publication_complete(token);
                        }
                    } else {
                        publication.pool.fail(token);
                        godot_error!(
                            "[AcceleratedOSR] Invalid snapshot completion; slot quarantined"
                        );
                    }
                }
                collect_retired(&completion);
                // Keep the registration until retirement work itself completes.
                // The guard also accounts for rejected/dropped callbacks.
                drop(pending_completion.take());
            },
        ));
    });
    check(
        rd.texture_get_data_async(sentinel, 0, &callback),
        "snapshot readback",
    )
}

pub(crate) fn get_godot_gpu_device_ids_vulkan(vulkan_lib_name: &str) -> Option<(u32, u32)> {
    use ash::vk;
    use godot::classes::RenderingServer;
    use godot::classes::rendering_device::DriverResource;
    use godot::global::{godot_error, godot_print};
    use godot::prelude::*;

    let rd = RenderingServer::singleton().get_rendering_device()?;

    let physical_device_ptr =
        rd.get_driver_resource(DriverResource::PHYSICAL_DEVICE, Rid::Invalid, 0);
    if physical_device_ptr == 0 {
        godot_error!(
            "[AcceleratedOSR/Vulkan] Failed to get Vulkan physical device for GPU ID query"
        );
        return None;
    }
    let physical_device: vk::PhysicalDevice = unsafe { std::mem::transmute(physical_device_ptr) };

    let lib = match unsafe { libloading::Library::new(vulkan_lib_name) } {
        Ok(lib) => lib,
        Err(e) => {
            godot_error!(
                "[AcceleratedOSR/Vulkan] Failed to load {} for GPU ID query: {}",
                vulkan_lib_name,
                e
            );
            return None;
        }
    };

    type GetPhysicalDeviceProperties2 = unsafe extern "system" fn(
        physical_device: vk::PhysicalDevice,
        p_properties: *mut vk::PhysicalDeviceProperties2<'_>,
    );

    let get_physical_device_properties2: GetPhysicalDeviceProperties2 = unsafe {
        match lib.get(b"vkGetPhysicalDeviceProperties2\0") {
            Ok(f) => *f,
            Err(e) => {
                godot_error!(
                    "[AcceleratedOSR/Vulkan] Failed to get vkGetPhysicalDeviceProperties2: {}. \
                     Vulkan 1.1+ is required for GPU ID query.",
                    e
                );
                return None;
            }
        }
    };

    let mut props2 = vk::PhysicalDeviceProperties2::default();
    unsafe {
        get_physical_device_properties2(physical_device, &mut props2);
    }

    let vendor_id = props2.properties.vendor_id;
    let device_id = props2.properties.device_id;
    let device_name = unsafe {
        std::ffi::CStr::from_ptr(props2.properties.device_name.as_ptr())
            .to_string_lossy()
            .into_owned()
    };

    godot_print!(
        "[AcceleratedOSR/Vulkan] Godot GPU: vendor=0x{:04x}, device=0x{:04x}, name={}",
        vendor_id,
        device_id,
        device_name
    );

    Some((vendor_id, device_id))
}

pub fn new() -> Result<Self, String> {
    let rd = RenderingServer::singleton()
        .get_rendering_device()
        .ok_or("Failed to get RenderingDevice")?;
    let device_ptr = rd.get_driver_resource(DriverResource::LOGICAL_DEVICE, Rid::Invalid, 0);
    let queue_ptr = rd.get_driver_resource(DriverResource::COMMAND_QUEUE, Rid::Invalid, 0);
    // Godot retains its references; clone adds our own COM references.
    let device: ID3D12Device = unsafe { clone_native_interface(device_ptr) }?;
    let diagnostics = NativeDebugDiagnostics::new(&device);
    let godot_queue = godot_command_queue(queue_ptr, &device)?;
    if unsafe { godot_queue.GetDesc() }.Type != D3D12_COMMAND_LIST_TYPE_DIRECT {
        return Err("Godot's main D3D12 queue is not a direct queue".into());
    }
    let capture_queue: ID3D12CommandQueue = unsafe {
        device.CreateCommandQueue(&D3D12_COMMAND_QUEUE_DESC {
            Type: D3D12_COMMAND_LIST_TYPE_DIRECT,
            ..Default::default()
        })
    }
    .map_err(|e| format!("CreateCommandQueue failed: {e}"))?;
    let capture_fence = unsafe { device.CreateFence(0, D3D12_FENCE_FLAG_NONE) }
        .map_err(|e| format!("Create capture fence failed: {e}"))?;
    let fence_event = FenceEvent(
        unsafe { CreateEventW(None, false, false, None) }
            .map_err(|e| format!("Create fence event failed: {e}"))?,
    );

    // This matches Godot 4.6's D3D12 feature selection. Enhanced and legacy
    // COPY_SOURCE are NOT interchangeable: interop requires a COMMON bridge.
    // https://github.com/godotengine/godot/blob/89cea143987d564363e15d207438530651d943ac/drivers/d3d12/rendering_device_driver_d3d12.cpp#L5574-L5578
    // https://microsoft.github.io/DirectX-Specs/d3d/D3D12EnhancedBarriers.html#interop-with-legacy-resourcebarrier
    let mut options = D3D12_FEATURE_DATA_D3D12_OPTIONS12::default();
    let enhanced = unsafe {
        device.CheckFeatureSupport(
            D3D12_FEATURE_D3D12_OPTIONS12,
            &mut options as *mut _ as *mut c_void,
            size_of::<D3D12_FEATURE_DATA_D3D12_OPTIONS12>() as u32,
        )
    }
    .is_ok()
        && options.EnhancedBarriersSupported.as_bool();
    let enhanced_bridge = if enhanced {
        Some(EnhancedBridge::new(&device)?)
    } else {
        None
    };

    let copy = NativeCopyList::new(&device)?;
    godot_print!(
        "[AcceleratedOSR/D3D12] Synchronous staging capture (enhanced barriers: {})",
        enhanced
    );
    Ok(Self {
        device,
        copy,
        capture_queue,
        godot_queue,
        capture_fence,
        fence_value: 0,
        fence_event,
        enhanced_bridge,
        diagnostics,
    })
}

fn new(device: &ID3D12Device) -> Option<Self> {
    let queue = device.cast::<ID3D12InfoQueue>().ok()?;
    let callback = queue.cast::<ID3D12InfoQueue1>().ok().and_then(|queue| {
        let mut cookie = 0;
        unsafe {
            queue.RegisterMessageCallback(
                Some(native_debug_message),
                D3D12_MESSAGE_CALLBACK_IGNORE_FILTERS,
                std::ptr::null_mut(),
                &mut cookie,
            )
        }
        .ok()
        .map(|()| (queue, cookie))
    });
    godot_print!(
        "[AcceleratedOSR/D3D12] Debug layer confirmed: ID3D12InfoQueue available; diagnostics {}",
        if callback.is_some() {
            "callback"
        } else {
            "polling"
        }
    );
    Some(Self {
        queue,
        callback,
        next_message: AtomicU64::new(0),
        discarded_messages: AtomicU64::new(0),
    })
}

pub fn get_godot_gpu_device_ids() -> Option<(u32, u32)> {
    let rd = RenderingServer::singleton().get_rendering_device()?;
    let device_ptr = rd.get_driver_resource(DriverResource::LOGICAL_DEVICE, Rid::Invalid, 0);
    let device: ID3D12Device = unsafe { clone_native_interface(device_ptr) }.ok()?;
    let target_luid: LUID = unsafe { device.GetAdapterLuid() };
    let factory: IDXGIFactory = unsafe { CreateDXGIFactory() }.ok()?;
    let mut adapter_index = 0u32;
    while let Ok(adapter) = unsafe { factory.EnumAdapters(adapter_index) } {
        let adapter: IDXGIAdapter = adapter;
        adapter_index += 1;
        let Ok(desc) = (unsafe { adapter.GetDesc() }) else {
            continue;
        };
        if desc.AdapterLuid.HighPart == target_luid.HighPart
            && desc.AdapterLuid.LowPart == target_luid.LowPart
        {
            return Some((desc.VendorId, desc.DeviceId));
        }
    }
    None
}

impl GodotTextureImporter {
    /// Called exclusively during initialization on Godot's rendering thread.
    pub fn new() -> Result<Self, String> {
        let importer = match RenderBackend::detect() {
            RenderBackend::D3D12 => Self::D3D12(d3d12::D3D12TextureImporter::new()?),
            RenderBackend::Vulkan => Self::Vulkan(Box::new(vulkan::VulkanTextureImporter::new()?)),
            _ => return Err("Accelerated OSR requires D3D12 or Vulkan on Windows".into()),
        };
        godot_print!("[AcceleratedOSR] Initialized synchronous native snapshot capture");
        Ok(importer)
    }

    pub fn capture(
        &mut self,
        info: &cef::AcceleratedPaintInfo,
        target: NativeCaptureTarget,
    ) -> Result<(), String> {
        match self {
            Self::D3D12(importer) => importer.capture(info, target),
            Self::Vulkan(importer) => importer.capture(info, target),
        }
    }

    pub fn prepare_publication(&self) -> Result<(), String> {
        match self {
            Self::D3D12(importer) => importer.prepare_publication(),
            Self::Vulkan(importer) => importer.prepare_publication(),
        }
    }
}

pub fn new() -> Result<Self, String> {
    let rd = RenderingServer::singleton()
        .get_rendering_device()
        .ok_or("Failed to get RenderingDevice")?;
    let device_handle = rd.get_driver_resource(DriverResource::LOGICAL_DEVICE, Rid::Invalid, 0);
    let instance_handle =
        rd.get_driver_resource(DriverResource::TOPMOST_OBJECT, Rid::Invalid, 0);
    let physical_handle =
        rd.get_driver_resource(DriverResource::PHYSICAL_DEVICE, Rid::Invalid, 0);
    let queue_handle = rd.get_driver_resource(DriverResource::COMMAND_QUEUE, Rid::Invalid, 0);
    let queue_family_index =
        rd.get_driver_resource(DriverResource::QUEUE_FAMILY, Rid::Invalid, 0) as u32;
    if [
        device_handle,
        instance_handle,
        physical_handle,
        queue_handle,
    ]
    .contains(&0)
    {
        return Err(
            "Godot did not expose its Vulkan device, instance, physical device, or queue"
                .into(),
        );
    }
    let entry = unsafe { ash::Entry::load_from("vulkan-1.dll") }
        .map_err(|e| format!("Load Vulkan entry points failed: {e}"))?;
    let instance = unsafe {
        ash::Instance::load(entry.static_fn(), vk::Instance::from_raw(instance_handle))
    };
    let device =
        unsafe { ash::Device::load(instance.fp_v1_0(), vk::Device::from_raw(device_handle)) };
    let godot_queue = vk::Queue::from_raw(queue_handle);
    let queue = crate::vulkan_hook::queue_sync::choose_capture_queue(
        device.handle(),
        godot_queue,
        queue_family_index,
    )?;
    if unsafe {
        instance.get_device_proc_addr(
            device.handle(),
            c"vkGetMemoryWin32HandlePropertiesKHR".as_ptr(),
        )
    }
    .is_none()
    {
        return Err("VK_KHR_external_memory_win32 is not enabled on Godot's device".into());
    }
    let external_memory = ash::khr::external_memory_win32::Device::new(&instance, &device);
    let physical_device = vk::PhysicalDevice::from_raw(physical_handle);
    let pool_info = vk::CommandPoolCreateInfo::default()
        .queue_family_index(queue_family_index)
        .flags(vk::CommandPoolCreateFlags::RESET_COMMAND_BUFFER);
    let command_pool = unsafe { device.create_command_pool(&pool_info, None) }
        .map_err(|e| format!("Create capture command pool failed: {e:?}"))?;
    let allocation = vk::CommandBufferAllocateInfo::default()
        .command_pool(command_pool)
        .level(vk::CommandBufferLevel::PRIMARY)
        .command_buffer_count(1);
    let command_buffer = match unsafe { device.allocate_command_buffers(&allocation) } {
        Ok(buffers) => buffers[0],
        Err(error) => {
            unsafe { device.destroy_command_pool(command_pool, None) };
            return Err(format!("Allocate capture command buffer failed: {error:?}"));
        }
    };
    let fence_info = vk::FenceCreateInfo::default().flags(vk::FenceCreateFlags::SIGNALED);
    let fence = match unsafe { device.create_fence(&fence_info, None) } {
        Ok(fence) => fence,
        Err(error) => {
            unsafe { device.destroy_command_pool(command_pool, None) };
            return Err(format!("Create capture fence failed: {error:?}"));
        }
    };
    Ok(Self {
        device,
        instance,
        physical_device,
        external_memory,
        command_pool,
        command_buffer,
        fence,
        queue,
        godot_queue,
        queue_family_index,
        publication_bridges: VecDeque::with_capacity(MAX_PENDING_PUBLICATION_BRIDGES),
        captured: false,
        _entry: entry,
    })
}

pub enum RenderMode {
    /// Software rendering using a CPU frame buffer.
    Software {
        /// Shared frame buffer containing RGBA pixel data.
        frame_buffer: Arc<Mutex<FrameBuffer>>,
        /// Godot ImageTexture for display.
        texture: Gd<ImageTexture>,
    },
    /// GPU-accelerated rendering using platform-specific shared textures.
    #[cfg(any(target_os = "macos", target_os = "windows", target_os = "linux"))]
    Accelerated {
        /// Shared render state containing importer and pending copy tracking.
        /// This is shared with the render handler for immediate GPU copy in on_accelerated_paint.
        render_state: Arc<Mutex<AcceleratedRenderState>>,
        /// The Texture2DRD wrapper for display in TextureRect.
        texture_2d_rd: Gd<Texture2Drd>,
    },
}

impl RenderMode {
    pub fn texture_2d(&self) -> Gd<Texture2D> {
        match self {
            Self::Software { texture, .. } => texture.clone().upcast(),
            #[cfg(any(target_os = "macos", target_os = "windows", target_os = "linux"))]
            Self::Accelerated { texture_2d_rd, .. } => texture_2d_rd.clone().upcast(),
        }
    }
}

fn should_enable_remote_debugging() -> bool {
    let os = Os::singleton();
    let engine = Engine::singleton();

    let is_debug_build = os.is_debug_build();
    let is_editor_hint = engine.is_editor_hint();

    is_debug_build || is_editor_hint
}

pub(crate) fn ensure_installed() -> Result<(), String> {
    let os = Os::singleton();
    if os.get_thread_caller_id() != os.get_main_thread_id() {
        return Err("CEF must be initialized on Godot's main thread".into());
    }

    let mut tree = Engine::singleton()
        .get_main_loop()
        .and_then(|main_loop| main_loop.try_cast::<SceneTree>().ok())
        .ok_or("CEF's external message pump requires a SceneTree main loop")?;

    CONNECTION.with_borrow_mut(|connection| {
        if connection.as_ref().is_some_and(|existing| {
            existing.tree_id == tree.instance_id()
                && tree.is_connected("process_frame", &existing.callable)
        }) {
            return Ok(());
        }

        if let Some(previous) = connection.take() {
            disconnect(previous);
        }

        // from_fn is bound to the creating thread. No Godot callable is invoked
        // by OnScheduleMessagePumpWork, which only touches the Rust scheduler.
        let callable = Callable::from_fn("gdcef_message_pump", |_| {
            crate::permissions::expire_pending();
            crate::dialogs::expire_pending();
            MESSAGE_PUMP.run_due(cef::do_message_loop_work);
        });
        let error = tree.connect("process_frame", &callable);
        if error != godot::global::Error::OK {
            return Err(format!("Failed to connect CEF's message pump: {error:?}"));
        }
        *connection = Some(PumpConnection {
            tree_id: tree.instance_id(),
            callable,
        });
        Ok(())
    })
}

fn build_adblock_engine(log_prefix: &str) -> Option<Rc<adblock::Engine>> {
    if !crate::settings::is_adblock_enabled() {
        return None;
    }

    let Some(rules_path) = crate::settings::get_adblock_rules_path() else {
        godot::global::godot_warn!(
            "[{}] Adblock is enabled, but adblock rules path setting is empty. Request filtering will be disabled.",
            log_prefix
        );
        return None;
    };

    let rules = match fs::read_to_string(&rules_path) {
        Ok(content) => content,
        Err(error) => {
            godot::global::godot_warn!(
                "[{}] Failed to read adblock rules file '{}': {}. Request filtering will be disabled.",
                log_prefix,
                rules_path.display().to_string(),
                error
            );
            return None;
        }
    };

    let mut filter_set = FilterSet::new(true);
    let _metadata = filter_set.add_filter_list(rules, ParseOptions::default());
    godot::global::godot_print!("[{}] Adblock filter list loaded.", log_prefix);
    Some(Rc::new(adblock::Engine::new_with_filter_set(filter_set)))
}

pub(crate) fn should_use_accelerated_osr(enable_accelerated_osr: bool, log_prefix: &str) -> bool {
    if !enable_accelerated_osr {
        godot::global::godot_print!(
            "[{}] Accelerated OSR disabled by `enable_accelerated_osr = false`; using software rendering",
            log_prefix
        );
        return false;
    }

    let (supported, reason) = accelerated_osr::accelerated_osr_support_diagnostic();
    if !supported {
        godot::global::godot_warn!(
            "[{}] Accelerated OSR unavailable: {}. Falling back to software rendering.",
            log_prefix,
            reason
        );
    }
    supported
}

pub(crate) fn get_max_fps() -> i32 {
    let setting_fps = crate::settings::get_max_frame_rate();
    if setting_fps > 0 {
        return setting_fps;
    }

    let engine_cap_fps = Engine::singleton().get_max_fps();
    let screen_cap_fps = DisplayServer::singleton().screen_get_refresh_rate().round() as i32;
    if engine_cap_fps > 0 {
        engine_cap_fps
    } else if screen_cap_fps > 0 {
        screen_cap_fps
    } else {
        60
    }
}

pub(crate) fn update_primary_texture(
    state: &mut BrowserState,
    _log_prefix: &str,
) -> Option<Gd<Texture2Drd>> {
    if let RenderMode::Software {
        frame_buffer,
        texture,
    } = &mut state.render_mode
    {
        let Ok(mut fb) = frame_buffer.lock() else {
            return None;
        };

        let popup_metadata = state.popup_state.lock().ok().and_then(|popup| {
            if popup.visible && !popup.buffer.is_empty() {
                Some((
                    popup.width,
                    popup.height,
                    popup.rect.x,
                    popup.rect.y,
                    popup.dirty,
                ))
            } else {
                None
            }
        });

        let popup_dirty = popup_metadata
            .as_ref()
            .is_some_and(|(_, _, _, _, dirty)| *dirty);

        if !fb.dirty && !popup_dirty {
            return None;
        }

        if fb.data.is_empty() {
            return None;
        }

        let width = fb.width as i32;
        let height = fb.height as i32;
        let display_scale = get_display_scale_factor();

        let final_data =
            if let Some((popup_width, popup_height, popup_x, popup_y, _)) = popup_metadata {
                let popup_buffer = state
                    .popup_state
                    .lock()
                    .ok()
                    .map(|popup| popup.buffer.clone());

                if let Some(popup_buffer) = popup_buffer {
                    let mut composited = fb.data.clone();
                    let scaled_x = (popup_x as f32 * display_scale) as i32;
                    let scaled_y = (popup_y as f32 * display_scale) as i32;
                    composite_popup(
                        &mut DestBuffer {
                            data: &mut composited,
                            width: fb.width,
                            height: fb.height,
                        },
                        &PopupBuffer {
                            data: &popup_buffer,
                            width: popup_width,
                            height: popup_height,
                            x: scaled_x,
                            y: scaled_y,
                        },
                    );
                    if let Ok(mut popup) = state.popup_state.lock() {
                        popup.mark_clean();
                    }
                    composited
                } else {
                    fb.data.clone()
                }
            } else {
                fb.data.clone()
            };

        let byte_array = PackedByteArray::from(final_data.as_slice());
        let image: Option<Gd<Image>> =
            Image::create_from_data(width, height, false, ImageFormat::RGBA8, &byte_array);
        if let Some(image) = image {
            texture.set_image(&image);
        }

        fb.mark_clean();
        return None;
    }

    #[cfg(any(target_os = "macos", target_os = "windows", target_os = "linux"))]
    if let RenderMode::Accelerated {
        render_state,
        texture_2d_rd,
    } = &mut state.render_mode
    {
        let rid = match render_state.lock() {
            Ok(state) => state.dst_rd_rid,
            Err(_) => return None,
        };
        let replacement = if rid.is_valid() && texture_2d_rd.get_texture_rd_rid() != rid {
            // All retained references must leave the old RD resource before its
            // publication generation can retire. Keep the wrapper stable across
            // resizes, just as the standalone CefTexture2D resource does.
            texture_2d_rd.set_texture_rd_rid(rid);
            Some(texture_2d_rd.clone())
        } else {
            None
        };
        if let Ok(mut state) = render_state.lock() {
            state.acknowledge_view(rid);
        }
        return replacement;
    }

    None
}

pub(crate) fn cleanup_runtime(app: &mut App, popup_texture_2d_rd: Option<&mut Gd<Texture2Drd>>) {
    if app.state.is_none() {
        app.mark_browser_closed();
        app.release_cef_if_retained();
        return;
    }
    app.mark_browser_closing();
    if let Some(state) = &app.state {
        if let Ok(mut drag) = state.source_drag.lock() {
            drag.enabled = false;
        }
        state.finish_source_drag(None, None, 0);
    }

    if let Some(state) = &app.state {
        state.permissions.close("browser_closed");
        state.dialogs.close("browser_closed");
    }

    if let Some(state) = &app.state
        && let Some(audio) = &state.audio
    {
        audio.shutdown_flag.store(true, Ordering::Relaxed);
    }

    #[cfg(any(target_os = "macos", target_os = "windows", target_os = "linux"))]
    if let Some(state) = &mut app.state
        && let RenderMode::Accelerated {
            render_state,
            texture_2d_rd,
        } = &mut state.render_mode
    {
        texture_2d_rd.set_texture_rd_rid(Rid::Invalid);
        if let Some(popup_texture_2d_rd) = popup_texture_2d_rd {
            popup_texture_2d_rd.set_texture_rd_rid(Rid::Invalid);
        }
        AcceleratedRenderState::shutdown(render_state);
    }

    if let Some(state) = app.state.take()
        && let Some(host) = state.browser.host()
    {
        host.close_browser(true as _);
    }

    app.clear_runtime_state();
    app.mark_browser_closed();
    app.release_cef_if_retained();
}

fn create_software_browser(
    app: &mut App,
    browser_settings: &BrowserSettings,
    context: Option<&mut cef::RequestContext>,
    params: BrowserCreateParams,
    software_target_texture: Option<Gd<ImageTexture>>,
    log_prefix: &str,
) -> Result<(), CefError> {
    let BrowserCreateParams {
        dpi,
        pixel_width,
        pixel_height,
        url,
        preload_script,
        popup_policy,
        permission_policy,
        dialog_policy,
    } = params;
    godot::global::godot_print!(
        "[{}] Creating browser in software rendering mode",
        log_prefix
    );
    let window_info = WindowInfo {
        bounds: cef::Rect {
            x: 0,
            y: 0,
            width: pixel_width,
            height: pixel_height,
        },
        windowless_rendering_enabled: true as _,
        shared_texture_enabled: false as _,
        external_begin_frame_enabled: true as _,
        ..Default::default()
    };

    let render_handler = cef_app::OsrRenderHandler::new(
        dpi,
        PhysicalSize::new(pixel_width as f32, pixel_height as f32),
    );
    let frame_buffer = render_handler.get_frame_buffer();
    let render_size = render_handler.get_size();
    let device_scale_factor = render_handler.get_device_scale_factor();
    let cursor_type = render_handler.get_cursor_type();
    let popup_state: PopupStateQueue = render_handler.get_popup_state();
    let sample_rate = AudioServer::singleton().get_mix_rate();
    let enable_audio_capture = crate::settings::is_audio_capture_enabled();
    let queues = webrender::ClientQueues::new(
        sample_rate,
        enable_audio_capture,
        permission_policy,
        dialog_policy,
    );

    let mut texture = software_target_texture.unwrap_or_else(ImageTexture::new_gd);
    // Avoid Godot's magenta placeholder while waiting for the first CEF paint.
    let initial_bytes =
        vec![0u8; (pixel_width.max(1) as usize) * (pixel_height.max(1) as usize) * 4];
    let initial_byte_array = PackedByteArray::from(initial_bytes.as_slice());
    if let Some(initial_image) = Image::create_from_data(
        pixel_width.max(1),
        pixel_height.max(1),
        false,
        ImageFormat::RGBA8,
        &initial_byte_array,
    ) {
        texture.set_image(&initial_image);
    }

    let cef_render_handler = webrender::SoftwareOsrHandler::build(
        render_handler,
        queues.event_queues.clone(),
        queues.source_drag.clone(),
    );
    let mut client = webrender::CefClientImpl::build(
        cef_render_handler,
        cursor_type.clone(),
        queues.clone(),
        popup_policy.clone(),
    );
    let mut extra_info = build_browser_extra_info(preload_script.as_deref())?;
    let cef_url: CefStringUtf16 = url.as_str().into();

    let browser = cef::browser_host_create_browser_sync(
        Some(&window_info),
        Some(&mut client),
        Some(&cef_url),
        Some(browser_settings),
        Some(&mut extra_info),
        context,
    )
    .ok_or_else(|| {
        queues.permissions.close("browser_closed");
        queues.dialogs.close("browser_closed");
        CefError::BrowserCreationFailed("browser_host_create_browser_sync returned None".into())
    })?;

    let event_queues = queues.event_queues.clone();
    let source_drag = queues.source_drag.clone();
    let permissions = queues.permissions.clone();
    let dialogs = queues.dialogs.clone();
    app.state = Some(BrowserState {
        browser,
        render_mode: RenderMode::Software {
            frame_buffer,
            texture,
        },
        render_size,
        device_scale_factor,
        cursor_type,
        popup_state,
        event_queues,
        audio: queues.into_audio_state(),
        source_drag,
        popup_policy,
        permissions,
        dialogs,
    });

    Ok(())
}

pub(super) fn cleanup_instance(&mut self) {
    self.base_mut().set_visible(false);
    let mut popup_texture_2d_rd = self.popup_texture_2d_rd.take();
    self.with_app_mut(|app| backend::cleanup_runtime(app, popup_texture_2d_rd.as_mut()));
    self.popup_texture_2d_rd = popup_texture_2d_rd;

    self.ime_active = false;
    self.ime_proxy = None;
    self.focus_state = Default::default();
    self.focus_reconcile_pending = false;
    self.pointer_state = Default::default();

    if let Some(mut overlay) = self.popup_overlay.take() {
        overlay.queue_free();
    }
    self.popup_texture = None;

    #[cfg(any(target_os = "macos", target_os = "windows", target_os = "linux"))]
    {
        self.popup_texture_2d_rd = None;
    }

    self.log_cleanup_state_violations();
}

pub(super) fn try_create_browser(&mut self) -> Result<(), CefError> {
    self.reconcile_browser_visibility();
    if self.with_app(|app| app.state.is_some()) {
        return Ok(());
    }
    if !self.with_app_mut(|app| app.begin_browser_create()) {
        return Ok(());
    }

    let logical_size = self.base().get_size();
    let dpi = self.get_pixel_scale_factor();
    let max_fps = self.get_max_fps();
    let params = backend::BackendCreateParams {
        logical_size,
        dpi,
        max_fps,
        url: self.url.to_string(),
        enable_accelerated_osr: self.enable_accelerated_osr,
        background_color: self.background_color,
        popup_policy: self.popup_policy,
        permission_policy: self.permission_policy,
        dialog_policy: self.dialog_policy,
        preload_script: self.preload_script.to_string(),
        preload_script_path: self.preload_script_path.to_string(),
        software_target_texture: None,
        log_prefix: "CefTexture",
    };
    if let Err(err) = self.with_app_mut(|app| backend::try_create_browser(app, &params)) {
        self.with_app_mut(|app| app.mark_browser_closed());
        return Err(err);
    }
    self.with_app_mut(|app| app.mark_browser_running());
    self.focus_state.invalidate_host_focus();
    if let Some(texture) =
        self.with_app(|app| app.state.as_ref().map(|s| s.render_mode.texture_2d()))
    {
        self.base_mut().set_texture(&texture);
    }

    self.last_size = logical_size;
    self.last_dpi = dpi;
    Ok(())
}

