pub(super) fn create_ime_proxy(&mut self) {
    let mut line_edit = LineEdit::new_alloc();
    line_edit.set_position(Vector2::new(-10000.0, -10000.0));
    line_edit.set_size(Vector2::new(200.0, 30.0));
    line_edit.set_mouse_filter(MouseFilter::IGNORE);
    line_edit.set_focus_mode(FocusMode::ALL);
    // Keep the proxy in edit mode across `ui_text_submit`. The proxy is
    // hidden and never meant to submit anything, but the page's Enter is
    // forwarded to it, and LineEdit leaves edit mode on that action
    // (`unedit()`), after which `gui_input` drops every key event because of
    // its `if (!editing) return;` guard. The host would then report focus and
    // editability as healthy while no text could reach the page, until a
    // mouse click re-entered edit mode.
    line_edit.set_keep_editing_on_text_submit(true);
    let callable_changed = self.base().callable("on_ime_proxy_text_changed");
    line_edit.connect("text_changed", &callable_changed);

    let callable_focus_changed = self.base().callable("on_ime_proxy_focus_exited");
    line_edit.connect("focus_entered", &callable_focus_changed);
    line_edit.connect("focus_exited", &callable_focus_changed);

    self.base_mut().add_child(&line_edit);
    self.ime_proxy = Some(line_edit);
}

pub(super) fn process_ime_position(&mut self) {
    if self.ime_active {
        let mut ds: Gd<DisplayServer> = DisplayServer::singleton();
        let display_scale = get_display_scale_factor();
        let pixel_scale = self.get_pixel_scale_factor();

        let rect = self.base().get_viewport_rect();
        let viewport_scaled =
            Vector2::new(rect.size.x * pixel_scale, rect.size.y * pixel_scale);
        let Some(window) = self.base().get_window() else {
            return;
        };
        let window_size = window.get_size();
        let viewport_offset = Vector2::new(
            (window_size.x as f32 - viewport_scaled.x) / 2.0 / pixel_scale,
            (window_size.y as f32 - viewport_scaled.y) / 2.0 / pixel_scale,
        );

        let node_offset = Vector2::new(
            self.base().get_global_position().x,
            self.base().get_global_position().y,
        );

        let final_ime_position = Vector2i::new(
            (self.ime_position.x as f32 * display_scale
                + (viewport_offset.x + node_offset.x) * pixel_scale) as i32,
            (self.ime_position.y as f32 * display_scale
                + (viewport_offset.y + node_offset.y) * pixel_scale) as i32,
        );

        ds.window_set_ime_position(final_ime_position);
    }
}

pub(super) fn defer_browser_focus_update(&mut self) {
    if self.focus_reconcile_pending {
        return;
    }
    self.focus_reconcile_pending = true;
    // Focus-exited is emitted before Godot assigns the new owner. Inspect
    // the settled owner, never the transient gap during a proxy transfer.
    self.base_mut()
        .call_deferred("_check_ime_focus_after_exit", &[]);
}

pub(super) fn browser_focus_owner(&self) -> FocusOwner {
    if !self.base().is_inside_tree() {
        return FocusOwner::Outside;
    }
    if let Some(viewport) = self.base().get_viewport()
        && let Some(focused) = viewport.gui_get_focus_owner()
    {
        let self_control = self.base().clone().upcast::<Control>();
        if focused == self_control {
            return FocusOwner::Browser;
        }
        if self
            .ime_proxy
            .as_ref()
            .is_some_and(|proxy| focused == proxy.clone().upcast::<Control>())
        {
            return FocusOwner::Proxy;
        }
    }
    FocusOwner::Outside
}

fn apply_browser_focus(&mut self, owner: FocusOwner, available: bool) {
    let Some(host) = self.with_app(|app| app.host()) else {
        // A future browser must receive focus even if the logical owner
        // has not changed since this node started processing.
        self.focus_state.invalidate_host_focus();
        self.ime_active = false;
        return;
    };
    let update = self.focus_state.reconcile(owner, available);
    // Clear composition before losing CEF focus, and never commit a late
    // proxy signal into whichever DOM element happens to be active later.
    if self.ime_active && !update.ime_active {
        host.ime_cancel_composition();
        if let Some(proxy) = self.ime_proxy.as_mut() {
            proxy.set_text("");
        }
    }
    self.ime_active = update.ime_active;

    if let Some(focused) = update.cef_focus {
        host.set_focus(focused as _);
    }

    match update.transfer {
        Some(FocusOwner::Proxy) => {
            // grab_focus performs the transfer. Do not separately release
            // the browser control and publish a spurious CEF blur.
            if let Some(mut proxy) = self.ime_proxy.clone() {
                // This can synchronously notify the parent control. Keep
                // its Rust borrow suspended while Godot transfers focus.
                let _guard = self.base_mut();
                proxy.grab_focus();
            }
        }
        Some(FocusOwner::Browser) => self.base_mut().grab_focus(),
        _ => {}
    }
}

pub(super) fn handle_os_ime_update(&mut self) {
    if !self.ime_active
        || !self.browser_input_available()
        || self.browser_focus_owner() != FocusOwner::Proxy
    {
        return;
    }

    let ime_text = DisplayServer::singleton().ime_get_text().to_string();
    let ime_selection = DisplayServer::singleton().ime_get_selection();
    let start = ime_selection.x.max(0) as u32;
    let end = ime_selection.y.max(0) as u32;

    // Update the IME composition text
    if let Some(host) = self.with_app(|app| app.host()) {
        input::ime_set_composition(&host, &ime_text, start, end);
    }
}

pub(super) fn handle_input_event(&mut self, event: Gd<InputEvent>) {
    let Ok(key) = event.try_cast::<InputEventKey>() else {
        return;
    };
    // Escape also cancels a source drag whose Godot adapter took focus.
    if key.is_pressed() && key.get_keycode() == Key::ESCAPE {
        self.cancel_browser_drag();
    }
    if !self.browser_input_available() || self.browser_focus_owner() == FocusOwner::Outside {
        return;
    }
    self.reconcile_browser_focus();
    let deliver_to_proxy = self.ime_active
        && crate::input::should_deliver_key_to_ime_proxy(
            key.get_keycode(),
            key.is_ctrl_pressed(),
            key.is_alt_pressed(),
            key.is_meta_pressed(),
        );
    self.texture2d_helper
        .bind()
        .forward_key_event(key, self.ime_active);
    // The proxy must receive normal Godot key/IME processing to produce
    // text_changed. The browser control has no such native text handler.
    if !deliver_to_proxy && let Some(mut viewport) = self.base().get_viewport() {
        viewport.set_input_as_handled();
    }
}

pub(super) fn handle_gui_input_event(&mut self, event: Gd<InputEvent>) {
    if !self.browser_input_available() {
        return;
    }
    let pixel_scale = self.get_pixel_scale_factor();
    let device_scale = self.get_device_scale_factor();

    // Unlike _input, _gui_input is hit-tested, respects mouse_filter and
    // follows Godot's mouse/touch capture. Positions already include canvas,
    // rotation and scale transforms. Never mutate the incoming event.
    if let Ok(button) = event.clone().try_cast::<InputEventMouseButton>() {
        self.last_pointer_position = button.get_position();
        let mask = match button.get_button_index() {
            MouseButton::LEFT => 1,
            MouseButton::RIGHT => 2,
            MouseButton::MIDDLE => 4,
            _ => 0,
        };
        let leave = self.pointer_state.button(mask, button.is_pressed());
        // Godot focuses the control before delivering a click. Apply CEF
        // focus before forwarding it without publishing an internal blur.
        self.reconcile_browser_focus();
        self.texture2d_helper.bind().forward_mouse_button_event(
            button,
            pixel_scale,
            device_scale,
        );
        if leave {
            self.send_browser_mouse_leave();
        }
    } else if let Ok(motion) = event.clone().try_cast::<InputEventMouseMotion>() {
        self.last_pointer_position = motion.get_position();
        self.pointer_state.motion();
        self.texture2d_helper.bind().forward_mouse_motion_event(
            motion,
            pixel_scale,
            device_scale,
        );
    } else if let Ok(pan) = event.clone().try_cast::<InputEventPanGesture>() {
        self.texture2d_helper
            .bind()
            .forward_pan_gesture_event(pan, pixel_scale, device_scale);
    } else if let Ok(touch) = event.clone().try_cast::<InputEventScreenTouch>() {
        if touch.is_pressed() {
            self.base_mut().grab_focus();
            self.reconcile_browser_focus();
        }
        self.texture2d_helper.bind_mut().forward_screen_touch_event(
            touch,
            pixel_scale,
            device_scale,
        );
    } else if let Ok(drag) = event.clone().try_cast::<InputEventScreenDrag>() {
        self.texture2d_helper.bind_mut().forward_screen_drag_event(
            drag,
            pixel_scale,
            device_scale,
        );
    } else if let Ok(magnify) = event.try_cast::<InputEventMagnifyGesture>() {
        self.texture2d_helper
            .bind()
            .forward_magnify_gesture_event(magnify);
    } else {
        // Keys were already routed through _input, including proxy input.
        return;
    }
    self.base_mut().accept_event();
}

#[derive(GodotClass)]
#[class(base=TextureRect)]
pub struct CefTexture {
    base: Base<TextureRect>,

    #[export]
    #[var(get = get_url_property, set = set_url_property)]
    /// The URL to load. Changing this triggers a navigation.
    /// Supported schemes: http://, https://, res://, user://
    url: GString,

    #[export]
    #[var(get = get_enable_accelerated_osr, set = set_enable_accelerated_osr)]
    /// Enable GPU-accelerated Off-Screen Rendering (OSR).
    /// If true, uses shared textures (Vulkan/D3D12/Metal) for high performance.
    /// If false, uses software rendering.
    enable_accelerated_osr: bool,

    #[export]
    #[var(get = get_background_color, set = set_background_color)]
    /// The background color of the browser view.
    /// Useful for transparent pages.
    background_color: Color,

    #[export]
    #[var(get = get_browser_hidden, set = set_browser_hidden)]
    /// Stop browser painting while keeping browser tasks and events active.
    browser_hidden: bool,

    #[export]
    #[var(get = get_pause_rendering_when_hidden, set = set_pause_rendering_when_hidden)]
    /// Also hide CEF when this control or an ancestor is not visible in the tree.
    pause_rendering_when_hidden: bool,

    #[export(enum = (Block = 0, Redirect = 1, SignalOnly = 2))]
    #[var(get = get_popup_policy, set = set_popup_policy)]
    /// Controls how popup windows (window.open, target="_blank") are handled.
    /// Block: suppress all popups silently (default).
    /// Redirect: navigate the current browser to the popup URL.
    /// SignalOnly: emit `popup_requested` signal and let GDScript decide.
    popup_policy: i32,

    #[export(enum = (ProjectDefault = -1, DenyAll = 0, AllowAll = 1, Signal = 2))]
    #[var(get = get_permission_policy, set = set_permission_policy)]
    /// Browser permission handling. ProjectDefault inherits the project setting at creation.
    permission_policy: i32,

    #[export(enum = (Native = 0, Signal = 1, Cancel = 2))]
    #[var(get = get_dialog_policy, set = set_dialog_policy)]
    /// Native CEF dialogs, application-owned asynchronous signals, or cancellation.
    dialog_policy: i32,

    #[export]
    #[var(get = get_preload_script, set = set_preload_script)]
    /// JavaScript source to inject into the main frame when its V8 context is created.
    preload_script: GString,

    #[export]
    #[var(get = get_preload_script_path, set = set_preload_script_path)]
    /// Godot file path containing JavaScript to inject as a preload script.
    preload_script_path: GString,

    #[var]
    /// Stores the IME cursor position in local coordinates (relative to this `CefTexture` node),
    /// automatically updated from the browser's caret position.
    ime_position: Vector2i,

    // Internal CefTexture2D helper for shared settings behavior.
    texture2d_helper: Gd<CefTexture2D>,
    // Change detection state
    last_size: Vector2,
    last_dpi: f32,
    // UI-only change detection state
    last_cursor: cef_app::CursorType,
    last_max_fps: i32,
    browser_create_deferred_pending: bool,
    frame_hook: Option<Callable>,

    // IME state
    ime_active: bool,
    ime_proxy: Option<Gd<LineEdit>>,
    focus_state: focus_state::FocusState,
    focus_reconcile_pending: bool,
    pointer_state: pointer_state::PointerState,
    last_pointer_position: Vector2,

    // Popup state
    popup_overlay: Option<Gd<TextureRect>>,
    popup_texture: Option<Gd<ImageTexture>>,
    #[cfg(any(target_os = "macos", target_os = "windows", target_os = "linux"))]
    popup_texture_2d_rd: Option<Gd<godot::classes::Texture2Drd>>,
    // Touch state

    // Find-in-page state
}

pub(super) fn handle_size_change(&mut self) -> bool {
    let logical_size = self.base().get_size();
    let dpi = self.get_pixel_scale_factor();
    let mut last_size = self.last_size;
    let mut last_dpi = self.last_dpi;
    let changed = self.with_app(|app| {
        backend::handle_size_change(app, &mut last_size, &mut last_dpi, logical_size, dpi)
    });
    self.last_size = last_size;
    self.last_dpi = last_dpi;
    changed
}

pub(super) fn update_texture(&mut self) {
    let should_bind_initial = self.base().get_texture().is_none();
    let initial_texture = if should_bind_initial {
        self.with_app(|app| {
            app.state
                .as_ref()
                .map(|state| state.render_mode.texture_2d())
        })
    } else {
        None
    };

    let replacement = self.with_app_mut(|app| {
        let Some(state) = &mut app.state else {
            return None;
        };
        backend::update_primary_texture(state, "CefTexture")
    });

    if let Some(tex) = replacement {
        self.base_mut().set_texture(&tex);
    } else if let Some(texture) = initial_texture {
        self.base_mut().set_texture(&texture);
    }

    #[cfg(any(target_os = "macos", target_os = "windows", target_os = "linux"))]
    {
        let popup_target = self.with_app(|app| {
            let state = app.state.as_ref()?;
            let RenderMode::Accelerated { render_state, .. } = &state.render_mode else {
                return None;
            };
            render_state.lock().ok()?.popup_rd_rid
        });
        if let Some(rid) = popup_target {
            let texture = self
                .popup_texture_2d_rd
                .get_or_insert_with(godot::classes::Texture2Drd::new_gd);
            if texture.get_texture_rd_rid() != rid {
                texture.set_texture_rd_rid(rid);
            }
            self.with_app(|app| {
                if let Some(state) = &app.state
                    && let RenderMode::Accelerated { render_state, .. } = &state.render_mode
                    && let Ok(mut state) = render_state.lock()
                {
                    state.acknowledge_popup(rid);
                }
            });
        }
    }
    self.update_popup_overlay();
    self.with_app(backend::queue_texture_publication);
}

#[cfg(any(target_os = "macos", target_os = "windows", target_os = "linux"))]
fn update_popup_overlay(&mut self) {
    let popup_visible_info = self.with_app(|app| {
        app.state.as_ref().and_then(|s| {
            s.popup_state.lock().ok().and_then(|popup| {
                if popup.visible {
                    Some((
                        popup.rect.x,
                        popup.rect.y,
                        popup.rect.width,
                        popup.rect.height,
                    ))
                } else {
                    None
                }
            })
        })
    });

    let accel_popup_info = self.with_app(|app| {
        app.state.as_ref().and_then(|s| {
            if let RenderMode::Accelerated { render_state, .. } = &s.render_mode {
                render_state.lock().ok().and_then(|state| {
                    if state.popup_rd_rid.is_some()
                        && state.popup_width > 0
                        && state.popup_height > 0
                    {
                        Some((
                            state.popup_dirty,
                            state.popup_has_content,
                            state.popup_width,
                            state.popup_height,
                        ))
                    } else {
                        None
                    }
                })
            } else {
                None
            }
        })
    });

    match (popup_visible_info, accel_popup_info) {
        (
            Some((x, y, _rect_w, _rect_h)),
            Some((popup_dirty, popup_has_content, tex_width, tex_height)),
        ) => {
            if self.popup_overlay.is_none() {
                let mut overlay = TextureRect::new_alloc();
                overlay.set_expand_mode(ExpandMode::IGNORE_SIZE);
                overlay.set_material(&Self::make_browser_material());
                overlay.set_mouse_filter(MouseFilter::IGNORE);
                let overlay_node: Gd<godot::classes::Node> = overlay.clone().upcast();
                self.base_mut().add_child(&overlay_node);
                self.popup_overlay = Some(overlay);
            }

            let display_scale = get_display_scale_factor();
            let cef_texture_size = self.base().get_size();
            let render_size = self.with_app(|app| {
                app.state
                    .as_ref()
                    .and_then(|s| s.render_size.lock().ok().map(|sz| (sz.width, sz.height)))
                    .unwrap_or((0.0, 0.0))
            });

            if let Some(overlay) = &mut self.popup_overlay {
                if let Some(texture_2d_rd) = &self.popup_texture_2d_rd {
                    overlay.set_texture(texture_2d_rd);
                }

                let scale_x = if render_size.0 > 0.0 {
                    cef_texture_size.x * display_scale / render_size.0
                } else {
                    display_scale
                };
                let scale_y = if render_size.1 > 0.0 {
                    cef_texture_size.y * display_scale / render_size.1
                } else {
                    display_scale
                };

                let local_x = x as f32 * scale_x;
                let local_y = y as f32 * scale_y;
                let local_width = tex_width as f32 * scale_x / display_scale;
                let local_height = tex_height as f32 * scale_y / display_scale;

                overlay.set_position(Vector2::new(local_x, local_y));
                overlay.set_size(Vector2::new(local_width, local_height));
                overlay.set_visible(popup_has_content);
            }

            if popup_dirty {
                self.with_app_mut(|app| {
                    if let Some(s) = app.state.as_ref()
                        && let RenderMode::Accelerated { render_state, .. } = &s.render_mode
                        && let Ok(mut rs) = render_state.lock()
                    {
                        rs.popup_dirty = false;

pub(super) fn update_cursor(&mut self) {
    let Some(current_cursor) = self.with_app(|app| {
        let state = app.state.as_ref()?;
        let cursor_type = state.cursor_type.lock().ok()?;
        Some(*cursor_type)
    }) else {
        return;
    };

    if current_cursor == self.last_cursor {
        return;
    }

    self.last_cursor = current_cursor;
    let shape = cursor::cursor_type_to_shape(current_cursor);
    self.base_mut().set_default_cursor_shape(shape);
}

