pub(super) fn process_all_event_queues(&mut self) {
    let Some(event_queues) =
        self.with_app(|app| app.state.as_ref().map(|s| s.event_queues.clone()))
    else {
        return;
    };

    // Take all events with a single lock, replacing with empty queues
    let events = {
        let Ok(mut queues) = event_queues.lock() else {
            godot::global::godot_warn!(
                "[CefTexture] Failed to lock event queues while draining signals"
            );
            return;
        };
        std::mem::take(&mut *queues)
    };

    // Now process events without holding the lock
    crate::display_events::emit_events(&events.display_events, |name, args| {
        self.base_mut().emit_signal(name, args);
    });
    let dialogs = self.dialog_controller();
    crate::dialog_info::emit_events(dialogs.as_ref(), &events, |name, args| {
        if name != "dialog_request_finished"
            && self.base().get_signal_connection_list(name).is_empty()
        {
            return false;
        }
        self.base_mut().emit_signal(name, args);
        true
    });
    self.emit_message_signals(&events.messages);
    self.emit_binary_message_signals(&events.binary_messages);
    self.emit_data_message_signals(&events.data_messages);
    self.emit_debug_ipc_signals(&events.debug_ipc_events);
    self.emit_url_change_signals(&events.url_changes);
    self.emit_title_change_signals(&events.title_changes);
    self.emit_loading_state_signals(&events.loading_states);
    self.emit_console_message_signals(&events.console_messages);
    self.emit_drag_event_signals(&events.drag_events);
    self.emit_popup_request_signals(&events.popup_requests);
    for (request_id, result) in &events.permission_request_finished {
        emit_signal_variants!(
            self,
            "permission_request_finished",
            *request_id,
            GString::from(result)
        );
    }
    self.emit_permission_request_signals(&events.permission_requests);
    self.emit_find_result_signals(&events.find_results);
    self.emit_cookie_event_signals(&events.cookie_events);
    self.emit_download_request_signals(&events.download_requests);
    self.emit_download_update_signals(&events.download_updates);
    self.emit_render_process_terminated_signals(&events.render_process_terminated);

    // Handle IME events (these may modify self state)
    self.process_ime_enable_events(&events.ime_enables);
    if let Some(range) = events.ime_composition_range {
        self.process_ime_composition_event(range);
    }
}

fn emit_data_message_signals(&mut self, messages: &VecDeque<Vec<u8>>) {
    for data in messages {
        match crate::ipc_data::decode_cbor_bytes_to_variant(data) {
            Ok(variant) => {
                self.base_mut().emit_signal("ipc_data_message", &[variant]);
            }
            Err(err) => {
                godot::global::godot_warn!(
                    "[CefTexture] Failed to decode IPC data message: {}",
                    err
                );
            }
        }
    }
}

fn emit_debug_ipc_signals(&mut self, events: &VecDeque<DebugIpcEvent>) {
    for event in events {
        let mut payload = godot::builtin::VarDictionary::new();
        payload.set("direction", &GString::from(event.direction.as_str()));
        payload.set("lane", &GString::from(event.lane.as_str()));
        payload.set("body", &GString::from(&event.body));
        payload.set("timestamp_unix_ms", event.timestamp_unix_ms);
        payload.set("body_size_bytes", event.body_size_bytes);
        self.base_mut()
            .emit_signal("debug_ipc_message", &[payload.to_variant()]);
    }
}

fn emit_cookie_event_signals(&mut self, events: &VecDeque<crate::cookie::CookieEvent>) {
    for event in events {
        match event {
            crate::cookie::CookieEvent::Received(cookies) => {
                let array: Array<Gd<CookieInfo>> =
                    cookies.iter().map(CookieInfo::from_data).collect();
                emit_signal_variants!(self, "cookies_received", array);
            }
            crate::cookie::CookieEvent::Set(success) => {
                emit_signal_variants!(self, "cookie_set", success);
            }
            crate::cookie::CookieEvent::Deleted(count) => {
                emit_signal_variants!(self, "cookies_deleted", count);
            }
            crate::cookie::CookieEvent::Flushed => {
                emit_signal_variants!(self, "cookies_flushed");
            }
        }
    }
}

pub(super) fn refresh_browser_drag(&mut self) {
    let enabled = self.base().is_inside_tree()
        && self.base().is_visible_in_tree()
        && self.base().can_process()
        && self.base().is_processing()
        && !self
            .base()
            .get_signal_connection_list("drag_started")
            .is_empty();
    let released = !Input::singleton().is_mouse_button_pressed(MouseButton::LEFT);
    self.with_app(|app| {
        if let Some(state) = &app.state {
            if let Ok(mut drag) = state.source_drag.lock() {
                drag.enabled = enabled;
            }
            // Runs after input dispatch, allowing a drop handler to finish first.
            if !enabled || released {
                state.finish_source_drag(None, None, 0);
            }
        }
    });
}

pub(super) fn connect_runtime_hooks(&mut self) {
    // CefTexture shuts down its helper during construction and drives that
    // helper itself. Its queued installation must not start a second browser
    // or double-tick the shared runtime.
    if !self.runtime.runtime_enabled()
        || Engine::singleton().is_editor_hint()
        || self.process_hook.is_some()
    {
        return;
    }

    let Some(mut tree) = Engine::singleton()
        .get_main_loop()
        .and_then(|main_loop| main_loop.try_cast::<SceneTree>().ok())
    else {
        godot::global::godot_error!(
            "[CefTexture2D] Browser runtime requires a SceneTree main loop"
        );
        return;
    };

    let process_callable = self.base().callable("_on_process_frame");
    let error = tree.connect("process_frame", &process_callable);
    if error != godot::global::Error::OK {
        godot::global::godot_error!(
            "[CefTexture2D] Failed to connect process frame: {error:?}"
        );
        return;
    }
    self.process_hook = Some((tree.instance_id(), process_callable));

    let frame_callable = self.base().callable("_on_frame_pre_draw");
    let error = RenderingServer::singleton().connect("frame_pre_draw", &frame_callable);
    if error == godot::global::Error::OK {
        self.frame_hook = Some(frame_callable);
    } else {
        godot::global::godot_error!("[CefTexture2D] Failed to connect render frame: {error:?}");
    }
}

pub(super) fn disconnect_runtime_hooks(&mut self) {
    if let Some((tree_id, callable)) = self.process_hook.take()
        && let Ok(mut tree) = Gd::<SceneTree>::try_from_instance_id(tree_id)
        && tree.is_connected("process_frame", &callable)
    {
        tree.disconnect("process_frame", &callable);
    }
    if let Some(callable) = self.frame_hook.take() {
        let mut rendering_server = RenderingServer::singleton();
        if rendering_server.is_connected("frame_pre_draw", &callable) {
            rendering_server.disconnect("frame_pre_draw", &callable);
        }
    }
}

pub(super) fn try_create_browser(&mut self) {
    backend::set_browser_hidden(self.runtime.app_mut(), self.browser_hidden);
    if self.runtime.app().state.is_some() || !self.runtime.app().can_create_browser() {
        return;
    }
    let logical_size = self.logical_size();
    let dpi = self.get_dpi();
    self.runtime.try_create_browser(RuntimeCreateConfig {
        logical_size,
        dpi,
        url: self.url.clone(),
        enable_accelerated_osr: self.enable_accelerated_osr,
        background_color: self.background_color,
        popup_policy: self.popup_policy,
        permission_policy: self.permission_policy,
        dialog_policy: self.dialog_policy,
        preload_script: self.preload_script.clone(),
        preload_script_path: self.preload_script_path.clone(),
        software_target_texture: Some(self.fallback_texture.clone()),
        log_prefix: "CefTexture2D",
    });
    #[cfg(any(target_os = "macos", target_os = "windows", target_os = "linux"))]
    if self.enable_accelerated_osr
        && let Some(state) = self.runtime.app_mut().state.as_mut()
        && let RenderMode::Accelerated {
            texture_2d_rd,
            render_state,
            ..
        } = &mut state.render_mode
        && let Some(stable) = &mut self.stable_texture_2d_rd
    {
        let dst_rd_rid = render_state
            .lock()
            .ok()
            .map(|rs| rs.dst_rd_rid)
            .unwrap_or(Rid::Invalid);
        stable.set_texture_rd_rid(dst_rd_rid);
        *texture_2d_rd = stable.clone();
        self.popup_compositor = Some(popup_compositor::PopupCompositor::new(stable.get_rid()));
    }
    self.base_mut().emit_changed();
}

pub(super) fn drain_event_queues(&mut self) {
    let events = self.runtime.drain_event_queues("CefTexture2D");
    crate::display_events::emit_events(&events.display_events, |name, args| {
        self.base_mut().emit_signal(name, args);
    });
    let dialogs = self.dialog_controller();
    crate::dialog_info::emit_events(dialogs.as_ref(), &events, |name, args| {
        if name != "dialog_request_finished"
            && self.base().get_signal_connection_list(name).is_empty()
        {
            return false;
        }
        self.base_mut().emit_signal(name, args);
        true
    });
    for (request_id, result) in events.permission_request_finished {
        self.base_mut().emit_signal(
            "permission_request_finished",
            &[request_id.to_variant(), GString::from(&result).to_variant()],
        );
    }
    for event in events.permission_requests {
        if !self.is_permission_pending(event.request_id) {
            continue;
        }
        if self
            .base()
            .get_signal_connection_list("permission_requested")
            .is_empty()
        {
            if let Some(state) = self.runtime.app().state.as_ref() {
                state.permissions.dismiss_request(event.request_id);
            }
            continue;
        }
        self.base_mut().emit_signal(
            "permission_requested",
            &[
                GString::from(&event.permission_type).to_variant(),
                GString::from(&event.url).to_variant(),
                event.request_id.to_variant(),
            ],
        );
    }
}

pub(super) fn tick(&mut self) {
    if !self.runtime.runtime_enabled() || Engine::singleton().is_editor_hint() {
        return;
    }

    self.try_create_browser();

    self.runtime.handle_max_fps_change();
    let logical_size = self.logical_size();
    let dpi = self.get_dpi();
    let _ = self.runtime.handle_size_change(logical_size, dpi);
    // Headless Godot does not emit frame_pre_draw. Browser lifecycle and
    // callbacks must also progress without drawing when minimized or with
    // the render loop disabled. Software frames can be produced here;
    // accelerated begin requests follow publication on frame_pre_draw.
    if self
        .runtime
        .app()
        .state
        .as_ref()
        .is_some_and(|state| matches!(state.render_mode, RenderMode::Software { .. }))
    {
        self.runtime.request_external_begin_frame();
    }
    self.drain_event_queues();
}

pub(super) struct PopupCompositor {
    proxy: Rid,
    view_texture: Rid,
    popup_texture: Gd<Texture2Drd>,
    bound_popup: Rid,
    // Canvas items borrow this material's RID.
    material: Gd<CanvasItemMaterial>,
    canvas: Option<PopupCanvas>,
    compositing: bool,
}

pub(super) fn new(view_texture: Rid) -> Self {
    let proxy = RenderingServer::singleton().texture_proxy_create(view_texture);
    // CanvasItemMaterial applies blend-mode changes during SceneTree's idle
    // flush. Create it with the browser, before any popup can be displayed:
    // creating it lazily in frame_pre_draw uses straight-alpha blending for
    // the first composed frame and multiplies CEF's premultiplied RGB twice.
    let mut material = CanvasItemMaterial::new_gd();
    material.set_blend_mode(godot::classes::canvas_item_material::BlendMode::PREMULT_ALPHA);
    Self {
        proxy,
        view_texture,
        popup_texture: Texture2Drd::new_gd(),
        bound_popup: Rid::Invalid,
        material,
        canvas: None,
        compositing: false,
    }
}

pub(super) fn update(&mut self, size: Vector2i, popup: Option<(Rid, Rect2)>) -> bool {
    let mut server = RenderingServer::singleton();
    let Some((popup_rid, rect)) = popup else {
        if self.compositing {
            server.texture_proxy_update(self.proxy, self.view_texture);
            if let Some(canvas) = &self.canvas {
                server.viewport_set_active(canvas.viewport, false);
                // Release the canvas's references before retiring a popup
                // generation. The persistent wrapper will be rebound later.
                server.canvas_item_clear(canvas.item);
            }
            self.popup_texture.set_texture_rd_rid(Rid::Invalid);
            self.bound_popup = Rid::Invalid;
            self.compositing = false;
            return true;
        }
        return false;
    };

    // Godot 4.6 leaves get_texture_rd_rid() unchanged when detaching an
    // invalid RID, although its RenderingServer texture has been freed.
    // Track our binding explicitly so reopening the same popup rebinds it.
    if self.bound_popup != popup_rid {
        self.popup_texture.set_texture_rd_rid(popup_rid);
        self.bound_popup = popup_rid;
    }
    let material = self.material.get_rid();
    let canvas = self
        .canvas
        .get_or_insert_with(|| PopupCanvas::new(&mut server, material));
    if canvas.layout != Some((size, rect)) || !self.compositing {
        server.viewport_set_size(canvas.viewport, size.x, size.y);
        server.canvas_item_clear(canvas.item);
        server.canvas_item_add_texture_rect(
            canvas.item,
            Rect2::new(Vector2::ZERO, size.to_vector2()),
            self.view_texture,
        );
        server.canvas_item_add_texture_rect(canvas.item, rect, self.popup_texture.get_rid());
        canvas.layout = Some((size, rect));
    }
    if !self.compositing {
        server.viewport_set_active(canvas.viewport, true);
        let output = server.viewport_get_texture(canvas.viewport);
        server.texture_proxy_update(self.proxy, output);
        self.compositing = true;
        return true;
    }
    false
}

pub(super) fn dispose(mut self) {
    let mut server = RenderingServer::singleton();
    server.free_rid(self.proxy);
    if let Some(canvas) = self.canvas.take() {
        if self.compositing {
            server.viewport_set_active(canvas.viewport, false);
        }
        server.free_rid(canvas.item);
        server.free_rid(canvas.canvas);
        server.free_rid(canvas.viewport);
    }
    self.popup_texture.set_texture_rd_rid(Rid::Invalid);
}

impl PopupCanvas {
    fn new(server: &mut RenderingServer, material: Rid) -> Self {
        let viewport = server.viewport_create();
        server.viewport_set_disable_3d(viewport, true);
        server.viewport_set_transparent_background(viewport, true);
        server.viewport_set_clear_mode(viewport, ViewportClearMode::ALWAYS);
        server.viewport_set_update_mode(viewport, ViewportUpdateMode::ALWAYS);
        if let Some(tree) = Engine::singleton()
            .get_main_loop()
            .and_then(|main_loop| main_loop.try_cast::<SceneTree>().ok())
            && let Some(root) = tree.get_root()
        {
            // Render the offscreen composition before its root-window consumer.
            server.viewport_set_parent_viewport(viewport, root.get_viewport_rid());
        }
        let canvas = server.canvas_create();
        server.viewport_attach_canvas(viewport, canvas);
        let item = server.canvas_item_create();
        server.canvas_item_set_parent(item, canvas);
        server.canvas_item_set_material(item, material);
        Self {
            viewport,
            canvas,
            item,
            layout: None,
        }
    }
}

pub(super) fn make_placeholder_texture(size: Vector2i) -> Gd<ImageTexture> {
    let width = size.x.max(1);
    let height = size.y.max(1);
    let pixel_count = (width as usize) * (height as usize);
    let bytes = vec![0u8; pixel_count * 4];
    let byte_array = PackedByteArray::from(bytes.as_slice());

    let mut texture = ImageTexture::new_gd();
    if let Some(image) =
        Image::create_from_data(width, height, false, ImageFormat::RGBA8, &byte_array)
    {
        texture.set_image(&image);
    }

    texture
}

pub(super) fn update_texture(&mut self) {
    let Some(state) = &mut self.runtime.app_mut().state else {
        return;
    };

    let software_had_dirty = match &state.render_mode {
        RenderMode::Software { frame_buffer, .. } => {
            let fb_dirty = frame_buffer.lock().ok().is_some_and(|fb| fb.dirty);
            let popup_dirty =
                state.popup_state.lock().ok().is_some_and(|popup| {
                    popup.visible && popup.dirty && !popup.buffer.is_empty()
                });
            fb_dirty || popup_dirty
        }
        #[cfg(any(target_os = "macos", target_os = "windows", target_os = "linux"))]
        RenderMode::Accelerated { .. } => false,
    };

    #[cfg(any(target_os = "macos", target_os = "windows", target_os = "linux"))]
    let had_pending_copy =
        if let RenderMode::Accelerated { render_state, .. } = &state.render_mode {
            render_state
                .lock()
                .ok()
                .is_some_and(|rs| rs.has_pending_copy)
        } else {
            false
        };
    #[cfg(not(any(target_os = "macos", target_os = "windows", target_os = "linux")))]
    let had_pending_copy = false;

    let replacement = self.runtime.update_primary_texture("CefTexture2D");
    let has_replacement = replacement.is_some();

    #[cfg(any(target_os = "macos", target_os = "windows", target_os = "linux"))]
    {
        if let Some(new_t2d) = replacement
            && let Some(ref mut stable) = self.stable_texture_2d_rd
        {
            let new_rd_rid = new_t2d.get_texture_rd_rid();
            stable.set_texture_rd_rid(new_rd_rid);
            if let Some(state) = self.runtime.app_mut().state.as_mut()
                && let RenderMode::Accelerated { texture_2d_rd, .. } = &mut state.render_mode
            {
                *texture_2d_rd = stable.clone();
            }
        }
    }

    let _ = replacement;
    let popup_changed = self.update_popup_composition();
    let should_emit_changed =
        software_had_dirty || has_replacement || had_pending_copy || popup_changed;
    if should_emit_changed {
        self.base_mut().emit_changed();
    }
    backend::queue_texture_publication(self.runtime.app());
}

pub(crate) fn update_primary_texture(
    &mut self,
    log_prefix: &str,
) -> Option<Gd<godot::classes::Texture2Drd>> {
    let Some(state) = &mut self.app.state else {
        return None;
    };
    backend::update_primary_texture(state, log_prefix)
}

pub(crate) fn cleanup_runtime(
