pub fn handle_mouse_button(
    host: &impl ImplBrowserHost,
    event: &Gd<InputEventMouseButton>,
    pixel_scale_factor: f32,
    device_scale_factor: f32,
) {
    let modifiers = keyboard_modifiers!(event) | mouse_button_modifiers(event.get_button_mask());
    let position = event.get_position();
    let mouse_event =
        create_mouse_event(position, pixel_scale_factor, device_scale_factor, modifiers);

    match event.get_button_index() {
        MouseButton::LEFT | MouseButton::MIDDLE | MouseButton::RIGHT => {
            let button_type = match event.get_button_index() {
                MouseButton::LEFT => MouseButtonType::LEFT,
                MouseButton::MIDDLE => MouseButtonType::MIDDLE,
                MouseButton::RIGHT => MouseButtonType::RIGHT,
                _ => return,
            };
            let mouse_up = !event.is_pressed();
            let click_count = if event.is_double_click() { 2 } else { 1 };
            host.send_mouse_click_event(
                Some(&mouse_event),
                button_type,
                mouse_up as i32,
                click_count,
            );
        }
        MouseButton::WHEEL_UP => {
            let delta = (WHEEL_DELTA * event.get_factor()) as i32;
            host.send_mouse_wheel_event(Some(&mouse_event), 0, delta);
        }
        MouseButton::WHEEL_DOWN => {
            let delta = (WHEEL_DELTA * event.get_factor()) as i32;
            host.send_mouse_wheel_event(Some(&mouse_event), 0, -delta);
        }
        MouseButton::WHEEL_LEFT => {
            let delta = (WHEEL_DELTA * event.get_factor()) as i32;
            host.send_mouse_wheel_event(Some(&mouse_event), -delta, 0);
        }
        MouseButton::WHEEL_RIGHT => {
            let delta = (WHEEL_DELTA * event.get_factor()) as i32;
            host.send_mouse_wheel_event(Some(&mouse_event), delta, 0);
        }
        _ => {}
    }
}

pub fn handle_mouse_motion(
    host: &impl ImplBrowserHost,
    event: &Gd<InputEventMouseMotion>,
    pixel_scale_factor: f32,
    device_scale_factor: f32,
) {
    let modifiers = keyboard_modifiers!(event) | mouse_button_modifiers(event.get_button_mask());
    let position = event.get_position();
    let mouse_event =
        create_mouse_event(position, pixel_scale_factor, device_scale_factor, modifiers);
    host.send_mouse_move_event(Some(&mouse_event), false as i32);
}

pub fn handle_pan_gesture(
    host: &impl ImplBrowserHost,
    event: &Gd<InputEventPanGesture>,
    pixel_scale_factor: f32,
    device_scale_factor: f32,
) {
    let modifiers = keyboard_modifiers!(event);
    let position = event.get_position();
    let mouse_event =
        create_mouse_event(position, pixel_scale_factor, device_scale_factor, modifiers);

    let (delta_x, delta_y) = pan_gesture_wheel_delta(event.get_delta(), device_scale_factor);

    if delta_x != 0 || delta_y != 0 {
        host.send_mouse_wheel_event(Some(&mouse_event), delta_x, delta_y);
    }
}

pub fn handle_screen_touch(
    host: &impl ImplBrowserHost,
    event: &Gd<InputEventScreenTouch>,
    pixel_scale_factor: f32,
    device_scale_factor: f32,
    touch_id_map: &mut HashMap<i32, i32>,
    _next_touch_id: &mut i32,
) {
    let index = event.get_index();
    let is_canceled = event.is_canceled();
    let is_pressed = event.is_pressed();
    let type_ = if is_canceled {
        TouchEventType::CANCELLED
    } else if is_pressed {
        TouchEventType::PRESSED
    } else {
        TouchEventType::RELEASED
    };

    let Some(id) = touch_id_for_event(touch_id_map, index, type_) else {
        return;
    };
    let touch_event = create_touch_event(
        event.get_position(),
        pixel_scale_factor,
        device_scale_factor,
        type_,
        id,
        1.0,
    );
    host.send_touch_event(Some(&touch_event));
}

pub fn handle_screen_drag(
    host: &impl ImplBrowserHost,
    event: &Gd<InputEventScreenDrag>,
    pixel_scale_factor: f32,
    device_scale_factor: f32,
    touch_id_map: &mut HashMap<i32, i32>,
    _next_touch_id: &mut i32,
) {
    let index = event.get_index();
    let Some(id) = touch_id_for_event(touch_id_map, index, TouchEventType::MOVED) else {
        return;
    };
    let touch_event = create_touch_event(
        event.get_position(),
        pixel_scale_factor,
        device_scale_factor,
        TouchEventType::MOVED,
        id,
        event.get_pressure(),
    );
    host.send_touch_event(Some(&touch_event));
}

pub fn handle_magnify_gesture(host: &impl ImplBrowserHost, event: &Gd<InputEventMagnifyGesture>) {
    let factor = event.get_factor() as f64;
    if factor.abs() <= f64::EPSILON {
        return;
    }

    let current_zoom = host.zoom_level();
    host.set_zoom_level(current_zoom + (factor * MAGNIFY_ZOOM_SENSITIVITY));
}

pub fn handle_key_event(
    host: &impl ImplBrowserHost,
    event: &Gd<InputEventKey>,
    focus_on_editable_field: bool,
) {
    let modifiers = keyboard_modifiers!(event);

    let is_pressed = event.is_pressed();
    let is_echo = event.is_echo();
    let keycode = event.get_keycode();

    // Godot also sends a KEY event for the NONE key for characters, which we don't want to process.
    if keycode == Key::NONE {
        return;
    }

    // Always let the page handle keydown first (e.g. Monaco's select-all).
    // Native macOS editing commands are supplied by the CEF keyboard handler
    // only after the renderer has declined the event.
    #[cfg(target_os = "macos")]
    let platform = KeyboardPlatform::MacOS;
    #[cfg(target_os = "windows")]
    let platform = KeyboardPlatform::Windows;
    #[cfg(target_os = "linux")]
    let platform = KeyboardPlatform::Linux;

    let input = KeyInput {
        keycode,
        physical_keycode: event.get_physical_keycode(),
        unicode: event.get_unicode(),
        modifiers,
        is_pressed,
        is_echo,
        focus_on_editable_field,
    };
    for key_event in key_events(input, platform).into_iter().flatten() {
        host.send_key_event(Some(&key_event));
    }
}

pub(crate) fn create_rd_texture_rid(
    width: i32,
    height: i32,
    data_format: DataFormat,
) -> CefResult<Rid> {
    let width = width.max(1) as i64;
    let height = height.max(1) as i64;

    let mut rd = RenderingServer::singleton()
        .get_rendering_device()
        .ok_or_else(|| CefError::GpuDeviceError("Failed to get RenderingDevice".to_string()))?;

    let mut format = godot::classes::RdTextureFormat::new_gd();
    format.set_format(data_format);
    // Texture2DRD creates both linear and sRGB views of its backing texture.
    // Both formats must be declared even when the resource itself is sRGB.
    format.add_shareable_format(data_format);
    match data_format {
        DataFormat::B8G8R8A8_SRGB => {
            format.add_shareable_format(DataFormat::B8G8R8A8_UNORM);
        }
        DataFormat::R8G8B8A8_SRGB => {
            format.add_shareable_format(DataFormat::R8G8B8A8_UNORM);
        }
        _ => {}
    }
    format.set_width(width as u32);
    format.set_height(height as u32);
    format.set_depth(1);
    format.set_array_layers(1);
    format.set_mipmaps(1);
    format.set_texture_type(RdTextureType::TYPE_2D);
    format.set_samples(TextureSamples::SAMPLES_1);
    format.set_usage_bits(
        TextureUsageBits::SAMPLING_BIT
            | TextureUsageBits::CAN_UPDATE_BIT
            | TextureUsageBits::CAN_COPY_TO_BIT
            | TextureUsageBits::CAN_COPY_FROM_BIT,
    );

    let rd_texture_rid = rd.texture_create(&format, &godot::classes::RdTextureView::new_gd());

    if !rd_texture_rid.is_valid() {
        return Err(CefError::TextureOperationFailed(format!(
            "Failed to create RenderingDevice texture {}x{}",
            width, height
        )));
    }

    // One initial transparent upload avoids sRGB RTV/UAV clear restrictions on
    // Godot's D3D12 backend. Browser frame pixels still stay entirely on the GPU.
    let transparent = PackedByteArray::from(vec![0; (width * height * 4) as usize].as_slice());
    let error = rd.texture_update(rd_texture_rid, 0, &transparent);
    if error != godot::global::Error::OK {
        rd.free_rid(rd_texture_rid);
        return Err(CefError::TextureOperationFailed(format!(
            "Failed to initialize display texture: {error:?}"
        )));
    }
    Ok(rd_texture_rid)
}

pub fn free_rd_texture(rd_texture_rid: Rid) {
    if rd_texture_rid.is_valid() {
        on_render_thread(move || {
            if let Some(mut rd) = RenderingServer::singleton().get_rendering_device() {
                rd.free_rid(rd_texture_rid);
            }
        });
    }
}

pub(crate) fn on_render_thread<F: FnOnce() + Send + Sync + 'static>(work: F) {
    let mut work = Some(work);
    let callable = Callable::from_sync_fn("gdcef_render", move |_: &[&Variant]| {
        if let Some(work) = work.take() {
            work();
        }
    });
    RenderingServer::singleton().call_on_render_thread(&callable);
}

fn register_string_setting(
    settings: &mut Gd<ProjectSettings>,
    name: &str,
    default: &str,
    hint: PropertyHint,
    hint_string: &str,
) {
    let name_gstring: GString = name.into();

    if !settings.has_setting(&name_gstring) {
        settings.set_setting(&name_gstring, &default.to_variant());
    }

    settings.set_initial_value(&name_gstring, &default.to_variant());
    settings.set_as_basic(&name_gstring, true);

    let property_info = vdict! {
        "name" => &name_gstring,
        "type" => VariantType::STRING.ord(),
        "hint" => hint.ord(),
        "hint_string" => hint_string,
    };

    settings.add_property_info(&property_info);
}

fn register_bool_setting(settings: &mut Gd<ProjectSettings>, name: &str, default: bool) {
    let name_gstring: GString = name.into();

    if !settings.has_setting(&name_gstring) {
        settings.set_setting(&name_gstring, &default.to_variant());
    }

    settings.set_initial_value(&name_gstring, &default.to_variant());
    settings.set_as_basic(&name_gstring, true);

    let property_info = vdict! {
        "name" => &name_gstring,
        "type" => VariantType::BOOL.ord(),
        "hint" => PropertyHint::NONE.ord(),
        "hint_string" => "",
    };

    settings.add_property_info(&property_info);
}

