pub(super) fn tick_keyboard_release(&mut self) {
    if !self
        .web_events
        .iter()
        .any(|event| event["type"] == "keyboard_ready")
    {
        return;
    }
    if !self.keyboard.focus_requested {
        self.keyboard.focus_requested = true;
        self.dialog_click(Vector2::new(
            50.0,
            if self.keyboard.phase == 0 {
                34.0
            } else {
                100.0
            },
        ));
        return;
    }
    if self.keyboard_web("keyboard_focus").is_none() {
        return;
    }
    if self.keyboard.sent < KEYS.len() * 2 {
        let (key, unicode, _) = KEYS[self.keyboard.sent / 2];
        let pressed = self.keyboard.sent.is_multiple_of(2);
        let mut event = InputEventKey::new_gd();
        event.set_keycode(key);
        event.set_physical_keycode(key);
        event.set_pressed(pressed);
        event.set_unicode(if pressed { unicode } else { 0 });
        event.set_shift_pressed(key == Key::SHIFT && pressed);
        if self.class == "CefTexture2D" {
            self.call(
                "forward_key_event",
                &[event.to_variant(), (self.keyboard.phase == 1).to_variant()],
            );
        } else if let Some(window) = &mut self.dialogs.window {
            window.push_input_ex(&event).in_local_coords(true).done();
        }
        self.keyboard.sent += 1;
        return;
    }
    let Some(result) = self.keyboard_web("keyboard_result") else {
        return;
    };
    let Some(events) = result["events"].as_array() else {
        self.fail("Keyboard fixture must return its DOM event sequence");
        return;
    };
    let phase = self.keyboard.phase;
    self.check(
        events.len() == KEYS.len() * 2,
        format!("Keyboard phase {phase} must deliver exactly one keydown and keyup per key: {events:?}"),
    );
    for (index, (_, _, key)) in KEYS.iter().enumerate() {
        let pair = events.get(index * 2..index * 2 + 2);
        self.check(
            pair.is_some_and(|pair| {
                pair[0]["type"] == "keydown"
                    && pair[1]["type"] == "keyup"
                    && pair[0]["key"] == *key
                    && pair[1]["key"] == *key
                    && pair[0]["code"] == pair[1]["code"]
                    && pair[0]["keyCode"] == pair[1]["keyCode"]
                    && pair.iter().all(|event| {
                        event["trusted"] == true
                            && event["repeat"] == false
                            && event["target"] == if phase == 0 { "surface" } else { "editor" }
                    })
            }),
            format!("Keyboard phase {phase}, key {key:?} must have matching trusted down/up identity: {pair:?}"),
        );
    }
    if phase == 1 {
        self.stop();
    } else {
        self.keyboard = KeyboardState {
            phase: 1,
            ..Default::default()
        };
    }
}

#[gdextension(entry_symbol = gdcef_itest_init)]
unsafe impl ExtensionLibrary for IntegrationTests {
    fn on_stage_init(stage: InitStage) {
        if stage == InitStage::MainLoop
            && std::env::var("GDCEF_ITEST").as_deref() == Ok("1")
            && !Engine::singleton().is_editor_hint()
        {
            START_PENDING.with(|pending| *pending.borrow_mut() = true);
        }
    }

    fn on_main_loop_frame() {
        let start = START_PENDING.with(|pending| pending.replace(false));
        if start {
            RUNNER.with(|runner| *runner.borrow_mut() = Some(Runner::new()));
        }
        // Taking ownership also prevents a callback from borrowing the live runner recursively.
        let active = RUNNER.with(|runner| runner.borrow_mut().take());
        if let Some(mut runner) = active {
            runner.tick();
            RUNNER.with(|slot| *slot.borrow_mut() = Some(runner));
        }
    }

    fn on_stage_deinit(stage: InitStage) {
        if stage == InitStage::MainLoop {
            RUNNER.with(|runner| {
                if let Some(mut runner) = runner.borrow_mut().take() {
                    runner.destroy_browser();
                    if let Some(mut poller) = runner.poller.take()
                        && poller.is_instance_valid()
                    {
                        poller.cancel_request();
                        poller.queue_free();
                    }
                    runner.disconnect_draw_observer();
                }
            });
            EVENTS.with(|events| events.borrow_mut().clear());
        }
    }
}

fn setup(&mut self, profile: &str) -> Result<(), String> {
    if !matches!(self.class.as_str(), "CefTexture" | "CefTexture2D")
        || !matches!(
            self.case.as_str(),
            "permission_grant_all"
                | "permission_deny_one"
                | "permission_timeout"
                | "permission_navigation"
                | "permission_unhandled_then_listen"
                | "js_ipc"
                | "lifecycle"
                | "dialog_js"
                | "dialog_file"
                | "dialog_timeout"
                | "dialog_unhandled"
                | "dialog_navigation"
                | "dialog_policy"
                | "dialog_lifecycle"
                | "dialog_before_unload"
                | "dialog_reentrant"
                | "display_events"
                | "browser_hidden"
                | "keyboard_release"
                | "keyboard_editing"
                | "keyboard_clipboard"
        )
    {
        return Err("Harness supplied an unknown class or case".into());
    }
    if self.case == "keyboard_clipboard"
        && std::env::var("GDCEF_ITEST_ALLOW_CLIPBOARD_WRITES").as_deref() != Ok("1")
    {
        return Err("keyboard_clipboard requires explicit clipboard-write opt-in".into());
    }
    let port = self
        .origin
        .strip_prefix("http://127.0.0.1:")
        .and_then(|value| value.parse::<u16>().ok());
    if port.is_none_or(|port| port == 0)
        || self.run.is_empty()
        || !self
            .run
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
        || !std::path::Path::new(profile).is_absolute()
    {
        return Err(
            "Harness must supply a loopback origin, alphanumeric run ID and absolute profile"
                .into(),
        );
    }
    ProjectSettings::singleton()
        .set_setting("godot_cef/storage/data_path", &profile.to_variant());
    ProjectSettings::singleton().set_setting(
        "godot_cef/dialogs/request_timeout_seconds",
        &1_i64.to_variant(),
    );
    self.check(
        DisplayServer::singleton().get_name() == "headless",
        "Integration run must use Godot's headless display server",
    );
    let draw_observer = callback("draw_frame", 0);
    let draw_error = RenderingServer::singleton().connect("frame_pre_draw", &draw_observer);
    if draw_error != Error::OK {
        return Err(format!("Could not observe draw frames: {draw_error:?}"));
    }
    self.draw_observer = Some(draw_observer);
    let mut poller = HttpRequest::new_alloc();
    let error = poller.connect("request_completed", &callback("http", 0));
    if error != Error::OK {
        poller.free();
        return Err(format!("Could not connect HTTPRequest: {error:?}"));
    }
    let Some(mut root) = scene_tree().and_then(|tree| tree.get_root()) else {
        poller.free();
        return Err("No SceneTree root after MainLoop initialization".into());
    };
    root.add_child(&poller);
    self.poller = Some(poller);
    if self.case == "lifecycle" && self.class == "CefTexture2D" {
        self.generation = 0;
    }
    self.create_browser()?;
    if self.generation == 0 {
        self.call("shutdown", &[]);
        self.shutdown_at = Some(Instant::now());
    }
    Ok(())
}

fn event(&mut self, event: Event) {
    if event.name == "draw_frame" {
        self.draw_frames += 1;
        return;
    }
    if event.name == "http" {
        self.polling = false;
        if self.stopping.is_some() {
            return;
        }
        let result = event
            .args
            .first()
            .and_then(|value| value.try_to::<i64>().ok());
        let status = event
            .args
            .get(1)
            .and_then(|value| value.try_to::<i64>().ok());
        let body = event
            .args
            .get(3)
            .and_then(|value| value.try_to::<PackedByteArray>().ok());
        if result != Some(0) || status != Some(200) {
            self.fail(format!("Loopback response failed: {result:?}/{status:?}"));
            return;
        }
        let parsed = body.and_then(|body| serde_json::from_slice::<Value>(&body.to_vec()).ok());
        if let Some(events) = parsed.and_then(|value| value["events"].as_array().cloned()) {
            self.web_events = events;
        } else {
            self.fail("Invalid loopback status JSON");
        }
        return;
    }
    if event.generation != self.generation || self.browser.is_none() {
        // Closing the old Node may report its cancellation during queued deletion.
        // It is valid until the next browser generation is instantiated.
        if self.case == "dialog_lifecycle"
            && event.name == "dialog_request_finished"
            && event.generation == self.generation
        {
            self.dialog_finished(&event.args);
            return;
        }
        self.stale_signals += 1;
        self.check(
            false,
            format!(
                "Stale {} callback from destroyed generation {}",
                event.name, event.generation
            ),
        );
        return;
    }
    match event.name {
        "permission_requested" => self.permission_requested(&event.args),
        "permission_request_finished" => self.permission_finished(&event.args),
        "file_dialog_requested" | "js_dialog_requested" | "dialog_immediate" => {
            self.dialog_requested(event.name, &event.args)
        }
        "dialog_request_finished" => self.dialog_finished(&event.args),
        "tooltip_changed"
        | "fullscreen_changed"
        | "loading_progress_changed"
        | "status_message_changed"
        | "favicon_urls_changed" => self.display_signal(event.name, &event.args),
        "load_finished" => {
            self.load_finished += 1;
        }
        "load_error" => self.fail(format!("Browser load failed: {:?}", event.args)),
        "ipc_message" | "ipc_binary_message" | "ipc_data_message" => {
            self.ipc_event(event.name, &event.args)
        }
        _ => self.fail(format!("Unexpected callback: {}", event.name)),
    }
}

fn disconnect_draw_observer(&mut self) {
    if let Some(callable) = self.draw_observer.take() {
        let mut rendering = RenderingServer::singleton();
        if rendering.is_connected("frame_pre_draw", &callable) {
            rendering.disconnect("frame_pre_draw", &callable);
        }
    }
}

fn report(&mut self) {
    self.reported = true;
    self.disconnect_draw_observer();
    self.check(
        self.draw_frames == 0,
        "Headless tests must complete without rendering frames",
    );
    if let Some(id) = self.previous_id {
        self.check(
            Gd::<Object>::try_from_instance_id(id).is_err(),
            "Final browser object must be freed",
        );
    }
    let requests: Vec<_> = self
        .requests
        .iter()
        .map(|request| json!({"type": request.kind, "url": request.url, "id": request.id}))
        .collect();
    let elapsed = self
        .first_request
        .zip(self.last_finished)
        .map(|(start, end)| end.duration_since(start).as_millis());
    godot_print!(
        "GDCEF_ITEST_RESULT {}",
        json!({
            "class": self.class, "case": self.case, "passed": self.failures.is_empty(),
            "checks": self.checks, "failures": self.failures, "requests": requests,
            "finished": self.finished, "unhandled_finished": self.unhandled_finished,
            "events": self.web_events, "request_to_finish_ms": elapsed,
            "generation": self.generation, "ipc_received": self.ipc_received,
            "load_finished": self.load_finished, "stale_signals": self.stale_signals,
            "process_frames": self.process_frames, "draw_frames": self.draw_frames,
            "dialog_requests": self.dialogs.requests,
            "dialog_finished": self.dialogs.finished,
            "display_signals": self.display.signals,
            "display_stage": self.display.stage,
            "elapsed_ms": self.started.elapsed().as_millis(),
        })
    );
    if let Some(mut tree) = scene_tree() {
        tree.quit_ex()
            .exit_code(i32::from(!self.failures.is_empty()))
            .done();
    }
}

fn scene_tree() -> Option<Gd<SceneTree>> {
    Engine::singleton()
        .get_main_loop()?
        .try_cast::<SceneTree>()
        .ok()
}

fn sources(&self) -> impl Iterator<Item = (&str, Source<'_>)> {
    self.files().map(|(path, header)| {
        (
            path,
            Source {
                signals: header.signals(),
                rpcs: header.rpcs(),
                signal_names: header.signal_names(),
                exports: header.exports(),
                digest: header.digest(),
            },
        )
    })
}

pub fn find(class: &str, method: &str) -> Option<Self> {
    let class_db = ClassDb::singleton();
    let declarer = find_declarer(&class_db, class, method)?;
    let info = find_info(&class_db, &declarer, method)?;
    let hash = hash_method(&info)?;
    let arity = Arity::read(&info)?;
    let (bind, declarer_tag) = find_bind(&declarer, &StringName::from(method), hash)?;
    let api = class_db.class_get_api_type(&declarer);
    let bind = if api == ApiType::CORE || api == ApiType::EDITOR {
        Bind::Engine { bind, declarer_tag }
    } else {
        Bind::Extension {
            declarer: declarer.to_string(),
            hash,
        }
    };
    Some(Self {
        bind,
        name: method.to_owned(),
        arity,
    })
}

pub fn call(
    &self,
    object: &Gd<Object>,
    args: &[Variant],
) -> Result<Variant, sys::GDExtensionCallError> {
    let (bind, declarer_tag) = self.bind.find(&self.name).ok_or(INVALID_METHOD)?;
    check_receiver(object, declarer_tag)?;
    self.arity.check(args.len())?;
    let pointers: SmallVec<[_; 4]> = args.iter().map(Variant::var_sys).collect();
    // SAFETY: the bind is alive while the engine runs or, for an
    // extension's class, was found just now with nothing run since,
    // `object` is a live object of the bind's class or one extending it,
    // as checked, and the argument pointers live for the call.
    super::run_engine_call(|answer, error| unsafe {
        sys::interface_fn!(object_method_bind_call)(
            bind,
            object.obj_sys(),
            pointers.as_ptr(),
            pointers.len() as i64,
            answer,
            error,
        );
    })
}

fn check_receiver(
    object: &Gd<Object>,
    declarer_tag: *mut c_void,
) -> Result<(), sys::GDExtensionCallError> {
    // SAFETY: the interface is initialized while the extension runs, and
    // `object` is live.
    let cast = unsafe { sys::interface_fn!(object_cast_to)(object.obj_sys(), declarer_tag) };
    if cast.is_null() {
        return Err(INVALID_METHOD);
    }
    Ok(())
}

impl Arity {
    /// The arity of the engine method `method` of the engine class `class`,
    /// or of the nearest of its ancestors declaring it.
    pub fn find(class: &str, method: &str) -> Option<Self> {
        let class_db = ClassDb::singleton();
        let declarer = find_declarer(&class_db, class, method)?;
        Self::read(&find_info(&class_db, &declarer, method)?)
    }

    /// Whether the method takes `given` arguments, or the error the engine's
    /// debug checks answer when it does not.
    pub fn check(&self, given: usize) -> Result<(), sys::GDExtensionCallError> {
        let takes = self.required + self.optional;
        let error = if given < self.required {
            sys::GDEXTENSION_CALL_ERROR_TOO_FEW_ARGUMENTS
        } else if given > takes && !self.is_vararg {
            sys::GDEXTENSION_CALL_ERROR_TOO_MANY_ARGUMENTS
        } else {
            return Ok(());
        };
        Err(sys::GDExtensionCallError {
            error,
            argument: 0,
            expected: takes as i32,
        })
    }

    // The arity a method's `info`, as ClassDB lists it, gives.
    fn read(info: &VarDictionary) -> Option<Self> {
        let taken = info
            .get_or_nil("args")
            .try_to::<Array<VarDictionary>>()
            .ok()?
            .len();
        let optional = info
            .get_or_nil("default_args")
            .try_to::<VarArray>()
            .ok()?
            .len();
        let flags = info.get_or_nil("flags").try_to::<i64>().ok()? as u64;
        Some(Self {
            required: taken.saturating_sub(optional),
            optional,
            is_vararg: flags & MethodFlags::VARARG.ord() != 0,
        })
    }
}

#[cfg(feature = "editor")]
/// The engine class that binds `method` among `class` and its ancestors,
/// nearest first, as GDScript names the native class a method overrides.
pub fn find_method_declarer(class: &str, method: &str) -> Option<String> {
    find_declarer(&ClassDb::singleton(), class, method).map(|declarer| declarer.to_string())
}

#[cfg(feature = "editor")]
/// Whether `member`, a property or a method of the engine class `class` or
/// one of its ancestors, answers a StringName.
pub fn is_string_name_member(class: &str, member: &str) -> bool {
    let class_db = ClassDb::singleton();
    let is_string_name = |info: &VarDictionary| {
        info.get_or_nil("type").try_to::<i64>().ok()
            == Some(i64::from(VariantType::STRING_NAME.ord))
    };
    let property = class_db
        .class_get_property_list(class)
        .iter_shared()
        .find(|info| info.get_or_nil("name").to_string() == member);
    if let Some(property) = property {
        return is_string_name(&property);
    }
    find_declarer(&class_db, class, member)
        .and_then(|declarer| find_info(&class_db, &declarer, member))
        .and_then(|info| info.get_or_nil("return").try_to::<VarDictionary>().ok())
        .is_some_and(|returned| is_string_name(&returned))
}

pub fn is_static_method(class: &str, method: &str) -> bool {
    let class_db = ClassDb::singleton();
    find_declarer(&class_db, class, method)
        .and_then(|declarer| find_info(&class_db, &declarer, method))
        .and_then(|info| info.get_or_nil("flags").try_to::<i64>().ok())
        .is_some_and(|flags| flags as u64 & MethodFlags::STATIC.ord() != 0)
}

fn find_declarer(class_db: &Gd<ClassDb>, class: &str, method: &str) -> Option<StringName> {
    let mut current = StringName::from(class);
    while !current.is_empty() {
        let declares = class_db
            .class_has_method_ex(&current, method)
            .no_inheritance(true)
            .done();
        if declares {
            return Some(current);
        }
        current = class_db.get_parent_class(&current);
    }
    None
}

fn read_parameter(mrb: &Mrb, name: String, class: Value) -> Result<Parameter, String> {
    let path = class
        .funcall(mrb, c"to_s", ())
        .ok()
        .and_then(String::from_value)
        .unwrap_or_default();
    let builtin = match path.as_str() {
        "Godot::Variant" => Some(VariantType::NIL),
        "Godot::Bool" => Some(VariantType::BOOL),
        "Integer" => Some(VariantType::INT),
        "Float" => Some(VariantType::FLOAT),
        "String" => Some(VariantType::STRING),
        "Symbol" => Some(VariantType::STRING_NAME),
        "Array" => Some(VariantType::ARRAY),
        "Hash" => Some(VariantType::DICTIONARY),
        _ => None,
    };
    if let Some(kind) = builtin {
        return Ok(Parameter::new(name, kind));
    }
    if let Some(engine_name) = path.strip_prefix("Godot::") {
        if let Some(kind) = kind_by_name(engine_name) {
            return Ok(Parameter::new(name, kind));
        }
        if ClassDb::singleton().class_exists(engine_name) {
            return Ok(Parameter::new(name, VariantType::OBJECT).with_class(engine_name.to_owned()));
        }
        return Err(describe_unknown_type(&path));
    }
    let engine_class = RClass::from_value(class)
        .and_then(|class| find_engine_ancestor(mrb, class))
        .ok_or_else(|| describe_unknown_type(&path))?;
    let class_name = editor_name_by_class_path(mrb, &path).unwrap_or(engine_class);
    Ok(Parameter::new(name, VariantType::OBJECT).with_class(class_name))
}

fn describe_mismatch(mrb: &Mrb, default: &Variant, class: &str) -> Option<String> {
    let kind = default.get_type();
    if kind == VariantType::NIL {
        return None;
    }
    let Ok(object) = default.try_to::<Gd<Object>>() else {
        return Some(name_type(kind));
    };
    (!is_of_class(mrb, &object, class)).then(|| resolve_class_name(&object))
}

fn is_of_class(mrb: &Mrb, object: &Gd<Object>, class: &str) -> bool {
    if let Some(engine_class) = class.strip_prefix("Godot::") {
        let object_class = StringName::from(&object.get_class());
        return ClassDb::singleton().is_parent_class(&object_class, engine_class);
    }
    let Some(file) = file_by_class_path(mrb, class) else {
        return false;
    };
    collect_script_files(object).any(|path| path == file)
}

fn resolve_class_name(object: &Gd<Object>) -> String {
    collect_script_files(object)
        .next()
        .and_then(|path| editor_name_by_path(&path))
        .unwrap_or_else(|| object.get_class().to_string())
}

fn collect_script_files(object: &Gd<Object>) -> impl Iterator<Item = String> {
    let mut script = object.get_script().map(Gd::upcast::<Script>);
    std::iter::from_fn(move || {
        let written = script.take()?;
        script = written.get_base_script();
        Some(written.get_path().to_string())
    })
}

fn read_element_type(mrb: &Mrb, class: Value) -> Result<ElementType, String> {
    let path = class
        .funcall(mrb, c"to_s", ())
        .ok()
        .and_then(String::from_value)
        .unwrap_or_default();
    let parameter = read_parameter(mrb, String::new(), class)?;
    if parameter.kind != VariantType::OBJECT {
        return Ok(ElementType {
            kind: parameter.kind,
            hint: PropertyHint::NONE,
            name: String::new(),
            engine_class: String::new(),
            script: None,
        });
    }
    let (engine_class, script) = match path.strip_prefix("Godot::") {
        Some(engine_class) => (engine_class.to_owned(), None),
        None => (
            RClass::from_value(class)
                .and_then(|class| find_engine_ancestor(mrb, class))
                .ok_or_else(|| describe_unknown_type(&path))?,
            file_by_class_path(mrb, &path)
                .and_then(|file| ResourceLoader::singleton().load(&file))
                .and_then(|resource| resource.try_cast::<Script>().ok()),
        ),
    };
    let class_db = ClassDb::singleton();
    let hint = if class_db.is_parent_class(&engine_class, "Resource") {
        PropertyHint::RESOURCE_TYPE
    } else if class_db.is_parent_class(&engine_class, "Node") {
        PropertyHint::NODE_TYPE
    } else {
        return Err("Export type can only be built-in, a resource, a node, or an enum.".to_owned());
    };
    Ok(ElementType {
        kind: VariantType::OBJECT,
        hint,
        name: parameter.class_name,
        engine_class,
        script,
    })
}

fn hint_by_class(mrb: &Mrb, class: &str) -> Result<(PropertyHint, String), String> {
    if let Some(engine_class) = class.strip_prefix("Godot::") {
        let class_db = ClassDb::singleton();
        if !class_db.class_exists(engine_class) {
            return Err(describe_unknown_type(class));
        }
        if class_db.is_parent_class(engine_class, "Resource") {
            return Ok((PropertyHint::RESOURCE_TYPE, engine_class.to_owned()));
        }
        if class_db.is_parent_class(engine_class, "Node") {
            return Ok((PropertyHint::NODE_TYPE, engine_class.to_owned()));
        }
        return Err("Export type can only be built-in, a resource, a node, or an enum.".to_owned());
    }
    let name = editor_name_by_class_path(mrb, class).ok_or_else(|| describe_unknown_type(class))?;
    let is_resource = file_by_class_path(mrb, class)
        .and_then(|file| ResourceLoader::singleton().load(&file))
        .and_then(|resource| resource.try_cast::<Script>().ok())
        .is_some_and(|script| {
            ClassDb::singleton().is_parent_class(&script.get_instance_base_type(), "Resource")
        });
    let hint = if is_resource {
        PropertyHint::RESOURCE_TYPE
    } else {
        PropertyHint::NODE_TYPE
    };
    Ok((hint, name))
}

fn engine_class_by_member(mrb: &Mrb, class: RClass, name: &str) -> Option<String> {
    let engine_class = find_engine_ancestor(mrb, class)?;
    let mut class_db = ClassDb::singleton();
    let has_member = class_db.class_has_signal(engine_class.as_str(), name)
        || class_db.class_has_integer_constant(engine_class.as_str(), name)
        || !class_db
            .class_get_property_setter(engine_class.as_str(), name)
            .is_empty()
        || !class_db
            .class_get_property_getter(engine_class.as_str(), name)
            .is_empty();
    has_member.then_some(engine_class)
}

impl EngineObject {
    fn new(object: Gd<Object>) -> Self {
        Self(ManuallyDrop::new(object), Standing::Plain)
    }

    // The object a script made, which the realm holds under its key.
    fn new_scripted(object: Gd<Object>) -> Self {
        Self(ManuallyDrop::new(object), Standing::Scripted)
    }
}

fn make(mrb: &Mrb, class: RClass) -> Result<Value, Error> {
    let path = class.path(mrb).unwrap_or_default();
    let name = read_engine_name(&path);
    let class_db = ClassDb::singleton();
    if !class_db.can_instantiate(name) {
        let message = format!("the engine makes no objects of {path}");
        return Err(make_not_implemented_error(mrb, &message));
    }
    let object = class_db.instantiate(name).to::<Gd<Object>>();
    Ok(mrb.wrap_as(EngineObject::new(object), class).as_value())
}

fn make_scripted(mrb: &Mrb, class: RClass) -> Result<Value, Error> {
    let path = class.path(mrb);
    let script = path
        .as_ref()
        .and_then(|path| script_by_class_path(mrb, path))
        .filter(|script| !script.get_instance_base_type().is_empty());
    let class_name = || {
        path.clone()
            .unwrap_or_else(|| "an unnamed class".to_owned())
    };
    let Some(script) = script else {
        let message = format!("no script defines {}, so it makes no object", class_name());
        return Err(make_not_implemented_error(mrb, &message));
    };
    let mut object = ClassDb::singleton()
        .instantiate(&script.get_instance_base_type())
        .to::<Gd<Object>>();
    let id = object.instance_id();
    object.set_script(&script);
    if object.get_script().is_none() {
        if !id.is_ref_counted() {
            object.free();
        }
        let message = format!("{}'s script refused its object here", class_name());
        return Err(make_not_implemented_error(mrb, &message));
    }
    let held = mrb
        .wrap_as(EngineObject::new_scripted(object), class)
        .as_value();
    let key = derive_object_key(id);
    if id.is_ref_counted() {
        realm::hold_loose(mrb, key, held);
    } else {
        realm::hold(mrb, key, held)?;
    }
    Ok(held)
}

fn script_by_class_path(mrb: &Mrb, path: &str) -> Option<Gd<Script>> {
    let names: Vec<String> = path.split("::").map(str::to_owned).collect();
    let script_path = (1..=names.len()).rev().find_map(|outer| {
        let file = realm::file_by_constant(mrb, &names[..outer])?;
        Some(match &names[outer..] {
            [] => file,
            inner => realm::join_inner_path(&file, inner),
        })
    })?;
    ResourceLoader::singleton()
        .load(&script_path)
        .and_then(|resource| resource.try_cast::<Script>().ok())
}

fn resolve(mrb: &Mrb, receiver: Value, name: Symbol) -> Result<Value, Error> {
    let held = <&EngineObject>::try_convert(receiver, mrb)?;
    let name = name.name(mrb).unwrap_or_default();
    let object = held.borrow_live_object(mrb, &name)?;
    let class = StringName::from(&object.get_class());
    let mut class_db = ClassDb::singleton();
    let property = if let Some(property) = name.strip_suffix('=') {
        Some((property, "set"))
    } else if object.has_method(name.as_str()) {
        None
    } else {
        Some((name.as_str(), "get"))
    };
    let target = match property {
        Some((property, accessor)) => {
            accessor_by_property(&mut class_db, &class, property, accessor).to_string()
        }
        None => name.clone(),
    };
    if target.is_empty() {
        return Ok(qnil().as_value());
    }
    let extended = find_engine_ancestor(mrb, receiver.class(mrb));
    // A setter takes the value beside any index, a getter nothing more.
    let takes_index = |accessor: &str| {
        let values = usize::from(accessor == "set");
        Arity::find(&class.to_string(), &target).is_some_and(|arity| arity.required > values)
    };
    if let Some((property, accessor)) = property.filter(|(_, accessor)| takes_index(accessor)) {
        let declared = extended.is_some_and(|extended| {
            let extended = StringName::from(extended.as_str());
            accessor_by_property(&mut class_db, &extended, property, accessor).to_string() == target
        });
        return resolve_indexed_property(mrb, accessor, property, declared);
    }
    let extended =
        extended.filter(|extended| class_db.class_has_method(extended.as_str(), target.as_str()));
    let declared = extended.is_some();
    let bound = extended
        .and_then(|extended| BoundMethod::find(&extended, &target))
        .map_or_else(|| qnil().as_value(), |bound| mrb.wrap(bound).as_value());
    let target = Symbol::from(mrb.intern(target.as_bytes())?).as_value();
    Ok(mrb
        .ary_new_from_values(&[target, declared.into_value(mrb), bound])
        .as_value())
}

fn accessor_by_property(
    class_db: &mut Gd<ClassDb>,
    class: &StringName,
    property: &str,
    accessor: &str,
) -> StringName {
    if accessor == "set" {
        class_db.class_get_property_setter(class, property)
    } else {
        class_db.class_get_property_getter(class, property)
    }
}

fn has_engine_member(mrb: &Mrb, class: RClass, name: Symbol) -> bool {
    let Some(extended) = find_engine_ancestor(mrb, class) else {
        return false;
    };
    let name = name.name(mrb).unwrap_or_default();
    let extended = StringName::from(extended.as_str());
    let mut class_db = ClassDb::singleton();
    if let Some(property) = name.strip_suffix('=') {
        return !class_db
            .class_get_property_setter(&extended, property)
            .is_empty();
    }
    class_db.class_has_method(&extended, name.as_str())
        || !class_db
            .class_get_property_getter(&extended, name.as_str())
            .is_empty()
}

fn singleton(mrb: &Mrb, class: RClass) -> Value {
    let path = class.path(mrb).unwrap_or_default();
    let name = read_engine_name(&path);
    let engine = Engine::singleton();
    if !engine.has_singleton(name) {
        return qnil().as_value();
    }
    engine
        .get_singleton(name)
        .map(|object| mrb.wrap_as(EngineObject::new(object), class).as_value())
        .unwrap_or_else(|| qnil().as_value())
}

fn refuse_instance_method(mrb: &Mrb, class: RClass, name: Symbol) -> Result<Value, Error> {
    let name = name.name(mrb).unwrap_or_default();
    let path = class.path(mrb).unwrap_or_default();
    let class = read_engine_name(&path);
    if ClassDb::singleton().class_has_method(class, name.as_str()) {
        return Err(make_no_method_error(
            mrb,
            &describe_instance_call(&name, class),
        ));
    }
    Ok(qnil().as_value())
}

fn call_static(mrb: &Mrb, class: RClass, name: Symbol, args: RArray) -> Result<Value, Error> {
    let name = name_by_symbol(mrb, name);
    let path = class.path(mrb).unwrap_or_default();
    let class = read_engine_name(&path);
    let data = super::data(mrb);
    let args = to_arguments(mrb, data, args.entries(mrb))?;
    let answer = ClassDb::singleton()
        .try_class_call_static(class, &name, &args)
        .map_err(|error| make_call_refusal(mrb, &error, class, &name.to_string(), args.len()))?;
    Ok(RubyCrossing(&answer).into_ruby(mrb, data))
}

pub(super) fn wrap_object(mrb: &Mrb, data: &BridgeData, object: Gd<Object>) -> Value {
    if let Some(held) = realm::object_by_key(mrb, derive_object_key(object.instance_id())) {
        return held;
    }
    let class = class_by_name(mrb, data, find_exposed_class(&object))
        .unwrap_or_else(|| object_class(mrb, data));
    mrb.wrap_as(EngineObject::new(object), class).as_value()
}

fn find_exposed_class(object: &Gd<Object>) -> StringName {
    let mut name = StringName::default();
    // SAFETY: the interface is initialized while the extension runs and
    // `object` is alive; the name it writes over is empty, so it holds
    // nothing to release.
    unsafe {
        sys::interface_fn!(object_get_class_name)(
            object.obj_sys().cast_const(),
            sys::get_library(),
            name.string_sys_mut().cast(),
        );
    }
    name
}

fn engine_constant_by_name(mrb: &Mrb, class: RClass, name: Symbol) -> Value {
    let name = name.name(mrb).unwrap_or_default();
    let path = class.path(mrb).unwrap_or_default();
    let class = read_engine_name(&path);
    let class_db = ClassDb::singleton();
    if !class_db.class_has_integer_constant(class, name.as_str()) {
        return qnil().as_value();
    }
    class_db
        .class_get_integer_constant(class, name.as_str())
        .into_value(mrb)
}

impl EngineObject {
    /// The engine object as the engine takes it, unless it was freed.
    pub fn to_variant(&self) -> Result<Variant, String> {
        if self.0.is_instance_valid() {
            Ok(self.0.to_variant())
        } else {
            Err("a freed engine object cannot reach the engine".to_owned())
        }
    }

    // The engine object, lent rather than copied since a copy checks it
    // again, or the Godot::CallError calling `method` on a freed one raises,
    // worded as GDScript words it.
    fn borrow_live_object(
        &self,
        mrb: &Mrb,
        method: &(impl fmt::Display + ?Sized),
    ) -> Result<&Gd<Object>, Error> {
        if self.0.is_instance_valid() {
            Ok(&*self.0)
        } else {
            let message = format!(
                "Attempt to call function '{method}' in base 'previously freed' on a null instance."
            );
            Err(make_call_error(mrb, &message))
        }
    }
}

#[derive(GodotClass)]
#[class(base = RefCounted, no_init)]
pub struct RubyObject {
    hold: Hold,
    // What the engine prints it as: the Ruby object's class.
    class: GString,
    base: Base<RefCounted>,
}

impl RubyObject {
    /// A new `RubyObject` for the object of class `class` that `key` holds.
    pub fn new(key: Key, class: &str) -> Gd<Self> {
        Gd::from_init_fn(|base| Self {
            hold: Hold(key),
            class: GString::from(class),
            base,
        })
    }

    /// The key the realm holds the Ruby object under.
    pub fn key(&self) -> Key {
        self.hold.0
    }
}

fn to_ruby(mrb: &Mrb, data: &BridgeData, variant: &Variant) -> Value {
    match variant.get_type() {
        VariantType::BOOL => variant.to::<bool>().into_value(mrb),
        VariantType::INT => variant.to::<i64>().into_value(mrb),
        VariantType::FLOAT => variant.to::<f64>().into_value(mrb),
        VariantType::STRING => mrb
            .str_new(variant.to::<GString>().to_string().as_bytes())
            .as_value(),
        VariantType::STRING_NAME => intern_symbol(mrb, data, variant.to::<StringName>()),
        VariantType::OBJECT => match variant
            .try_to::<Gd<Object>>()
            .ok()
            .filter(Gd::is_instance_valid)
        {
            None => qnil().as_value(),
            // Only a reference-counted object can be a Ruby object handed to
            // the engine; a node, the other kind the realm holds, never is.
            Some(object) if object.instance_id().is_ref_counted() => {
                match object.try_cast::<RubyObject>() {
                    Ok(held) => realm::object_by_key(mrb, held.bind().key())
                        .unwrap_or_else(|| qnil().as_value()),
                    Err(object) => object::wrap_object(mrb, data, object),
                }
            }
            Some(object) => object::wrap_object(mrb, data, object),
        },
        kind if value_type::is_value_type(kind) => value_type::wrap_variant(mrb, data, variant),
        _ => qnil().as_value(),
    }
}

fn engine_superclass_by_name(mrb: &Mrb, _godot: Value, name: Symbol) -> Value {
    let class_db = ClassDb::singleton();
    let Some(name) = name
        .name(mrb)
        .ok()
        .filter(|name| class_db.class_exists(name))
    else {
        return qnil().as_value();
    };
    let parent = class_db.get_parent_class(&name).to_string();
    mrb.str_new(parent.as_bytes()).as_value()
}

