    base: Base<Node>,
    run: Run,
    // Whether every test file ran without an error, which a passing run
    // still needs.
    is_loaded: bool,
}

#[godot_api]
impl INode for RubyTestRunner {
    fn ready(&mut self) {
        let args = take_user_args();
        let run_as_asked = choose_test_directories(&args)
            .and_then(|directories| collect_test_files(&directories))
            .and_then(|tests| Ok((tests, parse_test_options(&args)?)));
        match run_as_asked {
            Ok((tests, mut options)) => {
                options.load_failures = load(&tests);
                self.is_loaded = options.load_failures.is_empty();
                self.run = Run::Starting(options);
                let tree = self.base().get_tree();
                tree.signals()
                    .process_frame()
                    .connect_other(&*self, |runner| runner.run_frame(Frame::Process));
                tree.signals()
                    .physics_frame()
                    .connect_other(&*self, |runner| runner.run_frame(Frame::Physics));
            }
            Err(refused) => {
                error!("{refused}");
                self.quit(false);
            }
        }
    }
}

fn take_user_args() -> Vec<String> {
    let args: Vec<String> = Os::singleton()
        .get_cmdline_user_args()
        .as_slice()
        .iter()
        .map(GString::to_string)
        .collect();
    if args.is_empty() {
        take_run_file_args()
    } else {
        args
    }
}

pub fn nest_template(script: &mut Gd<RubyScript>, path: &str) {
    if !script.bind().take_template_mark() {
