#[class(base = ResourceFormatSaver, init, tool)]
pub struct ResourceFormatSaverRubyScript {
    base: Base<ResourceFormatSaver>,
}

pub fn register() {
    let saver = ResourceFormatSaverRubyScript::new_gd();
    ResourceSaver::singleton().add_resource_format_saver(&saver);
    *SAVER.lock().unwrap() = Some(saver.instance_id());
}

pub fn unregister() {
    if let Some(id) = SAVER.lock().unwrap().take() {
        let saver = Gd::<ResourceFormatSaverRubyScript>::from_instance_id(id);
        ResourceSaver::singleton().remove_resource_format_saver(&saver);
    }
}

#[godot_api]
impl IResourceFormatSaver for ResourceFormatSaverRubyScript {
    // The file takes the source as Godot holds it, and a script saved in the
    // editor reloads, as a GDScript does.
    fn save(&mut self, resource: Option<Gd<Resource>>, path: GString, _flags: u32) -> Error {
        let Some(mut script) = resource.and_then(|resource| resource.try_cast::<RubyScript>().ok())
        else {
            return Error::ERR_INVALID_PARAMETER;
        };
        editor::nest_template(&mut script, &path.to_string());
        let Some(mut file) = FileAccess::open(&path, ModeFlags::WRITE) else {
            return FileAccess::get_open_error();
        };
        file.store_string(&script.get_source_code());
        let error = file.get_error();
        if error != Error::OK && error != Error::ERR_FILE_EOF {
            return Error::ERR_CANT_CREATE;
        }
        drop(file);
        editor::reload_saved(&mut script);
        Error::OK
    }

    fn recognize(&self, resource: Option<Gd<Resource>>) -> bool {
        resource.is_some_and(|resource| resource.try_cast::<RubyScript>().is_ok())
    }

    fn get_recognized_extensions(&self, resource: Option<Gd<Resource>>) -> PackedStringArray {
        if self.recognize(resource) {
            PackedStringArray::from(&[GString::from("rb")])
        } else {
            PackedStringArray::new()
        }
    }
}

pub fn attach(script: &Gd<RubyScript>) {
    let data = Box::into_raw(Box::new(ClassInstance {
        script: script.instance_id(),
    }));
    // SAFETY: the interface is initialized while the extension runs; `INFO`
    // is static, and Godot hands `data` back to each callback until `free`
    // takes it, which it does as it frees the script.
    unsafe {
        let instance = sys::interface_fn!(script_instance_create3)(&INFO, data.cast());
        sys::interface_fn!(object_set_script_instance)(script.obj_sys(), instance.cast());
    }
}

fn call_on_class(script: &Gd<RubyScript>, method: &str, args: &[&Variant]) -> Option<Variant> {
    let constant = {
        let script = script.bind();
        (method == "new" || script.has_class_method(method)).then(|| script.class_constant())
    }?;
    let named: [Variant; 2] = [
        GString::from(&constant).to_variant(),
        StringName::from(method).to_variant(),
    ];
    let args: SmallVec<[_; 6]> = named
        .iter()
        .chain(args.iter().copied())
        .map(RubyCrossing)
        .collect();
    let answer =
        realm::enter(|realm| realm.call::<_, EngineCrossing>("Godot", c"__call_class__", args))
            .map(|EngineCrossing(answer)| answer)
            .unwrap_or_else(|failed: RubyError| {
                failed.write(&GodotLog);
                Variant::nil()
            });
    Some(answer)
}

fn find_script(data: sys::GDExtensionScriptInstanceDataPtr) -> Option<Gd<RubyScript>> {
    // SAFETY: `data` is what `attach` boxed, alive until `free`.
    let id = unsafe { &*data.cast::<ClassInstance>() }.script;
    Gd::try_from_instance_id(id).ok()
}

