fn set_skin_str(
    world: &crate::godot::nodes::SiloWorld,
    mut s: Gd<Node>,
    skin: &str,
) -> Option<Gd<Node>> {
    if let Some(v) = s.find_child(skin) {
        return Some(v);
    } else {
        if let Some(skin_scene) = world.get_skin(&skin.to_string()) {
            let mut v = skin_scene
                .instantiate()
                .expect("Failed to instantiate skin");
            v.set_name(skin);
            s.add_child(&v);
            return Some(v);
        }
    }
    None
}

