    parent_scope_prop: PhantomVar<Variant>,
    parent: RefCell<Option<Gd<BTBlackboardNative>>>,

    // Insertion-ordered entries: (name, variable object).
    vars: RefCell<Vec<(String, Gd<BTTaskVariableNative>)>>,
