pub fn tick(task: &BTTaskNative) -> i64 {
    let (runner, sub_tree) = {
        let d = task.data();
        (d.sub.runner.clone(), d.sub.tree.clone())
    };
    let (Some(runner), Some(sub_tree)) = (runner, sub_tree) else {
        return FAILURE;
    };
    if sub_tree.bind().data().root.is_none() {
        return FAILURE;
    }
    let Ok(runner_native) = runner.clone().try_cast::<BTRunnerNative>() else {
        return FAILURE;
    };

    let owner_id = task.data().owner_ref;
    let parent_runner = owner_id
        .and_then(|id| Gd::<Node>::try_from_instance_id(id).ok())
        .and_then(|node| node.try_cast::<BTRunnerNative>().ok());

    if let Some(parent) = &parent_runner {
        let budget = parent.bind().budget_handle();
        let delta = parent.bind().current_delta();
        runner_native.bind().share_budget(budget);
        runner_native.bind().set_delta(delta);
    } else {
        runner_native.bind().share_budget(None);
    }

    let delta = runner_native.bind().current_delta();
    let mut runner_node: Gd<Node> = runner_native.clone().upcast();
    let status = runner_node
        .call("tick", &[delta.to_variant()])
        .try_to::<i64>()
        .unwrap_or(FAILURE);

    if let Some(parent) = &parent_runner {
        if let Some(budget) = parent.bind().budget_handle() {
            let executions = budget.borrow().executions;
            parent.bind().set_task_executions(executions);
        }
    }
    status
}

fn resolve_param(
    task: &BTTaskNative,
    name: &GString,
    raw: Variant,
    default_val: Variant,
    blackboard: Option<Gd<BTBlackboardNative>>,
) -> Variant {
    let mut binding_key: Option<String> = None;
    if let Ok(dict) = raw.try_to::<VarDictionary>() {
        if dict.get("is_blackboard").map(|v| v.to::<bool>()).unwrap_or(false) {
            binding_key = Some(
                dict.get("key")
                    .map(|v| v.to::<GString>().to_string())
                    .unwrap_or_default(),
            );
        }
    }
    if binding_key.is_none() && raw.get_type() == VariantType::STRING {
        let text = raw.to::<GString>().to_string();
        if text.starts_with("@@") || text.starts_with("$$") {
            return GString::from(&text[1..]).to_variant();
        }
        if let Some(rest) = text.strip_prefix('@').or_else(|| text.strip_prefix('$')) {
            binding_key = Some(rest.to_string());
        }
    }

    let Some(key) = binding_key else {
        return raw;
    };

    if let Some(bb) = blackboard {
        let key_g = GString::from(key.as_str());
        let has = bb.bind().has_var(key_g.clone());
        if has {
            return bb.bind().get_var(key_g, default_val);
        }
    }

    // Warn once per (task, parameter) pair.
    let key_name = name.to_string();
    let first = task.data_mut().warned_bindings.insert(key_name);
    if first {
        let d = task.data();
        let label = if d.friendly_name.is_empty() {
            d.type_name.clone()
        } else {
            d.friendly_name.clone()
        };
        drop(d);
        godot_warn!(
            "BTTask '{}': blackboard binding '@{}' for parameter '{}' not found; using default",
            label,
            key,
            name
        );
    }
    default_val
}

