#[inline]
pub fn on_update(task: &Gd<BTTaskNative>) -> i64 {
    let (overrides, kind) = {
        let guard = task.bind();
        let d = guard.data();
        (d.overrides, d.kind)
    };
    if overrides & hook::ON_UPDATE != 0 {
        return call_int(task, "on_update", &[]);
    }
    if kind == Kind::SubTree {
        return crate::subtree::tick(&task.bind());
    }
