        return call_int(task, "decorate", &[status.to_variant()]);
    }
    task.bind().bt_decorate(status)
}

pub fn override_status(task: &Gd<BTTaskNative>, status: i64) -> i64 {
    if has_override(task, hook::OVERRIDE_STATUS) {
        return call_int(task, "override_status", &[status.to_variant()]);
    }
    task.bind().bt_override_status(status)
}

fn node_parent_shape(
    type_name: &str,
    registry: Option<&Gd<BTTaskRegistryNative>>,
) -> (bool, bool) {
    if let Some(registry) = registry {
        let task = registry.bind().create_task(GString::from(type_name));
        let __g_td = task.bind();
        let td = __g_td.data();
        let is_decorator = td.kind.is_decorator()
            || registry
                .bind()
                .get_category(GString::from(type_name))
                .to_string()
                == "Decorator";
        return (td.kind.has_children(), is_decorator);
    }
    (false, false)
}

pub struct Fonts {
    fonts: Vec<Gd<Font>>,
    /// System fonts discovered per codepoint, appended behind `fonts`.
    extra: RefCell<Vec<Gd<Font>>>,
    tried_paths: RefCell<HashSet<String>>,
    primary_cache: RefCell<HashMap<(u32, u8), bool>>,
    fallback_cache: RefCell<HashMap<(u32, bool), i16>>,
}

fn load() -> Result<Self, String> {
    let embed = |name: &str, bytes: &[u8]| -> Result<Gd<Font>, String> {
        let mut font = FontFile::new_gd();
        font.set_data(&PackedByteArray::from(bytes));
        if font.get_data().is_empty() {
            return Err(format!("font {name} failed to parse"));
        }
        Ok(font.upcast())
    };
    let system = |family: &str| -> Gd<Font> {
        let mut font = SystemFont::new_gd();
        font.set_font_names(&PackedStringArray::from([GString::from(family)]));
        font.upcast()
    };
    let fonts = vec![
        embed(
            "Regular",
            include_bytes!("../fonts/JetBrainsMonoNerdFont-Regular.ttf"),
        )?,
        embed(
            "Bold",
            include_bytes!("../fonts/JetBrainsMonoNerdFont-Bold.ttf"),
        )?,
        embed(
            "Italic",
            include_bytes!("../fonts/JetBrainsMonoNerdFont-Italic.ttf"),
        )?,
        embed(
            "BoldItalic",
            include_bytes!("../fonts/JetBrainsMonoNerdFont-BoldItalic.ttf"),
        )?,
        embed(
            "NotoEmoji",
            include_bytes!("../fonts/NotoEmoji-Regular.ttf"),
        )?,
        embed(
            "JuliaMono",
            include_bytes!("../fonts/JuliaMono-Regular.ttf"),
        )?,
        embed(
            "NotoColorEmoji",
            include_bytes!("../fonts/NotoColorEmoji.ttf"),
        )?,
        system("monospace"),
        system("sans-serif"),
    ];
    Ok(Self {
        fonts,
        extra: RefCell::new(Vec::new()),
        tried_paths: RefCell::new(HashSet::new()),
        primary_cache: RefCell::new(HashMap::new()),
        fallback_cache: RefCell::new(HashMap::new()),
    })
}

pub fn primary(&self) -> &Gd<Font> {
    &self.fonts[0]
}

pub fn style_font(&self, style: u8) -> &Gd<Font> {
    &self.fonts[style as usize]
}

pub fn resolve(&self, cp: u32, style: u8, wide: impl FnOnce() -> bool) -> Option<Gd<Font>> {
    let primary = *self
        .primary_cache
        .borrow_mut()
        .entry((cp, style))
        .or_insert_with(|| self.fonts[style as usize].has_char(cp));
    if primary {
        return Some(self.fonts[style as usize].clone());
    }
    let wide = wide();
    let idx = *self
        .fallback_cache
        .borrow_mut()
        .entry((cp, wide))
        .or_insert_with(|| self.compute_fallback(cp, wide));
    match usize::try_from(idx) {
        Err(_) => None,
        Ok(i) if i < self.fonts.len() => Some(self.fonts[i].clone()),
        Ok(i) => Some(self.extra.borrow()[i - self.fonts.len()].clone()),
    }
}

fn discover(&self, cp: u32) -> i16 {
    let Some(ch) = char::from_u32(cp) else {
        return -1;
    };
    let paths =
        Os::singleton().get_system_font_path_for_text("monospace", ch.to_string().as_str());
    for path in paths.as_slice() {
        let key = path.to_string();
        if !self.tried_paths.borrow_mut().insert(key) {
            continue;
        }
        let mut font = FontFile::new_gd();
        if font.load_dynamic_font(path) != GdError::OK {
            continue;
        }
        // Keep every loaded font: the extra scan serves codepoints this
        // one covers even when the requested one is missing from it.
        let covers = font.has_char(cp);
        let mut extra = self.extra.borrow_mut();
        extra.push(font.upcast());
        if covers {
            return (self.fonts.len() + extra.len() - 1) as i16;
        }
    }
    -1
}

pub fn encode_key(
    &mut self,
    term: &Terminal<'static, 'static>,
    ev: &Gd<InputEventKey>,
) -> &[u8] {
    self.buf.clear();

    let action = if ev.is_echo() {
        key::Action::Repeat
    } else if ev.is_pressed() {
        key::Action::Press
    } else {
        key::Action::Release
    };

    let mods = event_mods(ev.clone().upcast());
    let (vt_key, unshifted) = map_key(ev.get_keycode()).unwrap_or((Key::Unidentified, '\0'));

    // Control combos carry no text; the encoder derives them itself.
    // Windows reports AltGr as Ctrl+Alt, and those combos do carry text.
    let unicode = ev.get_unicode();
    let altgr =
        cfg!(windows) && mods.contains(key::Mods::CTRL) && mods.contains(key::Mods::ALT);
    let text = match char::from_u32(unicode) {
        Some(ch)
            if action != key::Action::Release
                && unicode >= 0x20
                && unicode != 0x7f
                && (!mods.contains(key::Mods::CTRL) || altgr)
                && !mods.contains(key::Mods::SUPER) =>
        {
            Some(ch)
        }
        _ => None,
    };

    // Modifiers that already shaped the produced text are consumed.
    let consumed = match text {
        Some(_) if altgr => mods & (key::Mods::SHIFT | key::Mods::CTRL | key::Mods::ALT),
        Some(_) => mods & key::Mods::SHIFT,
        None => key::Mods::empty(),
    };

    let mut utf8 = [0u8; 4];
    self.key_event
        .set_action(action)
        .set_key(vt_key)
        .set_mods(mods)
        .set_consumed_mods(consumed)
        .set_unshifted_codepoint(unshifted)
        .set_utf8(text.map(|ch| &*ch.encode_utf8(&mut utf8)));

    let _ = self
        .key_encoder
        .set_options_from_terminal(term)
        .encode_to_vec(&self.key_event, &mut self.buf);
    &self.buf
}

pub fn event_mods(ev: Gd<InputEventWithModifiers>) -> key::Mods {
    let mut mods = key::Mods::empty();
    if ev.is_shift_pressed() {
        mods |= key::Mods::SHIFT;
    }
    if ev.is_ctrl_pressed() {
        mods |= key::Mods::CTRL;
    }
    if ev.is_alt_pressed() {
        mods |= key::Mods::ALT;
    }
    if ev.is_meta_pressed() {
        mods |= key::Mods::SUPER;
    }
    mods
}

#[derive(GodotClass)]
#[class(tool, init, base = EditorExportPlugin, internal)]
struct GodottyExportPlugin {
    base: Base<EditorExportPlugin>,
}

#[godot_api]
impl IEditorExportPlugin for GodottyExportPlugin {
    fn export_file(&mut self, path: GString, _type: GString, _features: PackedStringArray) {
        if path.to_string().starts_with("res://addons/godotty/") && editor_only_libraries() {
            self.base_mut().skip();
        }
    }

    // "!" sorts before the engine's "GDExtension" plugin, so skip() wins
    // before its missing-library warning.
    fn get_name(&self) -> GString {
        "!godotty".into()
    }

    // Defaultless trait methods; never called while begin_customize_* is false.
    fn customize_resource(&mut self, _res: Gd<Resource>, _path: GString) -> Option<Gd<Resource>> {
        None
    }

    fn customize_scene(&mut self, _scene: Gd<Node>, _path: GString) -> Option<Gd<Node>> {
        None
    }

    fn get_customization_configuration_hash(&self) -> u64 {
        0
    }
}

fn editor_only_libraries() -> bool {
    let mut config = godot::classes::ConfigFile::new_gd();
    if config.load("res://addons/godotty/godotty.gdextension") != godot::global::Error::OK
        || !config.has_section("libraries")
    {
        return true;
    }
    config
        .get_section_keys("libraries")
        .as_slice()
        .iter()
        .all(|key| key.to_string().split('.').any(|tag| tag == "editor"))
}

fn new_wired_terminal(owner: Gd<Object>) -> Gd<Terminal> {
    let mut terminal = Terminal::new_alloc();
    {
        let mut t = terminal.bind_mut();
        t.run_in_editor = true;
        if let Some(shell) = configured_shell() {
            t.shell = shell.as_str().into();
        }
        if let Some(size) = EditorInterface::singleton()
            .get_editor_settings()
            .map(|s| s.get_setting(FONT_SIZE_SETTING))
            .and_then(|v| v.try_to::<i64>().ok())
        {
            t.font_size = (size as i32).clamp(6, 72);
        }
    }
    for (signal, method) in [
        ("title_changed", "on_title_changed"),
        ("exited", "on_exited"),
    ] {
        let cb = owner
            .callable(method)
            .bindv(&varray![&terminal.to_variant()]);
        terminal.connect_flags(signal, &cb, ConnectFlags::DEFERRED);
    }
    terminal
}

fn ensure_setting(settings: &mut Gd<EditorSettings>, name: &str, default: &Variant) {
    let current = settings
        .has_setting(name)
        .then(|| settings.get_setting(name))
        .filter(|v| v.get_type() == default.get_type());
    settings.erase(name);
    settings.set_setting(name, current.as_ref().unwrap_or(default));
    settings.set_initial_value(name, default, false);
}

fn ensure_shortcut(
    settings: &mut Gd<EditorSettings>,
    path: &str,
    keycode: GKey,
    ctrl: bool,
    meta: bool,
) {
    let mut key = InputEventKey::new_gd();
    key.set_keycode(keycode);
    key.set_ctrl_pressed(ctrl);
    key.set_meta_pressed(meta);
    let mut shortcut = Shortcut::new_gd();
    shortcut.set_events(&varray![&key.to_variant()]);
    settings.add_shortcut(path, &shortcut);
}

fn add_hint(
    settings: &mut Gd<EditorSettings>,
    name: &str,
    ty: VariantType,
    hint: PropertyHint,
    hint_string: &str,
) {
    let mut info = VarDictionary::new();
    info.set("name", name);
    info.set("type", ty.ord());
    info.set("hint", hint.ord());
    info.set("hint_string", hint_string);
    settings.add_property_info(&info);
}

pub(crate) fn shortcut_matches(path: &str, event: &Gd<InputEvent>) -> bool {
    EditorInterface::singleton()
        .get_editor_settings()
        .and_then(|s| s.get_shortcut(path))
        .is_some_and(|sc| sc.matches_event(event))
}

fn is_descendant(node: &Gd<Node>, ancestor: &Gd<Node>) -> bool {
    let mut current = node.clone();
    while let Some(parent) = current.get_parent() {
        if &parent == ancestor {
            return true;
        }
        current = parent;
    }
    false
}

impl RunCache {
    pub fn new() -> Self {
        Self {
            entries: Default::default(),
            generation: 0,
        }
    }

    /// Draw one run with its first baseline at `(run.x, baseline)`. A
    /// single cell skips shaping, alone it has no ligature context.
    pub fn draw(
        &mut self,
        canvas: Rid,
        font: &Gd<Font>,
        run: Run,
        baseline: f32,
        cell_w: f32,
        font_size: i32,
    ) {
        let origin = Vector2::new(run.x, baseline);
        if run.text.len() == 1 {
            font.draw_char_ex(canvas, origin, run.text.as_bytes()[0] as u32, font_size)
                .modulate(run.fg)
                .done();
            return;
        }
        let Some(ts) = TextServerManager::singleton().get_primary_interface() else {
            return;
        };
        let generation = self.generation;
        let entry = self.entries[run.style as usize]
            .entry(run.text)
            .or_insert_with_key(|text| Entry {
                glyphs: shape(text, font, font_size),
                used: generation,
            });
        entry.used = generation;
        for glyph in &entry.glyphs {
            ts.font_draw_glyph_ex(
                glyph.font_rid,
                canvas,
                glyph.font_size,
                origin + Vector2::new(glyph.cell as f32 * cell_w, 0.0) + glyph.offset,
                glyph.index,
            )
            .color(run.fg)
            .done();
        }
    }

    /// Drop runs not drawn since the last call.
    pub fn end_frame(&mut self) {
        let generation = self.generation;
        for map in &mut self.entries {
            map.retain(|_, entry| entry.used == generation);
        }
        self.generation += 1;
    }
}

fn shape(text: &str, font: &Gd<Font>, font_size: i32) -> Vec<Glyph> {
    let Some(mut ts) = TextServerManager::singleton().get_primary_interface() else {
        return Vec::new();
    };
    let rid = ts.create_shaped_text_ex().direction(Direction::LTR).done();
    ts.shaped_text_add_string(rid, text, &font.get_rids(), font_size as i64);
    let glyphs = ts
        .shaped_text_get_glyphs(rid)
        .iter_shared()
        .map(|g| {
            let get = |key: &str| g.get(key).unwrap_or_default();
            Glyph {
                cell: get("start").try_to().unwrap_or(0),
                index: get("index").try_to().unwrap_or(0),
                font_rid: get("font_rid").try_to().unwrap_or(Rid::Invalid),
                font_size: get("font_size").try_to().unwrap_or(font_size as i64),
                offset: get("offset").try_to().unwrap_or(Vector2::ZERO),
            }
        })
        .collect();
    ts.free_rid(rid);
    glyphs
}

fn rect(canvas: Rid, cell: Rect2, x0: f32, y0: f32, x1: f32, y1: f32, color: Color) {
    RenderingServer::singleton().canvas_item_add_rect(
        canvas,
        Rect2::new(
            Vector2::new(cell.position.x + x0, cell.position.y + y0),
            Vector2::new(x1 - x0, y1 - y0),
        ),
        color,
    );
}

fn polygon(canvas: Rid, cell: Rect2, points: &[(f32, f32)], color: Color) {
    let canvas_points: PackedVector2Array = points
        .iter()
        .map(|&(x, y)| Vector2::new(cell.position.x + x, cell.position.y + y))
        .collect();
    RenderingServer::singleton().canvas_item_add_polygon(
        canvas,
        &canvas_points,
        &PackedColorArray::from([color]),
    );

    let (w, h) = (cell.size.x, cell.size.y);
    let on_boundary = |a: (f32, f32), b: (f32, f32)| {
        (a.0 == b.0 && (a.0 <= 0.0 || a.0 >= w)) || (a.1 == b.1 && (a.1 <= 0.0 || a.1 >= h))
    };
    let mut run: Vec<(f32, f32)> = Vec::with_capacity(points.len() + 1);
    for i in 0..points.len() {
        let (a, b) = (points[i], points[(i + 1) % points.len()]);
        if on_boundary(a, b) {
            if run.len() > 1 {
                stroke(canvas, cell, &run, color, 1.0);
            }
            run.clear();
        } else {
            if run.is_empty() {
                run.push(a);
            }
            run.push(b);
        }
    }
    if run.len() > 1 {
        stroke(canvas, cell, &run, color, 1.0);
    }
}

fn stroke(canvas: Rid, cell: Rect2, points: &[(f32, f32)], color: Color, width: f32) {
    let points: PackedVector2Array = points
        .iter()
        .map(|&(x, y)| Vector2::new(cell.position.x + x, cell.position.y + y))
        .collect();
    RenderingServer::singleton()
        .canvas_item_add_polyline_ex(canvas, &points, &PackedColorArray::from([color]))
        .width(width)
        .antialiased(true)
        .done();
}

#[derive(GodotClass)]
#[class(tool, base = Node, internal)]
pub struct SyncNode {
    base: Base<Node>,
    sync: Option<ExternalSync>,
}

#[godot_api]
impl INode for SyncNode {
    fn init(base: Base<Node>) -> Self {
        SyncNode { base, sync: None }
    }

    fn ready(&mut self) {
        self.sync = ExternalSync::start();
        if self.sync.is_none() {
            godot_warn!("[godotty] file watcher unavailable; external edits sync on focus only");
        }
        self.base_mut().set_process(true);
    }

    fn process(&mut self, delta: f64) {
        if let Some(sync) = self.sync.as_mut() {
            sync.poll(delta);
        }
    }
}

fn sync(&mut self, batch: HashSet<PathBuf>) {
    // The reloads below run synchronously and some grab focus; capture
    // the owner now and restore it once they return, before any prompt
    // they queued (those are deferred) legitimately takes over.
    let focus_before = focus_owner();
    let fresh = self.deliver(batch);
    if !fresh.is_empty() {
        // The exact rescan the focus path runs; it queues itself when a
        // scan is already going.
        if let Some(mut filesystem) = EditorInterface::singleton().get_resource_filesystem() {
            filesystem.scan_sources();
        }
        self.reload_extensions(&fresh);
        self.reload_scenes(&fresh);
        self.queue_shaders(&fresh);
        self.script_pending.extend(fresh);
    }
    self.prune_scene_conflicts();
    // One prompt per tick at most; the retry tick presents whatever had
    // to wait, after the open prompt is answered.
    let presented = self.flush_scripts();
    if !presented {
        self.present_scene_dialog();
    }
    self.flush_shaders();
    restore_focus(focus_before);
}

fn reload_extensions(&mut self, fresh: &[PathBuf]) {
    for path in fresh {
        if is_own(path) {
            continue;
        }
        let config_changed = path.extension().is_some_and(|e| e == "gdextension");
        let Some(extension) = self
            .extensions
            .get(path)
            .cloned()
            .or_else(|| config_changed.then(|| localize(path)).flatten())
        else {
            continue;
        };
        let mut manager = GDExtensionManager::singleton();
        if !manager.is_extension_loaded(&extension) {
            continue;
        }
        // Deferred: reloading can unload this very library, so our own
        // stack must be clear when it happens.
        manager.call_deferred("reload_extension", &[extension.to_variant()]);
        if config_changed {
            self.extensions = extension_map();
        }
    }
}

fn reload_scenes(&mut self, fresh: &[PathBuf]) {
    let editor = EditorInterface::singleton();
    let open = globalized(&editor.get_open_scenes());
    let unsaved = globalized(&editor.get_unsaved_scenes());
    let project = self.root.join("project.godot");
    for path in fresh {
        if *path == project {
            self.project_pending = true;
            continue;
        }
        if !open.contains(path) || !path.exists() {
            continue;
        }
        if self.scene_saves.get(path) == Some(&mtime(path)) {
            continue;
        }
        self.scene_saves.remove(path);
        if unsaved.contains(path) {
            self.scene_dialog_pending.insert(path.clone());
        } else {
            reload_scene(path);
        }
    }
}

fn prune_scene_conflicts(&mut self) {
    if self.scene_conflicts.is_empty() {
        return;
    }
    let editor = EditorInterface::singleton();
    let open = globalized(&editor.get_open_scenes());
    let unsaved = globalized(&editor.get_unsaved_scenes());
    let conflicts = std::mem::take(&mut self.scene_conflicts);
    for path in conflicts {
        if open.contains(&path) && unsaved.contains(&path) {
            self.scene_conflicts.insert(path);
        } else if open.contains(&path)
            && path.exists()
            && self.delivered.get(&path) == Some(&mtime(&path))
            && self.scene_saves.get(&path) != Some(&mtime(&path))
        {
            reload_scene(&path);
        }
    }
}

fn flush_scripts(&mut self) -> bool {
    if self.script_pending.is_empty() && self.script_conflicts.is_empty() {
        return false;
    }
    if !autoreload_enabled() {
        // With autoreload off the editor prompts even for clean tabs;
        // the user chose prompts everywhere, which belongs to the real
        // focus-in, not a background sync.
        self.script_pending.clear();
        self.script_conflicts.clear();
        return false;
    }
    let Some(mut script_editor) = EditorInterface::singleton().get_script_editor() else {
        return false;
    };
    let unsaved = globalized(&script_editor.get_unsaved_files());
    let mut dissolved = false;
    self.script_conflicts.retain(|path| {
        let outstanding = unsaved.contains(path);
        dissolved |= !outstanding;
        outstanding
    });
    // A conflict is an unsaved tab whose file still holds the change we
    // delivered. Presence in script_pending means the file just changed
    // on disk, so an already-tracked conflict here is a new write and
    // re-prompts rather than being skipped.
    let new_conflicts: Vec<PathBuf> = self
        .script_pending
        .iter()
        .filter(|path| {
            unsaved.contains(*path) && self.delivered.get(*path) == Some(&mtime(path))
        })
        .cloned()
        .collect();
    if !new_conflicts.is_empty() {
        if modal_open() {
            return false;
        }
        self.script_conflicts.extend(new_conflicts);
        self.script_pending.clear();
        script_editor.reload_open_files();
        return true;
    }
    if !self.script_conflicts.is_empty() {
        return false;
    }
    if self.script_pending.is_empty() && !dissolved {
        return false;
    }
    // reload_open_files can deferred-pop a dialog; never over an open modal.
    if modal_open() {
        return false;
    }
    self.script_pending.clear();
    script_editor.reload_open_files();
    true
}

fn present_scene_dialog(&mut self) {
    if self.scene_dialog_pending.is_empty() && !self.project_pending {
        return;
    }
    if modal_open() {
        return;
    }
    let editor = EditorInterface::singleton();
    let open = globalized(&editor.get_open_scenes());
    let unsaved = globalized(&editor.get_unsaved_scenes());
    let mut fresh_info = std::mem::take(&mut self.project_pending);
    for path in std::mem::take(&mut self.scene_dialog_pending) {
        if open.contains(&path)
            && unsaved.contains(&path)
            && self.delivered.get(&path) == Some(&mtime(&path))
        {
            self.scene_conflicts.insert(path);
            fresh_info = true;
        } else if open.contains(&path)
            && path.exists()
            && self.delivered.get(&path) == Some(&mtime(&path))
            && self.scene_saves.get(&path) != Some(&mtime(&path))
        {
            // Dissolved while waiting for the slot: clean but stale.
            reload_scene(&path);
        }
    }
    if !fresh_info {
        return;
    }
    match editor_node() {
        Some(mut node) => node.notify(NodeNotification::APPLICATION_FOCUS_IN),
        None => godot_warn!(
            "[godotty] EditorNode not found; refocus the editor to resolve external changes"
        ),
    }
}

fn flush_shaders(&mut self) {
    if self.shader_pending.is_empty() {
        return;
    }
    self.shader_pending.clear();
    if !autoreload_enabled() {
        // Their editors would prompt for any change; that belongs to the
        // real focus-in.
        return;
    }
    let Some(base) = EditorInterface::singleton().get_base_control() else {
        return;
    };
    let editors = base
        .find_children_ex("*")
        .type_("TextShaderEditor")
        .owned(false)
        .done();
    for mut editor in editors.iter_shared() {
        if !shader_buffer_unsaved(&editor) {
            editor.notify(NodeNotification::APPLICATION_FOCUS_IN);
        }
    }
}

fn editor_node() -> Option<Gd<Node>> {
    let mut node: Gd<Node> = EditorInterface::singleton().get_base_control()?.upcast();
    loop {
        if node.get_class() == "EditorNode" {
            return Some(node);
        }
        node = node.get_parent()?;
    }
}

fn shader_buffer_unsaved(editor: &Gd<Node>) -> bool {
    let edits = editor
        .find_children_ex("*")
        .type_("CodeEdit")
        .owned(false)
        .done();
    let Some(edit) = edits.iter_shared().next() else {
        return true;
    };
    let Ok(edit) = edit.try_cast::<TextEdit>() else {
        return true;
    };
    edit.get_version() != edit.get_saved_version()
}

fn focus_owner() -> Option<Gd<Control>> {
    EditorInterface::singleton()
        .get_base_control()?
        .get_viewport()?
        .gui_get_focus_owner()
}

fn restore_focus(before: Option<Gd<Control>>) {
    let Some(mut before) = before else { return };
    if !before.is_instance_valid() {
        return;
    }
    let Some(current) = focus_owner() else { return };
    if current != before {
        before.grab_focus();
    }
}

fn reload_scene(path: &Path) {
    if let Some(local) = localize(path) {
        EditorInterface::singleton().reload_scene_from_path(&local);
    }
}

fn extension_map() -> HashMap<PathBuf, GString> {
    let mut map = HashMap::new();
    for extension in GDExtensionManager::singleton().get_loaded_extensions().as_slice() {
        let mut config = ConfigFile::new_gd();
        if config.load(extension) != godot::global::Error::OK {
            continue;
        }
        if !config.has_section("libraries") {
            continue;
        }
        for key in config.get_section_keys("libraries").as_slice() {
            let library = config.get_value("libraries", key).to_string();
            map.insert(globalize(&library), extension.clone());
        }
    }
    map
}

fn globalize(path: &str) -> PathBuf {
    PathBuf::from(
        ProjectSettings::singleton()
            .globalize_path(path)
            .to_string(),
    )
}

fn localize(path: &Path) -> Option<GString> {
    Some(ProjectSettings::singleton().localize_path(path.to_str()?))
}

fn project_root() -> Option<PathBuf> {
    let root = ProjectSettings::singleton()
        .globalize_path("res://")
        .to_string();
    (!root.is_empty()).then(|| PathBuf::from(root))
}

#[derive(GodotClass)]
#[class(tool, base = Control)]
pub struct Terminal {
    base: Base<Control>,
    #[export]
    pub(crate) font_size: i32,
    #[export]
    ligatures: bool,
    #[export]
    scrollback: u32,
    /// Command to run; empty means $SHELL.
    #[export]
    pub(crate) shell: GString,
    /// Where the shell starts; empty means project root, then $HOME.
    #[export]
    working_directory: GString,
    /// Spawn as a login shell so profiles rebuild the environment.
    /// Passes -l, so turn this off when shell is not a shell.
    #[export]
    login_shell: bool,
    /// Auto follows the editor theme (or the OS dark mode in games).
    #[export(enum = (Auto, Dark, Light))]
    color_scheme: i32,
    /// Run inside the editor too, like a tool script. Ignored in games.
    /// Off keeps terminals in edited scenes inert.
    #[export]
    pub(crate) run_in_editor: bool,
    state: Option<State>,
}

#[godot_api]
impl Terminal {
    #[signal]
    fn title_changed(title: GString);
    #[signal]
    fn bell();
    #[signal]
    fn exited(code: i64);

    #[func]
    fn is_exited(&self) -> bool {
        self.state.as_ref().is_none_or(|st| st.exited)
    }

    #[func]
    fn on_editor_settings_changed(&mut self) {
        self.refresh_theme();
        self.refresh_ligatures();
    }

    fn refresh_theme(&mut self) {
        if !self.in_editor() {
            return;
        }
        let pref = self.scheme_pref();
        let Some(st) = self.state.as_mut() else {
            return;
        };
        let theme = theme::resolve(true, pref);
        if theme == st.theme {
            return;
        }
        if let Err(e) = st.apply_theme(theme) {
            godot_error!("[godotty] theme change failed: {e}");
        }
    }

    fn refresh_ligatures(&mut self) {
        if !self.in_editor() {
            return;
        }
        let pref = self.ligatures_pref();
        if let Some(st) = self.state.as_mut()
            && st.ligatures != pref
        {
            st.ligatures = pref;
            st.needs_paint = true;
        }
    }
}

fn in_editor(&self) -> bool {
    self.run_in_editor && Engine::singleton().is_editor_hint()
}

fn scheme_pref(&self) -> i32 {
    if !self.in_editor() {
        return self.color_scheme;
    }
    EditorInterface::singleton()
        .get_editor_settings()
        .map(|s| s.get_setting(plugin::COLOR_SCHEME_SETTING))
        .and_then(|v| v.try_to::<i64>().ok())
        .map(|v| v as i32)
        .unwrap_or(theme::SCHEME_AUTO)
}

fn ligatures_pref(&self) -> bool {
    if !self.in_editor() {
        return self.ligatures;
    }
    EditorInterface::singleton()
        .get_editor_settings()
        .map(|s| s.get_setting(plugin::LIGATURES_SETTING))
        .and_then(|v| v.try_to::<bool>().ok())
        .unwrap_or(true)
}

fn handle_key(&mut self, key: &Gd<InputEventKey>) {
    // Left unconsumed so the editor's shortcut handling sees it.
    if is_editor_passthrough(key) {
        return;
    }

    if key.is_pressed() {
        if is_chord(key, GKey::C) {
            if let Some(st) = self.state.as_ref() {
                st.copy_selection(false);
            }
            self.base_mut().accept_event();
            return;
        }
        if is_chord(key, GKey::V) {
            if let Some(st) = self.state.as_mut().filter(|st| !st.exited) {
                st.paste_clipboard();
                st.needs_paint = true;
            }
            self.base_mut().accept_event();
            return;
        }

        // Per-terminal zoom through the rebindable editor shortcuts.
        if self.in_editor() {
            let ev = key.clone().upcast::<InputEvent>();
            let delta = if plugin::shortcut_matches(plugin::INCREASE_FONT_SHORTCUT, &ev) {
                Some(1)
            } else if plugin::shortcut_matches(plugin::DECREASE_FONT_SHORTCUT, &ev) {
                Some(-1)
            } else if plugin::shortcut_matches(plugin::RESET_FONT_SHORTCUT, &ev) {
                Some(0)
            } else {
                None
            };
            if let Some(delta) = delta {
                if let Some(st) = self.state.as_mut() {
                    st.adjust_font_pt(delta);
                }
                self.base_mut().accept_event();
                return;
            }
        }

        // Scrollback keys. Primary screen only, so TUIs keep them.
        let shift_only = key.is_shift_pressed()
            && !key.is_ctrl_pressed()
            && !key.is_alt_pressed()
            && !key.is_meta_pressed();
        if shift_only && let Some(st) = self.state.as_mut() {
            let scroll = match key.get_keycode() {
                GKey::PAGEUP => Some(ScrollViewport::Delta(-(st.geo.rows as isize))),
                GKey::PAGEDOWN => Some(ScrollViewport::Delta(st.geo.rows as isize)),
                GKey::HOME => Some(ScrollViewport::Top),
                GKey::END => Some(ScrollViewport::Bottom),
                _ => None,
            };
            if let Some(scroll) = scroll
                && st.vt.active_screen().ok() != Some(Screen::Alternate)
            {
                st.vt.scroll_viewport(scroll);
                st.needs_paint = true;
                self.base_mut().accept_event();
                return;
            }
        }
    }

    if let Some(st) = self.state.as_mut().filter(|st| !st.exited) {
        let bytes = st.input.encode_key(&st.vt, key);
        if !bytes.is_empty() {
            st.writer.write(bytes);
            let _ = st.vt.set_selection(None);
            st.vt.scroll_viewport(ScrollViewport::Bottom);
            st.needs_paint = true;
        }
        self.base_mut().accept_event();
    }
}

fn handle_mouse_button(&mut self, btn: &Gd<InputEventMouseButton>) {
    let index = btn.get_button_index();
    let pressed = btn.is_pressed();
    if index == MouseButton::LEFT && pressed {
        self.base_mut().grab_focus();
    }
    let pos = btn.get_position();
    let mods = event_mods(btn.clone().upcast());

    let wheel_up = index == MouseButton::WHEEL_UP;
    if wheel_up || index == MouseButton::WHEEL_DOWN {
        if pressed {
            // Godot reports partial wheel ticks via the event factor.
            let ticks = f64::from(btn.get_factor());
            self.scroll(if wheel_up { ticks } else { -ticks }, false, mods, pos);
            self.base_mut().accept_event();
        }
        return;
    }

    let mut handled = false;
    if let Some(st) = self.state.as_mut() {
        let geo = st.geo.mouse();
        // Shift bypasses tracking so text stays selectable in apps.
        // Exited terminals keep selection and scrollback, nothing else.
        let tracking = !st.exited
            && st.vt.is_mouse_tracking().unwrap_or(false)
            && !mods.contains(VtMods::SHIFT);

        if index == MouseButton::LEFT {
            // A selection in progress always completes on release, even
            // if Shift was let go first (which would re-enable tracking).
            if !pressed && st.selecting {
                st.input.selection_release(&st.vt, pos.x, pos.y, geo);
                st.selecting = false;
                st.copy_selection(true);
            } else if tracking {
                let bytes = st.input.encode_button(
                    &st.vt,
                    mouse::Button::Left,
                    pressed,
                    mods,
                    (pos.x, pos.y),
                    geo,
                );
                st.writer.write(bytes);
            } else if pressed {
                st.input.selection_press(&st.vt, pos.x, pos.y, geo);
                st.selecting = true;
            }
            handled = true;
        } else if index == MouseButton::MIDDLE && tracking {
            let bytes = st.input.encode_button(
                &st.vt,
                mouse::Button::Middle,
                pressed,
                mods,
                (pos.x, pos.y),
                geo,
            );
            st.writer.write(bytes);
            handled = true;
        } else if index == MouseButton::RIGHT && tracking {
            let bytes = st.input.encode_button(
                &st.vt,
                mouse::Button::Right,
                pressed,
                mods,
                (pos.x, pos.y),
                geo,
            );
            st.writer.write(bytes);
            handled = true;
        }
        if handled {
            st.needs_paint = true;
        }
    }
    if handled {
        self.base_mut().accept_event();
    }
}

fn handle_pan(&mut self, pan: &Gd<InputEventPanGesture>) {
    let mods = event_mods(pan.clone().upcast());
    let yoff = f64::from(-pan.get_delta().y) * PAN_TO_PIXELS;
    self.scroll(yoff, true, mods, pan.get_position());
    self.base_mut().accept_event();
}

fn handle_mouse_motion(&mut self, motion: &Gd<InputEventMouseMotion>) {
    let pos = motion.get_position();
    let mods = event_mods(motion.clone().upcast());
    let mask = motion.get_button_mask().ord();

    if let Some(st) = self.state.as_mut() {
        let geo = st.geo.mouse();
        if st.selecting {
            st.input
                .selection_drag(&st.vt, pos.x, pos.y, mods.contains(VtMods::ALT), geo);
            st.needs_paint = true;
        } else if !st.exited && st.vt.is_mouse_tracking().unwrap_or(false) {
            let held = if mask & MouseButtonMask::LEFT.ord() != 0 {
                Some(mouse::Button::Left)
            } else if mask & MouseButtonMask::RIGHT.ord() != 0 {
                Some(mouse::Button::Right)
            } else if mask & MouseButtonMask::MIDDLE.ord() != 0 {
                Some(mouse::Button::Middle)
            } else {
                None
            };
            let bytes = st
                .input
                .encode_motion(&st.vt, held, mods, (pos.x, pos.y), geo);
            st.writer.write(bytes);
        }
    }
}

fn resolve_cwd(configured: &str) -> PathBuf {
    let globalize =
        |p: &str| PathBuf::from(ProjectSettings::singleton().globalize_path(p).to_string());
    if !configured.is_empty() {
        let path = globalize(configured);
        if path.is_dir() {
            return path;
        }
        godot_warn!("[godotty] working_directory {configured} does not exist, using default");
    }
    let project = globalize("res://");
    if project.is_dir() {
        return project;
    }
    std::env::var_os("HOME")
        .or_else(|| std::env::var_os("USERPROFILE"))
        .map(PathBuf::from)
        .or_else(|| std::env::current_dir().ok())
        .unwrap_or_else(|| PathBuf::from("."))
}

impl Drop for State {
    fn drop(&mut self) {
        let mut rs = RenderingServer::singleton();
        rs.free_rid(self.canvas_fg);
        rs.free_rid(self.canvas_bg);
    }
}

fn copy_selection(&self, primary: bool) {
    let Ok(Some(bytes)) = self
        .vt
        .format_selection_alloc(None, FormatOptions::new().with_trim(true))
    else {
        return;
    };
    let Ok(text) = std::str::from_utf8(&bytes) else {
        return;
    };
    if text.is_empty() {
        return;
    }
    let mut ds = DisplayServer::singleton();
    if primary {
        // Godot warns on every call where no primary clipboard exists.
        if ds.has_feature(DisplayFeature::CLIPBOARD_PRIMARY) {
            ds.clipboard_set_primary(text);
        }
    } else {
        ds.clipboard_set(text);
    }
}

fn paste_clipboard(&mut self) {
    let text = DisplayServer::singleton().clipboard_get().to_string();
    if text.is_empty() {
        return;
    }

    let bracketed = self.vt.mode(Mode::BRACKETED_PASTE).unwrap_or(false);
    let mut data = text.into_bytes();
    let mut buf = vec![0u8; data.len() + 16];
    let written = match paste::encode(&mut data, bracketed, &mut buf) {
        Ok(n) => n,
        Err(VtError::OutOfSpace { required }) => {
            buf.resize(required, 0);
            match paste::encode(&mut data, bracketed, &mut buf) {
                Ok(n) => n,
                Err(_) => return,
            }
        }
        Err(_) => return,
    };
    self.writer.write(&buf[..written]);
    let _ = self.vt.set_selection(None);
    self.vt.scroll_viewport(ScrollViewport::Bottom);
}

fn is_chord(key: &Gd<InputEventKey>, which: GKey) -> bool {
    if key.get_keycode() != which {
        return false;
    }
    if cfg!(target_os = "macos") {
        key.is_meta_pressed()
    } else {
        key.is_ctrl_pressed() && key.is_shift_pressed()
    }
}

fn is_editor_passthrough(key: &Gd<InputEventKey>) -> bool {
    if !(key.is_ctrl_pressed() || key.is_alt_pressed() || key.is_meta_pressed()) {
        return false;
    }
    if !Engine::singleton().is_editor_hint() {
        return false;
    }
    let Some(settings) = EditorInterface::singleton().get_editor_settings() else {
        return false;
    };
    // The toggle shortcut is always passed through, no separate listing.
    if plugin::shortcut_matches(plugin::TOGGLE_SHORTCUT, &key.clone().upcast::<InputEvent>()) {
        return true;
    }
    let chords = settings
        .get_setting(plugin::PASSTHROUGH_SETTING)
        .try_to::<GString>()
        .unwrap_or_default();
    let combo = key.get_keycode_with_modifiers();
    let os = Os::singleton();
    chords
        .to_string()
        .split(',')
        .map(str::trim)
        .filter(|chord| !chord.is_empty())
        .any(|chord| os.find_keycode_from_string(chord) == combo)
}

pub fn resolve(run_in_editor: bool, pref: i32) -> Theme {
    if run_in_editor
        && let Some(control) = EditorInterface::singleton().get_base_control()
        && let Some(theme) = editor_theme(&control, pref)
    {
        return theme;
    }
    let dark = match pref {
        SCHEME_DARK => true,
        SCHEME_LIGHT => false,
        _ => {
            let ds = DisplayServer::singleton();
            !ds.is_dark_mode_supported() || ds.is_dark_mode()
        }
    };
    let (bg, fg) = neutral_surface(dark);
    generate(bg, fg, None, HUES)
}

fn editor_theme(control: &Gd<Control>, pref: i32) -> Option<Theme> {
    let color = |name: &str| -> Option<RgbColor> {
        control
            .has_theme_color_ex(name)
            .theme_type("Editor")
            .done()
            .then(|| {
                let c = control.get_theme_color_ex(name).theme_type("Editor").done();
                RgbColor {
                    r: (c.r.clamp(0.0, 1.0) * 255.0).round() as u8,
                    g: (c.g.clamp(0.0, 1.0) * 255.0).round() as u8,
                    b: (c.b.clamp(0.0, 1.0) * 255.0).round() as u8,
                }
            })
    };
    let mut bg = darken(color("base_color")?, RECESS);
    let mut fg = color("font_color")?;
    let accent = color("accent_color")?;

    // A forced scheme opposite the editor can't blend; take a neutral surface.
    let editor_dark = oklab_of(bg).l < 0.5;
    match pref {
        SCHEME_DARK if !editor_dark => (bg, fg) = neutral_surface(true),
        SCHEME_LIGHT if editor_dark => (bg, fg) = neutral_surface(false),
        _ => {}
    }

    let mut hues = HUES;
    for (slot, name) in [
        (0, "error_color"),
        (1, "success_color"),
        (2, "warning_color"),
    ] {
        if let Some(c) = color(name) {
            let lab = oklab_of(c);
            if (lab.a * lab.a + lab.b * lab.b).sqrt() > 0.03 {
                hues[slot] = lab.b.atan2(lab.a).to_degrees();
            }
        }
    }
    Some(generate(bg, fg, Some(accent), hues))
}

fn get_importer_and_params_from_import_file_content(
    &self,
    import_file_content: &str,
) -> (GString, VarDictionary) {
    let mut import_file = ConfigFile::new_gd();
    import_file.parse(import_file_content);
    let importer = import_file.get_value("remap", "importer");
    let keys: PackedStringArray = import_file.get_section_keys("params");
    let mut params: VarDictionary = vdict! {};
    for key in keys.as_slice().iter() {
        params.set(&key.to_variant(), &import_file.get_value("params", key));
    }
    (importer.to::<GString>(), params)
}

fn set_resource_path(resource: &mut Gd<Resource>, path: GString, cache_mode: CacheMode) {
    match cache_mode {
        CacheMode::IGNORE | CacheMode::IGNORE_DEEP => {
            resource.set_path_cache(&path);
        }
        CacheMode::REPLACE | CacheMode::REPLACE_DEEP => {
            resource.take_over_path(&path);
        }
        CacheMode::REUSE => {
            resource.set_path(&path);
        }
        _ => {
            // we should never get here
            tracing::error!("Invalid cache mode: {}", cache_mode.ord());
        }
    }
}

fn get_content_as_textfile_resource(content: &FileContent) -> Option<Gd<Resource>> {
    // For some reason, TextFile isn't bound in Rust, so we instantiate it manually.
    if !matches!(content, FileContent::String(_) | FileContent::Scene(_)) {
        tracing::error!("Do not try to save a non-text or scene file as a TextFile");
        return None;
    }
    let resource = ClassDb::singleton().instantiate(&StringName::from("TextFile"));
    if resource.is_nil() {
        tracing::error!("Error instantiating TextFile");
        return None;
    }
    let mut resource = resource.try_to::<Gd<Resource>>().unwrap();
    match content {
        FileContent::String(text) => {
            resource.call("set_text", &[text.to_variant()]);
        }
        FileContent::Scene(scene) => {
            resource.call("set_text", &[scene.serialize().to_variant()]);
        }
        _ => return None,
    }
    Some(resource)
}

#[derive(GodotClass)]
#[class(base = ResourceFormatSaver, tool)]
pub struct BackstitchResourceFormatSaver {
    #[base]
    base: Base<ResourceFormatSaver>,
}

#[godot_api]
impl IResourceFormatSaver for BackstitchResourceFormatSaver {
    fn init(base: Base<ResourceFormatSaver>) -> Self {
        Self { base }
    }

    fn save(&mut self, _resource: Option<Gd<Resource>>, _path: GString, _flags: u32) -> Error {
        // TODO: Decide if and how we want to save resources loaded from backstitch history; right now this is just here to prevent saving loaded history resources
        Error::ERR_LOCKED // indicate read-only
    }

    fn set_uid(&mut self, _path: GString, _uid: i64) -> Error {
        // TODO: see above
        Error::ERR_LOCKED
    }

    fn recognize(&self, _resource: Option<Gd<Resource>>) -> bool {
        if let Some(resource) = _resource {
            return recognize_path(resource.get_path());
        }
        false
    }

