pub fn free_texture(&mut self, id: egui::TextureId) {
    godot_print!("Freeing Texture: {:?}", id);

    // NOTE: Textures are all ref-counted.
    if self.textures.remove(&id).is_none() {
        // Texture could be uninitialized due to error.
        godot_warn!("Texture not found! {:?}", id);
    };
}

fn get(&self, id: &egui::TextureId) -> Option<Gd<ImageTexture>> {
    self.textures.get(id).map(|x| x.gd_tex.clone())
}

#[derive(GodotClass)]
#[class(base=Control, tool, init, internal, rename=INTERNAL__GodotEguiViewportBridge)]
pub(crate) struct EguiViewportBridge {
    base: Base<Control>,

    /// Viewport ID of self.
    viewport_id: Option<egui::ViewportId>,

    /// Any GUI event will be forwarded to this.
    fwd_event: Option<Box<dyn Fn(egui::Event)>>,

    /// EGUI context that this viewport is associated with.
    context: Option<egui::Context>,

    /// Rendered primitives: one canvas item per clipped primitive.
    canvas_items: Vec<Rid>,

    /// Materials for shader-based clip rect, parallel to canvas_items.
    clip_materials: Vec<Rid>,

    /// Shared clip rect shader (lazily created).
    clip_shader: Option<Rid>,

    /// Cached ui scale
    #[init(val = 1.0)]
    ui_scale_cache: f32,
}

fn mark_input_handled(&mut self) {
    if let Some(mut vp) = self.base().get_viewport() {
        vp.set_input_as_handled();
    }
}

pub fn draw(
    &mut self,
    textures: &TextureLibrary,
    shapes: Vec<egui::epaint::ClippedPrimitive>,
    scale: f32,
) {
    let mut gd_rs = RenderingServer::singleton();
    self.ui_scale_cache = scale;

    // Lazily create the clip rect shader.
    let clip_shader = *self.clip_shader.get_or_insert_with(|| {
        let shader = gd_rs.shader_create();
        gd_rs.shader_set_code(shader, &GString::from(CLIP_SHADER_CODE));
        shader
    });

    // Performs bookkeeping - Make canvas_items/materials be same length as
    // input shapes.
    {
        let rid_self_canvas = self.base().get_canvas_item();

        // Create missing items.
        for index in 0..shapes.len() {
            if index >= self.canvas_items.len() {
                let rid = gd_rs.canvas_item_create();
                gd_rs.canvas_item_set_parent(rid, rid_self_canvas);
                gd_rs.canvas_item_set_draw_index(rid, index as i32);
                self.canvas_items.push(rid);

                let mat = gd_rs.material_create();
                gd_rs.material_set_shader(mat, clip_shader);
                gd_rs.canvas_item_set_material(rid, mat);
                self.clip_materials.push(mat);
            } else {
                gd_rs.canvas_item_clear(self.canvas_items[index]);
            }
        }

        // Dispose unused items.
        for index in (shapes.len()..self.canvas_items.len()).rev() {
            gd_rs.free_rid(self.canvas_items[index]);
            gd_rs.free_rid(self.clip_materials[index]);
        }
        self.canvas_items.truncate(shapes.len());
        self.clip_materials.truncate(shapes.len());
    }

    // Render mesh content

    for (index, primitive) in shapes.into_iter().enumerate() {
        let rid_item = self.canvas_items[index];
        let mat = self.clip_materials[index];

        let egui::epaint::Primitive::Mesh(mesh) = primitive.primitive else {
            godot_error!("unsupported primitive");
            continue;
        };

        let Some(texture) = textures.get(&mesh.texture_id) else {
            godot_warn!("Missing Texture: {:?}", mesh.texture_id);
            return;
        };

        let mut verts = PackedVector2Array::new();
        let mut uvs = PackedVector2Array::new();
        let mut colors = PackedColorArray::new();
        let mut indices = PackedInt32Array::new();

        verts.resize(mesh.vertices.len());
        colors.resize(mesh.vertices.len());
        uvs.resize(mesh.vertices.len());

        indices.resize(mesh.indices.len());

        for (src, d_vert, d_uv, d_color) in itertools::multizip((
            mesh.vertices.as_slice(),
            verts.as_mut_slice(),
            uvs.as_mut_slice(),
            colors.as_mut_slice(),
        )) {
            d_vert.x = src.pos.x * scale;
            d_vert.y = src.pos.y * scale;

            d_uv.x = src.uv.x;
            d_uv.y = src.uv.y;

            d_color.r = src.color.r() as f32 / 255.0;
            d_color.g = src.color.g() as f32 / 255.0;
            d_color.b = src.color.b() as f32 / 255.0;
            d_color.a = src.color.a() as f32 / 255.0;
        }

        for (src, dst) in multizip((mesh.indices.as_slice(), indices.as_mut_slice())) {
            *dst = *src as i32;
        }

        let mut clip = primitive.clip_rect;
        clip.min.x *= scale;
        clip.min.y *= scale;
        clip.max.x *= scale;
        clip.max.y *= scale;

        // Update clip_rect uniform on this primitive's material.
        // Rect2 maps to vec4 as (pos.x, pos.y, size.x, size.y).
        let clip_rect = Rect2::new(
            Vector2::new(clip.min.x, clip.min.y),
            Vector2::new(clip.max.x - clip.min.x, clip.max.y - clip.min.y),
        );
        gd_rs.material_set_param(mat, &StringName::from("clip_rect"), &clip_rect.to_variant());

        gd_rs
            .canvas_item_add_triangle_array_ex(rid_item, &indices, &verts, &colors)
            .texture(texture.get_rid())
            .uvs(&uvs)
            .done(

#[derive(Default, Clone)]
pub struct StyleFonts {
    pub bold: Option<Gd<Font>>,
    pub italic: Option<Gd<Font>>,
    pub bold_italic: Option<Gd<Font>>,
    /// Fuentes REALES por peso (100..900) en redonda y cursiva
    /// (VectorRichText.set_weight_fonts). Peso base del texto: los runs con
    /// weight 400 sin negrita usan la base.
    pub roman_w: std::collections::HashMap<i32, Gd<Font>>,
    pub italic_w: std::collections::HashMap<i32, Gd<Font>>,
    pub base_weight: i32,
}

fn resolve_font_variation(base_font: &Gd<Font>, sf: &StyleFonts, style: &TextStyle) -> Gd<Font> {
    let f = Self::resolve_style_font(base_font, sf, style);
    // Interletra POR RUN (efectos "interletra progresiva", formato por
    // letra): antes se guardaba en el run pero el layout la ignoraba.
    let ls = style.letter_spacing.round() as i32;
    if ls == 0 {
        return f;
    }
    let mut var_font = FontVariation::new_gd();
    var_font.set_base_font(&f);
    var_font.set_spacing(godot::classes::text_server::SpacingType::GLYPH, ls);
    var_font.upcast()
}

fn resolve_style_font(base_font: &Gd<Font>, sf: &StyleFonts, style: &TextStyle) -> Gd<Font> {
    let (bold, italic) = (style.bold, style.italic);
    // Peso por run: archivo REAL de ese peso (Inter-Medium, -Black…).
    let w = sf.effective_weight(style);
    let base_w = if sf.base_weight > 0 { sf.base_weight } else { 400 };
    if w == base_w && !italic {
        return base_font.clone();
    }
    let table = if italic { &sf.italic_w } else { &sf.roman_w };
    if let Some(f) = table.get(&w) {
        return f.clone();
    }
    if !bold && !italic {
        return base_font.clone();
    }
    // (fuente, falta_negrita, falta_cursiva)
    let (src, synth_bold, synth_italic) = match (bold, italic) {
        (true, true) => match (&sf.bold_italic, &sf.bold, &sf.italic) {
            (Some(bi), _, _) => (bi.clone(), false, false),
            (None, Some(b), _) => (b.clone(), false, true),
            (None, None, Some(i)) => (i.clone(), true, false),
            _ => (base_font.clone(), true, true),
        },
        (true, false) => match &sf.bold {
            Some(b) => (b.clone(), false, false),
            None => (base_font.clone(), true, false),
        },
        _ => match &sf.italic {
            Some(i) => (i.clone(), false, false),
            None => (base_font.clone(), false, true),
        },
    };
    if !synth_bold && !synth_italic {
        return src;
    }
    let mut var_font = FontVariation::new_gd();
    var_font.set_base_font(&src);
    if synth_bold {
        var_font.set_variation_embolden(0.35);
    }
    if synth_italic {
        var_font.set_variation_transform(godot::builtin::Transform2D::from_cols(
            Vector2::new(1.0, 0.0),
            Vector2::new(0.22, 1.0),
            Vector2::ZERO,
        ));
    }
    var_font.upcast()
}

pub fn hit_test(&self, point: Vector2) -> usize {
    if self.lines.is_empty() {
        return 0;
    }

    let base_x = if self.is_paragraph { self.frame.padding_left } else { 0.0 };
    let base_y = if self.is_paragraph { self.frame.padding_top + self.vert_offset } else { 0.0 };

    if let Some(tp) = self.paragraphs.first() {
        let tp_coords = point - Vector2::new(base_x, base_y);
        let hit = tp.hit_test(tp_coords);
        if hit >= 0 {
            return hit as usize;
        }
    }

    let tsm = TextServerManager::singleton();
    let ts = tsm.get_primary_interface();

    let mut best_line = 0;
    let mut min_dist = f32::MAX;

    for (i, line) in self.lines.iter().enumerate() {
        let r = line.rect;
        if r.contains_point(point) {
            best_line = i;
            break;
        }
        let dx = if point.x < r.position.x {
            r.position.x - point.x
        } else if point.x > r.position.x + r.size.x {
            point.x - (r.position.x + r.size.x)
        } else {
            0.0
        };
        let dy = if point.y < r.position.y {
            r.position.y - point.y
        } else if point.y > r.position.y + r.size.y {
            point.y - (r.position.y + r.size.y)
        } else {
            0.0
        };
        let dist = dx * dx + dy * dy;
        if dist < min_dist {
            min_dist = dist;
            best_line = i;
        }
    }

    let line = &self.lines[best_line];
    if let Some(ref ts) = ts {
        let local_x = point.x - line.rect.position.x;
        let hit_grapheme = ts.shaped_text_hit_test_grapheme(line.line_rid, local_x as f64);
        if hit_grapheme >= 0 {
            return (hit_grapheme as usize).clamp(line.char_start, line.char_end);
        }
    }

    if point.x <= line.rect.position.x {
        return line.char_start;
    }
    if point.x >= line.rect.position.x + line.rect.size.x {
        return line.char_end;
    }
    let ratio = ((point.x - line.rect.position.x) / line.rect.size.x.max(1.0)).clamp(0.0, 1.0);
    let chars_in_line = line.char_end.saturating_sub(line.char_start);
    let offset = (ratio * chars_in_line as f32).round() as usize;
    line.char_start + offset
}

pub fn caret_rect(&self, char_idx: usize) -> Rect2 {
    if self.lines.is_empty() {
        let base_x = if self.is_paragraph { self.frame.padding_left } else { 0.0 };
        let base_y = if self.is_paragraph { self.frame.padding_top } else { 2.0 };
        return Rect2::new(Vector2::new(base_x, base_y), Vector2::new(2.0, 24.0));
    }

    let tsm = TextServerManager::singleton();
    let ts = tsm.get_primary_interface();

    for line in &self.lines {
        if char_idx >= line.char_start && char_idx <= line.char_end {
            let h = (line.ascent + line.descent).max(line.rect.size.y).max(16.0);
            let y = line.rect.position.y;

            if char_idx == line.char_start {
                return Rect2::new(Vector2::new(line.rect.position.x, y), Vector2::new(2.0, h));
            }

            if let Some(ref ts) = ts {
                let sel = ts.shaped_text_get_selection(
                    line.line_rid,
                    line.char_start as i64,
                    char_idx as i64,
                );
                if !sel.is_empty() {
                    if let Some(last_span) = sel.as_slice().last() {
                        let x = line.rect.position.x + last_span.y;
                        return Rect2::new(Vector2::new(x, y), Vector2::new(2.0, h));
                    }
                }
            }

            let ratio = if line.char_end > line.char_start {
                ((char_idx - line.char_start) as f32) / ((line.char_end - line.char_start) as f32)
            } else {
                0.0
            };
            let x = line.rect.position.x + (ratio * line.rect.size.x);
            return Rect2::new(Vector2::new(x, y), Vector2::new(2.0, h));
        }
    }

    if let Some(last) = self.lines.last() {
        let x = last.rect.position.x + last.rect.size.x;
        let y = last.rect.position.y;
        let h = (last.ascent + last.descent).max(last.rect.size.y).max(16.0);
        return Rect2::new(Vector2::new(x, y), Vector2::new(2.0, h));
    }

    Rect2::new(Vector2::ZERO, Vector2::new(2.0, 24.0))
}

pub fn selection_rects(&self, start: usize, end: usize) -> Vec<Rect2> {
    let mut rects = Vec::new();
    let s = start.min(end);
    let e = start.max(end);
    if s == e || self.lines.is_empty() {
        return rects;
    }

    let tsm = TextServerManager::singleton();
    let ts = tsm.get_primary_interface();

    for line in &self.lines {
        if line.char_end <= s || line.char_start >= e {
            continue;
        }
        let overlap_start = line.char_start.max(s);
        let overlap_end = line.char_end.min(e);
        let y = line.rect.position.y;
        let h = (line.ascent + line.descent).max(line.rect.size.y);

        if let Some(ref ts) = ts {
            let sel = ts.shaped_text_get_selection(
                line.line_rid,
                overlap_start as i64,
                overlap_end as i64,
            );
            if !sel.is_empty() {
                for span in sel.as_slice() {
                    let x = line.rect.position.x + span.x.min(span.y);
                    let w = (span.y - span.x).abs().max(2.0);
                    rects.push(Rect2::new(Vector2::new(x, y), Vector2::new(w, h)));
                }
                continue;
            }
        }

        let chars_in_line = (line.char_end - line.char_start).max(1) as f32;
        let x1_ratio = ((overlap_start - line.char_start) as f32) / chars_in_line;
        let x2_ratio = ((overlap_end - line.char_start) as f32) / chars_in_line;

        let x = line.rect.position.x + (x1_ratio * line.rect.size.x);
        let w = ((x2_ratio - x1_ratio) * line.rect.size.x).max(2.0);

        rects.push(Rect2::new(Vector2::new(x, y), Vector2::new(w, h)));
    }

    rects
}

#[derive(GodotClass)]
#[class(base=Control)]
pub struct VectorRichText {
    base: Base<Control>,
    doc: TextDocument,
    layout: LayoutEngine,
    editor: EditorState,
    default_font: Option<Gd<Font>>,
    /// set_font() explícito (FontCore): el tema ya no lo pisa en ready/recalculate.
    explicit_font: bool,
    /// Fuentes REALES por estilo: [negrita, cursiva, negrita+cursiva].
    /// Sin ellas se sintetiza (emboldening/cizalla), que con MSDF deja
    /// muescas blancas en las uniones de las letras.
    style_fonts: StyleFonts,
    accent_color: Color,
    selection_color: Color,
    last_click_msec: u64,
    last_click_pos: Vector2,
    click_count: u32,
    /// Sobremuestreo del raster de los glifos (≈ zoom de pantalla). Sin
    /// MSDF, cada letra se rasteriza a tamaño × oversampling: nítida con
    /// zoom. 0 = el del viewport. Lo fija WorldTextLabel al cambiar el zoom.
    oversampling: f32,
    /// Px de pantalla por letra a partir de los que se dibuja con contornos
    /// en vez de raster (0 = siempre raster). Lo fija WorldTextLabel.
    raster_cap: f32,
    /// Rect local con el que se recortaron los glifos vectoriales en el
    /// último draw; si la vista sale de él (paneo) hay que redibujar.
    vector_cull: Option<Rect2>,
}

pub fn start_editing_internal(&mut self) {
    if !self.editor.is_editing {
        let total = self.doc.char_count();
        let cur = self.editor.caret_index.min(total);
        self.editor.start_editing(cur, total);
        self.base_mut().set_mouse_filter(MouseFilter::STOP);
        if self.base().is_inside_tree() {
            self.base_mut().grab_focus();
        }
        self.base_mut().emit_signal("editing_started", &[]);
        self.notify_selection_changed();
        self.base_mut().queue_redraw();
    }
}

pub fn stop_editing_internal(&mut self) {
    if self.editor.is_editing {
        self.editor.stop_editing();
        self.base_mut().set_mouse_filter(MouseFilter::PASS);
        if self.base().is_inside_tree() {
            self.base_mut().release_focus();
        }
        self.base_mut().emit_signal("editing_finished", &[]);
        self.base_mut().queue_redraw();
    }
}

pub fn recalculate(&mut self) {
    // Antes el tema PISABA la fuente de set_font() en cada recálculo: la
    // familia/peso elegidos en FontCore nunca llegaban al editor nativo.
    if !self.explicit_font {
        if let Some(tf) = self.base().get_theme_font("font") {
            self.default_font = Some(tf);
        }
    }
    let old_overset = self.layout.is_overset;
    self.layout.reflow(&self.doc, self.default_font.clone(), &self.style_fonts);

    let min_sz = self.layout.content_size;
    self.base_mut().set_custom_minimum_size(min_sz);
    if !self.layout.is_paragraph {
        self.base_mut().set_size(min_sz);
    }

    if old_overset != self.layout.is_overset {
        let ov = self.layout.is_overset;
        self.base_mut().emit_signal("overset_changed", &[ov.to_variant()]);
    }
}

pub fn notify_selection_changed(&mut self) {
    let (s, e) = self.editor.selected_range().unwrap_or((self.editor.caret_index, self.editor.caret_index));
    let caret = self.editor.caret_index as i64;
    let mut base = self.base_mut();
    base.emit_signal("selection_changed", &[(s as i64).to_variant(), (e as i64).to_variant()]);
    base.emit_signal("caret_changed", &[caret.to_variant()]);
}

#[allow(clippy::too_many_arguments)]
pub fn draw_glyph(
    ts: &Gd<TextServer>,
    font_rid: Rid,
    index: i64,
    font_size: i64,
    stroke_px: f32,
    screen_px: f32,
    gp: Vector2,
    color: Color,
    canvas_rid: Rid,
    cull: Option<Rect2>,
) {
    let lod = lod_for(screen_px);
    let s = font_size.max(1) as f32 / REF_SIZE as f32;
    // Grosor en unidades REF, cuantizado a 1/8 px para la clave de caché.
    let stroke_q = (stroke_px / s * 8.0).round().max(0.0) as u32;
    let key = (font_rid.to_u64(), index, lod, stroke_q);

    CACHE.with(|c| {
        let mut cache = c.borrow_mut();
        if !cache.contains_key(&key) {
            if cache.len() >= MAX_CACHE {
                cache.clear();
            }
            let tol = SCREEN_TOLERANCE * REF_SIZE as f32 / lod_px(lod);
            let mesh = build_mesh(ts, font_rid, index, tol, stroke_q as f32 / 8.0);
            cache.insert(key, mesh);
        }
        let Some(mesh) = cache.get(&key).and_then(|m| m.as_ref()) else {
            return;
        };

        let world = Rect2::new(mesh.bounds.position * s + gp, mesh.bounds.size * s);
        if let Some(c) = cull {
            if !c.intersects(world) {
                return;
            }
        }

        let mut pts = PackedVector2Array::new();
        pts.resize(mesh.verts.len());
        {
            let sl = pts.as_mut_slice();
            for (o, v) in sl.iter_mut().zip(&mesh.verts) {
                *o = *v * s + gp;
            }
        }
        let cols = PackedColorArray::from(&[color][..]);
        let mut rs = RenderingServer::singleton();
        rs.canvas_item_add_triangle_array(canvas_rid, &PackedInt32Array::from(mesh.indices.as_slice()), &pts, &cols);

        // Borde antialiasado de ~1 px de pantalla (el relleno de triángulos no
        // tiene antialias y a este tamaño se verían escalones).
        if !mesh.edges.is_empty() {
            let mut lines = PackedVector2Array::new();
            lines.resize(mesh.edges.len());
            {
                let sl = lines.as_mut_slice();
                for (o, &i) in sl.iter_mut().zip(&mesh.edges) {
                    *o = pts.as_slice()[i as usize];
                }
            }
            let px_local = font_size.max(1) as f32 / screen_px.max(1.0);
            rs.canvas_item_add_multiline_ex(canvas_rid, &lines, &cols)
                .width(px_local)
                .antialiased(true)
                .done();
        }
    });
}

fn build_mesh(ts: &Gd<TextServer>, font_rid: Rid, index: i64, tol: f32, stroke_ref: f32) -> Option<GlyphMesh> {
    let data = ts.font_get_glyph_contours(font_rid, REF_SIZE, index);
    let points: PackedVector3Array = data.get("points")?.try_to().ok()?;
    let contours: PackedInt32Array = data.get("contours")?.try_to().ok()?;
    if points.is_empty() || contours.is_empty() {
        return None;
    }
    let path = contours_to_path(points.as_slice(), contours.as_slice())?;

    let mut buf: VertexBuffers<Vector2, u32> = VertexBuffers::new();
    if stroke_ref > 0.0 {
        // outline_size de Godot crece hacia fuera y hacia dentro del borde:
        // línea centrada en el contorno con ese grosor a cada lado.
        let opts = StrokeOptions::tolerance(tol)
            .with_line_width(stroke_ref * 2.0)
            .with_line_join(LineJoin::Round);
        StrokeTessellator::new()
            .tessellate_path(&path, &opts, &mut BuffersBuilder::new(&mut buf, |v: StrokeVertex| {
                let p = v.position();
                Vector2::new(p.x, p.y)
            }))
            .ok()?;
    } else {
        let opts = FillOptions::tolerance(tol).with_fill_rule(FillRule::NonZero);
        FillTessellator::new()
            .tessellate_path(&path, &opts, &mut BuffersBuilder::new(&mut buf, |v: FillVertex| {
                let p = v.position();
                Vector2::new(p.x, p.y)
            }))
            .ok()?;
    }
    if buf.indices.is_empty() {
        return None;
    }

    let indices: Vec<i32> = buf.indices.iter().map(|&i| i as i32).collect();
    let edges = boundary_edges(&indices);
    let mut min = buf.vertices[0];
    let mut max = buf.vertices[0];
    for v in &buf.vertices {
        min = Vector2::new(min.x.min(v.x), min.y.min(v.y));
        max = Vector2::new(max.x.max(v.x), max.y.max(v.y));
    }
    Some(GlyphMesh { verts: buf.vertices, indices, edges, bounds: Rect2::new(min, max - min) })
}

#[derive(GodotClass)]
#[class(init, base=RefCounted)]
struct ImageVectorizer {
    base: Base<RefCounted>,
}

#[godot_api]
impl ImageVectorizer {
    /// Vectoriza `input_path` (ruta de sistema de archivos, ya resuelta con
    /// ProjectSettings.globalize_path — no acepta "res://") y escribe el SVG
    /// resultante en `output_path`. Devuelve "" en éxito, o un mensaje de
    /// error legible en caso contrario.
    ///
    /// - filter_speckle: área mínima de mancha a conservar (ruido pequeño se
    ///   descarta); 4 es el valor por defecto de vtracer.
    /// - corner_threshold: ángulo (grados) bajo el cual un vértice se trata
    ///   como esquina dura en vez de curva; 60 es el valor por defecto.
    /// - color_mode_binary: true = blanco/negro (para trazos/logos), false =
    ///   color (para fotos/ilustraciones).
    #[func]
    fn vectorize_to_file(
        &self,
        input_path: GString,
        output_path: GString,
        filter_speckle: i64,
        corner_threshold: i64,
        color_mode_binary: bool,
    ) -> GString {
        let mut config = vtracer::Config::from_preset(vtracer::Preset::Photo);
        config.filter_speckle = filter_speckle.max(0) as usize;
        config.corner_threshold = corner_threshold as i32;
        config.color_mode = if color_mode_binary {
            vtracer::ColorMode::Binary
        } else {
            vtracer::ColorMode::Color
        };

        let result = vtracer::convert_image_to_svg(
            Path::new(&input_path.to_string()),
            Path::new(&output_path.to_string()),
            config,
        );

        match result {
            Ok(()) => GString::new(),
            Err(e) => GString::from(&e),
        }
    }

    /// Igual que vectorize_to_file pero con TODAS las opciones de vtracer en
    /// un Dictionary (las que falten usan el preajuste "Photo"):
    ///   color_mode: "color" | "binary"     hierarchical: "stacked" | "cutout"
    ///   mode: "spline" (Bézier) | "polygon" | "pixel"
    ///   filter_speckle, color_precision (1-8), layer_difference (0-255),
    ///   corner_threshold (°), length_threshold (3.5-10), max_iterations,
    ///   splice_threshold (°), path_precision (decimales)
    #[func]
    fn vectorize_ex(&self, input_path: GString, output_path: GString, opts: VarDictionary) -> GString {
        match vectorize_impl(&input_path.to_string(), &output_path.to_string(), config_from(&opts)) {
            Ok(()) => GString::new(),
            Err(e) => GString::from(&e),
        }
    }
}

