impl ToString for NvimInput {
    fn to_string(&self) -> String {
        if godot::classes::ProjectSettings::singleton()
            .get_setting("vimdow/debug/log_keys")
            .try_to::<bool>()
            .unwrap_or(false)
        {
            godot::global::godot_print!("Translated input: {:?}, Mods: {:?}", self.nk, self.mods);
        }
        match self.nk {
            NvimKeycode::Printable(c) => {
                let c = c.to_string();
                if self.mods.is_empty() || self.mods == Modifiers::SHIFT {
                    c
                } else {
                    self.apply_modifiers(&c)
                }
            }
            NvimKeycode::Keycode(k) => {
                let mut k = k.as_str().to_string();
                if self.mods.is_empty() {
                    return String::new();
                }

                // keycodes default to caps for labels.
                // doing this to preserve cases because neovim differentiates between Alt events
                // with case-sensitive characters.
                if !self.mods.contains(Modifiers::SHIFT) {
                    k = k.to_lowercase();
                }
                self.apply_modifiers(&k)
            }
            NvimKeycode::Named(n) => self.apply_modifiers(n),
            NvimKeycode::Function(ref f) => self.apply_modifiers(f),
        }
    }
}

impl From<Gd<InputEventKey>> for NvimInput {
    fn from(value: Gd<InputEventKey>) -> Self {
        let kc = value.get_keycode();
        let mut mods = Modifiers::NONE;
        if value.is_ctrl_pressed() {
            mods.insert(Modifiers::CTRL);
        }

        if value.is_alt_pressed() {
            mods.insert(Modifiers::ALT);
        }

        if value.is_meta_pressed() {
            mods.insert(Modifiers::META);
        }

        if value.is_shift_pressed() {
            mods.insert(Modifiers::SHIFT);
        }
        let nk = match kc {
            Key::ENTER => NvimKeycode::Named("CR"),
            Key::BACKSPACE => NvimKeycode::Named("BS"),
            Key::TAB => NvimKeycode::Named("Tab"),
            Key::ESCAPE => NvimKeycode::Named("Esc"),
            Key::SPACE => NvimKeycode::Named("Space"),
            Key::LEFT => NvimKeycode::Named("Left"),
            Key::RIGHT => NvimKeycode::Named("Right"),
            Key::UP => NvimKeycode::Named("Up"),
            Key::DOWN => NvimKeycode::Named("Down"),
            Key::DELETE => NvimKeycode::Named("Del"),
            _ if (Key::F1.ord()..=Key::F12.ord()).contains(&kc.ord()) => {
                NvimKeycode::Function(format!("F{}", kc.ord() - Key::F1.ord() + 1))
            }
            _ => {
                let uc = value.get_unicode();
                if uc != 0
                    && let Some(c) = char::from_u32(uc)
                {
                    if c == '<' {
                        NvimKeycode::Named("lt")
                    } else {
                        NvimKeycode::Printable(c)
                    }
                } else {
                    NvimKeycode::Keycode(kc)
                }
            }
        };

        Self { mods, nk }
    }
}

fn make_mouse_modifiers(event: Gd<InputEventMouse>) -> String {
    let mut modifiers = String::new();
    if event.is_ctrl_pressed() {
        modifiers.push('C');
    }
    if event.is_alt_pressed() {
        modifiers.push('A');
    }
    if event.is_shift_pressed() {
        modifiers.push('S');
    }
    if event.is_meta_pressed() {
        modifiers.push('M');
    }
    modifiers
}

pub fn from_input_event(
    event: Gd<InputEvent>,
    grid: i32,
    cell_size: Vector2,
) -> Option<Self> {
    if let Ok(mb) = event.clone().try_cast::<InputEventMouseButton>() {
        let pos = mb.get_position() / cell_size;
        Self::button(mb, grid, pos)
    } else if let Ok(mm) = event.clone().try_cast::<InputEventMouseMotion>() {
        let pos = mm.get_position() / cell_size;
        Self::motion(mm, grid, pos)
    } else {
        None
    }
}

fn motion(event: Gd<InputEventMouseMotion>, grid: i32, pos: Vector2) -> Option<Self> {
    let modifier = make_mouse_modifiers(event.clone().upcast());

    let button = match event.get_button_mask() {
        MouseButtonMask::LEFT => "left",
        MouseButtonMask::RIGHT => "right",
        _ => "move",
    }
    .to_string();
    let action = if event.get_button_mask().ord() != 0 {
        "drag"
    } else {
        "release" // shouldn't matter if it's moved
    }
    .to_string();

    Some(Self {
        button,
        action,
        modifier,
        grid,
        row: pos.y as i32,
        col: pos.x as i32,
    })
}

fn button(event: Gd<InputEventMouseButton>, grid: i32, pos: Vector2) -> Option<Self> {
    let modifier = make_mouse_modifiers(event.clone().upcast());
    let mut action = if event.is_pressed() {
        "press"
    } else {
        "release"
    }
    .to_string();

    let wheel_action =
        |s: &str| -> Option<String> { event.is_pressed().then_some(s.to_string()) };

    let btn_idx = event.get_button_index();
    let button = match btn_idx {
        MouseButton::LEFT => "left",
        MouseButton::RIGHT => "right",
        MouseButton::MIDDLE => "middle",
        MouseButton::XBUTTON1 => "x1",
        MouseButton::XBUTTON2 => "x2",
        MouseButton::WHEEL_UP => {
            action = wheel_action("up")?;

            "wheel"
        }
        MouseButton::WHEEL_DOWN => {
            action = wheel_action("down")?;
            "wheel"
        }
        MouseButton::WHEEL_LEFT => {
            action = wheel_action("left")?;
            "wheel"
        }
        MouseButton::WHEEL_RIGHT => {
            action = wheel_action("right")?;
            "wheel"
        }
        _ => return None,
    }
    .to_string();

    Some(Self {
        button,
        action,
        modifier,
        grid,
        row: pos.y as i32,
        col: pos.x as i32,
    })
}

pub fn check(&mut self) -> Option<Value> {
    let v = self.from.try_recv().ok()?;

    if let Value::Array(ref vec) = v
        && let [Value::Integer(msgtype), Value::Integer(msgid), ..] = vec.as_slice()
    // && let Some(1) = msgtype.as_i64()
    {
        match (msgtype.as_i64(), msgid.as_i64().map(|i| i as u32)) {
            // request from server
            (Some(0), Some(msgid)) => {
                self.pending_responses.insert(msgid);
            }

            // response from server
            (Some(1), Some(msgid)) => {
                assert!(
                    self.pending_requests.remove(&msgid),
                    "No msgid ({msgid}), exists"
                );
            }

            _ => {}
        }
    } else if !v.is_array() {
        godot_print!("Received a non-rpc value: {}", v);
    }

    Some(v)
}

pub fn is_running(&mut self) -> bool {
    match self.child.try_wait() {
        Ok(Some(status)) => {
            godot_print!("Neovim process exited with: {status}");
            false
        }
        Ok(None) => true,
        Err(e) => {
            godot_error!("Neovim process is dead: {e}");
            false
        }
    }
}

#[derive(GodotClass)]
#[class(tool, base=Node, init)]
pub struct NeovimClient {
    base: Base<Node>,
    nvim_process: Option<NeovimProcess>,
}

#[godot_api]
impl INode for NeovimClient {
    fn process(&mut self, _delta: f32) {
        let Some(np) = self.nvim_process.as_mut() else {
            return;
        };

        if let Ok(Some(e)) = np.try_wait() {
           self.signals().neovim_quit().emit(e.code().unwrap_or(-1));
            return;
        }

        let mut messages = vec![];
        while let Some(v) = np.check() {
            if let Value::Array(rpc) = v {
                messages.push(rpc);
            } else {
                godot_error!("not an array: {v:?}");
            }
        }

        for rpc in messages {
            let msgtype = rpc.get(0).and_then(|v| v.as_u64()).unwrap_or(99);
            match msgtype {
                2 => {
                    if let [Value::String(method), Value::Array(params)] = &rpc[1..3] {
                        let params = rpc_array_to_vararray(params.clone());
                        self.signals()
                            .neovim_event()
                            .emit(method.to_owned().into_str().unwrap(), &params);
                    }
                }
                1 => {
                    if let [Value::Integer(msgid), error, result] = &rpc[1..4] {
                        self.signals().neovim_response().emit(
                            msgid.as_i64().unwrap() as i32,
                            &rmpv_to_godot(error.to_owned()),
                            &rmpv_to_godot(result.to_owned()),
                        );
                    }
                }
                0 => {
                    if let [Value::Integer(msgid), Value::String(method), params] = &rpc[1..4] {
                        self.signals().neovim_request().emit(
                            msgid.as_i64().unwrap() as i32,
                            method.to_string(),
                            &rmpv_to_godot(params.to_owned()).to(),
                        );
                    }
                }
                _ => godot_error!("Got a non-existent message type: {msgtype}"),
            }
        }
    }
}

