pub fn camera_pose(actor: &Gd<Node3D>, category: &str) -> Option<(Vector3, Vector3, f32, f32)> {
    // These are the category Main cameras, not unbound per-slider aliases.
    let name = match category {
        "categories" => "AvatarCamMenu",
        "face" => "AvatarCamFaceMain",
        "nose" => "AvatarCamNoseMain",
        "eyes" => "AvatarCamEyeMain",
        "mouth" | "lips" => "AvatarCamMouthMain",
        "head" => "AvatarCamShapeMain",
        "hair" => "AvatarCamHairMain",
        "skin" => "AvatarCamSkin",
        "brow" => "AvatarCamBrow",
        "hat" => "AvatarCamHatMain",
        "clothes" => "AvatarCamCLothMenu",
        "top" => "AvatarCamTopMenu",
        "bottom" => "AvatarCamBottomsMenu",
        // SelectDriver vs AvatarSelectDriver is not yet a proven alias.
        _ => return None,
    };
    let rows: Vec<Vec<Value>> = serde_json::from_str(include_str!("avatar-cameras.json")).ok()?;
    let begin = rows
        .iter()
        .position(|row| row[0].as_str() == Some("[Cam]") && row[1].as_str() == Some(name))?;
    let block: Vec<_> = rows
        .iter()
        .skip(begin + 1)
        .take_while(|row| row[0].as_str() != Some("[EndCam]"))
        .collect();
    let anchor_offset = |key: &str| -> Option<Vector3> {
        let row = block.iter().find(|r| r[0].as_str() == Some(key))?;
        let anchor = super::source_bone_anchor(&actor.clone().upcast(), row[3].as_str()?)?;
        Some(
            anchor
                + Vector3::new(
                    -(row[5].as_f64()? as f32),
                    row[6].as_f64()? as f32,
                    row[7].as_f64()? as f32,
                ),
        )
    };
    let fov = block.iter().find(|r| r[0].as_str() == Some("CamFOV"))?[2].as_f64()? as f32;
    let roll = -(block.iter().find(|r| r[0].as_str() == Some("CamRoll"))?[2].as_f64()? as f32);
    Some((
        anchor_offset("CamPosEnd")?,
        anchor_offset("TargetPosEnd")?,
        fov,
        roll,
    ))
}

pub fn new(car: &mut Gd<Node3D>, length: f32, width: f32) -> Self {
    let mut smoke = vec![];
    for sign in [-1., 1.] {
        let mut emitter = particles(Color::from_rgba(0.7, 0.72, 0.74, 0.25), 1.15, 48, false);
        emitter.set_position(Vector3::new(sign * width * 0.39, 0.16, length * 0.30));
        car.add_child(&emitter);
        smoke.push(emitter);
    }
    let mut flame = particles(Color::from_rgba(0.08, 0.4, 1., 0.7), 0.20, 24, true);
    flame.set_position(Vector3::new(-width * 0.3, 0.3, length * 0.48));
    car.add_child(&flame);
    let mut nitro_light = OmniLight3D::new_alloc();
    nitro_light.set_position(Vector3::new(-width * 0.3, 0.3, length * 0.5));
    nitro_light.set_color(Color::from_rgb(0.08, 0.35, 1.));
    nitro_light.set_param(godot::classes::light_3d::Param::RANGE, 2.5);
    nitro_light.set_visible(false);
    car.add_child(&nitro_light);
    let mut brakes = vec![];
    for sign in [-1., 1.] {
        let mut lamp = OmniLight3D::new_alloc();
        lamp.set_position(Vector3::new(sign * width * 0.32, 0.5, length * 0.43));
        lamp.set_color(Color::from_rgb(1., 0.015, 0.005));
        lamp.set_param(godot::classes::light_3d::Param::RANGE, 2.);
        lamp.set_param(godot::classes::light_3d::Param::ENERGY, 0.15);
        car.add_child(&lamp);
        brakes.push(lamp);
        let mut head = SpotLight3D::new_alloc();
        head.set_position(Vector3::new(sign * width * 0.32, 0.5, -length * 0.43));
        head.set_rotation_degrees(Vector3::new(-7., 0., 0.));
        head.set_color(Color::from_rgb(0.78, 0.88, 1.));
