pub fn new(paths: Vec<String>) -> Result<Self, String> {
    let paths: Vec<_> = paths
        .into_iter()
        .filter(|p| !p.is_empty())
        .collect::<std::collections::BTreeSet<_>>()
        .into_iter()
        .collect();
    let operation = diagnostics::event("loading.start", json!({"resource_count":paths.len()}));
    let mut loader = ResourceLoader::singleton();
    let mut done = vec![];
    let mut resources = vec![];
    for path in &paths {
        if loader.has_cached(path)
            && let Some(resource) = loader.load(path)
        {
            resources.push(resource);
            done.push(true);
            continue;
        }
        let error = loader.load_threaded_request(path);
        if error != godot::global::Error::OK {
            diagnostics::event(
                "loading.end",
                json!({"operation":operation,"outcome":"error","category":"request_rejected","resource_count":paths.len()}),
            );
            return Err(format!("Cannot load {path}: {error:?}"));
        }
        done.push(false);
    }
    Ok(Self {
        paths,
        done,
        resources,
        samples: vec![],
        start: std::time::Instant::now(),
        operation,
        terminal: false,
        last_progress: std::time::Instant::now(),
        samples_dropped: 0,
    })
}

fn poll_inner(&mut self) -> Result<(f64, bool), String> {
    let mut loader = ResourceLoader::singleton();
    let mut total = 0.;
    for (i, path) in self.paths.iter().enumerate() {
        if self.done[i] {
            total += 1.;
            continue;
        }
        let progress = VarArray::new();
        let status = loader
            .load_threaded_get_status_ex(path)
            .progress(&progress)
            .done();
        if status == ThreadLoadStatus::LOADED {
            let resource = loader
                .load_threaded_get(path)
                .ok_or_else(|| format!("Loaded resource unavailable: {path}"))?;
            self.resources.push(resource);
            self.done[i] = true;
            total += 1.;
        } else if status == ThreadLoadStatus::FAILED
            || status == ThreadLoadStatus::INVALID_RESOURCE
        {
            let _ = loader.load_threaded_get(path);
            return Err(format!("Resource failed to load: {path}"));
        } else {
            total += progress
                .get(0)
                .and_then(|v| v.try_to::<f64>().ok())
                .unwrap_or(0.)
                .clamp(0., 1.);
        }
    }
    let progress = if self.paths.is_empty() {
        1.
    } else {
        total / self.paths.len() as f64
    };
    self.samples_dropped += u64::from(record_progress(
        &mut self.samples,
        progress,
        self.start.elapsed().as_secs_f64(),
    ));
    Ok((progress, self.done.iter().all(|d| *d)))
}

pub fn finish(mut self) -> (Vec<Gd<Resource>>, serde_json::Value) {
    let summary = json!({"paths":self.paths,"seconds":self.start.elapsed().as_secs_f64(),"samples":self.samples,"samples_dropped":self.samples_dropped});
    (std::mem::take(&mut self.resources), summary)
}

pub struct RenderedLayout {
    pub texts: BTreeMap<String, Gd<Label>>,
}

pub fn render(
    &self,
    parent: &mut Gd<Control>,
    texts: &[(&str, String)],
) -> Result<RenderedLayout, String> {
    for slot in self.slots.iter().filter(|slot| slot.kind == Kind::Box) {
        slot.draw_box(parent)?;
    }
    let mut result = RenderedLayout {
        texts: BTreeMap::new(),
    };
    for (name, text) in texts {
        let slot = self
            .slot(name)
            .ok_or_else(|| format!("Missing native text slot {name}"))?;
        if slot.kind != Kind::Text {
            return Err(format!("Native slot {name} is not text"));
        }
        let mut clip = Control::new_alloc();
        let (position, size) = slot.pixels();
        clip.set_position(position);
        clip.set_size(size);
        clip.set_clip_contents(true);
        clip.set_meta("native_layout_slot", &slot.name.to_variant());
        clip.set_mouse_filter(godot::classes::control::MouseFilter::IGNORE);
        parent.add_child(&clip);
        let mut label = Label::new_alloc();
        label.set_text(text);
        label.set_size(Vector2::new(size.x, 0.));
        label.set_autowrap_mode(godot::classes::text_server::AutowrapMode::WORD_SMART);
        let (font, height) = slot.font_resource()?;
        label.add_theme_font_override("font", &font);
        label.add_theme_font_size_override("font_size", height);
        label.add_theme_color_override("font_color", color(slot.color));
        label.set_horizontal_alignment(match slot.align.as_str() {
            "Centre" => godot::global::HorizontalAlignment::CENTER,
            "Right" => godot::global::HorizontalAlignment::RIGHT,
            _ => godot::global::HorizontalAlignment::LEFT,
        });
        if slot.shadow {
            label.add_theme_color_override("font_shadow_color", Color::BLACK);
            label.add_theme_constant_override("shadow_offset_x", 2);
            label.add_theme_constant_override("shadow_offset_y", 2);
        }
        label.set_mouse_filter(godot::classes::control::MouseFilter::IGNORE);
        clip.add_child(&label);
        result.texts.insert((*name).into(), label);
    }
    Ok(result)
}

pub fn font_resource(&self) -> Result<(Gd<Font>, i32), String> {
    let path = format!("res://assets/ui/native/fonts/{}-1080.fnt", self.font);
    if !ResourceLoader::singleton().exists(&path) {
        return Err(format!("Missing native font {path}"));
    }
    let font = godot::tools::load::<FontFile>(&path);
    let height = font.get_fixed_size().max(1);
    Ok((font.upcast(), height))
}

fn draw_box(&self, parent: &mut Gd<Control>) -> Result<(), String> {
    let (position, size) = self.pixels();
    let mut polygon = Polygon2D::new_alloc();
    polygon.set_polygon(&PackedVector2Array::from(
        &[
            Vector2::ZERO,
            Vector2::new(size.x, 0.),
            size,
            Vector2::new(0., size.y),
        ][..],
    ));
    polygon.set_position(position);
    if let Some(vertices) = self.vertices {
        polygon.set_vertex_colors(&PackedColorArray::from(&vertices.map(color)[..]));
    } else {
        polygon.set_color(color(self.color));
    }
    if let Some(name) = &self.texture {
        let path = format!("res://assets/ui/native/named/{name}.png");
        if !ResourceLoader::singleton().exists(&path) {
            return Err(format!("Missing native texture {path}"));
        }
        let texture = godot::tools::load::<Texture2D>(&path);
        let w = texture.get_width() as f32;
        let h = texture.get_height() as f32;
        let [u0, u1, v0, v1] = self.uv;
        polygon.set_uv(&PackedVector2Array::from(
            &[
                Vector2::new(u0 * w, v0 * h),
                Vector2::new(u1 * w, v0 * h),
                Vector2::new(u1 * w, v1 * h),
                Vector2::new(u0 * w, v1 * h),
            ][..],
        ));
        polygon.set_texture(&texture);
        polygon.set_texture_repeat(godot::classes::canvas_item::TextureRepeat::ENABLED);
        polygon.set_meta("native_asset", &name.to_variant());
    }
    if self.additive {
        let mut shader = godot::classes::Shader::new_gd();
        shader.set_code("shader_type canvas_item;render_mode blend_add;void fragment(){COLOR*=texture(TEXTURE,UV);}");
        let mut material = godot::classes::ShaderMaterial::new_gd();
        material.set_shader(&shader);
        polygon.set_material(&material);
    }
    polygon.set_meta("native_layout_slot", &self.name.to_variant());
    parent.add_child(&polygon);
    Ok(())
}

pub fn create(
    initial: Color,
    title: &str,
    price: u32,
    edit_alpha: bool,
) -> Result<Gd<Self>, String> {
    let json = FileAccess::get_file_as_string("res://assets/ui/native/colour-chart.json");
    let chart: serde_json::Value =
        serde_json::from_str(&json.to_string()).map_err(|error| error.to_string())?;
    let entries = chart["cells"]
        .as_array()
        .ok_or("Native colour chart is missing its cells")?;
    if chart["columns"] != COLUMNS || chart["rows"] != ROWS || entries.len() != COLUMNS * ROWS {
        return Err("Native colour chart must be the recovered 24×11 grid".into());
    }
    let mut cells = Vec::with_capacity(entries.len());
    for (index, entry) in entries.iter().enumerate() {
        if entry["column"] != index / ROWS || entry["row"] != index % ROWS {
            return Err("Native colour chart order differs from the source consumer".into());
        }
        let values = entry["rgba"]
            .as_array()
            .filter(|values| values.len() == 4)
            .ok_or("Invalid native chart RGBA")?;
        let mut rgba = [0.; 4];
        for (slot, value) in values.iter().enumerate() {
            rgba[slot] = value
                .as_u64()
                .filter(|value| *value <= 255)
                .ok_or("Invalid native chart byte")? as f32
                / 255.;
        }
        cells.push(Color::from_rgba(rgba[0], rgba[1], rgba[2], rgba[3]));
    }
    let mut node = Self::new_alloc();
    {
        let mut state = node.bind_mut();
        state.selected = nearest(&cells, initial);
        state.cells = cells;
        state.color = initial;
        state.title = title.into();
        state.price = price;
        state.edit_alpha = edit_alpha;
    }
    Ok(node)
}

