    child_name: &str,
) -> AnimationPlayerData {
    let playing = ap.is_playing();
    let current = if playing {
        let name = ap.get_current_animation().to_string();
        if name.is_empty() { None } else { Some(name) }
    } else {
        None
    };

    let animations: Vec<String> = ap
        .get_animation_list()
        .as_slice()
        .iter()
        .map(|s| s.to_string())
        .collect();

    let length_sec = current
        .as_ref()
        .and_then(|name| {
            ap.get_animation(&StringName::from(name.as_str()))
                .map(|anim| anim.get_length())
        })
        .unwrap_or(0.0);

    let looping = current
        .as_ref()
        .and_then(|name| {
            ap.get_animation(&StringName::from(name.as_str()))
                .map(|anim| anim.get_loop_mode() != godot::classes::animation::LoopMode::NONE)
        })
        .unwrap_or(false);

    AnimationPlayerData {
        child: child_name.into(),
        current_animation: current,
        animations,
        position_sec: ap.get_current_animation_position(),
        length_sec,
        looping,
        playing,
    }
}

