pub fn get_nav_path(&self, from: Vector3, to: Vector3) -> Result<NavPathResponse, String> {
    let mut nav_server = NavigationServer3D::singleton();
    let maps = nav_server.get_maps();
    if maps.is_empty() {
        return Err("No navigation maps available. Is NavigationServer3D active?".into());
    }
    let map = maps.get(0).ok_or("No navigation map at index 0")?;
    let path = nav_server.map_get_path(map, from, to, true);
    let traversable = !path.is_empty();
    let nav_distance: f64 = if traversable {
        let mut total = 0.0f32;
        for i in 1..path.len() {
            total += path[i - 1].distance_to(path[i]);
        }
        total as f64
    } else {
        0.0
    };
    let straight_distance = from.distance_to(to) as f64;

    Ok(NavPathResponse {
        nav_distance,
        straight_distance,
        path_ratio: if straight_distance > 0.0 {
            nav_distance / straight_distance
        } else {
            1.0
        },
        path_points: path.len() as u32,
        traversable,
    })
}

fn resource_path(res: &Gd<Resource>) -> Option<String> {
    let path = res.get_path().to_string();
    // Sub-resources embedded in a scene file have paths like
    // "res://scene.tscn::SubResourceId". Treat these as inline (no external file).
    if path.is_empty() || path.contains("::") {
        None
    } else {
        Some(path)
    }
}

pub fn validate_targets(owner: &Gd<Node>, config: &mut DashcamConfig) -> Result<(), String> {
    for action in &config.input_actions {
        if !InputMap::singleton().has_action(action.as_str()) {
            return Err(format!("Unknown InputMap action '{action}'"));
        }
    }
    if config.movement_nodes.is_empty() {
        return Ok(());
    }
    let tree = owner
        .get_tree_or_null()
        .ok_or("Movement capture requires a scene tree")?;
    let scene = tree
        .get_current_scene()
        .ok_or("Movement capture requires a current scene")?;
    let mut paths = Vec::new();
    for path in &config.movement_nodes {
        let body = scene
            .try_get_node_as::<CharacterBody3D>(path.as_str())
            .ok_or_else(|| format!("Movement target '{path}' must resolve to a CharacterBody3D"))?;
        let node = body.clone().upcast::<Node>();
        if node != scene && !scene.is_ancestor_of(&node) {
            return Err(format!(
                "Movement target '{path}' is outside the current scene captured by the recorder"
            ));
        }
        let canonical = body.get_path().to_string();
        if paths.contains(&canonical) {
            return Err(format!("Duplicate movement target '{path}'"));
        }
        paths.push(canonical);
    }
    config.movement_nodes = paths;
    Ok(())
}

pub fn capture(owner: &Gd<Node>, config: &DashcamConfig) -> HashMap<String, MovementFrameData> {
    let mut samples = HashMap::new();
    if config.movement_nodes.is_empty() {
        return samples;
    }
    let Some(tree) = owner.get_tree_or_null() else {
        return samples;
    };
    let Some(scene) = tree.get_current_scene() else {
        return samples;
    };
    let input = Input::singleton();
    let actions: BTreeMap<String, f32> = config
        .input_actions
        .iter()
        .filter(|action| InputMap::singleton().has_action(action.as_str()))
        .map(|action| (action.clone(), input.get_action_strength(action.as_str())))
        .collect();
    for path in &config.movement_nodes {
        // A selected node can be freed or replaced after configuration. Absence of
        // movement evidence is preferable to claiming stale contact facts.
        let Some(body) = scene.try_get_node_as::<CharacterBody3D>(path.as_str()) else {
            continue;
        };
        let mut normals = Vec::new();
        let mut truncated = false;
        for index in 0..body.get_slide_collision_count() {
            let Some(collision) = body.get_slide_collision(index) else {
                continue;
            };
            for contact in 0..collision.get_collision_count() {
                if normals.len() == MAX_SLIDE_CONTACT_NORMALS {
                    truncated = true;
                    break;
                }
                normals.push(vector(
                    collision.get_normal_ex().collision_index(contact).done(),
                ));
            }
            if truncated {
                break;
            }
        }
        samples.insert(
            scene
                .get_path_to(&body.clone().upcast::<Node>())
                .to_string(),
            MovementFrameData {
                input_actions: actions.clone(),
                on_floor: body.is_on_floor(),
                on_wall: body.is_on_wall(),
                on_ceiling: body.is_on_ceiling(),
                floor_normal: body.is_on_floor().then(|| vector(body.get_floor_normal())),
                real_velocity: vector(body.get_real_velocity()),
                slide_contact_normals: normals,
                slide_contacts_truncated: truncated,
            },
        );
    }
    samples
}

pub fn handle_query(
    request_id: String,
    method: &str,
    params: serde_json::Value,
    collector: &StageCollector,
    runtime_logger: Option<&Gd<Object>>,
) -> Option<Message> {
    match method {
        "capture_control" => Some(simple_query(
            request_id,
            handle_capture_control(collector, params),
        )),
        "get_viewport" => Some(simple_query(
            request_id,
            parse_params::<stage_protocol::viewport::ViewportParams>(params).and_then(|params| {
                params.validate().map_err(|message| QueryError {
                    code: "invalid_params".into(),
                    message,
                })?;
                let capture =
                    crate::viewport::capture(collector.base().get_tree_or_null(), &params)
                        .map_err(|message| QueryError {
                            code: "internal".into(),
                            message,
                        })?;
                to_json_value(&capture)
            }),
        )),
        "runtime_status" => Some(simple_query(
            request_id,
            parse_params::<stage_protocol::runtime::RuntimeStatusParams>(params).and_then(|_| {
                to_json_value(&crate::runtime_identity::status(
                    collector.base().get_tree_or_null(),
                ))
            }),
        )),
        "runtime_diagnostics" => Some(simple_query(
            request_id,
            parse_params::<stage_protocol::runtime_diagnostics::RuntimeDiagnosticsQueryParams>(
                params,
            )
            .and_then(|_| handle_runtime_diagnostics(runtime_logger)),
        )),
        "get_snapshot_data" => Some(simple_query(
            request_id,
            handle_get_snapshot_data(params, collector),
        )),
        "get_frame_info" => Some(simple_query(request_id, handle_get_frame_info(collector))),
        "get_node_inspect" => Some(simple_query(
            request_id,
            handle_get_node_inspect(params, collector),
        )),
        "get_scene_tree" => Some(simple_query(
            request_id,
            handle_get_scene_tree(params, collector),
        )),
        "execute_action" => handle_execute_action(request_id, params, collector),
        "spatial_query" => Some(simple_query(
            request_id,
            handle_spatial_query(params, collector),
        )),
        _ => Some(Message::Error {
            request_id,
            code: "method_not_found".to_string(),
            message: format!("Unknown query method: {method}"),
        }),
    }
}

fn handle_capture_control(
    collector: &StageCollector,
    params: serde_json::Value,
) -> Result<serde_json::Value, QueryError> {
    use godot::prelude::*;
    let invalid = |message: &str| QueryError {
        code: "invalid_params".into(),
        message: message.into(),
    };
    let Some(tree) = collector.base().get_tree_or_null() else {
        return Err(invalid("Scene tree unavailable"));
    };
    let Some(mut runtime) = tree.get_root().get_node_or_null("StageRuntime") else {
        return Err(invalid("StageRuntime is unavailable"));
    };
    let action = params["action"]
        .as_str()
        .ok_or_else(|| invalid("capture action is required"))?;
    let result = match action {
        "start" => runtime.call("capture_start", &[false.to_variant()]),
        "continue" => runtime.call("capture_start", &[true.to_variant()]),
        "stop" => runtime.call("capture_stop", &[]),
        "keep" => runtime.call(
            "capture_keep",
            &[GString::from(params["note"].as_str().unwrap_or("")).to_variant()],
        ),
        "save" => runtime.call(
            "capture_save",
            &[GString::from(params["note"].as_str().unwrap_or("")).to_variant()],
        ),
        "discard" => runtime.call("capture_discard", &[]),
        "status" => runtime.call("capture_status", &[]),
        "config" => {
            let patch: stage_protocol::capture::PhaseOptions =
                serde_json::from_value(params["config"].clone())
                    .map_err(|e| invalid(&format!("Invalid capture config: {e}")))?;
            let encoded = serde_json::to_string(&patch).map_err(|e| invalid(&e.to_string()))?;
            let value = godot::classes::Json::parse_string(&encoded);
            runtime.call("capture_configure", &[value])
        }
        _ => return Err(invalid("Unknown capture action")),
    };
    let mut result = crate::collector::variant_to_json(&result)
        .ok_or_else(|| invalid("Invalid capture response"))?;
    stage_protocol::capture::normalize_godot_integers(&mut result);
    if let Some(error) = result["error"].as_str() {
        return Err(invalid(error));
    }
    Ok(result)
}

fn handle_runtime_diagnostics(
    runtime_logger: Option<&Gd<Object>>,
) -> Result<serde_json::Value, QueryError> {
    use stage_protocol::runtime_diagnostics::{
        RuntimeDiagnosticCapture, RuntimeDiagnosticLimits, RuntimeDiagnosticsEngineResponse,
    };

    let limitations = vec![
        "Capture starts when StageRuntime registers its Logger; engine initialization and earlier messages are unavailable.".to_string(),
        "Godot stdout/stderr project settings can suppress Logger delivery.".to_string(),
        "Release builds can omit script backtraces unless call-stack tracking is enabled.".to_string(),
        "A blocked or hung runtime may not execute callbacks or answer this query.".to_string(),
    ];
    let Some(logger) = runtime_logger else {
        return to_json_value(&RuntimeDiagnosticsEngineResponse {
            identity: crate::runtime_identity::identity().clone(),
            available: false,
            diagnostics: Vec::new(),
            retained_count: 0,
            omitted_count: 0,
            limits: RuntimeDiagnosticLimits {
                queue_capacity: 128,
                message_max_chars: 2048,
                file_max_chars: 512,
                function_max_chars: 256,
                backtrace_max_frames: 16,
            },
            limitations,
        });
    };

    let snapshot = logger.clone().call("snapshot", &[]);
    let json = crate::collector::variant_to_json(&snapshot).ok_or_else(|| QueryError {
        code: "internal".into(),
        message: "Runtime logger returned unsupported diagnostic data".into(),
    })?;
    let capture: RuntimeDiagnosticCapture =
        serde_json::from_value(json).map_err(|error| QueryError {
            code: "internal".into(),
            message: format!("Runtime logger returned invalid diagnostic data: {error}"),
        })?;
    if capture.retained_count as usize != capture.entries.len()
        || capture.retained_count > capture.limits.queue_capacity
    {
        return Err(QueryError {
            code: "internal".into(),
            message: "Runtime logger returned inconsistent retained diagnostic counts".into(),
        });
    }
    to_json_value(&RuntimeDiagnosticsEngineResponse {
        identity: crate::runtime_identity::identity().clone(),
        available: true,
        diagnostics: capture.entries,
        retained_count: capture.retained_count,
        omitted_count: capture.omitted_count,
        limits: capture.limits,
        limitations,
    })
}

pub(super) fn begin_segment(
    &mut self,
    config: PhaseConfig,
    phase: &str,
    recording_id: &str,
    context: SegmentContext,
) -> Result<serde_json::Value, String> {
    config.validate(phase)?;
    if self.segment.is_some() {
        return Err("Finish and keep or discard the current segment first".into());
    }
    if !config.enabled {
        return Err("The selected capture phase is off".into());
    }
    if !matches!(phase, "startup" | "play") {
        return Err("phase must be startup or play".into());
    }
    let metadata_bytes = serde_json::to_vec(&context.project_metadata)
        .map_err(|e| format!("Invalid project metadata: {e}"))?
        .len();
    if context.project_metadata.len() > 32 || metadata_bytes > 64 * 1024 {
        return Err("Project metadata exceeds 32 providers or 64 KiB encoded payload".into());
    }
    let mut recorder_config = self.dashcam_config.clone();
    recorder_config.movement_nodes = config.movement_nodes.clone();
    recorder_config.input_actions = config.input_actions.clone();
    // Startup targets do not exist yet. Validate their portable names above;
    // resolve them while sampling, without inventing missing-node evidence.
    if phase == "play" {
        crate::movement_capture::validate_targets(&self.base().clone(), &mut recorder_config)?;
    }
    if recording_id.len() > 128
        || !recording_id
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
    {
        return Err("Invalid recording identifier".into());
    }
    self.set_capture_enabled_internal(false);
    self.pending_silent_markers.clear();
    self.gap_ledger = GapLedger::default();
    self.capture_probe = CaptureProbe::default();
    self.dashcam_config.capture_interval = config.spatial_interval;
    self.dashcam_config.screenshot_enabled = config.images;
    self.dashcam_config.screenshot_interval_frames = config.image_interval;
    self.dashcam_config.screenshot_max_dimension = config.image_size;
    self.dashcam_config.byte_cap_mb = config.payload_mib;
    self.dashcam_config.screenshot_byte_cap_mb = config.payload_mib;
    self.dashcam_config.anomaly_enabled = config.anomaly_enabled;
    self.dashcam_config.anomaly_min_proportion = config.anomaly_min_proportion;
    self.dashcam_config.anomaly_relative_factor = config.anomaly_relative_factor;
    self.dashcam_config.anomaly_sustained_frames = config.anomaly_sustained_frames;
    self.dashcam_config.anomaly_cooldown_sec = config.anomaly_cooldown_sec;
    self.dashcam_config.anomaly_noise_floor = config.anomaly_noise_floor;
    self.dashcam_config.dense_burst_enabled = false;
    self.dashcam_config.screenshot_readback = config.image_readback;
    self.dashcam_config.movement_nodes = recorder_config.movement_nodes;
    self.dashcam_config.input_actions = recorder_config.input_actions;
    let id = format!("clip_{}_{:08x}", current_time_ms(), rand_u32());
    self.segment = Some(Segment {
        context,
        config,
        phase: phase.into(),
        recording_id: if recording_id.is_empty() {
            id.clone()
        } else {
            recording_id.into()
        },
        id,
        started: Instant::now(),
        started_frame: current_physics_frame(),
        started_ms: current_time_ms(),
        ended_frame: None,
        ended_ms: None,
        elapsed_usec: 0,
        stop_reason: None,
        metrics: VecDeque::new(),
        metric_bytes: 0,
        marker_bytes: 0,
        previous_sample: None,
        observer_total_usec: 0,
        observer_max_usec: 0,
        dimensions: 0,
        pending_limit: None,
        trigger_deadline: None,
        last_system_marker: None,
    });
    self.set_capture_enabled_internal(true);
    Ok(self.segment_status())
}

pub(super) fn sample_segment_metrics(
    &mut self,
    data: &str,
    callback_usec: u64,
) -> Result<(), String> {
    if !self
        .segment
        .as_ref()
        .is_some_and(|s| s.active() && s.config.metrics)
    {
        return Ok(());
    }
    if !self.segment_admit(data.len() + 5 * std::mem::size_of::<u64>()) {
        return Ok(());
    }
    let Some(segment) = self
        .segment
        .as_mut()
        .filter(|s| s.active() && s.config.metrics)
    else {
        return Ok(());
    };
    let value: serde_json::Value =
        serde_json::from_str(data).map_err(|e| format!("Invalid metrics: {e}"))?;
    if !value.is_object() {
        return Err("Metrics must be a dictionary of explicit provider values".into());
    }
    let now = Instant::now();
    let interval_usec = segment
        .previous_sample
        .replace(now)
        .map(|last| now.duration_since(last).as_micros() as u64)
        .unwrap_or(0);
    let metric = Metric {
        render_frame: Engine::singleton().get_process_frames(),
        physics_frame: current_physics_frame(),
        timestamp_ms: current_time_ms(),
        elapsed_usec: segment.started.elapsed().as_micros() as u64,
        interval_usec,
        data: value.to_string(),
    };
    // Count the encoded value and fixed scalar fields, not process memory.
    let bytes = metric.data.len() + 5 * std::mem::size_of::<u64>();
    let cap = segment.config.payload_mib as usize * 1024 * 1024;
    if bytes > cap {
        return Err("One metric sample exceeds the capture payload budget".into());
    }
    segment.metric_bytes += bytes;
    segment.metrics.push_back(metric);
    segment.observer_total_usec = segment.observer_total_usec.saturating_add(callback_usec);
    segment.observer_max_usec = segment.observer_max_usec.max(callback_usec);
    if segment.config.retention == Retention::Rolling {
        while segment.metrics.len() > segment.config.max_records as usize
            || segment.metric_bytes > cap
            || segment.metrics.front().is_some_and(|m| {
                segment.started.elapsed().as_micros() as u64 - m.elapsed_usec
                    > segment.config.duration_secs as u64 * 1_000_000
            })
        {
            if let Some(old) = segment.metrics.pop_front() {
                segment.metric_bytes -= old.data.len() + 5 * std::mem::size_of::<u64>();
            } else {
                break;
            }
        }
    }
    Ok(())
}

pub(super) fn segment_marker(&mut self, source: &str, label: &str, tier: &str) {
    let now = Instant::now();
    let Some(segment) = self.segment.as_ref().filter(|s| s.active()) else {
        return;
    };
    // Suppressed markers must not evict evidence or trip a session bound.
    if tier == "system"
        && segment
            .last_system_marker
            .is_some_and(|last| now.duration_since(last).as_secs() < 5)
    {
        return;
    }
    let source: String = source.chars().take(64).collect();
    let label: String = label.chars().take(1024).collect();
    if !self.segment_admit(source.len() + label.len() + 16) {
        return;
    }
    let Some(segment) = self.segment.as_mut().filter(|s| s.active()) else {
        return;
    };
    if tier == "system" {
        segment.last_system_marker = Some(now);
    }
    if tier != "silent"
        && segment.config.retention == Retention::Rolling
        && segment.config.save == SavePolicy::OnTrigger
    {
        // A bounded post-window; repeated markers cannot postpone it forever.
        segment
            .trigger_deadline
            .get_or_insert(now + std::time::Duration::from_secs(5));
    }
    let frame = current_physics_frame();
    if self.pending_silent_markers.len() < 1024 {
        segment.marker_bytes += source.len() + label.len() + 16;
        self.pending_silent_markers.push(DashcamTrigger {
            frame,
            timestamp_ms: current_time_ms(),
            source: source.clone(),
            label: label.clone(),
        });
    }
    if tier != "silent" {
        self.base_mut().emit_signal(
            "marker_added",
            &[
                (frame as i64).to_variant(),
                GString::from(&source).to_variant(),
                GString::from(&label).to_variant(),
            ],
        );
    }
}

fn screenshot_unavailable_reason(&self) -> Option<String> {
    if Engine::singleton().is_editor_hint() {
        Some("editor_hint".into())
    } else if DisplayServer::singleton().get_name() == "headless" {
        Some("headless".into())
    } else if self.dashcam_config.screenshot_readback == ScreenshotReadback::Auto
        && RenderingServer::singleton().get_current_rendering_method() != "gl_compatibility"
    {
        Some("Native asynchronous capture requires Compatibility/OpenGL; synchronous recovery is explicit".into())
    } else {
        self.capture_error.clone()
    }
}

fn dispatch_screenshot_capture(&mut self) {
    if self.screenshot_unavailable_reason().is_some() {
        self.gap_ledger
            .record(current_physics_frame(), "readback_unavailable");
        return;
    }
    if self.pending_shot.is_some()
        || self.encoding_requests.len() >= self.dashcam_config.screenshot_encode_queue
    {
        self.capture_probe.dropped_queue_full += 1;
        self.gap_ledger
            .record(current_physics_frame(), "capture_capacity_full");
        return;
    }
    let Some(viewport) = self.base().get_viewport() else {
        self.capture_error = Some("Viewport unavailable".into());
        return;
    };
    let Some(texture) = viewport.get_texture() else {
        self.capture_error = Some("Viewport texture unavailable".into());
        return;
    };
    if texture.get_width() <= 0 || texture.get_height() <= 0 {
        self.capture_error = Some("Viewport texture is empty".into());
        return;
    }
    let size = crate::capture_readback::reduced_size(
        texture.get_width() as u32,
        texture.get_height() as u32,
        self.dashcam_config.screenshot_max_dimension,
    );
    let mut raw = RawShot {
        generation: self.capture_generation,
        frame: current_physics_frame(),
        timestamp_ms: current_time_ms(),
        rgba: Vec::new(),
        width: size.0 as u16,
        height: size.1 as u16,
        quality: (self.dashcam_config.screenshot_quality * 100.0).round() as u8,
        analyze: self.dashcam_config.anomaly_enabled && self.dashcam_config.screenshot_enabled,
        noise_floor: self.dashcam_config.anomaly_noise_floor,
    };
    let readback = self.readback.get_or_insert_with(Default::default);
    if self.dashcam_config.screenshot_readback == ScreenshotReadback::Synchronous {
        match readback.synchronous(texture.get_rid(), size) {
            Ok(pixels) => {
                self.capture_probe.observe_readback(pixels.latency_ms);
                self.capture_probe.submission_ms_max =
                    self.capture_probe.submission_ms_max.max(pixels.latency_ms);
                self.capture_probe.last_request_frame = raw.frame;
                self.capture_probe.last_completion_frame = current_physics_frame();
                raw.rgba = pixels.rgba;
                self.send_raw_shot(raw);
            }
            Err(error) => {
                self.gap_ledger.record(raw.frame, "readback_unavailable");
                self.capture_error = Some(error);
            }
        }
    } else {
        match readback.submit(texture.get_rid(), size, self.physics_tick_count) {
            Ok(()) => {
                self.pending_shot = Some(raw);
            }
            Err(error) => {
                self.gap_ledger.record(raw.frame, "readback_unavailable");
                self.capture_error = Some(error);
            }
        }
    }
}

fn drain_encoded_shots(&mut self) {
    loop {
        let shot = match self.screenshot_rx.as_ref().map(Receiver::try_recv) {
            Some(Ok(shot)) => shot,
            Some(Err(TryRecvError::Empty)) | None => break,
            Some(Err(TryRecvError::Disconnected)) => {
                self.screenshot_rx = None;
                for &(_, frame) in &self.encoding_requests {
                    self.gap_ledger.record(frame, "encode_worker_unavailable");
                }
                self.encoding_requests.clear();
                self.capture_error = Some("Screenshot encoder disconnected".into());
                break;
            }
        };
        self.encoding_requests.pop_front();
        if shot.generation != self.capture_generation || !self.is_dashcam_active() {
            continue;
        }
        if let Some(analysis) = shot.analysis {
            self.capture_probe.analysis_ms_ema = if self.capture_probe.analysis_ms_ema == 0.0 {
                analysis.analysis_ms
            } else {
                self.capture_probe.analysis_ms_ema * 0.95 + analysis.analysis_ms * 0.05
            };
            self.capture_probe.analysis_ms_max =
                self.capture_probe.analysis_ms_max.max(analysis.analysis_ms);
            self.anomaly_frames_analyzed = self.anomaly_frames_analyzed.saturating_add(1);
            if analysis.reset {
                self.anomaly_frames_skipped = self.anomaly_frames_skipped.saturating_add(1);
            }
            if self.dashcam_config.anomaly_enabled
                && let Some(label) = self.anomaly_detector.observe(
                    analysis.proportion,
                    analysis.reset,
                    shot.frame,
                    AnomalySettings {
                        min: self.dashcam_config.anomaly_min_proportion,
                        relative: self.dashcam_config.anomaly_relative_factor,
                        sustained: self.dashcam_config.anomaly_sustained_frames,
                        cooldown_frames: self.dashcam_config.anomaly_cooldown_sec as u64
                            * self.physics_fps as u64,
                    },
                )
            {
                self.on_dashcam_marker_with_tier(
                    "system",
                    &label,
                    shot.frame,
                    shot.timestamp_ms,
                    DashcamTier::System,
                );
                self.base_mut().emit_signal(
                    "marker_added",
                    &[
                        (shot.frame as i64).to_variant(),
                        GString::from("system").to_variant(),
                        GString::from(&label).to_variant(),
                    ],
                );
            }
        } else {
            self.anomaly_frames_skipped = self.anomaly_frames_skipped.saturating_add(1);
        }
        if shot.error.is_some() {
            self.gap_ledger.record(shot.frame, "encode_failed");
            continue;
        }
        let Some(jpeg_data) = shot.jpeg_data else {
            self.gap_ledger.record(shot.frame, "encode_failed");
            continue;
        };
        self.screenshot_ingest(CapturedScreenshot {
            frame: shot.frame,
            timestamp_ms: shot.timestamp_ms,
            jpeg_data,
            width: shot.width,
            height: shot.height,
        });
    }
}

fn do_capture(&mut self) -> Option<CapturedFrame> {
    let collector = self.collector.as_ref()?;

    let params = GetSnapshotDataParams {
        perspective: PerspectiveParam::Camera,
        radius: f64::MAX,
        include_offscreen: true,
        groups: vec![],
        class_filter: vec![],
        detail: DetailLevel::Standard,
        expose_internals: false,
    };

    let snapshot = match self.segment_scope() {
        Some(scope) if !scope.is_empty() => {
            collector.bind().collect_scoped_snapshot(&params, scope)
        }
        _ => collector.bind().collect_snapshot(&params),
    };
    if let Some(entity) = snapshot.entities.first() {
        self.segment_set_dimensions(entity.position.len() as u32);
    }

    let mut movement =
        crate::movement_capture::capture(&self.base().clone(), &self.dashcam_config);
    let frame_entities: Vec<FrameEntityData> = snapshot
        .entities
        .iter()
        .map(|e| FrameEntityData {
            path: e.path.clone(),
            class: e.class.clone(),
            position: e.position.clone(),
            rotation_deg: e.rotation_deg.clone(),
            velocity: e.velocity.clone(),
            groups: e.groups.clone(),
            visible: e.visible,
            state: e.state.clone(),
            movement: movement.remove(&e.path),
        })
        .collect();

    let data = match rmp_serde::to_vec(&frame_entities) {
        Ok(d) => d,
        Err(e) => {
            tracing::error!("Failed to serialize frame data: {e}");
            return None;
        }
    };

    let camera = self
        .base()
        .get_viewport()
        .and_then(|viewport| viewport.get_camera_3d())
        .map(|camera| {
            let position = camera.get_global_position();
            let quaternion = camera.get_global_transform().basis.get_quaternion();
            let object = camera.clone().upcast::<godot::classes::Object>();
            stage_protocol::recording::CameraFrameData {
                position: vec![position.x as f64, position.y as f64, position.z as f64],
                quaternion: vec![
                    quaternion.x as f64,
                    quaternion.y as f64,
                    quaternion.z as f64,
                    quaternion.w as f64,
                ],
                projection: object.get("projection").to::<i64>() as u8,
                fov_deg: object.get("fov").to::<f64>(),
                ortho_size: object.get("size").to::<f64>(),
                keep_aspect: object.get("keep_aspect").to::<i64>() as u8,
                camera_path: camera.get_path().to_string(),
            }
        });

    Some(CapturedFrame {
        frame: snapshot.frame,
        // Live snapshots use simulation-relative time. Segment channels
        // share wall time for retention and persisted temporal coverage;
        // mixing those clocks would immediately evict every spatial frame.
        timestamp_ms: if self.segment.is_some() {
            current_time_ms()
        } else {
            snapshot.timestamp_ms
        },
        data,
        camera,
    })
}

fn on_dashcam_marker_with_tier(
    &mut self,
    source: &str,
    label: &str,
    frame: u64,
    timestamp_ms: u64,
    tier: DashcamTier,
) {
    if self.segment.is_some() {
        self.segment_marker(source, label, tier.as_str());
        return;
    }
    // Determine action without borrowing dashcam_state.
    let is_buffering = matches!(self.dashcam_state, DashcamState::Buffering);
    let is_post_capture = matches!(self.dashcam_state, DashcamState::PostCapture { .. });

    if matches!(self.dashcam_state, DashcamState::Disabled) {
        return;
    }
    if self.dashcam_config.dense_burst_enabled {
        self.burst_until_frame = Some(frame.saturating_add(
            self.dashcam_config.dense_burst_duration_sec as u64 * self.physics_fps as u64,
        ));
    }

    if is_buffering {
        // Snapshot ring buffer and transition to PostCapture.
        let pre_buffer: Vec<CapturedFrame> = self.ring_buffer.iter().cloned().collect();
        let post_window = self.post_window_frames(tier);
        let force_close_at_frame = if tier == DashcamTier::System {
            Some(frame + self.dashcam_config.max_window_sec as u64 * self.physics_fps as u64)
        } else {
            None
        };

        self.dashcam_state = DashcamState::PostCapture {
            frames_remaining: post_window,
            tier,
            pre_buffer,
            post_buffer: Vec::new(),
            markers: vec![DashcamTrigger {
                frame,
                timestamp_ms,
                source: source.to_string(),
                label: label.to_string(),
            }],
            last_system_trigger_frame: if tier == DashcamTier::System {
                frame
            } else {
                0
            },
            force_close_at_frame,
            post_screenshots: Vec::new(),
        };

        let tier_str = tier.as_str();
        self.base_mut().emit_signal(
            "dashcam_clip_started",
            &[
                (frame as i64).to_variant(),
                GString::from(tier_str).to_variant(),
            ],
        );
    } else if is_post_capture {
        self.merge_dashcam_trigger(tier, source, label, frame, timestamp_ms);
    }
}

fn add_silent_marker(&mut self, source: &str, label: &str, frame: u64, timestamp_ms: u64) {
    self.pending_silent_markers.push(DashcamTrigger {
        frame,
        timestamp_ms,
        source: source.to_string(),
        label: label.to_string(),
    });

    if self.pending_silent_markers.len() > MAX_PENDING_SILENT_MARKERS {
        let excess = self.pending_silent_markers.len() - MAX_PENDING_SILENT_MARKERS;
        self.pending_silent_markers.drain(..excess);
    }

    self.base_mut().emit_signal(
        "marker_added",
        &[
            (frame as i64).to_variant(),
            GString::from(source).to_variant(),
            GString::from(label).to_variant(),
        ],
    );
}

fn detect_scene_dimensions(root: Option<Gd<Node>>) -> u32 {
    let Some(root) = root else { return 3 };
    let root_node: Gd<Node> = root.upcast();
    let has_2d = has_node_type_recursive(&root_node, true);
    let has_3d = has_node_type_recursive(&root_node, false);
    match (has_2d, has_3d) {
        (true, false) => 2,
        _ => 3,
    }
}

fn has_node_type_recursive(node: &Gd<Node>, check_2d: bool) -> bool {
    if check_2d {
        if node.clone().try_cast::<Node2D>().is_ok() {
            return true;
        }
    } else if node.clone().try_cast::<Node3D>().is_ok() {
        return true;
    }
    let count = node.get_child_count();
    for i in 0..count {
        if let Some(child) = node.get_child(i)
            && has_node_type_recursive(&child, check_2d)
        {
            return true;
        }
    }
    false
}

fn current_physics_frame() -> u64 {
    godot::classes::Engine::singleton().get_physics_frames()
}

pub(crate) fn globalize_path(godot_path: &str) -> String {
    godot::classes::ProjectSettings::singleton()
        .globalize_path(godot_path)
        .to_string()
}

pub fn handle_recording_query(
    recorder: &mut Gd<StageRecorder>,
    method: &str,
    params: &Value,
) -> Result<Value, (String, String)> {
    match method {
        "recording_list" => handle_list(recorder, params),
        "recording_delete" => handle_delete(recorder, params),
        "recording_marker" => handle_marker(recorder, params),
        "recording_markers" => handle_get_markers(recorder, params),
        "recording_resolve_path" => handle_resolve_path(params),
        "dashcam_status" => handle_dashcam_status(recorder),
        "dashcam_flush" => handle_dashcam_flush(recorder, params),
        "dashcam_config" => handle_dashcam_config(recorder, params),
        _ => Err((
            "method_not_found".into(),
            format!("Unknown recording method: {method}"),
        )),
    }
}

fn handle_list(
    recorder: &mut Gd<StageRecorder>,
    params: &Value,
) -> Result<Value, (String, String)> {
    let storage_path = params
        .get("storage_path")
        .and_then(|v| v.as_str())
        .unwrap_or("user://stage_recordings/");

    let recordings = recorder.bind().list_recordings(storage_path.into());

    let list: Vec<Value> = recordings
        .iter_shared()
        .map(|dict| {
            let created_at_unix_ms = dict
                .get("created_at_unix_ms")
                .map(|v: godot::builtin::Variant| v.to::<i64>())
                .unwrap_or(0);
            let created_at = unix_ms_to_iso8601(created_at_unix_ms);

            let trigger_label: Option<String> = dict
                .get("trigger_label")
                .map(|v| v.to_string())
                .filter(|s| !s.is_empty());

            let capture: Option<Value> = dict
                .get("capture_json")
                .map(|v| v.to_string())
                .and_then(|s| serde_json::from_str(&s).ok());

            let mut entry = json!({
                "clip_id": dict.get("clip_id").map(|v| v.to_string()).unwrap_or_default(),
                "name": dict.get("name").map(|v| v.to_string()).unwrap_or_default(),
                "frames_captured": dict.get("frames_captured").map(|v: godot::builtin::Variant| v.to::<u32>()).unwrap_or(0),
                "duration_ms": dict.get("duration_ms").map(|v: godot::builtin::Variant| v.to::<i64>()).unwrap_or(0),
                "frame_range": [
                    dict.get("frame_range_start").map(|v: godot::builtin::Variant| v.to::<i64>()).unwrap_or(0),
                    dict.get("frame_range_end").map(|v: godot::builtin::Variant| v.to::<i64>()).unwrap_or(0),
                ],
                "markers_count": dict.get("markers_count").map(|v: godot::builtin::Variant| v.to::<u32>()).unwrap_or(0),
                "size_kb": dict.get("size_kb").map(|v: godot::builtin::Variant| v.to::<u32>()).unwrap_or(0),
                "created_at": created_at,
                "created_at_unix_ms": created_at_unix_ms,
                "dashcam": dict.get("dashcam").map(|v: godot::builtin::Variant| v.to::<bool>()).unwrap_or(false),
                "tier": dict.get("dashcam_tier").map(|v| v.to_string()).unwrap_or_default(),
            });

            if let Some(label) = trigger_label {
                entry["trigger_label"] = json!(label);
            }
            if let Some(cap) = capture {
                entry["capture"] = cap;
            }

            entry
        })
        .collect();

    Ok(json!({ "clips": list }))
}

fn handle_delete(
    recorder: &mut Gd<StageRecorder>,
    params: &Value,
) -> Result<Value, (String, String)> {
    let id = params
        .get("clip_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| ("invalid_params".into(), "clip_id is required".to_string()))?;
    let storage_path = params
        .get("storage_path")
        .and_then(|v| v.as_str())
        .unwrap_or("user://stage_recordings/");

    let ok = recorder
        .bind()
        .delete_recording(storage_path.into(), id.into());

    if ok {
        Ok(json!({ "result": "ok", "clip_id": id }))
    } else {
        Err(("clip_not_found".into(), format!("Clip '{id}' not found")))
    }
}

fn handle_marker(
    recorder: &mut Gd<StageRecorder>,
    params: &Value,
) -> Result<Value, (String, String)> {
    let dashcam_active = {
        let state = recorder.bind().get_dashcam_state().to_string();
        state == "buffering" || state == "post_capture"
    };

    if !dashcam_active {
        return Err((
            "no_dashcam_active".into(),
            "Dashcam is not active to add a marker to".into(),
        ));
    }

    let source = params
        .get("source")
        .and_then(|v| v.as_str())
        .unwrap_or("agent");
    let label = params.get("label").and_then(|v| v.as_str()).unwrap_or("");

    let tier = if source == "agent" || source == "human" {
        "deliberate"
    } else {
        "system"
    };
    recorder
        .bind_mut()
        .trigger_dashcam_clip(source.into(), label.into(), tier.into());

    let frame = godot::classes::Engine::singleton().get_physics_frames();
    Ok(json!({
        "ok": true,
        "frame": frame,
        "source": source,
        "label": label,
        "dashcam_triggered": true,
        "dashcam_tier": tier,
    }))
}

fn handle_get_markers(
    recorder: &mut Gd<StageRecorder>,
    params: &Value,
) -> Result<Value, (String, String)> {
    let id = params
        .get("clip_id")
        .and_then(|v| v.as_str())
        .ok_or_else(|| ("invalid_params".into(), "clip_id is required".to_string()))?;
    let storage_path = params
        .get("storage_path")
        .and_then(|v| v.as_str())
        .unwrap_or("user://stage_recordings/");

    let markers = recorder
        .bind()
        .get_recording_markers(storage_path.into(), id.into());

    let list: Vec<Value> = markers
        .iter_shared()
        .map(|dict| {
            json!({
                "frame": dict.get("frame").map(|v: godot::builtin::Variant| v.to::<i64>()).unwrap_or(0),
                "timestamp_ms": dict.get("timestamp_ms").map(|v: godot::builtin::Variant| v.to::<i64>()).unwrap_or(0),
                "source": dict.get("source").map(|v| v.to_string()).unwrap_or_default(),
                "label": dict.get("label").map(|v| v.to_string()).unwrap_or_default(),
            })
        })
        .collect();

    Ok(json!({ "clip_id": id, "markers": list }))
}

fn handle_dashcam_status(recorder: &mut Gd<StageRecorder>) -> Result<Value, (String, String)> {
    serde_json::from_str(&recorder.bind().get_dashcam_status_json().to_string())
        .map_err(|error| ("internal_error".into(), error.to_string()))
}

fn handle_dashcam_flush(
    recorder: &mut Gd<StageRecorder>,
    params: &Value,
) -> Result<Value, (String, String)> {
    let label = params
        .get("marker_label")
        .and_then(|v| v.as_str())
        .unwrap_or("");

    // Capture buffer frame count before flush (flush drains the buffer)
    let buffer_frames = recorder.bind().get_dashcam_buffer_frames();

    let clip_id = recorder
        .bind_mut()
        .flush_dashcam_clip_from(label, "agent")
        .to_string();

    if clip_id.is_empty() {
        Err((
            "dashcam_not_active".into(),
            "Dashcam is not active or flush failed".into(),
        ))
    } else {
        Ok(json!({
            "result": "ok",
            "clip_id": clip_id,
            "tier": "deliberate",
            "frames": buffer_frames,
        }))
    }
}

fn handle_dashcam_config(
    recorder: &mut Gd<StageRecorder>,
    params: &Value,
) -> Result<Value, (String, String)> {
    let patch =
        serde_json::from_value::<stage_protocol::dashcam::DashcamConfigPatch>(params.clone())
            .map_err(|error| ("invalid_params".into(), error.to_string()))?;
    recorder
        .bind_mut()
        .configure_dashcam(&patch)
        .map_err(|error| ("invalid_params".into(), error))
}

pub fn identity() -> &'static RuntimeIdentity {
    static IDENTITY: OnceLock<RuntimeIdentity> = OnceLock::new();
    IDENTITY.get_or_init(|| {
        let process_id = std::process::id();
        let started = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos();
        RuntimeIdentity {
            project_path: ProjectSettings::singleton()
                .globalize_path("res://")
                .to_string(),
            process_id,
            run_id: format!("run_{process_id}_{started}"),
        }
    })
}

pub fn status(tree: Option<Gd<SceneTree>>) -> RuntimeStatus {
    let scene = tree.and_then(|tree| tree.get_current_scene());
    RuntimeStatus {
        identity: identity().clone(),
        ready: scene.as_ref().is_some_and(|scene| scene.is_node_ready()),
        current_scene: scene.map(|scene| scene.get_scene_file_path().to_string()),
    }
}

#[derive(GodotClass)]
#[class(base = Node)]
pub struct StageTCPServer {
    base: Base<Node>,
    listener: Option<TcpListener>,
    /// Sparse vec of client slots; None = empty slot.
    clients: Vec<Option<ClientSlot>>,
    port: i32,
    /// Frame-advance state machine. The connected/handshake_completed fields are
    /// unused — per-slot state in `clients` is authoritative for connection status.
    conn_state: ConnectionState,
    /// The single client-owned deferred action using the shared frame counter.
    pending_action: Option<PendingAction>,
    collector: Option<Gd<StageCollector>>,
    recorder: Option<Gd<StageRecorder>>,
    runtime_logger: Option<Gd<Object>>,
    /// Seconds of silence on a handshaked connection before treating it as a zombie.
    /// 0 = disabled.
    client_idle_timeout_secs: u64,
}

fn try_accept(&mut self) {
    let filled = self.clients.iter().filter(|s| s.is_some()).count();
    if filled >= MAX_CLIENTS {
        return;
    }

    let listener = match &self.listener {
        Some(l) => l,
        None => return,
    };

    match listener.accept() {
        Ok((stream, addr)) => {
            stream.set_nonblocking(true).ok();
            let slot = ClientSlot {
                stream,
                handshake_complete: false,
                last_activity_at: None,
            };
            let slot_idx = match self.clients.iter().position(|s| s.is_none()) {
                Some(i) => {
                    self.clients[i] = Some(slot);
                    i
                }
                None => {
                    self.clients.push(Some(slot));
                    self.clients.len() - 1
                }
            };
            godot_print!("[Stage] Client connected from {} (slot {})", addr, slot_idx);
            self.send_handshake_to_slot(slot_idx);
        }
        Err(ref e) if e.kind() == ErrorKind::WouldBlock => {}
        Err(e) => {
            godot_error!("[Stage] Accept error: {}", e);
        }
    }
}

fn send_handshake_to_slot(&mut self, slot_idx: usize) {
    let handshake = Handshake::new(
        self.get_godot_version(),
        self.detect_scene_dimensions(),
        self.get_physics_ticks(),
        self.get_project_name(),
        crate::runtime_identity::identity().clone(),
    );
    let msg = Message::Handshake(handshake);

    let result = match self.clients.get_mut(slot_idx).and_then(|s| s.as_mut()) {
        Some(slot) => with_blocking_io(&mut slot.stream, |s| codec::write_message(s, &msg)),
        None => return,
    };

    match result {
        Ok(()) => godot_print!("[Stage] Handshake sent to slot {}", slot_idx),
        Err(e) => {
            godot_error!(
                "[Stage] Failed to send handshake to slot {}: {}",
                slot_idx,
                e
            );
            self.disconnect_slot(slot_idx);
        }
    }
}

fn try_read_handshake(&mut self, slot_idx: usize) {
    let result = match self.clients.get_mut(slot_idx).and_then(|s| s.as_mut()) {
        Some(slot) => with_blocking_io(&mut slot.stream, |s| {
            s.set_read_timeout(Some(std::time::Duration::from_millis(1)))
                .ok();
            codec::read_message::<Message>(s)
        }),
        None => return,
    };

    match result {
        Ok(Message::HandshakeAck(ack)) => {
            godot_print!(
                "[Stage] Handshake ACK from slot {} — session {}",
                slot_idx,
                ack.session_id
            );
            if let Some(Some(slot)) = self.clients.get_mut(slot_idx) {
                slot.handshake_complete = true;
                slot.last_activity_at = Some(std::time::Instant::now());
            }
        }
        Ok(Message::HandshakeError(err)) => {
            godot_error!(
                "[Stage] Handshake rejected by slot {}: {}",
                slot_idx,
                err.message
            );
            self.disconnect_slot(slot_idx);
        }
        Err(codec::CodecError::Io(ref e))
            if e.kind() == ErrorKind::WouldBlock || e.kind() == ErrorKind::TimedOut => {}
        Err(codec::CodecError::Io(ref e))
            if e.kind() == ErrorKind::UnexpectedEof
                || e.kind() == ErrorKind::ConnectionReset =>
        {
            godot_print!("[Stage] Slot {} disconnected during handshake", slot_idx);
            self.disconnect_slot(slot_idx);
        }
        Err(e) => {
            godot_error!("[Stage] Handshake read error on slot {}: {}", slot_idx, e);
            self.disconnect_slot(slot_idx);
        }
        Ok(_) => {
            godot_error!(
                "[Stage] Unexpected message before handshake on slot {}",
                slot_idx
            );
            self.disconnect_slot(slot_idx);
        }
    }
}

fn try_read_query(&mut self, slot_idx: usize) -> bool {
    let result = match self.clients.get_mut(slot_idx).and_then(|s| s.as_mut()) {
        Some(slot) => with_blocking_io(&mut slot.stream, |s| {
            s.set_read_timeout(Some(std::time::Duration::from_millis(1)))
                .ok();
            codec::read_message::<Message>(s)
        }),
        None => return false,
    };

    match result {
        Ok(msg) => {
            if let Some(Some(slot)) = self.clients.get_mut(slot_idx) {
                slot.last_activity_at = Some(std::time::Instant::now());
            }
            self.handle_query_message(slot_idx, msg);
            true
        }
        Err(codec::CodecError::Io(ref e))
            if e.kind() == ErrorKind::WouldBlock || e.kind() == ErrorKind::TimedOut =>
        {
            false
        }
        Err(codec::CodecError::Io(ref e))
            if e.kind() == ErrorKind::UnexpectedEof
                || e.kind() == ErrorKind::ConnectionReset =>
        {
            godot_print!("[Stage] Client in slot {} disconnected", slot_idx);
            self.disconnect_slot(slot_idx);
            false
        }
        Err(e) => {
            godot_error!("[Stage] Read error on slot {}: {}", slot_idx, e);
            self.disconnect_slot(slot_idx);
            false
        }
    }
}

fn handle_query_message(&mut self, slot_idx: usize, msg: Message) {
    match msg {
        Message::Query {
            request_id,
            method,
            params,
        } => {
            if method == "execute_action" && self.pending_action.is_some() {
                self.send_response_to_slot(
                    slot_idx,
                    Message::Error {
                        request_id,
                        code: "action_in_progress".into(),
                        message: "Another action owns physics-frame advancement; retry after it completes.".into(),
                    },
                );
                return;
            }
            if method.starts_with("recording_") || method.starts_with("dashcam_") {
                let response_msg = if let Some(ref mut recorder) = self.recorder {
                    match crate::recording_handler::handle_recording_query(
                        recorder, &method, &params,
                    ) {
                        Ok(data) => Message::Response { request_id, data },
                        Err((code, message)) => Message::Error {
                            request_id,
                            code,
                            message,
                        },
                    }
                } else {
                    Message::Error {
                        request_id,
                        code: "internal_error".to_string(),
                        message: "Recorder not available".to_string(),
                    }
                };
                self.send_response_to_slot(slot_idx, response_msg);
            } else if let Some(ref collector) = self.collector {
                let response = crate::query_handler::handle_query(
                    request_id,
                    &method,
                    params,
                    &collector.bind(),
                    self.runtime_logger.as_ref(),
                );
                match response {
                    Some(msg) => self.send_response_to_slot(slot_idx, msg),
                    // Deferred action: transfer validated state into the one
                    // TCP-owned lifecycle before returning to the poll loop.
                    None => self.sync_deferred_action_from_collector(slot_idx),
                }
            } else {
                self.send_response_to_slot(
                    slot_idx,
                    Message::Error {
                        request_id,
                        code: "scene_not_loaded".to_string(),
                        message: "Collector not available".to_string(),
                    },
                );
            }
        }
        Message::Event { event, data } if event == "activity_log" => {
            let entry_type = data
                .get("entry_type")
                .and_then(|v| v.as_str())
                .unwrap_or("query")
                .to_string();
            let summary = data
                .get("summary")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string();
            let tool_name = data
                .get("tool")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string();
            let active_watches: i64 = data
                .get("meta")
                .and_then(|m| m.get("active_watches"))
                .and_then(|v| v.as_i64())
                .unwrap_or(-1);
            self.base_mut().emit_signal(
                "activity_received",
                &[
                    GString::from(entry_type.as_str()).to_variant(),
                    GString::from(summary.as_str()).to_variant(),
                    GString::from(tool_name.as_str()).to_variant(),
                    active_watches.to_variant(),
                ],
            );
        }
        _ => {
            godot_print!(
                "[Stage] Received unhandled message type on slot {}",
                slot_idx

fn disconnect_slot(&mut self, slot_idx: usize) {
    if slot_idx < self.clients.len() {
        self.clients[slot_idx] = None;
    }
    // Owner loss cancels the whole deferred lifecycle. For sequences this
    // also releases only sequence-owned presses and restores pause.
    if self.pending_action.as_ref().map(PendingAction::slot_idx) == Some(slot_idx) {
        self.cancel_pending_action();
        godot_print!(
            "[Stage] Slot {} disconnected during deferred action — action cancelled",
            slot_idx
        );
    }
}

fn check_idle_timeout(&mut self, slot_idx: usize) {
    if self.client_idle_timeout_secs == 0 {
        return;
    }
    let timed_out = self
        .clients
        .get(slot_idx)
        .and_then(|s| s.as_ref())
        .and_then(|slot| slot.last_activity_at)
        .map(|last| last.elapsed().as_secs() > self.client_idle_timeout_secs)
        .unwrap_or(false);
    if timed_out {
        godot_print!(
            "[Stage] Slot {} idle timeout — dropping zombie connection",
            slot_idx
        );
        self.disconnect_slot(slot_idx);
    }
}

fn set_scene_paused(&self, paused: bool) {
    if let Some(mut tree) = self.base().get_tree_or_null() {
        tree.set_pause(paused);
    }
}

fn get_godot_version(&self) -> String {
    let info = godot::classes::Engine::singleton().get_version_info();
    let major = info
        .get("major")
        .and_then(|v| v.try_to::<i32>().ok())
        .unwrap_or(0);
    let minor = info
        .get("minor")
        .and_then(|v| v.try_to::<i32>().ok())
        .unwrap_or(0);
    format!("{}.{}", major, minor)
}

fn detect_scene_dimensions(&self) -> u32 {
    let Some(tree) = self.base().get_tree_or_null() else {
        return 3;
    };
    let Some(root) = tree.get_current_scene() else {
        return 3;
    };
    let root_node: godot::obj::Gd<godot::classes::Node> = root.upcast();

    let has_2d = Self::has_node_type_recursive(&root_node, true);
    let has_3d = Self::has_node_type_recursive(&root_node, false);

    match (has_2d, has_3d) {
        (true, false) => 2,
        (false, true) => 3,
        (true, true) => 0,   // mixed
        (false, false) => 3, // default to 3D if no spatial nodes
    }
}

fn has_node_type_recursive(
    node: &godot::obj::Gd<godot::classes::Node>,
    check_2d: bool,
) -> bool {
    if check_2d {
        if node.clone().try_cast::<godot::classes::Node2D>().is_ok() {
            return true;
        }
    } else if node.clone().try_cast::<godot::classes::Node3D>().is_ok() {
        return true;
    }
    let count = node.get_child_count();
    for i in 0..count {
        if let Some(child) = node.get_child(i)
            && Self::has_node_type_recursive(&child, check_2d)
        {
            return true;
        }
    }
    false
}

