pub fn capture(
    tree: Option<Gd<SceneTree>>,
    params: &ViewportParams,
) -> Result<ViewportCapture, String> {
    let mut metadata = ViewportMetadata {
        identity: crate::runtime_identity::identity().clone(),
        readback_physics_frame: Engine::singleton().get_physics_frames(),
        frames_drawn: Engine::singleton().get_frames_drawn() as u64,
        timestamp_ms: Time::singleton().get_ticks_msec(),
        availability: ViewportAvailability::Unavailable {
            reason: ViewportUnavailableReason::NoViewport,
        },
    };
    let unavailable = |mut metadata: ViewportMetadata, reason| {
        metadata.availability = ViewportAvailability::Unavailable { reason };
        ViewportCapture {
            metadata,
            image_base64: None,
        }
    };
    // The headless renderer has no texture pixels; do not ask its dummy texture
    // backend to read back an invalid render target.
    if DisplayServer::singleton().get_name() == "headless" {
        return Ok(unavailable(metadata, ViewportUnavailableReason::Headless));
    }
    let Some(tree) = tree else {
        return Ok(unavailable(metadata, ViewportUnavailableReason::NoViewport));
    };
    let viewport = tree.get_root();
    let Some(texture) = viewport.get_texture() else {
        return Ok(unavailable(metadata, ViewportUnavailableReason::NoViewport));
    };
    let Some(mut image) = texture.get_image() else {
        return Ok(unavailable(
            metadata,
            ViewportUnavailableReason::EmptyPixels,
        ));
    };
    if image.is_empty() || image.get_width() <= 0 || image.get_height() <= 0 {
        return Ok(unavailable(
            metadata,
            ViewportUnavailableReason::EmptyPixels,
        ));
    }
    let source_width = image.get_width() as u32;
    let source_height = image.get_height() as u32;
    let scale = (params.max_dimension as f64 / source_width.max(source_height) as f64).min(1.0);
    let width = ((source_width as f64 * scale).round() as u32).max(1);
    let height = ((source_height as f64 * scale).round() as u32).max(1);
    if width != source_width || height != source_height {
        image.resize(width as i32, height as i32);
    }
    let jpeg = image.save_jpg_to_buffer_ex().quality(0.8).done();
    if jpeg.is_empty() {
        return Err("Godot could not encode the viewport as JPEG".into());
    }
    metadata.availability = ViewportAvailability::Available {
        width,
        height,
        source_width,
        source_height,
    };
    Ok(ViewportCapture {
        metadata,
        image_base64: Some(Marshalls::singleton().raw_to_base64(&jpeg).to_string()),
    })
}

#[derive(GodotClass)]
#[class(base=Node)]
pub struct OcpRuntimeBridge {
    base: Base<Node>,
    inbox: Option<Receiver<Inbound>>,
    outbox: Option<Sender<Envelope>>,
    connected: bool,
    /// I7 V1 slice 4b: `speech-completed` is no longer faked at dispatch time —
    /// it fires when GDScript reports playback done. This maps each in-flight
    /// `speechId` to its causing `speech-requested` envelope id so the deferred
    /// outcome stays correlated (NFR-004). Cleared on completion.
    pending_speech: std::collections::HashMap<uuid::Uuid, uuid::Uuid>,
    /// I8A slice 1: `animation-completed` is likewise no longer faked at
    /// dispatch — it fires when GDScript reports the animation actually ended.
    /// `animation-requested` carries no per-request id (unlike `speechId`), so
    /// the bridge mints an **animation instance token** per request, passes it
    /// to the signal, and maps it here to the causing envelope id for the
    /// deferred, correlated `animation-completed`. Cleared on completion.
    pending_animation: std::collections::HashMap<uuid::Uuid, uuid::Uuid>,
    /// I8A slice 2b: `emotion-presented`'s `expressionSet`/`fallback` are no
    /// longer hardcoded at dispatch — only GDScript (the Expression module,
    /// RFC-0008 §4.1) knows which expression it actually rendered. Same
    /// instance-token bridge as animations: mint per emotion-changed, map to
    /// the cause envelope, emit the honest outcome on GDScript's report.
    pending_emotion: std::collections::HashMap<uuid::Uuid, uuid::Uuid>,
    /// G8 opt-in render-host lifecycle. This bridge only reports lifecycle;
    /// native HWND ownership remains outside Godot until production G8 passes.
    render_host_attached: bool,
    worker_stop: Arc<AtomicBool>,
    worker_threads: Vec<thread::JoinHandle<()>>,
    resource_system: System,
    credential_broker: Option<credential_broker::CredentialBroker>,
    voice_vad: VoiceActivityDetector,
}

pub fn load_and_start(
    host: Arc<Mutex<PluginHost>>,
    plugin_id: &str,
    wasm: &[u8],
    cfg: &EngineConfig,
) -> Result<RunOutcome, EngineError> {
    if host.lock().expect("host lock").state(plugin_id) != Some(PluginState::Active) {
        return Err(EngineError::NotActive);
    }

    let mut wt_config = Config::new();
    wt_config.consume_fuel(true);
    let engine = WasmEngine::new(&wt_config).map_err(|e| EngineError::Runtime(e.to_string()))?;

    let module = match Module::new(&engine, wasm) {
        Ok(m) => m,
        Err(e) => {
            let _ = host.lock().expect("host lock").reject(
                plugin_id,
                "abi: module failed to compile",
                None,
            );
            return Err(EngineError::Compile(e.to_string()));
        }
    };

    for name in REQUIRED_EXPORTS {
        if module.get_export(name).is_none() {
            let _ = host.lock().expect("host lock").reject(
                plugin_id,
                &format!("abi: missing export {name}"),
                None,
            );
            return Err(EngineError::MissingExport(name.to_owned()));
        }
    }

    let mut linker: Linker<GuestState> = Linker::new(&engine);
    // WASI preview1 (ABI §1 target wasm32-wasip1). No preopens/env/stdio in
    // the alpha; per-grant preopens land with the fs slice (SEC-005).
    p1::add_to_linker_sync(&mut linker, |s: &mut GuestState| &mut s.wasi)
        .map_err(|e| EngineError::Runtime(e.to_string()))?;
    add_ocp_imports(&mut linker)?;

    let state = GuestState {
        host: host.clone(),
        plugin_id: plugin_id.to_owned(),
        limits: StoreLimitsBuilder::new()
            .memory_size(cfg.max_memory_bytes)
            .build(),
        wasi: WasiCtxBuilder::new().build_p1(),
    };
    let mut store = Store::new(&engine, state);
    store.limiter(|s| &mut s.limits);
    // Instantiation (data/memory init) is fueled separately from the guest's
    // run quota — SEC-004 governs execution, not loading.
    const INSTANTIATION_FUEL: u64 = 1_000_000_000;
    store
        .set_fuel(INSTANTIATION_FUEL)
        .map_err(|e| EngineError::Runtime(e.to_string()))?;

    let instance = match linker.instantiate(&mut store, &module) {
        Ok(i) => i,
        Err(e) => {
            let _ = host.lock().expect("host lock").reject(
                plugin_id,
                "abi: instantiation failed (unknown import?)",
                None,
            );
            return Err(EngineError::Runtime(e.to_string()));
        }
    };

    let abi_fn = instance
        .get_typed_func::<(), i32>(&mut store, "ocp_abi_version")
        .map_err(|e| EngineError::Runtime(e.to_string()))?;
    match abi_fn.call(&mut store, ()) {
        Ok(v) if v == ABI_VERSION => {}
        Ok(v) => {
            let _ = host.lock().expect("host lock").reject(
                plugin_id,
                &format!("abi: unsupported version {v}"),
                None,
            );
            return Err(EngineError::AbiMismatch(v));
        }
        Err(_) => {
            let _ = host
                .lock()
                .expect("host lock")
                .report_crash(plugin_id, None);
            return Ok(RunOutcome::Crashed);
        }
    }

    let start = instance
        .get_typed_func::<(), i32>(&mut store, "ocp_start")
        .map_err(|e| EngineError::Runtime(e.to_string()))?;
    // The run quota starts here (SEC-004).
    store
        .set_fuel(cfg.fuel)
        .map_err(|e| EngineError::Runtime(e.to_string()))?;
    match start.call(&mut store, ()) {
        Ok(rc) => Ok(RunOutcome::Completed(rc)),
        Err(_trap) => {
            // Fuel/OOM/unreachable: contained; the plugin dies, the host does not.
            let _ = host
                .lock()
                .expect("host lock")
                .report_crash(plugin_id, None);
            Ok(RunOutcome::Crashed)
        }
    }
}

