impl GrpcChannel {
    fn build(uri: &str) -> Option<Gd<GrpcChannel>> {
        match transport::connect_lazy(uri) {
            Ok(channel) => Some(Gd::from_init_fn(|base| GrpcChannel { channel, base })),
            Err(e) => {
                godot_error!("[godot-grpc] invalid endpoint {uri:?}: {e}");
