    }
}

struct Begun {
    id: u64,
    call: Gd<GrpcCall>,
    sender: Sender<PumpEvent>,
    handle: tokio::runtime::Handle,
}

fn begin(input: OptMsgDesc, output: OptMsgDesc) -> Result<Begun, Gd<GrpcCall>> {
    let id = bridge::next_call_id();
    let call = GrpcCall::create(id, input, output);
    bridge::register(id, call.clone());
    let sender = bridge::sender();
    match runtime::handle() {
        Some(handle) => Ok(Begun {
            id,
            call,
            sender,
            handle,
        }),
        None => {
            let _ = sender.send(PumpEvent::Failed {
                call_id: id,
                code: i32::from(Code::Unavailable) as i64,
                message: "godot-grpc Tokio runtime is not running".into(),
            });
            Err(call)
        }
    }
}

fn spawn_and_attach<F>(begun: Begun, task: impl FnOnce(u64, Sender<PumpEvent>) -> F) -> Gd<GrpcCall>
where
    F: std::future::Future<Output = ()> + Send + 'static,
{
    let Begun {
        id,
        mut call,
        sender,
        handle,
    } = begun;
    let join = handle.spawn(task(id, sender));
    call.bind_mut().set_abort(join.abort_handle());
    call
}

pub(crate) fn start_unary(
    channel: Channel,
    path: &str,
    request: Vec<u8>,
    output: OptMsgDesc,
) -> Gd<GrpcCall> {
    let begun = match begin(Default::default(), output) {
        Ok(b) => b,
        Err(call) => return call,
    };
    let path = match parse_path(&begun, path) {
        Ok(p) => p,
        Err(()) => return begun.call,
    };
    spawn_and_attach(begun, move |id, sender| async move {
        let event = match transport::unary(channel, path, request).await {
            Ok(bytes) => PumpEvent::Completed { call_id: id, bytes },
            Err(status) => fail(id, &status),
        };
        let _ = sender.send(event);
    })
}

pub(crate) fn start_server_stream(
    channel: Channel,
    path: &str,
    request: Vec<u8>,
    output: OptMsgDesc,
) -> Gd<GrpcCall> {
    let begun = match begin(Default::default(), output) {
        Ok(b) => b,
        Err(call) => return call,
    };
    let path = match parse_path(&begun, path) {
        Ok(p) => p,
        Err(()) => return begun.call,
    };
    spawn_and_attach(begun, move |id, sender| async move {
        match transport::open_server_stream(channel, path, request).await {
            Ok(stream) => pump_stream(id, &sender, stream).await,
            Err(status) => {
                let _ = sender.send(fail(id, &status));
            }
        }
    })
}

pub(crate) fn start_client_stream(
    channel: Channel,
    path: &str,
    input: OptMsgDesc,
    output: OptMsgDesc,
) -> Gd<GrpcCall> {
    let mut begun = match begin(input, output) {
        Ok(b) => b,
        Err(call) => return call,
    };
    let path = match parse_path(&begun, path) {
        Ok(p) => p,
        Err(()) => return begun.call,
    };
    let requests = attach_outbound(&mut begun.call);
    spawn_and_attach(begun, move |id, sender| async move {
        let event = match transport::client_streaming(channel, path, requests).await {
            Ok(bytes) => PumpEvent::Completed { call_id: id, bytes },
            Err(status) => fail(id, &status),
        };
        let _ = sender.send(event);
    })
}

pub(crate) fn start_bidi(
    channel: Channel,
    path: &str,
    input: OptMsgDesc,
    output: OptMsgDesc,
) -> Gd<GrpcCall> {
    let mut begun = match begin(input, output) {
        Ok(b) => b,
        Err(call) => return call,
    };
    let path = match parse_path(&begun, path) {
        Ok(p) => p,
        Err(()) => return begun.call,
    };
    let requests = attach_outbound(&mut begun.call);
    spawn_and_attach(begun, move |id, sender| async move {
        match transport::open_bidi_stream(channel, path, requests).await {
            Ok(stream) => pump_stream(id, &sender, stream).await,
            Err(status) => {
                let _ = sender.send(fail(id, &status));
            }
        }
    })
}

fn attach_outbound(call: &mut Gd<GrpcCall>) -> UnboundedReceiverStream<Vec<u8>> {
    let (tx, rx) = unbounded_channel::<Vec<u8>>();
    call.bind_mut().set_outbound(tx);
    UnboundedReceiverStream::new(rx)
}

fn variant_to_message(md: &MessageDescriptor, v: &Variant) -> Result<DynamicMessage, String> {
    if let Ok(gd) = v.try_to::<Gd<GrpcMessage>>() {
        match gd.bind().dynamic() {
            Some(dm) => Ok(dm.clone()),
            None => Err("GrpcMessage has no bound type".to_string()),
        }
    } else if let Ok(dict) = v.try_to::<VarDictionary>() {
        dict_to_message(md.clone(), &dict)
    } else {
        Err(format!(
            "field expects a Dictionary or GrpcMessage ({})",
            md.full_name()
        ))
    }
}

#[derive(GodotClass)]
#[class(init, base = RefCounted)]
pub struct GrpcDescriptorPool {
    pool: Option<DescriptorPool>,
    base: Base<RefCounted>,
}

#[godot_api]
impl GrpcDescriptorPool {
    /// Load a serialized `FileDescriptorSet` from raw bytes. Returns false (and
    /// logs) on parse failure.
    #[func]
    fn load_bytes(&mut self, bytes: PackedByteArray) -> bool {
        match DescriptorPool::decode(bytes.as_slice()) {
            Ok(pool) => {
                self.pool = Some(pool);
                true
            }
            Err(e) => {
                godot_error!("[godot-grpc] failed to parse descriptor set: {e}");
                false
            }
        }
    }

    /// Load a `FileDescriptorSet` from a Godot resource path (e.g.
    /// `"res://protos/helloworld.descriptor.bin"`). Returns false on failure.
    #[func]
    fn load_file(&mut self, res_path: GString) -> bool {
        let bytes = FileAccess::get_file_as_bytes(&res_path);
        if bytes.is_empty() {
            godot_error!("[godot-grpc] could not read descriptor file {res_path}");
            return false;
        }
        self.load_bytes(bytes)
    }

    /// Look up a service by its fully-qualified name (e.g.
    /// `"helloworld.Greeter"`). Returns `null` if not loaded or not found.
    #[func]
    fn service(&self, full_name: GString) -> Option<Gd<GrpcServiceStub>> {
        let name = full_name.to_string();
        let Some(pool) = self.pool.as_ref() else {
            godot_error!("[godot-grpc] descriptor pool is empty; call load_file/load_bytes first");
            return None;
        };
        match pool.get_service_by_name(&name) {
            Some(svc) => Some(GrpcServiceStub::create(svc)),
            None => {
                godot_error!("[godot-grpc] service {name:?} not found in descriptor pool");
                None
            }
        }
    }
}

#[godot_api]
impl GrpcStatus {
    /// The numeric gRPC status code (0 = OK, 1 = CANCELLED, ... 16 = UNAUTHENTICATED).
    #[func]
    pub fn code(&self) -> i64 {
        self.code
    }

    /// The status message returned by the server (may be empty).
    #[func]
    pub fn message(&self) -> GString {
        self.message.clone()
    }

    /// A static human-readable description of the status code.
    #[func]
    pub fn description(&self) -> GString {
        tonic::Code::from(self.code as i32).description().into()
    }

    /// Whether this status represents success (code == 0).
    #[func]
    pub fn is_ok(&self) -> bool {
        self.code == 0
    }
}

#[allow(dead_code)]
impl GrpcStatus {
    /// Build a `GrpcStatus` object from a `tonic::Status`.
    pub(crate) fn from_tonic(status: &Status) -> Gd<Self> {
        Self::create(i32::from(status.code()) as i64, status.message())
    }

    /// Build a `GrpcStatus` object from a raw code and message.
    pub(crate) fn create(code: i64, message: &str) -> Gd<Self> {
        let message = GString::from(message);
        Gd::from_init_fn(|base| GrpcStatus {
            code,
            message,
            base,
        })
    }
}

#[godot_api]
impl GrpcError {
    /// The gRPC status underlying this error.
    #[func]
    pub fn status(&self) -> Gd<GrpcStatus> {
        self.status.clone()
    }

    /// The status message, for convenience (`status().message()`).
    #[func]
    pub fn message(&self) -> GString {
        self.status.bind().message()
    }

    /// The full Rust-side cause chain (empty if none).
    #[func]
    pub fn cause(&self) -> GString {
        self.cause.clone()
    }
}

#[allow(dead_code)]
impl GrpcError {
    /// Build a `GrpcError` from a `tonic::Status`, capturing its source chain.
    pub(crate) fn from_tonic(status: &Status) -> Gd<Self> {
        let mut cause = String::new();
        let mut src = std::error::Error::source(status);
        while let Some(e) = src {
            if !cause.is_empty() {
                cause.push_str(": ");
            }
            cause.push_str(&e.to_string());
            src = e.source();
        }
        let status = GrpcStatus::from_tonic(status);
        Gd::from_init_fn(|base| GrpcError {
            status,
            cause: GString::from(&cause),
            base,
        })
    }

    /// Build a `GrpcError` from a transport/connection-level error (no gRPC status).
    pub(crate) fn from_transport(code: tonic::Code, err: impl std::fmt::Display) -> Gd<Self> {
        let msg = err.to_string();
        let status = GrpcStatus::create(i32::from(code) as i64, &msg);
        Gd::from_init_fn(|base| GrpcError {
            status,
            cause: GString::from(&msg),
            base,
        })
    }
}

