fn shader(code: &str, shared: bool) -> Gd<Shader> {
    let make = || {
        let mut shader = Shader::new_gd();
        shader.set_code(code);
        shader
    };
    if !shared {
        return make();
    }
    SHADERS.with_borrow_mut(|cache| cache.entry(code.to_string()).or_insert_with(make).clone())
}

pub struct Built {
    pub material: Gd<ShaderMaterial>,
    pub warnings: Vec<String>,
}

pub fn build(
    out: &GdshaderOutput,
    location: Option<&str>,
    strict_textures: bool,
    shared_shader: bool,
    texture: impl Fn(&str) -> Result<Gd<Texture2D>, String>,
) -> Result<Built, String> {
    let mut material = ShaderMaterial::new_gd();
    material.set_shader(&shader(&out.code, shared_shader));
    for (uniform, name) in out.reflection.uniforms.iter().zip(&out.uniform_names) {
        material.set_shader_parameter(name.as_str(), &variant(&uniform.default));
    }
    let mut warnings = out.reflection.approximations.clone();
    for t in &out.reflection.textures {
        match reference(location, &t.file).and_then(|path| texture(&path)) {
            Ok(texture) => material.set_shader_parameter(&format!("shadewire_t{}", t.index), &texture.to_variant()),
            Err(e) if strict_textures => return Err(e),
            Err(e) => warnings.push(format!("texture {}: {e}", t.file)),
        }
    }
    let mut reflection = serde_json::to_value(&out.reflection).map_err(|e| e.to_string())?;
    reflection["approximations"] = serde_json::json!(warnings);
    material.set_meta("shadewire_reflection", &Json::parse_string(&reflection.to_string()));
    Ok(Built { material, warnings })
}

pub fn load_text(
    text: &str,
    location: Option<&str>,
    options: &LoadOptions,
    budget: Arc<Budget>,
) -> Result<Gd<ShaderMaterial>, String> {
    let out = compile(text, location, options, resolver(budget.clone()))?;
    let pixels = options.limits.max_texture_pixels;
    let built = build(&out, location, options.strict_textures, true, |path| load_texture(path, &budget, pixels))?;
    Ok(warn(built, location.unwrap_or("<string>")))
}

fn warn(built: Built, name: &str) -> Gd<ShaderMaterial> {
    for warning in built.warnings {
        godot_warn!("shadewire: {name}: {warning}");
    }
    built.material
}

pub fn load_path(path: &str, options: &LoadOptions) -> Result<Gd<ShaderMaterial>, String> {
    let budget = Budget::new(options.limits.max_material_bytes);
    let text = read_text(path, &budget)?;
    load_text(&text, Some(path), options, budget)
}

fn finish_fetched(fetched: Box<Fetched>) -> Result<Gd<ShaderMaterial>, String> {
    let Fetched { out, location, options, textures, budget } = *fetched;
    let pixels = options.limits.max_texture_pixels;
    let texture = |path: &str| match textures.get(path) {
        Some(Ok(bytes)) => texture_from_bytes(path, &PackedByteArray::from(bytes.as_slice()), pixels),
        Some(Err(e)) => Err(e.clone()),
        None => load_texture(path, &budget, pixels),
    };
    let built = build(&out, Some(&location), options.strict_textures, true, texture)?;
    Ok(warn(built, &location))
}

#[derive(GodotClass)]
#[class(base=RefCounted)]
pub struct Shadewire {
    base: Base<RefCounted>,
    last_error: GString,
    /// `func(url: String) -> PackedStringArray`: extra `Name: value` headers for each request (signed URLs,
    /// short-lived tokens), added after the `set_http_headers` ones. Called on the main thread.
    #[var]
    http_headers_callback: Callable,
    /// Where the disk cache lives (default `user://shadewire_cache`). Objects sharing a directory share its cache.
    #[var]
    cache_dir: GString,
    /// The disk cache's cap in bytes (default 256 MiB); lowering it evicts least recently used entries, 0 turns the
    /// cache off. It belongs to the directory: every object using it sees the same cap.
    #[var(get = get_cache_max_bytes, set = set_cache_max_bytes)]
    cache_max_bytes: PhantomVar<i64>,
    rules: HeaderRules,
    requests: HashMap<i64, Arc<AtomicBool>>,
    next_id: i64,
    sender: Sender<Event>,
    receiver: Receiver<Event>,
}

impl Shadewire {
    fn finish<T>(&mut self, result: Result<T, String>) -> Option<T> {
        match result {
            Ok(value) => {
                self.last_error = GString::new();
                Some(value)
            }
            Err(e) => {
                self.last_error = e.as_str().into();
                None
            }
        }
    }

    fn cache(&self) -> SharedCache {
        let dir = ProjectSettings::singleton().globalize_path(&self.cache_dir).to_string();
        cache::shared(std::path::Path::new(&dir), DEFAULT_MAX_BYTES)
    }

    fn with_cache<T>(&self, f: impl FnOnce(&mut cache::DiskCache) -> T) -> T {
        f(&mut self.cache().lock().unwrap_or_else(|e| e.into_inner()))
    }

    /// Events are drained once per frame, from the scene tree's `process_frame`, while requests are pending.
    fn poll_while_pending(&mut self) -> Result<(), String> {
        let tree = Engine::singleton().get_main_loop().and_then(|l| l.try_cast::<SceneTree>().ok());
        let mut tree = tree.ok_or("load_material_async needs a SceneTree main loop")?;
        let callable = Callable::from_object_method(&self.to_gd(), POLL);
        if self.requests.is_empty() {
            if tree.is_connected("process_frame", &callable) {
                tree.disconnect("process_frame", &callable);
            }
        } else if !tree.is_connected("process_frame", &callable) {
            tree.connect("process_frame", &callable);
        }
        Ok(())
    }
}

fn scene(&mut self, name: &str, p: &Params, ret: &Ty, origin: &str) -> Result<Val, String> {
    if name == "data_isvalid" {
        return Ok(Val::bool(false));
    }
    let property = p.at(0).str().unwrap_or_default().to_string();
    let default = p.at(1).clone();
    let Some(ir) = ret.ir() else {
        self.warn(format!("scene::{name}(\"{property}\"): its default"));
        return Ok(default);
    };
    let value = match default.known_value() {
        Some(v) => NodeArg::Value(v.clone()),
        None => {
            self.warn(format!("scene::{name}(\"{property}\"): a varying default read as zero"));
            NodeArg::Value(Value::zero(ir))
        }
    };
    let inputs = [("geomprop", NodeArg::Text(property)), ("default", value)];
    let id = self.e.instantiate("geompropvalue", ir, &inputs, origin).map_err(|e| e.to_string())?;
    Ok(Val::node(ret.clone(), id))
}

fn sample(&mut self, t: &Texture, coord: &Val, wrap_u: &Val, wrap_v: &Val, origin: &str) -> R<Num> {
    let coord = Self::n(coord)?;
    let uv = self.node_of(&coord, origin);
    let inputs = [
        ("file", NodeArg::File { path: t.file.clone(), colorspace: colorspace(t) }),
        ("uaddressmode", NodeArg::Text(address(wrap_u).to_string())),
        ("vaddressmode", NodeArg::Text(address(wrap_v).to_string())),
        ("filtertype", NodeArg::Text("linear".to_string())),
        ("texcoord", NodeArg::Node(uv)),
    ];
    let id = self.e.instantiate("image", Type::Color4, &inputs, origin).map_err(|e| e.to_string())?;
    Ok(Num::Node(id))
}

pub fn instantiate(
    &mut self,
    category: &str,
    out: Type,
    inputs: &[(&str, Arg)],
    origin: &str,
) -> Result<NodeId, Error> {
    self.instantiate_node(category, PortType::Value(out), inputs, None, origin)
}

pub fn instantiate_output(
    &mut self,
    category: &str,
    output: &str,
    inputs: &[(&str, Arg)],
    origin: &str,
) -> Result<NodeId, Error> {
    self.instantiate_node(category, PortType::MultiOutput, inputs, Some(output), origin)
}

fn instantiate_node(
    &mut self,
    category: &str,
    port_type: PortType,
    inputs: &[(&str, Arg)],
    output: Option<&str>,
    origin: &str,
) -> Result<NodeId, Error> {
    let origin = self.unique_origin(origin);
    let origin = origin.as_str();
    let at = Location { file: None, line: 0, path: origin.to_string(), source: None };
    let Some(synthetic) = self.synthetic else {
        return Err(Error::BadValue { at, message: "instantiate needs Elaborator::standalone".to_string() });
    };
    let (doc_inputs, interface) = self.bind_args(inputs, origin);
    let node = synthetic.node(Node {
        category: category.to_string(),
        name: origin.to_string(),
        port_type,
        nodedef: None,
        version: None,
        inputs: doc_inputs,
        line: 0,
        source: None,
    });
    let scope = self.synthetic_scope(&[], interface);
    let id = self.instance(&scope, node, output, &at)?;
    self.check_node_limit()?;
    Ok(id)
}

