fn project_references<'a>(
    document: &'a Document,
    session: &'a ProjectSession,
) -> impl Iterator<Item = PathBuf> + 'a {
    let base = document.module().map(|m| m.base().path.clone());
    let modules = crate::dress_up::modules(session)
        .into_iter()
        .map(|m| PathBuf::from(m.path));
    let psd = session.proposals.psd().map(Path::to_path_buf);
    base.into_iter().chain(modules).chain(psd)
}

impl PreviewBaseCache {
    /// 開いているモジュールのプロジェクトの本体だけの `.ugoe`。覚えているものが使えればそれを返す。
    fn bundle(&self, document: &Document, session: &ProjectSession) -> IpcResult<Arc<[u8]>> {
        let context = document.module().ok_or(EditorError::NotAModule)?;
        let revision = context.base_revision();
        let file = session
            .base_digest()
            .map(|digest| (context.base().path.clone(), digest));
        let mut cached = self.0.lock().map_err(|_| EditorError::LockPoisoned {
            what: "preview cache",
        })?;
        if let Some(entry) = cached.as_mut()
            && (entry.revision == revision || (file.is_some() && entry.file == file))
        {
            entry.revision = revision;
            return Ok(entry.bytes.clone());
        }
        let bytes: Arc<[u8]> =
            ugoe_editor_core::export_base_bundle(&session.to_project(document))?.into();
        *cached = Some(CachedBase {
            revision,
            file,
            bytes: bytes.clone(),
        });
        Ok(bytes)
    }
}

fn rebase(
    document: &mut Document,
    session: &mut ProjectSession,
    base: Option<std::path::PathBuf>,
    slot: Option<String>,
) -> IpcResult<BaseReload> {
    let context = document.module().ok_or(EditorError::NotAModule)?.clone();
    let relocated = base.is_some() || slot.is_some();
    let path = base.unwrap_or_else(|| context.base().path.clone());
    let new_slot = slot.map(|s| ugoe_model::SlotId::from(s.as_str()));
    let slot = new_slot
        .as_ref()
        .map_or_else(|| context.slot().id.to_string(), ToString::to_string);
    let result = load_base(&path).and_then(|base| {
        document
            .rebase_module_on(base, new_slot.as_ref())
            .map_err(ProjectError::from)
    });
    let problem = match result {
        Ok(()) => {
            session.remember_base(document);
            if relocated {
                session.mark_meta_modified();
            }
            None
        }
        Err(error) => Some(
            diagnose(&error, &path, &slot).unwrap_or_else(|| ModuleProblem {
                kind: ModuleProblemKind::DoesNotFit,
                base: path.display().to_string(),
                slot: slot.clone(),
                base_slots: Vec::new(),
                error: error.to_message(),
                collider_references: Vec::new(),
            }),
        ),
    };
    Ok(BaseReload {
        status: status(session, document),
        problem,
    })
}

pub(crate) fn base_change(&self, document: &Document) -> IpcResult<Option<ExternalChange>> {
    let (Some(context), Some(known)) = (document.module(), &self.base_disk) else {
        return Ok(None);
    };
    let path = &context.base().path;
    if !path.exists() {
        return Ok(Some(ExternalChange {
            files: Vec::new(),
            missing: true,
            token: "base-missing".into(),
        }));
    }
    match known.reread_base(path) {
        Ok(now) if now == *known => Ok(None),
        Ok(now) => Ok(Some(ExternalChange {
            files: known.changed_files(&now),
            missing: false,
            token: format!("base-{:016x}", now.digest()),
        })),
        Err(ProjectError::NotAProject { .. }) => Ok(Some(ExternalChange {
            files: Vec::new(),
            missing: true,
            token: "base-missing".into(),
        })),
        Err(e) => Err(e.into()),
    }
}

fn base_fingerprint(document: &Document) -> Option<ProjectFingerprint> {
    let path = &document.module()?.base().path;
    ProjectFingerprint::read_base(path)
        .inspect_err(|e| eprintln!("could not fingerprint the base model: {e}"))
        .ok()
}

#[derive(GodotClass)]
#[class(base = Node2D, tool)]
pub(crate) struct UgoePuppet2D {
    /// 表示するモデル (`.ugoe` を `load()` した `UgoeModel`。`data` にバイト列を持つリソース)。
    #[var(set = set_model, hint = RESOURCE_TYPE, hint_string = "UgoeModel", usage_flags = [DEFAULT])]
    model: Option<Gd<Resource>>,
    /// 時間を進めるか。止めている間もパラメータの変更は反映する。
    #[export]
    playing: bool,
    /// 時間の進む速さ。有限で負でない値だけを受け付ける。
    #[export(range = (0.0, 4.0, 0.01, or_greater))]
    #[var(set = set_speed)]
    speed: f32,
    /// エディタの中でも時間を進めるか (目パチ・呼吸・物理)。
    #[export]
    play_in_editor: bool,
    /// マスクのテクスチャの解像度の倍率。1 で画面上の大きさと同じ解像度
    /// (`docs/spec/rendering.md#精度`)。下げると軽くなるが、マスクの縁が粗くなる。画面上の大きさを掛けた解像度は
    /// 1/16〜16 に収め、2^(1/4) 刻みに切り上げて使う (`render::quantize_mask_scale`)。
    #[export(range = (0.1, 4.0, 0.05, or_greater))]
    #[var(set = set_mask_scale)]
    mask_scale: f32,
    /// 取り付ける着せ替えのモジュール (`.ugoemod` を `load()` した `UgoeModule`。合成の順)。
    /// `attach_module` などで変えると、この配列も変わる。
    #[var(set = set_modules, hint = TYPE_STRING, hint_string = "24/17:UgoeModule", usage_flags = [DEFAULT])]
    modules: VarArray,
    /// 環境光 (`docs/spec/rendering.md#ライティング`)。1 を超えてもよい。
    #[export_group(name = "Lighting")]
    #[export]
    #[var(set = set_ambient_light)]
    ambient_light: Color,
    /// 光源。`{ "type": "directional", "direction": Vector3, "color": Color }` か
    /// `{ "type": "point", "position": Vector3, "color": Color, "range": float }` (キャンバス座標 + 奥行き)。
    #[var(set = set_lights, hint = TYPE_STRING, hint_string = "27:", usage_flags = [DEFAULT])]
    lights: VarArray,
    /// シーンの `Light2D` (`PointLight2D`・`DirectionalLight2D`) も光源にするか (`lights` の後ろに足す)。
    /// 同じキャンバスにあり、有効で見えていて、`range_item_cull_mask` がこのノードの `light_mask` と重なるものを使う。
    #[export]
    #[var(set = set_use_scene_lights)]
    use_scene_lights: bool,
    /// フェイストラッキングの入力にする `XRFaceTracker` の名前 (`XRServer` に登録した名前。
    /// 標準は `/user/face_tracker`)。空なら使わない。毎フレーム読み、見つからなければ前の値を保つ。
    #[export_group(name = "Tracking")]
    #[export]
    xr_face_tracker: StringName,
    /// トラッキング中に、再生中のモーションが動かすパラメータではモーションを優先するか
    /// (`docs/spec/motion.md#トラッキング中のモーションの優先`)。既定は false。モデルを読み直しても保つ。
    #[export]
    #[var(set = set_motion_over_tracking)]
    motion_over_tracking: bool,
    /// `motion_over_tracking` でも、トラッキングのままにするパラメータの ID (目など)。モデルに無い ID は無視する。
    /// モデルを読み直しても保つ。
    #[export]
    #[var(set = set_tracking_kept)]
    tracking_kept: PackedStringArray,
    /// 圧縮したチャンク 1 つを展開した後の大きさの上限 (バイト。`docs/spec/file-formats.md#読み込みの上限`)。
    /// 次の読み込み (モデルと着せ替えのモジュール) から効く。負の値は拒む。
    #[export_group(name = "Load limits")]
    #[export]
    #[var(set = set_max_chunk_decompressed)]
    max_chunk_decompressed: i64,
    /// 1 つのファイルで、圧縮したチャンクを展開したバイトの合計の上限。次の読み込みから効く。負の値は拒む。
    #[export]
    #[var(set = set_max_total_decompressed)]
    max_total_decompressed: i64,
    /// テクスチャと法線マップの画像 (PNG・KTX2) の幅と高さそれぞれの上限 (画素)。次の読み込みから効く。
    /// 負の値と 2^32 以上は拒む。
    #[export]
    #[var(set = set_max_image_side)]
    max_image_side: i64,

    loaded: Option<LoadedModel>,
    /// 木の外で `model` を変えたので、木に戻ったときに読み込み直す (`ready` は最初の 1 回しか呼ばれないため)。
    model_pending: bool,
    /// `lights` を読んだもの (読めない要素は除く)。
    manual_lights: Vec<Light>,
    /// シーンの光源のノード (`use_scene_lights` のとき)。
    scene_lights: Vec<Gd<Light2D>>,
    /// 木にノードが足されたか外された (シーンの光源を探し直す)。木の `node_added` と `node_removed` で立てる。
    scene_changed: Rc<Cell<bool>>,
    /// 木の変化を見ている接続 (木から出るときに外す)。
    tree_watch: Option<Callable>,
    /// 光源をシェーダの形に直したもの。
    lighting: LightUniforms,
    /// トラッキングの入力 (モデルを読み直しても保つ)。
    tracking: Option<TrackingInput>,
    /// `update` の各段を動かすか (モデルを読み直しても保つ)。
    toggles: Toggles,
    /// 直前の読み込み (モデルか着せ替えのモジュール) の失敗 (`get_load_error()`)。成功したら空。
    load_error: VarDictionary,
    /// 付けているモジュールのリソースと、読んだ中身 (付け外しで読み直さないため)。
    attached: Vec<(Gd<Resource>, Arc<ModuleData>)>,
    renderer: Option<Renderer>,
    /// インスペクタやスクリプトで設定したパラメータの値 (ID ごと)。
    /// シーンに保存し、読み込み直したときにも当てる。
    parameters: HashMap<Str

fn install(&mut self, mut loaded: LoadedModel) {
    self.unload();
    self.load_error = VarDictionary::new();
    for warning in &loaded.warnings {
        godot_warn!("ugoe: {warning}");
    }
    // 覚えているパラメータを当てる (モデルに無い ID は捨てる)。
    let params = loaded.puppet.instance_mut().parameters_mut();
    self.parameters
        .retain(|id, value| match params.index_of(id) {
            Some(i) => {
                params.set(i, *value);
                true
            }
            None => false,
        });
    loaded.puppet.set_tracking(self.tracking);
    loaded.puppet.set_toggles(self.toggles);
    loaded
        .puppet
        .set_motion_over_tracking(self.motion_over_tracking);
    self.loaded = Some(loaded);
    self.push_tracking_kept();
    let modules = self.module_resources();
    if !modules.is_empty() && !self.apply_modules(modules) {
        godot_warn!("ugoe: showing the model without the modules");
    }
    self.rebuild_renderer(Vec::new());
    self.redraws = 0;
    self.step(0.0);
    self.base_mut().notify_property_list_changed();
    self.signals().model_loaded().emit();
}

fn unload(&mut self) {
    self.model_pending = false;
    if let Some(mut renderer) = self.renderer.take() {
        renderer.remove_viewports();
    }
    if self.loaded.take().is_some() {
        self.base_mut().notify_property_list_changed();
    }
}

fn module_resources(&self) -> Vec<Gd<Resource>> {
    self.modules
        .iter_shared()
        .filter_map(|v| v.try_to::<Gd<Resource>>().ok())
        .collect()
}

fn parse_module(&mut self, resource: &Gd<Resource>) -> Option<Arc<ModuleData>> {
    match self.read_module(resource) {
        Ok(data) => Some(data),
        Err(error) => {
            self.load_error = error;
            None
        }
    }
}

fn read_module(&self, resource: &Gd<Resource>) -> Result<Arc<ModuleData>, VarDictionary> {
    if let Some((_, data)) = self.attached.iter().find(|(r, _)| r == resource) {
        return Ok(Arc::clone(data));
    }
    let path = resource.get_path();
    let Ok(bytes) = resource.get("data").try_to::<PackedByteArray>() else {
        let message = format!("`{path}` is not a UgoeModule (it has no `data`)");
        godot_error!("ugoe: {message}");
        return Err(error_dictionary(DressUpError::INVALID_FILE, &message, []));
    };
    match ModuleData::from_bytes(bytes.as_slice(), self.load_limits()) {
        Ok(data) => {
            for warning in &data.warnings {
                godot_warn!("ugoe: module `{path}`: {warning}");
            }
            Ok(Arc::new(data))
        }
        Err(e) => {
            godot_error!("ugoe: module `{path}`: {e}");
            Err(load_error_dictionary(&e))
        }
    }
}

fn apply_modules(&mut self, list: Vec<Gd<Resource>>) -> bool {
    let mut parsed = Vec::with_capacity(list.len());
    for resource in list {
        let Some(data) = self.parse_module(&resource) else {
            return false;
        };
        parsed.push((resource, data));
    }
    self.apply_parsed_modules(parsed)
}

fn apply_parsed_modules(&mut self, parsed: Vec<(Gd<Resource>, Arc<ModuleData>)>) -> bool {
    if let Some(loaded) = &mut self.loaded {
        let change =
            match loaded.set_modules(parsed.iter().map(|(_, d)| Arc::clone(d)).collect()) {
                Ok(change) => change,
                Err(e) => {
                    godot_error!("ugoe: dress-up failed: {e}");
                    let fields = e.fields().into_iter().map(|(k, v)| (k, field_variant(v)));
                    self.load_error = error_dictionary(e.code(), &e.to_string(), fields);
                    return false;
                }
            };
        self.after_dress_up(&change);
    }
    self.modules = parsed.iter().map(|(r, _)| r.to_variant()).collect();
    self.attached = parsed;
    self.load_error = VarDictionary::new();
    true
}

fn watch_tree(&mut self, on: bool) {
    let Some(mut tree) = self.base().get_tree_or_null() else {
        return;
    };
    if let Some(callable) = self.tree_watch.take() {
        for signal in ["node_added", "node_removed"] {
            if tree.is_connected(signal, &callable) {
                tree.disconnect(signal, &callable);
            }
        }
    }
    if !on {
        return;
    }
    let changed = Rc::clone(&self.scene_changed);
    let callable = Callable::from_linked_fn("ugoe_watch_lights", &self.to_gd(), move |args| {
        let is_light = args
            .first()
            .and_then(|v| v.try_to::<Gd<Node>>().ok())
            .is_some_and(|n| n.is_class("Light2D"));
        if is_light {
            changed.set(true);
        }
    });
    for signal in ["node_added", "node_removed"] {
        tree.connect(signal, &callable);
    }
    self.tree_watch = Some(callable);
    self.scene_changed.set(true);
}

fn find_scene_lights(&mut self) {
    if !self.scene_changed.replace(false) {
        self.scene_lights.retain(|l| l.is_instance_valid());
        return;
    }
    self.scene_lights.clear();
    let Some(viewport) = self.base().get_viewport() else {
        return;
    };
    self.scene_lights = viewport
        .find_children_ex("*")
        .type_("Light2D")
        .owned(false)
        .done()
        .iter_shared()
        .filter_map(|n| n.try_cast::<Light2D>().ok())
        .collect();
}

fn scene_light_values(&self) -> Vec<Light> {
    if !self.use_scene_lights || !self.base().is_inside_tree() {
        return Vec::new();
    }
    let Some(loaded) = &self.loaded else {
        return Vec::new();
    };
    let origin = loaded.model().meta.canvas.origin;
    let base = self.base();
    let canvas = base.get_canvas();
    let mask = base.get_light_mask();
    let editor = Engine::singleton().is_editor_hint();
    let to_local = base.get_global_transform().affine_inverse();
    // 全体の座標の 1 単位あたりの、このノードの座標の単位数 (高さと半径に掛ける)。
    let unit = to_local.determinant().abs().sqrt();
    self.scene_lights
        .iter()
        .filter(|l| {
            l.is_instance_valid()
                && l.is_enabled()
                && l.is_visible_in_tree()
                && (editor || !l.is_editor_only())
                && l.get_item_cull_mask() & mask != 0
                && l.get_canvas() == canvas
        })
        .filter_map(|l| {
            let c = l.get_color() * l.get_energy();
            let color = Rgb::new(c.r, c.g, c.b);
            let xform = l.get_global_transform();
            if l.is_class("DirectionalLight2D") {
                let down = to_local.basis_xform(xform.basis_xform(Vector2::DOWN));
                let direction = directional_from_light2d([down.x, down.y], l.get_height())?;
                return Some(Light::Directional { direction, color });
            }
            let point = l.clone().try_cast::<PointLight2D>().ok()?;
            let p = to_local * xform.origin;
            let range = point.get_texture().map_or(f32::INFINITY, |t| {
                let size = t.get_size();
                let s = xform.scale();
                size.x.max(size.y) / 2.0
                    * point.get_texture_scale()
                    * s.x.abs().max(s.y.abs())
                    * unit
            });
            Some(Light::Point {
                position: [p.x + origin.x, p.y + origin.y, l.get_height() * unit],
                color,
                range,
            })
        })
        .collect()
}

fn read_xr_face_tracker(&mut self) {
    let Some(tracker) = XrServer::singleton().get_tracker(&self.xr_face_tracker) else {
        return;
    };
    let tracker = tracker.upcast::<RefCounted>();
    if tracker.is_class("XRFaceTracker") {
        self.set_tracking_from_xr_face_tracker(tracker);
    }
}

fn step(&mut self, dt: f32) {
    let Some(loaded) = &mut self.loaded else {
        return;
    };
    loaded.puppet.update(dt);
    let events: Vec<(GString, f32, GString, i64)> = loaded
        .puppet
        .motion_events()
        .iter()
        .zip(loaded.puppet.motion_event_sources())
        .map(|(e, source)| {
            (
                GString::from(e.value.as_str()),
                e.t,
                GString::from(source.name.as_str()),
                to_i64(source.number),
            )
        })
        .collect();
    self.draw();
    for (value, time, motion, number) in events {
        self.signals().motion_event().emit(&value);
        self.signals()
            .motion_event_fired()
            .emit(&value, time, &motion, number);
    }
}

fn draw(&mut self) {
    // マスクは画面上の大きさ (ビューポートの画素) に合わせた解像度で描く (Renderer::draw が 2^(1/4) 刻みに丸める)。
    let screen_scale = if self.base().is_inside_tree() {
        let s = self.base().get_global_transform_with_canvas().scale();
        s.x.abs().max(s.y.abs())
    } else {
        1.0
    };
    let mask_scale = self.mask_scale * screen_scale;
    self.dirty = false;
    if let (Some(loaded), Some(renderer)) = (&self.loaded, &mut self.renderer)
        && renderer.draw(loaded, mask_scale)
    {
        self.redraws += 1;
    }
}

struct MaskLevel {
    viewport: Gd<SubViewport>,
    /// ビューポートの中の根。カバレッジのキャンバスアイテムの親の親。
    _root: Gd<Node2D>,
    /// 前の段のアトラスを写すキャンバスアイテム。カバレッジのキャンバスアイテムはこの子 (写した後に描く)。
    copy: Rid,
    _copy_material: Option<Gd<ShaderMaterial>>,
    texture: Gd<ViewportTexture>,
}

struct MaskItem {
    /// マスクとして使うメッシュの番号。
    mesh: usize,
    item: Rid,
    vertices: Option<VertexMesh>,
    material: Gd<ShaderMaterial>,
    area: Option<MaskArea>,
    /// アトラスでの左上の画素。
    slot: (u32, u32),
}

struct DrawItem {
    item: Rid,
    /// 頂点だけを書き換えるメッシュ。`None` なら毎回三角形の配列を足し直す (裏面カリングで頂点番号が変わる要素など)。
    vertices: Option<VertexMesh>,
    material: Gd<ShaderMaterial>,
}

#[derive(Default)]
pub struct DecodedTexture {
    color: Option<Gd<ImageTexture>>,
    normal: Option<Gd<ImageTexture>>,
}

pub struct Renderer {
    container: Rid,
    items: Vec<DrawItem>,
    levels: Vec<MaskLevel>,
    masks: Vec<MaskItem>,
    table: MaskTable,
    table_texture: Option<Gd<ImageTexture>>,
    /// アトラスの大きさ (画素)。
    atlas: (u32, u32),
    textures: TextureCache,
    /// 読み込んでから最初の描画か (すべてを描き直す)。
    fresh: bool,
    /// 描かなかったフレームの変更フラグ。
    pending: PendingChanges,
    /// 直前の描画で使ったマスクの解像度。
    mask_scale: MaskResolution,
    /// アトラスに収まらなかったときに、マスクの解像度に掛ける倍率 (解像度が変わると 1 に戻す)。
    shrink: MaskShrink,
    // 毎フレームの作業用
    points: PackedVector2Array,
    uvs: Vec<PackedVector2Array>,
    indices: Vec<PackedInt32Array>,
    culled: Vec<i32>,
    colors: PackedColorArray,
    names: UniformNames,
}

fn rs() -> Gd<RenderingServer> {
    RenderingServer::singleton()
}

fn make_shader(kind: ShaderKind) -> Gd<Shader> {
    let mut s = Shader::new_gd();
    s.set_code(&shader::source(kind));
    s
}

fn material(shader: &Gd<Shader>) -> Gd<ShaderMaterial> {
    let mut m = ShaderMaterial::new_gd();
    m.set_shader(shader);
    m
}

fn load_image(
    data: &TextureData,
    what: &str,
    pixels: impl FnOnce(&mut [u8]),
) -> Option<Gd<ImageTexture>> {
    let mut image = match decode_image(data.format, &data.bytes) {
        Ok(image) => image,
        Err(error) => {
            godot_warn!(
                "ugoe: failed to decode a {what} ({:?}): {error}",
                data.format
            );
            return None;
        }
    };
    pixels(&mut image.pixels);
    let image = Image::create_from_data(
        i32::try_from(image.width).ok()?,
        i32::try_from(image.height).ok()?,
        false,
        Format::RGBA8,
        &PackedByteArray::from(image.pixels.as_slice()),
    )?;
    ImageTexture::create_from_image(&image)
}

fn load_texture(data: &TextureData) -> Option<Gd<ImageTexture>> {
    load_image(data, "texture", premultiply)
}

fn load_normal_map(data: &TextureData) -> Option<Gd<ImageTexture>> {
    load_image(data, "normal map", |_| {})
}

fn set_mask_params(
    material: &mut Gd<ShaderMaterial>,
    atlas: &Gd<ViewportTexture>,
    table: &Option<Gd<ImageTexture>>,
    first: i32,
    count: usize,
    mode: MaskMode,
) {
    if count == 0 {
        return;
    }
    material.set_shader_parameter("mask_atlas", &atlas.to_variant());
    if let Some(table) = table {
        material.set_shader_parameter("mask_table", &table.to_variant());
    }
    material.set_shader_parameter("mask_first", &first.to_variant());
    material.set_shader_parameter("mask_count", &(count as i32).to_variant());
    material.set_shader_parameter(
        "mask_intersection",
        &(mode == MaskMode::Intersection).to_variant(),
    );
}

fn set_light_params(material: &mut Gd<ShaderMaterial>, names: &UniformNames, light: &LightParams) {
    material.set_shader_parameter(&names.ambient_light, &light.ambient);
    material.set_shader_parameter(&names.light_count, &light.count);
    material.set_shader_parameter(&names.light_vectors, &light.vectors);
    material.set_shader_parameter(&names.light_colors, &light.colors);
}

fn set_color_params(
    material: &mut Gd<ShaderMaterial>,
    names: &UniformNames,
    state: &DrawableState,
    changed: DrawableChanges,
    all: bool,
) {
    if all || changed.contains(DrawableChanges::OPACITY) {
        material.set_shader_parameter(&names.opacity, &state.opacity.to_variant());
    }
    if all || changed.contains(DrawableChanges::MULTIPLY_COLOR) {
        let c = state.multiply_color;
        material.set_shader_parameter(
            &names.multiply_color,
            &Vector3::new(c.r, c.g, c.b).to_variant(),
        );
    }
    if all || changed.contains(DrawableChanges::SCREEN_COLOR) {
        let c = state.screen_color;
        material.set_shader_parameter(
            &names.screen_color,
            &Vector3::new(c.r, c.g, c.b).to_variant(),
        );
    }
    if all || changed.contains(DrawableChanges::MASK_STRENGTH) {
        material.set_shader_parameter(&names.mask_strength, &state.mask_strength.to_variant());
    }
}

