#[test]
fn rebase_keeps_unsaved_module_edits() {
    let temp = tempfile::tempdir().unwrap();
    let base_path = save_base(temp.path());
    let project = Project::new_module("Hat", &base_path, &"Hair".into()).unwrap();
    let dir = temp.path().join("hat.ugoeproj");
    project.save(&dir).unwrap();
    let before = crate::ProjectFingerprint::read_base(&base_path).unwrap();
    let mut document = Project::load(&dir).unwrap().document();
    document
        .apply(Command::AddPart {
            part: Part {
                id: "Brim".into(),
                name: "Brim".into(),
                parent: None,
                keyforms: KeyformGrid::constant(ugoe_model::part::PartKeyform { opacity: 1.0 }),
            },
        })
        .unwrap();

    // 本体を外で変える (パラメータを足し、スロットの範囲を変える)。
    let mut base = Project::load(&base_path).unwrap();
    base.model
        .parameters
        .push(dress_up_base().parameters[0].clone());
    base.model.parameters.last_mut().unwrap().id = "Extra".into();
    base.model.slots[0].draw_order.max = 600.0;
    base.save(&base_path).unwrap();
    let after = before.reread_base(&base_path).unwrap();
    assert_ne!(before, after);

    let state = document.state_id();
    document
        .rebase_module(crate::project::load_base(&base_path).unwrap())
        .unwrap();
    assert!(document.model().parameters.iter().any(|p| p.id == "Extra"));
    // 合成し直すので、新しく作った要素の ID にも接頭辞が付く。
    assert!(document.model().parts.iter().any(|p| p.id == "Hat/Brim"));
    assert_eq!(document.module().unwrap().slot().draw_order.max, 600.0);
    assert!(document.is_modified());
    assert!(document.state_id() > state);
    assert!(!document.undo());

    // 本体からスロットがなくなると読み直せない。別のスロットを選んで開ける。
    base.model.slots.remove(0);
    base.model.avatar = None;
    base.save(&base_path).unwrap();
    let before = document.model().clone();
    assert!(matches!(
        document.rebase_module(crate::project::load_base(&base_path).unwrap()),
        Err(ModuleError::UnknownSlot(_))
    ));
    assert_eq!(*document.model(), before);
    assert!(matches!(
        Project::load(&dir),
        Err(ProjectError::Module(ModuleError::UnknownSlot(_)))
    ));
    let (link_base, link_slot) = crate::project::read_module_link(&dir).unwrap();
    assert_eq!(link_base, base_path);
    assert_eq!(link_slot.as_str(), "Hair");
    let reopened = Project::load_module_with(&dir, None, Some(&"Outfit".into())).unwrap();
    assert_eq!(
        reopened.module.as_ref().unwrap().slot().id.as_str(),
        "Outfit"
    );
    // 開き直さずに、別のスロットで本体を読み直すこともできる (保存していない編集は残る)。
    document
        .rebase_module_on(
            crate::project::load_base(&base_path).unwrap(),
            Some(&"Outfit".into()),
        )
        .unwrap();
    assert_eq!(document.module().unwrap().slot().id.as_str(), "Outfit");
    assert!(document.model().parts.iter().any(|p| p.id == "Hat/Brim"));
    assert!(document.is_modified());
}

#[test]
fn module_pose_groups_can_be_set() {
    use ugoe_model::pose::{Pose, PoseEntry, PoseGroup};
    let module = long_hair_module();
    let mut document = document(&module);
    let entry = |part: &str| PoseEntry {
        part: part.into(),
        links: Vec::new(),
    };
    let own = |id: &str| format!("{}/{id}", module.name);
    let first = own(module.parts[0].id.as_str());
    for (id, name) in [("HairA", "Hair A"), ("HairB", "Hair B")] {
        document
            .apply(Command::AddPart {
                part: Part {
                    id: id.into(),
                    name: name.into(),
                    parent: Some(first.as_str().into()),
                    keyforms: KeyformGrid::constant(ugoe_model::part::PartKeyform { opacity: 1.0 }),
                },
            })
            .unwrap();
    }
    document
        .apply(Command::SetPose {
            pose: Pose {
                groups: vec![PoseGroup {
                    entries: vec![entry("HairA"), entry("HairB")],
                }],
                ..Pose::default()
            },
        })
        .unwrap();
    let split = split(&document);
    assert_eq!(split.pose.groups.len(), 1);
    assert_eq!(split.pose.groups[0].entries[1].part.as_str(), "HairB");

    let base_part = dress_up_base().parts[0].id.clone();
    let error = document
        .apply(Command::SetPose {
            pose: Pose {
                groups: vec![PoseGroup {
                    entries: vec![entry(base_part.as_str()), entry("HairA")],
                }],
                ..Pose::default()
            },
        })
        .unwrap_err();
    assert!(
        matches!(
            error,
            EditError::ModuleShape { .. } | EditError::ReadOnlyBase { .. }
        ),
        "{error:?}"
    );
    // Undo で最初のポーズの設定の前に戻る。
    assert!(document.undo());
    assert!(document.model().pose.groups.is_empty());
}

#[test]
fn base_check_runs_before_the_base_is_read() {
    use std::cell::RefCell;

    let temp = tempfile::tempdir().unwrap();
    let base_path = save_base(temp.path());
    let dir = temp.path().join("mods/hat.ugoeproj");
    Project::new_module("Hat", &base_path, &"Hair".into())
        .unwrap()
        .save(&dir)
        .unwrap();

    // `project.json` の参照 (`../../avatar.ugoeproj`) を絶対パスに解決して渡す。断れば本体を読まない。
    let seen = RefCell::new(Vec::new());
    let refuse = |path: &std::path::Path| {
        seen.borrow_mut().push(path.to_path_buf());
        Err("outside".to_owned())
    };
    let err = Project::load_checking_base(&dir, &refuse).unwrap_err();
    assert!(
        matches!(&err, ProjectError::BaseRefused { path, reason } if *path == base_path && reason == "outside"),
        "{err}"
    );
    assert_eq!(*seen.borrow(), vec![base_path.clone()]);
    // 本体が無くても、確かめるのは開く前 (見つからないことは確かめた後で分かる)。
    let moved = temp.path().join("moved.ugoeproj");
    std::fs::rename(&base_path, &moved).unwrap();
    assert!(matches!(
        Project::load_checking_base(&dir, &refuse),
        Err(ProjectError::BaseRefused { .. })
    ));

    // 返したパスから読み、保存する参照は元のまま。
    let redirect = |_: &std::path::Path| Ok(moved.clone());
    let project = Project::load_checking_base(&dir, &redirect).unwrap();
    assert_eq!(project.module.as_ref().unwrap().base().path, base_path);
    assert_eq!(project.model.meshes.len(), dress_up_base().meshes.len());

    // モデルのプロジェクトでは呼ばない。
    let never = |_: &std::path::Path| -> Result<std::path::PathBuf, String> {
        panic!("a model project has no base")
    };
    assert!(Project::load_checking_base(&moved, &never).is_ok());
}

#[test]
fn base_can_be_a_bundle() {
    let temp = tempfile::tempdir().unwrap();
    let base_path = save_base(temp.path());
    let bytes = export_bundle(&Project::load(&base_path).unwrap()).unwrap();
    std::fs::create_dir_all(temp.path()).unwrap();
    let bundle = temp.path().join("avatar.ugoe");
    std::fs::write(&bundle, bytes).unwrap();
    let project = Project::new_module("Hat", &bundle, &"Outfit".into()).unwrap();
    assert_eq!(project.model.meshes.len(), dress_up_base().meshes.len());
    let dir = temp.path().join("mods/hat.ugoeproj");
    project.save(&dir).unwrap();
    let meta: serde_json::Value =
        serde_json::from_slice(&std::fs::read(dir.join("project.json")).unwrap()).unwrap();
    assert_eq!(meta["module"]["base"], "../../avatar.ugoe");
    let project = Project::load(&dir).unwrap();
    // プレビューで比べるための本体だけのバンドル (モジュールの要素を含まない)。
    let base_only = ugoe_format::read_bundle(&export_base_bundle(&project).unwrap()).unwrap();
    assert_eq!(base_only.model, dress_up_base());
    assert!(matches!(
        export_base_bundle(&Project::load(&base_path).unwrap()),
        Err(ProjectError::NotAModule)
    ));
}

pub fn new_module(name: &str, base: &Path, slot: &SlotId) -> Result<Self, ProjectError> {
    let base = load_base(&normalize_path(base))?;
    let context = ModuleContext::new(base, slot, name, ModuleRequirements::default())?;
    let workspace = context.workspace(&context.empty_module(), &Textures::new())?;
    let mut meta = ProjectMeta::new(name);
    meta.kind = ProjectKind::Module;
    meta.module = Some(ModuleLink {
        base: context.base().path.display().to_string(),
        slot: slot.clone(),
    });
    Ok(Self::from_workspace(meta, workspace, context))
}

fn meta_for(&self, dir: &Path) -> ProjectMeta {
    let mut meta = self.meta.clone();
    if let Some(context) = &self.module {
        meta.kind = ProjectKind::Module;
        meta.module = Some(ModuleLink {
            base: relative_path(&normalize_path(&absolute(dir)), &context.base().path),
            slot: context.slot().id.clone(),
        });
    }
    meta
}

pub(crate) fn import_psd(
    args: ImportArgs,
    psd: PathBuf,
    base: Option<PathBuf>,
) -> Result<Imported, ToolError> {
    let name = args.name.unwrap_or_else(|| {
        psd.file_stem()
            .map(|s| s.to_string_lossy().into_owned())
            .unwrap_or_else(|| "untitled".to_owned())
    });
    let project = match (&base, &args.slot) {
        (None, None) => Project::empty(name.clone()),
        (Some(base), Some(slot)) => Project::new_module(&name, base, &SlotId::from(slot.as_str()))
            .map_err(|e| {
                ToolError::coded(
                    format!("the module project could not be created: {e}"),
                    e.to_message(),
                )
            })?,
        _ => {
            return Err(ToolError::invalid_arguments(
                "pass `base` and `slot` together to create a module project",
            ));
        }
    };
    let source = PsdSource::load(psd.clone())?;
    let mut document = project.document();
    let mut import = layer_tree_command(
        document.model(),
        &source.tree,
        &PsdImportOptions::new(name.clone()),
    )
    .map_err(|e| ToolError::coded(e.to_string(), e.to_message()))?;
    if let Some(context) = document.module() {
        context.map_new_meshes(&mut import.command);
    }
    document.apply(import.command).map_err(|e| {
        ToolError::coded(
            format!("the PSD could not be imported: {e}"),
            e.to_message(),
        )
    })?;
    let module = document
        .module()
        .map(|context| json!({ "base": context.base().path, "slot": context.slot().id }));
    let next = if module.is_some() {
        "get_psd_layers でレイヤーと画像を見て分類し、get_module_rig_guide → propose_module_rig"
    } else {
        "get_psd_layers でレイヤーと画像を見て分類する"
    };
    let value = json!({
        "name": name,
        "psd": psd,
        "layers": source.labels.len(),
        // モジュールなら衣装のメッシュだけを数える。
        "meshes": document
            .model()
            .meshes
            .iter()
            .filter(|m| document.module().is_none_or(|c| !c.is_base_mesh(&m.id)))
            .count(),
        "module": module,
        "warnings": import.warnings,
        "next": next,
    });
    Ok(Imported {
        meta: project.meta,
        document,
        source,
        value,
    })
}

fn build_helper() -> Option<Gd<RefCounted>> {
    let mut script = GDScript::new_gd();
    script.set_source_code("extends RefCounted\nfunc _cap():\n\treturn get_stack()\n");
    script.reload();
    let mut obj = RefCounted::new_gd();
    obj.set_script(&script);
    Some(obj)
}

fn capture_loc() -> Option<String> {
    if !EngineDebugger::singleton().is_active() {
        return None;
    }
    let mut helper = HELPER.with(|h| {
        let mut slot = h.borrow_mut();
        if slot.is_none() {
            *slot = build_helper();
        }
        slot.clone()
    })?;
    let frames = helper.call("_cap", &[]).try_to::<Array<Variant>>().ok()?;
    let frame = frames.get(1)?.try_to::<VarDictionary>().ok()?;
    let source = frame.get(&"source".to_variant())?.try_to::<GString>().ok()?;
    let line = frame.get(&"line".to_variant())?.try_to::<i64>().ok()?;
    Some(format!("{source}:{line}"))
}

pub(crate) fn break_if_pending() {
    if !PENDING_BREAK.with(|b| b.replace(false)) {
        return;
    }
    let mut debugger = EngineDebugger::singleton();
    if debugger.is_active() {
        debugger.debug_ex().is_error_breakpoint(true).done();
    }
}

#[godot_api(secondary)]
impl ImGuiApi {
    /// Register a Godot texture so it can be drawn with `image()` and `image_button()`.
    ///
    /// Returns an id to pass to those functions. Call this during the layout signal,
    /// once per texture (for example on the first frame), and reuse the id afterwards.
    #[func]
    fn register_texture(&self, texture: Gd<Texture2D>) -> i64 {
        register_texture(texture) as i64
    }

    /// Draw a registered texture at the given size. `texture_id` comes from
    /// `register_texture()`. The size is in logical pixels, scaled by the global UI scale.
    #[func]
    fn image(&self, texture_id: i64, size: Vector2) {
        if !is_in_frame() {
            return;
        }
        unsafe {
            sys::igImage(
                texture_id as usize as *mut c_void,
                vec2s(size.x, size.y),
                vec2(0.0, 0.0),
                vec2(1.0, 1.0),
                white(),
                transparent(),
            )
        }
    }

    /// Draw a clickable image button. `texture_id` comes from `register_texture()`.
    /// Returns `true` on the frame it is clicked. The size is in logical pixels, scaled.
    #[func]
    fn image_button(&self, id: GString, texture_id: i64, size: Vector2) -> bool {
        if !is_in_frame() {
            return false;
        }
        let c = cstr(&id);
        unsafe {
            sys::igImageButton(
                c.as_ptr(),
                texture_id as usize as *mut c_void,
                vec2s(size.x, size.y),
                vec2(0.0, 0.0),
                vec2(1.0, 1.0),
                transparent(),
                white(),
            )
        }
    }
}

