                && min_y >= clip_rect[1] - CLIP_FIT_EPS
                && max_x <= clip_rect[2] + CLIP_FIT_EPS
                && max_y <= clip_rect[3] + CLIP_FIT_EPS;

            if fits {
                let points = PackedVector2Array::from(&pv[base..end]);
