pub(super) enum PendingInput {
    Keys(String),
    Event(Gd<godot::classes::InputEvent>),
}

pub(super) fn process_command_results(&mut self) {
    for client in [&self.script_neovim, &self.shader_neovim]
        .into_iter()
        .flatten()
    {
        let Ok(client) = client.try_lock() else {
            continue;
        };
        for completed in client.take_command_results() {
            match completed.result {
                Ok(Some(value)) => {
                    godot_print!("[godot-neovim] {}: {}", completed.command, value)
                }
                Ok(None) => {}
                Err(error) => godot_warn!("[godot-neovim] {}: {}", completed.command, error),
            }
        }
    }
    if self.pending_cursor_sync
        && !self.pending_neovim_switch
        && !self.current_commands_pending()
    {
        self.sync_cursor_to_neovim();
    }
}

pub(super) fn defer_input_during_switch(
    &mut self,
    event: &Gd<godot::classes::InputEvent>,
) -> bool {
    if !self.pending_neovim_switch
        || self.get_focused_code_edit_direct().is_none()
        || !event.is_class("InputEventKey")
    {
        return false;
    }
    self.pending_switch_input
        .push(PendingInput::Event(event.clone()));
    if let Some(mut viewport) = self
        .get_focused_code_edit_direct()
        .and_then(|editor| editor.get_viewport())
    {
        viewport.set_input_as_handled();
    }
    true
}

pub(super) fn retry_pending_neovim_switch(&mut self) {
    if !self.pending_neovim_switch {
        return;
    }
    let ready = self
        .get_current_neovim()
        .and_then(|client| client.try_lock().ok())
        .is_some_and(|client| !client.commands_pending());
    if !ready {
        return;
    }
    // Drain the previous buffer before replacing its editor and sync state.
    self.process_neovim_updates();
    self.pending_neovim_switch = false;
    self.script_changed_pending.set(false);
    self.handle_script_changed_deferred();
    if self.pending_neovim_switch {
        return;
    }
    if !self.pending_switch_path.is_empty()
        && self.pending_switch_path != self.current_script_path
    {
        self.clear_pending_neovim_switch();
        return;
    }
    for input in std::mem::take(&mut self.pending_switch_input) {
        match input {
            PendingInput::Keys(keys) => {
                self.base_mut()
                    .call_deferred("send_deferred_keys", &[keys.to_variant()]);
            }
            PendingInput::Event(event) => {
                if let Some(mut viewport) = self
                    .current_editor
                    .as_ref()
                    .and_then(|editor| editor.get_viewport())
                {
                    viewport.call_deferred("push_input", &[event.to_variant()]);
                }
            }
        }
    }
}

fn switch_script_tab(&mut self, offset: i32) {
    // Check if we're in ShaderEditor - if so, switch shader tabs instead
    if self.current_editor_type == EditorType::Shader {
        self.switch_shader_tab(offset);
        return;
    }

    // External CodeEdits (Unknown) have no ScriptEditor tabs to switch
    if self.current_editor_type == EditorType::Unknown {
        crate::verbose_print!(
            "[godot-neovim] switch_script_tab: ignoring for external CodeEdit"
        );
        return;
    }

    let mut editor = EditorInterface::singleton();
    let Some(script_editor) = editor.get_script_editor() else {
        return;
    };

    let open_scripts = script_editor.get_open_scripts();
    let count = open_scripts.len() as i32;
    if count <= 1 {
        crate::verbose_print!(
            "[godot-neovim] switch_script_tab: only {} script(s) open",
            count
        );
        return;
    }

    // Find current script index
    let current_script = script_editor.get_current_script();
    let current_path = current_script
        .as_ref()
        .map(|s| s.get_path().to_string())
        .unwrap_or_default();

    let mut current_idx: i32 = 0;
    for i in 0..count {
        if let Some(script) = open_scripts.get(i as usize) {
            if script.get_path().to_string() == current_path {
                current_idx = i;
                break;
            }
        }
    }

    // Calculate new index with wrapping
    let new_idx = ((current_idx + offset) % count + count) % count;

    // Get the target script and switch using call_deferred
    if let Some(script) = open_scripts.get(new_idx as usize) {
        let new_path = script.get_path().to_string();
        crate::verbose_print!(
            "[godot-neovim] Tab switch: {} -> {} ({})",
            current_idx,
            new_idx,
            new_path
        );
        // Use call_deferred to avoid blocking during input handling
        editor.call_deferred("edit_script", &[script.to_variant()]);
    }
}

pub(crate) fn sync_godot_script_tab(&mut self, neovim_path: &str) {
    let mut editor = EditorInterface::singleton();
    let Some(script_editor) = editor.get_script_editor() else {
        return;
    };

    // Check if current Godot script already matches
    if let Some(current_script) = script_editor.get_current_script() {
        let current_res_path = current_script.get_path().to_string();
        // Convert res:// path to absolute path for comparison
        let current_abs_path =
            godot::classes::ProjectSettings::singleton().globalize_path(&current_res_path);
        let current_abs_str = current_abs_path.to_string().replace('\\', "/");

        // Normalize neovim path (ensure forward slashes)
        let neovim_normalized = neovim_path.replace('\\', "/");

        if current_abs_str == neovim_normalized {
            // Already on the correct script
            return;
        }
    }

    // Find and switch to the script matching neovim_path
    let open_scripts = script_editor.get_open_scripts();
    let neovim_normalized = neovim_path.replace('\\', "/");

    for i in 0..open_scripts.len() {
        if let Some(script) = open_scripts.get(i) {
            let res_path = script.get_path().to_string();
            let abs_path =
                godot::classes::ProjectSettings::singleton().globalize_path(&res_path);
            let abs_str = abs_path.to_string().replace('\\', "/");

            if abs_str == neovim_normalized {
                crate::verbose_print!(
                    "[godot-neovim] BufEnter: Switching Godot tab to {}",
                    res_path
                );
                // Use call_deferred to avoid issues during event processing
                editor.call_deferred("edit_script", &[script.to_variant()]);
                return;
            }
        }
    }

    crate::verbose_print!(
        "[godot-neovim] BufEnter: No matching Godot script for {}",
        neovim_path
    );
}

fn find_code_edit_in_control(&self, control: Gd<godot::classes::Node>) -> Option<Gd<CodeEdit>> {
    // Check if this node is a CodeEdit
    if let Ok(code_edit) = control.clone().try_cast::<CodeEdit>() {
        return Some(code_edit);
    }

    // Recursively search children
    for i in 0..control.get_child_count() {
        if let Some(child) = control.get_child(i) {
            if let Some(code_edit) = self.find_code_edit_in_control(child) {
                return Some(code_edit);
            }
        }
    }

    None
}

fn emit_file_menu_signal(shortcut: &str) -> bool {
    let Some(editor) = EditorInterface::singleton().get_script_editor() else {
        return false;
    };
    editor_tree::find_menu(&editor.upcast(), shortcut)
        .is_some_and(|popup| editor_tree::emit_menu_action(popup, shortcut))
}

pub(in crate::plugin) fn cmd_edit(&self, file_path: &str) {
    let mut editor = EditorInterface::singleton();

    if file_path.is_empty() {
        // No file specified - open quick open dialog
        let callback = Callable::from_fn("quick_open_callback", |args: &[&Variant]| {
            if let Some(path_var) = args.first() {
                let path: String = path_var.to::<String>();
                if !path.is_empty() {
                    // Load and open the selected script
                    let resource = godot::classes::ResourceLoader::singleton().load(&path);
                    if let Some(res) = resource {
                        if let Ok(script) = res.try_cast::<godot::classes::Script>() {
                            let mut ed = EditorInterface::singleton();
                            ed.edit_script(&script);
                            crate::verbose_print!(
                                "[godot-neovim] :e - Opened script from quick open: {}",
                                path
                            );
                        }
                    }
                }
            }
            Variant::nil()
        });

        // Filter for Script types
        let mut base_types: Array<StringName> = Array::new();
        base_types.push(&StringName::from("Script"));
        editor
            .popup_quick_open_ex(&callback)
            .base_types(&base_types)
            .done();
        crate::verbose_print!("[godot-neovim] :e - Opened quick open dialog");
        return;
    }

    // Try to load the resource
    let path = if file_path.starts_with("res://") {
        file_path.to_string()
    } else {
        // Assume relative to res://
        format!("res://{}", file_path)
    };

    // Load the resource
    let resource = godot::classes::ResourceLoader::singleton().load(&path);
    if let Some(res) = resource {
        // Try to cast to Script
        if let Ok(script) = res.try_cast::<godot::classes::Script>() {
            // Use edit_script to open the script
            editor.edit_script(&script);
            crate::verbose_print!("[godot-neovim] :e - Opened script: {}", path);
        } else {
            godot_warn!("[godot-neovim] :e - Not a script file: {}", path);
        }
    } else {
        godot_warn!("[godot-neovim] :e - File not found: {}", path);
    }
}

fn close_shader_tab(&mut self) {
    // Queue the action on this editor's menu before clearing its identity.
    // A synthetic Ctrl+W may reach a different window or script editor.
    if !self.emit_current_file_menu_action("script_editor/close_file") {
        godot_warn!("[godot-neovim] :q - Could not find shader File menu");
        return;
    }
    // Disconnect from signals BEFORE clearing editor reference
    // to avoid accessing freed CodeEdit instance
    self.disconnect_caret_changed_signal();
    self.disconnect_text_changed_signal();
    self.disconnect_resized_signal();
    self.disconnect_gui_input_signal();

    // Delete shader buffer from Neovim before closing
    if !self.current_script_path.is_empty() {
        // Convert res:// path to absolute path for Neovim
        let abs_path = if self.current_script_path.starts_with("res://") {
            godot::classes::ProjectSettings::singleton()
                .globalize_path(&self.current_script_path)
                .to_string()
        } else {
            self.current_script_path.clone()
        };
        self.delete_neovim_buffer(&abs_path, EditorType::Shader);
    }

    // Clear current editor after disconnecting signals
    self.current_editor = None;
    self.current_editor_type = EditorType::Unknown;

    // Set flag to grab focus on shader editor after close
    // This ensures we focus the remaining shader tab's CodeEdit
    self.focus_shader_after_close = true;

    crate::verbose_print!("[godot-neovim] :q - Shader tab close queued");
}

