fn close_all_shader_tabs(&mut self) {
    // Find ShaderEditor's TabContainer and get shader paths for buffer cleanup
    let editor = EditorInterface::singleton();
    let Some(base_control) = editor.get_base_control() else {
        return;
    };

    // Find EditorNode
    let Some(editor_node) = self.find_editor_node_from_control(&base_control) else {
        return;
    };

    let Some(container) = editor_tree::find_shader_container(&editor_node) else {
        return;
    };
    let Some(list) = editor_tree::document_list(&container) else {
        return;
    };
    let Some(popup) = editor_tree::find_menu(&container, "script_editor/close_file") else {
        return;
    };
    let tab_count = list.get_item_count();
    for index in 0..tab_count {
        let path = list.get_item_tooltip(index).to_string();
        if path.starts_with("res://") {
            if let Some(path) = self.convert_res_path_to_absolute(&path) {
                self.delete_neovim_buffer(&path, EditorType::Shader);
            }
        }
    }

    // 4.8 exposes Close All in the File menu. Legacy versions expose only Close.
    if !editor_tree::emit_menu_action(popup.clone(), "script_editor/close_all") {
        for _ in 0..tab_count {
            editor_tree::emit_menu_action(popup.clone(), "script_editor/close_file");
        }
    }
}

fn find_editor_node_from_control(
    &self,
    control: &Gd<godot::classes::Control>,
) -> Option<Gd<godot::classes::Node>> {
    let mut current: Gd<godot::classes::Node> = control.clone().upcast();
    loop {
        let class_name = current.get_class().to_string();
        if class_name == "EditorNode" {
            return Some(current);
        }
        current = current.get_parent()?;
    }
}

fn convert_res_path_to_absolute(&self, res_path: &str) -> Option<String> {
    use godot::classes::ProjectSettings;
    let project_path = ProjectSettings::singleton()
        .globalize_path(res_path)
        .to_string();
    if project_path.is_empty() {
        None
    } else {
        Some(project_path)
    }
}

pub(in crate::plugin) fn open_documentation(&mut self) {
    let Some(ref editor) = self.current_editor else {
        return;
    };

    // Get word under cursor
    let line_idx = editor.get_caret_line();
    let col_idx = editor.get_caret_column() as usize;
    let line_text = editor.get_line(line_idx).to_string();
    let chars: Vec<char> = line_text.chars().collect();

    if col_idx >= chars.len() {
        return;
    }

    // Find word boundaries
    let is_word_char = |c: char| c.is_alphanumeric() || c == '_';
    let mut start = col_idx;
    while start > 0 && is_word_char(chars[start - 1]) {
        start -= 1;
    }
    let mut end = col_idx;
    while end < chars.len() && is_word_char(chars[end]) {
        end += 1;
    }

    if start == end {
        return;
    }

    let word: String = chars[start..end].iter().collect();
    crate::verbose_print!("[godot-neovim] K: Looking up help for '{}'", word);

    // If word starts with uppercase, assume it's a class name (fast path)
    if word.chars().next().is_some_and(|c| c.is_uppercase()) {
        self.pending_help_query = Some(HelpQuery {
            class_name: word.clone(),
            member_name: None,
            member_type: HelpMemberType::Class,
        });
        crate::verbose_print!("[godot-neovim] K: Queueing class help for '{}'", word);
        return;
    }

    // Try LSP hover to get class/member information
    let Some(ref lsp) = self.godot_lsp else {
        crate::verbose_print!("[godot-neovim] K: LSP not available, skipping '{}'", word);
        return;
    };

    // Get absolute file path and convert to URI
    let abs_path = if self.current_script_path.starts_with("res://") {
        ProjectSettings::singleton()
            .globalize_path(&self.current_script_path)
            .to_string()
    } else {
        self.current_script_path.clone()
    };

    let uri = if abs_path.starts_with('/') {
        format!("file://{}", abs_path)
    } else {
        format!("file:///{}", abs_path.replace('\\', "/"))
    };

    // Get project root for LSP initialization
    let project_root = ProjectSettings::singleton()
        .globalize_path("res://")
        .to_string();
    let root_uri = if project_root.starts_with('/') {
        format!("file://{}", project_root)
    } else {
        format!("file:///{}", project_root.replace('\\', "/"))
    };

    // Ensure LSP is connected and initialized
    if !lsp.is_connected() {
        if let Err(e) = lsp.connect(6005) {
            crate::verbose_print!("[godot-neovim] K: LSP connect failed: {}", e);
            return;
        }
    }

    if !lsp.is_initialized() {
        if let Err(e) = lsp.initialize(&root_uri) {
            crate::verbose_print!("[godot-neovim] K: LSP init failed: {}", e);
            return;
        }
    }

    // Request hover information
    let line = line_idx as u32;
    let col = col_idx as u32;
    let hover_result = lsp.hover(&uri, line, col);

    match hover_result {
        Ok(Some(hover)) => {
            // Parse hover contents to extract class and member information
            if let Some(query) = Self::parse_hover_for_help(&hover, &word) {
                crate::verbose_print!(
                    "[godot-neovim] K: LSP hover found - class: {}, member: {:?}, type: {:?}",
                    query.class_name,
                    query.member_name,
                    query.member_type
                );
                self.pending_help_query = Some(query);
            } else {
                crate::verbose_print!("[godot-neovim] K: Could not parse hover for '{}'", word);
            }
        }
        Ok(None) => {
            crate::verbose_print!("[godot-neovim] K: No hover info for '{}'", word);
        }
        Err(e) => {
            crate::verbose_print!("[godot-neovim] K: LSP hover error: {}", e);
        }
    }
}

pub(in crate::plugin) fn cmd_show_marks(&self) {
    if self.marks.is_empty() {
        godot_print!("[godot-neovim] :marks - No marks set");
        return;
    }

    godot_print!("[godot-neovim] :marks");
    godot_print!("mark  line  col");

    // Sort marks by character
    let mut marks: Vec<_> = self.marks.iter().collect();
    marks.sort_by_key(|(k, _)| *k);

    for (mark, (line, col)) in marks {
        godot_print!(" {}    {:>4}  {:>3}", mark, line + 1, col);
    }
}

pub(in crate::plugin) fn cmd_show_registers(&self) {
    if self.registers.is_empty() {
        godot_print!("[godot-neovim] :registers - No registers set");
        return;
    }

    godot_print!("[godot-neovim] :registers");

    // Sort registers by character
    let mut regs: Vec<_> = self.registers.iter().collect();
    regs.sort_by_key(|(k, _)| *k);

    for (reg, content) in regs {
        // Truncate long content and show preview
        let preview = if content.len() > 50 {
            format!("{}...", &content[..47])
        } else {
            content.replace('\n', "^J")
        };
        godot_print!("\"{}   {}", reg, preview);
    }
}

pub(in crate::plugin) fn cmd_show_jumps(&self) {
    godot_print!("[godot-neovim] :jumps");
    godot_print!(" jump line  col");

    if self.jump_list.is_empty() {
        godot_print!("   (empty)");
        return;
    }

    for (i, (line, col)) in self.jump_list.iter().enumerate() {
        let marker = if i == self.jump_list_pos { ">" } else { " " };
        godot_print!("{}{:>4}  {:>4}  {:>3}", marker, i + 1, line + 1, col);
    }

    if self.jump_list_pos >= self.jump_list.len() {
        godot_print!(">          (current)");
    }
}

pub(in crate::plugin) fn cmd_show_changes(&self) {
    godot_print!("[godot-neovim] :changes");
    godot_print!("   (change list not tracked)");
    godot_print!("   Use undo/redo (u/Ctrl+R) for changes");
}

pub(in crate::plugin) fn cmd_list_buffers(&self) {
    let editor = EditorInterface::singleton();
    if let Some(script_editor) = editor.get_script_editor() {
        let open_scripts = script_editor.get_open_scripts();

        godot_print!("[godot-neovim] :ls - Open buffers:");
        for i in 0..open_scripts.len() {
            if let Some(script) = open_scripts.get(i) {
                let path = script.get_path().to_string();
                let name = path.split('/').next_back().unwrap_or(&path);
                godot_print!("  {}: {}", i + 1, name);
            }
        }
    }
}

pub(super) fn simulate_key_press(key: Key, ctrl: bool, shift: bool, alt: bool) {
    let mut key_press = InputEventKey::new_gd();
    key_press.set_keycode(key);
    key_press.set_ctrl_pressed(ctrl);
    key_press.set_shift_pressed(shift);
    key_press.set_alt_pressed(alt);
    key_press.set_pressed(true);
    Input::singleton().parse_input_event(&key_press);

    let mut key_release = InputEventKey::new_gd();
    key_release.set_keycode(key);
    key_release.set_ctrl_pressed(ctrl);
    key_release.set_shift_pressed(shift);
    key_release.set_alt_pressed(alt);
    key_release.set_pressed(false);
    Input::singleton().parse_input_event(&key_release);
}

fn set_command_mode_color(label: &mut Gd<Label>) {
    label.add_theme_color_override("font_color", Color::from_rgb(1.0, 1.0, 0.4));
}

pub(super) fn show_file_info(&mut self) {
    let Some(ref editor) = self.current_editor else {
        self.show_status_message("No file");
        return;
    };

    let current_line = editor.get_caret_line() + 1; // 1-indexed for display
    let total_lines = editor.get_line_count();
    let percent = if total_lines > 0 {
        (current_line * 100) / total_lines
    } else {
        0
    };

    // Try to get the script path
    let file_name = if let Some(script_edit) = EditorInterface::singleton().get_script_editor()
    {
        if let Some(current_script) = script_edit.get_current_script() {
            let path = current_script.get_path().to_string();
            if path.is_empty() {
                "[New File]".to_string()
            } else {
                // Extract just the filename from path
                path.split('/').next_back().unwrap_or(&path).to_string()
            }
        } else {
            "[No Script]".to_string()
        }
    } else {
        "[Unknown]".to_string()
    };

    let msg = format!(
        "\"{}\" line {} of {} --{}%--",
        file_name, current_line, total_lines, percent
    );

    self.show_status_message(&msg);
    crate::verbose_print!("[godot-neovim] Ctrl+G: {}", msg);
}

pub(super) fn open_url_under_cursor(&mut self) {
    let Some(ref editor) = self.current_editor else {
        return;
    };

    let line_idx = editor.get_caret_line();
    let col_idx = editor.get_caret_column() as usize;
    let line_text = editor.get_line(line_idx).to_string();
    let chars: Vec<char> = line_text.chars().collect();

    if col_idx >= chars.len() {
        crate::verbose_print!("[godot-neovim] gx: Cursor at end of line");
        return;
    }

    // Find start and end of URL-like text
    // Valid URL characters: alphanumeric, /:.-_~?#[]@!$&'()*+,;=%
    let url_chars = |c: char| c.is_alphanumeric() || "/:.-_~?#[]@!$&'()*+,;=%".contains(c);

    let mut start = col_idx;
    while start > 0 && url_chars(chars[start - 1]) {
        start -= 1;
    }

    let mut end = col_idx;
    while end < chars.len() && url_chars(chars[end]) {
        end += 1;
    }

    if start == end {
        crate::verbose_print!("[godot-neovim] gx: No URL under cursor");
        return;
    }

    let url: String = chars[start..end].iter().collect();

    // Check if it looks like a URL
    if url.starts_with("http://") || url.starts_with("https://") || url.starts_with("file://") {
        crate::verbose_print!("[godot-neovim] gx: Opening URL: {}", url);
        let _ = Os::singleton().shell_open(&url);
    } else if url.contains("://") {
        // Other URL schemes
        crate::verbose_print!("[godot-neovim] gx: Opening URI: {}", url);
        let _ = Os::singleton().shell_open(&url);
    } else if url.contains('.') && !url.starts_with('.') {
        // Likely a domain name - add https://
        let full_url = format!("https://{}", url);
        crate::verbose_print!("[godot-neovim] gx: Opening as URL: {}", full_url);
        let _ = Os::singleton().shell_open(&full_url);
    } else {
        crate::verbose_print!("[godot-neovim] gx: Not a valid URL: {}", url);
    }
}

pub(super) fn update_float_window_connection(&mut self) {
    let Some(ref editor) = self.current_editor else {
        crate::verbose_print!("[godot-neovim] update_float_window: no current_editor");
        return;
    };

    // Get the window containing the CodeEdit
    let Some(window) = editor.get_window() else {
        crate::verbose_print!("[godot-neovim] update_float_window: editor has no window");
        return;
    };

    // Check if this is a float window (not the main window)
    // Float windows are children of EditorNode, main window is the root window
    let main_window = EditorInterface::singleton()
        .get_base_control()
        .and_then(|c| c.get_window());

    let is_float_window = match main_window {
        Some(ref main) => {
            let is_float = window.instance_id() != main.instance_id();
            crate::verbose_print!(
                "[godot-neovim] update_float_window: editor_window={} (id={}), main_window={} (id={}), is_float={}",
                window.get_name(),
                window.instance_id(),
                main.get_name(),
                main.instance_id(),
                is_float
            );
            is_float
        }
        None => {
            crate::verbose_print!("[godot-neovim] update_float_window: no main window found");
            false
        }
    };

    // Always connect gui_input signal - it will check is_in_float_window() internally
    // This ensures we catch input in float windows
    self.connect_gui_input_signal();

    if is_float_window {
        crate::verbose_print!(
            "[godot-neovim] CodeEdit is in float window: {}",
            window.get_name()
        );
    }
}

pub(super) fn handle_script_changed(&mut self) {
    // Increment switch ID and store as pending
    // This allows detecting and skipping stale deferred operations
    // when rapid tab switching occurs (ref: vscode-neovim commit 0520846)
    self.script_switch_id = self.script_switch_id.wrapping_add(1);
    self.pending_switch_id = self.script_switch_id;

    // Use call_deferred to ensure Godot has fully switched to the new script
    // before we try to find the CodeEdit and sync buffer
    self.base_mut()
        .call_deferred("handle_script_changed_deferred", &[]);
}

fn get_script_editor_code_edit_via_api(&self) -> Option<Gd<CodeEdit>> {
    let editor = EditorInterface::singleton();
    let script_editor = editor.get_script_editor()?;

    // Use public API: get_current_editor() returns ScriptEditorBase
    let current_editor: Gd<ScriptEditorBase> = script_editor.get_current_editor()?;

    // get_base_editor() returns the underlying Control (which is a CodeEdit)
    let base_editor: Gd<Control> = current_editor.get_base_editor()?;

    // Cast Control to CodeEdit
    base_editor.try_cast::<CodeEdit>().ok()
}

pub(super) fn get_focused_code_edit_direct(&self) -> Option<Gd<CodeEdit>> {
    let editor = EditorInterface::singleton();
    let base_control = editor.get_base_control()?;

    // First try the main viewport
    let main_viewport = base_control.get_viewport()?;
    if let Some(focus_owner) = main_viewport
        .gui_get_focus_owner()
        .filter(|c| c.is_visible_in_tree() && c.get_window().is_some_and(|w| w.has_focus()))
    {
        if let Ok(code_edit) = focus_owner.try_cast::<CodeEdit>() {
            return Some(code_edit);
        }
    }

    // Float windows are managed by EditorNode, not as children of root window.
    // We need to find EditorNode by traversing up from base_control
    // and then search its children for WindowWrapper/Window nodes.
    let editor_node = self.find_editor_node(base_control.clone().upcast())?;
    crate::verbose_print!(
        "[godot-neovim] Found EditorNode: {} (children={})",
        editor_node.get_name(),
        editor_node.get_child_count()
    );
    self.find_focused_code_edit_in_subwindows(editor_node)
}

fn find_editor_node(&self, node: Gd<Node>) -> Option<Gd<Node>> {
    let mut current = node;
    loop {
        let class_name = current.get_class().to_string();
        if class_name == "EditorNode" {
            return Some(current);
        }
        current = current.get_parent()?;
    }
}

fn find_focused_code_edit_in_subwindows(&self, node: Gd<Node>) -> Option<Gd<CodeEdit>> {
    // If this is a Window, check its focus owner or search for CodeEdit directly
    if let Ok(window) = node.clone().try_cast::<Window>() {
        let window_has_focus = window.has_focus();

        // First try gui_get_focus_owner
        if let Some(focus_owner) = window
            .gui_get_focus_owner()
            .filter(|c| window_has_focus && c.is_visible_in_tree())
        {
            if let Ok(code_edit) = focus_owner.try_cast::<CodeEdit>() {
                return Some(code_edit);
            }
        }

        // If window has focus (OS-level), search for any CodeEdit in this window
        // Float windows won't report gui_get_focus_owner correctly when called from main window
        if window_has_focus {
            if let Some(code_edit) = super::editor_tree::visible_code_edit(&window.upcast()) {
                return Some(code_edit);
            }
        }
    }

    // Search children for more windows
    let count = node.get_child_count();
    for i in 0..count {
        if let Some(child) = node.get_child(i) {
            if let Some(code_edit) = self.find_focused_code_edit_in_subwindows(child) {
                return Some(code_edit);
            }
        }
    }

    None
}

pub(super) fn find_focused_code_edit(&self, node: Gd<Control>) -> Option<Gd<CodeEdit>> {
    // Check if this node is a focused CodeEdit
    if let Ok(code_edit) = node.clone().try_cast::<CodeEdit>() {
        if code_edit.has_focus() {
            return Some(code_edit);
        }
    }

    // Search children
    let count = node.get_child_count();
    for i in 0..count {
        if let Some(child) = node.get_child(i) {
            if let Ok(control) = child.try_cast::<Control>() {
                if let Some(code_edit) = self.find_focused_code_edit(control) {
                    return Some(code_edit);
                }
            }
        }
    }

    None
}

pub(super) fn find_visible_code_edit(&self, node: Gd<Control>) -> Option<Gd<CodeEdit>> {
    // Check if this node is a visible CodeEdit
    if let Ok(code_edit) = node.clone().try_cast::<CodeEdit>() {
        if code_edit.is_visible_in_tree() {
            return Some(code_edit);
        }
    }

    // Search children
    let count = node.get_child_count();
    for i in 0..count {
        if let Some(child) = node.get_child(i) {
            if let Ok(control) = child.try_cast::<Control>() {
                if let Some(code_edit) = self.find_visible_code_edit(control) {
                    return Some(code_edit);
                }
            }
        }
    }

    None
}

pub(super) fn find_visible_code_edit_safe(&self, node: Gd<Control>) -> Option<Gd<CodeEdit>> {
    let editor = EditorInterface::singleton();
    let script_editor = editor.get_script_editor()?;
    let current_script = script_editor.get_current_script()?;
    let expected_path = current_script.get_path().to_string();

    if expected_path.is_empty() {
        return None;
    }

    // Find the CodeEdit
    let code_edit = self.find_visible_code_edit(node)?;

    // Verify: the CodeEdit should be in a visible tab that corresponds to current script
    // Get the first line and compare with script content
    let editor_first_line = if code_edit.get_line_count() > 0 {
        code_edit.get_line(0).to_string()
    } else {
        String::new()
    };

    let script_source = current_script.get_source_code().to_string();
    let script_first_line = script_source.lines().next().unwrap_or("");

    // If content matches, this is likely the correct CodeEdit
    if editor_first_line.trim() == script_first_line.trim() {
        crate::verbose_print!(
            "[godot-neovim] find_visible_code_edit_safe: content matches for '{}'",
            expected_path
        );
        Some(code_edit)
    } else {
        crate::verbose_print!(
            "[godot-neovim] find_visible_code_edit_safe: content mismatch, skipping"
        );
        None
    }
}

fn is_code_edit_in_script_editor(&self, code_edit: &Gd<CodeEdit>) -> bool {
    let mut current: Option<Gd<godot::classes::Node>> = code_edit.get_parent();

    while let Some(node) = current {
        let class_name = node.get_class().to_string();
        // Godot internal classes that wrap CodeEdits in the built-in ScriptEditor
        if class_name == "CodeTextEditor"
            || class_name == "ScriptTextEditor"
            || class_name == "ScriptEditor"
        {
            return true;
        }
        current = node.get_parent();
    }
    false
}

fn is_code_edit_in_shader_editor(&self, code_edit: &Gd<CodeEdit>) -> bool {
    let mut current: Option<Gd<godot::classes::Node>> = code_edit.get_parent();

    while let Some(node) = current {
        let class_name = node.get_class().to_string();
        // Check for shader-related class names
        // TextShaderEditor, ShaderTextEditor, ShaderEditor
        if class_name.contains("Shader") {
            crate::verbose_print!(
                "[godot-neovim] CodeEdit is in shader hierarchy: {}",
                class_name
            );
            return true;
        }
        current = node.get_parent();
    }
    false
}

fn get_shader_path_from_code_edit(&self, code_edit: &Gd<CodeEdit>) -> Option<String> {
    let mut current: Option<Gd<godot::classes::Node>> = code_edit.get_parent();
    let mut depth = 0;

    while let Some(mut node) = current {
        let class_name = node.get_class().to_string();
        let node_name = node.get_name().to_string();
        crate::verbose_print!(
            "[godot-neovim] Shader path search depth {}: {} ({})",
            depth,
            node_name,
            class_name
        );

        // Accept both the legacy split and the shared 4.8 document container.
        if matches!(
            class_name.as_str(),
            "HSplitContainer" | "DocumentEditorContainer"
        ) {
            if let Some(list) = super::editor_tree::document_list(&node) {
                if let Some(index) = list.get_selected_items().get(0) {
                    let path = list.get_item_tooltip(index).to_string();
                    if path.starts_with("res://") {
                        return Some(path);
                    }
                }
            }
        }

        // Check for shader-related classes that might have get_shader() or similar method
        // TextShaderEditor, ShaderTextEditor, or any class containing "Shader"
        if class_name.contains("Shader") {
            // Try multiple method names (Godot versions may differ)
            let method_names = ["get_shader", "get_edited_shader", "get_current_shader"];

            for method_name in method_names {
                if node.has_method(method_name) {
                    crate::verbose_print!(
                        "[godot-neovim]   {} has method '{}'",
                        class_name,
                        method_name
                    );
                    let result = node.call(method_name, &[]);
                    crate::verbose_print!(
                        "[godot-neovim]   {}() result type: {:?}",
                        method_name,
                        result.get_type()
                    );
                    if let Ok(shader) = result.try_to::<Gd<Resource>>() {
                        let path = shader.get_path().to_string();
                        crate::verbose_print!(
                            "[godot-neovim]   shader.get_path() = '{}'",
                            path
                        );
                        if !path.is_empty() {
                            crate::verbose_print!(
                                "[godot-neovim] Found shader path via {}.{}(): {}",
                                class_name,
                                method_name,
                                path
                            );
                            return Some(path);
                        }
                    }
                }
            }

            // Try get_shader_include() / get_edited_shader_include() for .gdshaderinc files
            let include_methods = ["get_shader_include", "get_edited_shader_include"];
            for method_name in include_methods {
                if node.has_method(method_name) {
                    let result_inc = node.call(method_name, &[]);
                    if let Ok(shader_inc) = result_inc.try_to::<Gd<Resource>>() {
                        let path = shader_inc.get_path().to_string();
                        if !path.is_empty() {
                            crate::verbose_print!(
                                "[godot-neovim] Found shader include path via {}.{}(): {}",
                                class_name,
                                method_name,
                                path
                            );
                            return Some(path);
                        }
                    }
                }
            }
        }

        current = node.get_parent();
        depth += 1;
    }
    crate::verbose_print!(
        "[godot-neovim] Shader path not found in hierarchy (searched {} levels)",
        depth

pub(super) fn focus_shader_editor_code_edit(&mut self) {
    // Find the ShaderEditor's visible CodeEdit
    let editor = EditorInterface::singleton();
    let Some(base_control) = editor.get_base_control() else {
        crate::verbose_print!("[godot-neovim] focus_shader_editor: no base_control");
        return;
    };

    // Find EditorNode to search for ShaderEditor
    let Some(editor_node) = self.find_editor_node(base_control.clone().upcast()) else {
        crate::verbose_print!("[godot-neovim] focus_shader_editor: no EditorNode found");
        return;
    };

    // Search for ShaderEditor's CodeEdit
    if let Some(mut code_edit) = self.find_shader_editor_code_edit(editor_node) {
        code_edit.grab_focus();
        crate::verbose_print!("[godot-neovim] Focused ShaderEditor CodeEdit after close");
    } else {
        crate::verbose_print!(
            "[godot-neovim] focus_shader_editor: no ShaderEditor CodeEdit found"
        );
    }
}

fn find_shader_editor_code_edit(&self, node: Gd<Node>) -> Option<Gd<CodeEdit>> {
    let class_name = node.get_class().to_string();

    // Look for ShaderTextEditor (contains CodeEdit for shaders)
    if class_name == "ShaderTextEditor" {
        return super::editor_tree::visible_code_edit(&node);
    }

    // Recursively search children
    let child_count = node.get_child_count();
    for i in 0..child_count {
        if let Some(child) = node.get_child(i) {
            // Skip hidden nodes for efficiency
            if let Ok(control) = child.clone().try_cast::<Control>() {
                if !control.is_visible() {
                    continue;
                }
            }
            if let Some(code_edit) = self.find_shader_editor_code_edit(child) {
                return Some(code_edit);
            }
        }
    }

    None
}

pub(super) fn get_script_editor_current_tab_path(
    &self,
    script_editor: &Gd<godot::classes::ScriptEditor>,
) -> Option<String> {
    use godot::classes::ItemList;

    // Find the ItemList in ScriptEditor (the file list on the left side)
    // Each item has a tooltip with the full resource path
    let node: Gd<godot::classes::Node> = script_editor.clone().upcast();

    fn find_item_list(node: &Gd<godot::classes::Node>) -> Option<Gd<ItemList>> {
        let class_name = node.get_class().to_string();

        if class_name == "ItemList" {
            if let Ok(item_list) = node.clone().try_cast::<ItemList>() {
                return Some(item_list);
            }
        }

        for i in 0..node.get_child_count() {
            if let Some(child) = node.get_child(i) {
                if let Some(found) = find_item_list(&child) {
                    return Some(found);
                }
            }
        }
        None
    }

    if let Some(item_list) = find_item_list(&node) {
        // Get selected items (should be the current script/file)
        let selected = item_list.get_selected_items();
        if !selected.is_empty() {
            if let Some(idx) = selected.get(0) {
                let tooltip = item_list.get_item_tooltip(idx).to_string();
                crate::verbose_print!(
                    "[godot-neovim] Got path from ItemList tooltip: {}",
                    tooltip
                );
                if !tooltip.is_empty() {
                    return Some(tooltip);
                }
            }
        }
    }

    None
}

pub(super) fn menu_item_id(popup: &Gd<PopupMenu>, shortcut_path: &str) -> Option<i32> {
    let mut settings = EditorInterface::singleton().get_editor_settings()?;
    if !settings.has_method("get_shortcut") {
        // Older engines do not bind EditorSettings.get_shortcut. Resource names
        // are the untranslated TTRC strings, even when menu labels are translated.
        let name = match shortcut_path {
            "script_editor/save" => "Save",
            "script_editor/save_all" => "Save All",
            "script_editor/close_file" => "Close",
            "script_editor/close_all" => "Close All",
            "shader_editor/open" | "script_editor/open_shader" => "Load Shader File...",
            _ => return None,
        };
        return (0..popup.get_item_count()).find_map(|index| {
            popup.get_item_shortcut(index).and_then(|shortcut| {
                (shortcut.get_name() == name).then(|| popup.get_item_id(index))
            })
        });
    }
    let shortcut = settings
        .call("get_shortcut", &[shortcut_path.to_variant()])
        .try_to::<Gd<Shortcut>>()
        .ok()?;
    (0..popup.get_item_count()).find_map(|index| {
        (popup.get_item_shortcut(index).as_ref() == Some(&shortcut))
            .then(|| popup.get_item_id(index))
    })
}

pub(super) fn find_menu(node: &Gd<Node>, shortcut_path: &str) -> Option<Gd<PopupMenu>> {
    if let Ok(button) = node.clone().try_cast::<MenuButton>() {
        let popup = button.get_popup()?;
        if menu_item_id(&popup, shortcut_path).is_some() {
            return Some(popup);
        }
    }
    for child in node.get_children().iter_shared() {
        if let Some(popup) = find_menu(&child, shortcut_path) {
            return Some(popup);
        }
    }
    None
}

pub(super) fn emit_menu_action(mut popup: Gd<PopupMenu>, shortcut_path: &str) -> bool {
    let Some(id) = menu_item_id(&popup, shortcut_path) else {
        return false;
    };
    popup.call_deferred("emit_signal", &["id_pressed".to_variant(), id.to_variant()]);
    true
}

pub(super) fn document_list(node: &Gd<Node>) -> Option<Gd<ItemList>> {
    for child in node.get_children().iter_shared() {
        if let Ok(list) = child.clone().try_cast::<ItemList>() {
            return Some(list);
        }
        // Do not enter editor tabs or the outline, which may contain unrelated lists.
        let class = child.get_class().to_string();
        if matches!(
            class.as_str(),
            "VBoxContainer" | "HSplitContainer" | "VSplitContainer" | "DocumentList"
        ) {
            if let Some(list) = document_list(&child) {
                return Some(list);
            }
        }
    }
    None
}

pub(super) fn find_shader_container(node: &Gd<Node>) -> Option<Gd<Node>> {
    let class = node.get_class().to_string();
    let shortcut = match class.as_str() {
        // Early 4.8 builds used a second ScriptEditor for shaders.
        "DocumentEditorContainer" | "ScriptEditor" => Some("script_editor/open_shader"),
        "HSplitContainer" => Some("shader_editor/open"),
        _ => None,
    };
    if let Some(shortcut) = shortcut {
        if document_list(node).is_some() && find_menu(node, shortcut).is_some() {
            return Some(node.clone());
        }
    }
    for child in node.get_children().iter_shared() {
        if let Some(container) = find_shader_container(&child) {
            return Some(container);
        }
    }
    None
}

pub(super) fn visible_code_edit(node: &Gd<Node>) -> Option<Gd<CodeEdit>> {
    if let Ok(editor) = node.clone().try_cast::<CodeEdit>() {
        return editor.is_visible_in_tree().then_some(editor);
    }
    for child in node.get_children().iter_shared() {
        if let Some(editor) = visible_code_edit(&child) {
            return Some(editor);
        }
    }
    None
}

impl GodotNeovimPlugin {
    pub(in crate::plugin) fn handle_command_mode_input(
        &mut self,
        key_event: &Gd<godot::classes::InputEventKey>,
    ) {
        let keycode = key_event.get_keycode();
        let ctrl_pressed = key_event.is_ctrl_pressed();

        // Escape or Ctrl+[ closes command line
        if keycode == Key::ESCAPE || (ctrl_pressed && keycode == Key::BRACKETLEFT) {
            self.close_command_line();
        } else if keycode == Key::ENTER {
            self.execute_command();
        } else if keycode == Key::BACKSPACE {
            // Remove last character (but keep the ':')
            if self.command_buffer.len() > 1 {
                self.command_buffer.pop();
                self.update_command_display();
            }
            // Reset history browsing when editing
            self.command_history_index = None;
        } else if keycode == Key::UP {
            // Browse command history (older)
            self.command_history_up();
        } else if keycode == Key::DOWN {
            // Browse command history (newer)
            self.command_history_down();
        } else {
            // Append character to command buffer
            let unicode = key_event.get_unicode();
            if unicode > 0 {
                if let Some(c) = char::from_u32(unicode) {
                    self.command_buffer.push(c);
                    self.update_command_display();
                    // Reset history browsing when typing
                    self.command_history_index = None;
                }
            }
        }

        if let Some(mut viewport) = self.base().get_viewport() {
            viewport.set_input_as_handled();
        }
    }
}

fn mark_input_handled(&self) {
    if let Some(mut viewport) = self.base().get_viewport() {
        viewport.set_input_as_handled();
    }
}

fn resolve_custom_modified_key(
    &self,
    key_event: &Gd<godot::classes::InputEventKey>,
) -> Option<VarDictionary> {
    if self.is_alt_composed_unicode(key_event) {
        return None;
    }
    let notation = self.modified_key_notation(key_event)?;
    let custom = if Self::is_visual_mode(&self.current_mode) {
        &self.custom_visual_keys
    } else {
        &self.custom_normal_keys
    };
    if custom.contains(&notation) {
        return Some(self.dispatch_key(&notation));
    }
    if key_event.is_meta_pressed() {
        return Some(self.dispatch_pass_through());
    }
    None
}

fn resolve_dispatchable_single_key(
    &self,
    key_event: &Gd<godot::classes::InputEventKey>,
) -> Option<String> {
    let keycode = key_event.get_keycode();
    let unicode_char = char::from_u32(key_event.get_unicode());
    let ctrl = key_event.is_ctrl_pressed();
    let shift = key_event.is_shift_pressed();

    if ctrl {
        return None;
    }

    // '/' - forward search
    if unicode_char == Some('/') {
        return Some("/".to_string());
    }
    // '?' - backward search
    if unicode_char == Some('?') {
        return Some("?".to_string());
    }
    // ':' - command line
    if unicode_char == Some(':') {
        return Some(":".to_string());
    }
    // '*' - search word forward
    if unicode_char == Some('*') {
        return Some("*".to_string());
    }
    // '#' - search word backward
    if unicode_char == Some('#') {
        return Some("#".to_string());
    }
    // 'n' - search next (not Shift)
    if keycode == Key::N && !shift {
        return Some("n".to_string());
    }
    // 'N' - search previous (Shift+N)
    if keycode == Key::N && shift {
        return Some("N".to_string());
    }
    // 'u' - undo (not Shift, not after 'g' prefix which is gu = lowercase operator)
    if keycode == Key::U && !shift && self.last_key != "g" {
        return Some("u".to_string());
    }
    // 'K' - documentation (Shift+K, not after 'g' prefix which is gK)
    if keycode == Key::K && shift && self.last_key != "g" {
        return Some("K".to_string());
    }

    None
}

fn handle_side_effect_keys(
    &mut self,
    key_event: &Gd<godot::classes::InputEventKey>,
) -> Option<VarDictionary> {
    let keycode = key_event.get_keycode();
    let unicode_char = char::from_u32(key_event.get_unicode());

    // ';' - repeat find char same direction
    if keycode == Key::SEMICOLON && !key_event.is_shift_pressed() {
        self.repeat_find_char(true);
        self.send_keys(";");
        if self.recording_macro.is_some() && !self.playing_macro {
            self.macro_buffer.push(";".to_string());
        }
        return Some(self.dispatch_handled());
    }

    // ',' - repeat find char opposite direction
    if keycode == Key::COMMA && !key_event.is_shift_pressed() {
        self.repeat_find_char(false);
        self.send_keys(",");
        if self.recording_macro.is_some() && !self.playing_macro {
            self.macro_buffer.push(",".to_string());
        }
        return Some(self.dispatch_handled());
    }

    // '%' - matching bracket
    if unicode_char == Some('%') {
        self.jump_to_matching_bracket();
        self.send_keys("%");
        if self.recording_macro.is_some() && !self.playing_macro {
            self.macro_buffer.push("%".to_string());
        }
        return Some(self.dispatch_handled());
    }

    // '0' - go to start of line (only when not part of a count, not after g)
    if unicode_char == Some('0') && !key_event.is_ctrl_pressed() && self.last_key != "g" {
        self.move_to_line_start();
        self.send_keys("0");
        return Some(self.dispatch_handled());
    }

    // '^' - go to first non-blank (not after g)
    if unicode_char == Some('^') && self.last_key != "g" {
        self.move_to_first_non_blank();
        self.send_keys("^");
        return Some(self.dispatch_handled());
    }

    // '$' - go to end of line (not after g)
    if unicode_char == Some('$') && self.last_key != "g" {
        self.move_to_line_end();
        self.send_keys("$");
        return Some(self.dispatch_handled());
    }

    // 'J' - join lines (not after g - that's gJ)
    if keycode == Key::J
        && key_event.is_shift_pressed()
        && !key_event.is_ctrl_pressed()
        && self.last_key != "g"
    {
        self.send_keys("J");
        return Some(self.dispatch_handled());
    }

    // H/M/L - viewport-relative movement
    if !key_event.is_ctrl_pressed()
        && !key_event.is_alt_pressed()
        && (keycode == Key::H || keycode == Key::M || keycode == Key::L)
        && key_event.is_shift_pressed()
    {
        let key_str = match keycode {
            Key::H => "H",
            Key::M => "M",
            Key::L => "L",
            _ => unreachable!(),
        };
        self.send_keys(key_str);
        return Some(self.dispatch_handled());
    }

    // 'R' - enter replace mode
    if keycode == Key::R && key_event.is_shift_pressed() && !key_event.is_ctrl_pressed() {
        if self.recording_macro.is_some() && !self.playing_macro {
            self.macro_buffer.push("R".to_string());
        }
        self.enter_replace_mode();
        return Some(self.dispatch_handled());
    }

    None
}

fn handle_operator_keys(
    &mut self,
    key_event: &Gd<godot::classes::InputEventKey>,
) -> Option<VarDictionary> {
    let unicode_char = char::from_u32(key_event.get_unicode());

    // '>' - indent operator
    if unicode_char == Some('>') {
        if self.last_key == ">" {
            self.send_keys(">>");
            self.clear_last_key();
            if self.recording_macro.is_some() && !self.playing_macro {
                self.macro_buffer.push(">>".to_string());
            }
        } else {
            self.set_last_key(">");
        }
        return Some(self.dispatch_handled());
    }

    // '<' - unindent operator
    if unicode_char == Some('<') {
        if self.last_key == "<" {
            self.send_keys("<LT><LT>");
            self.clear_last_key();
            if self.recording_macro.is_some() && !self.playing_macro {
                self.macro_buffer.push("<<".to_string());
            }
        } else {
            self.set_last_key("<");
        }
        return Some(self.dispatch_handled());
    }

    None
}

fn handle_prefix_key_accumulation(
    &mut self,
    key_event: &Gd<godot::classes::InputEventKey>,
) -> Option<VarDictionary> {
    let keycode = key_event.get_keycode();
    let unicode_char = char::from_u32(key_event.get_unicode());

    // 'g' prefix (not after another g - allow gg)
    if unicode_char == Some('g')
        && !key_event.is_ctrl_pressed()
        && !key_event.is_shift_pressed()
        && self.last_key != "g"
    {
        self.set_last_key("g");
        return Some(self.dispatch_handled());
    }

    // '[' prefix (not after [ or ])
    if keycode == Key::BRACKETLEFT
        && !key_event.is_shift_pressed()
        && !key_event.is_ctrl_pressed()
        && self.last_key != "["
        && self.last_key != "]"
    {
        self.set_last_key("[");
        return Some(self.dispatch_handled());
    }

    // ']' prefix (not after [ or ])
    if keycode == Key::BRACKETRIGHT
        && !key_event.is_shift_pressed()
        && !key_event.is_ctrl_pressed()
        && self.last_key != "["
        && self.last_key != "]"
    {
        self.set_last_key("]");
        return Some(self.dispatch_handled());
    }

    // 'Z' prefix (Shift+Z)
    if keycode == Key::Z
        && key_event.is_shift_pressed()
        && !key_event.is_ctrl_pressed()
        && self.last_key != "Z"
    {
        self.set_last_key("Z");
        return Some(self.dispatch_handled());
    }

    None
}

pub(in crate::plugin) fn process_insert_key_event_impl(
    &mut self,
    key_event: &Gd<godot::classes::InputEventKey>,
) -> VarDictionary {
    self.process_insert_replace_key_event(key_event, false)
}

pub(in crate::plugin) fn process_replace_key_event_impl(
    &mut self,
    key_event: &Gd<godot::classes::InputEventKey>,
) -> VarDictionary {
    self.insert_escape_pending = None;
    self.process_insert_replace_key_event(key_event, true)
}

fn handle_pending_insert_register(
    &mut self,
    key_event: &Gd<godot::classes::InputEventKey>,
) -> VarDictionary {
    let keycode = key_event.get_keycode();
    let ctrl = key_event.is_ctrl_pressed();

    // Esc / Ctrl+[ cancels the pending register (no `<C-r>` was sent yet)
    // AND exits insert mode — in Neovim, <C-r><Esc> aborts the register
    // prompt and the Esc still takes effect, returning to normal mode.
    if keycode == Key::ESCAPE || (ctrl && keycode == Key::BRACKETLEFT) {
        self.pending_insert_register = false;
        if self.recording_macro.is_some() && !self.playing_macro {
            self.macro_buffer.push("<Esc>".to_string());
        }
        self.send_escape();
        return self.dispatch_handled();
    }

    let register_key = self.key_event_to_nvim_notation(key_event);
    if register_key.is_empty() {
        // Modifier-only press — keep waiting for the register character.
        return self.dispatch_handled();
    }
    self.pending_insert_register = false;

    let full = format!("<C-r>{}", register_key);
    if self.recording_macro.is_some() && !self.playing_macro {
        self.macro_buffer.push(full.clone());
    }
    self.send_keys(&full);

    self.dispatch_handled()
}

fn record_plain_insert_key(&mut self, key_event: &Gd<godot::classes::InputEventKey>) {
    if self.recording_macro.is_none() || self.playing_macro {
        return;
    }
    match key_event.get_keycode() {
        Key::BACKSPACE => self.macro_buffer.push("<BS>".to_string()),
        Key::ENTER => self.macro_buffer.push("<CR>".to_string()),
        Key::DELETE => self.macro_buffer.push("<Del>".to_string()),
        Key::TAB => self.macro_buffer.push("<Tab>".to_string()),
        _ => {
            let unicode = key_event.get_unicode();
            if unicode > 0 {
                if let Some(c) = char::from_u32(unicode) {
                    self.macro_buffer.push(c.to_string());
                }
            }
        }
    }
}

fn apply_replace_overwrite(&mut self, key_event: &Gd<godot::classes::InputEventKey>) {
    let unicode = key_event.get_unicode();
    if unicode == 0 {
        return;
    }
    let Some(ref mut editor) = self.current_editor else {
        return;
    };
    let line = editor.get_caret_line();
    let col = editor.get_caret_column();
    let line_text: String = editor.get_line(line).to_string();
    if (col as usize) < line_text.chars().count() {
        editor.select(line, col, line, col + 1);
        editor.delete_selection();
    }
}

pub(in crate::plugin) fn handle_pending_char_op(
    &mut self,
    key_event: &Gd<godot::classes::InputEventKey>,
) -> bool {
    let Some(op) = self.pending_char_op else {
        return false;
    };

    let keycode = key_event.get_keycode();

    // Ignore modifier-only key presses (SHIFT, CTRL, ALT, META keys themselves)
    // These are pressed before the actual character key and should not cancel the operation
    if matches!(
        keycode,
        Key::SHIFT | Key::CTRL | Key::ALT | Key::META | Key::CAPSLOCK | Key::NUMLOCK
    ) {
        // Don't consume the event, but don't cancel either - wait for actual character
        return false;
    }

    // Cancel on Escape or any modifier key combination (Ctrl+X, Alt+X, etc.)
    if keycode == Key::ESCAPE
        || key_event.is_ctrl_pressed()
        || key_event.is_alt_pressed()
        || key_event.is_meta_pressed()
    {
        self.pending_char_op = None;
        crate::verbose_print!(
            "[godot-neovim] Cancelled pending char op '{}' due to modifier/escape",
            op
        );
        // Don't consume the event - let it be processed normally
        return false;
    }

    // Get the character
    let unicode = key_event.get_unicode();
    if unicode > 0 {
        if let Some(c) = char::from_u32(unicode) {
            self.pending_char_op = None;
            // Build the key sequence for f/F/t/T
            let keys = match op {
                'f' | 'F' | 't' | 'T' | 'r' => Some(format!("{}{}", op, c)),
                _ => None,
            };

            match op {
                'f' => self.find_char_forward(c, false),
                'F' => self.find_char_backward(c, false),
                't' => self.find_char_forward(c, true),
                'T' => self.find_char_backward(c, true),
                // 'r' is sent to Neovim via keys above (Neovim Master design)
                _ => {}
            }

            // Send to Neovim and record to local macro buffer
            if let Some(keys) = keys {
                self.send_keys(&keys);
                // Record to local macro buffer (early return skips normal recording)
                if self.recording_macro.is_some() && !self.playing_macro {
                    self.macro_buffer.push(keys);
                }
            }
            if let Some(mut viewport) = self.base().get_viewport() {
                viewport.set_input_as_handled();
            }
            return true;
        }
    }

    // Non-printable key pressed - cancel the pending operation
    self.pending_char_op = None;
    crate::verbose_print!(
        "[godot-neovim] Cancelled pending char op '{}' due to non-printable key",
        op
    );
    false
}

pub(in crate::plugin) fn handle_pending_mark_op(
    &mut self,
    key_event: &Gd<godot::classes::InputEventKey>,
) -> bool {
    let Some(op) = self.pending_mark_op else {
        return false;
    };

    let keycode = key_event.get_keycode();

    // Ignore modifier-only key presses (SHIFT, CTRL, ALT, META keys themselves)
    if matches!(
        keycode,
        Key::SHIFT | Key::CTRL | Key::ALT | Key::META | Key::CAPSLOCK | Key::NUMLOCK
    ) {
        return false;
    }

    // Cancel on Escape or any modifier key combination
    if keycode == Key::ESCAPE
        || key_event.is_ctrl_pressed()
        || key_event.is_alt_pressed()
        || key_event.is_meta_pressed()
    {
        self.pending_mark_op = None;
        crate::verbose_print!(
            "[godot-neovim] Cancelled pending mark op '{}' due to modifier/escape",
            op
        );
        // Don't consume the event - let it be processed normally
        return false;
    }

    // Get the character (must be a-z for marks)
    let unicode = key_event.get_unicode();
    if unicode > 0 {
        if let Some(c) = char::from_u32(unicode) {
            if c.is_ascii_lowercase() {
                self.pending_mark_op = None;
                match op {
                    'm' => self.set_mark(c),
                    '\'' => self.jump_to_mark_line(c),
                    '`' => self.jump_to_mark_position(c),
                    _ => {}
                }
                if let Some(mut viewport) = self.base().get_viewport() {
                    viewport.set_input_as_handled();
                }
                return true;
            }
            // Non a-z character - cancel and let it be processed normally
            self.pending_mark_op = None;
            crate::verbose_print!(
                "[godot-neovim] Cancelled pending mark op '{}' - invalid mark char '{}'",
                op,
                c
            );
            return false;
        }
    }

    // Non-printable key pressed - cancel the pending operation
    self.pending_mark_op = None;
    crate::verbose_print!(
        "[godot-neovim] Cancelled pending mark op '{}' due to non-printable key",
        op
    );
    false
}

pub(in crate::plugin) fn handle_pending_macro_op(
    &mut self,
    key_event: &Gd<godot::classes::InputEventKey>,
) -> bool {
    let Some(op) = self.pending_macro_op else {
        return false;
    };

    let keycode = key_event.get_keycode();

    // Ignore modifier-only key presses (SHIFT, CTRL, ALT, META keys themselves)
    if matches!(
        keycode,
        Key::SHIFT | Key::CTRL | Key::ALT | Key::META | Key::CAPSLOCK | Key::NUMLOCK
    ) {
        return false;
    }

    // Cancel on Escape or any modifier key combination
    if keycode == Key::ESCAPE
        || key_event.is_ctrl_pressed()
        || key_event.is_alt_pressed()
        || key_event.is_meta_pressed()
    {
        self.pending_macro_op = None;
        crate::verbose_print!(
            "[godot-neovim] Cancelled pending macro op '{}' due to modifier/escape",
            op
        );
        // Don't consume the event - let it be processed normally
        return false;
    }

    // Get the character
    let unicode = key_event.get_unicode();
    if unicode > 0 {
        if let Some(c) = char::from_u32(unicode) {
            self.pending_macro_op = None;
            match op {
                'q' => {
                    // Start recording if a-z
                    if c.is_ascii_lowercase() {
                        self.start_macro_recording(c);
                    } else {
                        crate::verbose_print!(
                            "[godot-neovim] Macro recording cancelled - invalid register '{}'",
                            c
                        );
                    }
                }
                '@' => {
                    if c == '@' {
                        // @@ - replay last macro
                        self.replay_last_macro();
                    } else if c == ':' {
                        // @: - repeat last Ex command
                        self.repeat_last_ex_command();
                    } else if c.is_ascii_lowercase() {
                        // @{a-z} - play specific macro
                        self.play_macro(c);
                    } else {
                        crate::verbose_print!(
                            "[godot-neovim] Macro playback cancelled - invalid register '{}'",
                            c
                        );
                    }
                }
                _ => {}
            }
            if let Some(mut viewport) = self.base().get_viewport() {
                viewport.set_input_as_handled();
            }
            return true;
        }
    }

    // Non-printable key pressed - cancel the pending operation
    self.pending_macro_op = None;
    crate::verbose_print!(
        "[godot-neovim] Cancelled pending macro op '{}' due to non-printable key",
        op
    );
    false
}

pub(in crate::plugin) fn handle_pending_register(
    &mut self,
    key_event: &Gd<godot::classes::InputEventKey>,
) -> bool {
    if self.selected_register != Some('\0') {
        return false;
    }

    let keycode = key_event.get_keycode();

    // Cancel on Escape
    if keycode == Key::ESCAPE {
        self.selected_register = None;
        if let Some(mut viewport) = self.base().get_viewport() {
            viewport.set_input_as_handled();
        }
        return true;
    }

    // Get the character
    // Valid registers: a-z (named), " (unnamed), + and * (clipboard), _ (black hole), 0 (yank)
    let unicode = key_event.get_unicode();
    if unicode > 0 {
        if let Some(c) = char::from_u32(unicode) {
            let is_valid_register = c.is_ascii_lowercase()
                || c == '"'
                || c == '+'
                || c == '*'
                || c == '_'
                || c == '0';
            if is_valid_register {
                self.selected_register = Some(c);
                crate::verbose_print!("[godot-neovim] \"{}: Register selected", c);
                if let Some(mut viewport) = self.base().get_viewport() {
                    viewport.set_input_as_handled();
                }
                return true;
            }
        }
    }
    false
}

impl GodotNeovimPlugin {
    pub(in crate::plugin) fn handle_search_mode_input(
        &mut self,
        key_event: &Gd<godot::classes::InputEventKey>,
    ) {
        let keycode = key_event.get_keycode();

        if keycode == Key::ESCAPE {
            self.close_search_mode();
        } else if keycode == Key::ENTER {
            self.execute_search();
        } else if keycode == Key::BACKSPACE {
            // Remove last character (but keep the '/' or '?')
            if self.search_buffer.len() > 1 {
                self.search_buffer.pop();
                self.update_search_display();
            }
        } else {
            // Append character to search buffer
            let unicode = key_event.get_unicode();
            if unicode > 0 {
                if let Some(c) = char::from_u32(unicode) {
                    self.search_buffer.push(c);
                    self.update_search_display();
                }
            }
        }

        if let Some(mut viewport) = self.base().get_viewport() {
            viewport.set_input_as_handled();
        }
    }
}

pub(super) fn resolve_insert_escape(&mut self, event: &Gd<InputEventKey>) -> bool {
    let pending = self.insert_escape_pending.take();
    if self.insert_escape_keys.is_empty() {
        return false;
    }
    let notation = self.key_event_to_nvim_string(event).unwrap_or_default();
    if notation.starts_with('<')
        && !self.is_alt_composed_unicode(event)
        && self.insert_escape_keys.contains(&notation)
    {
        self.record_insert_escape();
        return true;
    }
    if event.is_ctrl_pressed() || event.is_alt_pressed() || event.is_meta_pressed() {
        return false;
    }
    let Some(character) = char::from_u32(event.get_unicode()).filter(|c| !c.is_control())
    else {
        // Modifier-only presses do not interrupt a shifted sequence.
        if matches!(event.get_keycode(), godot::global::Key::SHIFT) {
            self.insert_escape_pending = pending;
        }
        return false;
    };
    let Some(mut editor) = self.current_editor.clone() else {
        return false;
    };
    if editor.has_selection() || editor.get_caret_count() != 1 {
        return false;
    }
    let line = editor.get_caret_line();
    let column = editor.get_caret_column();
    let text = editor.get_line(line).to_string();
    let previous = pending
        .as_ref()
        .filter(|p| {
            p.editor == editor
                && p.line == line
                && p.column == column
                && p.text == text
                && p.time.elapsed() < Duration::from_millis(1000)
        })
        .map(|p| p.prefix.as_str())
        .unwrap_or("");
    let (matched, prefix) = resolve_sequence(previous, character, &self.insert_escape_keys);
    if matched {
        let count = prefix.chars().count() - 1;
        if count > 0 {
            // The final character is consumed; remove only the verified prefix.
            editor.remove_text(line, column - count as i32, line, column);
            editor.set_caret_column(column - count as i32);
            if self.recording_macro.is_some() && !self.playing_macro {
                self.macro_buffer
                    .truncate(self.macro_buffer.len().saturating_sub(count));
            }
        }
        self.record_insert_escape();
        return true;
    }
    if !prefix.is_empty() {
        let mut expected: Vec<char> = text.chars().collect();
        expected.insert(column as usize, character);
        self.insert_escape_pending = Some(PendingEscape {
            editor,
            line,
            column: column + 1,
            text: expected.into_iter().collect(),
            prefix,
            time: Instant::now(),
        });
    }
    false
}

pub(super) fn is_alt_composed_unicode(&self, event: &Gd<InputEventKey>) -> bool {
    if !event.is_alt_pressed() {
        return false;
    }
    let unicode = event.get_unicode();
    if unicode == 0 {
        return false;
    }
    let Some(uc) = char::from_u32(unicode) else {
        return false;
    };
    let Some(kc) = char::from_u32(event.get_keycode().ord() as u32) else {
        return false;
    };
    !kc.eq_ignore_ascii_case(&uc)
}

pub(super) fn modified_key_notation(&self, event: &Gd<InputEventKey>) -> Option<String> {
    let ctrl = event.is_ctrl_pressed();
    let alt = event.is_alt_pressed();
    let meta = event.is_meta_pressed();
    let shift = event.is_shift_pressed();
    if !(ctrl || alt || meta) {
        return None;
    }

    let keycode = event.get_keycode();
    let ord = keycode.ord();
    let base = match keycode {
        Key::ESCAPE => "Esc".to_string(),
        Key::ENTER => "CR".to_string(),
        Key::TAB => "Tab".to_string(),
        Key::BACKSPACE => "BS".to_string(),
        Key::DELETE => "Del".to_string(),
        Key::UP => "Up".to_string(),
        Key::DOWN => "Down".to_string(),
        Key::LEFT => "Left".to_string(),
        Key::RIGHT => "Right".to_string(),
        Key::HOME => "Home".to_string(),
        Key::END => "End".to_string(),
        Key::PAGEUP => "PageUp".to_string(),
        Key::PAGEDOWN => "PageDown".to_string(),
        Key::SPACE => "Space".to_string(),
        _ if (Key::A.ord()..=Key::Z.ord()).contains(&ord)
            || (Key::KEY_0.ord()..=Key::KEY_9.ord()).contains(&ord) =>
        {
            let c = char::from_u32(ord as u32)?.to_ascii_lowercase();
            c.to_string()
        }
        _ => {
            // Punctuation: the unicode value already reflects Shift.
            let c = char::from_u32(event.get_unicode()).filter(|c| !c.is_control())?;
            return Some(Self::format_modified_key(
                ctrl,
                alt,
                false,
                meta,
                &c.to_string(),
            ));
        }
    };
    // Shift is significant for letters/digits and special keys.
    Some(Self::format_modified_key(ctrl, alt, shift, meta, &base))
}

pub(super) fn key_event_to_nvim_string(&self, event: &Gd<InputEventKey>) -> Option<String> {
    let keycode = event.get_keycode();
    let ctrl = event.is_ctrl_pressed();
    let alt = event.is_alt_pressed();
    let shift = event.is_shift_pressed();

    // Ctrl+[ is equivalent to Escape (terminal standard)
    if ctrl && keycode == Key::BRACKETLEFT {
        return Some("<Esc>".to_string());
    }

    // Handle special keys
    let key_str = match keycode {
        Key::ESCAPE => "<Esc>".to_string(),
        Key::ENTER => "<CR>".to_string(),
        Key::TAB => "<Tab>".to_string(),
        Key::BACKSPACE => "<BS>".to_string(),
        Key::DELETE => "<Del>".to_string(),
        Key::UP => "<Up>".to_string(),
        Key::DOWN => "<Down>".to_string(),
        Key::LEFT => "<Left>".to_string(),
        Key::RIGHT => "<Right>".to_string(),
        Key::HOME => "<Home>".to_string(),
        Key::END => "<End>".to_string(),
        Key::PAGEUP => "<PageUp>".to_string(),
        Key::PAGEDOWN => "<PageDown>".to_string(),
        // Note: F1-F12 are intentionally NOT mapped - let Godot handle them
        // F1 opens :help in Neovim which causes freezes
        Key::SPACE => " ".to_string(),
        _ => {
            // Get unicode character
            let unicode = event.get_unicode();
            if unicode > 0 {
                let c = char::from_u32(unicode)?;
                // Apply shift modifier for letters (get_unicode may not include shift)
                if shift && c.is_ascii_lowercase() {
                    c.to_ascii_uppercase().to_string()
                } else {
                    c.to_string()
                }
            } else {
                return None;
            }
        }
    };

    // Apply modifiers
    let result = if ctrl || alt {
        let mut mods = String::new();
        if ctrl {
            mods.push('C');
        }
        if alt {
            mods.push('A');
        }
        if shift && key_str.len() == 1 {
            mods.push('S');
        }

        if key_str.starts_with('<') {
            // Already a special key
            format!("<{}-{}>", mods, &key_str[1..key_str.len() - 1])
        } else {
            format!("<{}-{}>", mods, key_str)
        }
    } else {
        key_str
    };

    Some(result)
}

pub(super) fn key_event_to_nvim_notation(&self, key_event: &Gd<InputEventKey>) -> String {
    let keycode = key_event.get_keycode();
    let unicode = key_event.get_unicode();
    let ctrl = key_event.is_ctrl_pressed();
    let alt = key_event.is_alt_pressed();
    let shift = key_event.is_shift_pressed();

    // Handle special keys
    let special = match keycode {
        Key::BACKSPACE => Some("<BS>"),
        Key::TAB => Some("<Tab>"),
        Key::ENTER => Some("<CR>"),
        Key::DELETE => Some("<Del>"),
        Key::HOME => Some("<Home>"),
        Key::END => Some("<End>"),
        Key::PAGEUP => Some("<PageUp>"),
        Key::PAGEDOWN => Some("<PageDown>"),
        Key::UP => Some("<Up>"),
        Key::DOWN => Some("<Down>"),
        Key::LEFT => Some("<Left>"),
        Key::RIGHT => Some("<Right>"),
        // Note: F1-F12 are intentionally NOT mapped - let Godot handle them
        _ => None,
    };

    if let Some(key_str) = special {
        // Add modifiers to special keys
        if ctrl || alt || shift {
            let mut modifiers = String::new();
            if ctrl {
                modifiers.push_str("C-");
            }
            if alt {
                modifiers.push_str("A-");
            }
            if shift {
                modifiers.push_str("S-");
            }
            // Convert <Key> to <C-A-S-Key>
            let inner = &key_str[1..key_str.len() - 1];
            return format!("<{}{}>", modifiers, inner);
        }
        return key_str.to_string();
    }

    // Handle printable characters
    if unicode > 0 {
        if let Some(c) = char::from_u32(unicode) {
            // Ctrl+letter combinations
            if ctrl && !alt {
                let base_char = c.to_ascii_lowercase();
                if base_char.is_ascii_alphabetic() {
                    return format!("<C-{}>", base_char);
                }
            }
            // Alt combinations
            if alt && !ctrl {
                return format!("<A-{}>", c);
            }
            // Ctrl+Alt combinations
            if ctrl && alt {
                return format!("<C-A-{}>", c);
            }
            // Regular character (shift is already applied in unicode)
            return c.to_string();
        }
    }

    String::new()
}

impl GodotNeovimPlugin {
    /// Execute a process_*_key_event_impl result that requests keymap dispatch.
    /// With a GDScript handler registered, defer the lookup via call_deferred
    /// (a direct Callable invocation would re-enter &mut self). Without one,
    /// resolve against the built-in default keymap (input/builtin.rs).
    fn handle_dispatch_result(&mut self, result: VarDictionary) {
        if !result.get_or_nil("needs_dispatch").to::<bool>() {
            return;
        }
        let resolved_key = result.get_or_nil("resolved_key");
        let mode = result.get_or_nil("mode");
        if self.input_handler.is_some() {
            self.base_mut()
                .call_deferred("_dispatch_key_to_gdscript", &[resolved_key, mode]);
        } else {
            let mode = mode.to::<GString>().to_string();
            let key = resolved_key.to::<GString>().to_string();
            self.dispatch_key_builtin(&mode, &key);
        }
    }
}

fn activate_plugin_impl(&mut self) {
    crate::verbose_print!("[godot-neovim] v{} activating", VERSION);

    // Initialize settings first
    settings::initialize_settings();

    // Validate Neovim path
    let validation = settings::validate_current_path();
    if !validation.is_valid() {
        godot_warn!("[godot-neovim] Neovim validation failed, plugin may not work correctly");
    }

    // Get addons path for Lua plugin
    let addons_path = ProjectSettings::singleton()
        .globalize_path("res://addons/godot-neovim")
        .to_string();

    // Initialize Neovim client for ScriptEditor
    match NeovimClient::new() {
        Ok(mut client) => {
            if let Err(e) = client.start(Some(&addons_path)) {
                godot_error!(
                    "[godot-neovim] Failed to start Neovim for ScriptEditor: {}",
                    e
                );
                return;
            }
            self.script_neovim = Some(Mutex::new(client));
            crate::verbose_print!("[godot-neovim] ScriptEditor Neovim initialized");
        }
        Err(e) => {
            godot_error!(
                "[godot-neovim] Failed to create Neovim client for ScriptEditor: {}",
                e
            );
            return;
        }
    }

    // Initialize Neovim client for ShaderEditor (separate instance)
    match NeovimClient::new() {
        Ok(mut client) => {
            if let Err(e) = client.start(Some(&addons_path)) {
                godot_error!(
                    "[godot-neovim] Failed to start Neovim for ShaderEditor: {}",
                    e
                );
                // Continue with ScriptEditor only
            } else {
                self.shader_neovim = Some(Mutex::new(client));
                crate::verbose_print!("[godot-neovim] ShaderEditor Neovim initialized");
            }
        }
        Err(e) => {
            godot_warn!(
                "[godot-neovim] Failed to create Neovim client for ShaderEditor: {}",
                e
            );
            // Continue with ScriptEditor only
        }
    }

    // Create LSP client only if use_thread is enabled in editor settings
    // (LSP server won't respond without threading enabled)
    let use_thread = EditorInterface::singleton()
        .get_editor_settings()
        .map(|settings| {
            settings
                .get_setting("network/language_server/use_thread")
                .try_to::<bool>()
                .unwrap_or(false)
        })
        .unwrap_or(false);

    if use_thread {
        let lsp_client = Arc::new(GodotLspClient::new());
        self.godot_lsp = Some(lsp_client);
        self.lsp_connected = true;
        crate::verbose_print!("[godot-neovim] LSP client initialized (use_thread=true)");
    } else {
        crate::verbose_print!("[godot-neovim] LSP disabled (use_thread=false)");
    }

    // Create mode indicator label and recording indicator
    self.create_mode_label();
    self.create_recording_label();

    // Connect to script editor signals
    self.connect_script_editor_signals();

    // Connect to settings changed signal
    self.connect_settings_signals();

    // Try to find existing CodeEdit (indicates hot reload if found)
    self.find_current_code_edit();
    if self.current_editor.is_some() {
        crate::verbose_print!(
            "[godot-neovim] Found existing CodeEdit - triggering full reinitialization (hot reload)"
        );
        // Trigger full reinitialization via deferred call
        // This uses the same flow as on_script_changed for consistent behavior
        self.script_changed_pending.set(true);
    }

    // Enable process() to be called every frame for checking redraw events
    self.base_mut().set_process(true);

    crate::verbose_print!("[godot-neovim] Plugin activated successfully");
}

fn deactivate_plugin_impl(&mut self) {
    self.clear_pending_neovim_switch();
    crate::verbose_print!("[godot-neovim] Plugin deactivating");

    // Disable process() first
    self.base_mut().set_process(false);

    // Cleanup mode labels (check if still valid before freeing)
    if let Some(mut label) = self.mode_label.take() {
        if label.is_instance_valid() {
            label.queue_free();
        }
    }
    if let Some(mut label) = self.shader_mode_label.take() {
        if label.is_instance_valid() {
            label.queue_free();
        }
    }
    if let Some(mut label) = self.recording_label.take() {
        if label.is_instance_valid() {
            label.queue_free();
        }
    }
    if let Some(mut label) = self.shader_recording_label.take() {
        if label.is_instance_valid() {
            label.queue_free();
        }
    }

    // Restore standard line caret before disconnecting
    if let Some(ref mut editor) = self.current_editor {
        editor.set_caret_type(godot::classes::text_edit::CaretType::LINE);
    }

    // Disconnect from gui_input signal
    self.disconnect_gui_input_signal();
    self.disconnect_text_changed_signal();

    // Clear current editor reference
    self.current_editor = None;

    // Disconnect and clear LSP client
    if let Some(ref lsp) = self.godot_lsp {
        lsp.disconnect();
    }
    self.godot_lsp = None;

    // Neovim clients will be stopped when dropped (with timeout)
    self.script_neovim = None;
    self.shader_neovim = None;

    self.pending_insert_cursor_sync = false;
    self.plugin_active = false;
    crate::verbose_print!("[godot-neovim] Plugin deactivated");
}

pub(super) fn send_keys(&mut self, keys: &str) -> bool {
    if self.pending_neovim_switch {
        self.pending_switch_input
            .push(super::async_commands::PendingInput::Keys(keys.to_owned()));
        return true;
    }
    crate::verbose_print!("[godot-neovim] send_keys: {}", keys);

    // Clear user_cursor_sync flag when sending keys
    // This ensures Neovim's cursor updates are applied after keyboard input
    // (user_cursor_sync is set by mouse click to prevent viewport override)
    self.user_cursor_sync = false;

    // Track the visual submode at send time. mode_change redraw events
    // report all of v/V/Ctrl-V as "visual", so this is the only reliable
    // signal. The dispatch path also sets this from InputEventKey, but
    // keys can arrive here directly (GDScript action_send_keys, macros).
    match keys {
        "v" => self.visual_mode_type = 'v',
        "V" => self.visual_mode_type = 'V',
        "<C-v>" => self.visual_mode_type = '\x16',
        _ => {}
    }

    // nvim_input parses "<...>" notation, so a bare "<" is an incomplete
    // special key: it returns 0 bytes written and the key is silently
    // dropped (breaking << unindent). Escape it as "<lt>".
    let keys = if keys == "<" { "<lt>" } else { keys };

    // If exiting Insert mode, buffer keys to be sent after exit completes
    // This prevents key loss during the sync process (vscode-neovim style)
    if self.is_exiting_insert_mode {
        crate::verbose_print!(
            "[godot-neovim] Buffering key during Insert mode exit: {}",
            keys
        );
        self.pending_keys_after_exit.push_str(keys);
        return true;
    }

    // Send keys via channel (lock scope limited to channel send only)
    {
        let Some(neovim) = self.get_current_neovim() else {
            crate::verbose_print!("[godot-neovim] No neovim");
            return false;
        };

        // Try to get lock - channel send is instant so lock contention is minimal
        let Ok(client) = neovim.try_lock() else {
            // Even if lock fails, we can't queue without access to the channel
            // This should be rare since channel send is non-blocking
            crate::verbose_print!("[godot-neovim] Mutex busy, key may be lost: {}", keys);
            return false;
        };

        // Send keys via unbounded channel (never blocks, never drops)
        if !client.send_key_via_channel(keys) {
            godot_error!("[godot-neovim] Failed to queue keys via channel");
            return false;
        }
    }
    // Lock released here

    // Track key send time for no-response detection
    self.last_key_send_time = Some(std::time::Instant::now());
    self.pending_key_count += 1;

    crate::verbose_print!("[godot-neovim] Key queued via channel: {}", keys);

    // Emit signal for GDScript key sequence display
    self.base_mut()
        .emit_signal("key_sent", &[keys.to_variant()]);

    // Note: Modified flag sync is now event-driven via BufModifiedSet autocmd
    // No need to set pending_modified_sync here

    true
}

pub(super) fn show_recovery_dialog(&mut self) {
    self.recovery_dialog_open = true;

    let mut dialog = ConfirmationDialog::new_alloc();
    dialog.set_title("Neovim Recovery");
    dialog.set_text("Neovim is not responding.\n\nSave all files and restart?");
    dialog.set_ok_button_text("Save & Restart");
    dialog.set_cancel_button_text("Cancel");

    // Add custom button for restart without saving
    dialog
        .add_button_ex("Restart without Saving")
        .right(false)
        .action("restart_no_save")
        .done();

    // Connect signals
    let callable_confirmed = self.base().callable("on_recovery_save_restart");
    let callable_canceled = self.base().callable("on_recovery_cancel");
    let callable_custom = self.base().callable("on_recovery_custom_action");

    dialog.connect("confirmed", &callable_confirmed);
    dialog.connect("canceled", &callable_canceled);
    dialog.connect("custom_action", &callable_custom);

    // Add to editor and show
    if let Some(base_control) = EditorInterface::singleton().get_base_control() {
        let mut base_control = base_control;
        base_control.add_child(&dialog);
        dialog.popup_centered();
    }

    self.recovery_dialog = Some(dialog);
}

pub(super) fn save_all_open_scripts(&mut self) {
    let editor = EditorInterface::singleton();
    let Some(script_editor) = editor.get_script_editor() else {
        crate::verbose_print!("[godot-neovim] Recovery: No script editor found");
        return;
    };

    let open_scripts = script_editor.get_open_scripts();
    let current_script = script_editor.get_current_script();

    for i in 0..open_scripts.len() {
        let Some(script) = open_scripts.get(i) else {
            continue;
        };
        let Some(mut script) = script.try_cast::<godot::classes::Script>().ok() else {
            continue;
        };

        let path = script.get_path();
        if path.is_empty() {
            continue;
        }

        // If this is the current script and we have a valid editor,
        // sync the CodeEdit content to the Script first
        let is_current = current_script
            .as_ref()
            .map(|cs| cs.get_path() == path)
            .unwrap_or(false);

        if is_current {
            if let Some(ref editor) = self.current_editor {
                if editor.is_instance_valid() {
                    let text = editor.get_text();
                    script.set_source_code(&text);
                    crate::verbose_print!(
                        "[godot-neovim] Recovery: Synced CodeEdit to Script: {}",
                        path
                    );
                }
            }
        }

        // Save using ResourceSaver
        let result = ResourceSaver::singleton()
            .save_ex(&script)
            .path(&path)
            .done();

        if result == godot::global::Error::OK {
            crate::verbose_print!("[godot-neovim] Recovery: Saved {}", path);
        } else {
            godot_warn!("[godot-neovim] Recovery: Failed to save {}", path);
        }
    }
}

pub(super) fn restart_neovim(&mut self) {
    self.clear_pending_neovim_switch();
    crate::verbose_print!("[godot-neovim] Recovery: Restarting Neovim...");

    // Stop existing Neovim clients
    if let Some(ref neovim) = self.script_neovim {
        if let Ok(mut client) = neovim.lock() {
            client.stop();
        }
    }
    self.script_neovim = None;

    if let Some(ref neovim) = self.shader_neovim {
        if let Ok(mut client) = neovim.lock() {
            client.stop();
        }
    }
    self.shader_neovim = None;

    // Reset sync state
    self.sync_manager.reset();
    self.reset_timeout_counter();

    // Get addons path for Lua plugin
    let addons_path = ProjectSettings::singleton()
        .globalize_path("res://addons/godot-neovim")
        .to_string();

    // Create new Neovim client for ScriptEditor
    match NeovimClient::new() {
        Ok(mut client) => {
            if let Err(e) = client.start(Some(&addons_path)) {
                godot_error!(
                    "[godot-neovim] Recovery: Failed to start Neovim for ScriptEditor: {}",
                    e
                );
                return;
            }

            self.script_neovim = Some(Mutex::new(client));
            crate::verbose_print!(
                "[godot-neovim] Recovery: ScriptEditor Neovim restarted successfully"
            );
        }
        Err(e) => {
            godot_error!(
                "[godot-neovim] Recovery: Failed to create Neovim client for ScriptEditor: {}",
                e
            );
            return;
        }
    }

    // Create new Neovim client for ShaderEditor
    match NeovimClient::new() {
        Ok(mut client) => {
            if let Err(e) = client.start(Some(&addons_path)) {
                godot_error!(
                    "[godot-neovim] Recovery: Failed to start Neovim for ShaderEditor: {}",
                    e
                );
                // Continue with ScriptEditor only
            } else {
                self.shader_neovim = Some(Mutex::new(client));
                crate::verbose_print!(
                    "[godot-neovim] Recovery: ShaderEditor Neovim restarted successfully"
                );
            }
        }
        Err(e) => {
            godot_warn!(
                "[godot-neovim] Recovery: Failed to create Neovim client for ShaderEditor: {}",
                e
            );
            // Continue with ScriptEditor only
        }
    }

    // Reinitialize current buffer
    self.script_changed_pending.set(true);
}

pub(super) fn create_mode_label(&mut self) {
    crate::verbose_print!(
        "[godot-neovim] create_mode_label called for {:?}",
        self.current_editor_type
    );

    // Only create label if we have a current editor with a status bar
    let Some(code_edit) = &self.current_editor else {
        crate::verbose_print!("[godot-neovim] create_mode_label: no current_editor");
        return;
    };

    let Some(mut status_bar) = self.find_status_bar(code_edit.clone().upcast()) else {
        crate::verbose_print!("[godot-neovim] create_mode_label: no status_bar found");
        return;
    };

    let mut label = Label::new_alloc();
    label.set_text(" NORMAL ");

    // Style the label
    label.add_theme_color_override("font_color", Color::from_rgb(0.0, 1.0, 0.5));

    // Add to status bar
    status_bar.add_child(&label);
    status_bar.move_child(&label, 0);

    // Store in appropriate field based on editor type
    match self.current_editor_type {
        EditorType::Shader => {
            label.set_name("NeovimShaderModeLabel");
            self.shader_mode_label = Some(label);
            crate::verbose_print!("[godot-neovim] Created mode label for ShaderEditor");
        }
        _ => {
            label.set_name("NeovimModeLabel");
            self.mode_label = Some(label);
            crate::verbose_print!("[godot-neovim] Created mode label for ScriptEditor");
        }
    }
}

#[allow(dead_code)]
pub(super) fn get_current_mode_label(&mut self) -> Option<&mut Gd<Label>> {
    match self.current_editor_type {
        EditorType::Shader => self.shader_mode_label.as_mut(),
        _ => self.mode_label.as_mut(),
    }
}

pub(super) fn create_recording_label(&mut self) {
    let Some(code_edit) = &self.current_editor else {
        return;
    };

    let Some(mut status_bar) = self.find_status_bar(code_edit.clone().upcast()) else {
        return;
    };

    // Check if label already exists
    let label_name = match self.current_editor_type {
        EditorType::Shader => "NeovimShaderRecordingLabel",
        _ => "NeovimRecordingLabel",
    };

    // Don't create if already exists
    if status_bar.has_node(label_name) {
        return;
    }

    let mut label = Label::new_alloc();
    label.set_name(label_name);
    label.set_text("");
    label.set_visible(false);

    // Style: red color for recording indicator
    label.add_theme_color_override("font_color", Color::from_rgb(1.0, 0.3, 0.3));

    // Add to status bar, after mode label (index 1)
    status_bar.add_child(&label);
    status_bar.move_child(&label, 1);

    match self.current_editor_type {
        EditorType::Shader => {
            self.shader_recording_label = Some(label);
        }
        _ => {
            self.recording_label = Some(label);
        }
    }
}

pub(super) fn find_status_bar(&self, node: Gd<Control>) -> Option<Gd<Control>> {
    // The status bar is an HBoxContainer inside CodeTextEditor (sibling of CodeEdit)
    // CodeTextEditor > CodeEdit (node)
    //                > HBoxContainer (status bar with line/column info)

    // Get parent (should be CodeTextEditor)
    let parent = node.get_parent()?;

    let parent_class = parent.get_class().to_string();
    crate::verbose_print!(
        "[godot-neovim] CodeEdit parent: {} ({})",
        parent.get_name(),
        parent_class
    );

    // Search siblings for HBoxContainer (status bar)
    let child_count = parent.get_child_count();
    crate::verbose_print!(
        "[godot-neovim] Searching {} siblings for status bar",
        child_count
    );
    for i in 0..child_count {
        if let Some(child) = parent.get_child(i) {
            let class_name = child.get_class().to_string();
            crate::verbose_print!(
                "[godot-neovim]   Sibling {}: {} ({})",
                i,
                child.get_name(),
                class_name
            );
            if class_name == "HBoxContainer" {
                if let Ok(control) = child.try_cast::<Control>() {
                    crate::verbose_print!("[godot-neovim] Found HBoxContainer status bar");
                    return Some(control);
                }
            }
        }
    }

    crate::verbose_print!("[godot-neovim] Status bar not found");
    None
}

pub(super) fn connect_script_editor_signals(&mut self) {
    let editor = EditorInterface::singleton();
    if let Some(mut script_editor) = editor.get_script_editor() {
        // Connect to editor script changed signal
        let callable = self.base().callable("on_script_changed");
        if !script_editor.is_connected("editor_script_changed", &callable) {
            script_editor.connect("editor_script_changed", &callable);
        }

        // Connect to script close signal (for Neovim buffer cleanup)
        let close_callable = self.base().callable("on_script_close");
        if !script_editor.is_connected("script_close", &close_callable) {
            script_editor.connect("script_close", &close_callable);
        }
    }
}

pub(super) fn connect_settings_signals(&mut self) {
    let editor = EditorInterface::singleton();
    if let Some(mut editor_settings) = editor.get_editor_settings() {
        // Connect to settings changed signal
        let callable = self.base().callable("on_settings_changed");
        if !editor_settings.is_connected("settings_changed", &callable) {
            editor_settings.connect("settings_changed", &callable);
        }
    }
}

pub(super) fn connect_caret_changed_signal(&mut self) {
    // Create callable first to avoid borrow conflicts
    let callable = self.base().callable("on_caret_changed");

    let Some(ref mut editor) = self.current_editor else {
        return;
    };

    // Connect to caret_changed signal to detect mouse clicks and other cursor changes
    // Check if already connected to avoid duplicate connections
    if !editor.is_connected("caret_changed", &callable) {
        editor.connect("caret_changed", &callable);
        crate::verbose_print!("[godot-neovim] Connected to caret_changed signal");
    }
}

pub(super) fn disconnect_caret_changed_signal(&mut self) {
    // Create callable first to avoid borrow conflicts
    let callable = self.base().callable("on_caret_changed");

    let Some(ref mut editor) = self.current_editor else {
        return;
    };

    // Disconnect from caret_changed signal before closing
    if editor.is_connected("caret_changed", &callable) {
        editor.disconnect("caret_changed", &callable);
        crate::verbose_print!("[godot-neovim] Disconnected from caret_changed signal");
    }
}

pub(super) fn connect_text_changed_signal(&mut self) {
    let callable = self.base().callable("on_text_changed_for_insert_sync");

    let Some(ref mut editor) = self.current_editor else {
