}

pub(super) fn connect_resized_signal(&mut self) {
    // Create callable first to avoid borrow conflicts
    let callable = self.base().callable("on_editor_resized");

    let Some(ref mut editor) = self.current_editor else {
        return;
    };

    // Connect to resized signal to detect editor size changes
    // (window resize, panel toggle, dock width changes, etc.)
    if !editor.is_connected("resized", &callable) {
        editor.connect("resized", &callable);
        crate::verbose_print!("[godot-neovim] Connected to resized signal");
    }
}

pub(super) fn disconnect_resized_signal(&mut self) {
    // Create callable first to avoid borrow conflicts
    let callable = self.base().callable("on_editor_resized");

    let Some(ref mut editor) = self.current_editor else {
        return;
    };

    // Disconnect from resized signal before closing
    if editor.is_connected("resized", &callable) {
        editor.disconnect("resized", &callable);
        crate::verbose_print!("[godot-neovim] Disconnected from resized signal");
    }
}

pub(super) fn connect_gui_input_signal(&mut self) {
    let callable = self.base().callable("on_codeedit_gui_input");

    let Some(ref mut editor) = self.current_editor else {
        return;
    };

    if !editor.is_connected("gui_input", &callable) {
        editor.connect("gui_input", &callable);
        crate::verbose_print!("[godot-neovim] Connected to gui_input signal");
    }
}

pub(super) fn disconnect_gui_input_signal(&mut self) {
    let callable = self.base().callable("on_codeedit_gui_input");

    let Some(ref mut editor) = self.current_editor else {
        return;
    };

    if editor.is_connected("gui_input", &callable) {
        editor.disconnect("gui_input", &callable);
        crate::verbose_print!("[godot-neovim] Disconnected from gui_input signal");
    }
}

pub fn initialize_settings() {
    let editor = EditorInterface::singleton();
    let Some(mut settings) = editor.get_editor_settings() else {
        godot_error!("[godot-neovim] Failed to get EditorSettings");
        return;
    };

    // Add setting if it doesn't exist
    if !settings.has_setting(SETTING_NEOVIM_PATH) {
        let default_path = get_default_neovim_path();
        settings.set_setting(SETTING_NEOVIM_PATH, &Variant::from(default_path));
    }

    // Set initial value for Revert button (update_current=false: don't overwrite user's value)
    let default_path = get_default_neovim_path();
    settings.set_initial_value(SETTING_NEOVIM_PATH, &Variant::from(default_path), false);

    // Add property info for better UI
    let mut property_info = VarDictionary::new();
    property_info.set("name", SETTING_NEOVIM_PATH);
    property_info.set("type", VariantType::STRING.ord());
    property_info.set("hint", PropertyHint::GLOBAL_FILE.ord());
    property_info.set("hint_string", &get_file_filter());

    settings.add_property_info(&property_info);

    // Add neovim_clean setting if it doesn't exist
    // Default is true (--clean) for safety - avoids plugin compatibility issues
    if !settings.has_setting(SETTING_NEOVIM_CLEAN) {
        settings.set_setting(SETTING_NEOVIM_CLEAN, &Variant::from(true));
    }

    // Set initial value for Revert button (update_current=false: don't overwrite user's value)
    settings.set_initial_value(SETTING_NEOVIM_CLEAN, &Variant::from(true), false);

    // Add property info for neovim_clean (checkbox)
    let mut clean_info = VarDictionary::new();
    clean_info.set("name", SETTING_NEOVIM_CLEAN);
    clean_info.set("type", VariantType::BOOL.ord());

    settings.add_property_info(&clean_info);

    // Add timeoutlen setting if it doesn't exist (advanced setting)
    if !settings.has_setting(SETTING_TIMEOUTLEN) {
        settings.set_setting(SETTING_TIMEOUTLEN, &Variant::from(DEFAULT_TIMEOUTLEN_MS));
    }

    // Set initial value for Revert button (update_current=false: don't overwrite user's value)
    settings.set_initial_value(
        SETTING_TIMEOUTLEN,
        &Variant::from(DEFAULT_TIMEOUTLEN_MS),
        false,
    );

    // Add property info for timeoutlen (integer with range)
    let mut timeoutlen_info = VarDictionary::new();
    timeoutlen_info.set("name", SETTING_TIMEOUTLEN);
    timeoutlen_info.set("type", VariantType::INT.ord());
    timeoutlen_info.set("hint", PropertyHint::RANGE.ord());
    timeoutlen_info.set("hint_string", "0,10000,100"); // min, max, step

    settings.add_property_info(&timeoutlen_info);

    crate::verbose_print!(
        "[godot-neovim] Settings initialized. Neovim path: {}, Clean: {}, Timeoutlen: {}ms",
        get_neovim_path(),
        get_neovim_clean(),
        get_timeoutlen()
    );
}

pub fn get_neovim_path() -> String {
    let editor = EditorInterface::singleton();
    let Some(settings) = editor.get_editor_settings() else {
        return get_default_neovim_path().to_string();
    };

    if settings.has_setting(SETTING_NEOVIM_PATH) {
        let value = settings.get_setting(SETTING_NEOVIM_PATH);
        if let Ok(path) = value.try_to::<GString>() {
            let path_str = path.to_string();
            if !path_str.is_empty() {
                return path_str;
            }
        }
    }

    get_default_neovim_path().to_string()
}

pub fn get_neovim_clean() -> bool {
    let editor = EditorInterface::singleton();
    let Some(settings) = editor.get_editor_settings() else {
        return true; // Default to clean mode
    };

    if settings.has_setting(SETTING_NEOVIM_CLEAN) {
        let value = settings.get_setting(SETTING_NEOVIM_CLEAN);
        if let Ok(clean) = value.try_to::<bool>() {
            return clean;
        }
    }

    true // Default to clean mode
}

pub fn get_timeoutlen() -> u64 {
    let editor = EditorInterface::singleton();
    let Some(settings) = editor.get_editor_settings() else {
        return DEFAULT_TIMEOUTLEN_MS as u64;
    };

    if settings.has_setting(SETTING_TIMEOUTLEN) {
        let value = settings.get_setting(SETTING_TIMEOUTLEN);
        if let Ok(timeout) = value.try_to::<i64>() {
            // Clamp to valid range (0 to 10000ms)
            return timeout.clamp(0, 10000) as u64;
        }
    }

    DEFAULT_TIMEOUTLEN_MS as u64
}

pub fn on_settings_changed(settings: &Gd<EditorSettings>) {
    if settings.has_setting(SETTING_NEOVIM_PATH) {
        let value = settings.get_setting(SETTING_NEOVIM_PATH);
        if let Ok(path) = value.try_to::<GString>() {
            let path_str = path.to_string();

            // Skip validation if path is empty (will use PATH to find nvim)
            if path_str.is_empty() {
                return;
            }

            let result = validate_neovim_path(&path_str);

            match &result {
                ValidationResult::Valid { version } => {
                    crate::verbose_print!("[godot-neovim] Neovim path validated: {}", version);
                }
                ValidationResult::NotFound => {
                    godot_warn!(
                        "[godot-neovim] Neovim not found at '{}'. The path will be used but may fail at runtime.",
                        path_str
                    );
                }
                ValidationResult::NotExecutable => {
                    godot_warn!("[godot-neovim] Neovim at '{}' is not executable.", path_str);
                }
                ValidationResult::InvalidVersion { error } => {
                    godot_warn!(
                        "[godot-neovim] Neovim validation failed at '{}': {}",
                        path_str,
                        error
                    );
                }
            }
        }
    }
}

pub fn new(tree: &Gd<SceneTree>, bus: &StringName, mixer: &Mixer) -> Self {
    let rate = mixer.rate() as f32;
    let mut generator = AudioStreamGenerator::new_gd();
    generator.set_mix_rate(rate);
    generator.set_buffer_length(BUFFER_SECONDS);

    let mut player = AudioStreamPlayer::new_alloc();
    player.set_name("ServoAudio");
    player.set_stream(&generator);
    player.set_bus(bus);
    player.set_autoplay(true);
    // Paused along with the WebViews by `pump`, not by the tree.
    player.set_process_mode(godot::classes::node::ProcessMode::ALWAYS);

    // Servo starts from a node's `_ready()`, where the root can still be
    // busy adding its children.
    if let Some(mut root) = tree.get_root() {
        root.call_deferred("add_child", &[player.to_variant()]);
    }

    Self {
        player,
        playback: None,
        rate: rate as f64,
        capacity: 0,
        last_pump: None,
        peak_frame_seconds: 0.0,
        margin_seconds: 0.0,
        calm_seconds: 0.0,
        skips: 0,
        mixed: Vec::new(),
        paused: false,
    }
}

pub fn pump(&mut self, mixer: &Mixer, paused: bool) {
    let now = Instant::now();
    let frame_seconds = self
        .last_pump
        .map_or(0.0, |last| (now - last).as_secs_f64())
        .min(MAX_FRAME_SECONDS);
    self.last_pump = Some(now);

    if !self.player.is_instance_valid() {
        return;
    }
    if paused != self.paused {
        self.paused = paused;
        self.player.set_stream_paused(paused);
    }
    if paused {
        return;
    }
    let Some(mut playback) = self.playback() else {
        return;
    };

    self.peak_frame_seconds = frame_seconds.max(self.peak_frame_seconds * PEAK_DECAY);
    let skips = playback.get_skips();
    if skips != self.skips {
        self.skips = skips;
        self.margin_seconds =
            (self.margin_seconds + MARGIN_STEP_SECONDS).min(MAX_MARGIN_SECONDS);
        self.calm_seconds = 0.0;
    } else {
        self.calm_seconds += frame_seconds;
        if self.calm_seconds >= CALM_SECONDS {
            self.margin_seconds = (self.margin_seconds - MARGIN_STEP_SECONDS / 2.0).max(0.0);
            self.calm_seconds = 0.0;
        }
    }

    // Each source keeps two frames' worth queued, so whatever this frame
    // takes is already waiting. Godot's audio thread drains the generator in
    // whole mix buffers, so one frame can take twice what its time suggests.
    mixer.set_high_water(
        ((self.peak_frame_seconds * SOURCE_FRAMES_AHEAD * self.rate) as usize)
            .max(MIN_HIGH_WATER),
    );

    let target_seconds =
        (self.peak_frame_seconds * FRAMES_AHEAD).max(MIN_TARGET_SECONDS) + self.margin_seconds;
    let target = ((target_seconds * self.rate) as i32).min(self.capacity);
    let queued = self.capacity - playback.get_frames_available();
    let wanted = target - queued;
    let output_latency = AudioServer::singleton().get_output_latency();
    mixer.set_latency(queued.max(target) as f64 / self.rate + output_latency);
    // A producer that has not caught up yet is waited for while the
    // generator still holds a frame's worth: taking its frames now would
    // leave a hole of silence in the middle of its sound.
    let floor = (self.peak_frame_seconds * self.rate) as i32 - queued;
    let wanted = wanted.min(floor.max(mixer.available().min(i32::MAX as usize) as i32));
    if wanted <= 0 {
        return;
    }

    mixer.pull(wanted as usize, &mut self.mixed);
    let frames: PackedVector2Array = self
        .mixed
        .iter()
        .map(|frame| Vector2::new(frame[0], frame[1]))
        .collect();
    playback.push_buffer(&frames);
}

fn playback(&mut self) -> Option<Gd<AudioStreamGeneratorPlayback>> {
    if self.playback.is_none() && self.player.is_playing() {
        let playback = self
            .player
            .get_stream_playback()?
            .try_cast::<AudioStreamGeneratorPlayback>()
            .ok()?;
        self.capacity = playback.get_frames_available();
        self.skips = playback.get_skips();
        self.playback = Some(playback);
    }
    self.playback.clone()
}

pub struct AndroidBridge {
    /// Kept so that `eglDestroyImageKHR` can be called on release.
    egl: Egl,
    buffer: *mut c_void,
    display: EglDisplay,
    image: EglImage,
    /// The GL texture Servo writes through, with `image` bound to it.
    gl_texture: glow::Texture,
    texture: Gd<ExternalTexture>,
    size: PhysicalSize<u32>,
}

pub fn new(
    context: &GodotRenderingContext,
    size: PhysicalSize<u32>,
    host: &crate::gl_guard::HostContext,
) -> Result<Self, String> {
    // Make Servo's GL context current before touching EGL.
    context
        .make_current_public()
        .map_err(|error| format!("make_current failed: {error:?}"))?;

    let egl = Egl::load(context)?;

    // SAFETY: what follows is a straight sequence of raw EGL and
    // AHardwareBuffer calls, with Servo's context current. Anything already
    // allocated is released before returning on failure.
    unsafe {
        let display = egl.current_display()?;
        let buffer = allocate_buffer(size)?;

        let image = match image_from_buffer(&egl, display, buffer) {
            Ok(image) => image,
            Err(error) => {
                AHardwareBuffer_release(buffer);
                return Err(error);
            }
        };

        let gl_texture = match egl.bind_image_to_texture(context.glow(), image) {
            Ok(texture) => texture,
            Err(error) => {
                (egl.destroy_image)(display, image);
                AHardwareBuffer_release(buffer);
                return Err(error);
            }
        };

        // From here on the GL calls belong to Godot. `ExternalTexture` calls
        // `glEGLImageTargetTexture2DOES` internally, so creating it while
        // Servo's context is current would put the texture on the wrong
        // context. Hand the thread back first.
        host.restore();

        // Give Godot the same EGLImage. `ExternalTexture` is a Texture2D, so
        // it drops straight into a material.
        let mut texture = ExternalTexture::new_gd();
        texture.set_size(Vector2::new(size.width as f32, size.height as f32));
        texture.set_external_buffer_id(image as u64);

        Ok(Self {
            egl,
            buffer,
            display,
            image,
            gl_texture,
            texture,
            size,
        })
    }
}

impl TextureBridge for AndroidBridge {
    fn texture(&self) -> Gd<Texture2D> {
        self.texture.clone().upcast()
    }

    fn update(&mut self, context: &GodotRenderingContext) -> Result<(), String> {
        let source_fbo = context.framebuffer();
        // SAFETY: the GL context is current and the texture is alive.
        unsafe { super::blit_flipped(context.glow(), source_fbo, self.gl_texture, self.size) }
    }

    fn backend_name(&self) -> &'static str {
        "android-ahardwarebuffer"
    }

    fn needs_external_sampler(&self) -> bool {
        true
    }

    fn release(&mut self, context: &GodotRenderingContext) {
        // `eglDestroyImageKHR` wants the display Servo's context is on, and
        // nothing guarantees that context is still current by now.
        let _ = context.make_current_public();

        // SAFETY: everything here was allocated above. Nulled out so a second
        // call cannot double free.
        unsafe {
            if !self.image.is_null() && !self.display.is_null() {
                (self.egl.destroy_image)(self.display, self.image);
                self.image = std::ptr::null_mut();
            }
            if !self.buffer.is_null() {
                AHardwareBuffer_release(self.buffer);
                self.buffer = std::ptr::null_mut();
            }
        }
    }
}

pub struct CpuBridge {
    texture: Gd<ImageTexture>,
    /// The pixel buffers and the `Image` pointing at each, index-aligned.
    frames: [Frame; 2],
    /// Index of the frame most recently handed to `texture`.
    current: usize,
    size: PhysicalSize<u32>,
}

struct Frame {
    pixels: PackedByteArray,
    image: Gd<Image>,
}

impl TextureBridge for CpuBridge {
    fn texture(&self) -> Gd<Texture2D> {
        self.texture.clone().upcast()
    }

    /// Read one frame back and push it into the `ImageTexture`.
    ///
    /// The destination alternates every frame so that nothing is allocated or
    /// copied. `PackedByteArray` is copy-on-write, so writing into the buffer the
    /// `Image` currently references would duplicate it. Leaving that one alone
    /// and writing into the other keeps the reference count at 1, and the
    /// destination of `glReadPixels` becomes the texture's contents directly.
    ///
    /// When the rendering server runs on its own thread, `texture.update()` only
    /// queues a command and the data is read up to one frame later. Two sets are
    /// enough that the side still waiting to be read is never overwritten.
    fn update(&mut self, context: &GodotRenderingContext) -> Result<(), String> {
        let next = self.current ^ 1;
        let frame = &mut self.frames[next];

        if !context.read_pixels_flipped_into(self.size, frame.pixels.as_mut_slice()) {
            return Err("glReadPixels failed".into());
        }

        frame.image.set_data(
            self.size.width as i32,
            self.size.height as i32,
            false,
            Format::RGBA8,
            &frame.pixels,
        );
        self.texture.update(&frame.image);
        self.current = next;
        Ok(())
    }

    fn backend_name(&self) -> &'static str {
        "cpu-readback"
    }
}

pub struct D3d12Bridge {
    /// The shared texture on ANGLE's D3D11 device. Servo writes into this one.
    d3d11_texture: ID3D11Texture2D,
    /// The same memory opened on Godot's D3D12 device. Held to keep it alive.
    _d3d12_resource: ID3D12Resource,
    /// The shared resource wrapped as a Godot RD texture. The copy source.
    imported: Rid,
    /// A texture Godot allocated itself. The copy destination, and what is displayed.
    owned: Rid,
    texture: Gd<Texture2Drd>,
    size: PhysicalSize<u32>,
}

impl D3d12Bridge {
    pub fn new(context: &GodotRenderingContext, size: PhysicalSize<u32>) -> Result<Self, String> {
        let d3d11_device = angle::d3d11_device(context)?;
        let godot_device = super::godot_logical_device()?;

        // SAFETY: both devices are live, and the handle is closed once D3D12 has
        // opened it.
        let (d3d11_texture, d3d12_resource) = unsafe {
            let (texture, handle) = angle::create_shared_texture(&d3d11_device, size)?;
            let opened = open_on_d3d12(godot_device, handle);
            let _ = CloseHandle(handle);
            (texture, opened?)
        };

        let mut rendering_device = RenderingServer::singleton()
            .get_rendering_device()
            .ok_or("no RenderingDevice")?;

        let imported = import_rd_texture(&mut rendering_device, &d3d12_resource, size)?;
        let owned =
            create_owned_rd_texture(&mut rendering_device, DataFormat::R8G8B8A8_UNORM, size)?;

        let mut texture = Texture2Drd::new_gd();
        texture.set_texture_rd_rid(owned);

        Ok(Self {
            d3d11_texture,
            _d3d12_resource: d3d12_resource,
            imported,
            owned,
            texture,
            size,
        })
    }
}

impl TextureBridge for D3d12Bridge {
    fn texture(&self) -> Gd<Texture2D> {
        self.texture.clone().upcast()
    }

    fn update(&mut self, context: &GodotRenderingContext) -> Result<(), String> {
        angle::blit_into(context, &self.d3d11_texture, self.size)?;
        copy_rd_texture(self.imported, self.owned, self.size)
    }

    fn backend_name(&self) -> &'static str {
        "d3d12-shared-nt-handle"
    }

    fn release(&mut self, _context: &GodotRenderingContext) {
        self.texture.set_texture_rd_rid(Rid::Invalid);
        if let Some(mut rendering_device) = RenderingServer::singleton().get_rendering_device() {
            for rid in [&mut self.owned, &mut self.imported] {
                if rid.is_valid() {
                    rendering_device.free_rid(*rid);
                    *rid = Rid::Invalid;
                }
            }
        }
    }
}

fn import_rd_texture(
    rendering_device: &mut Gd<RenderingDevice>,
    resource: &ID3D12Resource,
    size: PhysicalSize<u32>,
) -> Result<Rid, String> {
    let rid = rendering_device.texture_create_from_extension(
        TextureType::TYPE_2D,
        DataFormat::R8G8B8A8_UNORM,
        TextureSamples::SAMPLES_1,
        TextureUsageBits::SAMPLING_BIT | TextureUsageBits::CAN_COPY_FROM_BIT,
        resource.as_raw() as u64,
        size.width as u64,
        size.height as u64,
        1,
        1,
    );
    if rid.is_valid() {
        Ok(rid)
    } else {
        Err("texture_create_from_extension returned an invalid RID".into())
    }
}

pub struct MetalBridge {
    /// Holds the IOSurface reference. Dropping it would pull the storage out
    /// from under the texture below.
    _native_surface: NativeSurface,
    /// The `id<MTLTexture>` handed to Godot. This reference is this bridge's
    /// own; Godot's is sorted out in `new()`.
    _metal_texture: Retained<AnyObject>,
    rd_texture: Rid,
    texture: Gd<Texture2Drd>,
}

impl MetalBridge {
    pub fn new(context: &GodotRenderingContext, size: PhysicalSize<u32>) -> Result<Self, String> {
        let metal_device = super::godot_logical_device()?;

        // Take the IOSurface out of the bound surface. That needs a `&Surface`,
        // so unbind and rebind once. The same surface is used from here on, so
        // the texture created below stays valid for the whole lifetime.
        let native_surface = context
            .with_unbound_surface(|device, surface| device.native_surface(surface))
            .map_err(|error| format!("failed to take the surfman surface: {error:?}"))?;

        let metal_texture =
            unsafe { create_metal_texture(metal_device, Some(&native_surface), size)? };

        let mut rendering_device = RenderingServer::singleton()
            .get_rendering_device()
            .ok_or("no RenderingDevice")?;

        // `texture_free` releases the texture, but whether the import retained
        // it first depends on the driver. 4.6 does, and 4.8 does again
        // (godotengine/godot#121995). 4.7 only casts the pointer, so its release
        // takes the reference kept below. That one is then released a second
        // time when this bridge drops, and Godot crashes a few frames later. So
        // a driver like 4.7's is handed a reference of its own to release.
        let godot_takes_ours = godot_takes_imported_reference(metal_device, &mut rendering_device)?;
        let handed = if godot_takes_ours {
            Retained::into_raw(metal_texture.clone())
        } else {
            Retained::as_ptr(&metal_texture).cast_mut()
        };

        let rd_texture = import_texture(&mut rendering_device, handed, size);
        if !rd_texture.is_valid() {
            if godot_takes_ours {
                // SAFETY: from `into_raw` above, and Godot did not take it.
                drop(unsafe { Retained::from_raw(handed) });
            }
            return Err("texture_create_from_extension returned an invalid RID".into());
        }

        let mut texture = Texture2Drd::new_gd();
        texture.set_texture_rd_rid(rd_texture);

        Ok(Self {
            _native_surface: native_surface,
            _metal_texture: metal_texture,
            rd_texture,
            texture,
        })
    }
}

impl TextureBridge for MetalBridge {
    fn texture(&self) -> Gd<Texture2D> {
        self.texture.clone().upcast()
    }

    /// Both sides look at the same memory, so there is nothing to transfer.
    /// Just flush the outstanding GL work.
    fn update(&mut self, context: &GodotRenderingContext) -> Result<(), String> {
        use glow::HasContext;
        unsafe { context.glow().flush() };
        Ok(())
    }

    fn backend_name(&self) -> &'static str {
        "metal-iosurface"
    }

    fn needs_v_flip(&self) -> bool {
        true
    }

    fn release(&mut self, _context: &GodotRenderingContext) {
        if self.rd_texture.is_valid() {
            self.texture.set_texture_rd_rid(Rid::Invalid);
            if let Some(mut rendering_device) = RenderingServer::singleton().get_rendering_device()
            {
                rendering_device.free_rid(self.rd_texture);
            }
            self.rd_texture = Rid::Invalid;
        }
    }
}

fn godot_takes_imported_reference(
    metal_device: u64,
    rendering_device: &mut Gd<RenderingDevice>,
) -> Result<bool, String> {
    static TAKES: OnceLock<bool> = OnceLock::new();
    if let Some(&takes) = TAKES.get() {
        return Ok(takes);
    }

    let size = PhysicalSize::new(1, 1);
    let probe = unsafe { create_metal_texture(metal_device, None, size)? };
    let before = retain_count(&probe);
    let rd_texture = import_texture(rendering_device, Retained::as_ptr(&probe).cast_mut(), size);
    if !rd_texture.is_valid() {
        return Err("texture_create_from_extension returned an invalid RID".into());
    }
    let takes = retain_count(&probe) <= before;
    if takes {
        // Freeing the RID below releases the probe as well.
        std::mem::forget(probe.clone());
    }
    rendering_device.free_rid(rd_texture);

    Ok(*TAKES.get_or_init(|| takes))
}

fn import_texture(
    rendering_device: &mut Gd<RenderingDevice>,
    metal_texture: *mut AnyObject,
    size: PhysicalSize<u32>,
) -> Rid {
    rendering_device.texture_create_from_extension(
        TextureType::TYPE_2D,
        // The IOSurface is created as kCVPixelFormatType_32BGRA. The same
        // format as the texture, so Godot makes no view of it: a view would be
        // what it keeps, and the reference handed over would never be released.
        DataFormat::B8G8R8A8_UNORM,
        TextureSamples::SAMPLES_1,
        TextureUsageBits::SAMPLING_BIT | TextureUsageBits::COLOR_ATTACHMENT_BIT,
        metal_texture as u64,
        size.width as u64,
        size.height as u64,
        1,
        1,
    )
}

pub trait TextureBridge {
    /// The texture handed to Godot. The same instance for the whole lifetime.
    fn texture(&self) -> Gd<Texture2D>;

    /// Called right after Servo's `paint()` and before `present()`.
    fn update(&mut self, context: &GodotRenderingContext) -> Result<(), String>;

    fn backend_name(&self) -> &'static str;

    /// Whether the texture can only be read through `samplerExternalOES`.
    ///
    /// Android's `GL_TEXTURE_EXTERNAL_OES` is such a texture. A `sampler2D`
    /// reads it as black, so the caller has to swap in a different shader.
    fn needs_external_sampler(&self) -> bool {
        false
    }

    /// Whether the texture arrives upside down.
    ///
    /// GL's origin is bottom-left, which a path with a transfer step can correct
    /// on the way through. macOS shares the IOSurface as it is and has nowhere to
    /// do that, so it returns `true`.
    fn needs_v_flip(&self) -> bool {
        false
    }

    /// Called as the node leaves the tree, and again on every resize.
    ///
    /// Frees the Godot RIDs and whatever the path allocated. Servo's rendering
    /// context is still alive here and is passed in, because a GL object can
    /// only be deleted through the context that made it and nothing else
    /// guarantees one is current by this point.
    fn release(&mut self, context: &GodotRenderingContext) {
        let _ = context;
    }
}

pub fn create(
    context: &GodotRenderingContext,
    size: PhysicalSize<u32>,
    host: &crate::gl_guard::HostContext,
) -> Box<dyn TextureBridge> {
    let driver = RenderingServer::singleton()
        .get_current_rendering_driver_name()
        .to_string();

    match try_create_shared(&driver, context, size, host) {
        SharedPath::Ready(bridge) => return bridge,
        SharedPath::Failed(error) => {
            godot_warn!(
                "godot-servo: GPU texture sharing on the '{driver}' backend failed \
                 ({error}); falling back to CPU readback."
            );
        }
        SharedPath::Absent(reason) => {
            godot_print!(
                "godot-servo: no GPU sharing path on the '{driver}' backend: \
                 {reason}. Using CPU readback."
            );
        }
    }

    Box::new(cpu::CpuBridge::new(size))
}

pub(crate) fn driver_resource(
    resource: godot::classes::rendering_device::DriverResource,
    what: &str,
) -> Result<u64, String> {
    let rendering_device = RenderingServer::singleton()
        .get_rendering_device()
        .ok_or("no RenderingDevice (the Compatibility renderer has none)")?;

    let handle = rendering_device.get_driver_resource(resource, Rid::Invalid, 0);
    if handle == 0 {
        return Err(format!("get_driver_resource returned a null {what}"));
    }
    Ok(handle)
}

pub(crate) fn create_owned_rd_texture(
    rendering_device: &mut Gd<godot::classes::RenderingDevice>,
    format: godot::classes::rendering_device::DataFormat,
    size: PhysicalSize<u32>,
) -> Result<Rid, String> {
    use godot::classes::rendering_device::{TextureSamples, TextureType, TextureUsageBits};
    use godot::classes::{RdTextureFormat, RdTextureView};

    let mut texture_format = RdTextureFormat::new_gd();
    texture_format.set_format(format);
    texture_format.set_texture_type(TextureType::TYPE_2D);
    texture_format.set_width(size.width);
    texture_format.set_height(size.height);
    texture_format.set_depth(1);
    texture_format.set_array_layers(1);
    texture_format.set_mipmaps(1);
    texture_format.set_samples(TextureSamples::SAMPLES_1);
    texture_format.set_usage_bits(
        TextureUsageBits::SAMPLING_BIT
            | TextureUsageBits::CAN_COPY_TO_BIT
            | TextureUsageBits::CAN_COPY_FROM_BIT,
    );

    let view = RdTextureView::new_gd();
    let rid = rendering_device.texture_create(&texture_format, &view);
    if rid.is_valid() {
        Ok(rid)
    } else {
        Err("texture_create returned an invalid RID".into())
    }
}

pub(crate) fn copy_rd_texture(from: Rid, to: Rid, size: PhysicalSize<u32>) -> Result<(), String> {
    let mut rendering_device = RenderingServer::singleton()
        .get_rendering_device()
        .ok_or("no RenderingDevice")?;
    let extent = Vector3::new(size.width as f32, size.height as f32, 1.0);
    let error =
        rendering_device.texture_copy(from, to, Vector3::ZERO, Vector3::ZERO, extent, 0, 0, 0, 0);
    if error != godot::global::Error::OK {
        return Err(format!("texture_copy failed: {error:?}"));
    }
    Ok(())
}

pub fn enabled_extensions() -> Result<Vec<String>, String> {
    let mut rendering_device = RenderingServer::singleton()
        .get_rendering_device()
        .ok_or("there is no RenderingDevice")?;

    if !rendering_device.has_method(METHOD) {
        return Err(format!(
            "this Godot has no RenderingDevice.{METHOD}(), so a project has no way \
             to enable the device extensions an imported texture needs \
             (godotengine/godot#114940)"
        ));
    }

    // Not in the compiled bindings, so this goes through a dynamic call. The
    // `has_method` check above is what keeps that from raising an error.
    let names: PackedStringArray = rendering_device
        .call(METHOD, &[])
        .try_to()
        .map_err(|error| format!("{METHOD}() returned something unexpected: {error}"))?;

    Ok(names.as_slice().iter().map(GString::to_string).collect())
}

pub fn wait_until_idle(&self) {
    RenderingServer::singleton().force_sync();
    // SAFETY: nothing else holds the queues, per the comment above.
    let _ = unsafe { self.device.device_wait_idle() };
}

pub struct VulkanBridge {
    vulkan: VulkanDevice,
    /// The platform's shared memory, as a `VkImage` and whatever Servo draws
    /// into it through.
    image: SharedImage,
    /// The imported image wrapped as a Godot RD texture. The copy source.
    imported: Rid,
    /// A texture Godot allocated itself. The copy destination, and what is displayed.
    owned: Rid,
    texture: Gd<Texture2Drd>,
    size: PhysicalSize<u32>,
}

impl VulkanBridge {
    fn new(
        vulkan: VulkanDevice,
        context: &GodotRenderingContext,
        size: PhysicalSize<u32>,
    ) -> Result<Self, String> {
        let mut image = SharedImage::new(&vulkan, context, size)?;

        match build_textures(&image, size) {
            Ok((imported, owned)) => {
                let mut texture = Texture2Drd::new_gd();
                texture.set_texture_rd_rid(owned);
                Ok(Self {
                    vulkan,
                    image,
                    imported,
                    owned,
                    texture,
                    size,
                })
            }
            Err(error) => {
                vulkan.wait_until_idle();
                image.destroy(&vulkan, context);
                Err(error)
            }
        }
    }
}

fn build_textures(image: &SharedImage, size: PhysicalSize<u32>) -> Result<(Rid, Rid), String> {
    let mut rendering_device = RenderingServer::singleton()
        .get_rendering_device()
        .ok_or("no RenderingDevice")?;

    let imported = rendering_device.texture_create_from_extension(
        TextureType::TYPE_2D,
        SharedImage::GODOT_FORMAT,
        TextureSamples::SAMPLES_1,
        TextureUsageBits::SAMPLING_BIT | TextureUsageBits::CAN_COPY_FROM_BIT,
        image.vk_image().as_raw(),
        size.width as u64,
        size.height as u64,
        1,
        1,
    );
    if !imported.is_valid() {
        return Err("texture_create_from_extension returned an invalid RID".into());
    }

    match create_owned_rd_texture(&mut rendering_device, SharedImage::GODOT_FORMAT, size) {
        Ok(owned) => Ok((imported, owned)),
        Err(error) => {
            rendering_device.free_rid(imported);
            Err(error)
        }
    }
}

impl TextureBridge for VulkanBridge {
    fn texture(&self) -> Gd<Texture2D> {
        self.texture.clone().upcast()
    }

    fn update(&mut self, context: &GodotRenderingContext) -> Result<(), String> {
        self.image.update(context, self.size)?;
        copy_rd_texture(self.imported, self.owned, self.size)
    }

    fn backend_name(&self) -> &'static str {
        SharedImage::BACKEND_NAME
    }

    fn needs_v_flip(&self) -> bool {
        SharedImage::NEEDS_V_FLIP
    }

    fn release(&mut self, context: &GodotRenderingContext) {
        self.texture.set_texture_rd_rid(Rid::Invalid);
        if let Some(mut rendering_device) = RenderingServer::singleton().get_rendering_device() {
            for rid in [&mut self.owned, &mut self.imported] {
                if rid.is_valid() {
                    rendering_device.free_rid(*rid);
                    *rid = Rid::Invalid;
                }
            }
        }
        // Godot's own free is queued, and frames referencing the image may still
        // be in flight, so the allocation cannot go until the device is done.
        self.vulkan.wait_until_idle();
        self.image.destroy(&self.vulkan, context);
    }
}

pub fn godot_adapter() -> Option<surfman::Adapter> {
    let driver = RenderingServer::singleton()
        .get_current_rendering_driver_name()
        .to_string();
    let luid = match driver.as_str() {
        "d3d12" => d3d12_luid(),
        "vulkan" => vulkan_luid(),
        // No RenderingDevice, so no device to match, and no shared texture
        // either: the Compatibility renderer takes the readback path anyway.
        _ => return None,
    }?;

    let Some(adapter) = adapter_with_luid(luid) else {
        godot_warn!(
            "godot-servo: no DXGI adapter matches the one Godot renders on; \
             Servo may end up on another GPU, which costs the shared texture."
        );
        return None;
    };

    // SAFETY: `into_raw` hands over the reference this function owns, which is
    // exactly what `ComPtr::from_raw` takes. The two `IDXGIAdapter` types are
    // the same COM interface; surfman's is the `winapi` one.
    let owned = unsafe {
        wio::com::ComPtr::from_raw(adapter.into_raw() as *mut winapi::shared::dxgi::IDXGIAdapter)
    };
    Some(surfman::Adapter::from_dxgi_adapter(owned))
}

pub fn register() {
    let server = ServoServer::new_alloc();
    Engine::singleton().register_singleton(SINGLETON_NAME, &server);
    SINGLETON.with(|singleton| *singleton.borrow_mut() = Some(server));
}

pub fn unregister() {
    let Some(mut server) = SINGLETON.with(|singleton| singleton.borrow_mut().take()) else {
        return;
    };
    server.bind_mut().shut_down();
    Engine::singleton().unregister_singleton(SINGLETON_NAME);
    server.free();
}

#[derive(GodotClass)]
#[class(base=Object, init)]
pub struct ServoServer {
    base: Base<Object>,

    /// Enable WebGL 2.0. Servo has it off by default.
    #[var(set = set_enable_webgl2)]
    #[init(val = true)]
    enable_webgl2: bool,

    /// Enable WebGPU. Servo has it off by default.
    ///
    /// On here, because the binary carries wgpu either way, and Servo starts
    /// its WebGPU thread only on a page's first request. A `file://` page
    /// cannot use it at all; see the README.
    #[var(set = set_enable_webgpu)]
    #[init(val = true)]
    enable_webgpu: bool,

    /// Play the pages' audio through Godot. Off, Servo drops it, as it did
    /// before.
    ///
    /// Covers Web Audio. The sound goes to an `AudioStreamPlayer` this server
    /// adds to the root, on [member audio_bus].
    #[var(set = set_enable_audio)]
    #[init(val = true)]
    enable_audio: bool,

    /// The bus the pages' audio plays on. Can be changed at any time.
    #[var(set = set_audio_bus)]
    #[init(val = StringName::from("Master"))]
    audio_bus: StringName,

    servo: Option<Servo>,
    audio: Option<AudioOutput>,
    waker: GodotWaker,
    /// The running `ServoWebView`s. Ids rather than `Gd`s, so a node freed
    /// without leaving the tree is skipped instead of dereferenced.
    webviews: Vec<InstanceId>,
}

#[godot_api]
impl ServoServer {
    #[func]
    fn set_enable_webgl2(&mut self, value: bool) {
        if value != self.enable_webgl2 && !self.refuse_change("enable_webgl2") {
            self.enable_webgl2 = value;
        }
    }

    #[func]
    fn set_enable_webgpu(&mut self, value: bool) {
        if value != self.enable_webgpu && !self.refuse_change("enable_webgpu") {
            self.enable_webgpu = value;
        }
    }

    #[func]
    fn set_enable_audio(&mut self, value: bool) {
        if value != self.enable_audio && !self.refuse_change("enable_audio") {
            self.enable_audio = value;
        }
    }

    #[func]
    fn set_audio_bus(&mut self, value: StringName) {
        if let Some(audio) = &mut self.audio {
            audio.set_bus(&value);
        }
        self.audio_bus = value;
    }
}

pub fn singleton() -> Option<Gd<Self>> {
    SINGLETON.with(|singleton| singleton.borrow().clone())
}

pub fn attach(&mut self, webview: InstanceId) -> Servo {
    if !self.webviews.contains(&webview) {
        self.webviews.push(webview);
    }
    if let Some(servo) = &self.servo {
        return servo.clone();
    }

    // Servo leaves threads behind that nothing can join, so this library has
    // to stay mapped after Godot unloads it at exit. See `module_pin`.
    crate::module_pin::pin();

    install_crypto_provider();
    point_temp_dir_at_app_cache();
    let tree = Engine::singleton()
        .get_main_loop()
        .and_then(|main_loop| main_loop.try_cast::<SceneTree>().ok());
    if self.enable_audio {
        self.start_audio(tree.as_ref());
    }
    let preferences = Preferences {
        dom_webgl2_enabled: self.enable_webgl2,
        dom_webgpu_enabled: self.enable_webgpu,
        ..Default::default()
    };
    let servo = ServoBuilder::default()
        .preferences(preferences)
        .event_loop_waker(Box::new(self.waker.clone()))
        .build();
    servo.setup_logging();

    match tree {
        Some(tree) => {
            tree.signals()
                .process_frame()
                .connect_other(&self.to_gd(), Self::pump);
        }
        None => {
            godot_error!("godot-servo: no SceneTree to pump Servo from");
        }
    }

    self.servo = Some(servo.clone());
    servo
}

fn pump(&mut self) {
    let Some(servo) = self.servo.clone() else {
        return;
    };
    self.webviews
        .retain(|id| Gd::<ServoWebView>::try_from_instance_id(*id).is_ok());
    let active: Vec<Gd<ServoWebView>> = self
        .webviews
        .iter()
        .filter_map(|id| Gd::<ServoWebView>::try_from_instance_id(*id).ok())
        .filter(|webview| webview.is_inside_tree() && webview.can_process())
        .collect();

    // While every node is paused, so is Servo, as it was when each node
    // pumped from its own `_process`. With no node running at all there is
    // still the last WebView's teardown to finish, so a wake-up is answered.
    if let (Some(audio), Some(mixer)) = (&mut self.audio, audio::Mixer::get()) {
        audio.pump(mixer, active.is_empty());
    }

    let woken = self.waker.take_pending();
    if active.is_empty() && (!self.webviews.is_empty() || !woken) {
        return;
    }

    for mut webview in active {
        webview.bind_mut().before_spin();
    }
    // `spin_event_loop()` makes Servo's GL context current.
    let _host_context = HostContext::capture();
    servo.spin_event_loop();
}

fn start_audio(&mut self, tree: Option<&Gd<SceneTree>>) {
    let Some(tree) = tree else {
        godot_error!("godot-servo: no SceneTree to play audio in");
        return;
    };
    audio::install(AudioServer::singleton().get_mix_rate() as u32);
    if let Some(mixer) = audio::Mixer::get() {
        self.audio = Some(AudioOutput::new(tree, &self.audio_bus, mixer));
    }
}

fn point_temp_dir_at_app_cache() {
    if !cfg!(target_os = "android") || std::env::var_os("TMPDIR").is_some() {
        return;
    }
    let cache = godot::classes::Os::singleton().get_cache_dir().to_string();
    if !cache.is_empty() {
        std::env::set_var("TMPDIR", cache);
    }
}

#[derive(GodotClass)]
#[class(base=Node, init)]
pub struct ServoWebView {
    base: Base<Node>,

    /// The URL to open on start.
    #[export]
    #[init(val = GString::from("about:blank"))]
    url: GString,

    /// The WebView resolution, in pixels.
    #[export]
    #[init(val = Vector2i::new(1024, 768))]
    view_size: Vector2i,

    /// Whether to start automatically once the scene is ready.
    ///
    /// The start is deferred past `_ready()`, so it comes after every node in
    /// the scene is ready, and so any of them can still set `ServoServer` up.
    #[export]
    #[init(val = true)]
    autostart: bool,

    /// Where to put the IME candidate window, in window coordinates.
    ///
    /// The caret position inside the WebView cannot be used as it is: on a 3D
    /// panel there is no correspondence between a position on the panel and one
    /// on screen. Take the caret rectangle from the `ime_requested` signal,
    /// project it in the game, and assign the result here. The default (0, 0) is
    /// the top-left of the window.
    #[export]
    ime_anchor: Vector2,

    inner: Option<Inner>,
    /// `autostart` queued a start that `start()` or `stop()` has not overtaken.
    autostart_pending: bool,
    next_script_id: i64,
    /// Answers to `evaluate_javascript()` calls made while nothing was running.
    /// They cannot go on the sink's queue, which lives in `Inner`, so they wait
    /// here for the next `_process` to emit them alongside it.
    deferred_results: Vec<(i64, String)>,

    /// Whether the IME is up. True only while an editable element has focus.
    ime_active: bool,
    /// Whether a composition is in progress, so `CompositionState::Start` is
    /// sent exactly once.
    composing: bool,
    /// The previous preedit string, used to drop notifications that changed nothing.
    last_preedit: GString,
    /// The composition ended and the committed text is expected to arrive as key events.
    awaiting_commit: bool,
    /// Where that committed text is assembled.
    pending_commit: String,
}

fn godot_key_to_servo(event: &Gd<InputEventKey>) -> Option<Key> {
    use servo::NamedKey;

    let named = match event.get_keycode() {
        GodotKey::ENTER | GodotKey::KP_ENTER => NamedKey::Enter,
        GodotKey::BACKSPACE => NamedKey::Backspace,
        GodotKey::TAB => NamedKey::Tab,
        GodotKey::ESCAPE => NamedKey::Escape,
        GodotKey::DELETE => NamedKey::Delete,
        GodotKey::LEFT => NamedKey::ArrowLeft,
        GodotKey::RIGHT => NamedKey::ArrowRight,
        GodotKey::UP => NamedKey::ArrowUp,
        GodotKey::DOWN => NamedKey::ArrowDown,
        GodotKey::HOME => NamedKey::Home,
        GodotKey::END => NamedKey::End,
        GodotKey::PAGEUP => NamedKey::PageUp,
        GodotKey::PAGEDOWN => NamedKey::PageDown,
        GodotKey::SHIFT => NamedKey::Shift,
        GodotKey::CTRL => NamedKey::Control,
        GodotKey::ALT => NamedKey::Alt,
        GodotKey::META => NamedKey::Meta,
        _ => {
            // Printable characters go through unchanged.
            let unicode = event.get_unicode();
            if let Some(character) = char::from_u32(unicode).filter(|c| !c.is_control()) {
                return Some(Key::Character(character.to_string()));
            }
            return shortcut_character(event).map(Key::Character);
        }
    };
    Some(Key::Named(named))
}

fn shortcut_character(event: &Gd<InputEventKey>) -> Option<String> {
    if !(event.is_ctrl_pressed() || event.is_alt_pressed() || event.is_meta_pressed()) {
        return None;
    }

    // `Key` is a wrapper around an ordinal, not a Rust enum, so the letters and
    // digits are picked out by range rather than by pattern. Godot puts both at
    // their ASCII codes, the letters uppercase.
    let keycode = event.get_keycode().ord();
    let letters = GodotKey::A.ord()..=GodotKey::Z.ord();
    let digits = GodotKey::KEY_0.ord()..=GodotKey::KEY_9.ord();

    let character = if letters.contains(&keycode) {
        let upper = char::from_u32(keycode as u32)?;
        if event.is_shift_pressed() {
            upper
        } else {
            upper.to_ascii_lowercase()
        }
    } else if digits.contains(&keycode) {
        char::from_u32(keycode as u32)?
    } else {
        return None;
    };
    Some(character.to_string())
}

fn resolve<T>(&self, path: &NodePath, name: &str, missing: &mut Vec<String>) -> Option<Gd<T>>
where
    T: GodotClass + Inherits<Node>,
{
    if path.is_empty() {
        missing.push(name.into());
        return None;
    }
    match self.base().try_get_node_as::<T>(path) {
        Some(node) => Some(node),
        None => {
            missing.push(name.into());
            None
        }
    }
}

fn wire_session(&mut self) {
    let Some(mut session) = self
        .base()
        .try_get_node_as::<AthanorHostSession>(&self.session_path)
    else {
        self.detail = "shared Host session not found".into();
        return;
    };
    let this = self.to_gd();
    for (signal, method) in [
        ("opened", "on_host_opened"),
        ("closed", "on_host_closed"),
        ("malformed", "on_host_malformed"),
        ("unavailable", "on_host_unavailable"),
        ("message", "on_host_message"),
    ] {
        session.connect(signal, &Callable::from_object_method(&this, method));
    }
    self.session = Some(session);
}

#[godot_api]
impl AthanorDispatch {
    #[func]
    fn on_host_opened(&mut self) {
        self.detail = "Host connected; waiting for authenticated binding".into();
        self.render();
    }

    #[func]
    fn on_host_closed(&mut self, detail: GString) {
        self.pending_correlation = None;
        self.detail = format!("Host disconnected: {detail}");
        self.render();
    }

    #[func]
    fn on_host_malformed(&mut self, detail: GString) {
        self.pending_correlation = None;
        self.detail = format!("malformed JSON refused: {detail}");
        self.render();
    }

    #[func]
    fn on_host_unavailable(&mut self, detail: GString) {
        self.pending_correlation = None;
        self.detail = detail.to_string();
        self.render();
    }

    #[func]
    fn on_host_message(&mut self, envelope: VarDictionary) {
        let correlation = protocol::event_correlation_id(&envelope).ok();
        if correlation.as_deref() == self.pending_correlation.as_deref() {
            match protocol::parse_dispatch_result(&envelope) {
                Ok(projection) => {
                    self.pending_correlation = None;
                    self.detail =
                        "authenticated packet receipt applied; nothing was executed".into();
                    self.projection = Some(projection);
                }
                Err(reason) => {
                    self.pending_correlation = None;
                    self.detail = format!("dispatch receipt refused: {reason}");
                }
            }
        }
        self.render();
    }

    #[func]
    fn on_form_changed(&mut self) {
        self.render();
    }

    #[func]
    fn on_send_pressed(&mut self) {
        self.send_request();
        self.render();
    }
}

#[godot_api]
impl AthanorFamiliarStatus {
    #[func]
    fn on_host_opened(&mut self) {
        self.detail = "Host connected; waiting for authenticated binding".into();
        self.request_status();
        self.render();
    }

    #[func]
    fn on_host_closed(&mut self, detail: GString) {
        self.pending_correlation = None;
        self.detail = format!("Host disconnected: {detail}");
        self.render();
    }

    #[func]
    fn on_host_malformed(&mut self, detail: GString) {
        self.pending_correlation = None;
        self.detail = format!("malformed JSON refused: {detail}");
        self.render();
    }

    #[func]
    fn on_host_unavailable(&mut self, detail: GString) {
        self.pending_correlation = None;
        self.detail = detail.to_string();
        self.render();
    }

    #[func]
    fn on_host_message(&mut self, envelope: VarDictionary) {
        let correlation = protocol::event_correlation_id(&envelope).ok();
        if correlation.as_deref() == self.pending_correlation.as_deref() {
            match protocol::parse_familiar_status(&envelope) {
                Ok(projection) => {
                    self.pending_correlation = None;
                    self.detail = "authenticated familiar status applied".into();
                    self.projection = Some(projection);
                }
                Err(reason) => {
                    self.pending_correlation = None;
                    self.detail = format!("familiar status refused: {reason}");
                }
            }
        } else if self.projection.is_none() && self.pending_correlation.is_none() {
            self.request_status();
        }
        self.render();
    }

    #[func]
    fn on_refresh_pressed(&mut self) {
        self.request_status();
        self.render();
    }
}

#[godot_api]
impl AthanorHealth {
    #[func]
    fn on_host_opened(&mut self) {
        self.detail = "Host transport opened; awaiting authenticated EventMeta".into();
        self.render();
    }

    #[func]
    fn on_host_closed(&mut self, detail: GString) {
        self.binding = None;
        self.recall_request = None;
        self.boat_request = None;
        self.detail = format!("Host disconnected: {detail}");
        self.render();
    }

    #[func]
    fn on_host_malformed(&mut self, detail: GString) {
        self.last_refusal = Some(format!("malformed JSON: {detail}"));
        self.recall_request = None;
        self.boat_request = None;
        self.detail = "Host JSON refused".into();
        self.render();
    }

    #[func]
    fn on_host_unavailable(&mut self, detail: GString) {
        self.detail = detail.to_string();
        self.render();
    }

    #[func]
    fn on_host_message(&mut self, envelope: VarDictionary) {
        let projection = protocol::event_projection_id(&envelope);
        let correlation = protocol::event_correlation_id(&envelope).ok();
        match projection.as_deref() {
            Ok(::protocol::RECALL_POLICY_PROJECTION_ID) => self.apply_recall(&envelope),
            Ok(::protocol::PAPER_BOAT_RECEIPT_PROJECTION_ID) => self.apply_boat(&envelope),
            Ok(::protocol::ROUTING_PROJECTION_ID) => self.apply_routing(&envelope),
            Ok(_) => {}
            Err(reason) => self.last_refusal = Some(format!("EventMeta refused: {reason}")),
        }
        if correlation.as_deref() == self.recall_request.as_deref() {
            self.recall_request = None;
        }
        if correlation.as_deref() == self.boat_request.as_deref() {
            self.boat_request = None;
        }
        self.render();
    }

    #[func]
    fn on_refresh_pressed(&mut self) {
        self.request_snapshots();
        self.render();
    }
}

pub struct HostLink {
    peer: Gd<WebSocketPeer>,
    rng: Gd<RandomNumberGenerator>,
    phase: LinkPhase,
    url: String,
}

pub fn new() -> Self {
    let mut rng = RandomNumberGenerator::new_gd();
    rng.randomize();
    Self {
        peer: WebSocketPeer::new_gd(),
        rng,
        phase: LinkPhase::Closed,
        url: String::new(),
    }
}

#[godot_api]
impl AthanorHostSession {
    #[signal]
    fn opened();

    #[signal]
    fn closed(detail: GString);

    #[signal]
    fn malformed(detail: GString);

    #[signal]
    fn unavailable(detail: GString);

    #[signal]
    fn message(envelope: VarDictionary);

    #[func]
    fn reconnect(&mut self, url: GString) -> bool {
        match self.open(&url.to_string()) {
            Ok(()) => true,
            Err(reason) => {
                self.base_mut()
                    .emit_signal("unavailable", &[reason.to_variant()]);
                false
            }
        }
    }

    #[func]
    fn disconnect_host(&mut self) {
        self.close();
    }
}

impl AthanorHostSession {
    pub fn phase(&self) -> LinkPhase {
        self.link.phase()
    }

    pub fn url(&self) -> &str {
        self.link.url()
    }

    pub fn binding(&self) -> Option<HostBinding> {
        self.binding.clone()
    }

    pub fn new_identifier(&mut self) -> String {
        self.link.new_identifier()
    }

    pub fn send(&mut self, envelope: &VarDictionary) -> Result<(), String> {
        self.link.send(envelope)
    }

    pub fn open(&mut self, url: &str) -> Result<(), String> {
        if self.link.phase() != LinkPhase::Closed {
            self.link.close();
        }
        self.binding = None;
        let token = Os::singleton()
            .get_environment("ATHANOR_HOST_TOKEN")
            .to_string();
        self.link.open(url, &token)?;
        self.base_mut().set_process(true);
        Ok(())
    }

    pub fn close(&mut self) {
        self.link.close();
        self.binding = None;
        self.base_mut().set_process(false);
    }
}

fn utc_timestamp(unix_seconds: i64) -> String {
    let time = Time::singleton();
    format!("{}Z", time.get_datetime_string_from_unix_time(unix_seconds))
}

fn base_envelope(
    binding: Option<&HostBinding>,
    command_type: &str,
    identity: &CommandIdentity,
) -> VarDictionary {
    let time = Time::singleton();
    let now = time.get_unix_time_from_system() as i64;
    let field = |pick: fn(&HostBinding) -> &String| -> String {
        binding.map(pick).cloned().unwrap_or_default()
    };

    let mut envelope = VarDictionary::new();
    envelope.set("schema_version", SCHEMA_VERSION);
    envelope.set("message_id", identity.message_id.clone());
    envelope.set("house_id", field(|b| &b.house_id));
    envelope.set("sender_room", field(|b| &b.room));
    envelope.set("sender_spirit", field(|b| &b.spirit));
    envelope.set("sender_session", field(|b| &b.session));
    envelope.set("recipient", field(|b| &b.recipient));
    envelope.set("command_or_event_type", command_type);
    envelope.set("correlation_id", identity.message_id.clone());
    envelope.set("causation_id", identity.causation_id.clone());
    envelope.set("reply_target", field(|b| &b.session));
    envelope.set("idempotency_key", identity.idempotency_key.clone());
    envelope.set("source_record_refs", &VarArray::new().to_variant());
    envelope.set("scope", field(|b| &b.scope));
    envelope.set("visibility", field(|b| &b.visibility));
    envelope.set("authority_class", field(|b| &b.authority_class));
    envelope.set("created_at", utc_timestamp(now));
    envelope.set("expires_at", utc_timestamp(now + COMMAND_EXPIRY_SECONDS));
    envelope.set("max_hops", MAX_HOPS);
    envelope.set("projection_id", PROJECTION_ID);
    envelope
}

fn resolve<T>(&self, path: &NodePath, name: &str, missing: &mut Vec<String>) -> Option<Gd<T>>
where
    T: GodotClass + Inherits<Node>,
{
    if path.is_empty() {
        missing.push(name.to_string());
        return None;
    }
    match self.base().try_get_node_as::<T>(path) {
        Some(node) => Some(node),
        None => {
            missing.push(name.to_string());
            None
        }
    }
}

fn wire_controls(&mut self) {
    let this = self.to_gd();
    let host_url = self.host_url.clone();
    let Some(bound) = self.bound.as_mut() else {
        return;
    };

    bound.disclosure.set_text(RECALL_POLICY_DISCLOSURE);

    if bound.url_field.get_text().to_string().trim().is_empty() {
        bound.url_field.set_text(&host_url);
    }
    bound
        .url_field
        .set_placeholder(protocol::HOST_URL_PLACEHOLDER);
    bound.url_field.set_focus_mode(FocusMode::ALL);
    bound.url_field.connect(
        "text_submitted",
        &Callable::from_object_method(&this, "on_url_submitted"),
    );

    let handlers: [(&mut Gd<Button>, &str); 4] = [
        (&mut bound.connect_button, "on_connect_pressed"),
        (&mut bound.disconnect_button, "on_disconnect_pressed"),
        (&mut bound.snapshot_button, "on_snapshot_pressed"),
        (&mut bound.apply_button, "on_apply_pressed"),
    ];
    for (button, method) in handlers {
        button.set_focus_mode(FocusMode::ALL);
        button.connect("pressed", &Callable::from_object_method(&this, method));
    }

    let mode_methods = [
        "on_mode_auto_pressed",
        "on_mode_conversation_pressed",
        "on_mode_work_pressed",
        "on_mode_quiet_pressed",
    ];
    for (button, method) in bound.mode_buttons.iter_mut().zip(mode_methods) {
        button.set_focus_mode(FocusMode::ALL);
        button.connect("pressed", &Callable::from_object_method(&this, method));
    }
}

fn wire_session(&mut self) {
    let Some(mut session) = self
        .base()
        .try_get_node_as::<AthanorHostSession>(&self.session_path)
    else {
        self.link_state = LinkState::Idle;
        self.link_detail = "shared Host session not found".into();
        return;
    };
    let this = self.to_gd();
    for (signal, method) in [
        ("opened", "on_host_opened"),
        ("closed", "on_host_closed"),
        ("malformed", "on_host_malformed"),
        ("unavailable", "on_host_unavailable"),
        ("message", "on_host_message"),
    ] {
        session.connect(signal, &Callable::from_object_method(&this, method));
    }
    self.session = Some(session);
}

fn wire_session(&mut self) {
    let Some(mut session) = self
        .base()
        .try_get_node_as::<AthanorHostSession>(&self.session_path)
    else {
