        return;
    };
    let this = self.to_gd();
    session.connect(
        "opened",
        &Callable::from_object_method(&this, "on_host_opened"),
    );
    session.connect(
        "closed",
        &Callable::from_object_method(&this, "on_host_closed"),
    );
    session.connect(
        "malformed",
