impl PartyHost {
    /// Запустить сервер. Ошибка — если бинарник не нашёлся или не стартовал.
    pub fn start(master: &str, preset: &str) -> Result<Self, String> {
        let binary = find_server().ok_or_else(|| "oh-server рядом с игрой не найден".to_string())?;

        let settings = ProjectSettings::singleton();
        let presets = settings.globalize_path("res://presets").to_string();
        let status_path = settings.globalize_path("user://party.json").to_string();
        // Файл прошлой игры не должен сойти за свежий.
        let _ = godot::classes::DirAccess::remove_absolute(&status_path);

        let core = core_next_to(&binary);
        let args = host_args(master, preset, &presets, &core, &status_path);

        let packed: PackedStringArray = args.iter().map(GString::from).collect();
        let pid = Os::singleton().create_process(&binary, &packed);
        if pid <= 0 {
            return Err(format!("не запустить {binary}"));
        }
        Ok(Self {
            pid,
            status_path,
            waited: 0.0,
        })
    }

    /// Проверить, не готов ли сервер. `Err` — время вышло.
    pub fn poll(&mut self, delta: f64) -> Result<Option<PartyStatus>, String> {
        if let Some(file) = FileAccess::open(&self.status_path, ModeFlags::READ) {
            let text = file.get_as_text().to_string();
            if !text.trim().is_empty() {
                let status = parse_status(&text)?;
                // Файл мог появиться раньше, чем сервер договорил: ждём флага.
                if status.ready {
                    return Ok(Some(status));
                }
            }
        }
        self.waited += delta;
        if self.waited > START_TIMEOUT {
            return Err("сервер не поднялся".to_string());
        }
        Ok(None)
    }

    /// Остановить сервер: игра с другом заканчивается вместе с игрой.
    pub fn stop(&self) {
        if self.pid > 0 {
            Os::singleton().kill(self.pid);
        }
    }
}

fn find_server() -> Option<String> {
    let os = Os::singleton();
    let windows = os.get_name() == "Windows";
    let exe_dir = os
        .get_executable_path()
        .to_string()
        .rsplit_once(['/', '\\'])
        .map(|(dir, _)| dir.to_string())
        .unwrap_or_default();
    let project_dir = ProjectSettings::singleton()
        .globalize_path("res://")
        .to_string();

    server_candidates(&exe_dir, &project_dir, windows)
        .into_iter()
        .find(|path| FileAccess::file_exists(path))
}

pub struct NetClient {
    socket: Gd<WebSocketPeer>,
    session: Session,
    url: String,
    /// Накопитель времени до следующей отправки ввода.
    input_timer: f32,
    /// Сокет уже открывался: по переходу в CLOSED сообщаем об обрыве один раз.
    was_open: bool,
    closed_reported: bool,
    /// Когда последний раз уходил пинг-заполнитель (мс движка).
    last_keepalive: i64,
}

pub fn connect(url: &str, nickname: &str, preset: &str, content_hash: &str) -> Option<Self> {
    let mut socket = WebSocketPeer::new_gd();
    let error = socket.connect_to_url(url);
    if error != godot::global::Error::OK {
        godot_warn!("[net] не подключиться к {url}: {error:?}");
        return None;
    }

    let hello = Hello {
        protocol: VERSION,
        game_version: env!("CARGO_PKG_VERSION").to_string(),
        preset_id: preset.to_string(),
        content_hash: content_hash.to_string(),
        auth: Auth {
            mode: "open".to_string(),
            nickname: nickname.to_string(),
            ..Default::default()
        },
        ..Default::default()
    };

    Some(Self {
        socket,
        session: Session::new(hello),
        url: url.to_string(),
        input_timer: 0.0,
        was_open: false,
        closed_reported: false,
        last_keepalive: 0,
    })
}

pub fn send_keepalive(&mut self) {
    const PERIOD_MS: i64 = 1000;
    let now = godot::classes::Time::singleton().get_ticks_msec() as i64;
    if now - self.last_keepalive < PERIOD_MS {
        return;
    }
    self.last_keepalive = now;
    self.session.send_ping(now);
}

fn update_boss_phase(&mut self) {
    let health_ratio = if self.max_hp > 0.0 {
        self.hp / self.max_hp
    } else {
        0.0
    };
    while let Some(phase) = self.boss_phases.get(self.boss_phase_idx) {
        if health_ratio > phase.threshold {
            break;
        }
        let abilities = phase.abilities.clone();
        let damage_mult = phase.damage_mult;
        let speed_mult = phase.speed_mult;
        let tint = phase.tint;
        self.boss_phase_idx += 1;
        self.atk_damage *= damage_mult;
        self.speed *= speed_mult;
        for cfg in abilities {
            if self
                .abilities
                .iter()
                .any(|ability| ability.cfg.id == cfg.id)
            {
                continue;
            }
            self.abilities.push(AbilityRt {
                cd: cfg.cooldown.min(0.8),
                cfg,
            });
        }
        if let Some([r, g, b]) = tint {
            self.pending_color = Color::from_rgba(r, g, b, 1.0);
        }
        self.cast = None;
        self.charge_timer = 0.0;
        self.phase_transition = self.phase_transition.max(0.9);
        self.stagger = 0.0;
        self.alert_anim =
            Self::animation_duration(self.anim_cfg.alert_frames, self.anim_cfg.alert_fps());
        self.hurt_flash =
            Self::animation_duration(self.anim_cfg.pain_frames, self.anim_cfg.pain_fps());
        self.phase_reqs.push(PhaseReq {
            pos: self.base().get_global_position(),
            color: self.pending_color,
            boss_name: self.display_name(),
            phase: self.boss_phase_idx,
            total: self.boss_phases.len(),
        });
    }
}

pub fn set_player(&mut self, player: Gd<CharacterBody3D>) {
    self.player = Some(player);
}

pub fn weak_point_multiplier_at(&self, world_hit: Vector3) -> f32 {
    let body_height = 1.6 * self.vis_scale;
    let local_height = world_hit.y - self.base().get_global_position().y;
    if local_height >= body_height * self.weak_point_height {
        self.weak_point_multiplier
    } else {
        1.0
    }
}

fn separation(&self, my_pos: Vector3) -> Vector3 {
    let tree = self.base().get_tree();
    let my_id = self.base().instance_id();
    let mut push = Vector3::ZERO;
    for node in tree.get_nodes_in_group("enemies").iter_shared() {
        if node.instance_id() == my_id {
            continue;
        }
        let Ok(other) = node.try_cast::<Node3D>() else {
            continue;
        };
        let d = my_pos - other.get_global_position();
        let flat = Vector3::new(d.x, 0.0, d.z);
        let len = flat.length();
        if len > 0.01 && len < 1.7 {
            push += flat / len * (1.7 - len);
        }
    }
    push
}

fn apply_velocity(&mut self, vel: Vector3) {
    let mut fv = vel;
    if !self.base().is_on_floor() {
        fv.y = -9.8;
    }
    self.base_mut().set_velocity(fv);
    self.base_mut().move_and_slide();
}

fn has_los(&mut self, player_pos: Vector3) -> bool {
    let from = self.base().get_global_position() + Vector3::new(0.0, 1.3, 0.0);
    let to = player_pos + Vector3::new(0.0, 1.3, 0.0);
    let Some(world) = self.base().get_world_3d() else {
        return true;
    };
    let Some(mut space) = world.clone().get_direct_space_state() else {
        return true;
    };
    let Some(mut query) = PhysicsRayQueryParameters3D::create(from, to) else {
        return true;
    };
    let mut excl: godot::builtin::Array<Rid> = godot::builtin::Array::new();
    excl.push(self.base().get_rid());
    query.set_exclude(&excl);
    let hit = space.intersect_ray(&query);
    if hit.is_empty() {
        return true;
    }
    if let Some(cv) = hit.get("collider") {
        if let Ok(node) = cv.try_to::<Gd<godot::classes::Node>>() {
            if let Some(ref p) = self.player {
                return node.instance_id() == p.instance_id();
            }
        }
    }
    false
}

