pub(super) fn process_paused(&mut self) {
    let input = Input::singleton();
    if input.is_action_just_pressed("escape") || input.is_action_just_pressed("choice_1") {
        self.close_pause();
        return;
    }
    if input.is_action_just_pressed("choice_2") {
        self.auto_save();
