pub(super) fn respawn_at_hub(&mut self) {
    let lost = {
        let st = self.state.as_mut().unwrap();
        let lost = st.gold / 4;
        st.gold -= lost;
        lost
    };
    // возрождение снимает дебаффы (горение/замедление/оглушение)
    self.player_statuses.clear();
    if let Some(p) = self.player() {
        if let Ok(mut pl) = p.clone().try_cast::<Player>() {
            let mut b = pl.bind_mut();
            b.speed_mult = 1.0;
            b.stunned = false;
        }
    }
    if self.loc == Loc::Dungeon {
        self.clear_dungeon();
        self.loc = Loc::World;
    }
    if let Some(p) = self.player() {
        if let Ok(mut pl) = p.clone().try_cast::<Player>() {
            let max = pl.bind().max_hp;
            {
                let mut b = pl.bind_mut();
                b.dead = false;
                b.hp = max;
            }
            pl.bind_mut().teleport(Vector3::new(0.0, 1.1, 10.0));
        }
    }
    self.mode = Mode::Explore;
    if let Some(ref mut dp) = self.dead_panel {
        dp.set_visible(false);
    }
    Input::singleton().set_mouse_mode(godot::classes::input::MouseMode::CAPTURED);
    self.update_loc_label();
    self.show_flash(&if self.settings.lang == "en" {
        format!("You awaken in the hub. Gold lost: {lost}.")
    } else {
        format!("Ты очнулся в хабе. Потеряно золота: {lost}.")
    });
    self.auto_save();
}

pub(super) fn process_dialogue(&mut self) {
    if let Some(mut p) = self.player() {
        let mut vel = p.get_velocity();
        vel.x = 0.0;
        vel.z = 0.0;
        p.set_velocity(vel);
    }
    let input = Input::singleton();
    if !self.at_choices {
        if input.is_action_just_pressed("interact") {
            self.advance_dialogue();
        }
    } else {
        if input.is_action_just_pressed("choice_1") {
            self.select_choice(0);
        }
        if input.is_action_just_pressed("choice_2") {
            self.select_choice(1);
        }
        if input.is_action_just_pressed("choice_3") {
            self.select_choice(2);
        }
        if input.is_action_just_pressed("choice_4") {
            self.select_choice(3);
        }
    }
}

pub(super) fn process_inventory(&mut self) {
    if Input::singleton().is_action_just_pressed("choice_1") {
        self.select_weapon_mod(1);
        return;
    }
    if Input::singleton().is_action_just_pressed("choice_2") {
        self.select_weapon_mod(2);
        return;
    }
    if Input::singleton().is_action_just_pressed("inventory")
        || Input::singleton().is_action_just_pressed("escape")
    {
        self.close_inventory();
    }
    if Input::singleton().is_action_just_pressed("interact") {
        self.ui_use_item();
    }
}

pub(super) fn build_post_fx(&mut self) {
    use godot::classes::control::MouseFilter;
    use godot::classes::{ColorRect, Shader, ShaderMaterial};

    // Пост-обработку можно полностью выключить в настройках.
    if !self.settings.post_fx {
        return;
    }
    let k = self.settings.post_intensity.clamp(0.0, 2.0);

    let mut shader = Shader::new_gd();
    shader.set_code(POST_FX_SHADER);
    let mut mat = ShaderMaterial::new_gd();
    mat.set_shader(&shader);
    // базовые параметры масштабируем интенсивностью из настроек
    mat.set_shader_parameter("vignette", &(0.34_f32 * k).to_variant());
    mat.set_shader_parameter("aberration", &(1.4_f32 * k).to_variant());
    mat.set_shader_parameter("scanline", &(0.045_f32 * k).to_variant());
    mat.set_shader_parameter("grain", &(0.04_f32 * k).to_variant());

    let mut rect = ColorRect::new_alloc();
    rect.set_anchors_preset(godot::classes::control::LayoutPreset::FULL_RECT);
    rect.set_material(&mat);
    rect.set_mouse_filter(MouseFilter::IGNORE);

    let mut layer = CanvasLayer::new_alloc();
    layer.set_layer(0); // под HUD (1), поверх 3D-вьюпорта
    layer.add_child(&rect);
    self.base_mut().add_child(&layer);
    self.post_mat = Some(mat); // хэндл для реактивных импульсов
}

pub(super) fn refresh_weapon_sheet(&mut self) {
    let def = weapon_def(self.arsenal.current);
    let Some(tex) = self.cache.get(&def.sheet) else {
        return;
    };
    let mut at = AtlasTexture::new_gd();
    at.set_atlas(&tex);
    at.set_region(Rect2::new(
        Vector2::ZERO,
        Vector2::new(FRAME_W, def.frame_h),
    ));
    if let Some(ref mut wr) = self.weapon_rect {
        wr.set_texture(&at);
        // масштаб: высота на экране пропорциональна высоте кадра
        let k = def.view_scale;
        let w = FRAME_W * k;
        let h = def.frame_h * k;
        place(
            wr,
            0.5,
            1.0,
            HUD_W * 0.5 - w * 0.5 + def.view_offset[0],
            HUD_H - h + def.view_offset[1],
            w,
            h,
        );
        wr.set_visible(true);
    }
    self.weapon_atlas = Some(at);
    self.update_weapon_mod_visual();
    self.weapon_anim = WeaponAnim::Switch(def.switch_time);
    self.anim_timer = 0.0;
    self.melee_impact_pending = None;
    self.weapon_bloom = 0.0;
    self.set_weapon_frame(def.switch_frames[0]);
    if let Some(ref mut wl) = self.weapon_label {
        let alt_hint = def
            .alt_fire
            .as_ref()
            .map(|alt| {
                let name = if self.settings.lang == "en" {
                    &alt.name_en
                } else {
                    &alt.name_ru
                };
                format!("  |  RMB: {name}")
            })
            .unwrap_or_default();
        wl.set_text(&format!(
            "[{}] {}  ({}){}",
            def.id.slot() + 1,
            def.name(&self.settings.lang),
            def.dmg_type.name(&self.settings.lang),
            alt_hint,
        ));
    }
}

