    self.base_mut().set_velocity(Vector3::ZERO);
}

impl Settings {
    /// Применить видео-настройки: режим окна (фуллскрин/окно) + вертикальная синхр.
    pub fn apply_video(&self) {
        use godot::classes::display_server::{VSyncMode, WindowMode};
        use godot::classes::DisplayServer;
        use godot::obj::Singleton;
        let mut ds = DisplayServer::singleton();
        ds.window_set_mode(if self.fullscreen {
            WindowMode::FULLSCREEN
        } else {
            WindowMode::WINDOWED
        });
        ds.window_set_vsync_mode(if self.vsync {
            VSyncMode::ENABLED
        } else {
            VSyncMode::DISABLED
        });
    }

    /// Применить громкость к аудио-шинам (Master, а при наличии — Music/SFX).
    pub fn apply_audio(&self) {
        use godot::classes::AudioServer;
        use godot::obj::Singleton;
        let mut a = AudioServer::singleton();
        a.set_bus_volume_db(0, lin_to_db(self.master_vol));
        // Отдельные шины Music/SFX, если заведены (иначе тихо игнорируем).
        for (name, vol) in [("Music", self.music_vol), ("SFX", self.sfx_vol)] {
            let idx = a.get_bus_index(name);
            if idx >= 0 {
                a.set_bus_volume_db(idx, lin_to_db(vol));
            }
        }
    }

    /// Применить всё, что можно применить без узлов сцены (видео + аудио).
    pub fn apply_global(&self) {
        self.apply_video();
        self.apply_audio();
    }
}

#[derive(Default)]
pub struct TexCache {
    map: HashMap<String, Option<Gd<Texture2D>>>,
}

impl TexCache {
    pub fn new() -> Self {
        Self {
            map: HashMap::new(),
        }
    }

    pub fn get(&mut self, path: &str) -> Option<Gd<Texture2D>> {
        if let Some(t) = self.map.get(path) {
            return t.clone();
        }
        let tex = ResourceLoader::singleton()
            .load(path)
            .and_then(|resource| resource.try_cast::<Texture2D>().ok());
        self.map.insert(path.to_string(), tex.clone());
        tex
    }
}

pub fn make_box(
    pos: Vector3,
    size: Vector3,
    color: Color,
    tex: Option<&Gd<Texture2D>>,
    _uv: f32,
) -> Gd<StaticBody3D> {
    let mut body = StaticBody3D::new_alloc();
    body.set_position(pos);

    let mut mi = MeshInstance3D::new_alloc();
    let mut mesh = BoxMesh::new_gd();
    mesh.set_size(size);
    mi.set_mesh(&mesh);

    let mut mat = StandardMaterial3D::new_gd();
    if let Some(t) = tex {
        mat.set_albedo(Color::WHITE);
        mat.set_texture(TextureParam::ALBEDO, t);
        mat.set_uv1_scale(Vector3::splat(1.0 / TEXEL_M));
        mat.set_flag(Flags::UV1_USE_TRIPLANAR, true);
        mat.set_flag(Flags::UV1_USE_WORLD_TRIPLANAR, true);
        mat.set_texture_filter(TextureFilter::NEAREST_WITH_MIPMAPS_ANISOTROPIC);
    } else {
        mat.set_albedo(color);
    }
    mi.set_surface_override_material(0, &mat);

    let mut col = CollisionShape3D::new_alloc();
    let mut shape = BoxShape3D::new_gd();
    shape.set_size(size);
    col.set_shape(&shape);

    body.add_child(&mi);
    body.add_child(&col);
    body
}

pub fn make_box_rot(
    pos: Vector3,
    size: Vector3,
    rot_y: f32,
    color: Color,
    tex: Option<&Gd<Texture2D>>,
    uv: f32,
) -> Gd<StaticBody3D> {
    let mut b = make_box(pos, size, color, tex, uv);
    b.set_rotation(Vector3::new(0.0, rot_y, 0.0));
    b
}

pub fn make_ramp(
    low: Vector3,
    high: Vector3,
    width: f32,
    thick: f32,
    color: Color,
    tex: Option<&Gd<Texture2D>>,
) -> Gd<StaticBody3D> {
    let dir = high - low;
    let len = dir.length().max(0.01);
    let dirn = dir / len;
    // ось ширины — перпендикуляр к направлению склона в горизонтали
    let right = Vector3::UP.cross(dirn).normalized();
    let up = dirn.cross(right).normalized();
    let uv = (len / 3.0).max(1.0);
    // размеры запекаем в меш/шейп; basis — чистое вращение (ортонормированный)
    let mut body = make_box(
        Vector3::ZERO,
        Vector3::new(width, thick, len),
        color,
        tex,
        uv,
    );
    let basis = Basis::from_cols(right, up, dirn);
    body.set_transform(Transform3D {
        basis,
        origin: (low + high) * 0.5 - up * (thick * 0.5),
    });
    body
}

pub fn make_glow_slab(
    pos: Vector3,
    size: Vector3,
    tex: Option<&Gd<Texture2D>>,
    emission: Color,
    _uv: f32,
) -> Gd<MeshInstance3D> {
    let mut mi = MeshInstance3D::new_alloc();
    let mut mesh = BoxMesh::new_gd();
    mesh.set_size(size);
    mi.set_mesh(&mesh);
    mi.set_position(pos);
    let mut mat = StandardMaterial3D::new_gd();
    if let Some(t) = tex {
        mat.set_albedo(Color::WHITE);
        mat.set_texture(TextureParam::ALBEDO, t);
        mat.set_uv1_scale(Vector3::splat(1.0 / TEXEL_M));
        mat.set_flag(Flags::UV1_USE_TRIPLANAR, true);
        mat.set_flag(Flags::UV1_USE_WORLD_TRIPLANAR, true);
        mat.set_texture_filter(TextureFilter::NEAREST_WITH_MIPMAPS_ANISOTROPIC);
    }
    mat.set_feature(Feature::EMISSION, true);
    mat.set_emission(emission);
    mat.set_emission_energy_multiplier(0.9);
    mi.set_surface_override_material(0, &mat);
    mi
}

