fn ensure_render_device(&mut self) -> bool {
    if self.rd.is_some() {
        return true;
    }

    self.rd = RenderingServer::singleton().get_rendering_device();
    if self.rd.is_none() {
        godot_warn!("ParcelRendererNode: RenderingDevice unavailable in current editor state.");
        return false;
    }

    godot_print!("ParcelRendererNode: reacquired RenderingDevice.");
    true
}

fn resolve_render_size(&self) -> Vector2 {
    let settings = ProjectSettings::singleton();

    let width_v = settings.get_setting("display/window/size/viewport_width");
    let height_v = settings.get_setting("display/window/size/viewport_height");

    let Ok(width) = width_v.try_to::<i64>() else {
        godot_error!(
            "ParcelRendererNode: project setting display/window/size/viewport_width is not an integer."
        );
        return Vector2::ZERO;
    };

    let Ok(height) = height_v.try_to::<i64>() else {
        godot_error!(
            "ParcelRendererNode: project setting display/window/size/viewport_height is not an integer."
        );
        return Vector2::ZERO;
    };

    if width <= 0 || height <= 0 {
        godot_error!(
            "ParcelRendererNode: invalid project viewport size {}x{} from ProjectSettings.",
            width,
            height,
        );
        return Vector2::ZERO;
    }

    if !self.render_scale.is_finite() || self.render_scale <= 0.0 {
        godot_error!(
            "ParcelRendererNode: render_scale must be a positive finite number, got {}.",
            self.render_scale,
        );
        return Vector2::ZERO;
    }

    let scaled = Vector2::new(width as f32, height as f32) * self.render_scale;
    Vector2::new(scaled.x.round().max(1.0), scaled.y.round().max(1.0))
}

fn sync_size_and_resources(&mut self) {
    if !self.ensure_render_device() {
        return;
    }

    let size = self.resolve_render_size();
    let new_w = size.x as u32;
    let new_h = size.y as u32;

    if new_w <= 2 || new_h <= 2 {
        if !self.logged_waiting_for_size {
            godot_print!(
                "ParcelRendererNode waiting for valid render size from ProjectSettings; current={}x{}.",
                new_w,
                new_h,
            );
            self.logged_waiting_for_size = true;
        }
        return;
    }

    if self.logged_waiting_for_size {
        godot_print!(
            "ParcelRendererNode received valid project viewport size={}x{}.",
            new_w,
            new_h,
        );
        self.logged_waiting_for_size = false;
    }

    let resized = new_w != self.width || new_h != self.height;
    if resized {
        self.width = new_w;
        self.height = new_h;
        godot_print!(
            "ParcelRendererNode using render target {}x{}.",
            self.width,
            self.height,
        );
    }

    if let Some(mut rd) = self.rd.take() {
        if resized {
            self.remove_preview_node();
            self.recreate_resources(&mut rd);
            self.attach_preview_texture();
        } else if !self.resources_ready() {
            self.create_texture(&mut rd);
            self.create_pipeline_and_uniforms(&mut rd);
            self.attach_preview_texture();
        } else if !self.has_preview_node() {
            self.attach_preview_texture();
        }

        self.rd = Some(rd);
    }
}

pub(super) fn on_ready(&mut self) {
    self.base_mut().set_process(true);

    self.sync_size_and_resources();
}

pub(super) fn on_process(&mut self, delta: f64) {
    let in_editor = Engine::singleton().is_editor_hint();
    let show_preview = !in_editor || !self.editor_selection_known || self.editor_selected;
    self.set_preview_visible(show_preview);
    if !show_preview {
        return;
    }

    self.sync_size_and_resources();

    if self.pipeline_rid == Rid::Invalid || self.uniform_set_rid == Rid::Invalid {
        return;
    }

    if self.animate {
        self.time_seconds += delta as f32;
    }

    let camera_data = self.camera_data_for_frame();

    let Some(mut rd) = self.rd.take() else {
        return;
    };

    let parcel_count = (self.parcel_data.len() / PARCEL_FLOATS_PER_INSTANCE) as f32;

    if self.time_buffer_rid != Rid::Invalid {
        let frame_data = [
            self.time_seconds,
            0.0f32,
            0.0f32,
            0.0f32,
            parcel_count,
            0.0f32,
            0.0f32,
            0.0f32,
        ];
        let mut bytes = Vec::with_capacity(32);
        for value in frame_data {
            bytes.extend_from_slice(&value.to_le_bytes());
        }
        let packed = PackedByteArray::from(bytes.as_slice());
        let _ = rd.buffer_update(self.time_buffer_rid, 0, 32, &packed);
    }

    if self.camera_buffer_rid != Rid::Invalid {
        let _ = rd.buffer_update(self.camera_buffer_rid, 0, 128, &camera_data);
    }

    if self.parcel_buffer_rid != Rid::Invalid && self.parcel_data_dirty {
        let packed = parcel_bytes(&self.parcel_data);
        if !packed.is_empty() {
            let _ = rd.buffer_update(self.parcel_buffer_rid, 0, packed.len() as u32, &packed);
        }
        self.parcel_data_dirty = false;
    }

    let list = rd.compute_list_begin();
    rd.compute_list_bind_compute_pipeline(list, self.pipeline_rid);
    rd.compute_list_bind_uniform_set(list, self.uniform_set_rid, 0);
    rd.compute_list_dispatch(list, self.width.div_ceil(8), self.height.div_ceil(8), 1);
    rd.compute_list_end();
    self.rd = Some(rd);

    self.base_mut().queue_redraw();
}

#[godot_api]
impl ParcelRendererNode {
    /// Replaces the rendered parcels with packed `Parcel` records of
    /// `PARCEL_FLOATS_PER_INSTANCE` floats each, as produced by the growth
    /// addon. Invalid input is rejected and the previous parcels are kept.
    #[func]
    fn set_parcels(&mut self, parcels: PackedFloat32Array) {
        let values = parcels.as_slice();
        if values.len() % PARCEL_FLOATS_PER_INSTANCE != 0 {
            godot_error!(
                "ParcelRendererNode: set_parcels expects packed records of {} floats, got {} floats.",
                PARCEL_FLOATS_PER_INSTANCE,
                values.len(),
            );
            return;
        }

        let count = values.len() / PARCEL_FLOATS_PER_INSTANCE;
        if count > MAX_PARCELS {
            godot_error!(
                "ParcelRendererNode: set_parcels received {} parcels but the buffer holds at most {}.",
                count,
                MAX_PARCELS,
            );
            return;
        }

        let previous_count = self.parcel_data.len() / PARCEL_FLOATS_PER_INSTANCE;
        self.parcel_data.clear();
        self.parcel_data.extend_from_slice(values);
        self.parcel_data_dirty = true;
        if count != previous_count {
            godot_print!("ParcelRendererNode: received {} parcels.", count);
        }
    }

    #[func]
    fn set_editor_selected(&mut self, selected: bool) {
        self.editor_selected = selected;
        self.editor_selection_known = true;
    }
}

impl ParcelRendererNode {
    pub(super) fn parcel_buffer_size_bytes() -> u32 {
        (MAX_PARCELS * PARCEL_FLOATS_PER_INSTANCE * std::mem::size_of::<f32>()) as u32
    }

    pub(super) fn camera_data_for_frame(&mut self) -> PackedByteArray {
        if let Some(vp) = self.base().get_viewport() {
            if let Some(camera) = vp.get_camera_3d() {
                return camera_uniform_bytes(
                    camera.get_camera_transform(),
                    camera.get_camera_projection(),
                );
            }
        }

        if let Some(camera) = self
            .base()
            .try_get_node_as::<Camera3D>("../Camera3D")
            .or_else(|| self.base().try_get_node_as::<Camera3D>("Camera3D"))
        {
            return camera_uniform_bytes(
                camera.get_camera_transform(),
                camera.get_camera_projection(),
            );
        }

        camera_uniform_bytes(Transform3D::IDENTITY, Projection::IDENTITY)
    }

    pub(super) fn destroy_resources(&mut self, rd: &mut Gd<RenderingDevice>) {
        resources::destroy_resources(self, rd);
    }

    pub(super) fn recreate_resources(&mut self, rd: &mut Gd<RenderingDevice>) {
        resources::recreate_resources(self, rd);
    }

    pub(super) fn create_texture(&mut self, rd: &mut Gd<RenderingDevice>) {
        resources::create_texture(self, rd);
    }

    pub(super) fn create_pipeline_and_uniforms(&mut self, rd: &mut Gd<RenderingDevice>) {
        resources::create_pipeline_and_uniforms(self, rd);
    }
}

fn log_shader_source_attempt() {
    let file_path = ProjectSettings::singleton()
        .globalize_path(SHADER_PATH)
        .to_string();
    let source = std::fs::read_to_string(&file_path).unwrap_or_else(|error| {
        format!("failed to read shader source from '{file_path}': {error}")
    });

    let compact = collapse_log_lines(&source);
    godot_warn!(
        "ParcelRendererNode: compiling shader '{}'. Source preview: {}",
        SHADER_PATH,
        compact
    );
}

pub(super) fn destroy_resources(node: &mut ParcelRendererNode, rd: &mut Gd<RenderingDevice>) {
    if node.uniform_set_rid != Rid::Invalid {
        rd.free_rid(node.uniform_set_rid);
        node.uniform_set_rid = Rid::Invalid;
    }
    if node.pipeline_rid != Rid::Invalid {
        rd.free_rid(node.pipeline_rid);
        node.pipeline_rid = Rid::Invalid;
    }
    if node.shader_rid != Rid::Invalid {
        rd.free_rid(node.shader_rid);
        node.shader_rid = Rid::Invalid;
    }
    if node.texture_rid != Rid::Invalid {
        rd.free_rid(node.texture_rid);
        node.texture_rid = Rid::Invalid;
    }
    if node.time_buffer_rid != Rid::Invalid {
        rd.free_rid(node.time_buffer_rid);
        node.time_buffer_rid = Rid::Invalid;
    }
    if node.camera_buffer_rid != Rid::Invalid {
        rd.free_rid(node.camera_buffer_rid);
        node.camera_buffer_rid = Rid::Invalid;
    }
    if node.parcel_buffer_rid != Rid::Invalid {
        rd.free_rid(node.parcel_buffer_rid);
        node.parcel_buffer_rid = Rid::Invalid;
    }
}

pub(super) fn create_texture(node: &mut ParcelRendererNode, rd: &mut Gd<RenderingDevice>) {
    let usage = TextureUsageBits::STORAGE_BIT | TextureUsageBits::SAMPLING_BIT;
    let data_format = DataFormat::R32G32B32A32_SFLOAT;

    if !rd.texture_is_format_supported_for_usage(data_format, usage) {
        node.texture_rid = Rid::Invalid;
        godot_warn!(
            "ParcelRendererNode: R32G32B32A32_SFLOAT not supported for STORAGE|SAMPLING usage."
        );
        return;
    }

    let mut format = RdTextureFormat::new_gd();
    format.set_width(node.width);
    format.set_height(node.height);
    format.set_format(data_format);
    format.set_usage_bits(usage);

    let view = RdTextureView::new_gd();
    node.texture_rid = rd.texture_create(&format, &view);
    if node.texture_rid != Rid::Invalid {
        return;
    }

    node.texture_rid = Rid::Invalid;
    godot_warn!("ParcelRendererNode: failed to create RGBA32F output texture.");
}

fn create_time_buffer(node: &mut ParcelRendererNode, rd: &mut Gd<RenderingDevice>) {
    // vec4 time + vec4 scene params.
    node.time_buffer_rid = rd.uniform_buffer_create(32);
    if node.time_buffer_rid == Rid::Invalid {
        godot_warn!("ParcelRendererNode: failed to create iTime uniform buffer.");
    }
}

fn create_camera_buffer(node: &mut ParcelRendererNode, rd: &mut Gd<RenderingDevice>) {
    // Inverse view and inverse projection.
    node.camera_buffer_rid = rd.uniform_buffer_create(128);
    if node.camera_buffer_rid == Rid::Invalid {
        godot_warn!("ParcelRendererNode: failed to create camera uniform buffer.");
    }
}

fn create_parcel_buffer(node: &mut ParcelRendererNode, rd: &mut Gd<RenderingDevice>) {
    let byte_count = ParcelRendererNode::parcel_buffer_size_bytes();
    let initial_data = PackedByteArray::from(vec![0u8; byte_count as usize].as_slice());
    node.parcel_buffer_rid = rd.storage_buffer_create_ex(byte_count).data(&initial_data).done();
    if node.parcel_buffer_rid == Rid::Invalid {
        godot_warn!("ParcelRendererNode: failed to create parcel storage buffer.");
        return;
    }

    // The fresh buffer is zeroed, so whatever parcels are already loaded have
    // to be uploaded again on the next frame.
    node.parcel_data_dirty = true;
}

pub(super) fn recreate_resources(node: &mut ParcelRendererNode, rd: &mut Gd<RenderingDevice>) {
    destroy_resources(node, rd);
    create_texture(node, rd);
    create_pipeline_and_uniforms(node, rd);
}

pub(super) fn create_pipeline_and_uniforms(node: &mut ParcelRendererNode, rd: &mut Gd<RenderingDevice>) {
    if node.texture_rid == Rid::Invalid {
        godot_warn!("ParcelRendererNode: output texture RID is invalid.");
        return;
    }

    create_time_buffer(node, rd);
    if node.time_buffer_rid == Rid::Invalid {
        return;
    }

    create_camera_buffer(node, rd);
    if node.camera_buffer_rid == Rid::Invalid {
        return;
    }

    create_parcel_buffer(node, rd);
    if node.parcel_buffer_rid == Rid::Invalid {
        return;
    }

    let shader_file: Gd<RdShaderFile> = load(SHADER_PATH);
    if !shader_file.is_instance_valid() {
        godot_warn!("ParcelRendererNode: failed to load shader file {}", SHADER_PATH);
        return;
    }

    let Some(spirv) = shader_file.get_spirv() else {
        godot_warn!("ParcelRendererNode: failed to load SPIR-V from {}", SHADER_PATH);
        log_shader_source_attempt();
        return;
    };

    let bytecode = spirv.get_stage_bytecode(ShaderStage::COMPUTE);
    let byte_count = bytecode.len();
    let compile_error = spirv.get_stage_compile_error(ShaderStage::COMPUTE);

    if !compile_error.is_empty() {
        let compact_error = collapse_log_lines(&compile_error.to_string());
        godot_error!(
            "ParcelRendererNode: shader compile error for {} (compute stage): {}",
            SHADER_PATH,
            compact_error,
        );
    }

    godot_print!(
        "ParcelRendererNode: creating shader from SPIR-V bytes for {} ({} bytes).",
        SHADER_PATH,
        byte_count,
    );

    node.shader_rid = rd.shader_create_from_spirv(&spirv);
    if node.shader_rid == Rid::Invalid {
        godot_error!(
            "ParcelRendererNode: shader creation failed for {}. This usually means the bytecode or included shaders are invalid; shader source dump follows.",
            SHADER_PATH,
        );
        if !compile_error.is_empty() {
            let compact_error = collapse_log_lines(&compile_error.to_string());
            godot_error!("ParcelRendererNode: shader compile details: {}", compact_error);
        }
        log_shader_source_attempt();
        return;
    }

    node.pipeline_rid = rd.compute_pipeline_create(node.shader_rid);
    if node.pipeline_rid == Rid::Invalid {
        godot_warn!("ParcelRendererNode: failed to create compute pipeline RID.");
        return;
    }

    let mut output_image = RdUniform::new_gd();
    output_image.set_uniform_type(UniformType::IMAGE);
    output_image.set_binding(0);
    output_image.add_id(node.texture_rid);

    let mut time_uniform = RdUniform::new_gd();
    time_uniform.set_uniform_type(UniformType::UNIFORM_BUFFER);
    time_uniform.set_binding(1);
    time_uniform.add_id(node.time_buffer_rid);

    let mut camera_uniform = RdUniform::new_gd();
    camera_uniform.set_uniform_type(UniformType::UNIFORM_BUFFER);
    camera_uniform.set_binding(2);
    camera_uniform.add_id(node.camera_buffer_rid);

    let mut parcel_uniform = RdUniform::new_gd();
    parcel_uniform.set_uniform_type(UniformType::STORAGE_BUFFER);
    parcel_uniform.set_binding(3);
    parcel_uniform.add_id(node.parcel_buffer_rid);

    node.uniform_set_rid = rd.uniform_set_create(
        &Array::from_iter([output_image, time_uniform, camera_uniform, parcel_uniform]),
        node.shader_rid,
        0,
    );
    if node.uniform_set_rid == Rid::Invalid {
        godot_warn!(
            "ParcelRendererNode: failed to create uniform set (set=0, binding=0 image, binding=1 iTime, binding=2 camera, binding=3 parcels)."
        );
    }
}

impl ParcelRendererNode {
    pub(super) fn has_preview_node(&self) -> bool {
        self.base().try_get_node_as::<Sprite2D>(PREVIEW_NAME).is_some()
    }

    pub(super) fn attach_preview_texture(&mut self) {
        let mut texture = Texture2Drd::new_gd();
        texture.set_texture_rd_rid(self.texture_rid);
        let preview_scale = Vector2::splat(1.0 / self.render_scale);

        if let Some(mut sprite) = self.base().try_get_node_as::<Sprite2D>(PREVIEW_NAME) {
            sprite.set_texture(&texture);
            sprite.set_centered(false);
            sprite.set_scale(preview_scale);
            return;
        }

        let mut sprite = Sprite2D::new_alloc();
        sprite.set_name(PREVIEW_NAME);
        sprite.set_texture(&texture);
        sprite.set_centered(false);
        sprite.set_scale(preview_scale);
        self.base_mut().add_child(&sprite);
    }

    pub(super) fn set_preview_visible(&mut self, visible: bool) {
        if let Some(mut sprite) = self.base().try_get_node_as::<Sprite2D>(PREVIEW_NAME) {
            sprite.set_visible(visible);
        }
    }

    pub(super) fn remove_preview_node(&mut self) {
        if let Some(mut sprite) = self.base().try_get_node_as::<Sprite2D>(PREVIEW_NAME) {
            sprite.set_visible(false);
            sprite.queue_free();
        }
    }
}

pub fn run_cases<C: ParcelCase>(context: &str, shader_path: &str, cases: &[C]) -> TestReport {
    let total = cases.len();

    if !Engine::singleton().is_editor_hint() {
        return TestReport { passed: 0, total: 0 };
    }

    let Some(mut harness) = ComputeHarness::new(context, shader_path) else {
        godot_print!("[{}] ERROR could not run any of the {} cases.", context, total);
        return TestReport { passed: 0, total };
    };

    let mut passed = 0usize;
    let mut failed = 0usize;

    for case in cases {
        let label = case.label();
        match run_case(&mut harness, case) {
            Ok(()) => {
                godot_print!("[{}] PASS  '{}'", context, label);
                passed += 1;
            }
            Err(CaseError::Mismatch(msg)) => {
                godot_print!("[{}] FAIL  '{}'\n  {}", context, label, msg);
                failed += 1;
            }
            Err(CaseError::Broken(msg)) => {
                godot_print!("[{}] ERROR '{}': {}", context, label, msg);
                failed += 1;
            }
        }
    }

    godot_print!(
        "[{}] Results: {}/{} passed.",
        context,
        passed,
        passed + failed
    );

    TestReport {
        passed,
        total: passed + failed,
    }
}

pub struct ComputeHarness {
    rd: Gd<RenderingDevice>,
    pipeline_rid: Rid,
    shader_rid: Rid,
}

pub fn dispatch(&mut self, input: &[f32], output_floats: usize) -> Result<Vec<f32>, String> {
    const PARCEL_BUFFER_PARCELS: u32 = 100;
    // Keep this aligned with Parcel in core/structs.glslinc:
    // vec3 mean, mat3 covariance, mat3 inverseCovariance, float peakDensity, vec3 color
    // with std430 padding, which totals 36 float slots per parcel.
    const PARCEL_BUFFER_FLOATS_PER_PARCEL: u32 = 36;
    const PARCEL_BUFFER_BYTES: u32 = PARCEL_BUFFER_PARCELS * PARCEL_BUFFER_FLOATS_PER_PARCEL * 4;

    let mut input_bytes = Vec::with_capacity(input.len() * std::mem::size_of::<f32>());
    for value in input {
        input_bytes.extend_from_slice(&value.to_le_bytes());
    }
    let input_byte_count = input_bytes.len() as u32;
    let output_byte_count = (output_floats * std::mem::size_of::<f32>()) as u32;

    let input_buffer_rid = self
        .rd
        .storage_buffer_create_ex(input_byte_count)
        .data(&PackedByteArray::from(input_bytes.as_slice()))
        .done();
    if input_buffer_rid == Rid::Invalid {
        return Err("failed to create input storage buffer".into());
    }

    let zeroed = PackedByteArray::from(vec![0u8; output_byte_count as usize].as_slice());
    let output_buffer_rid = self
        .rd
        .storage_buffer_create_ex(output_byte_count)
        .data(&zeroed)
        .done();
    if output_buffer_rid == Rid::Invalid {
        self.rd.free_rid(input_buffer_rid);
        return Err("failed to create output storage buffer".into());
    }

    let parcel_zeroed = PackedByteArray::from(vec![0u8; PARCEL_BUFFER_BYTES as usize].as_slice());
    let parcel_buffer_rid = self
        .rd
        .storage_buffer_create_ex(PARCEL_BUFFER_BYTES)
        .data(&parcel_zeroed)
        .done();
    if parcel_buffer_rid == Rid::Invalid {
        self.rd.free_rid(input_buffer_rid);
        self.rd.free_rid(output_buffer_rid);
        return Err("failed to create parcel storage buffer".into());
    }

    let uniform_set_rid = {
        let mut input_uniform = RdUniform::new_gd();
        input_uniform.set_uniform_type(UniformType::STORAGE_BUFFER);
        input_uniform.set_binding(0);
        input_uniform.add_id(input_buffer_rid);

        let mut output_uniform = RdUniform::new_gd();
        output_uniform.set_uniform_type(UniformType::STORAGE_BUFFER);
        output_uniform.set_binding(1);
        output_uniform.add_id(output_buffer_rid);

        let mut parcel_uniform = RdUniform::new_gd();
        parcel_uniform.set_uniform_type(UniformType::STORAGE_BUFFER);
        parcel_uniform.set_binding(3);
        parcel_uniform.add_id(parcel_buffer_rid);

        self.rd.uniform_set_create(
            &Array::from_iter([input_uniform, output_uniform, parcel_uniform]),
            self.shader_rid,
            0,
        )
    };
    if uniform_set_rid == Rid::Invalid {
        self.rd.free_rid(input_buffer_rid);
        self.rd.free_rid(output_buffer_rid);
        self.rd.free_rid(parcel_buffer_rid);
        return Err("failed to create uniform set".into());
    }

    let list = self.rd.compute_list_begin();
    self.rd
        .compute_list_bind_compute_pipeline(list, self.pipeline_rid);
    self.rd
        .compute_list_bind_uniform_set(list, uniform_set_rid, 0);
    self.rd.compute_list_dispatch(list, 1, 1, 1);
    self.rd.compute_list_end();

    self.rd.submit();
    self.rd.sync();

    let result = self.rd.buffer_get_data(output_buffer_rid).to_vec();

    self.rd.free_rid(uniform_set_rid);
    self.rd.free_rid(input_buffer_rid);
    self.rd.free_rid(output_buffer_rid);
    self.rd.free_rid(parcel_buffer_rid);

    if result.len() < output_byte_count as usize {
        return Err(format!(
            "short read: expected {} bytes, got {}",
            output_byte_count,
            result.len()
        ));
    }

    let mut values = Vec::with_capacity(output_floats);
    for i in 0..output_floats {
        let offset = i * std::mem::size_of::<f32>();
        let bytes: [u8; 4] = result[offset..

fn create_rendering_device(context_name: &str) -> Option<Gd<RenderingDevice>> {
    let device = RenderingServer::singleton().create_local_rendering_device();
    if device.is_none() {
        godot_warn!("{context_name}: failed to create local RenderingDevice; skipping tests.");
    }
    device
}

fn compile_compute_pipeline(
    rd: &mut Gd<RenderingDevice>,
    shader_path: &str,
    context_name: &str,
) -> Option<(Rid, Rid)> {
    let shader_file: Gd<RdShaderFile> = load(shader_path);
    let spirv = shader_file.get_spirv();
    if spirv.is_none() {
        godot_warn!("{context_name}: failed to load shader SPIR-V from '{shader_path}'.");
        return None;
    }

    let shader_rid = rd.shader_create_from_spirv(&spirv.unwrap());
    if shader_rid == Rid::Invalid {
        godot_warn!("{context_name}: failed to create shader '{shader_path}'.");
        return None;
    }

    let pipeline_rid = rd.compute_pipeline_create(shader_rid);
    if pipeline_rid == Rid::Invalid {
        godot_warn!("{context_name}: failed to create compute pipeline for '{shader_path}'.");
        rd.free_rid(shader_rid);
        None
    } else {
        Some((shader_rid, pipeline_rid))
    }
}

