	collision.transform = shape_transform
	collision.debug_color = Color.YELLOW * Color(1, 1, 1, 0.1)

	var body := RigidBody2D.new()
	body.add_child(collision)

	if pickable:
		var script := load("res://utils/rigidbody_pick.gd")
