	if input_event is InputEventMouseButton and input_event.button_index == MOUSE_BUTTON_LEFT and input_event.pressed:
		# Get closest point on navmesh for the current mouse cursor position.
		var mouse_cursor_position: Vector2 = input_event.position
		var camera_ray_length := 1000.0
		var camera_ray_start := _camera.project_ray_origin(mouse_cursor_position)
		var camera_ray_end := camera_ray_start + _camera.project_ray_normal(mouse_cursor_position) * camera_ray_length

		var closest_point_on_navmesh := NavigationServer3D.map_get_closest_point_to_segment(
				get_world_3d().navigation_map,
				camera_ray_start,
				camera_ray_end
			)
		_robot.set_target_position(closest_point_on_navmesh)

	elif input_event is InputEventMouseMotion:
		if input_event.button_mask & (MOUSE_BUTTON_MASK_MIDDLE + MOUSE_BUTTON_MASK_RIGHT):
			_cam_rotation -= input_event.screen_relative.x * 0.005
			$CameraBase.set_rotation(Vector3.UP * _cam_rotation)

func _process(_delta: float) -> void:
	var mouse_cursor_position: Vector2 = get_viewport().get_mouse_position()

	var map: RID = get_world_3d().navigation_map
	# Do not query when the map has never synchronized and is empty.
	if NavigationServer3D.map_get_iteration_id(map) == 0:
		return

	var camera: Camera3D = get_viewport().get_camera_3d()
	var camera_ray_length: float = 1000.0
	var camera_ray_start: Vector3 = camera.project_ray_origin(mouse_cursor_position)
	var camera_ray_end: Vector3 = camera_ray_start + camera.project_ray_normal(mouse_cursor_position) * camera_ray_length
	var closest_point_on_navmesh: Vector3 = NavigationServer3D.map_get_closest_point_to_segment(
			map,
			camera_ray_start,
			camera_ray_end
		)

	if Input.is_mouse_button_pressed(MOUSE_BUTTON_LEFT):
		path_start_position = closest_point_on_navmesh

	%DebugPaths.global_position = path_start_position

	%PathDebugCorridorFunnel.target_position = closest_point_on_navmesh
	%PathDebugEdgeCentered.target_position = closest_point_on_navmesh
	%PathDebugNoPostProcessing.target_position = closest_point_on_navmesh

	%PathDebugCorridorFunnel.get_next_path_position()
	%PathDebugEdgeCentered.get_next_path_position()
	%PathDebugNoPostProcessing.get_next_path_position()

