func _process(_delta: float) -> void:
	if _is_on_floor:
		$CollisionShape.debug_color = Color.WHITE
	else:
		$CollisionShape.debug_color = Color.RED

func _integrate_forces(state: PhysicsDirectBodyState3D) -> void:
	var delta: float = state.step
	var velocity := (_forward * _dir * _walk_spd * delta) + (state.linear_velocity * Vector3.UP)
	state.linear_velocity = state.linear_velocity.move_toward(velocity, _acceleration * delta)

	if state.transform.origin.z < -_distance:
		_dir = -1.0
	if state.transform.origin.z > _distance:
		_dir = 1.0

	ground_check(delta)

func ground_check(delta: float) -> void:
	var space_state: PhysicsDirectSpaceState3D = get_world_3d().direct_space_state
	var shape := PhysicsShapeQueryParameters3D.new()
	shape.transform = _collision_shape.global_transform
	shape.transform.origin += get_gravity() * delta
	shape.shape_rid = _collision_shape.shape.get_rid()
	shape.collision_mask = 2
	var result := space_state.get_rest_info(shape)
	if result:
		_is_on_floor = true
	else:
		_is_on_floor = false

func _input(any_input_event: InputEvent) -> void:
	if any_input_event is InputEventMouseButton:
		if not any_input_event.pressed and any_input_event.button_index == MOUSE_BUTTON_LEFT:
			_picked = false

	if any_input_event is InputEventMouseMotion:
		_mouse_pos = any_input_event.position

func _input_event(_camera: Camera3D, any_input_event: InputEvent, _position: Vector3, _normal: Vector3, _shape_idx: int) -> void:
	if any_input_event is InputEventMouseButton:
		if any_input_event.pressed and any_input_event.button_index == MOUSE_BUTTON_LEFT:
			_picked = true
			_mouse_pos = any_input_event.position
			_last_mouse_pos = _mouse_pos

func _physics_process(delta: float) -> void:
	if _picked:
		var mouse_delta := _mouse_pos - _last_mouse_pos

		var world_delta := Vector3.ZERO
		world_delta.x = mouse_delta.x * MOUSE_DELTA_COEFFICIENT
		world_delta.y = -mouse_delta.y * MOUSE_DELTA_COEFFICIENT

		var camera := get_viewport().get_camera_3d()
		if camera:
			var camera_basis := camera.global_transform.basis
			world_delta = camera_basis * world_delta

			var camera_dist := camera.global_transform.origin.distance_to(global_transform.origin)
			const DEFAULT_CAMERA_FOV = 75.0
			var fov_coefficient := camera.fov / DEFAULT_CAMERA_FOV
			world_delta *= CAMERA_DISTANCE_COEFFICIENT * camera_dist * fov_coefficient

		if freeze:
			global_transform.origin += world_delta
		else:
			linear_velocity = world_delta / delta
		_last_mouse_pos = _mouse_pos

func _integrate_forces(state: PhysicsDirectBodyState3D) -> void:
	var delta := state.get_step()
	var lin_velocity := state.get_linear_velocity()

 	# Apply gravity.
	lin_velocity += get_gravity() * delta
	var up := -get_gravity().normalized()

	if dying:
		state.set_linear_velocity(lin_velocity)
		return

	for i in state.get_contact_count():
		var contact_collider := state.get_contact_collider_object(i)
		var contact_normal := state.get_contact_local_normal(i)

		if is_instance_valid(contact_collider):
			if contact_collider is Bullet and contact_collider.enabled:
				dying = true
				axis_lock_angular_x = false
				axis_lock_angular_y = false
				axis_lock_angular_z = false
				collision_layer = 0
				state.set_angular_velocity(-contact_normal.cross(up).normalized() * 33.0)
				_animation_player.play(&"impact")
				_animation_player.queue(&"extra/explode")
				contact_collider.enabled = false
				$SoundWalkLoop.stop()
				$SoundHit.play()
				return

	var advance: bool = _ray_floor.is_colliding() and not _ray_wall.is_colliding()

	var dir: Vector3 = ($Enemy/Skeleton as Node3D).get_transform().basis.z.normalized()
	var deaccel_dir: Vector3 = dir

	if advance:
		if dir.dot(lin_velocity) < MAX_SPEED:
			lin_velocity += dir * ACCEL * delta
		deaccel_dir = dir.cross(get_gravity()).normalized()
	else:
		if prev_advance:
			rot_dir = 1

		dir = Basis(up, rot_dir * ROT_SPEED * (delta)) * dir
		$Enemy/Skeleton.set_transform(Transform3D().looking_at(-dir, up))

	var dspeed: float = deaccel_dir.dot(lin_velocity)
	dspeed -= DEACCEL * delta
	if dspeed < 0:
		dspeed = 0

	lin_velocity = lin_velocity - deaccel_dir * deaccel_dir.dot(lin_velocity) \
			+ deaccel_dir * dspeed

	state.set_linear_velocity(lin_velocity)
	prev_advance = advance

func _ready() -> void:
	# Find collision exceptions for ray.
	# This is done to prevent the player and enemies from colliding
	# with the camera.
	var node: Node = self
	while is_instance_valid(node):
		if node is RigidBody3D or node is CharacterBody3D:
			collision_exception.append(node.get_rid())
			break
		else:
			node = node.get_parent()

	# This detaches the camera transform from the parent spatial node.
	set_as_top_level(true)

func adjust_facing(facing: Vector3, target: Vector3, step: float, adjust_rate: float, \
		current_gn: Vector3) -> Vector3:
	var normal := target
	var t := normal.cross(current_gn).normalized()

	var x := normal.dot(facing)
	var y := t.dot(facing)

	var ang := atan2(y,x)

	if absf(ang) < 0.001:
		return facing

	var s := signf(ang)
	ang = ang * s
	var turn := ang * adjust_rate * step
	var a: float
	if ang < turn:
		a = ang
	else:
		a = turn
	ang = (ang - a) * s

	return (normal * cos(ang) + t * sin(ang)) * facing.length()

