func _vertical_movement(delta: float) -> void:
	if Input.is_action_just_pressed(&"jump"):
		vertical_speed = 60

	vertical_speed -= delta * 240 # Gravity
	var k := move_and_collide(Vector3.UP * vertical_speed * delta)

	if k != null:
